/// The single lowering-time `this`-register resolver shared by the bare
/// `::name`/member-ref site and the bare-extension-call sites. A bound
/// local `this` always wins; otherwise `this` is recovered from an outer
/// capture when it is a known outer name — and, when `in_lambda_body` is
/// set, also for any lambda body (whose implicit `this` arrives via the
/// closure's own capture slot even without a `knowsOuter` record). When
/// `bind_local` is set the recovered capture register is bound as the
/// frame's `this` so later references reuse it. Returns `null` at top
/// level / in a non-receiver context.
fn resolveThisRegKind(b: *FuncBuilder, in_lambda_body: bool, bind_local: bool) Allocator.Error!?Reg {
    if (b.resolve("this")) |r| return r;
    if (b.knowsOuter("this") or (in_lambda_body and b.capturesThisSlot())) {
        const dst = try b.loadCaptureHoisted("this");
        if (bind_local) try b.bind("this", dst);
        if (runtime.envOnce("KLIO_THIS_TRACE") != null) {
            std.debug.print("[this-recover] bind={} reg={d} depth={d} in={s}\n", .{ bind_local, dst.int(), b.scopeDepth(), build.currentRealFn() orelse "-" });
        }
        return dst;
    }
    return null;
}

/// The register holding the current implicit receiver (`this`), if one is
/// in scope: either bound directly (a method / extension / receiver lambda
/// body) or reachable as an outer capture. Returns `null` at top level / in
/// a non-receiver context. Used to bind a bare `::name` member reference to
/// its receiver at creation time.
fn resolveThisReg(b: *FuncBuilder) Allocator.Error!?Reg {
    return resolveThisRegKind(b, false, false);
}

/// Resolve the instance selected by `super`. A lambda nested in a class
/// member keeps the member's lexical receiver in its closure capture slot,
/// even though the lambda frame has no locally bound `this` parameter.
fn resolveSuperThisReg(b: *FuncBuilder) Allocator.Error!?Reg {
    return resolveThisRegKind(b, true, false);
}

/// Lower an expression that appears as the *receiver / qualifier head* of a
/// member access or call. A bare single-segment class/interface name here
/// is a *qualifier* — it stays the class value so nested-class
/// (`Outer.Inner`) and companion-member forwarding work — unlike the same
/// Path in value position, which resolves to the companion object.
/// Everything else defers to `lowerExpr`.
pub fn lowerReceiver(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    // A receiver is a NESTED expression: the enclosing call's per-arg
    // typing stash must never reach the receiver's own lambdas —
    // `ByteArray(2) { it.toByte() }.scan("") { op }` typed the factory's
    // `it` from scan's operation through exactly this leak. Shield the
    // stash for the whole receiver lowering.
    const sh_bm = b.pending_arg_broad_masks;
    const sh_fg = b.pending_arg_fn_generic;
    const sh_lp = b.pending_arg_lambda_param_types;
    // The `-> Unit` coercion mask belongs to the enclosing call's args too:
    // a receiver splicing a `-> Unit` operator (map -> unsafeTransform) must
    // not tag the outer call's lambda (`X.map { }.firstOrNull { }`).
    const sh_lu = b.pending_arg_lambda_unit;
    b.pending_arg_broad_masks = null;
    b.pending_arg_fn_generic = null;
    b.pending_arg_lambda_param_types = null;
    b.pending_arg_lambda_unit = null;
    defer {
        b.pending_arg_broad_masks = sh_bm;
        b.pending_arg_fn_generic = sh_fg;
        b.pending_arg_lambda_param_types = sh_lp;
        if (b.pending_arg_lambda_unit) |m| b.allocator.free(m);
        b.pending_arg_lambda_unit = sh_lu;
    }
    if (expr.* == .Path and expr.Path.segments.len == 1) {
        const segments = expr.Path.segments;
        const n = segments[0].name;
        // Skip the class-name shortcut when the scope renames this name to
        // a (mangled) nested class/object or a file-private type: a bare
        // `Inner` inside `Outer` must reach `Outer$Inner` even though a
        // same-named top-level class owns the bare `class_id`. Falling
        // through to `lowerExpr` applies the rewrite in the `Path` arm.
        const aliased = scopeTypeRename(b, n, segments[0].span.file.int()) != null;
        // A class whose bare simple name is unregistered because it
        // collision-mangled (two `internal` classes named `TrieNode` in
        // different packages) is still pinned by the file's named import:
        // resolve `import …immutableMap.TrieNode` through its FQN. Without
        // this the receiver of `TrieNode.EMPTY` in an importing file falls to
        // a member access on the implicit receiver (`get_field TrieNode on
        // Companion`).
        var imported_fqn: ?[]const u8 = null;
        const imported_cid: ?ir.ClassId = if (!aliased and b.module.classId(n) == null) blk: {
            for (b.module.importAliasPathsIn(segments[0].span.file, n)) |p| {
                if (b.module.classIdByFqn(p.fqn)) |cid| {
                    imported_fqn = p.fqn;
                    break :blk cid;
                }
            }
            break :blk null;
        } else null;
        if (!aliased and b.resolve(n) == null and !b.knowsOuter(n) and
            (b.module.classId(n) != null or imported_cid != null) and !enclosingMemberShadowsClass(b, n))
        {
            const dst = b.allocReg();
            // A collision-mangled import has no name-published singleton under
            // its bare simple name; key the load on the FQN so the name-keyed
            // fallback (used when the singleton is not yet published) drives
            // the object/companion init by its fully-qualified name instead of
            // missing on the bare simple name.
            const nm = try b.module.internConst(b.allocator, .{ .String = imported_fqn orelse n });
            // The index-resolved class rides as the exact identity so a
            // same-simple-name class/object from an invisible package
            // cannot swap in at runtime (a nested `State` inside the
            // caller's class must not resolve to another package's
            // file-private `object State`). A same-named top-level
            // property keeps the name-keyed read — the property wins in
            // value position — but only when it is at least as visible
            // as the class at this site: a materialised stdlib property
            // from an unimported package (`kotlin.math.E` at the shipped
            // tier) must not outrank a user classifier named `E`.
            const cls_pick: ?ir.ClassId = blk: {
                if (imported_cid) |cid| break :blk cid;
                if (isTopLevelProp(n)) {
                    const pt = b.module.topLevelPropRefTier(n, b.self_package, segments[0].span.file) orelse 255;
                    const ct = b.module.classRefTier(n, b.self_package, segments[0].span.file) orelse 255;
                    if (pt <= ct) break :blk b.module.classIdExactImport(n, segments[0].span.file);
                }
                break :blk b.module.classIdIndexed(n, b.self_package, segments[0].span.file);
            };
            // A collision-mangled import target has no name-published singleton
            // to fall back on (`TrieNode` is registered only under its mangled
            // simple name), so load the class value by id directly — the
            // subsequent `.EMPTY` reads its companion off that value.
            try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm, .class = cls_pick, .ctor_ref = imported_cid != null } });
            return dst;
        }
    }
    // A receiver is not in the call's tail position; drop the
    // expected-type hint so it does not reach a reified inline call here.
    const prev_expected = b.pushExpected(null);
    const r = try lowerExpr(b, expr);
    b.restoreExpected(prev_expected);
    return r;
}

/// Among same-name overload candidates, prefer the one whose parameter type
/// at an explicitly-cast argument position (`x as T`) matches the cast
/// target `T`. Returns `null` when no cast argument disambiguates an
/// arity-matching candidate, so the caller falls back to its arity-first
/// pick.
pub fn overloadPickByCast(
    b: *FuncBuilder,
    cands: []const FuncId,
    args: []const Expr,
    want: usize,
) Allocator.Error!?FuncId {
    // Collect (arg index, cast simple-name) pairs.
    var casts: std.ArrayList(struct { i: usize, name: []const u8 }) = .empty;
    defer casts.deinit(b.allocator);
    for (args, 0..) |a, i| {
        if (a == .As) {
            const full = a.As.ty.name.name;
            const simple = rsplitLast(full, '.');
            try casts.append(b.allocator, .{ .i = i, .name = simple });
        }
    }
    if (casts.items.len == 0) return null;

    var best: ?FuncId = null;
    var best_score: i32 = 0;
    for (cands) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (!f.hasBody() or (f.params.len != 0 and f.params[f.params.len - 1].is_vararg)) continue;
        const base: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        if (f.params.len -| base != want) continue;
        var score: i32 = 0;
        for (casts.items) |c| {
            if (base + c.i < f.params.len) {
                const p = f.params[base + c.i];
                const pn = rsplitLast(p.ty.name, '.');
                if (std.mem.eql(u8, pn, c.name)) score += 2;
            }
        }
        if (score > 0 and (best == null or score > best_score)) {
            best = fid;
            best_score = score;
        }
    }
    return best;
}

/// Candidates that agree on a trailing lambda parameter's PARAMETER types
/// but differ only in its declared RETURN (`sumOf`'s `(T) -> Int / Long /
/// UInt / ULong / Double` variants) discriminate by the literal's derived
/// return under the agreed binding, exactly as kotlinc infers. The
/// derivation feeds only this pick among a FIXED set — it never
/// instantiates a type variable, which is the hazard the member-tail
/// enrichment refutation recorded. No unique match leaves the tie.
/// Whether a declared receiver head can serve a value whose static head is
/// `actual` — the head itself, a builtin supertype, or a declared supertype
/// by simple name.
pub fn receiverHeadServes(b: *const FuncBuilder, actual: []const u8, declared: []const u8) bool {
    if (std.mem.eql(u8, actual, declared)) return true;
    for (applicability.builtinSupersOf(actual)) |sup| {
        if (std.mem.eql(u8, applicability.simpleName(sup), declared)) return true;
    }
    if (b.module.registry.class_super_names.get(actual)) |chain| {
        for (chain) |sup| {
            if (std.mem.eql(u8, applicability.simpleName(sup), declared)) return true;
        }
    }
    return false;
}

/// Deriver-only leniency: a TYPE record can pick among bodyless expect
/// headers whose signatures discriminate; an emission pick never can.
pub threadlocal var lamret_allow_bodyless: bool = false;

pub fn overloadPickByLambdaReturn(
    b: *FuncBuilder,
    cands: []const FuncId,
    args: []const Expr,
    want: usize,
) Allocator.Error!?FuncId {
    return overloadPickByLambdaReturnRecv(b, cands, args, want, null);
}

fn overloadPickByLambdaReturnRecv(
    b: *FuncBuilder,
    cands: []const FuncId,
    args: []const Expr,
    want: usize,
    explicit_recv_head: ?[]const u8,
) Allocator.Error!?FuncId {
    return overloadPickByLambdaReturnFull(b, cands, args, want, explicit_recv_head, null);
}

pub fn overloadPickByLambdaReturnFull(
    b: *FuncBuilder,
    cands: []const FuncId,
    args: []const Expr,
    want: usize,
    explicit_recv_head: ?[]const u8,
    recv_expr: ?*const Expr,
) Allocator.Error!?FuncId {
    if (args.len == 0) return null;
    const li = args.len - 1;
    if (args[li] != .Lambda) return null;
    const lam = args[li].Lambda;
    const stmts = lam.body.stmts;
    if (stmts.len == 0 or stmts[stmts.len - 1] != .Expr) return null;
    const Entry = struct { fid: FuncId, ret: []const u8, params: []const ir.TypeRef, exact_recv: bool };
    var family: std.ArrayList(Entry) = .empty;
    defer family.deinit(b.allocator);
    // The implicit receiver's head filters extension candidates before the
    // agreement check — the CharSequence variants' `(Char) -> R` params must
    // not disagree a UByteArray family into a bail.
    const actual_recv_head: ?[]const u8 = blk: {
        if (explicit_recv_head) |h| break :blk h;
        const h = b.recvTy() orelse b.spliceRecvTy() orelse b.enclosingRecvTy() orelse break :blk null;
        break :blk typeHead(std.mem.trimEnd(u8, h, "?"));
    };
    const lamret_why = runtime.envOnce("KLIO_LAMRET_WHY");
    for (cands) |fid| {
        const f = b.module.funcById(fid) orelse {
            if (lamret_why != null) std.debug.print("[lamret-why] #{d} skip=null_func\n", .{fid.int()});
            continue;
        };
        const why = lamret_why != null and std.mem.indexOf(u8, f.fqn, lamret_why.?) != null;
        if (!f.hasBody() and !lamret_allow_bodyless) {
            if (why) std.debug.print("[lamret-why] {s}#{d} skip=no_body\n", .{ f.fqn, fid.int() });
            continue;
        }
        const base: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        if (f.params.len -| base != want) {
            if (why) std.debug.print("[lamret-why] {s}#{d} skip=arity params={d} want={d}\n", .{ f.fqn, fid.int(), f.params.len, want });
            continue;
        }
        var exact_recv = false;
        if (base == 1) {
            const ah = actual_recv_head orelse {
                if (why) std.debug.print("[lamret-why] {s}#{d} skip=no_recv_head\n", .{ f.fqn, fid.int() });
                continue;
            };
            var dr = std.mem.trimEnd(u8, f.params[0].ty.name, "?");
            if (std.mem.indexOfScalar(u8, dr, '<')) |lt| dr = dr[0..lt];
            const dh = typeHead(dr);
            exact_recv = std.mem.eql(u8, ah, dh);
            if (!(exact_recv or dh.len <= 2 or ir.parseClassTypeParamIdentity(f.params[0].ty.name) != null or
                receiverHeadServes(b, ah, dh)))
            {
                if (why) std.debug.print("[lamret-why] {s}#{d} skip=recv ah={s} dh={s}\n", .{ f.fqn, fid.int(), ah, dh });
                continue;
            }
        }
        const pty = f.params[f.params.len - 1].ty;
        if (!std.mem.startsWith(u8, typeHead(pty.name), "Function") or pty.args.len < 1) {
            if (why) std.debug.print("[lamret-why] {s}#{d} skip=fn_ty pty={s} args={d}\n", .{ f.fqn, fid.int(), pty.name, pty.args.len });
            continue;
        }
        const params = pty.args[0 .. pty.args.len - 1];
        const ret_head = typeHead(std.mem.trimEnd(u8, pty.args[pty.args.len - 1].name, "?"));
        if (ret_head.len == 0) continue;
        try family.append(b.allocator, .{ .fid = fid, .ret = ret_head, .params = params, .exact_recv = exact_recv });
    }
    const lamret_trace = runtime.envOnce("KLIO_LAMRET_TRACE") != null;
    // Receiver specificity narrows before the return pick, exactly as
    // kotlinc ranks: an exact-receiver family (`UByteArray.sumOf`) beats
    // supertype-receiver applicables (`Iterable<T>.sumOf` through
    // `UByteArray : Collection<UByte>`), whose different param spelling
    // must not disagree the pick into a bail.
    var any_exact = false;
    for (family.items) |e| any_exact = any_exact or e.exact_recv;
    if (any_exact) {
        var w: usize = 0;
        for (family.items) |e| {
            if (e.exact_recv) {
                family.items[w] = e;
                w += 1;
            }
        }
        family.items.len = w;
    }
    // The surviving set must agree on the lambda-slot's parameter types;
    // return variety is what the pick discriminates.
    var agreed_params: ?[]const ir.TypeRef = null;
    var distinct_returns: usize = 0;
    for (family.items) |e| {
        if (agreed_params) |prev| {
            if (prev.len != e.params.len) return null;
            for (prev, e.params) |pa, pb2| {
                if (!std.mem.eql(u8, pa.name, pb2.name)) return null;
            }
        } else {
            agreed_params = e.params;
        }
    }
    for (family.items, 0..) |e, ei| {
        var seen = false;
        for (family.items[0..ei]) |prior| {
            if (std.mem.eql(u8, prior.ret, e.ret)) {
                seen = true;
                break;
            }
        }
        if (!seen) distinct_returns += 1;
    }
    if (family.items.len < 2 or distinct_returns < 2) {
        if (lamret_trace and family.items.len != 0) {
            std.debug.print("[lamret-bail] family={d} distinct={d} first={s}\n", .{
                family.items.len,
                distinct_returns,
                if (b.module.funcById(family.items[0].fid)) |f| f.fqn else "?",
            });
        }
        return null;
    }
    const fparams = agreed_params orelse return null;
    // Bind the lambda's value parameters from the agreed declared types; a
    // sole bare-type-parameter param is the receiver's ELEMENT (the
    // collection-selector family this pick exists for).
    var nb = try FuncBuilder.init(b.allocator, b.module);
    nb.census_quiet = true;
    defer nb.deinit();
    // The lambda body's calls resolve in the CALLER's lexical class scope:
    // `it.toLong()` inside `expected.map { it.toLong() }` binds the
    // enclosing class's private member-extension.
    if (b.ownerClass()) |oc0| nb.setOwnerClass(oc0);
    var elem_owned: ?ir.TypeRef = null;
    defer if (elem_owned) |*t| t.deinit(b.allocator);
    var i: usize = 0;
    while (i < fparams.len) : (i += 1) {
        const pname = if (lam.params.len == 0 and fparams.len == 1)
            "it"
        else if (i < lam.params.len)
            lam.params[i].name
        else
            return null;
        const declared = fparams[i];
        const dh = typeHead(std.mem.trimEnd(u8, declared.name, "?"));
        // A scalar head (the unsigned types among them) has no class row but
        // the deriver types its members from the declaration tables, so the
        // declared param type still binds.
        if (staticTypeClassId(b, declared) != null or isPrimitiveTypeName(dh)) {
            try nb.setLocalDeclTypeOwned(pname, try declared.clone(b.allocator));
        } else if (dh.len <= 2 or ir.parseClassTypeParamIdentity(declared.name) != null) {
            if (fparams.len != 1) return null;
            if (elem_owned == null) {
                if (recv_expr) |re| {
                    elem_owned = try iterableElementTypeRef(b, re);
                } else {
                    const this_expr: Expr = .{ .This = .{ .qualifier = null, .span = args[li].span() } };
                    elem_owned = try iterableElementTypeRef(b, &this_expr);
                }
                if (lamret_trace) {
                    std.debug.print("[lamret-elem] recv_expr={} recvTy={s} elem={s}\n", .{
                        recv_expr != null,
                        b.recvTy() orelse "-",
                        if (elem_owned) |e2| e2.name else "<null>",
                    });
                }
            }
            const elem = elem_owned orelse return null;
            try nb.setLocalDeclTypeOwned(pname, try elem.clone(b.allocator));
        } else {
            return null;
        }
    }
    od_depth += 1;
    const derived = staticExprTypeRef(&nb, &stmts[stmts.len - 1].Expr) catch null;
    od_depth -= 1;
    if (lamret_trace and derived == null) {
        std.debug.print("[lamret-bail] derive=null family={d} first={s}\n", .{
            family.items.len,
            if (b.module.funcById(family.items[0].fid)) |f| f.fqn else "?",
        });
    }
    var derived_ty = derived orelse return null;
    defer derived_ty.deinit(b.allocator);
    const derived_head = typeHead(std.mem.trimEnd(u8, derived_ty.name, "?"));
    var pick: ?FuncId = null;
    for (family.items) |e| {
        if (std.mem.eql(u8, e.ret, derived_head)) {
            if (pick != null) return null;
            pick = e.fid;
        }
    }
    if (runtime.envOnce("KLIO_LAMRET_TRACE") != null and pick != null) {
        const pf = b.module.funcById(pick.?);
        std.debug.print("[lamret-pick] derived={s} -> {s}\n", .{ derived_head, if (pf) |f2| f2.fqn else "?" });
    }
    return pick;
}

/// Lower one expression into the current block, returning the register
/// holding its value. Value-less forms (assignments, declarations) return a
/// synthetic `Unit` register so downstream code stays uniform.
pub fn lowerExpr(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    // Arm the implicit-label for a call's argument lambdas with the
    // callee's simple name (`with(n) { … }` → "with"). `lowerArgRun`
    // consumes and re-arms it per argument; `Lambda` reads it.
    if (expr.* == .Call) {
        b.pending_lambda_label = calleeLabel(expr.Call.callee);
    }
    switch (expr.*) {
        .IntLit => |lit| {
            // Honour the literal's declared kind (`1L`, `1U`, `1uL`)
            // rather than letting the value range pick.
            return switch (lit.kind) {
                .Long => b.emitConst(.{ .Long = lit.value }),
                .UInt => b.emitConst(.{ .UInt = @intCast(lit.value) }),
                .ULong => b.emitConst(.{ .ULong = @bitCast(lit.value) }),
                .Int => blk: {
                    if (lit.value >= std.math.minInt(i32) and lit.value <= std.math.maxInt(i32)) {
                        break :blk b.emitConst(.{ .Int = @intCast(lit.value) });
                    } else {
                        break :blk b.emitConst(.{ .Long = lit.value });
                    }
                },
            };
        },
        .FloatLit => |lit| return switch (lit.kind) {
            .Float => b.emitConst(.{ .Float = @floatCast(lit.value) }),
            .Double => b.emitConst(.{ .Double = lit.value }),
        },
        .BoolLit => |lit| return b.emitConst(.{ .Bool = lit.value }),
        .NullLit => return b.emitConst(.Null),
        .CharLit => |lit| return b.emitConst(.{ .Char = lit.value }),

        .Binary => |bin| return lowerBinary(b, bin),

        .Unary => |u| {
            // `-2147483648` parses as Neg(IntLit(2147483648)); the operand's
            // value doesn't fit in i32 so general IntLit-lowering would widen
            // to Long. Special-case Int.MIN_VALUE so it stays Int.
            if (u.op == .Neg and u.expr.* == .IntLit) {
                const il = u.expr.IntLit;
                if (il.kind == .Int and il.value == @as(i64, std.math.maxInt(i32)) + 1) {
                    return b.emitConst(.{ .Int = std.math.minInt(i32) });
                }
            }
            // Prefix ++ / -- need both an Inc/Dec UnOp AND a write-back to
            // the lvalue; return the NEW value.
            if (u.op == .PreInc or u.op == .PreDec) {
                const operand = try lowerExpr(b, u.expr);
                const dst = b.allocReg();
                const uo: UnOp = if (u.op == .PreInc) .Inc else .Dec;
                try b.push(.{ .UnOp = .{ .dst = dst, .op = uo, .operand = operand } });
                try writeBackLvalue(b, u.expr, dst);
                return dst;
            }
            const operand = try lowerExpr(b, u.expr);
            const dst = b.allocReg();
            switch (u.op) {
                .Not => try b.push(.{ .Not = .{ .dst = dst, .src = operand } }),
                .Neg => try b.push(.{ .UnOp = .{ .dst = dst, .op = .Neg, .operand = operand } }),
                .Pos => try b.push(.{ .UnOp = .{ .dst = dst, .op = .Plus, .operand = operand } }),
                .PreInc, .PreDec => unreachable,
            }
            return dst;
        },
        .If => |f| {
            // A single destination register both arms write into via Move
            // before jumping to the join.
            const cond_r = try lowerExpr(b, f.cond);
            const t_block = try b.allocBlock();
            const f_block = try b.allocBlock();
            const join = try b.allocBlock();
            const dst = b.allocReg();
            b.terminate(.{ .Branch = .{ .cond = cond_r, .t = t_block, .f = f_block } });
            // Then arm. An `if (x is T)` guard smart-casts `x` to `T` for the
            // arm, and extension resolution is static — see `narrowIsCheck`.
            b.switchTo(t_block);
            var narrowed: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer narrowed.deinit(b.allocator);
            try narrowIsCheckAll(b, f.cond, &narrowed);
            var not_null: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer not_null.deinit(b.allocator);
            try narrowNullCheckAll(b, f.cond, true, &not_null);
            const t_val = try lowerExpr(b, f.then_branch);
            var nn = not_null.items.len;
            while (nn > 0) : (nn -= 1) b.restoreLocal(not_null.items[nn - 1]);
            var ni = narrowed.items.len;
            while (ni > 0) : (ni -= 1) b.restoreLocal(narrowed.items[ni - 1]);
            try b.push(.{ .Move = .{ .dst = dst, .src = t_val } });
            b.terminate(.{ .Goto = join });
            // Else arm.
            b.switchTo(f_block);
            var else_not_null: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer else_not_null.deinit(b.allocator);
            try narrowNullCheckAll(b, f.cond, false, &else_not_null);
            const f_val = if (f.else_branch) |e| try lowerExpr(b, e) else try b.emitConst(.Unit);
            var en = else_not_null.items.len;
            while (en > 0) : (en -= 1) b.restoreLocal(else_not_null.items[en - 1]);
            try b.push(.{ .Move = .{ .dst = dst, .src = f_val } });
            b.terminate(.{ .Goto = join });
            b.switchTo(join);
            return dst;
        },
        .Block => |block| return lowerBlock(b, &block),
        .Path => return lowerPath(b, expr),
        .StringTemplate => |st| return lowerStringTemplate(b, st.parts),
        .While => |w| {
            const header = try b.allocBlock();
            const body_blk = try b.allocBlock();
            const exit = try b.allocBlock();
            b.terminate(.{ .Goto = header });

            b.switchTo(header);
            const c = try lowerExpr(b, w.cond);
            b.terminate(.{ .Branch = .{ .cond = c, .t = body_blk, .f = exit } });

            b.switchTo(body_blk);
            try b.pushLoop(null, header, exit);
            var w_not_null: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer w_not_null.deinit(b.allocator);
            try narrowNullCheckAll(b, w.cond, true, &w_not_null);
            _ = try lowerExpr(b, w.body);
            var wn = w_not_null.items.len;
            while (wn > 0) : (wn -= 1) b.restoreLocal(w_not_null.items[wn - 1]);
            b.popLoop();
            b.terminate(.{ .Goto = header });

            b.switchTo(exit);
            return b.emitConst(.Unit);
        },
        .Member => return lowerMember(b, expr),
        .Index => |ix| {
            // `r[a, b, ...]` → r.get(a, b, ...). The `get` resolves against
            // the receiver's STATIC type, as kotlinc does: carry the declared
            // head so a runtime subtype's own generic `get<T>` cannot shadow
            // the statically-visible member. `map[local]` on a
            // `PersistentMap<CompositionLocal, ValueHolder>`-typed local must
            // bind the plain map `get` (returning the holder), never
            // `PersistentCompositionLocalHashMap.get<T>` (the composition-
            // local READ, which returns the resolved value). A head that is
            // not an ancestor of the runtime receiver disengages the static
            // scope, so an imprecise head degrades to the unhinted walk.
            const recv = try lowerReceiver(b, ix.receiver);
            const run = try lowerArgRun(b, ix.args);
            const dst = b.allocReg();
            const nm = try b.module.internConst(b.allocator, .{ .String = "get" });
            const static_recv: ?ConstId = blk: {
                const t = argDeclTypeRef(b, ix.receiver) orelse break :blk null;
                const head = std.mem.trimEnd(u8, t.name, "?");
                if (head.len == 0) break :blk null;
                break :blk try b.module.internConst(b.allocator, .{ .String = head });
            };
            try b.push(.{ .CallMember = .{
                .dst = dst,
                .receiver = recv,
                .name = nm,
                .args = run[0],
                .n_args = run[1],
                .arg_names = &.{},
                .static_recv = static_recv,
            } });
            return dst;
        },
        .Call => return lowerCall(b, expr),
        .DoWhile => |w| {
            const body_blk = try b.allocBlock();
            const exit = try b.allocBlock();
            b.terminate(.{ .Goto = body_blk });

            b.switchTo(body_blk);
            try b.pushLoop(null, body_blk, exit);
            // Kotlin scopes the do-body's declarations into the `while`
            // condition; when the body is a block, lower its statements and the
            // condition in one shared scope so `do { val x = … } while (x …)`
            // resolves `x` instead of treating it as a stray global.
            if (w.body) |body| {
                if (body.* == .Block) {
                    const block = &body.Block;
                    try b.pushScope();
                    try hoistMutualLocalFns(b, block);
                    for (block.stmts) |*stmt| _ = try lowerStmt(b, stmt);
                    b.popLoop();
                    const c = try lowerExpr(b, w.cond);
                    try b.popScope();
                    b.terminate(.{ .Branch = .{ .cond = c, .t = body_blk, .f = exit } });
                    b.switchTo(exit);
                    return b.emitConst(.Unit);
                }
                _ = try lowerExpr(b, body);
            }
            b.popLoop();
            const c = try lowerExpr(b, w.cond);
            b.terminate(.{ .Branch = .{ .cond = c, .t = body_blk, .f = exit } });

            b.switchTo(exit);
            return b.emitConst(.Unit);
        },
        .Return => return lowerReturn(b, expr),
        .Throw => |t| {
            const r = try lowerExpr(b, t.value);
            b.terminate(.{ .Throw = r });
            const dead = try b.allocBlock();
            b.switchTo(dead);
            return b.emitConst(.Unit);
        },
        .When => |w| {
            // `when (val v = subject) { ... }` binds `v` to the subject's
            // value so pattern arms can refer to it.
            if (w.subject != null and w.subject_binding != null) {
                try b.pushScope();
                const sv = try lowerExpr(b, w.subject.?);
                try b.bind(w.subject_binding.?.name.name, sv);
                // The subject is evaluated exactly once: the bound register
                // doubles as the when's subject (re-lowering would re-run a
                // side-effecting subject like a queue poll).
                const r = try when_expr.lowerWhenWithSubjectReg(b, w.subject, sv, w.branches, exprSpan(expr));
                try b.popScope();
                return r;
            }
            return lowerWhen(b, w.subject, w.branches, exprSpan(expr));
        },
        .Try => return lowerTry(b, expr),
        .Lambda => return lowerLambda(b, expr),
        .Break => |brk| {
            const lbl: ?[]const u8 = if (brk.label) |i| i.name else null;
            if (b.loopFor(lbl)) |frame| {
                const target = frame.break_target;
                try replayFinallysForJump(b, frame.finally_base);
                try emitTowerPopsForJump(b, frame.encl_tower_base);
                b.terminate(.{ .Goto = target });
                const dead = try b.allocBlock();
                b.switchTo(dead);
            } else {
                try b.push(.{ .Trace = .{ .span = exprSpan(expr) } });
            }
            return b.emitConst(.Unit);
        },
        .Continue => |cont| {
            const lbl: ?[]const u8 = if (cont.label) |i| i.name else null;
            if (b.loopFor(lbl)) |frame| {
                const target = frame.continue_target;
                try replayFinallysForJump(b, frame.finally_base);
                try emitTowerPopsForJump(b, frame.encl_tower_base);
                b.terminate(.{ .Goto = target });
                const dead = try b.allocBlock();
                b.switchTo(dead);
            } else {
                try b.push(.{ .Trace = .{ .span = exprSpan(expr) } });
            }
            return b.emitConst(.Unit);
        },
        .For => |f| return lowerFor(b, f.vars, f.iter, f.body),
        .IsCheck => |ck| {
            const s = try lowerExpr(b, ck.expr);
            const dst = b.allocReg();
            // An enclosing splice's reified parameter is substituted here,
            // NULLABILITY included. Leaving the parameter name for the
            // runtime to resolve through its bound class value loses the
            // `?`: `filterIsInstance<Int?>()` then dropped every null,
            // because a class value cannot carry nullability.
            var check_name = loweredCheckTypeName(b, &ck.ty);
            var check_nullable = ck.ty.nullable;
            if (ck.ty.type_args.len == 0) {
                if (b.resolveReifiedTypeName(ck.ty.name.name)) |bound| {
                    var head = bound;
                    if (std.mem.endsWith(u8, head, "?")) {
                        head = head[0 .. head.len - 1];
                        check_nullable = true;
                    }
                    // The bound name carries the FULL spelling
                    // (`BufferedChannel<*>`); an `is` check is on the head
                    // alone, exactly as the runtime's class-value fallback
                    // was.
                    if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
                    if (head.len != 0) check_name = head;
                }
            }
            try b.push(.{ .InstanceOf = .{
                .dst = dst,
                .src = s,
                .ty = .{ .name = check_name, .nullable = check_nullable, .args = &.{} },
            } });
            if (ck.negated) {
                const neg = b.allocReg();
                try b.push(.{ .Not = .{ .dst = neg, .src = dst } });
                return neg;
            }
            return dst;
        },
        .As => |cast| {
            const s = try lowerExpr(b, cast.expr);
            // A cast to a NON-reified type parameter (`x as T`) is erased: the
            // JVM `checkcast` targets the bound and passes any value (including
            // null), so it is a runtime no-op — a genuine mismatch surfaces
            // only when the value is later used as `T`. Return the value as-is,
            // so a type parameter named like a concrete class (`class
            // ScopeMap<Key, Scope>` alongside a test's `class Scope`) is not
            // checked against that class and a nullable instantiation does not
            // throw. Reified type params are excluded (the reified splice
            // substitutes the concrete type before this point).
            if (b.isTypeParam(cast.ty.name.name)) return s;
            const dst = b.allocReg();
            try b.push(.{ .Cast = .{
                .dst = dst,
                .src = s,
                .ty = .{ .name = loweredCheckTypeName(b, &cast.ty), .nullable = cast.ty.nullable, .args = &.{} },
                .safe = cast.safe,
            } });
            return dst;
        },
        .Postfix => return lowerPostfix(b, expr),
        .Labeled => return lowerLabeled(b, expr),
        .PropertyRef => |pr| {
            // `::enumEntries` against a declared `() -> Head<E>` function
            // type: the expected return solves the target's single reified
            // type parameter, and the plain fn VALUE cannot carry it —
            // lower the reference as a zero-arg closure over the stamped
            // call instead.
            if (try reifiedRefClosure(b, pr.name.name, pr.name.span)) |r| return r;
            // `::name` naming a file-private top-level function mangled per
            // file (two files in one package each declaring the same
            // `private fun`) references the calling file's mangled name.
            // Without the rewrite the bare name has no declaration at all
            // and the reference degrades to a member ref on the enclosing
            // `this` — kotlinx's `::createSegment` inside SemaphoreImpl.
            // Locals, outer captures and own members still shadow it, the
            // same scope order the bare CALL rewrite honors.
            if (build.filePrivateFuncRename(pr.name.name, pr.name.span.file.int())) |renamed| {
                if (b.resolve(pr.name.name) == null and !b.knowsOuter(pr.name.name) and
                    !b.hasOwnMember(pr.name.name))
                {
                    var rewritten = expr.*;
                    rewritten.PropertyRef.name = .{ .name = renamed, .span = pr.name.span };
                    return lowerExpr(b, &rewritten);
                }
            }
            // `::greet` — a registered top-level fn loads the function value;
            // a tracked local / top-level prop keeps the unbound PropertyRef;
            // an untracked own-receiver member binds a MemberRef. The symbol
            // index resolves the name from this file's package and imports,
            // and a unique pick is carried as an exact identity — a class
            // first (`::Ctor`; the runtime gives a class value precedence
            // over a same-named function), then a non-extension function —
            // so a same-simple-name declaration from another package cannot
            // swap in at runtime. Deferred shapes (overload sets, extension
            // forms) keep the name-keyed emission.
            const dst = b.allocReg();
            const nm = try b.module.internConst(b.allocator, .{ .String = pr.name.name });
            // `::localFn` names a local function, which is lowered to a closure
            // value bound to a register. The reference loads that closure — it
            // is the referenced callable, not an unbound property of whatever
            // the use site later applies it to.
            // A LOCAL EXTENSION fn's closure takes its receiver as the
            // leading parameter, but a bare `::ref` to it is
            // receiver-BOUND — kotlinc binds the enclosing implicit
            // receiver, so `handles.forEach(::validateGroupState)` inside
            // `table.edit { }` invokes with the edit receiver. Forward
            // through a synthesized lambda whose bare call re-resolves the
            // local ext against `this` (capture machinery included); the
            // reference then has the value-parameter arity the use site
            // expects. The mark set is inherited into nested lambda
            // builders, where the closure itself is an outer capture.
            if (runtime.envOnce("KLIO_REF_TRACE")) |w| {
                if (std.mem.eql(u8, w, pr.name.name)) std.debug.print("[ref-trace] {s} lef={} recvctx={} resolve={} outer={} arity_tys={} pending={d} expected_fn={}\n", .{ pr.name.name, b.isLocalExtFn(pr.name.name), inReceiverContext(b), b.resolve(pr.name.name) != null, b.knowsOuter(pr.name.name), b.localFnParamTys(pr.name.name) != null, b.pending_lambda_arity, if (b.peekExpected()) |e| e.function != null else false });
            }
            if (b.isLocalExtFn(pr.name.name) and inReceiverContext(b) and
                (b.resolve(pr.name.name) != null or b.knowsOuter(pr.name.name)))
            {
                if (try localExtRefClosure(b, pr.name.name, pr.name.span)) |r| return r;
            }
            if (b.isLocalFn(pr.name.name)) {
                if (b.resolve(pr.name.name)) |reg| {
                    try b.push(.{ .Move = .{ .dst = dst, .src = reg } });
                    return dst;
                }
            }
            // `::rec` referencing the ENCLOSING local fn from inside its own
            // body (or a lambda nested in it): the plain name is unbound here
            // — and a later same-named sibling would rebind it — so the
            // reference loads the fn's own closure through its mangled cell,
            // the same binding a bare self-call uses. Extension locals need a
            // bound receiver and keep the member/property forms below.
            if (b.selfLocalFn()) |slf| {
                if (std.mem.eql(u8, slf.name, pr.name.name) and !b.isLocalExtFn(slf.mangled)) {
                    const cell: ?Reg = if (b.resolve(slf.mangled)) |r|
                        r
                    else if (b.knowsOuter(slf.mangled))
                        try resolveCapture(b, slf.mangled)
                    else
                        null;
                    if (cell) |c| {
                        try b.push(.{ .CellGet = .{ .dst = dst, .cell = c } });
                        return dst;
                    }
                }
            }
            // The innermost implicit receiver declaring `name` as a member
            // outranks every top-level pick: kotlinc binds `::proceed`
            // inside `intercept { handler(context, ::proceed) }` to the
            // pipeline context, not a same-named global. Stdlib alias
            // intrinsics keep their global form (a receiver class does not
            // shadow `::minOf`-style refs it never declares).
            if (!ir.isAliasName(pr.name.name)) receiver_member: {
                const rh = b.recvTy() orelse break :receiver_member;
                const cid = (b.module.uniqueClassIdBySimpleName(rh) orelse
                    b.module.classIdByFqn(rh)) orelse break :receiver_member;
                if (!b.module.classHierarchyDeclaresMember(cid, pr.name.name))
                    break :receiver_member;
                if (try resolveThisRegKind(b, true, false)) |this_reg| {
                    try b.push(.{ .MemberRef = .{ .dst = dst, .receiver = this_reg, .name = nm } });
                    return dst;
                }
            }
            const is_tracked = b.resolve(pr.name.name) != null or isTopLevelProp(pr.name.name);
            // A same-named enclosing member only shadows the global for `::name`
            // when it could actually be the referenced callable: if the use
            // site expects a specific arity (a function-typed parameter slot)
            // and the member cannot accept it, the global wins — e.g.
            // `propagateOf2(::minOf, …)` from a `@Test fun minOf()` references
            // the stdlib `minOf`, not the zero-arg test method.
            const ref_arity = b.pending_lambda_arity;
            const member_shadows_ref = enclosingDeclaresMember(b, pr.name.name) and
                (ref_arity < 0 or b.ownMemberApplicable(pr.name.name, @intCast(ref_arity)));
            var class_pick: ?ir.ClassId = b.module.classIdIndexed(pr.name.name, b.self_package, pr.name.span.file);
            var ref_shapes = try callableRefArgShapes(b, ref_arity);
            defer if (ref_shapes) |*shapes| shapes.deinit(b.allocator);
            // A sealed/abstract class constructs nothing through a reference:
            // under a TYPED expected function type, the same-named function
            // overloads are the reference's target, picked by those types
            // (`val g: (String?) -> P = ::P` binds the `String?` overload,
            // which a runtime `null` could never tell from `Number?`).
            if (class_pick) |cid| typed: {
                if (cid.int() >= b.module.classes.items.len or !b.module.classes.items[cid.int()].is_abstract) break :typed;
                if (b.module.funcsBySimpleName(pr.name.name).len == 0) break :typed;
                const shapes = ref_shapes orelse break :typed;
                var typed_any = false;
                for (shapes.shapes) |sh| {
                    if (sh.ty != null) typed_any = true;
                }
                if (typed_any) class_pick = null;
            }
            const ref_pick: ?FuncId = if (class_pick != null)
                null
            else if (ref_shapes) |shapes|
                try b.module.resolveBareRefExpected(
                    b.allocator,
                    pr.name.name,
                    b.self_package,
                    pr.name.span.file,
                    shapes.shapes,
                )
            else
                b.module.resolveBareRefIndexed(pr.name.name, b.self_package, pr.name.span.file);
            refAudit(b, pr.name.name, ref_pick);
            // A callable reference whose only declaration is in an
            // unimported package is unresolved (kotlinc rejects `::name` /
            // `::Ctor` the same as a bare call to it). Record the
            // diagnostic before binding the lenient pick.
            if (class_pick) |cid| {
                _ = try recordOutOfScopeRef(b, pr.name.name, pr.name.span, classFqnOf(b, cid), b.module.classRefTier(pr.name.name, b.self_package, pr.name.span.file));
            } else if (ref_pick) |fid| {
                _ = try recordOutOfScopeRef(b, pr.name.name, pr.name.span, fqnOf(b, fid), b.module.bareRefTier(pr.name.name, b.self_package, pr.name.span.file));
            }
            // `::name` in a slot whose declared function type is written
            // entirely in the callee's type parameters
            // (`totalOrderMinOf2<Comparable<Any>>(::minOf)` against
            // `f2t: (T, T) -> T`) denotes the GENERIC overload: kotlinc
            // substitutes the call-site type argument, so only the generic
            // candidate is applicable. Bind the reference by id; a numeric
            // or otherwise-typed slot keeps the plain alias/global forms.
            if (class_pick == null and ref_pick == null and b.pending_ref_fn_generic and
                !member_shadows_ref and ref_arity >= 0)
            {
                if (try genericRefTarget(
                    b,
                    pr.name.name,
                    pr.name.span.file,
                    @intCast(ref_arity),
                )) |fid| {
                    const fqn_n = if (b.module.funcById(fid)) |f|
                        try b.module.internConst(b.allocator, .{ .String = f.fqn })
                    else
                        nm;
                    try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = fqn_n, .func = fid } });
                    return dst;
                }
            }
            if (class_pick != null and !member_shadows_ref) {
                try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm, .class = class_pick.?, .ctor_ref = true } });
            } else if (ref_pick != null and !member_shadows_ref) {
                const fid = ref_pick.?;
                const n = blk: {
                    if (b.module.funcById(fid)) |f| {
                        break :blk try b.module.internConst(b.allocator, .{ .String = f.fqn });
                    }
                    break :blk nm;
                };
                try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = n, .func = fid } });
            } else if ((b.module.funcId(pr.name.name) != null or b.module.classId(pr.name.name) != null) and !member_shadows_ref) {
                try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm } });
            } else if (ir.isAliasName(pr.name.name) and !member_shadows_ref) {
                // `::minOf` / `::maxOf` / `::listOf` … name a stdlib host
                // intrinsic. A bare `LoadGlobal` resolves it to its
                // `.Intrinsic` callable value; binding it to the enclosing
                // `this` (the `!is_tracked` branch below) would emit a
                // `this.<name>` member ref that misses at runtime. The member
                // test is scoped to the ENCLOSING class's hierarchy — a
                // program-wide member-name set is poisoned by an unrelated
                // sibling class that happens to declare a `minOf`/`maxOf`
                // `@Test`, which `::minOf` here can never refer to.
                try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm } });
            } else if (!is_tracked) {
                // Lambda-aware: a receiver lambda's `this` lives in the
                // capture slot the runtime receiver-binding fills, so a bare
                // `::proceed` inside `intercept { handler(context, ::proceed) }`
                // binds the pipeline context, not a KProperty shell.
                if (try resolveThisRegKind(b, true, false)) |this_reg| {
                    // Inside a MEMBER EXTENSION the frame's `this` is the
                    // extension receiver; a `::name` referencing an OWNER
                    // member must bind the dispatch receiver instead
                    // (`::requestFocus` inside `SemanticsPropertyReceiver.
                    // applySemantics()` of FocusableNode). Route through
                    // the qualified-this runtime walk, which resolves the
                    // enclosing owner instance over the outer/receiver
                    // chains.
                    var recv_reg = this_reg;
                    if (member_shadows_ref) {
                        if (b.ownerClass()) |own| {
                            const ext_recv = b.recvTy();
                            if (ext_recv != null and !std.mem.eql(u8, ext_recv.?, own)) {
                                const qnm = try b.module.internConst(b.allocator, .{ .String = own });
                                const qreg = b.allocReg();
                                try b.push(.{ .QualifiedThis = .{ .dst = qreg, .receiver = this_reg, .qualifier = qnm } });
                                recv_reg = qreg;
                            }
                        }
                    }
                    try b.push(.{ .MemberRef = .{ .dst = dst, .receiver = recv_reg, .name = nm } });
                } else {
                    try b.push(.{ .PropertyRef = .{ .dst = dst, .name = nm } });
                }
            } else {
                try b.push(.{ .PropertyRef = .{ .dst = dst, .name = nm } });
            }
            return dst;
        },
        .MemberRef => |mr| {
            // `TypeName::class` on a bare type name: load the receiver with
            // constructor-reference semantics so a class that declares a
            // `companion object` yields the CLASS value, not its companion
            // singleton. Without `ctor_ref` a class-name read resolves to the
            // published companion (Kotlin's `C` ⇒ `C.Companion` value rule),
            // and `.class` then takes the companion's class — so once the
            // companion is constructed, `C::class` degrades to
            // `C$Companion$Companion` and `isInstance` / the name diverge.
            // `.class` is the identity on the resulting class value (and the
            // object's class for an `object` singleton), so it is kept.
            if (std.mem.eql(u8, mr.name.name, "class") and
                mr.receiver.* == .Path and mr.receiver.Path.segments.len == 1)
            {
                const rn0 = mr.receiver.Path.segments[0].name;
                if (b.resolve(rn0) == null and !b.knowsOuter(rn0)) {
                    // A reified parameter bound by the enclosing splice IS
                    // its actual (`T::class` inside a spliced
                    // `assertFailsWith<reified T>`): the bound head, never
                    // a runtime read of the process-global `T`.
                    const reified_head: ?[]const u8 = blk: {
                        const bound = b.resolveReifiedTypeName(rn0) orelse break :blk null;
                        var h = std.mem.trimEnd(u8, bound, "?");
                        if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
                        if (h.len == 0) break :blk null;
                        break :blk h;
                    };
                    // A nested class referenced by bare name inside its
                    // declaring subtree lives in the class table under its
                    // lifted name: that alias outranks every same-named
                    // class elsewhere (`A::class` inside a member extension
                    // of the outer that declares `class A`).
                    const rn = reified_head orelse (scopeTypeRename(b, rn0, mr.receiver.Path.segments[0].span.file.int()) orelse rn0);
                    // Resolve by the reference's own file and package first: a
                    // user declaration whose simple name collides with a
                    // builtin (`object Target` beside `kotlin.annotation
                    // .Target`) owns the name at its own site, and the
                    // simple-name index answers whichever registered last.
                    if (b.module.classIdIndexed(rn, b.self_package, mr.receiver.Path.segments[0].span.file) orelse
                        b.module.classId(rn)) |cid|
                    {
                        const recv = b.allocReg();
                        const rnm = try b.module.internConst(b.allocator, .{ .String = rn });
                        try b.push(.{ .LoadGlobal = .{ .dst = recv, .name = rnm, .class = cid, .ctor_ref = true } });
                        const dst = b.allocReg();
                        const cnm = try b.module.internConst(b.allocator, .{ .String = "class" });
                        try b.push(.{ .MemberRef = .{ .dst = dst, .receiver = recv, .name = cnm } });
                        return dst;
                    }
                }
            }
            // `String::countVowels` where the member names an in-scope
            // LOCAL extension function: kotlinc resolves the reference to
            // that local, not to a member of the type. The local lowered
            // as a closure bound to its name; the closure takes the
            // receiver as its first param, exactly the callable shape a
            // `Type::ext` reference must have.
            if (!std.mem.eql(u8, mr.name.name, "class") and
                mr.receiver.* == .Path and mr.receiver.Path.segments.len == 1 and
                b.isLocalExtFn(mr.name.name))
            {
                if (b.resolve(mr.name.name)) |r| return r;
                if (b.knowsOuter(mr.name.name)) {
                    const idx = try b.recordCapture(mr.name.name);
                    const dst = b.allocReg();
                    try b.push(.{ .LoadCapture = .{ .dst = dst, .idx = idx } });
                    return dst;
                }
            }
            if (!std.mem.eql(u8, mr.name.name, "class")) {
                var ref_shapes = try callableRefArgShapes(b, b.pending_lambda_arity);
                defer if (ref_shapes) |*shapes| shapes.deinit(b.allocator);
                if (ref_shapes) |*shapes| {
                    if (try resolveExtensionRefTarget(
                        b,
                        mr.receiver,
                        mr.name,
                        shapes,
                    )) |target_id| {
                        const target = b.module.funcById(target_id).?;
                        const recv = try lowerReceiver(b, mr.receiver);
                        const dst = b.allocReg();
                        const original_name = try b.module.internConst(
                            b.allocator,
                            .{ .String = target.name },
                        );
                        try b.push(.{ .MemberRef = .{
                            .dst = dst,
                            .receiver = recv,
                            .name = original_name,
                            .func = target_id,
                        } });
                        return dst;
                    }
                }
            }
            // `Outer::Nested` where `Nested` is a class is a constructor
            // reference, not a bound member ref — load the class value.
            if (!std.mem.eql(u8, mr.name.name, "class") and
                mr.receiver.* == .Path and
                b.module.classId(mr.name.name) != null)
            {
                const dst = b.allocReg();
                const nm = try b.module.internConst(b.allocator, .{ .String = mr.name.name });
                try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm } });
                return dst;
            }
            // `X::member` where `X` is a bare type/constructor name that has
            // no IR classId (e.g. an unsigned array `ULongArray`) must load
            // the type reference directly. Routing it through
            // `lowerReceiver` -> the implicit-`this` path inside a method
            // would emit `this.X(...)` and invoke the constructor instead of
            // taking the type value (`UIntArray::copyInto` inside a test
            // class constructed a UIntArray from the ref's first use).
            if (mr.receiver.* == .Path and mr.receiver.Path.segments.len == 1) {
                const rn = mr.receiver.Path.segments[0].name;
                // A scope-renamed name has no bare `class_id` either, but it
                // is a real classifier — a nested `Box` inside its declaring
                // class lifts to `Holder$Box`. Loading the bare name would
                // strand the reference on an unresolved global; defer to
                // `lowerReceiver`, which applies the rewrite.
                const renamed = scopeTypeRename(b, rn, mr.receiver.Path.segments[0].span.file.int()) != null;
                if (!renamed and b.resolve(rn) == null and !b.knowsOuter(rn) and
                    b.module.classId(rn) == null and !b.hasOwnMember(rn) and
                    !isTopLevelProp(rn))
                {
                    const rr = b.allocReg();
                    const rnm = try b.module.internConst(b.allocator, .{ .String = rn });
                    try b.push(.{ .LoadGlobal = .{ .dst = rr, .name = rnm } });
                    const dst = b.allocReg();
                    const cnm = try b.module.internConst(b.allocator, .{ .String = mr.name.name });
                    try b.push(.{ .MemberRef = .{ .dst = dst, .receiver = rr, .name = cnm } });
                    return dst;
                }
            }
            const recv = try lowerReceiver(b, mr.receiver);
            const dst = b.allocReg();
            const nm = try b.module.internConst(b.allocator, .{ .String = mr.name.name });
            try b.push(.{ .MemberRef = .{ .dst = dst, .receiver = recv, .name = nm } });
            return dst;
        },
        .ObjectExpr => {
            // Anonymous-object expressions carry rich AST shape; emit a
            // `BuildObject` Inst whose host synthesises a fresh ClassDef
            // with the snapshotted env on each call.
            var outer_names = try b.visibleNames();
            defer outer_names.deinit();
            // A receiver lambda binds `this` through the closure's capture
            // slot rather than a scope binding, so `visibleNames` misses it
            // (a method body binds it as a param and includes it). The
            // enclosing receiver is part of the anon's closed-over env: a
            // supertype ctor arg (`object : Prov(this)`) evaluates against
            // this snapshot before the object exists.
            if (!outer_names.contains("this") and
                (b.resolve("this") != null or b.capturesThisSlot() or b.knowsOuter("this")))
            {
                try outer_names.put("this", {});
            }
            const captured_names = try setToSlice(b.allocator, &outer_names);
            const captures = try b.allocator.alloc(Reg, captured_names.len);
            for (captured_names, captures) |n, *c| c.* = try resolveCapture(b, n);
            const dst = b.allocReg();
            const ast_box = try b.allocator.create(Expr);
            ast_box.* = expr.*;
            try b.push(.{ .BuildObject = .{
                .dst = dst,
                .ast = runtime.forest.ForestField(Expr).fromPtr(ast_box),
                .captured_names = captured_names,
                .captures = captures,
                .scope_renames = try collectScopeRenames(b, expr.ObjectExpr.span.file.int()),
                .scope_classes = try collectScopeClasses(b, expr),
            } });
            return dst;
        },
        .AnonFun => return lowerAnonFun(b, expr),
        .This => |t| {
            if (t.qualifier) |q| {
                // A labeled receiver `this@fn` for an enclosing (extension)
                // function: resolve / capture the `this@<fn>` slot bound at
                // that function's entry — possibly through nested lambdas — so
                // it is the function's receiver, not the lambda's own `this`.
                const label = try std.fmt.allocPrint(b.allocator, "this@{s}", .{q.name});
                if (b.resolve(label)) |r| return r;
                if (b.knowsOuter(label)) {
                    const dst2 = try b.loadCaptureHoisted(label);
                    try b.bind(label, dst2);
                    return dst2;
                }
                // The enclosing ANON OBJECT closed over the labeled
                // receiver (`this@minus` inside an anon method): read the
                // capture. The class-label walk below would resolve to the
                // anon instance itself. No scope bind: a read inside a
                // conditional branch must not cache its register for reads
                // on paths where the branch never ran.
                if (decl_mod.isLowerAnonCapture(label)) {
                    const idx = try b.recordCapture(label);
                    const dst2 = b.allocReg();
                    try b.push(.{ .LoadCapture = .{ .dst = dst2, .idx = idx } });
                    return dst2;
                }
                // Inside a spliced receiver-lambda region, `this@<fn>`
                // naming the enclosing REAL function is that function's
                // OWN receiver — the innermost `this` is the splice
                // subject (`destination.apply { putAll(this@toMap) }`
                // read the destination back and built an empty map). The
                // outermost scope's `this` binding is the function's own.
                if (inline_call.rfsEnabled() and
                    (b.lambda_splice_resolve != null or b.encl_tower_depth > 0))
                {
                    if (build.currentRealFn()) |rf| {
                        if (std.mem.eql(u8, rf, q.name)) {
                            if (b.resolveOutermost("this")) |own| return own;
                        }
                    }
                }
                // Otherwise a class-name label (`this@Outer`): walk at runtime
                // from the nearest `this` over the class/outer chain.
                const this_reg = b.resolve("this") orelse blk: {
                    break :blk try b.loadCaptureHoisted("this");
                };
                const nm = try b.module.internConst(b.allocator, .{ .String = q.name });
                const dst = b.allocReg();
                try b.push(.{ .QualifiedThis = .{ .dst = dst, .receiver = this_reg, .qualifier = nm } });
                return dst;
            }
            // `this` bare resolves to the implicit first param, or the
            // captured `this` slot inside a lambda body.
            // `KLIO_THIS_TRACE=1` — every bare-`this` lowering: the active
            // splice window, each scope index holding a `this` binding, and
            // the resolved register (`resolve` applies the window + the
            // enclosing splice's hidden bands).
            if (runtime.envOnce("KLIO_THIS_TRACE") != null) {
                std.debug.print("[this-trace] span={}:{} depth={d}", .{ exprSpan(expr).file, exprSpan(expr).start, b.scopes.items.len });
                if (b.lambda_splice_resolve) |w| std.debug.print(" window=caller<{d} own>={d}", .{ w.caller_depth, w.own_base });
                var k: usize = 0;
                while (k < b.scopes.items.len) : (k += 1) {
                    if (b.scopes.items[k].get("this")) |r| std.debug.print(" s{d}=r{d}", .{ k, r.int() });
                }
                std.debug.print(" -> {?}\n", .{b.resolve("this")});
            }
            const this_reg = b.resolve("this") orelse blk: {
                break :blk try b.loadCaptureHoisted("this");
            };
            return this_reg;
        },
        .Super => {
            // `super` bare reads the same instance value as `this`.
            if (try resolveSuperThisReg(b)) |this_reg| return this_reg;
            try b.push(.{ .Trace = .{ .span = exprSpan(expr) } });
            return b.emitConst(.Unit);
        },
        .Spread => {
            // A bare spread outside a call argument list has no lowering yet.
            try b.push(.{ .Trace = .{ .span = exprSpan(expr) } });
            return b.emitConst(.Unit);
        },
    }
}

/// `Binary` lowering: the short-circuiting operators (`&&`, `||`, `?:`),
/// the `in`/`!in` desugars, generic-operand comparisons, and the eager
/// primitive operators.
/// Numeric/string/char/bool simple type heads whose `+`/`-` stay primitive.
pub fn isPrimitiveTypeName(name: []const u8) bool {
    const prims = [_][]const u8{ "Int", "Long", "Short", "Byte", "Double", "Float", "Char", "Boolean", "String", "UInt", "ULong", "UShort", "UByte", "Number" };
    for (prims) |p2| {
        if (std.mem.eql(u8, name, p2)) return true;
    }
    return false;
}

/// Whether a nominal receiver carries enough structural arguments to prove an
/// overload choice. Head-only evidence for a generic class (`List`) cannot
/// substitute its declaration parameters and must not displace a complete
/// declaration-derived type (`List<Int>`).
fn staticClassifierArgsComplete(b: *FuncBuilder, ty: TypeRef) bool {
    var identity = std.mem.trimEnd(u8, ty.name, "?");
    if (std.mem.indexOfScalar(u8, identity, '<')) |lt| identity = identity[0..lt];
    const head = typeHead(identity);
    const cid = if (std.mem.indexOfScalar(u8, identity, '.') != null)
        b.module.classIdByFqn(identity)
    else
        b.module.uniqueClassIdBySimpleName(head);
    const class_id = cid orelse return true;
    if (class_id.int() >= b.module.classes.items.len) return false;
    const class = &b.module.classes.items[class_id.int()];
    return ty.args.len >= class.type_params.len;
}

/// Resolve a non-primitive binary operator through the same member/extension
/// declaration engine as its explicit-call form (`a + b` is `a.plus(b)`).
/// The static argument type is essential for overloads such as
/// `Collection<T>.plus(element: T)` versus `.plus(elements: Sequence<T>)`.
fn lowerResolvedBinaryOperator(
    b: *FuncBuilder,
    op: AstBinOp,
    lhs: *const Expr,
    rhs: *const Expr,
    call_span: ast.Span,
) Allocator.Error!?Reg {
    const method: []const u8 = switch (op) {
        .Add => "plus",
        .Sub => "minus",
        else => return null,
    };

    var inferred_lhs_ty: ?ir.TypeRef = null;
    defer if (inferred_lhs_ty) |*ty| ty.deinit(b.allocator);
    if (lhs.* == .Call or lhs.* == .Binary) {
        inferred_lhs_ty = try staticCallReturnTypeRef(b, lhs);
    }
    if (runtime.envOnce("KLIO_HOP_TRACE") != null) {
        const lazy = argDeclTypeRefLazy(b, lhs);
        const bare: ?[]const u8 = if (lhs.* == .Path and lhs.Path.segments.len == 1)
            staticBareReceiverType(b, lhs.Path.segments[0].name)
        else
            null;
        std.debug.print("[binop-in] {s} lhs={s} inferred={s} lazy={s} bare={s} owner={s}\n", .{
            method,
            @tagName(std.meta.activeTag(lhs.*)),
            if (inferred_lhs_ty) |t| t.name else "-",
            if (lazy) |t| t.name else "-",
            bare orelse "-",
            b.ownerClass() orelse "-",
        });
    }
    const declared_lhs_ty = inferred_lhs_ty orelse
        argDeclTypeRefLazy(b, lhs) orelse return null;
    if (isPrimitiveTypeName(typeHead(declared_lhs_ty.name))) return null;
    if (!staticClassifierArgsComplete(b, declared_lhs_ty)) return null;

    const args = rhs[0..1];
    const ident = ast.Ident{ .name = method, .span = call_span };
    const member_form = try lowerResolvedMemberCall(
        b,
        lhs,
        ident,
        args,
        &.{},
        &.{},
        declared_lhs_ty,
        .{},
    );
    if (runtime.envOnce("KLIO_HOP_TRACE") != null) {
        std.debug.print("[binop] {s} lhs_ty={s} member={s}\n", .{
            method,
            declared_lhs_ty.name,
            @tagName(std.meta.activeTag(member_form)),
        });
    }
    switch (member_form) {
        .lowered => |reg| return reg,
        .deferred => return null,
        .none => {},
    }
    ext_route_tag = "lowerResolvedBinaryOperator:1404";
    return try lowerResolvedExtensionCall(
        b,
        lhs,
        ident,
        args,
        &.{},
        &.{},
        declared_lhs_ty,
    );
}

fn lowerBinary(b: *FuncBuilder, bin: anytype) Allocator.Error!Reg {
    const op = bin.op;
    const lhs = bin.lhs;
    const rhs = bin.rhs;

    if (try lowerResolvedBinaryOperator(b, op, lhs, rhs, bin.span)) |reg| {
        return reg;
    }

    // Compatibility path for a known `this` receiver whose declaration set
    // is not yet complete enough for exact resolution. The shared resolver
    // runs first so smart casts and overload applicability can select the
    // precise static extension before this name-based fallback.
    if ((op == .Add or op == .Sub) and lhs.* == .This and lhs.This.qualifier == null) {
        const sty: ?[]const u8 = b.recvTy() orelse b.enclosingRecvTy();
        if (sty) |ty| {
            if (!isPrimitiveTypeName(ty)) {
                const l = try lowerExpr(b, lhs);
                const r = try lowerExpr(b, rhs);
                const args_start = try packContiguous(b, &.{r});
                const dst = b.allocReg();
                const nm = try b.module.internConst(b.allocator, .{ .String = if (op == .Add) "plus" else "minus" });
                try b.push(.{ .CallMember = .{
                    .dst = dst,
                    .receiver = l,
                    .name = nm,
                    .static_recv = try b.module.internConst(b.allocator, .{ .String = ty }),
                    .args = args_start,
                    .n_args = 1,
                    .arg_names = &.{},
                } });
                return dst;
            }
        }
    }

    // `list + (x as Any)`: kotlinc resolves `plus(element: T)` from the
    // RHS's STATIC type, appending the value as one element even when it
    // is itself a list at runtime. Route a statically list-headed LHS
    // with an Any-cast RHS through `plusElement`.
    if (op == .Add and staticListHead(lhs) and ast_scan.isBoxedToAnyForm(rhs)) {
        const l = try lowerExpr(b, lhs);
        const r = try lowerExpr(b, rhs);
        const args_start = try packContiguous(b, &.{r});
        const dst = b.allocReg();
        const nm = try b.module.internConst(b.allocator, .{ .String = "plusElement" });
        try b.push(.{ .CallMember = .{
            .dst = dst,
            .receiver = l,
            .name = nm,
            .args = args_start,
            .n_args = 1,
        } });
        return dst;
    }

    // `==` on a boxed operand (an `Any`-typed or generic type-parameter value,
    // e.g. `assertEquals(expected: T, actual: T)`) uses total-order equality —
    // `NaN == NaN` is true and `0.0 != -0.0`, matching boxed `Double.equals`.
    if ((op == .Eq or op == .Neq) and
        (isBoxedToAnyForm(lhs) or isBoxedToAnyForm(rhs) or
            isAnyTypedPath(b, lhs) or isAnyTypedPath(b, rhs) or
            isGenericTypedPath(b, lhs) or isGenericTypedPath(b, rhs)))
    {
        const l = try lowerExpr(b, lhs);
        const r = try lowerExpr(b, rhs);
        const dst = b.allocReg();
        const ir_op: BinOp = if (op == .Eq) .BoxedEq else .BoxedNotEq;
        try b.push(.{ .BinOp = .{ .dst = dst, .op = ir_op, .lhs = l, .rhs = r } });
        return dst;
    }

    // `x in haystack` / `x !in haystack`.
    if (op == .In or op == .NotIn) {
        // `x in lo..hi` / `x in lo..<hi` with a range *literal* on the right
        // lowers to `lo <= x && x <(=) hi` — but only when `x` is provably a
        // scalar element. A range-valued `x` dispatches `contains` instead
        // (an in-scope `operator LongRange.contains(LongRange)` decides
        // range-in-range; the element compare would be wrong for it).
        if (rhs.* == .Binary and (rhs.Binary.op == .Range or rhs.Binary.op == .RangeUntil) and
            !lhsIsRangeShaped(b, lhs))
        {
            const r_op = rhs.Binary.op;
            const lo = rhs.Binary.lhs;
            const hi = rhs.Binary.rhs;
            const x = try lowerExpr(b, lhs);
            const lo_r = try lowerExpr(b, lo);
            const hi_r = try lowerExpr(b, hi);
            const ge = b.allocReg();
            try b.push(.{ .BinOp = .{ .dst = ge, .op = .LessEq, .lhs = lo_r, .rhs = x } });
            const upper: BinOp = if (r_op == .RangeUntil) .Less else .LessEq;
            const le = b.allocReg();
            try b.push(.{ .BinOp = .{ .dst = le, .op = upper, .lhs = x, .rhs = hi_r } });
            const both = b.allocReg();
            try b.push(.{ .BinOp = .{ .dst = both, .op = .And, .lhs = ge, .rhs = le } });
            if (op == .NotIn) {
                const dst = b.allocReg();
                try b.push(.{ .Not = .{ .dst = dst, .src = both } });
                return dst;
            }
            return both;
        }
        const recv = try lowerExpr(b, rhs);
        const arg_slot = b.allocReg();
        const l = try lowerExpr(b, lhs);
        try b.push(.{ .Move = .{ .dst = arg_slot, .src = l } });
        const contains = b.allocReg();
        const nm = try b.module.internConst(b.allocator, .{ .String = "contains" });
        try b.push(.{ .CallMember = .{
            .dst = contains,
            .receiver = recv,
            .name = nm,
            .args = arg_slot,
            .n_args = 1,
            .arg_names = &.{},
        } });
        if (op == .NotIn) {
            const dst = b.allocReg();
            try b.push(.{ .Not = .{ .dst = dst, .src = contains } });
            return dst;
        }
        return contains;
    }

    // Elvis `a ?: b` short-circuits.
    if (op == .Elvis) {
        const l = try lowerExpr(b, lhs);
        const null_r = try b.emitConst(.Null);
        const is_null = b.allocReg();
        try b.push(.{ .BinOp = .{ .dst = is_null, .op = .Eq, .lhs = l, .rhs = null_r } });
        const then_b = try b.allocBlock();
        const else_b = try b.allocBlock();
        const join = try b.allocBlock();
        const dst = b.allocReg();
        b.terminate(.{ .Branch = .{ .cond = is_null, .t = then_b, .f = else_b } });
        b.switchTo(then_b);
        const rv = try lowerExpr(b, rhs);
        try b.push(.{ .Move = .{ .dst = dst, .src = rv } });
        b.terminate(.{ .Goto = join });
        b.switchTo(else_b);
        try b.push(.{ .Move = .{ .dst = dst, .src = l } });
        b.terminate(.{ .Goto = join });
        b.switchTo(join);
        return dst;
    }

    // Logical `&&` / `||`.
    if (op == .And or op == .Or) {
        const l = try lowerExpr(b, lhs);
        const then_b = try b.allocBlock();
        const else_b = try b.allocBlock();
        const join = try b.allocBlock();
        const dst = b.allocReg();
        b.terminate(.{ .Branch = .{ .cond = l, .t = then_b, .f = else_b } });
        if (op == .And) {
            b.switchTo(then_b);
            // The right operand sees every proof the left one establishes:
            // `it is UByte && it.toByte() ...` smart-casts `it` for the
            // member call, exactly as an `if` guard narrows its then-arm.
            var narrowed: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer narrowed.deinit(b.allocator);
            try narrowIsCheckAll(b, lhs, &narrowed);
            var not_null: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer not_null.deinit(b.allocator);
            try narrowNullCheckAll(b, lhs, true, &not_null);
            const rv = try lowerExpr(b, rhs);
            var nn = not_null.items.len;
            while (nn > 0) : (nn -= 1) b.restoreLocal(not_null.items[nn - 1]);
            var ni = narrowed.items.len;
            while (ni > 0) : (ni -= 1) b.restoreLocal(narrowed.items[ni - 1]);
            try b.push(.{ .Move = .{ .dst = dst, .src = rv } });
            b.terminate(.{ .Goto = join });
            b.switchTo(else_b);
            const false_r = try b.emitConst(.{ .Bool = false });
            try b.push(.{ .Move = .{ .dst = dst, .src = false_r } });
            b.terminate(.{ .Goto = join });
        } else {
            b.switchTo(then_b);
            const true_r = try b.emitConst(.{ .Bool = true });
            try b.push(.{ .Move = .{ .dst = dst, .src = true_r } });
            b.terminate(.{ .Goto = join });
            b.switchTo(else_b);
            // `x == null || x.m()` runs its right operand only when the
            // left is false, which proves the null-checks' falsy side.
            var else_not_null: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer else_not_null.deinit(b.allocator);
            try narrowNullCheckAll(b, lhs, false, &else_not_null);
            const rv = try lowerExpr(b, rhs);
            var en = else_not_null.items.len;
            while (en > 0) : (en -= 1) b.restoreLocal(else_not_null.items[en - 1]);
            try b.push(.{ .Move = .{ .dst = dst, .src = rv } });
            b.terminate(.{ .Goto = join });
        }
        b.switchTo(join);
        return dst;
    }

    // Comparison on a generic type-parameter operand → `a.compareTo(b) <op> 0`.
    // Inside a function that declares its own type parameters, an operand
    // with no concrete static type (`var min = iterator.next()` in the
    // generic `minOrNull` body) is `T`-typed under Kotlin's inference, so
    // the comparison also follows the `compareTo` total order — the IEEE
    // primitive comparison applies only where a numeric static type is
    // established (a literal, or a local with a numeric declared type or
    // literal initializer).
    if ((op == .Lt or op == .Le or op == .Gt or op == .Ge) and
        (isGenericOperand(b, lhs) or isGenericOperand(b, rhs) or
            (b.hasOwnTypeParams() and
                !staticallyOrderedOperand(b, lhs) and !staticallyOrderedOperand(b, rhs))))
    {
        const recv = try lowerExpr(b, lhs);
        const arg_slot = b.allocReg();
        const r = try lowerExpr(b, rhs);
        try b.push(.{ .Move = .{ .dst = arg_slot, .src = r } });
        const cmp = b.allocReg();
        const nm = try b.module.internConst(b.allocator, .{ .String = "compareTo" });
        try b.push(.{ .CallMember = .{
            .dst = cmp,
            .receiver = recv,
            .name = nm,
            .args = arg_slot,
            .n_args = 1,
            .arg_names = &.{},
        } });
        const zero = try b.emitConst(.{ .Int = 0 });
        const dst = b.allocReg();
        try b.push(.{ .BinOp = .{ .dst = dst, .op = astBinop(op), .lhs = cmp, .rhs = zero } });
        return dst;
    }

    const l0 = try lowerExpr(b, lhs);
    // `it + x` / `it - x` where `it` is statically a broad collection
    // (`Iterable`/`Collection`) produces a `List` even when the runtime value
    // is a `Set`; coerce the receiver to a list so the `List`-returning
    // `plus`/`minus` is dispatched rather than the `Set`-returning one.
    const l = if (op == .Add or op == .Sub)
        try helpers.coerceBroadCollectionToList(b, lhs, l0)
    else
        l0;
    const r = try lowerExpr(b, rhs);
    const dst = b.allocReg();
    try b.push(.{ .BinOp = .{ .dst = dst, .op = astBinop(op), .lhs = l, .rhs = r } });
    return dst;
}

fn isGenericOperand(b: *FuncBuilder, e: *const Expr) bool {
    return e.* == .Path and e.Path.segments.len == 1 and
        b.isGenericTypedParam(e.Path.segments[0].name);
}

/// A comparison operand with an established concrete static type: a literal,
/// or a plain local/param whose declared type is a known builtin value head
/// or whose recorded initializer is a literal. Such an operand keeps the
/// primitive `BinOp` comparison inside a generic function; everything else
/// there is `T`-typed under Kotlin's inference and dispatches `compareTo`.
fn staticallyOrderedOperand(b: *FuncBuilder, e: *const Expr) bool {
    if (argLitKind(e) != null) return true;
    if (e.* == .Path and e.Path.segments.len == 1) {
        const n = e.Path.segments[0].name;
        if (b.localDeclType(n)) |t| return paramLitKind(t) != null;
        if (b.localInitExpr(n)) |ie| return argLitKind(ie) != null;
    }
    return false;
}

/// Write `val` back to the lvalue `target` (shared by prefix ++/-- and the
/// postfix path's pre-snapshot path). Delegates to the single write-back
/// decision in `stmt_mod.storeCombinedToTarget` so compound-assign, prefix,
/// and postfix never diverge on where a bare name lands (local / cell /
/// capture / own-member / lambda-this / top-level global).
fn writeBackLvalue(b: *FuncBuilder, target: *const Expr, val: Reg) Allocator.Error!void {
    try stmt_mod.storeCombinedToTarget(b, target, val);
}

/// A bare `name` an enclosing class declares as a value member (an enclosing
/// companion's `Default`) shadows an unrelated global classifier of the same
/// simple name. True when `name` is an enclosing member and is NOT a nested
/// Whether `name` is a known class that has a registered companion object.
/// Such a name in value position is its companion singleton (Kotlin: `C`
/// yields `C.Companion`), which must win over a folded classifier name that
/// would otherwise route the read to a non-existent `this.<name>` field.
fn classWithCompanion(b: *const FuncBuilder, name: []const u8) bool {
    return b.module.classId(name) != null and
        b.module.registry.companion_singletons.contains(name);
}

/// type reachable along the enclosing-owner chain (a nested type keeps the
/// classifier path so it names a class value).
fn enclosingMemberShadowsClass(b: *const FuncBuilder, name: []const u8) bool {
    if (!b.hasEnclosingMember(name)) return false;
    var owner = b.ownerClass();
    var hops: usize = 0;
    while (owner) |o| : (hops += 1) {
        if (hops > 32) break;
        if (b.module.registry.nested_object_aliases.get(o)) |m| {
            if (m.contains(name)) return false;
        }
        owner = b.module.registry.enclosing_class.get(o);
    }
    return true;
}

/// The mangled lift name a type reference `name` resolves to in the
/// current scope: a (mangled) nested class/object aliased anywhere along
/// the enclosing-class chain — Kotlin makes a private nested class
/// visible throughout its declaring class's subtree, and a lifted
/// sibling/nested member keeps the outer on its chain — or a renamed
/// file-private class/typealias declared by the reference's own file.
/// Returns null when no rename applies.

/// Whether the own member overload of `name` with this arity declares a
/// NON-function parameter where the call passes a lambda literal — such a
/// member cannot bind the call, so it must not outrank a same-named
/// extension that can (`cast(value, name) { … }` picking the member
/// `cast(value, name, tag: String)` bound the lambda to `tag`).
/// Whether the enclosing class declares a member named `name` that a call
/// with `nargs` arguments can bind. The own-member arity mask decides when
/// it has an entry; a lazily lowered body carries none, and then the
/// registered signatures of the owner's same-named members decide
/// (`Json.encodeToString(value, mode)` never takes one argument). Unknown
/// stays applicable, as the mask's own default does.
fn enclosingMemberTakes(b: *const FuncBuilder, name: []const u8, nargs: usize) bool {
    const tr = if (runtime.envOnce("KLIO_INLINE_PICK")) |w| std.mem.eql(u8, w, name) else false;
    if (b.own_member_arity.get(name) != null) {
        if (tr) std.debug.print("[emt] {s} mask -> {}\n", .{ name, b.ownMemberApplicable(name, nargs) });
        return b.ownMemberApplicable(name, nargs);
    }
    const owner = b.ownerClass() orelse build.currentOwnerClass() orelse {
        if (tr) std.debug.print("[emt] {s} no owner -> true\n", .{name});
        return true;
    };
    var found_any = false;
    for (b.module.funcsBySimpleName(name)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.fqn.len <= name.len + 1) continue;
        const prefix = f.fqn[0 .. f.fqn.len - name.len - 1];
        if (!std.mem.endsWith(u8, prefix, owner)) continue;
        found_any = true;
        var required: usize = 0;
        var total: usize = 0;
        for (f.params, 0..) |*p, i| {
            if (i == 0 and std.mem.eql(u8, p.name, "this")) continue;
            if (p.is_vararg) return true;
            total += 1;
            if (!p.has_default) required += 1;
        }
        if (nargs >= required and nargs <= total) {
            if (tr) std.debug.print("[emt] {s} owner={s} sig {s} takes {d}\n", .{ name, owner, f.fqn, nargs });
            return true;
        }
    }
    if (tr) std.debug.print("[emt] {s} owner={s} found_any={} -> {}\n", .{ name, owner, found_any, !found_any });
    return !found_any;
}

fn ownMemberRejectsLambdas(b: *const FuncBuilder, name: []const u8, args: []const Expr) bool {
    const owner = b.ownerClass() orelse return false;
    // The registration key is the SOURCE class name; a file-private class
    // lowers under a `$f<n>` mangle and a nested one under `Outer$Inner`.
    const mf = inline_state.exprBodyMemberAst(owner, name, args.len) orelse blk: {
        if (std.mem.indexOf(u8, owner, "$f")) |i| {
            if (inline_state.exprBodyMemberAst(owner[0..i], name, args.len)) |m| break :blk m;
        }
        return false;
    };
    for (args, 0..) |*a, i| {
        const is_lambda = switch (a.*) {
            .Lambda, .AnonFun => true,
            else => false,
        };
        if (!is_lambda) continue;
        if (i >= mf.params.len) return false;
        if (mf.params[i].ty.function == null and !std.mem.eql(u8, mf.params[i].ty.name.name, "Any")) return true;
    }
    return false;
}

pub fn scopeTypeRename(b: *const FuncBuilder, name: []const u8, file: u32) ?[]const u8 {
    return scopeTypeRenameFrom(b, b.ownerClass(), name, file);
}

/// `scopeTypeRename` starting the enclosing-class walk at an explicit
/// owner: an inline splice binds its reified names AFTER pushing the
/// callee's frame (which drops the caller's owner), so the caller's
/// lexical owner is passed in to keep a nested class's lifted name.
pub fn scopeTypeRenameFrom(b: *const FuncBuilder, owner_start: ?[]const u8, name: []const u8, file: u32) ?[]const u8 {
    var owner = owner_start;
    var hops: usize = 0;
    while (owner) |o| : (hops += 1) {
        if (hops > 32) break;
        if (b.module.registry.nested_object_aliases.get(o)) |m| {
            if (m.get(name)) |renamed| return renamed;
        }
        // A supertype's nested classifiers are in scope in the subclass
        // body (`Conflict("foo")` inside a test extending the base that
        // declares `class Conflict`), lifted names included.
        if (supertypeNestedAlias(b, o, name, 0)) |renamed| return renamed;
        owner = b.module.registry.enclosing_class.get(o);
    }
    // An anon-object member body lowering at runtime carries its lexical
    // site's flattened renames (the side module's registries are empty).
    if (build.anonScopeRename(name)) |renamed| return renamed;
    if (build.fileTypeRename(name, file)) |renamed| return renamed;
    // Same-package cross-file reference to a package-renamed internal
    // top-level classifier.
    if (b.module.packageOfFile(ir.FileId.from(file))) |pkg| {
        if (build.pkgTypeRename(name, pkg)) |renamed| return renamed;
    }
    // Cross-package reference through an import of the declaring package
    // (internal visibility spans the whole module).
    if (decl_mod.importedPkgTypeRename(b.module, name, ir.FileId.from(file))) |renamed| return renamed;
    return null;
}

/// The lifted name a supertype of `cls_name` registers for nested `name`,
/// walking the declared supertype chain.
fn supertypeNestedAlias(b: *const FuncBuilder, cls_name: []const u8, name: []const u8, depth: usize) ?[]const u8 {
    if (depth > 16) return null;
    const cid = b.module.classId(cls_name) orelse return null;
    if (cid.int() >= b.module.classes.items.len) return null;
    const cls = &b.module.classes.items[cid.int()];
    for (cls.supertypes) |sid| {
        if (sid.int() >= b.module.classes.items.len) continue;
        const sup = &b.module.classes.items[sid.int()];
        if (b.module.registry.nested_object_aliases.get(sup.name)) |m| {
            if (m.get(name)) |renamed| return renamed;
        }
        if (supertypeNestedAlias(b, sup.name, name, depth + 1)) |renamed| return renamed;
    }
    return null;
}

/// Flatten every scope-true type rename visible at the current lexical
/// site — the enclosing-class chain's alias maps (nearest scope first),
/// the anon-scope renames when this site itself sits inside an anon-object
/// body lowering, and the declaring file's file-private type renames —
/// into one slice for a `BuildObject` instruction. First entry per name
/// wins on lookup, so nearer scopes shadow outer ones.
fn collectScopeRenames(b: *FuncBuilder, file: u32) Allocator.Error![]const ir.ScopeRename {
    var out: std.ArrayList(ir.ScopeRename) = .empty;
    var owner = b.ownerClass();
    var hops: usize = 0;
    while (owner) |o| : (hops += 1) {
        if (hops > 32) break;
        if (b.module.registry.nested_object_aliases.get(o)) |m| {
            var it = m.iterator();
            while (it.next()) |e| {
                try out.append(b.allocator, .{ .name = e.key_ptr.*, .renamed = e.value_ptr.* });
            }
        }
        owner = b.module.registry.enclosing_class.get(o);
    }
    for (build.anonScopeRenames()) |r| try out.append(b.allocator, r);
    if (build.fileTypeRenamesFor(file)) |m| {
        var it = m.iterator();
        while (it.next()) |e| {
            try out.append(b.allocator, .{ .name = e.key_ptr.*, .renamed = e.value_ptr.* });
        }
    }
    if (b.module.packageOfFile(ir.FileId.from(file))) |pkg| {
        if (build.pkgTypeRenamesFor(pkg)) |m| {
            var it = m.iterator();
            while (it.next()) |e| {
                try out.append(b.allocator, .{ .name = e.key_ptr.*, .renamed = e.value_ptr.* });
            }
        }
    }
    return out.toOwnedSlice(b.allocator);
}

/// Resolve every bare classifier referenced by an anonymous-object subtree at
/// its lexical site. The object's bodies lower later in a side module, so these
/// exact identities must travel with the object instruction.
fn collectScopeClasses(b: *FuncBuilder, expr: *const Expr) Allocator.Error![]const ir.ScopeClassRef {
    var names = StringSet.init(b.allocator);
    defer names.deinit();
    try collectPathIdents(expr, &names);

    var out: std.ArrayList(ir.ScopeClassRef) = .empty;
    var it = names.keyIterator();
    while (it.next()) |name_ptr| {
        const name = name_ptr.*;
        const cid = classIdAtLexicalSite(b, name, expr.span().file) orelse continue;
        if (cid.int() >= b.module.classes.items.len) continue;
        const cls = b.module.classes.items[cid.int()];
        const has_companion = b.module.registry.companion_singletons.contains(name) or
            b.module.registry.companion_singletons.contains(cls.name) or
            b.module.registry.companion_singletons.contains(cls.fqn);
        try out.append(b.allocator, .{
            .name = name,
            .fqn = cls.fqn,
            .has_companion = has_companion,
        });
    }
    return out.toOwnedSlice(b.allocator);
}

/// Reduce a dotted path to its last two segments (`a.b.C` -> `b.C`);
/// null when the path has fewer than two.
fn lastTwoSegments(path: []const u8) ?[]const u8 {
    var last: ?usize = null;
    var prev: ?usize = null;
    var i: usize = 0;
    while (i < path.len) : (i += 1) {
        if (path[i] == '.') {
            prev = last;
            last = i;
        }
    }
    if (last == null) return null;
    const start = if (prev) |p| p + 1 else 0;
    return path[start..];
}

/// The lowered name for a type position (`as T` / `is T` / catch type):
/// a qualified nested reference (`Outer.Inner`) whose target the lift
/// mangled resolves to the mangled lift name, then the scope-true
/// rename ladder (`scopeTypeRename`), then the bare simple name.
pub fn loweredTypeName(b: *const FuncBuilder, ty: *const ast.TypeRef) []const u8 {
    if (ty.qualified_path) |qp| {
        if (lastTwoSegments(qp)) |key| {
            if (b.module.registry.mangled_nested.get(key)) |m| return m;
        }
    }
    if (scopeTypeRename(b, ty.name.name, ty.span.file.int())) |renamed| return renamed;
    // A function-local class (`@Serializable data class Outer(...)` declared
    // in the body) is keyed by its `$lc<fn>` alias; an explicit type argument
    // naming it (`decodeFromString<Outer>(...)`) binds that alias, not the
    // bare name another file's `Outer` would answer.
    var lc_buf: [160]u8 = undefined;
    if (std.fmt.bufPrint(&lc_buf, "{s}$lc{s}", .{ ty.name.name, build.currentRealFn() orelse "" }) catch null) |key| {
        if (b.module.registry.class_super_names.get(key) != null) {
            return b.allocator.dupe(u8, key) catch ty.name.name;
        }
    }
    return ty.name.name;
}

/// Lower a source type into an owned structural type for builder metadata.
/// The top-level head follows the same scope-aware classifier rename as
/// expression type positions.
pub fn loweredOwnedLocalTypeRef(b: *const FuncBuilder, ty: *const ast.TypeRef) Allocator.Error!TypeRef {
    var lowered = try decl_mod.loweredTypeRef(b.allocator, ty, true);
    errdefer lowered.deinit(b.allocator);
    const resolved_head = loweredTypeName(b, ty);
    if (!std.mem.eql(u8, lowered.name, resolved_head)) {
        const owned_head = try b.allocator.dupe(u8, resolved_head);
        b.allocator.free(lowered.name);
        lowered.name = owned_head;
    }
    if (ty.qualified_path == null) {
        var alias_fqn: ?[]const u8 = null;
        const imports = b.module.importAliasPathsIn(ty.span.file, ty.name.name);
        for (imports) |imported| {
            if (!b.module.registry.type_alias_types.contains(imported.fqn)) continue;
            if (alias_fqn != null and !std.mem.eql(u8, alias_fqn.?, imported.fqn)) {
                alias_fqn = null;
                break;
            }
            alias_fqn = imported.fqn;
        }
        const package = b.module.packageOfFile(ty.span.file) orelse b.self_package;
        const own_fqn = if (package.len == 0)
            try b.allocator.dupe(u8, ty.name.name)
        else
            try std.fmt.allocPrint(b.allocator, "{s}.{s}", .{ package, ty.name.name });
        defer b.allocator.free(own_fqn);
        if (alias_fqn == null and b.module.registry.type_alias_types.contains(own_fqn)) {
            alias_fqn = own_fqn;
        }
        if (alias_fqn) |fqn| {
            const marker = try std.fmt.allocPrint(b.allocator, "#qual:{s}", .{fqn});
            errdefer b.allocator.free(marker);
            const args = try b.allocator.alloc(ir.TypeRef, lowered.args.len + 1);
            errdefer b.allocator.free(args);
            @memcpy(args[0..lowered.args.len], lowered.args);
            args[args.len - 1] = .{
                .name = marker,
                .nullable = false,
                .args = &.{},
            };
            b.allocator.free(lowered.args);
            lowered.args = args;
        }
    }
    return lowered;
}

/// Type name for an `is` / `as` check. Like `loweredTypeName`, but a
/// package-qualified reference (`b.Shape`) keeps its dotted path (normalised
/// to the class FQN when it resolves) instead of being stripped to the simple
/// name, so the runtime hierarchy walk can compare class identity and reject a
/// same-simple-name class from another package. A nested-class path
/// (`Outer.Inner`) still maps to its lifted/mangled name.
pub fn loweredCheckTypeName(b: *const FuncBuilder, ty: *const ast.TypeRef) []const u8 {
    if (ty.qualified_path) |qp| {
        if (lastTwoSegments(qp)) |key| {
            if (b.module.registry.mangled_nested.get(key)) |m| return m;
        }
        // The path's first segment may itself be a nested class lifted under
        // a mangled name (`S.A` written inside `Tests`, where the private
        // `S` lifted as `Tests$S`): the lift keyed `A` by that lifted owner,
        // so the reference resolves through the owner's scope alias.
        if (std.mem.indexOfScalar(u8, qp, '.')) |d| {
            if (scopeTypeRename(b, qp[0..d], ty.span.file.int())) |owner| {
                if (std.fmt.allocPrint(b.allocator, "{s}.{s}", .{ owner, qp[d + 1 ..] })) |aliased| {
                    if (lastTwoSegments(aliased)) |key| {
                        if (b.module.registry.mangled_nested.get(key)) |m| return m;
                    }
                    if (b.module.classIdByFqn(aliased)) |cid| {
                        if (cid.int() < b.module.classes.items.len) return b.module.classes.items[cid.int()].fqn;
                    }
                } else |_| {}
            }
        }
        // Normalise to the canonical FQN when the dotted path resolves to a
        // registered class; otherwise carry the dotted path through so the
        // runtime resolves (or strips) it once every class is registered.
        if (b.module.classIdByFqn(qp)) |cid| {
            if (cid.int() < b.module.classes.items.len) return b.module.classes.items[cid.int()].fqn;
        }
        return qp;
    }
    if (scopeTypeRename(b, ty.name.name, ty.span.file.int())) |renamed| return renamed;
    // A bare check type this file's explicit import names (`import
    // …Operation.Marker`; `x is Marker`) normalises to the imported class's
    // canonical FQN, so the runtime compares class identity — the simple
    // name alone cannot resolve a nested member two packages both declare
    // (its lifted name is shared, so a name compare matches either twin).
    // An enclosing class's own nested classifier still wins over the
    // import (inner scope first), keeping the simple-name compare.
    if (!enclosingDeclaresNestedClassifier(b, ty.name.name)) {
        if (b.module.classIdExactImport(ty.name.name, ty.span.file)) |cid| {
            if (cid.int() < b.module.classes.items.len) return b.module.classes.items[cid.int()].fqn;
        }
    }
    return ty.name.name;
}

/// Whether any class in the enclosing-class chain declares a NESTED
/// classifier named `name` — the scope where a bare check-type name binds
/// before the file's imports are consulted.
fn enclosingDeclaresNestedClassifier(b: *const FuncBuilder, name: []const u8) bool {
    const oc = b.ownerClass() orelse return false;
    const owner_id = b.module.classId(oc) orelse return false;
    return b.module.classIdNestedIn(owner_id, name) != null;
}

/// The mangled per-file global for a bare `name` referenced from the file
/// `file`, or null when the reference is not a read of a renamed
/// file-private top-level property. Locals, lambda/anon-object captures,
/// and own class members shadow the property (Kotlin scope order), so the
/// rename only applies when none of them bind the name.
pub fn filePrivatePropRename(b: *FuncBuilder, name: []const u8, file: u32) ?[]const u8 {
    const renamed = build.filePrivateRename(name, file) orelse return null;
    if (b.resolve(name) != null) return null;
    if (b.knowsOuter(name)) return null;
    if (decl_mod.isLowerAnonCapture(name)) return null;
    if (b.hasOwnMember(name)) return null;
    return renamed;
}

/// `Path` lowering — the full bare-name resolution ladder.
/// The DECLARED name a renamed import binds `seg` to for a bare READ, when
/// the caller's file imports something under a different leaf and nothing in
/// scope — a local, a parameter, an enclosing capture, a top-level of that
/// spelling — claims the name as written. Null leaves the spelling alone.
fn bareAliasTargetName(b: *FuncBuilder, seg: *const ast.Ident) ?[]const u8 {
    if (b.resolve(seg.name) != null or b.knowsOuter(seg.name) or b.isParam(seg.name)) return null;
    // A MEMBER of the enclosing class wins over an import, so the alias
    // decides only a name nothing in scope claims.
    if (b.hasOwnMember(seg.name) or b.hasEnclosingMember(seg.name)) return null;
    if (topLevelNameExists(b, seg.name)) return null;
    for (b.module.importAliasPathsIn(seg.span.file, seg.name)) |p| {
        if (p.segs.len == 0) continue;
        const target = p.segs[p.segs.len - 1];
        if (std.mem.eql(u8, target, seg.name)) continue;
        // The import itself is the evidence: Kotlin validated the path, and
        // the target may be a compiler intrinsic with no registry row of its
        // own (`kotlin.coroutines.coroutineContext`).
        return target;
    }
    return null;
}

/// Whether a top-level PROPERTY of this spelling exists — a stored global or a
/// custom-getter one. Only the property channel is consulted: a call and a
/// classifier already resolve through their own alias paths.
fn topLevelNameExists(b: *FuncBuilder, name: []const u8) bool {
    if (b.module.registry.top_level_prop_getters.contains(name)) return true;
    return b.module.registry.top_level_prop_pkgs.contains(name);
}

fn lowerPath(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const segments = expr.Path.segments;
    const span0 = expr.Path.span;

    // `var x by D` reads THROUGH the delegate: `D.getValue(null, ::x)` at every
    // read, not once at the declaration. A `MutableState` delegate hands back the
    // state's current value that way — and, in a composition, records the read on
    // the snapshot, which is what makes a later write invalidate the group that
    // read it. Reading a value cached at the declaration recorded no read at all,
    // so `var name by mutableStateOf(…)` never recomposed.
    if (segments.len == 1) {
        if (try lowerDelegateRead(b, segments[0].name)) |r| return r;
    }

    // File-private top-level property rename: a bare reference from the
    // declaring file resolves to the per-file mangled global. Locals,
    // captures, and own members keep shadowing it (Kotlin scope order).
    if (filePrivatePropRename(b, segments[0].name, segments[0].span.file.int())) |renamed| {
        const new_segs = try b.allocator.dupe(ast.Ident, segments);
        defer b.allocator.free(new_segs);
        new_segs[0] = .{ .name = renamed, .span = segments[0].span };
        const rewritten = Expr{ .Path = .{ .segments = new_segs, .span = span0 } };
        return lowerExpr(b, &rewritten);
    }

    // `const val name = <literal>` inline.
    if (segments.len == 1 and b.ownerClass() != null and b.resolve(segments[0].name) == null) {
        const owner = b.ownerClass().?;
        if (b.module.registry.class_const_inits.get(.{ .a = owner, .b = segments[0].name })) |c| {
            return b.emitConst(c);
        }
    }
    // Mangled nested-class/object alias and file-private type rewrite.
    {
        const renamed = scopeTypeRename(b, segments[0].name, segments[0].span.file.int());
        if (renamed != null and b.resolve(segments[0].name) == null) {
            const new_segs = try b.allocator.dupe(ast.Ident, segments);
            defer b.allocator.free(new_segs);
            new_segs[0] = .{ .name = renamed.?, .span = segments[0].span };
            const rewritten = Expr{ .Path = .{ .segments = new_segs, .span = span0 } };
            return lowerExpr(b, &rewritten);
        }
    }

    if (segments.len == 1) {
        const name0 = segments[0].name;
        // Bare `Unit` is the Unit singleton value.
        if (std.mem.eql(u8, name0, "Unit") and b.resolve("Unit") == null) {
            return b.emitConst(.Unit);
        }
        // Splice hygiene for the suspend-implicit `coroutineContext`: inside a
        // SPLICED inline-fn body (not an inline-argument lambda, whose source
        // lives at the caller), the bare name means the intrinsic — the callee
        // could not see a caller local/param that happens to share it. Without
        // this, `currentCoroutineContext()` (body: bare `coroutineContext`)
        // spliced into a function with a `coroutineContext` PARAMETER answered
        // with the parameter.
        if (std.mem.eql(u8, name0, "coroutineContext") and b.lambda_splice_resolve == null) {
            if (b.inlineLambdaCallerDepth()) |base| {
                if (b.resolveSpliceLocal(name0, base) == null) {
                    const dst = b.allocReg();
                    const n = try b.module.internConst(b.allocator, .{ .String = "coroutineContext" });
                    try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = n } });
                    return dst;
                }
            }
        }
        // A RENAMED import binds this spelling to another declaration
        // (`import kotlin.coroutines.coroutineContext as currentContext`). A
        // call and a classifier already resolve through the alias; a bare
        // PROPERTY read did not, and reached the runtime as the spelling — a
        // member probe on the enclosing receiver, then an unresolved global.
        // Nothing in scope claims the name, so the import decides it.
        if (bareAliasTargetName(b, &segments[0])) |target| {
            const dst = b.allocReg();
            const n = try b.module.internConst(b.allocator, .{ .String = target });
            try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = n } });
            return dst;
        }
        if (b.resolve(name0)) |r| {
            if (runtime.envOnce("KLIO_BARE_TRACE")) |w| if (std.mem.eql(u8, w, name0)) {
                std.debug.print("[bare-read-local] {s} reg={d} in={s} window={}\n", .{ name0, r.int(), build.currentRealFn() orelse "-", b.lambda_splice_resolve != null });
            };
            if (b.isBoxed(name0)) {
                const dst = b.allocReg();
                try b.push(.{ .CellGet = .{ .dst = dst, .cell = r } });
                return dst;
            }
            return r;
        }
        // A bare read of a name the enclosing anon object closes over reads
        // the captured value. Whether the capture is a shared Cell (a
        // written-through outer `var`) is decided by the CAPTURE SITE's
        // builder, invisible here — so always read through CellGet, which
        // passes a non-cell value unchanged. Without this a captured
        // counter's `++` handed the raw Cell to UnOp.
        if (isLowerAnonCapture(name0)) {
            const cell = try b.loadCaptureHoisted(name0);
            const dst = b.allocReg();
            try b.push(.{ .CellGet = .{ .dst = dst, .cell = cell } });
            return dst;
        }
        // Lambda-body capture.
        if (b.knowsOuter(name0)) {
            const cell = try b.loadCaptureHoisted(name0);
            if (b.isBoxed(name0)) {
                const dst = b.allocReg();
                try b.push(.{ .CellGet = .{ .dst = dst, .cell = cell } });
                return dst;
            }
            return cell;
        }
        // An `it` written in a zero-parameter / receiver lambda whose
        // implicit `it` was suppressed, with no enclosing lambda supplying
        // one: kotlinc rejects this as an unresolved reference. Record the
        // diagnostic so the build driver fails the program before it runs.
        if (b.it_suppressed and std.mem.eql(u8, name0, "it")) {
            try b.module.resolve_diags.append(b.allocator, .{
                .name = "it",
                .fqn_a = "",
                .fqn_b = "",
                .span = segments[0].span,
                .kind = .unresolved_local,
            });
            return b.emitConst(.Unit);
        }
        // A bare `coroutineContext` member of the implicit receiver.
        if (std.mem.eql(u8, name0, "coroutineContext") and b.hasOwnMember("coroutineContext")) {
            if (b.resolve("this")) |this_reg| {
                const dst = b.allocReg();
                const field = try b.module.internConst(b.allocator, .{ .String = "$coroutineContext$explicit" });
                try b.push(.{ .GetField = .{ .dst = dst, .receiver = this_reg, .field = field } });
                return dst;
            }
        }
        // Member read on `this` via GetField when the owning class declares
        // this name. A companioned class name is excepted: it is its companion
        // singleton, resolved by the classifier sentinel below, not a field.
        // A NESTED classifier of the enclosing class (`enum LayoutState` inside
        // `LayoutNode`, referenced bare) is also excepted: it is a class
        // reference, not an instance member, so it falls to the class-ref
        // lowering below (which loads the nested class and reads the enum entry).
        if (b.hasOwnMember(name0) and !classWithCompanion(b, name0) and
            !spliceSubjectHidesOwnMember(b, name0))
        {
            if (b.resolve("this")) |this_reg| {
                const dst = b.allocReg();
                const nm = try sgetterName(b, name0);
                try b.push(.{ .GetField = .{ .dst = dst, .receiver = this_reg, .field = nm } });
                return dst;
            }
            // Superclass-ctor delegation thunk: a bare own-member is a
            // companion access.
            if (b.isParamThunk()) {
                if (b.ownerClass()) |owner| {
                    const cls = b.allocReg();
                    const on = try b.module.internConst(b.allocator, .{ .String = owner });
                    try b.push(.{ .LoadGlobal = .{ .dst = cls, .name = on } });
                    const dst = b.allocReg();
                    const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
                    try b.push(.{ .GetField = .{ .dst = dst, .receiver = cls, .field = nm } });
                    return dst;
                }
            }
        }
        // A bare reference to the enclosing type's own companion object
        // (`Key` inside `interface I { companion object Key; … = Key }`)
        // resolves to that companion singleton via the qualified `I.Key`
        // form. Needed because a companion that has a supertype (e.g.
        // `companion object Key : CoroutineContext.Key<I>`) is also
        // registered as a classId under its simple name, which would
        // otherwise route the bare name to the class reference below
        // instead of the singleton.
        if (b.ownerClass()) |owner| {
            const comp_mangled: ?[]const u8 = b.module.registry.companion_singletons.get(owner);
            if (comp_mangled) |cm| {
                const simple = if (std.mem.lastIndexOfScalar(u8, cm, '$')) |i| cm[i + 1 ..] else cm;
                if (std.mem.eql(u8, simple, name0)) {
                    const sp = segments[0].span;
                    var rsegs = [_]ast.Ident{
                        .{ .name = owner, .span = sp },
                        .{ .name = name0, .span = sp },
                    };
                    const qualified = Expr{ .Path = .{ .segments = &rsegs, .span = sp } };
                    return lowerExpr(b, &qualified);
                }
            }
        }
        // Runtime-lowered anonymous-object bodies carry the exact classifier
        // identities visible at their lexical site. Their side modules do not
        // contain the program class index, so bind the classifier directly by
        // FQN after locals, captures, and receiver members have had priority.
        if (build.anonScopeClass(name0)) |class_ref| {
            const cls = b.allocReg();
            const fqn = try b.module.internConst(b.allocator, .{ .String = class_ref.fqn });
            try b.push(.{ .LoadGlobal = .{ .dst = cls, .name = fqn } });
            if (!class_ref.has_companion) return cls;
            const dst = b.allocReg();
            const sentinel = try b.module.internConst(b.allocator, .{ .String = "<class-companion-or-self>" });
            try b.push(.{ .GetField = .{ .dst = dst, .receiver = cls, .field = sentinel } });
            return dst;
        }
        // A visible top-level `const val` outranks a class binding from a
        // less-visible scope: inside ScatterMap.kt the bare `Empty` is the
        // file's compile-time constant, never kotlinx-atomicfu's file-private
        // `object Empty` that shares the simple name in the flat class table.
        // Compare scope tiers and inline the literal when the constant wins
        // (Kotlin inlines const vals at every reference).
        if (b.resolve(name0) == null and !b.knowsOuter(name0) and
            !b.hasOwnMember(name0) and !b.hasEnclosingMember(name0) and
            !build.anonCaptureBinds(name0))
        {
            if (b.module.topLevelConstLiteral(name0, b.self_package, segments[0].span.file)) |cv| {
                const ptier = b.module.topLevelPropRefTier(name0, b.self_package, segments[0].span.file) orelse 255;
                const ctier = b.module.classRefTier(name0, b.self_package, segments[0].span.file) orelse 255;
                if (ptier < ctier) {
                    orEmitAudit(b, "top_level_prop", "ConstInline", name0);
                    return try b.emitConst(cv);
                }
            }
        }
        // A NAMED companion-member import outranks a same-named class in
        // expression position (kotlinc: `import Layout.Companion.Marker`
        // binds the value `Marker` even when an `interface Marker` is in
        // scope — the classifier only matters in type position). Rewrite
        // to the qualified companion access before the class arm below
        // can capture the name.
        if (b.resolve(name0) == null and !b.knowsOuter(name0) and
            !b.hasOwnMember(name0) and !b.hasEnclosingMember(name0))
        {
            if (importCompanionRewrite(b, segments[0].span.file, name0)) |rw| {
                const sp = segments[0].span;
                const rsegs = try b.allocator.alloc(ast.Ident, rw.segs.len);
                for (rw.segs, 0..) |s2, k| rsegs[k] = .{ .name = s2, .span = sp };
                const qualified = Expr{ .Path = .{ .segments = rsegs, .span = sp } };
                return lowerExpr(b, &qualified);
            }
        }
        // A bare name that is a known class is a class reference. In a
        // receiver context a runtime receiver member shadows the
        // classifier (kotlinc: a property named like a class wins in
        // expression position), so the read decides at runtime with the
        // index-resolved class riding as the exact global arm; the
        // companion sentinel passes a member value through unchanged.
        // The flat `classId` is null when a same-simple-name class in another
        // package forced collision-mangling (both `gapbuffer` and `linkbuffer`
        // `InsertSlotsWithFixups` leave the simple name out of the index). An
        // explicit `import pkg.Outer.Name` in THIS file still names exactly one
        // of them, so treat the bare name as that class reference rather than
        // letting it fall to a by-name global read that binds first-registered.
        if ((b.module.classId(name0) != null or
            b.module.classIdExactImport(name0, segments[0].span.file) != null) and
            (!enclosingMemberShadowsClass(b, name0) or classWithCompanion(b, name0)))
        {
            const n = try b.module.internConst(b.allocator, .{ .String = name0 });
            const cls = b.allocReg();
            if (inReceiverContext(b)) {
                const this_idx = try b.recordCapture("this");
                orEmitAudit(b, "class_name_value", "LoadFromThisOrGlobal", name0);
                try b.push(.{ .LoadFromThisOrGlobal = .{
                    .dst = cls,
                    .this_idx = this_idx,
                    .name = n,
                    .class = scopedClassIdForRead(b, name0, segments[0].span.file),
                } });
            } else {
                orEmitAudit(b, "class_name_value", "LoadGlobal", name0);
                try b.push(.{ .LoadGlobal = .{
                    .dst = cls,
                    .name = n,
                    .class = scopedClassIdForRead(b, name0, segments[0].span.file),
                } });
            }
            const dst = b.allocReg();
            const sentinel = try b.module.internConst(b.allocator, .{ .String = "<class-companion-or-self>" });
            try b.push(.{ .GetField = .{ .dst = dst, .receiver = cls, .field = sentinel } });
            return dst;
        }
        // A bare builtin type name used as a qualifier. Outside any
        // receiver context no member can shadow it, so the read is a
        // static global.
        if (isBuiltinTypeName(name0)) {
            const name = try b.module.internConst(b.allocator, .{ .String = name0 });
            const dst = b.allocReg();
            if (inReceiverContext(b)) {
                const this_idx = try b.recordCapture("this");
                orEmitAudit(b, "builtin_type_name", "LoadFromThisOrGlobal", name0);
                try b.push(.{ .LoadFromThisOrGlobal = .{ .dst = dst, .this_idx = this_idx, .name = name } });
            } else {
                orEmitAudit(b, "builtin_type_name", "LoadGlobal", name0);
                try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = name } });
            }
            return dst;
        }
        // An imported member of a (possibly named) companion object →
        // rewrite to the qualified `C.MEMBER` companion access.
        if (b.resolve(name0) == null) {
            if (importCompanionRewrite(b, segments[0].span.file, name0)) |rw| {
                const sp = segments[0].span;
                const rsegs = try b.allocator.alloc(ast.Ident, rw.segs.len);
                for (rw.segs, 0..) |s, k| rsegs[k] = .{ .name = s, .span = sp };
                const qualified = Expr{ .Path = .{ .segments = rsegs, .span = sp } };
                return lowerExpr(b, &qualified);
            }
            // A member brought in bare by `import EnumOrObject.*`
            // (`import DurationUnit.*` → `MINUTES` == `DurationUnit.MINUTES`).
            // An implicit-receiver member shadows a star-import: a bare name
            // that is a member of `this` — or of any lexically enclosing
            // receiver, which is the case inside a lambda whose enclosing class
            // declares the name — resolves against that receiver, not the
            // star-imported class. `hasOwnMember` alone misses the lambda case
            // (a lambda body has no own class), so a bare `state` inside a
            // method's lambda was wrongly rewritten to `Enum.state`.
            // A same-scope top-level declaration also outranks a star-import:
            // a bare `STATE_COMPLETED` that names a top-level `val`/`fun` is
            // that declaration, not `Enum.STATE_COMPLETED` for some unrelated
            // `import Enum.*` whose enum does not even declare it (which would
            // wrongly qualify it onto the enum and read a bogus field).
            if (!b.hasEnclosingMember(name0) and !isTopLevelProp(name0) and
                !b.module.hasBareCallCandidate(name0, segments[0].span.file))
            {
                if (wildcardClassMemberRewrite(b, segments[0].span.file)) |cls| {
                    const sp = segments[0].span;
                    var rsegs = [_]ast.Ident{
                        .{ .name = cls, .span = sp },
                        .{ .name = name0, .span = sp },
                    };
                    const qualified = Expr{ .Path = .{ .segments = &rsegs, .span = sp } };
                    return lowerExpr(b, &qualified);
                }
            }
        }
        // A bare reference to a known top-level property is a global read
        // — unless a runtime implicit receiver could shadow it: kotlinc
        // resolves implicit-receiver members ahead of package-scope
        // properties, so where some class declares a member of this name
        // and a receiver is (or may be bound) in scope, the read decides
        // at runtime instead.
        // A class visible from this scope outranks a same-named top-level
        // property the file never imported (`E.serializer()` on a user
        // enum `E` is the class, never `kotlin.math.E`).
        // Only a REAL top-level property with a scope tier can lose to the
        // class; an `object` (published as a global, no property tier)
        // stays on the top-level path that loads its singleton.
        const class_over_unimported_prop = b.module.classIdIndexed(name0, b.self_package, segments[0].span.file) != null and
            (b.module.topLevelPropRefTier(name0, b.self_package, segments[0].span.file) orelse 0) >= 4;
        if (isTopLevelProp(name0) and !b.hasOwnMember(name0) and !b.hasEnclosingMember(name0) and
            !build.anonCaptureBinds(name0) and !class_over_unimported_prop and
            b.module.classIdExactImport(name0, segments[0].span.file) == null and
            !(inReceiverContext(b) and anyReceiverClassDeclares(b, name0)))
        {
            // Kotlin `const val` semantics: a reference to a visible
            // top-level compile-time constant inlines its literal value.
            // This also makes the read immune to the flat runtime global
            // table, where a same-simple-name value published by another
            // module can capture the name (androidx.collection's `Empty`
            // sentinel vs compose's `LocaleList.Empty`).
            if (b.module.topLevelConstLiteral(name0, b.self_package, segments[0].span.file)) |cv| {
                orEmitAudit(b, "top_level_prop", "ConstInline", name0);
                return try b.emitConst(cv);
            }
            // A bare read whose only declaration is an unimported
            // cross-package property is unresolved (kotlinc rejects it).
            if (b.module.topLevelPropFqn(name0)) |pfqn| {
                _ = try recordOutOfScopeRef(b, name0, segments[0].span, pfqn, b.module.topLevelPropRefTier(name0, b.self_package, segments[0].span.file));
            }
            orEmitAudit(b, "top_level_prop", "LoadGlobal", name0);
            const dst = b.allocReg();
            const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
            try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm } });
            return dst;
        }
        // Value-position bare reference to a top-level function, in a
        // context no receiver can shadow (no reachable `this`, no
        // enclosing member, no owner-class getter qualification): the
        // symbol index resolves it from the caller's scope and a unique
        // pick loads by exact FQN, so a same-simple-name function from
        // another package cannot swap in at runtime.
        if (!inReceiverContext(b) and
            !b.hasOwnMember(name0) and !b.hasEnclosingMember(name0) and !isTopLevelProp(name0))
        {
            const ref_pick = b.module.resolveBareRefIndexed(name0, b.self_package, segments[0].span.file);
            refAudit(b, name0, ref_pick);
            if (ref_pick) |fid| {
                if (b.module.funcById(fid)) |f| {
                    if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
                        if (std.mem.eql(u8, w, name0)) {
                            std.debug.print("[bare-value-arm] {s} -> {s}#{d} self_pkg={s} file={d} fn={s}\n", .{ name0, f.fqn, fid.int(), b.self_package, segments[0].span.file.int(), build.currentRealFn() orelse "-" });
                        }
                    }
                    _ = try recordOutOfScopeRef(b, name0, segments[0].span, f.fqn, b.module.bareRefTier(name0, b.self_package, segments[0].span.file));
                    const dst = b.allocReg();
                    const n = try b.module.internConst(b.allocator, .{ .String = f.fqn });
                    try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = n, .func = fid } });
                    return dst;
                }
            }
        }
        if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
            if (std.mem.eql(u8, w, name0)) {
                std.debug.print("[bare-read-pre] {s} this={} splice_recv={s} window={} in={s} own={} encl={} owner={s}\n", .{
                    name0,
                    b.resolve("this") != null,
                    b.spliceRecvTy() orelse "-",
                    b.lambda_splice_resolve != null,
                    build.currentRealFn() orelse "-",
                    b.hasOwnMember(name0),
                    b.enclosing_members.contains(name0),
                    b.ownerClass() orelse "-",
                });
                if (b.enclosing_members.contains(name0)) {
                    std.debug.print("[bare-read-encl]", .{});
                    var eit = b.enclosing_members.keyIterator();
                    var n: usize = 0;
                    while (eit.next()) |k| : (n += 1) {
                        if (n < 40) std.debug.print(" {s}", .{k.*});
                    }
                    std.debug.print(" (total {d})\n", .{n});
                }
            }
        }
        if (b.resolve("this")) |this_reg| {
            // A bare name resolving to a known top-level fn is a
            // value-position function reference; skip the GetField shortcut.
            // A known top-level *property* skips it too: the shortcut's
            // lenient field resolution would adopt outer-chain members a
            // plain extension receiver does not lexically see — the
            // runtime walk below resolves member-vs-global with the right
            // receiver scope.
            const is_known_global =
                b.module.hasBareCallCandidate(name0, segments[0].span.file) or
                isTopLevelProp(name0);
            // A name declared only by an outer class must not become a plain
            // field read on the inner `this`. Defer it to the implicit-receiver
            // walk below, which carries the declaring class in the scoped
            // getter name. The same rule handles receiver lambdas, where the
            // innermost candidate may instead be a scope-function receiver.
            const enclosing_only_member = !b.hasOwnMember(name0) and b.hasEnclosingMember(name0);
            // Directly inside an inline extension splice the body was written
            // against the DECLARATION's scope, where the bound receiver's
            // members shadow any top-level candidate: `size == 0` in
            // IntArray.isEmpty means the receiver's size no matter what
            // same-named globals the CALLER's universe declares. The GetField
            // read keeps its runtime miss-fallback, so a spliced body whose
            // receiver lacks the name still reaches the global. A NESTED
            // lambda inside the splice is excluded — its bare names must keep
            // resolving against the runtime receiver walk (the
            // `setSpliceRecvTy` contract).
            // A SPLICED receiver lambda has no runtime closure: its receiver
            // exists only as the window's bound register, so the runtime
            // receiver walk the nested-lambda contract defers to cannot see
            // it. When the window head STATICALLY declares the name, the
            // member read wins here — a bare `parameters` inside
            // `URLBuilder(...).apply { … }` is the builder's property, never
            // the top-level `parameters(builder)` function value.
            const window_recv_declares = b.lambda_splice_resolve != null and
                // The head must describe the value actually BOUND as
                // `this` (the window's own subject). A member-inline
                // splice binds its OWNER while a nested plain-lambda
                // window carries the lambda's context head — pinning a
                // GetField on that mismatch read `currentGroup` off the
                // SlotTable instead of the writer.
                b.splice_recv_from_window and blk: {
                const rh = b.spliceRecvTy() orelse break :blk false;
                const h = typeHead(std.mem.trimEnd(u8, rh, "?"));
                const hs = b.module.registry.hierarchy_shadow_names.get(h) orelse break :blk false;
                if (!hs.complete) break :blk false;
                break :blk hs.names.contains(name0);
            };
            const splice_receiver_first = (b.lambda_splice_resolve == null and b.spliceRecvTy() != null) or
                window_recv_declares;
            if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
                if (std.mem.eql(u8, w, name0)) {
                    std.debug.print("[bare-read] {s} in={s} known_global={} own={} encl={} splice_recv={s} owner={s}\n", .{
                        name0,
                        build.currentRealFn() orelse "-",
                        is_known_global,
                        b.hasOwnMember(name0),
                        b.hasEnclosingMember(name0),
                        b.spliceRecvTy() orelse "-",
                        b.ownerClass() orelse "-",
                    });
                }
            }
            // ...unless the innermost receiver is statically the very class
            // the scoped getter names. A receiver lambda inside a COMPANION
            // binds `this` to the scope-function receiver
            // (`C(r).apply { raw }` in `C.Companion.mk`), and the deferred
            // walk cannot reach it: it rides the CAPTURE chain, which in a
            // companion function holds no `C` at all, so the read missed to
            // a global that does not exist. Where the receiver's class is
            // the declaring one, the field read on it is the answer.
            const receiver_is_owner = blk: {
                if (!enclosing_only_member) break :blk false;
                // The splice head may only vouch for the resolved `this`
                // when the window actually BOUND it (splice_recv_from_window)
                // — a bare member-inline splice binds nothing, so the ambient
                // `this` is whatever the enclosing lambda holds (a suspend
                // lambda's dispatch coroutine), and pinning a field read on
                // it with the OWNER's head read `job` off the runBlocking
                // coroutine instead of the enclosing class.
                const rh = (if (b.lambda_splice_resolve == null or b.splice_recv_from_window)
                    b.spliceRecvTy()
                else
                    null) orelse b.recvTy() orelse break :blk false;
                const decl_owner = sgetterOwner(b, name0) orelse break :blk false;
                const rhh = typeHead(std.mem.trimEnd(u8, rh, "?"));
                if (rhh.len == 0) break :blk false;
                if (b.module.classIsOrExtends(rhh, decl_owner)) break :blk true;
                // The declaring owner may carry a file-collision mangle
                // (`Operations$f429`) the receiver's SOURCE-spelled head
                // never does; compare the source names too.
                if (!inline_call.rfsEnabled()) break :blk false;
                break :blk std.mem.eql(u8, rhh, stripLowerFileMangle(decl_owner)) or
                    b.module.classIsOrExtends(rhh, stripLowerFileMangle(decl_owner));
            };
            // The EXTENSION receiver's own members shadow the enclosing
            // class's: inside `fun Scope.f()` declared in `class C`, a bare
            // name both `Scope` and `C` declare is `Scope`'s — kotlinc ranks
            // implicit receivers innermost first, and `this` is the receiver.
            const recv_declares = blk: {
                const rh = b.recvTy() orelse break :blk false;
                const h = typeHead(std.mem.trimEnd(u8, rh, "?"));
                const hs = b.module.registry.hierarchy_shadow_names.get(h) orelse break :blk false;
                if (!hs.complete) break :blk false;
                break :blk hs.names.contains(name0);
            };
            if ((!is_known_global or splice_receiver_first or recv_declares) and
                (!enclosing_only_member or receiver_is_owner or recv_declares))
            {
                const dst = b.allocReg();
                const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
                // The ambient `this` may be a spliced SUBJECT whose static
                // class does not declare the name (`descriptor` inside
                // `decoder.decodeStructure(descriptor) { … }`): kotlinc
                // ranks implicit receivers by static type, so the read
                // binds the innermost subject that declares it, else the
                // receiver beneath the subjects — never the runtime
                // object's same-named private field.
                const target = subjectCorrectedBareThis(b, name0, this_reg);
                try b.push(.{ .GetField = .{ .dst = dst, .receiver = target, .field = nm } });
                return dst;
            }
            // Inside a spliced receiver lambda whose subject's STATIC class
            // does not declare the name, the enclosing class's member is
            // the binding — kotlinc ranks implicit receivers by their
            // static types, never by what the runtime object happens to
            // hold (`descriptor` inside `decoder.decodeStructure(...) { }`
            // is the serializer's, not the decoder's private field).
            const window_head_lacks = b.lambda_splice_resolve != null and b.splice_recv_from_window and blk: {
                const rh = b.spliceRecvTy() orelse break :blk false;
                const h = typeHead(std.mem.trimEnd(u8, rh, "?"));
                const hs = b.module.registry.hierarchy_shadow_names.get(h) orelse break :blk false;
                if (!hs.complete) break :blk false;
                break :blk !hs.names.contains(name0);
            };
            if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
                if (std.mem.eql(u8, w, name0)) {
                    const rh0 = b.spliceRecvTy() orelse "-";
                    const hs0 = b.module.registry.hierarchy_shadow_names.get(typeHead(std.mem.trimEnd(u8, rh0, "?")));
                    std.debug.print("[bare-read-corr] {s} window_lacks={} encl_only={} window={} from_window={} recv={s} hs={} complete={} subjects={d} known_global={} recv_declares={}\n", .{ name0, window_head_lacks, enclosing_only_member, b.lambda_splice_resolve != null, b.splice_recv_from_window, rh0, hs0 != null, if (hs0) |h| h.complete else false, b.subject_binds.items.len, is_known_global, recv_declares });
                }
            }
            if ((enclosing_only_member or window_head_lacks) and !recv_declares and !is_known_global) blk: {
                const oc = b.ownerClass() orelse break :blk;
                const ocid = b.module.classIdIndexed(oc, b.self_package, segments[0].span.file) orelse
                    b.module.classId(oc) orelse break :blk;
                if (!b.module.classHierarchyDeclaresMember(ocid, name0)) break :blk;
                const corrected = subjectCorrectedBareThis(b, name0, this_reg);
                if (corrected == this_reg) break :blk;
                orEmitAudit(b, "subject_corrected_read", "GetField", name0);
                const dst = b.allocReg();
                const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
                try b.push(.{ .GetField = .{ .dst = dst, .receiver = corrected, .field = nm } });
                return dst;
            }
        }
        // Outside any receiver context no member can shadow the name, so
        // the read is a static global (kotlinc rejects resolving it
        // against a caller's receiver).
        if (!inReceiverContext(b)) {
            orEmitAudit(b, "bare_name_fallthrough", "LoadGlobal", name0);
            const dst = b.allocReg();
            // A RENAMED import binds this spelling to another declaration
            // (`import kotlin.coroutines.coroutineContext as currentContext`).
            // A call and a classifier already resolve through the alias; a
            // bare PROPERTY read reached the runtime as the spelled name and
            // found nothing. Resolve it at the emission only, so the spelling
            // the source wrote is what every diagnostic still reports.
            const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
            try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm } });
            return dst;
        }
        const this_idx = try b.recordCapture("this");
        const dst = b.allocReg();
        const name = try sgetterName(b, name0);
        // The index's unique pick rides as the exact global arm; the
        // runtime member probe still runs first, and a runtime-scoped
        // shadowing capture re-routes to the name lookup.
        const ref_pick = b.module.resolveBareRefIndexed(name0, b.self_package, segments[0].span.file);
        orEmitAudit(b, "bare_name_fallthrough", "LoadFromThisOrGlobal", name0);
        try b.push(.{ .LoadFromThisOrGlobal = .{
            .dst = dst,
            .this_idx = this_idx,
            .name = name,
            .func = ref_pick,
        } });
        return dst;
    }

    // Multi-segment paths. Try the full FQN against the host first.
    if (segments.len >= 2 and
        isPackageHead(segments[0].name) and
        headIsPackage(b, segments[0].name) and
        b.resolve(segments[0].name) == null and
        !b.knowsOuter(segments[0].name) and
        !b.hasEnclosingMember(segments[0].name) and
        b.module.classId(segments[0].name) == null)
    {
        // The const pool stores the slice by reference, so the joined FQN
        // must live for the module's lifetime — let the module allocator
        // own it rather than freeing it here.
        const fqn = try joinSegments(b.allocator, segments);
        // Ride the exact class id of the longest FQN prefix that names a class
        // so the runtime binds that declaration rather than re-resolving the
        // tail by simple name (two packages with a same-simple-name
        // `Operation.Ins` would otherwise both bind the first-registered one).
        if (try emitFqnWithClassPrefix(b, fqn)) |r| return r;
        const dst = b.allocReg();
        const n = try b.module.internConst(b.allocator, .{ .String = fqn });
        try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = n } });
        // A fully-qualified class-with-companion in value position resolves to
        // its companion singleton (Kotlin: `C` yields `C.Companion`), the same
        // forwarding the bare-name arm applies. Without it `pkg.C` loaded the
        // class value while bare `C` loaded the companion, so `pkg.C === C`
        // was false and `context[ContinuationInterceptor]` (an interface with a
        // named companion Key) missed the dispatcher element. The
        // `<class-companion-or-self>` sentinel returns the companion when one
        // exists and the class/object value otherwise, so a plain object or a
        // companion-less class is unaffected.
        const fqn_simple = if (std.mem.lastIndexOfScalar(u8, fqn, '.')) |d| fqn[d + 1 ..] else fqn;
        if (classWithCompanion(b, fqn_simple) and b.module.funcIdByFqn(fqn) == null) {
            const comp = b.allocReg();
            const sentinel = try b.module.internConst(b.allocator, .{ .String = "<class-companion-or-self>" });
            try b.push(.{ .GetField = .{ .dst = comp, .receiver = dst, .field = sentinel } });
            return comp;
        }
        return dst;
    }

    const first = segments[0];
    var cur: Reg = undefined;
    if (b.resolve(first.name)) |r| {
        cur = r;
    } else if (inReceiverContext(b)) {
        // Unresolved head: route through `this` / the enclosing receiver.
        // A head naming a known class carries the index-resolved class as
        // the exact global arm (a runtime receiver member still shadows
        // it, innermost first).
        const this_idx = try b.recordCapture("this");
        const dst = b.allocReg();
        const n = try b.module.internConst(b.allocator, .{ .String = first.name });
        orEmitAudit(b, "multi_seg_head", "LoadFromThisOrGlobal", first.name);
        try b.push(.{ .LoadFromThisOrGlobal = .{
            .dst = dst,
            .this_idx = this_idx,
            .name = n,
            .class = b.module.classIdIndexed(first.name, b.self_package, first.span.file),
        } });
        cur = dst;
    } else {
        // No receiver context: the head is a static global.
        const dst = b.allocReg();
        const n = try b.module.internConst(b.allocator, .{ .String = first.name });
        orEmitAudit(b, "multi_seg_head", "LoadGlobal", first.name);
        try b.push(.{ .LoadGlobal = .{
            .dst = dst,
            .name = n,
            .class = b.module.classIdIndexed(first.name, b.self_package, first.span.file),
        } });
        cur = dst;
    }
    for (segments[1..]) |seg| {
        const next = b.allocReg();
        const field = try b.module.internConst(b.allocator, .{ .String = seg.name });
        try b.push(.{ .GetField = .{ .dst = next, .receiver = cur, .field = field } });
        cur = next;
    }
    return cur;
}

/// The nearest lexical class whose hierarchy declares `name`. A lambda keeps
/// its enclosing class as `ownerClass`, while a lifted inner class reaches its
/// outer classes through `enclosing_class`; consulting both gives a scoped
/// getter the class that actually contributes the bare property.
/// The source-level name behind a file-collision mangle (`X$f12` -> `X`).
fn stripLowerFileMangle(n: []const u8) []const u8 {
    const i = std.mem.lastIndexOfScalar(u8, n, '$') orelse return n;
    if (i + 2 >= n.len or n[i + 1] != 'f') return n;
    for (n[i + 2 ..]) |c| {
        if (c < '0' or c > '9') return n;
    }
    return n[0..i];
}

fn sgetterOwner(b: *const FuncBuilder, name: []const u8) ?[]const u8 {
    const lexical_owner = b.ownerClass() orelse return null;
    var owner: ?[]const u8 = lexical_owner;
    var hops: usize = 0;
    while (owner) |o| : (hops += 1) {
        if (hops > 32) break;
        const own = std.mem.eql(u8, o, lexical_owner) and b.hasOwnMember(name);
        const hierarchy_has = if (b.module.registry.hierarchy_shadow_names.get(o)) |hierarchy|
            hierarchy.names.contains(name)
        else
            false;
        if (own) return o;
        if (hierarchy_has) return o;
        owner = b.module.registry.enclosing_class.get(o);
    }
    return lexical_owner;
}

/// Intern the scope-qualified getter field name `$sgetter$<owner>\u{1f}<name>`
/// when an enclosing class is known, else the plain name.
fn sgetterName(b: *FuncBuilder, name: []const u8) Allocator.Error!ConstId {
    if (sgetterOwner(b, name)) |owner| {
        // The const pool stores the slice by reference, so the buffer must
        // live for the module's lifetime — let the module allocator own it
        // rather than freeing it here (which would leave a dangling field
        // name read back at dispatch time).
        const qual = try std.fmt.allocPrint(b.allocator, "$sgetter${s}\u{1f}{s}", .{ owner, name });
        return b.module.internConst(b.allocator, .{ .String = qual });
    }
    return b.module.internConst(b.allocator, .{ .String = name });
}

const ImportRewrite = struct { segs: []const []const u8 };

/// Resolve a bare name imported via `import a.b.C…MEMBER` into the qualified
/// access path starting at the rightmost segment naming a class this module
/// declares (dropping the leading package). Intermediate segments between the
/// class and the member are preserved (`import Outer.State.Idle` → the nested
/// `Outer.State.Idle`), EXCEPT an explicit `Companion` hop, which is dropped
/// because a companion member is reached through the class itself
/// (`import X.Companion.member` → `X.member`). Returns null when the path names
/// no declared class, or the class is the leaf (a bare type reference).
fn importCompanionRewrite(b: *FuncBuilder, file: ir.FileId, name: []const u8) ?ImportRewrite {
    const segs = b.module.importAliasIn(file, name) orelse return null;
    // Find the rightmost segment naming a class the module declares (skips the
    // leading package), then extend left across any enclosing-class chain so the
    // path starts at the OUTERMOST (top-level, globally loadable) class — a bare
    // nested class name (`LayoutState`) is not itself loadable, but the qualified
    // `Outer.LayoutState.Idle` resolves the nested classifier then the entry.
    // The scan excludes the LEAF segment: the leaf is the imported member,
    // and a same-named CLASS elsewhere in scope must not capture it —
    // `import Layout.Companion.Marker` next to an `interface Marker` still
    // rewrites to `Layout.Marker`. (A bare `import a.b.SomeClass` type
    // reference has no member segment and simply finds no class here.)
    var cls_idx: ?usize = null;
    var i = segs.len - 1;
    while (i > 0) {
        i -= 1;
        if (b.module.classId(segs[i]) != null) {
            cls_idx = i;
            break;
        }
    }
    const ci = cls_idx orelse return null;

    var start = ci;
    while (start > 0 and b.module.classId(segs[start - 1]) != null) start -= 1;

    // Keep the leading package segments when the class named by the import's
    // FQN is NOT the one its simple name resolves to in the flat class index
    // — either the simple name was collision-mangled out (two packages declare
    // a same-simple-name nested member, gapbuffer vs linkbuffer `Operation`)
    // or it resolves to a different, first-registered declaration. Dropping the
    // package would bind that wrong one; the full `pkg.Outer.Member` path
    // resolves the exact declaration the import named.
    if (start > 0) {
        const fqn_parts = segs[0 .. ci + 1];
        const fqn = std.mem.join(b.allocator, ".", fqn_parts) catch return null;
        if (b.module.classIdByFqn(fqn)) |fqn_cid| {
            const simple_cid = b.module.classId(segs[ci]);
            if (simple_cid == null or simple_cid.?.int() != fqn_cid.int()) start = 0;
        }
    }

    const last = segs.len - 1;
    var out = b.allocator.alloc([]const u8, segs.len - start) catch return null;
    var n: usize = 0;
    var j = start;
    while (j < segs.len) : (j += 1) {
        // Drop an intermediate `Companion` hop — `X.member` resolves the
        // companion member — but keep a nested classifier (`Outer.State`).
        if (j != last and std.mem.eql(u8, segs[j], "Companion")) continue;
        out[n] = segs[j];
        n += 1;
    }
    return .{ .segs = out[0..n] };
}

/// A bare name brought into scope by `import EnumOrObject.*` resolves to that
/// class's member (`import DurationUnit.*` makes `MINUTES` mean
/// `DurationUnit.MINUTES`). Returns the simple class name to qualify with, or
/// null when no wildcard import targets a declared class with this surface.
/// The runtime `GetField` resolves the enum entry / companion member exactly as
/// it does for the written-out `Class.name`.
fn wildcardClassMemberRewrite(b: *FuncBuilder, file: ir.FileId) ?[]const u8 {
    const list = b.module.registry.import_wildcards.get(file) orelse return null;
    for (list.items) |path| {
        // The wildcard target names a class (enum / object) rather than a
        // package: its members are visible under their bare names. Match the
        // full FQN first, then the simple tail.
        if (b.module.classIdByFqn(path) != null) return lastPathSegment(path);
        const tail = lastPathSegment(path);
        if (b.module.classId(tail) != null) return tail;
    }
    return null;
}

fn lastPathSegment(path: []const u8) []const u8 {
    if (std.mem.lastIndexOfScalar(u8, path, '.')) |dot| return path[dot + 1 ..];
    return path;
}

fn isBuiltinTypeName(name: []const u8) bool {
    const names = [_][]const u8{
        "Int",   "Long",    "Short",  "Byte", "Double", "Float",
        "Char",  "Boolean", "String", "UInt", "ULong",  "UShort",
        "UByte",
    };
    for (names) |n| {
        if (std.mem.eql(u8, name, n)) return true;
    }
    return false;
}

fn lowerStringTemplate(b: *FuncBuilder, parts: []const ast.StringPart) Allocator.Error!Reg {
    var cur = try b.emitConst(.{ .String = "" });
    for (parts) |part| {
        const piece = switch (part) {
            .Text => |s| try b.emitConst(.{ .String = s }),
            .ShortInterp => |ident| try lowerShortInterp(b, ident),
            .Interp => |e| try lowerExpr(b, e),
        };
        const dst = b.allocReg();
        try b.push(.{ .BinOp = .{ .dst = dst, .op = .StringConcat, .lhs = cur, .rhs = piece } });
        cur = dst;
    }
    return cur;
}

fn lowerShortInterp(b: *FuncBuilder, ident: ast.Ident) Allocator.Error!Reg {
    // `$this` denotes the receiver itself — `this` is a keyword, never a
    // member or global name — so it lowers exactly like a bare `this`
    // expression: the bound `this`, or the captured slot in a lambda body.
    if (std.mem.eql(u8, ident.name, "this")) {
        if (b.resolve("this")) |r| return r;
        return b.loadCaptureHoisted("this");
    }
    // `"… $x …"` where `x` is a `var x by D` local reads THROUGH the delegate,
    // exactly as a bare `x` does.
    if (try lowerDelegateRead(b, ident.name)) |r| return r;
    if (b.resolve(ident.name)) |r| {
        if (b.isBoxed(ident.name)) {
            const dst = b.allocReg();
            try b.push(.{ .CellGet = .{ .dst = dst, .cell = r } });
            return dst;
        }
        return r;
    }
    if (b.knowsOuter(ident.name)) {
        const cell = try b.loadCaptureHoisted(ident.name);
        if (b.isBoxed(ident.name)) {
            const dst = b.allocReg();
            try b.push(.{ .CellGet = .{ .dst = dst, .cell = cell } });
            return dst;
        }
        return cell;
    }
    // A renamed file-private top-level property (`"$prefix.Derived"` beside
    // another file's same-named private `prefix`) reads its per-file mangled
    // global exactly as a bare reference does.
    if (filePrivatePropRename(b, ident.name, ident.span.file.int())) |renamed| {
        var segs = [_]ast.Ident{.{ .name = renamed, .span = ident.span }};
        const path = Expr{ .Path = .{ .segments = &segs, .span = ident.span } };
        return lowerExpr(b, &path);
    }
    if (b.hasOwnMember(ident.name) and b.resolve("this") != null) {
        const this_reg = b.resolve("this").?;
        const dst = b.allocReg();
        const nm = try b.module.internConst(b.allocator, .{ .String = ident.name });
        try b.push(.{ .GetField = .{ .dst = dst, .receiver = this_reg, .field = nm } });
        return dst;
    }
    if (b.resolve("this")) |this_reg| {
        const dst = b.allocReg();
        const n = try b.module.internConst(b.allocator, .{ .String = ident.name });
        try b.push(.{ .GetField = .{ .dst = dst, .receiver = this_reg, .field = n } });
        return dst;
    }
    const n = try b.module.internConst(b.allocator, .{ .String = ident.name });
    const dst = b.allocReg();
    if (inReceiverContext(b)) {
        const this_idx = try b.recordCapture("this");
        orEmitAudit(b, "short_interp", "LoadFromThisOrGlobal", ident.name);
        try b.push(.{ .LoadFromThisOrGlobal = .{ .dst = dst, .this_idx = this_idx, .name = n } });
    } else {
        orEmitAudit(b, "short_interp", "LoadGlobal", ident.name);
        try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = n } });
    }
    return dst;
}

/// `Member` lowering: safe member access (`recv?.x`), `super.<prop>`, FQN
/// flatten, explicit `coroutineContext`, and the plain GetField.
fn lowerMember(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const m = expr.Member;
    const receiver = m.receiver;
    const name = m.name;

    if (m.safe) {
        // `recv?.x` — null-guard. An explicit `recv?.coroutineContext` is a
        // literal member read exactly like the non-safe arm below: without the
        // sentinel the runtime's suspend-implicit redirect served the AMBIENT
        // coroutine's context instead of the receiver's own.
        const recv = try lowerReceiver(b, receiver);
        const null_r = try b.emitConst(.Null);
        const is_null = b.allocReg();
        try b.push(.{ .BinOp = .{ .dst = is_null, .op = .Eq, .lhs = recv, .rhs = null_r } });
        const then_b = try b.allocBlock();
        const else_b = try b.allocBlock();
        const join = try b.allocBlock();
        const dst = b.allocReg();
        b.terminate(.{ .Branch = .{ .cond = is_null, .t = then_b, .f = else_b } });
        b.switchTo(then_b);
        const n = try b.emitConst(.Null);
        try b.push(.{ .Move = .{ .dst = dst, .src = n } });
        b.terminate(.{ .Goto = join });
        b.switchTo(else_b);
        const field_name: []const u8 = if (std.mem.eql(u8, name.name, "coroutineContext"))
            "$coroutineContext$explicit"
        else
            name.name;
        const field = try b.module.internConst(b.allocator, .{ .String = field_name });
        const v = b.allocReg();
        try b.push(.{ .GetField = .{ .dst = v, .receiver = recv, .field = field } });
        try b.push(.{ .Move = .{ .dst = dst, .src = v } });
        b.terminate(.{ .Goto = join });
        b.switchTo(join);
        return dst;
    }

    // `super.<prop>` — dispatch its getter via the parent chain.
    if (receiver.* == .Super) {
        if (try resolveSuperThisReg(b)) |this_reg| {
            if (b.ownerClass()) |owner| {
                const sup = receiver.Super;
                const dst = b.allocReg();
                const nm = try b.module.internConst(b.allocator, .{ .String = name.name });
                const oc = try b.module.internConst(b.allocator, .{ .String = owner });
                const qual_const = try superQualifier(b, sup.qualifier, sup.label);
                const args_start = b.allocReg();
                try b.push(.{ .CallSuper = .{
                    .dst = dst,
                    .receiver = this_reg,
                    .owner_class = oc,
                    .qualifier = qual_const,
                    .name = nm,
                    .args = args_start,
                    .n_args = 0,
                    .arg_names = &.{},
                } });
                return dst;
            }
        }
    }

    // Flatten chains like `kotlin.math.PI` into a single FQN lookup.
    if (try collectDottedFqn(b.allocator, expr)) |fqn| {
        defer b.allocator.free(fqn);
        const head = firstSegment(fqn);
        // A real package root (`kotlin.math.PI`) flattens to an FQN LoadGlobal
        // even inside a class method; only an ambiguous head defers to a member
        // when `this` is in scope. Mirrors the call path (lowerFqnGlobalCall).
        const head_is_real_pkg = isPkgRoot(head);
        if (isPackageHead(head) and
            headIsPackage(b, head) and
            b.resolve(head) == null and
            !b.knowsOuter(head) and
            !b.hasEnclosingMember(head) and
            b.module.classId(head) == null and
            (head_is_real_pkg or b.resolve("this") == null))
        {
            if (try emitFqnWithClassPrefix(b, fqn)) |r| return r;
            const dst = b.allocReg();
            const n = try b.module.internConst(b.allocator, .{ .String = fqn });
            try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = n } });
            // A fully-qualified class-with-companion in value position yields its
            // companion singleton (Kotlin: `C` yields `C.Companion`), matching the
            // bare-name arm. Without it `pkg.C` loaded the class value while bare
            // `C` loaded the companion, so `pkg.C === C` was false and
            // `context[ContinuationInterceptor]` (an interface with a named
            // companion Key) missed the dispatcher element. The
            // `<class-companion-or-self>` sentinel returns the companion when one
            // exists and the class/object value otherwise, leaving a plain object
            // or a companion-less class unchanged.
            const fqn_simple = if (std.mem.lastIndexOfScalar(u8, fqn, '.')) |d| fqn[d + 1 ..] else fqn;
            // A same-FQN factory function (`kotlinx.coroutines.Job` is both an
            // interface with a companion `Key` AND a `fun Job()` factory) keeps
            // the class value: as a call callee it is the factory, and a bare
            // reference reaches its companion through explicit `.Key`. Only a
            // companioned classifier with no such function forwards.
            if (classWithCompanion(b, fqn_simple) and b.module.funcIdByFqn(fqn) == null) {
                const comp = b.allocReg();
                const sentinel = try b.module.internConst(b.allocator, .{ .String = "<class-companion-or-self>" });
                try b.push(.{ .GetField = .{ .dst = comp, .receiver = dst, .field = sentinel } });
                return comp;
            }
            return dst;
        }
    }

    // An explicit `recv.coroutineContext` is a literal field read.
    if (std.mem.eql(u8, name.name, "coroutineContext")) {
        const recv = try lowerReceiver(b, receiver);
        const dst = b.allocReg();
        const field = try b.module.internConst(b.allocator, .{ .String = "$coroutineContext$explicit" });
        try b.push(.{ .GetField = .{ .dst = dst, .receiver = recv, .field = field } });
        return dst;
    }

    // `c.code` on a STATIC Char receiver is the scalar identity read â
    // emit it as `c - NUL` (Char minus Char is Int in Kotlin, and the
    // subtrahend is code zero), a plain BinOp instead of a dynamic field
    // read: it stays in fused loop regions and skips the runtime
    // extension-getter dispatch per read.
    if (std.mem.eql(u8, name.name, "code")) {
        const recv_head: ?[]const u8 = blk: {
            const t = staticExprTypeRef(b, receiver) catch null;
            var tr = t orelse break :blk null;
            defer tr.deinit(b.allocator);
            if (tr.nullable) break :blk null;
            break :blk if (std.mem.eql(u8, typeHead(tr.name), "Char")) "Char" else null;
        };
        if (recv_head != null) {
            const recv = try lowerReceiver(b, receiver);
            const zero = try b.emitConst(.{ .Char = 0 });
            const dst = b.allocReg();
            try b.push(.{ .BinOp = .{ .dst = dst, .op = .Sub, .lhs = recv, .rhs = zero } });
            return dst;
        }
    }

    // Static-type-directed extension-property read. When the receiver's
    // STATIC type resolves `name` to an in-scope member-extension property
    // rather than a member of that type, Kotlin runs the extension getter —
    // a same-named stored field the runtime object happens to carry is
    // irrelevant. Emit an extension-read marker so dispatch resolves the
    // extension property instead of that accidental field.
    if (try staticExtPropReadField(b, receiver, name.name)) |marker| {
        const recv = try lowerReceiver(b, receiver);
        const dst = b.allocReg();
        try b.push(.{ .GetField = .{ .dst = dst, .receiver = recv, .field = marker } });
        return dst;
    }

    // Explicit `this.x` where the enclosing class declares `x` as a private
    // SHADOW of a supertype's same-name stored property reads ITS OWN
    // owner-mangled cell, matching the bare-name read and the shadow write.
    if (receiver.* == .This and receiver.This.qualifier == null) {
        if (b.ownerClass()) |owner| {
            var kb: [256]u8 = undefined;
            if (std.fmt.bufPrint(&kb, "{s}\u{1f}{s}", .{ owner, name.name })) |probe| {
                if (b.module.registry.private_shadow_props.getKey(probe)) |key| {
                    const trecv = try lowerReceiver(b, receiver);
                    const tdst = b.allocReg();
                    const tfield = try b.module.internConst(b.allocator, .{ .String = key });
                    try b.push(.{ .GetField = .{ .dst = tdst, .receiver = trecv, .field = tfield } });
                    return tdst;
                }
            } else |_| {}
        }
    }

    const recv = try lowerReceiver(b, receiver);
    const dst = b.allocReg();
    const field = try b.module.internConst(b.allocator, .{ .String = name.name });
    try b.push(.{ .GetField = .{ .dst = dst, .receiver = recv, .field = field } });
    return dst;
}

/// The statically known type-head of a bare single-name receiver: a typed
/// local/param, else an enclosing-class member (property / constructor-
/// parameter property) walked over the owner's supertype chain. Null when the
/// name has no statically known type here (an untyped local, an outer
/// capture, or a name the enclosing class does not declare as a typed member).
/// The full declared TYPE of a bare name that reads a property of the
/// enclosing class or the extension receiver — the argument-carrying half of
/// `staticBareReceiverType`. Only recorded for a property whose declared
/// type has arguments that name real classes, so a `null` here simply means
/// the head-only answer stands.
/// A class property's FULL declared type, following the supertype chain the
/// head lookup follows.
fn propTypeRefOn(b: *const FuncBuilder, owner: []const u8, name: []const u8) ?ir.TypeRef {
    if (b.module.registry.class_prop_type_refs.get(.{ .a = owner, .b = name })) |t| return t;
    const chain: []const []const u8 = b.module.registry.class_super_names.get(owner) orelse &.{};
    for (chain) |cls| {
        if (b.module.registry.class_prop_type_refs.get(.{ .a = cls, .b = name })) |t| return t;
    }
    return null;
}

/// A declared property type with the OWNER's type parameters replaced by the
/// receiver's own type arguments. Null when any argument stays a parameter —
/// a partial answer says nothing the head does not already say.
fn substitutedPropType(
    b: *FuncBuilder,
    owner: []const u8,
    recv_ty: ir.TypeRef,
    declared: ir.TypeRef,
) ?ir.TypeRef {
    if (declared.args.len == 0) return declared;
    if (recv_ty.args.len == 0) return null;
    const cid = b.module.uniqueClassIdBySimpleName(owner) orelse
        b.module.classIdByFqn(owner) orelse return null;
    if (cid.int() >= b.module.classes.items.len) return null;
    const tps = b.module.classes.items[cid.int()].type_params;
    if (tps.len == 0 or tps.len != recv_ty.args.len) return null;
    var buf: [4]ir.TypeRef = undefined;
    if (declared.args.len > buf.len) return null;
    for (declared.args, 0..) |darg, i| {
        const dh = typeHead(std.mem.trimEnd(u8, darg.name, "?"));
        var found = false;
        for (tps, 0..) |tp, j| {
            if (!std.mem.eql(u8, tp, dh)) continue;
            const sub = recv_ty.args[j];
            if (sub.name.len == 0 or std.mem.eql(u8, sub.name, "*")) return null;
            if (bareTypeParamHead(sub.name)) return null;
            buf[i] = sub;
            found = true;
            break;
        }
        if (!found) {
            if (bareTypeParamHead(darg.name)) return null;
            buf[i] = darg;
        }
    }
    const owned = b.allocator.dupe(ir.TypeRef, buf[0..declared.args.len]) catch return null;
    return ir.TypeRef{ .name = declared.name, .nullable = declared.nullable, .args = owned };
}

/// A bare type-parameter head is not a property owner; its declared BOUND
/// is. `entries` inside `<K, V, M : Map<out K, V>> M.onEachIndexed` reads a
/// Map property, so the owner lookups chase `M -> Map`.
fn boundOwnerHead(b: *const FuncBuilder, head: []const u8) []const u8 {
    if (b.typeParamBoundRef(head)) |bref| {
        var h = std.mem.trimEnd(u8, bref.name, "?");
        if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
        if (h.len != 0) return typeHead(h);
    }
    return head;
}

fn staticBareReceiverTypeRef(b: *const FuncBuilder, recv_name: []const u8) ?ir.TypeRef {
    const self_shadowed = init_self_name != null and std.mem.eql(u8, init_self_name.?, recv_name);
    if (!self_shadowed) {
        if (b.resolve(recv_name) != null) return null;
        if (b.knowsOuter(recv_name)) return null;
    }
    const owner = b.ownerClass() orelse blk: {
        const head = b.recvTy() orelse b.spliceRecvTy() orelse return null;
        break :blk boundOwnerHead(b, typeHead(std.mem.trimEnd(u8, head, "?")));
    };
    if (b.module.registry.class_prop_type_refs.get(.{ .a = owner, .b = recv_name })) |t| return t;
    const chain: []const []const u8 = b.module.registry.class_super_names.get(owner) orelse &.{};
    for (chain) |cls| {
        if (b.module.registry.class_prop_type_refs.get(.{ .a = cls, .b = recv_name })) |t| return t;
    }
    return null;
}

pub fn staticBareReceiverType(b: *const FuncBuilder, recv_name: []const u8) ?[]const u8 {
    // Inside `val writer = writer`'s initializer the local's own name is
    // free (recorded at the decl), so the reference is the enclosing
    // member, never the shadow being declared.
    const self_shadowed = init_self_name != null and std.mem.eql(u8, init_self_name.?, recv_name);
    // A local/param binding shadows an enclosing member of the same name.
    if (!self_shadowed) {
        if (b.resolve(recv_name) != null) return b.localDeclType(recv_name);
        if (b.knowsOuter(recv_name)) return null;
    }
    // The enclosing class, else the EXTENSION RECEIVER — a bare name inside
    // `fun UByteArray.indices()` is a member of the receiver, and a top-level
    // extension has no enclosing class at all, so the search stopped there.
    const tr = if (runtime.envOnce("KLIO_EXT_TRACE")) |w| std.mem.eql(u8, w, recv_name) else false;
    const owner = b.ownerClass() orelse blk: {
        if (std.mem.eql(u8, runtime.envOnce("KLIO_EXT_RECV_PROP") orelse "1", "0")) return null;
        // The splice-receiver hint serves the same role inside an inline
        // extension splice, where the body's builder has no recvTy of its
        // own.
        const head = b.recvTy() orelse b.spliceRecvTy() orelse {
            if (tr) std.debug.print("[sbrt] {s}: no owner, no recvTy\n", .{recv_name});
            return null;
        };
        break :blk boundOwnerHead(b, typeHead(std.mem.trimEnd(u8, head, "?")));
    };
    if (tr) std.debug.print("[sbrt] {s}: owner={s} head={?s} ext={?s}\n", .{ recv_name, owner, propTypeHeadOn(b, owner, recv_name), extPropReturnHead(b, owner, recv_name) });
    if (propTypeHeadOn(b, owner, recv_name)) |h| return h;
    if (extPropReturnHead(b, owner, recv_name)) |h| return h;
    // A receiver lambda rebinds `this`, so a bare name inside it can be the
    // RECEIVER's member rather than the enclosing class's:
    // `Duration(raw).apply { … value … }` sits in Duration's companion, whose
    // own surface has no `value` at all. Consulted only after the enclosing
    // class declines, so no answer this walk already gives can change.
    const recv_head = b.recvTy() orelse b.spliceRecvTy() orelse b.enclosingRecvTy() orelse return null;
    const rh = boundOwnerHead(b, typeHead(std.mem.trimEnd(u8, recv_head, "?")));
    if (rh.len == 0 or std.mem.eql(u8, rh, owner)) return null;
    if (propTypeHeadOn(b, rh, recv_name)) |h| return h;
    return extPropReturnHead(b, rh, recv_name);
}

/// The declared return head of an EXTENSION PROPERTY named `name` on
/// `head` (or its builtin/declared supertypes): the lowered getter follows
/// the stable `__ext_get_<Head>_<name>` naming contract, and its return
/// type is the bare read's static type — `indices` inside a `ShortArray`
/// extension body is an `IntRange`, so the desugared `for (i in indices)`
/// iterator call binds.
fn extPropReturnHead(b: *const FuncBuilder, head: []const u8, name: []const u8) ?[]const u8 {
    if (extPropDeclHead(b, head, name)) |h| return h;
    if (extPropGetterReturn(b, head, name)) |h| return h;
    for (applicability.builtinSupersOf(head)) |sup| {
        if (extPropDeclHead(b, sup, name)) |h| return h;
        if (extPropGetterReturn(b, sup, name)) |h| return h;
    }
    if (b.module.registry.class_super_names.get(head)) |chain| {
        for (chain) |sup| {
            if (extPropDeclHead(b, applicability.simpleName(sup), name)) |h| return h;
            if (extPropGetterReturn(b, applicability.simpleName(sup), name)) |h| return h;
        }
    }
    return null;
}

/// The declaration-scan channel: `(receiver head, name)` recorded before
/// any body lowers, so the answer exists while the declaring library is
/// itself still lowering. The head must still name a class to be useful
/// dispatch evidence.
fn extPropDeclHead(b: *const FuncBuilder, head: []const u8, name: []const u8) ?[]const u8 {
    const raw = b.module.registry.ext_prop_type_heads.get(.{ .a = head, .b = name }) orelse return null;
    var h = std.mem.trimEnd(u8, raw, "?");
    if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
    if (h.len == 0 or std.mem.eql(u8, h, "Unit")) return null;
    const cid = (if (std.mem.indexOfScalar(u8, h, '.') != null)
        b.module.classIdByFqn(h)
    else
        b.module.uniqueClassIdBySimpleName(typeHead(h)));
    if (cid == null) return null;
    return h;
}

fn extPropGetterReturn(b: *const FuncBuilder, head: []const u8, name: []const u8) ?[]const u8 {
    const tr = if (runtime.envOnce("KLIO_EXT_TRACE")) |w| std.mem.eql(u8, w, name) else false;
    var buf: [160]u8 = undefined;
    const gname = std.fmt.bufPrint(&buf, "__ext_get_{s}_{s}", .{ head, name }) catch return null;
    const fids = b.module.funcsBySimpleName(gname);
    if (tr) std.debug.print("[extpget] gname={s} fids={d}\n", .{ gname, fids.len });
    if (fids.len == 0) return null;
    const f = b.module.funcById(fids[0]) orelse return null;
    var h = std.mem.trimEnd(u8, f.return_ty.name, "?");
    if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
    if (tr) std.debug.print("[extpget] ret head={s}\n", .{h});
    if (h.len == 0 or std.mem.eql(u8, h, "Unit")) return null;
    const cid = (if (std.mem.indexOfScalar(u8, h, '.') != null)
        b.module.classIdByFqn(h)
    else
        b.module.uniqueClassIdBySimpleName(typeHead(h)));
    if (tr) std.debug.print("[extpget] cid={?}\n", .{cid});
    if (cid == null) return null;
    return h;
}

fn propTypeHeadOn(b: *const FuncBuilder, owner: []const u8, name: []const u8) ?[]const u8 {
    const heads = b.module.registry.class_prop_type_heads;
    if (heads.get(.{ .a = owner, .b = name })) |h| return h;
    const chain: []const []const u8 = b.module.registry.class_super_names.get(owner) orelse &.{};
    for (chain) |cls| {
        if (heads.get(.{ .a = cls, .b = name })) |h| return h;
    }
    // A property typed only by its initializer call (`val json = Json {
    // … }`): the class registration could not see a pack's factory or
    // class, so the head is read from the initializer here, where every
    // declaration is registered.
    if (propInitCallHead(b, owner, name)) |h| return h;
    for (chain) |cls| {
        if (propInitCallHead(b, cls, name)) |h| return h;
    }
    // A runtime anon-object member body's own property heads travel in the
    // installed snapshot — the synthesized class has no registry entries.
    return build.anonPropHead(owner, name);
}

/// The class a member property's initializer call names: a constructor
/// (`Json { }` resolves to the class of that name) or a plain function
/// whose same-named overloads agree on a declared, concrete return head.
fn propInitCallHead(b: *const FuncBuilder, owner: []const u8, name: []const u8) ?[]const u8 {
    const p = inline_state.memberPropAst(owner, name) orelse {
        if (std.c.getenv("KLIO_PROPHEAD_TRACE") != null) std.debug.print("[prophead-lazy] no ast for {s}.{s}\n", .{ owner, name });
        return null;
    };
    if (std.c.getenv("KLIO_PROPHEAD_TRACE") != null) std.debug.print("[prophead-lazy] {s}.{s} ty={} init={}\n", .{ owner, name, p.ty != null, p.init != null });
    if (p.ty != null) return null;
    const init = p.init orelse return null;
    if (init != .Call) return null;
    const callee = init.Call.callee;
    if (callee.* != .Path or callee.Path.segments.len != 1) return null;
    const nm = callee.Path.segments[0].name;
    if (nm.len == 0) return null;
    if (std.ascii.isUpper(nm[0]) and b.module.classId(nm) != null) return nm;
    var agreed: ?[]const u8 = null;
    for (b.module.funcsBySimpleName(nm)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) continue;
        var head = std.mem.trimEnd(u8, f.return_ty.name, "?");
        if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
        if (head.len == 0 or std.mem.eql(u8, head, "Unit") or (head.len <= 2 and std.ascii.isUpper(head[0]))) return null;
        if (agreed) |g| {
            if (!std.mem.eql(u8, g, head)) return null;
        } else agreed = head;
    }
    return agreed;
}

/// Whether `ty` (or a supertype) declares a member property named `name`.
/// Keyed on `class_prop_type_heads`, which records member and constructor-
/// parameter properties by declaring class.
fn staticTypeDeclaresProp(b: *const FuncBuilder, ty: []const u8, name: []const u8) bool {
    const heads = b.module.registry.class_prop_type_heads;
    if (heads.get(.{ .a = ty, .b = name }) != null) return true;
    const chain: []const []const u8 = b.module.registry.class_super_names.get(ty) orelse return false;
    for (chain) |cls| {
        if (heads.get(.{ .a = cls, .b = name }) != null) return true;
    }
    return false;
}

/// When a qualified read `recv.name` resolves — by the STATIC type of `recv`
/// — to an in-scope member-extension property whose getter must win over any
/// same-named stored field on the runtime object, return the interned
/// `$extread$<name>` marker. Null when the ordinary field read applies.
fn staticExtPropReadField(b: *FuncBuilder, receiver: *const Expr, name: []const u8) Allocator.Error!?ConstId {
    const recv_name = switch (receiver.*) {
        .Path => |p| if (p.segments.len == 1) p.segments[0].name else return null,
        else => return null,
    };
    const static_ty = staticBareReceiverType(b, recv_name) orelse return null;
    const owner = b.ownerClass() orelse return null;
    // An in-scope member-extension property `name` on the enclosing class
    // whose extension-receiver type the static type satisfies.
    const ext_recv = inline_state.memberExtPropRecv(owner, name) orelse return null;
    if (!b.module.classIsOrExtends(static_ty, ext_recv)) return null;
    // A member of the static type outranks the extension (Kotlin); the
    // ordinary field read is then correct.
    if (staticTypeDeclaresProp(b, static_ty, name)) return null;
    const marker = try std.fmt.allocPrint(b.allocator, "$extread${s}", .{name});
    return try b.module.internConst(b.allocator, .{ .String = marker });
}

/// Intern the `super<Q>` qualifier (type ref) or `super@Q` label (ident).
fn superQualifier(b: *FuncBuilder, qualifier: ?ast.TypeRef, label: ?ast.Ident) Allocator.Error!?ConstId {
    if (qualifier) |t| {
        return try b.module.internConst(b.allocator, .{ .String = t.name.name });
    }
    if (label) |id| {
        return try b.module.internConst(b.allocator, .{ .String = id.name });
    }
    return null;
}

/// Replay the `finally { … }` bodies pushed above `base` inline, innermost
/// first, ahead of a jump that leaves their try regions (an inline `return`
/// to its join, a `break`/`continue` crossing a `try`). While one finally
/// replays, only the finallys strictly outside it stay active, so a jump
/// within the finally body still unwinds correctly. The bypassed try
/// regions' runtime `TryFrame`s are popped when the current block exits —
/// the jump bypasses the finally sentinel that would pop them.
fn replayFinallysForJump(b: *FuncBuilder, base_raw: usize) Allocator.Error!void {
    const base = @min(base_raw, b.finally_stack.items.len);
    const pop_bodies = try b.finallyBodiesFrom(base);
    if (b.finally_stack.items.len > base) {
        // Each finally body re-lowers under the splice-resolve context that
        // was active when its `try` was lowered, not the jump site's: a
        // spliced body's finally replayed inside a spliced lambda otherwise
        // resolves the body's own params against the lambda's caller region.
        const windows = try b.finallyWindowsSnapshot();
        defer b.allocator.free(windows);
        const prior = try b.swapFinallyStack(&.{});
        defer b.allocator.free(prior);
        var idx: usize = prior.len;
        while (idx > base) {
            idx -= 1;
            const blk = &prior[idx];
            const outer = try b.allocator.dupe(ast.Block, prior[0..idx]);
            const dropped = try b.swapFinallyStack(outer);
            b.allocator.free(dropped);
            const saved_window = b.lambda_splice_resolve;
            // The band list is restored by VALUE: a nested splice inside the
            // replayed body appends at the truncated length and would
            // otherwise overwrite the outer bands a bare length restore
            // re-exposes.
            const saved_bands = try b.allocator.dupe(
                @TypeOf(b.splice_hidden_bands.items[0]),
                b.splice_hidden_bands.items,
            );
            defer b.allocator.free(saved_bands);
            if (idx < windows.len) {
                b.lambda_splice_resolve = windows[idx].window;
                b.splice_hidden_bands.items.len = @min(b.splice_hidden_bands.items.len, windows[idx].bands_len);
            }
            _ = try lowerBlock(b, blk);
            b.lambda_splice_resolve = saved_window;
            b.splice_hidden_bands.clearRetainingCapacity();
            try b.splice_hidden_bands.appendSlice(b.allocator, saved_bands);
        }
        const restore = try b.allocator.dupe(ast.Block, prior);
        const dropped2 = try b.swapFinallyStack(restore);
        b.allocator.free(dropped2);
    }
    if (pop_bodies.len != 0) {
        b.setPopOnExit(b.cur, pop_bodies);
    } else {
        b.allocator.free(pop_bodies);
    }
}

fn lowerReturn(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const ret = expr.Return;
    const label = ret.label;
    var r: ?Reg = null;
    if (ret.value) |e| {
        // `return …` puts the declared return type in tail position; only a
        // bare `return` targets the enclosing fn.
        var prev: ?(?ast.TypeRef) = null;
        if (label == null) prev = b.pushExpected(b.declaredReturn());
        const lowered = try lowerExpr(b, e);
        if (prev) |p| b.restoreExpected(p);
        r = lowered;
    }
    // An unlabeled `return` inside an inlined body returns from that inline
    // fn — the call's value.
    if (label == null) {
        if (b.inlineActiveReturn()) |ar| {
            if (r) |rr| try b.push(.{ .Move = .{ .dst = ar.reg, .src = rr } });
            // Replay the `finally { … }` blocks pushed *inside* this inline
            // frame before jumping to its join. Finallys from an enclosing
            // inline frame belong to that frame's own return and must not run
            // here: `composing { try { return snap.enter(block) } finally { apply } }`
            // inlines `enter { try { return block() } finally { restore } }`, so
            // at `return block()` the stack holds [apply, restore]; replaying
            // both would apply the snapshot twice.
            try replayFinallysForJump(b, ar.finally_base);
            // Also pop the CATCH-ONLY try frames opened inside this inline body:
            // the jump to the join bypasses their `catch_done` exit, so without
            // this the catch stays armed over the code after the inlined call
            // (`parseString("double") { toDouble() }` then rejecting NaN).
            const catch_pops = try b.catchBodiesFrom(ar.catch_base);
            defer b.allocator.free(catch_pops);
            try b.appendPopOnExit(b.cur, catch_pops);
            b.terminate(.{ .Goto = ar.join });
            const dead = try b.allocBlock();
            b.switchTo(dead);
            return b.emitConst(.Unit);
        }
    }
    // `return@<inlineFnName>` inside a spliced inline-argument lambda.
    if (label) |lbl| {
        if (b.inlineLambdaRetFor(lbl.name)) |lr| {
            if (r) |rr| try b.push(.{ .Move = .{ .dst = lr.reg, .src = rr } });
            b.terminate(.{ .Goto = lr.join });
            const dead = try b.allocBlock();
            b.switchTo(dead);
            return b.emitConst(.Unit);
        }
        // `return@<inlineFnName>` targeting an inline body currently being
        // SPLICED — reached from inside a lambda spliced by a nested inline
        // call (`accept { … }.otherwise { return@tryParseTime }`). The
        // target has no runtime frame, so the return resolves here to the
        // splice frame's join, replaying its own finallys first.
        if (if (runtime.envOnce("KLIO_NO_LR_STATIC") == null) b.inlineReturnFor(lbl.name) else null) |ar| {
            if (r) |rr| try b.push(.{ .Move = .{ .dst = ar.reg, .src = rr } });
            try replayFinallysForJump(b, ar.finally_base);
            b.terminate(.{ .Goto = ar.join });
            const dead = try b.allocBlock();
            b.switchTo(dead);
            return b.emitConst(.Unit);
        }
    }
    if (label) |lbl| {
        // A labeled return unwinds at runtime to the frame whose function /
        // lambda carries this label (`frameMatchesLabel`). That is correct
        // whether the target is the current lambda (a local `return@self`,
        // absorbed at this frame) or an enclosing one reached through a
        // non-inlined call — e.g. `run sc@{ once { return@sc } }`, where the
        // lambda passed to the inline `once` is itself lowered outside any
        // inline context. Emitting a plain `Return` there returned from the
        // lambda locally and silently dropped the non-local return.
        b.terminate(.{ .LabeledReturn = .{ .label = lbl.name, .value = r } });
    } else if (b.isLambdaBody() and !b.isNamedLocalFn()) {
        // A bare `return` in an argument lambda returns from the function
        // the lambda is WRITTEN in. When the enclosing inline callee runs
        // as a real frame (image-deferred / cross-pack body), the labeled
        // form unwinds exactly to that frame (`frameMatchesLabel`); an
        // untargeted non-local return would be absorbed by the first HOF
        // boundary — `fastFirstOrNull`'s `return it` escaped its own body
        // and became its CALLER's return value.
        if (build.currentRealFn()) |ename| {
            b.terminate(.{ .LabeledReturn = .{ .label = ename, .value = r } });
        } else {
            b.terminate(.{ .NonLocalReturn = r });
        }
    } else {
        b.terminate(.{ .Return = r });
    }
    const dead = try b.allocBlock();
    b.switchTo(dead);
    return b.emitConst(.Unit);
}

fn lowerTry(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const t = expr.Try;
    const result = b.allocReg();
    const exit = try b.allocBlock();
    const finally_entry: ?BlockId = if (t.finally != null) try b.allocBlock() else null;
    // The post-finally sentinel is allocated up front so catch handlers can be
    // protected by the finally before their bodies are lowered (a throw in a
    // catch must run the finally, then re-raise past this sentinel).
    const finally_done: ?BlockId = if (finally_entry != null) try b.allocBlock() else null;

    // Pre-allocate each catch handler's entry block + exception register.
    const Handler = struct { c: ast.Catch, blk: BlockId, exc: Reg };
    const handlers = try b.allocator.alloc(Handler, t.catches.len);
    defer b.allocator.free(handlers);
    for (t.catches, handlers) |c, *h| {
        const blk = try b.allocBlock();
        const exc = b.allocReg();
        h.* = .{ .c = c, .blk = blk, .exc = exc };
    }

    const body_entry = try b.allocBlock();
    b.terminate(.{ .Goto = body_entry });
    b.switchTo(body_entry);
    const cur_id = b.cur;
    const catch_handlers = try b.allocator.alloc(CatchHandler, handlers.len);
    for (handlers, catch_handlers) |h, *ch| {
        ch.* = .{ .type_name = loweredTypeName(b, &h.c.ty), .handler = h.blk, .exception_reg = h.exc };
    }
    b.attachCatches(cur_id, catch_handlers, finally_entry);
    if (finally_done) |done| b.setFinallyDoneFor(cur_id, done);
    if (finally_entry == null and t.catches.len != 0) b.setCatchDoneFor(cur_id, exit);
    if (t.finally) |blk| try b.pushFinally(blk, cur_id);
    // A catch-only try (no finally) needs its body tracked so an inline
    // `return` inside it pops the runtime catch frame on the way to its join.
    const catch_only = finally_entry == null and t.catches.len != 0;
    if (catch_only) try b.pushCatchBody(cur_id);
    const body_val = try lowerBlock(b, &t.body);
    if (catch_only) b.popCatchBody();
    try b.push(.{ .Move = .{ .dst = result, .src = body_val } });
    if (finally_entry) |fin| {
        b.terminate(.{ .Goto = fin });
    } else {
        b.terminate(.{ .Goto = exit });
    }

    // Each handler body. A catch body is itself protected by the finally so a
    // throw from within it still runs the finally before propagating.
    for (handlers) |h| {
        b.switchTo(h.blk);
        if (finally_entry) |fin| b.protectCatchWithFinally(h.blk, fin, finally_done.?);
        try b.pushScope();
        try b.bind(h.c.binding.name, h.exc);
        // A catch parameter's type is always written in the source, so it is
        // static evidence for every member call on it in the handler. Binding
        // the register without recording the type left those calls with no
        // receiver type — the largest single reason static member dispatch
        // declines is locals lowering has in scope but has no type for.
        try b.setLocalDeclTypeOwned(
            h.c.binding.name,
            try decl_mod.loweredTypeRef(b.allocator, &h.c.ty, true),
        );
        if (h.c.ty.nullable) try b.setLocalDeclNullable(h.c.binding.name);
        const v = try lowerBlock(b, &h.c.body);
        try b.push(.{ .Move = .{ .dst = result, .src = v } });
        try b.popScope();
        if (finally_entry) |fin| {
            b.terminate(.{ .Goto = fin });
        } else {
            b.terminate(.{ .Goto = exit });
        }
    }

    // Finally body.
    if (finally_entry) |fin| {
        if (t.finally != null) b.popFinally();
        const done = finally_done.?;
        b.switchTo(fin);
        if (t.finally) |blk| _ = try lowerBlock(b, &blk);
        b.terminate(.{ .Goto = done });
        b.switchTo(done);
        b.terminate(.{ .Goto = exit });
    }

    b.switchTo(exit);
    return result;
}

fn lowerLambda(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const lam = expr.Lambda;
    const eager_shape = b.module.eagerParamShapeOf(lam.body.span);
    const recorded_recv = b.lambdaArgRecv(expr.span());
    var expected_recv_owned: ?ir.TypeRef = null;
    defer if (expected_recv_owned) |receiver| {
        var cleanup = receiver;
        cleanup.deinit(b.allocator);
    };
    const expected_recv: ?ir.TypeRef = blk: {
        if (b.peekExpected()) |exp| {
            if (exp.function) |ft| {
                if (ft.receiver) |*receiver| {
                    expected_recv_owned = try loweredOwnedLocalTypeRef(b, receiver);
                    break :blk expected_recv_owned.?;
                }
            }
        }
        break :blk null;
    };
    const expected_shape_known = if (b.peekExpected()) |exp|
        exp.function != null
    else
        false;
    const receiver_type = recorded_recv orelse expected_recv;
    const receiver_head = if (receiver_type) |receiver|
        receiver.name
    else
        b.module.eagerRecvHeadOf(lam.body.span);
    const lambda_receiver_shape_known = expected_shape_known or
        recorded_recv != null or eager_shape != null;
    const lambda_has_receiver = receiver_head != null or
        (eager_shape != null and eager_shape.?.has_receiver);
    b.module.pending_lambda_no_receiver = lambda_receiver_shape_known and !lambda_has_receiver;
    // Consume the per-argument expected lambda arity set by the call
    // lowering for this argument slot before the body recurses (which
    // re-arms it for the body's own nested calls).
    var expected_arity = b.pending_lambda_arity;
    b.pending_lambda_arity = -1;
    // Broad-collection mask for this lambda's params (set by the call lowering
    // from the callee parameter's function type). Consumed before the body
    // recurses so a nested lambda does not inherit it.
    const lambda_broad_mask = b.pending_lambda_broad_mask;
    b.pending_lambda_broad_mask = 0;
    // Callee-generic slot flag: the expected function type's parameters are
    // all the callee's own type parameters, so this lambda's params carry
    // Kotlin's generic static typing. Consumed the same way.
    const lambda_fn_generic = b.pending_ref_fn_generic;
    b.pending_ref_fn_generic = false;
    // A lambda assigned to a typed binding (`val h: Ctx.() -> Unit = { … }`)
    // never reaches the call-argument arity path; derive the arity from the
    // binding's functional type so a `T.() -> R` receiver lambda (zero value
    // parameters) drops its `it` and resolves bare members through the
    // receiver bound at invocation, rather than a spurious `it` parameter.
    // The arity recorded at the call site (by span), authoritative when the
    // per-argument `pending_lambda_arity` was not set on this emit path.
    var arity_src: []const u8 = "pending";
    if (expected_arity == -1) {
        if (b.lambdaArgArity(expr.span())) |ar| {
            expected_arity = ar;
            arity_src = "callsite";
        }
    }
    if (expected_arity == -1) {
        if (b.peekExpected()) |exp| {
            if (exp.function) |ft| {
                expected_arity = @intCast(ft.params.len);
                arity_src = "expected";
            }
        }
    }
    // Last resort: typeck's own answer for this lambda, keyed by its body span.
    // The AST-side sources above all need the callee's signature, which a
    // CROSS-PACK member call does not have — the callee is absent from the
    // lowering module's name index (`onDrawWithContent { … }` on a
    // `CacheDrawScope` declared in another pack). Typeck resolved the expected
    // type across packs, so it knows the value arity even when the lowering
    // cannot see the declaration.
    if (expected_arity == -1) {
        if (eager_shape) |shape| {
            expected_arity = @intCast(shape.arity);
            arity_src = if (shape.has_receiver) "eager-recv" else "eager-plain";
        }
    }
    // A zero-`->` lambda gets its implicit `it` only when its own
    // functional type takes exactly one parameter. A `() -> R` and a
    // `T.() -> R` receiver lambda both encode arity 0, so the
    // parser-injected `it` is dropped and an `it` reference inside resolves
    // to the nearest enclosing lambda's `it` (or is rejected when none
    // exists). Suppression applies only to the arity-0 shapes; an unknown
    // arity (-1, an unconstrained value position) keeps the single-`it`
    // binding unchanged.
    const suppress_it = lam.implicit_it and expected_arity == 0;
    if (orAuditOn() and lam.implicit_it)
        std.debug.print("[IT-AUDIT] lambda f{d}:{d}..{d} expected_arity={d} src={s} suppress={}\n", .{ lam.body.span.file.int(), lam.body.span.start, lam.body.span.end, expected_arity, arity_src, suppress_it });
    const eff_params: []const ast.Ident = if (suppress_it) &.{} else lam.params;
    const eff_param_tys: []const ?ast.TypeRef = if (suppress_it) &.{} else lam.param_tys;
    // Names of lambda params (including the implicit `it`) whose effective
    // static type — the lambda's own annotation, else the expected functional
    // type's parameter — is a broad collection (`Iterable`/`Collection`).
    // Recorded on the body builder so `it + x` over a runtime `Set` produces a
    // `List`. Derived here (not via the body's `param_tys`) so the implicit
    // `it`'s runtime overload-dispatch placeholder type is left untouched.
    var broad_names: std.ArrayList([]const u8) = .empty;
    defer broad_names.deinit(b.allocator);
    if (!suppress_it and eff_params.len != 0) {
        const ft = if (b.peekExpected()) |exp| exp.function else null;
        for (eff_params, 0..) |p, i| {
            const ty: ?ast.TypeRef = if (i < eff_param_tys.len and eff_param_tys[i] != null)
                eff_param_tys[i]
            else if (ft != null and i < ft.?.params.len)
                ft.?.params[i]
            else
                null;
            const by_ty = ty != null and ty.?.function == null and helpers.isBroadCollectionTypeName(ty.?.name.name);
            // Also honor the callee-parameter mask: a call-argument lambda has
            // no expected functional type on the stack, so its `it`'s declared
            // `Iterable` type lives only in the callee's parameter signature.
            const by_mask = i < 32 and (lambda_broad_mask >> @intCast(i)) & 1 != 0;
            if (by_ty or by_mask) {
                try broad_names.append(b.allocator, p.name);
            }
        }
    }
    // Params of a callee-generic slot (unannotated only — an explicit
    // annotation is the stronger static fact and wins).
    var generic_names: std.ArrayList([]const u8) = .empty;
    defer generic_names.deinit(b.allocator);
    if (lambda_fn_generic and !suppress_it) {
        for (eff_params, 0..) |p, i| {
            const annotated = i < eff_param_tys.len and eff_param_tys[i] != null;
            if (!annotated) try generic_names.append(b.allocator, p.name);
        }
    }
    // `outer_names` / `inherited_rlp` ownership passes into the lambda lower.
    const outer_names = try b.visibleNames();
    const inherited_rlp = try b.receiverLambdaParamNames();
    try b.stashRecvHeadsForLambda();
    var outer_boxed = try b.boxedVarsSnapshot();
    defer outer_boxed.deinit();
    const enclosing_owner = try enclosingOwnerFor(b);

    const inherited_lef = try b.localExtFnNames();
    const inherited_erp = try b.erasedRecvParamNames();
    // The implicit label this lambda carries (`runTest { … }` → "runTest").
    // The body binds `this@<label>` to its receiver.
    b.module.pending_lambda_this_label = b.pending_lambda_label;
    // The receiver type in scope at the body's site: a receiver lambda
    // (`T.() -> R`) rebinds the implicit `this` to `T`, otherwise a plain
    // block captures the enclosing `this`. Carried into the body so a bare
    // call there can still disambiguate a receiver-lambda argument's arity.
    // A receiver-lambda ARGUMENT whose receiver type the resolved callee made
    // concrete (recorded by `recordLambdaArgReceivers`) — reached when the
    // call is deferred so no expected type carries the receiver to lowerLambda.
    b.module.pending_lambda_receiver_tower = try b.collectReceiverTowerLabeled(
        b.allocator,
        receiver_head,
        b.pending_lambda_label,
    );
    b.module.pending_lambda_enclosing_recv = blk: {
        if (receiver_head) |rr| break :blk rr;
        break :blk b.enclosingRecvTy();
    };
    // The body owns that receiver as its extension receiver, so a bare call
    // there prefers an extension on it over a same-file plain namesake —
    // `validate { contact(c) }` binds `MockViewValidator.contact`, not the
    // same-file `@Composable contact`.
    if (std.c.getenv("KLIO_LAR_TRACE") != null) {
        std.debug.print("[lar-stash] s={d}..{d} head={s} ty={s}\n", .{ expr.span().start, expr.span().end, receiver_head orelse "-", if (receiver_type) |r| r.name else "-" });
    }
    if (receiver_head) |rr| b.module.pending_lambda_own_recv = rr;
    if (receiver_type) |receiver| {
        b.module.pending_lambda_own_recv_type = try receiver.clone(b.allocator);
    }
    b.module.pending_lambda_unit = b.pending_ref_lambda_unit;
    if (!suppress_it) {
        if (b.pending_ref_lambda_param_types) |types| {
            const value_param_count: usize = if (lam.implicit_it and
                eff_params.len == 0) 1 else eff_params.len;
            const count = @min(types.len, value_param_count);
            const owned = try b.allocator.alloc(ir.TypeRef, count);
            var initialized: usize = 0;
            errdefer {
                for (owned[0..initialized]) |*ty| ty.deinit(b.allocator);
                b.allocator.free(owned);
            }
            for (types[0..count], owned) |src, *dst| {
                dst.* = try src.clone(b.allocator);
                initialized += 1;
            }
            b.module.pending_lambda_param_types = owned;
        }
    }
    // Carry the enclosing non-reified type-parameter names so an `x as T`
    // cast inside the lambda body is still erased.
    b.module.pending_lambda_type_params = try b.typeParamNamesSlice();
    b.module.pending_lambda_reified_names = try b.reifiedTypeNamesSlice();
    b.module.pending_lambda_type_param_bounds = try b.typeParamBoundsSlice();
    b.module.pending_lambda_type_param_bound_refs = try b.typeParamBoundRefsSlice();
    // A lambda inside a local fn's body keeps that fn's self-identity (a
    // named local fn overrides this with its own before its body lowers).
    if (b.module.pending_lambda_self_fn == null) b.module.pending_lambda_self_fn = b.selfLocalFn();
    // Non-callable-local evidence flows into the body (transitively — this
    // builder's set already includes what it inherited).
    b.module.pending_lambda_nonfn_locals = try b.nonFnLocalNames();
    b.module.pending_lambda_local_decl_types = try b.localDeclTypesSnapshot();
    if (std.c.getenv("KLIO_LAMINH") != null) std.debug.print("[laminh] produce lambda b={x} n={d}\n", .{ @intFromPtr(b) & 0xffff, b.localDeclTypeCount() });
    // Fold ACTIVE inline-splice param types into the snapshot: a nested
    // closure inside a spliced body captures the callee's parameter by
    // name (`destination.add(it)` inside `transform(element)?.let { ... }`
    // spliced from mapNotNullTo), and the local-decl snapshot never saw
    // the splice channel.
    if (b.module.pending_lambda_local_decl_types) |*locals| {
        var sp_it = b.spliceParamTyIterator();
        while (sp_it.next()) |e| {
            if (locals.types.contains(e.key_ptr.*)) continue;
            const lowered_ty = try decl_mod.loweredTypeRef(b.allocator, e.value_ptr, true);
            try locals.types.put(e.key_ptr.*, lowered_ty);
        }
        // Pre-derive the lazily-typed outer locals INTO the snapshot: a
        // closure capturing `val iterator = listIterator(size)` sees only
        // an on-demand derivation that cannot run in the closure's scope.
        // Deriving here runs in the OUTER builder — the only scope the
        // initializer was written in — and the closure inherits a plain
        // declared type.
        var init_it = b.localInitExprIterator();
        while (init_it.next()) |e| {
            if (locals.types.contains(e.key_ptr.*)) continue;
            const prev_self = init_self_name;
            if (b.localInitNameFree(e.key_ptr.*)) init_self_name = e.key_ptr.*;
            // The FULL deriver, not just the call-return channel: a literal
            // or member-read init crosses the capture boundary too
            // (`var result = 0` read inside the repeat lambda).
            const derived = staticExprTypeRef(b, e.value_ptr.*) catch null;
            init_self_name = prev_self;
            if (derived) |ty| try locals.types.put(e.key_ptr.*, ty);
        }
    }
    const lowered = try lambda_body.lowerLambdaBodyCapturingKindWithIt(
        b.module,
        eff_params,
        eff_param_tys,
        &lam.body,
        outer_names,
        true,
        &outer_boxed,
        null,
        false,
        false,
        inherited_rlp,
        inherited_lef,
        inherited_erp,
        &b.local_fn_overloads,
        enclosing_owner,
        suppress_it,
        if (suppress_it) lam.span else null,
        broad_names.items,
        generic_names.items,
    );
    const body_func = lowered.func;
    const captured_names = lowered.captures;
    if (b.module.funcByIdMut(body_func)) |f| {
        f.lambda_receiver_shape_known = lambda_receiver_shape_known;
        f.lambda_has_receiver = lambda_has_receiver;
        // The receiver HEAD is this lambda's OWN derivation — the body
        // builder's recvTy can carry the ENCLOSING lambda's receiver (a
        // placement block nested in a measure lambda recorded
        // "MeasureScope"), and the runtime's compatibility receiver
        // inference then re-selects a chain value satisfying the wrong
        // head, silently swapping the invoke's real receiver (the
        // coordinator displaced the PlacementScope and every placement
        // pass lost its member-extension owner). When the shape is known,
        // record exactly the derived head — or null for a plain lambda,
        // which disables re-selection and keeps the passed receiver.
        if (lambda_receiver_shape_known) {
            f.lambda_receiver_ty = if (receiver_head) |h| try b.allocator.dupe(u8, h) else null;
        }
    }

    // Record the implicit label.
    if (b.pending_lambda_label) |label| {
        b.pending_lambda_label = null;
        if (b.module.funcByIdMut(body_func)) |f| {
            f.implicit_label = label;
        }
    }
    // A `suspend { … }` literal: the body is a suspend function value.
    if (b.pending_suspend_lambda) {
        b.pending_suspend_lambda = false;
        if (b.module.funcByIdMut(body_func)) |f| {
            f.is_suspend = true;
        }
    }
    const captures = try b.allocator.alloc(Reg, captured_names.len);
    for (captured_names, captures) |n, *c| c.* = try resolveCapture(b, n);

    const param_names = if (suppress_it)
        try b.allocator.alloc([]const u8, 0)
    else
        try lambdaParamNames(b.allocator, lam.params);
    const body_ast = lam.body;
    const dst = b.allocReg();
    try b.push(.{ .AstLambda = .{
        .dst = dst,
        .params = param_names,
        .body_ast = body_ast,
        .captures = captures,
        .captured_names = captured_names,
        .absorb_return = false,
        .body_func = body_func,
    } });
    return dst;
}

fn lowerAnonFun(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const af = expr.AnonFun;
    const receiver_head: ?[]const u8 = if (af.receiver_ty) |r| r.name.name else null;
    const body_block: ast.Block = blk: {
        if (af.body) |body| {
            switch (body.*) {
                .Block => |bl| break :blk bl,
                .Expr => |e| {
                    const stmts = try b.allocator.alloc(ast.Stmt, 1);
                    stmts[0] = .{ .Expr = e };
                    break :blk .{ .stmts = stmts, .span = exprSpan(expr) };
                },
            }
        }
        break :blk .{ .stmts = &.{}, .span = exprSpan(expr) };
    };
    const param_names = try b.allocator.alloc([]const u8, af.params.len);
    const param_idents = try b.allocator.alloc(ast.Ident, af.params.len);
    defer b.allocator.free(param_idents);
    const param_tys = try b.allocator.alloc(?ast.TypeRef, af.params.len);
    defer b.allocator.free(param_tys);
    for (af.params, param_names, param_idents, param_tys) |p, *pn, *pi, *pt| {
        pn.* = p.name.name;
        pi.* = p.name;
        pt.* = p.ty;
    }
    // `outer_names` / `inherited_rlp` ownership passes into the lambda lower.
    const outer_names = try b.visibleNames();
    const inherited_rlp = try b.receiverLambdaParamNames();
    try b.stashRecvHeadsForLambda();
    var outer_boxed = try b.boxedVarsSnapshot();
    defer outer_boxed.deinit();
    const enclosing_owner = try enclosingOwnerFor(b);

    const inherited_lef = try b.localExtFnNames();
    const inherited_erp = try b.erasedRecvParamNames();
    b.module.pending_lambda_receiver_tower = try b.collectReceiverTowerLabeled(b.allocator, receiver_head, null);
    if (receiver_head) |head| {
        b.module.pending_lambda_enclosing_recv = head;
        b.module.pending_lambda_own_recv = head;
    }
    if (af.receiver_ty) |*receiver| {
        b.module.pending_lambda_own_recv_type = try loweredOwnedLocalTypeRef(b, receiver);
    }
    b.module.pending_lambda_nonfn_locals = try b.nonFnLocalNames();
    b.module.pending_lambda_local_decl_types = try b.localDeclTypesSnapshot();
    if (std.c.getenv("KLIO_LAMINH") != null) std.debug.print("[laminh] produce anonfun b={x} n={d}\n", .{ @intFromPtr(b) & 0xffff, b.localDeclTypeCount() });
    const lowered = try lowerLambdaBodyCapturingKind(
        b.module,
        param_idents,
        param_tys,
        &body_block,
        outer_names,
        false,
        &outer_boxed,
        null,
        inherited_rlp,
        inherited_lef,
        inherited_erp,
        enclosing_owner,
    );
    const captured_names = lowered.captures;
    if (b.module.funcByIdMut(lowered.func)) |f| {
        f.lambda_receiver_shape_known = true;
        f.lambda_has_receiver = receiver_head != null;
    }
    const captures = try b.allocator.alloc(Reg, captured_names.len);
    for (captured_names, captures) |n, *c| c.* = try resolveCapture(b, n);
    const dst = b.allocReg();
    try b.push(.{ .AstLambda = .{
        .dst = dst,
        .params = param_names,
        .body_ast = body_block,
        .captures = captures,
        .captured_names = captured_names,
        .absorb_return = true,
        .body_func = lowered.func,
    } });
    return dst;
}

/// Build the lexically enclosing class context handed to a lambda body.
fn enclosingOwnerFor(b: *FuncBuilder) Allocator.Error!?EnclosingOwner {
    if (b.ownerClass()) |o| {
        return EnclosingOwner{ .class = o, .members = try b.enclosingMembersForChild() };
    }
    return null;
}

fn lambdaParamNames(allocator: Allocator, params: []const ast.Ident) Allocator.Error![][]const u8 {
    if (params.len == 0) {
        const out = try allocator.alloc([]const u8, 1);
        out[0] = "it";
        return out;
    }
    const out = try allocator.alloc([]const u8, params.len);
    for (params, out) |p, *o| o.* = p.name;
    return out;
}

/// The non-receiver parameter count encoded in a lowered function-type
/// head (`Function{N}` from `decl.loweredTypeRef`), or null when the type
/// is not a function type. A `T.() -> R` receiver lambda and a `() -> R`
/// lambda both encode `Function0`; a `(T) -> R` lambda encodes `Function1`.
fn fnTypeArity(ty: ir.TypeRef) ?i16 {
    const head = ty.name;
    if (!std.mem.startsWith(u8, head, "Function")) return null;
    const digits = head["Function".len..];
    if (digits.len == 0) return null;
    const n = std.fmt.parseInt(i16, digits, 10) catch return null;
    return n;
}

/// A function-typed parameter whose declared return is `Unit`: the
/// `Function{N}` tag's trailing type argument (before any `#` markers).
fn fnTypeReturnsUnit(b: *FuncBuilder, ty: ir.TypeRef) bool {
    if (fnTypeArityAlias(b, ty) == null) return false;
    var hi = ty.args.len;
    while (hi > 0 and ty.args[hi - 1].name.len != 0 and ty.args[hi - 1].name[0] == '#') hi -= 1;
    if (hi == 0) return false;
    const ret = ty.args[hi - 1];
    return (std.mem.eql(u8, ret.name, "Unit") or std.mem.eql(u8, ret.name, "kotlin.Unit")) and !ret.nullable;
}

/// `fnTypeArity` resolving an aliased function-typed parameter
/// (`RoutingHandler = RoutingContext.() -> Unit` → `Function0`) through the
/// typealias registry before reading the `Function{N}` tag.
fn fnTypeArityAlias(b: *FuncBuilder, ty: ir.TypeRef) ?i16 {
    if (fnTypeArity(ty)) |n| return n;
    if (b.module.registry.type_aliases.get(ty.name)) |resolved| {
        if (std.mem.startsWith(u8, resolved, "Function")) {
            const digits = resolved["Function".len..];
            if (digits.len != 0) return std.fmt.parseInt(i16, digits, 10) catch null;
        }
    }
    return null;
}

/// Per-argument expected lambda arity for a call dispatched to the
/// resolved runtime `func`, parallel to `args`. Each entry is the
/// non-receiver parameter count of the matching parameter's function type,
/// or `-1` when the parameter is not a function type or cannot be aligned.
/// `recv_offset` skips a leading implicit `this` parameter (member /
/// extension calls). Positional alignment only: a named or spread argument
/// list yields all-unknown so a misaligned guess never suppresses an `it`.
/// The extension overload named `name` that hosts a trailing lambda for a
/// call of `user_arg_count` arguments: an extension (leading `this`) whose
/// last parameter is function-typed and whose non-receiver arity equals
/// `user_arg_count`. The bare-call heuristic resolves one FuncId by
/// declaration order, which for an overloaded name (`get` — `List.get`,
/// `Map.get`, `Route.get(path, body)`) may not be the overload the trailing
/// lambda lands on; the per-argument arity readout must read the lambda's
/// expected arity from the hosting overload so a `T.() -> R` handler drops
/// its synthetic `it`.
/// Whether `f`'s trailing function-typed parameter declares more
/// parameters than the call's trailing lambda supplies, leaving a reified
/// type parameter that appears in that lambda-parameter list unbound. Used
/// to reject a reified inline overload a bare/underfilled lambda cannot
/// instantiate (`post<reified R>(path, RoutingContext.(R) -> Unit)` for a
/// zero-parameter handler). Conservative: only fires when the last
/// parameter resolves to a function type whose arity exceeds the lambda's.
fn reifiedNeedsLambdaArity(b: *FuncBuilder, f: *const ast.Function, lambda_arity: usize) bool {
    if (f.params.len == 0) return false;
    const ty = f.params[f.params.len - 1].ty;
    const fn_arity: usize = blk: {
        if (ty.function) |ft| break :blk ft.params.len;
        const tag = b.module.registry.type_aliases.get(ty.name.name) orelse return false;
        if (!std.mem.startsWith(u8, tag, "Function")) return false;
        break :blk std.fmt.parseInt(usize, tag["Function".len..], 10) catch return false;
    };
    return fn_arity > lambda_arity;
}

/// Whether any same-named lowered candidate is an extension whose value-
/// parameter shape can bind this call's argument count through an implicit
/// receiver — `to(x)` inside a class is `this.to(x)`, so the receiver-bound
/// candidate keeps the bare call on the member/extension dispatch path. The
/// host global serves the call only when no receiver-bound binding is
/// possible (no such candidate, or none fits the arity: `iterator { … }`
/// against the zero-arg `Map.iterator()` family).
fn extensionCandidateFitsArity(b: *FuncBuilder, name: []const u8, user_arg_count: usize) bool {
    for (b.module.funcsBySimpleName(name)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this")) continue;
        const user_params = f.params.len - 1;
        var required: usize = 0;
        var has_vararg = false;
        for (f.params[1..]) |*p| {
            if (p.is_vararg) {
                has_vararg = true;
                continue;
            }
            if (!p.has_default) required += 1;
        }
        if (has_vararg) {
            if (user_arg_count >= required) return true;
        } else if (user_arg_count >= required and user_arg_count <= user_params) {
            return true;
        }
    }
    return false;
}

/// The class MEMBER that hosts a trailing lambda for a bare call, reached
/// owner-scoped through `member_method_fids`. `Module.func_name_index` indexes
/// only TOP-LEVEL functions, so a bare call to a member (`onDrawWithContent { … }`
/// inside a `CacheDrawScope` extension) could not reach its signature at lower
/// time: the trailing lambda's expected arity came back unknown and a
/// `T.() -> R` receiver lambda kept the parser's synthetic `it`, which then
/// swallowed the receiver at invocation.
///
/// The candidate classes are the enclosing owner and the declared extension
/// receiver, each walked up its supertype chain — the member may be declared on
/// a supertype of the receiver we are lowering against.
fn memberHostingTrailingLambda(b: *FuncBuilder, name: []const u8, user_arg_count: usize) ?FuncId {
    const mhtl_trace = if (runtime.envOnce("KLIO_MISS_TRACE")) |w| std.mem.eql(u8, w, name) else false;
    var roots: [2]?[]const u8 = .{ b.ownerClass(), null };
    if (b.recvTy()) |rt| roots[1] = rsplitLast(rt, '.');
    if (mhtl_trace) std.debug.print("[mhtl] {s}: owner={?s} recv_root={?s} argc={d}\n", .{ name, roots[0], roots[1], user_arg_count });
    for (roots) |root_opt| {
        const root = root_opt orelse continue;
        // The class itself, then its transitive supertype names (nearest first).
        const supers: []const []const u8 = b.module.registry.class_super_names.get(root) orelse &.{};
        var i: usize = 0;
        while (i < 1 + supers.len) : (i += 1) {
            const cls = if (i == 0) root else supers[i - 1];
            const prefix = std.fmt.allocPrint(b.allocator, "{s}\x00{s}\x00", .{ cls, name }) catch return null;
            defer b.allocator.free(prefix);
            var found: ?FuncId = null;
            var found_arity: ?i16 = null;
            var found_recv: ?[]const u8 = null;
            var it = b.module.registry.member_method_fids.iterator();
            while (it.next()) |entry| {
                if (!std.mem.startsWith(u8, entry.key_ptr.*, prefix)) continue;
                const fid = entry.value_ptr.*;
                const f = b.module.funcById(fid) orelse continue;
                const hosts = memberHostsTrailingLambdaAtArity(b, cls, f, fid, user_arg_count);
                if (mhtl_trace) std.debug.print("[mhtl] {s}: cls={s} cand #{d} params={d} hosts={} last_ty={s} last_arity={?d}\n", .{ name, cls, fid.int(), f.params.len, hosts, if (f.params.len != 0) f.params[f.params.len - 1].ty.name else "-", if (f.params.len != 0) fnTypeArityAlias(b, f.params[f.params.len - 1].ty) else null });
                if (!hosts) continue;
                const last = f.params[f.params.len - 1];
                const arity = fnTypeArityAlias(b, last.ty) orelse continue;
                const recv = fnTypeReceiverHead(b, last.ty);
                if (found_arity) |fa| {
                    if (fa != arity or !optionalStringEql(found_recv, recv)) return null;
                } else {
                    found = fid;
                    found_arity = arity;
                    found_recv = recv;
                }
            }
            if (found) |fid| return fid;
        }
    }
    return null;
}

fn predeclaredMemberTrailingLambdaShape(b: *FuncBuilder, name: []const u8, user_arg_count: usize) ?ir.ModuleRegistry.MemberTrailingLambdaShape {
    if (user_arg_count >= 63) return null;
    const bit = @as(u64, 1) << @intCast(user_arg_count);
    var roots: [2]?[]const u8 = .{ b.ownerClass(), null };
    if (b.recvTy()) |rt| roots[1] = rsplitLast(rt, '.');
    for (roots) |root_opt| {
        const root = root_opt orelse continue;
        const supers: []const []const u8 = b.module.registry.class_super_names.get(root) orelse &.{};
        var i: usize = 0;
        while (i < 1 + supers.len) : (i += 1) {
            const cls = if (i == 0) root else supers[i - 1];
            const shapes = b.module.registry.member_trailing_lambda_shapes.get(.{ .a = cls, .b = name }) orelse continue;
            var agreed: ?ir.ModuleRegistry.MemberTrailingLambdaShape = null;
            for (shapes.items) |shape| {
                if (shape.accepted_arities & bit == 0) continue;
                if (agreed) |old| {
                    if (old.value_arity != shape.value_arity or
                        !optionalStringEql(old.receiver_head, shape.receiver_head)) return null;
                } else {
                    agreed = shape;
                }
            }
            if (agreed) |shape| return shape;
        }
    }
    return null;
}

fn optionalStringEql(a: ?[]const u8, b: ?[]const u8) bool {
    if (a == null or b == null) return a == null and b == null;
    return std.mem.eql(u8, a.?, b.?);
}

fn memberParamHasDefault(b: *FuncBuilder, cls: []const u8, fid: FuncId, param_index: usize) bool {
    const f = b.module.funcById(fid) orelse return false;
    if (param_index < f.params.len and f.params[param_index].has_default) return true;
    if (b.module.registry.local_fn_defaults.get(fid)) |slots| {
        if (param_index < slots.items.len and slots.items[param_index] != null) return true;
    }
    if (b.module.registry.abstract_member_defaults.get(.{ .a = cls, .b = f.name })) |slots| {
        if (param_index < slots.items.len and slots.items[param_index] != null) return true;
    }
    const supers: []const []const u8 = b.module.registry.class_super_names.get(cls) orelse &.{};
    for (supers) |owner| {
        if (b.module.registry.abstract_member_defaults.get(.{ .a = owner, .b = f.name })) |slots| {
            if (param_index < slots.items.len and slots.items[param_index] != null) return true;
        }
    }
    return false;
}

fn memberHostsTrailingLambdaAtArity(b: *FuncBuilder, cls: []const u8, f: *const Func, fid: FuncId, user_arg_count: usize) bool {
    if (user_arg_count == 0 or f.params.len == 0) return false;
    const off: usize = if (std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
    const user_params = f.params.len - off;
    if (user_arg_count > user_params or user_params == 0) return false;
    const last = f.params[f.params.len - 1];
    if (last.is_vararg or fnTypeArityAlias(b, last.ty) == null) return false;
    // Positional arguments before a trailing lambda fill parameters from the
    // front. Every gap before the last parameter must therefore have a
    // declaration-site default, including one inherited from an expect or
    // abstract member by its concrete implementation.
    var pi = off + user_arg_count - 1;
    while (pi < f.params.len - 1) : (pi += 1) {
        if (!memberParamHasDefault(b, cls, fid, pi)) return false;
    }
    return true;
}

/// The declared RETURN type head of a function-typed parameter — the last type
/// argument of its `FunctionN`. Null when the shape is not a function type.
fn lambdaReturnHead(ty: ir.TypeRef) ?[]const u8 {
    if (!std.mem.startsWith(u8, ty.name, "Function")) return null;
    if (ty.args.len == 0) return null;
    return ty.args[ty.args.len - 1].name;
}

fn retHeadEql(a: ?[]const u8, b_in: ?[]const u8) bool {
    if (a == null and b_in == null) return true;
    if (a == null or b_in == null) return false;
    return std.mem.eql(u8, a.?, b_in.?);
}

fn overloadHostingTrailingLambda(b: *FuncBuilder, name: []const u8, user_arg_count: usize) ?FuncId {
    const ohtl_trace = if (runtime.envOnce("KLIO_MISS_TRACE")) |w| std.mem.eql(u8, w, name) else false;
    const list = b.module.func_name_index.get(name) orelse {
        if (ohtl_trace) std.debug.print("[ohtl] {s}: no func_name_index entry\n", .{name});
        return memberHostingTrailingLambda(b, name, user_arg_count);
    };
    if (ohtl_trace) std.debug.print("[ohtl] {s}: {d} candidates argc={d}\n", .{ name, list.items.len, user_arg_count });
    // With several same-named overloads that all host a trailing lambda
    // (`SnapshotStateList.withCurrent(block: T.() -> R)` and
    // `StateRecord.withCurrent(block: (r: T) -> R)`), declaration order is not
    // evidence: the block's arity differs per overload (0 vs 1), and picking
    // the wrong one records the wrong arity, so a receiver-lambda argument
    // keeps a spurious `it` and its bare member reads fall through to globals.
    // Prefer the overload whose leading `this` matches the enclosing receiver
    // type; only fall back to declaration order when none matches.
    const recv_simple: ?[]const u8 = if (b.enclosingRecvTy()) |r| simpleTypeHead(r) else null;
    var fallback: ?FuncId = null;
    // A candidate whose body has not been attached yet still answers the
    // arity question — its SIGNATURE is what the lambda shape needs. A file
    // lowered before the file that declares its callee (a user file whose
    // package places it ahead of a pack's own sources) sees the callee
    // body-less at this point; skipping it left the trailing receiver-lambda
    // with a spurious implicit `it` bound to the invocation argument
    // (`launch(Dispatchers.Default) { it }` read the StandaloneCoroutine).
    // With-body candidates still outrank body-less ones: an `expect`
    // declaration shadowed by its actual keeps losing to the real one.
    var bodyless: ?FuncId = null;
    var fallback_ret: ?[]const u8 = null;
    var ret_conflict = false;
    for (list.items) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (ohtl_trace) std.debug.print("[ohtl] {s}: cand #{d} params={d} body={} last_ty={s} last_arity={?d}\n", .{ name, fid.int(), f.params.len, f.hasBody(), if (f.params.len != 0) f.params[f.params.len - 1].ty.name else "-", if (f.params.len != 0) fnTypeArityAlias(b, f.params[f.params.len - 1].ty) else null });
        // Both shapes host a trailing lambda: an extension/member (leading
        // `this`) and a plain top-level fn — the offset generalizes.
        const off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        const user_params = f.params.len - off;
        if (user_params < user_arg_count) continue;
        const last = f.params[f.params.len - 1];
        if (last.is_vararg) continue;
        if (fnTypeArityAlias(b, last.ty) == null) continue;
        // Under-applied (`launch { … }` against `launch(context = …,
        // start = …, block)`): the trailing lambda binds the last param
        // out of sequence, so every skipped parameter must be defaulted.
        if (user_params != user_arg_count) {
            var i: usize = off + user_arg_count - 1; // leading args fill params[off..]
            var gap_defaulted = true;
            while (i < f.params.len - 1) : (i += 1) {
                if (!f.params[i].has_default) {
                    gap_defaulted = false;
                    break;
                }
            }
            if (!gap_defaulted) continue;
        }
        if (!f.hasBody()) {
            if (bodyless == null) bodyless = fid;
            continue;
        }
        // Receiver match wins outright; otherwise remember the first valid
        // candidate as the declaration-order fallback.
        if (recv_simple) |rs| {
            if (off == 1 and std.mem.eql(u8, simpleTypeHead(f.params[0].ty.name), rs))
                return fid;
        }
        if (fallback == null) {
            fallback = fid;
            fallback_ret = lambdaReturnHead(last.ty);
        } else if (!retHeadEql(fallback_ret, lambdaReturnHead(last.ty))) {
            ret_conflict = true;
        }
    }
    // Several surviving candidates whose trailing lambdas differ in RETURN
    // type — `sumOf(selector: (T) -> Int)` against `(T) -> Double`, 80 of them
    // for that name. Kotlin picks by the lambda's inferred return type, which
    // lowering does not have, so declaration order here is a guess. The pick
    // is used to STAMP the lambda's parameter types as if it were proven, and
    // a wrong stamp is worse than none: the call resolves correctly when
    // nothing is recorded. Decline instead.
    if (ret_conflict) {
        if (ohtl_trace) std.debug.print("[ohtl] {s}: declined, candidates differ in lambda return type\n", .{name});
        return null;
    }
    if (fallback) |fid| return fid;
    // A member on the enclosing/receiver class outranks a SIGNATURE-ONLY
    // top-level namesake: at pack bake the StateRecord.withCurrent extension
    // is still body-less while SnapshotStateMap.mutate's call to its own
    // private withCurrent lowers, and letting the extension's (r: T) -> R
    // arity re-shape the member call's `{ this }` block made a fresh engine
    // pack return the outer map from every mutate (the get_field-map
    // family). A WITH-BODY top-level (the fallback above) still wins as
    // before.
    if (memberHostingTrailingLambda(b, name, user_arg_count)) |fid| return fid;
    if (bodyless) |fid| return fid;
    return null;
}

/// Whether any argument in the call is passed by name.
fn anyNamedArg(arg_names: []const ?[]const u8) bool {
    for (arg_names) |an| if (an != null) return true;
    return false;
}

/// Map each argument to the callee parameter it fills, honoring Kotlin's
/// named-argument rules: a named argument matches the parameter of that name; an
/// unnamed trailing lambda binds the last parameter; the remaining unnamed
/// (positional) arguments fill the still-unassigned parameters left to right.
/// `params` is the callee's parameter slice with any receiver already removed.
/// Returns a per-argument target index (parallel to `args`), null for an
/// argument whose parameter can't be determined. Caller frees the slice.
fn mapArgsToParams(
    b: *FuncBuilder,
    params: []const ir.Param,
    args: []const Expr,
    arg_names: []const ?[]const u8,
) Allocator.Error!?[]?usize {
    const out = try b.allocator.alloc(?usize, args.len);
    for (out) |*o| o.* = null;
    const used = try b.allocator.alloc(bool, params.len);
    defer b.allocator.free(used);
    for (used) |*u| u.* = false;
    // 1. Named arguments bind their same-named parameter. A named argument
    // that matches NO parameter makes the whole call inapplicable to this
    // callee (Kotlin rejects the candidate outright), so the map must fail
    // rather than silently drop the argument — otherwise an unnamed trailing
    // lambda still "binds" the last parameter of a callee that cannot take
    // this call, and downstream heuristics record that parameter's lambda
    // shape (receiver head, arity) against the wrong lambda.
    for (args, 0..) |_, j| {
        const an = if (j < arg_names.len) arg_names[j] else null;
        if (an) |name| {
            const idx_opt: ?usize = for (params, 0..) |p, idx| {
                if (std.mem.eql(u8, p.name, name)) break idx;
            } else null;
            const idx = idx_opt orelse {
                b.allocator.free(out);
                return null;
            };
            out[j] = idx;
            used[idx] = true;
        }
    }
    // 2. An unnamed trailing lambda binds the last (still-free) parameter.
    var trailing_done = false;
    if (args.len != 0) {
        const last = args.len - 1;
        const last_named = last < arg_names.len and arg_names[last] != null;
        const last_lambda = args[last] == .Lambda or args[last] == .AnonFun;
        if (!last_named and last_lambda and params.len != 0 and !used[params.len - 1]) {
            out[last] = params.len - 1;
            used[params.len - 1] = true;
            trailing_done = true;
        }
    }
    // 3. Remaining unnamed arguments fill the free parameters front to back.
    var pidx: usize = 0;
    for (args, 0..) |_, j| {
        const an = if (j < arg_names.len) arg_names[j] else null;
        if (an != null) continue;
        if (trailing_done and j == args.len - 1) continue;
        while (pidx < params.len and used[pidx]) pidx += 1;
        if (pidx < params.len) {
            out[j] = pidx;
            if (!params[pidx].is_vararg) {
                used[pidx] = true;
                pidx += 1;
            }
        }
    }
    return out;
}

/// The element type of a function-typed VARARG parameter. The lowered
/// parameter may carry the element type directly (`Function0`) rather than a
/// materialized array, so try it as-is before stripping an array layer.
fn varargFnElemTy(b: *FuncBuilder, ty: ir.TypeRef) ir.TypeRef {
    if (fnTypeArityAlias(b, ty) != null) return ty;
    return applicability.varargElementRef(&ty);
}

fn argFnArities(b: *FuncBuilder, func: *const Func, args: []const Expr, arg_names: []const ?[]const u8, recv_offset: usize) Allocator.Error!?[]i16 {
    if (args.len == 0) return null;
    for (args) |*a| if (a.* == .Spread) return null;
    if (func.params.len < recv_offset) return null;
    const params = func.params[recv_offset..];
    const out = try b.allocator.alloc(i16, args.len);
    for (out) |*o| o.* = -1;
    // Named arguments: resolve each lambda's expected arity through its target
    // parameter (by name) so a receiver lambda passed by name is still detected
    // as arity-0 — otherwise it is mistaken for an `it`-lambda and its bare
    // member accesses fall through to unresolved globals.
    if (anyNamedArg(arg_names)) {
        const map = (try mapArgsToParams(b, params, args, arg_names)) orelse {
            b.allocator.free(out);
            return null;
        };
        defer b.allocator.free(map);
        for (out, map) |*o, m| {
            if (m) |pi| o.* = fnTypeArityAlias(b, params[pi].ty) orelse -1;
        }
        return out;
    }
    // A trailing lambda fills the last function-typed parameter even when
    // earlier defaulted parameters are omitted; align the trailing lambda
    // with the last parameter and the leading args from the front.
    // Same vararg run as the receiver recorder below. Without this the
    // literals keep their implicit `it` parameter, so the closure reports one
    // value parameter, and the VM's receiver rule — bind the extra leading
    // argument when a receiver-carrying closure is called with `n_params + 1`
    // arguments — cannot fire.
    for (params, 0..) |p, vp| {
        if (!p.is_vararg) continue;
        const n_after = params.len - vp - 1;
        if (args.len < vp + n_after) break;
        const vararg_end = args.len - n_after;
        const elem_arity = fnTypeArityAlias(b, varargFnElemTy(b, params[vp].ty)) orelse -1;
        var vi2: usize = 0;
        while (vi2 < vp and vi2 < args.len) : (vi2 += 1) out[vi2] = fnTypeArityAlias(b, params[vi2].ty) orelse -1;
        vi2 = vp;
        while (vi2 < vararg_end) : (vi2 += 1) out[vi2] = elem_arity;
        var k: usize = 0;
        while (k < n_after) : (k += 1) {
            const ai = vararg_end + k;
            const pi = vp + 1 + k;
            if (ai < args.len and pi < params.len) out[ai] = fnTypeArityAlias(b, params[pi].ty) orelse -1;
        }
        return out;
    }
    const trailing_lambda = args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun;
    if (trailing_lambda and args.len <= params.len) {
        // Leading positional args map 1:1 from the front.
        var i: usize = 0;
        while (i + 1 < args.len) : (i += 1) {
            out[i] = fnTypeArityAlias(b, params[i].ty) orelse -1;
        }
        // The trailing lambda maps to the last parameter.
        out[args.len - 1] = fnTypeArityAlias(b, params[params.len - 1].ty) orelse -1;
    } else if (args.len == params.len) {
        for (params, out) |p, *o| o.* = fnTypeArityAlias(b, p.ty) orelse -1;
    } else {
        b.allocator.free(out);
        return null;
    }
    return out;
}

/// The declared receiver-type head of a receiver-lambda parameter type
/// (`MockViewValidator.() -> Unit`), or null when the type is not a direct
/// receiver function. The lowered encoding is
/// `[#suspend?] [receiver?] params(n) ret(1) [#markers]`; a receiver is present
/// when the non-marker, non-suspend arg count is `n + 2`.
fn fnTypeReceiver(b: *FuncBuilder, ty: ir.TypeRef) ?ir.TypeRef {
    if (!std.mem.startsWith(u8, ty.name, "Function")) return null;
    const arity = fnTypeArityAlias(b, ty) orelse return null;
    const n: usize = if (arity < 0) 0 else @intCast(arity);
    var hi: usize = ty.args.len;
    while (hi > 0 and ty.args[hi - 1].name.len != 0 and ty.args[hi - 1].name[0] == '#') hi -= 1;
    var lo: usize = 0;
    if (lo < hi and std.mem.eql(u8, ty.args[lo].name, "#suspend")) lo += 1;
    const remaining = hi - lo; // [receiver?] params(n) ret(1)
    if (remaining == n + 2 and lo < hi) {
        const receiver = ty.args[lo];
        if (receiver.name.len != 0 and receiver.name[0] != '#') return receiver;
    }
    return null;
}

fn fnTypeReceiverHead(b: *FuncBuilder, ty: ir.TypeRef) ?[]const u8 {
    return if (fnTypeReceiver(b, ty)) |receiver| receiver.name else null;
}

fn funcDeclaresTypeParam(b: *const FuncBuilder, func: *const Func, name: []const u8) bool {
    const params = b.module.registry.func_type_params.get(func.id) orelse return false;
    for (params.items) |param| {
        if (std.mem.eql(u8, param, name)) return true;
    }
    return false;
}

/// Substitute a receiver-function parameter's direct function type parameter
/// from authoritative call-argument evidence. This is the common
/// `with(receiver, block: T.() -> R)` shape: the block's implicit receiver is
/// the static type of `receiver`, not the unbound declaration name `T`.
fn callBoundLambdaReceiverType(
    b: *FuncBuilder,
    func: *const Func,
    declared_receiver: ir.TypeRef,
    params: []const ir.Param,
    args: []const Expr,
    arg_names: []const ?[]const u8,
    type_args: []const ast.TypeRef,
    call_receiver: ?ir.TypeRef,
) Allocator.Error!ir.TypeRef {
    const head = declared_receiver.name;
    if (!funcDeclaresTypeParam(b, func, head)) {
        // The head can be the ENCLOSING CLASS's type parameter, whose
        // instantiation the call receiver's own type arguments carry:
        // `propertyEquals { }` on a `CompareContext<Map<K, V>>` receiver
        // binds its `T.() -> P` lambda's receiver to `Map<K, V>`.
        if (classParamReceiverInstantiation(b, func, head, call_receiver)) |inst| {
            return inst.clone(b.allocator);
        }
        return declared_receiver.clone(b.allocator);
    }
    if (b.module.registry.func_type_params.get(func.id)) |declared_params| {
        for (declared_params.items, 0..) |param, index| {
            if (!std.mem.eql(u8, param, head)) continue;
            if (index < type_args.len) {
                return loweredOwnedLocalTypeRef(b, &type_args[index]);
            }
            break;
        }
    }
    if (call_receiver) |actual_receiver| {
        if (func.params.len != 0 and
            std.mem.eql(u8, func.params[0].name, "this") and
            std.mem.eql(u8, func.params[0].ty.name, head))
        {
            return actual_receiver.clone(b.allocator);
        }
    }

    var mapping: ?[]const ?usize = null;
    defer if (mapping) |items| b.allocator.free(items);
    if (anyNamedArg(arg_names)) {
        mapping = try mapArgsToParams(b, params, args, arg_names);
        if (mapping == null) return declared_receiver.clone(b.allocator);
    }

    const trailing_lambda = args.len != 0 and
        (args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun);
    var bound: ?ir.TypeRef = null;
    for (args, 0..) |*arg, i| {
        if (arg.* == .Lambda or arg.* == .AnonFun or arg.* == .Spread) continue;
        const param_index: ?usize = if (mapping) |items|
            items[i]
        else if (trailing_lambda and i + 1 == args.len and args.len <= params.len)
            params.len - 1
        else if (i < params.len)
            i
        else
            null;
        const pi = param_index orelse continue;
        if (pi >= params.len) continue;
        const param_ty = params[pi].ty;
        if (param_ty.nullable or param_ty.args.len != 0 or
            !std.mem.eql(u8, param_ty.name, head)) continue;
        const actual = argDeclTypeRefLazy(b, arg) orelse continue;
        if (b.isTypeParam(actual.name)) continue;
        if (bound) |existing| {
            if (!existing.eql(actual)) return declared_receiver.clone(b.allocator);
        } else {
            bound = actual;
        }
    }
    return if (bound) |actual|
        actual.clone(b.allocator)
    else
        declared_receiver.clone(b.allocator);
}

/// `head` as a type parameter of `func`'s ENCLOSING CLASS, instantiated by
/// the call receiver's own type arguments. Answers a borrowed ref into the
/// receiver's arg list; the caller clones. The receiver must name the
/// declaring class itself so its argument list aligns with the class's
/// parameter list, and the instantiation must be concrete.
fn classParamReceiverInstantiation(
    b: *FuncBuilder,
    func: *const Func,
    head: []const u8,
    call_receiver: ?ir.TypeRef,
) ?*const ir.TypeRef {
    const cpt = runtime.envOnce("KLIO_CPT_TRACE") != null;
    // The declared receiver's head is usually the class param's IDENTITY
    // MANGLE, which names its owning class and parameter directly; a plain
    // param name falls back to the declaration's enclosing class.
    var owner: ir.ClassId = undefined;
    var param_name: []const u8 = head;
    if (ir.parseClassTypeParamIdentity(head)) |identity| {
        owner = identity.owner;
        param_name = identity.param;
    } else {
        const sig = b.module.decl_sigs.get(func.id.int()) orelse {
            if (cpt) std.debug.print("[cpt] {s}: no sig\n", .{func.name});
            return null;
        };
        owner = sig.enclosing_class orelse {
            if (cpt) std.debug.print("[cpt] {s}: no enclosing class\n", .{func.name});
            return null;
        };
    }
    if (owner.int() >= b.module.classes.items.len) return null;
    const cls = &b.module.classes.items[owner.int()];
    var index: ?usize = null;
    for (cls.type_params, 0..) |tp, i| {
        if (std.mem.eql(u8, tp, param_name)) {
            index = i;
            break;
        }
    }
    const ti = index orelse {
        if (cpt) std.debug.print("[cpt] {s} param={s}: not in {s} params (n={d})\n", .{ func.name, param_name, cls.name, cls.type_params.len });
        return null;
    };
    const own_recv: ?ir.TypeRef = if (call_receiver == null) b.recvTypeRef() else null;
    const recv: *const ir.TypeRef = if (call_receiver) |*cr| cr else if (own_recv) |*orr| orr else {
        if (cpt) std.debug.print("[cpt] {s} head={s}: no receiver ref\n", .{ func.name, head });
        return null;
    };
    var rhead = std.mem.trimEnd(u8, recv.name, "?");
    if (std.mem.indexOfScalar(u8, rhead, '<')) |lt| rhead = rhead[0..lt];
    rhead = typeHead(rhead);
    if (!std.mem.eql(u8, rhead, cls.name) and !std.mem.eql(u8, rhead, applicability.simpleName(cls.fqn))) {
        if (cpt) std.debug.print("[cpt] {s} head={s}: recv {s} != cls {s}\n", .{ func.name, head, rhead, cls.name });
        return null;
    }
    if (ti >= recv.args.len) {
        if (cpt) std.debug.print("[cpt] {s} head={s}: recv {s} args={d} ti={d}\n", .{ func.name, head, recv.name, recv.args.len, ti });
        return null;
    }
    const inst = &recv.args[ti];
    if (inst.name.len == 0 or b.isTypeParam(inst.name)) {
        if (cpt) std.debug.print("[cpt] {s} head={s}: inst {s} not concrete\n", .{ func.name, head, inst.name });
        return null;
    }
    if (cpt) std.debug.print("[cpt] {s} head={s}: -> {s}\n", .{ func.name, head, inst.name });
    return inst;
}

fn recordCallBoundLambdaReceiver(
    b: *FuncBuilder,
    func: *const Func,
    call_span: ast.Span,
    declared_receiver: ir.TypeRef,
    params: []const ir.Param,
    args: []const Expr,
    arg_names: []const ?[]const u8,
    type_args: []const ast.TypeRef,
    call_receiver: ?ir.TypeRef,
) Allocator.Error!void {
    const resolved = try callBoundLambdaReceiverType(
        b,
        func,
        declared_receiver,
        params,
        args,
        arg_names,
        type_args,
        call_receiver,
    );
    // An answer that is still the UNINSTANTIATED declared parameter — the
    // function's own type param or a class param's identity mangle — must
    // never clobber an instantiated record another resolution pass made.
    if (resolved.eql(declared_receiver) and
        (funcDeclaresTypeParam(b, func, declared_receiver.name) or
            ir.parseClassTypeParamIdentity(declared_receiver.name) != null) and
        b.lambdaArgRecv(call_span) != null)
    {
        var cleanup = resolved;
        cleanup.deinit(b.allocator);
        return;
    }
    if (std.c.getenv("KLIO_LAR_TRACE") != null)
        std.debug.print("[lar-site] site=cbr fn={s} declared={s} resolved={s} s={d}..{d}\n", .{ func.fqn, declared_receiver.name, resolved.name, call_span.start, call_span.end });
    try b.recordLambdaArgRecvOwned(call_span, resolved);
}

/// Record the receiver-type head of each receiver-lambda ARGUMENT so its body
/// owns that receiver even when the call is deferred and no expected type
/// reaches `lowerLambda`. Mirrors `argFnArities`' arg→param alignment.
fn recordLambdaArgReceivers(
    b: *FuncBuilder,
    func: *const Func,
    args: []const Expr,
    arg_names: []const ?[]const u8,
    type_args: []const ast.TypeRef,
    recv_offset: usize,
) Allocator.Error!void {
    return recordLambdaArgReceiversForCallReceiver(
        b,
        func,
        args,
        arg_names,
        type_args,
        null,
        recv_offset,
    );
}

fn recordLambdaArgReceiversForCallReceiver(
    b: *FuncBuilder,
    func: *const Func,
    args: []const Expr,
    arg_names: []const ?[]const u8,
    type_args: []const ast.TypeRef,
    call_receiver: ?ir.TypeRef,
    recv_offset: usize,
) Allocator.Error!void {
    if (args.len == 0 or func.params.len < recv_offset) return;
    for (args) |*a| if (a.* == .Spread) return;
    const params = func.params[recv_offset..];
    if (anyNamedArg(arg_names)) {
        const map = (try mapArgsToParams(b, params, args, arg_names)) orelse return;
        defer b.allocator.free(map);
        for (args, map) |*a, m| {
            if (a.* != .Lambda and a.* != .AnonFun) continue;
            if (m) |pi| if (pi < params.len) {
                if (fnTypeReceiver(b, params[pi].ty)) |receiver| {
                    try recordCallBoundLambdaReceiver(b, func, a.span(), receiver, params, args, arg_names, type_args, call_receiver);
                }
            };
        }
        return;
    }
    // A function-typed VARARG parameter binds EVERY argument in its run.
    // `f(vararg blocks: Sink.() -> Unit)` called with two lambda literals
    // matches neither shape below — two arguments never equal the one
    // declared parameter, nor fit `args.len <= params.len` — so neither
    // literal was recorded. kotlinx-datetime's `alternativeParsing(vararg
    // others: T.() -> Unit, primary: T.() -> Unit)` is the shape RFC_1123
    // parses through.
    for (params, 0..) |p, vp| {
        if (!p.is_vararg) continue;
        const n_after = params.len - vp - 1;
        if (args.len < vp + n_after) break;
        const vararg_end = args.len - n_after;
        if (fnTypeReceiver(b, varargFnElemTy(b, params[vp].ty))) |receiver| {
            var vi: usize = vp;
            while (vi < vararg_end) : (vi += 1) {
                if (args[vi] != .Lambda and args[vi] != .AnonFun) continue;
                try recordCallBoundLambdaReceiver(b, func, args[vi].span(), receiver, params, args, arg_names, type_args, call_receiver);
            }
        }
        var k: usize = 0;
        while (k < n_after) : (k += 1) {
            const ai = vararg_end + k;
            const pi = vp + 1 + k;
            if (ai >= args.len or pi >= params.len) break;
            if (args[ai] != .Lambda and args[ai] != .AnonFun) continue;
            if (fnTypeReceiver(b, params[pi].ty)) |receiver| {
                try recordCallBoundLambdaReceiver(b, func, args[ai].span(), receiver, params, args, arg_names, type_args, call_receiver);
            }
        }
        return;
    }
    const trailing_lambda = args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun;
    if (trailing_lambda and args.len <= params.len) {
        var i: usize = 0;
        while (i + 1 < args.len) : (i += 1) {
            if ((args[i] == .Lambda or args[i] == .AnonFun)) {
                if (fnTypeReceiver(b, params[i].ty)) |receiver| {
                    try recordCallBoundLambdaReceiver(b, func, args[i].span(), receiver, params, args, arg_names, type_args, call_receiver);
                }
            }
        }
        if (fnTypeReceiver(b, params[params.len - 1].ty)) |receiver| {
            try recordCallBoundLambdaReceiver(
                b,
                func,
                args[args.len - 1].span(),
                receiver,
                params,
                args,
                arg_names,
                type_args,
                call_receiver,
            );
        }
    } else if (args.len == params.len) {
        for (args, params) |*a, p| {
            if (a.* != .Lambda and a.* != .AnonFun) continue;
            if (fnTypeReceiver(b, p.ty)) |receiver| {
                try recordCallBoundLambdaReceiver(b, func, a.span(), receiver, params, args, arg_names, type_args, call_receiver);
            }
        }
    }
}

/// A bitmask of which of a `FunctionN`-typed parameter's `arity` value
/// parameters are declared as a broad collection (`Iterable`/`Collection`).
/// Used so a lambda bound to that parameter marks those of its own params
/// broad — then `it + x` over a runtime `Set` produces a `List`, matching the
/// declared (not runtime) receiver type. Only direct `Function{N}` types are
/// decoded (a typealias gives arity but not parameter types → mask 0).
fn fnTypeBroadMask(ty: ir.TypeRef, arity: i16) u32 {
    if (arity <= 0) return 0;
    const n: usize = @intCast(arity);
    if (!std.mem.startsWith(u8, ty.name, "Function")) return 0;
    // The lowered encoding is `[#suspend?] [receiver?] params… ret [#markers]`.
    var hi: usize = ty.args.len;
    while (hi > 0 and ty.args[hi - 1].name.len != 0 and ty.args[hi - 1].name[0] == '#') hi -= 1;
    var lo: usize = 0;
    if (lo < hi and std.mem.eql(u8, ty.args[lo].name, "#suspend")) lo += 1;
    const remaining = hi - lo; // [receiver?] params(n) ret(1)
    var pstart = lo;
    if (remaining == n + 2) {
        pstart = lo + 1; // an explicit receiver precedes the value params
    } else if (remaining != n + 1) {
        return 0; // cannot align
    }
    var mask: u32 = 0;
    var i: usize = 0;
    while (i < n and i < 32 and pstart + i < hi) : (i += 1) {
        if (helpers.isBroadCollectionTypeName(ty.args[pstart + i].name)) {
            mask |= (@as(u32, 1) << @intCast(i));
        }
    }
    return mask;
}

/// Per-argument broad-collection lambda-parameter masks for a call dispatched
/// to `func`, parallel to `args` and aligned exactly like `argFnArities`.
fn argLambdaBroadMasks(b: *FuncBuilder, func: *const Func, args: []const Expr, arg_names: []const ?[]const u8, recv_offset: usize) Allocator.Error!?[]u32 {
    if (args.len == 0) return null;
    for (arg_names) |an| if (an != null) return null;
    for (args) |*a| if (a.* == .Spread) return null;
    if (func.params.len < recv_offset) return null;
    const params = func.params[recv_offset..];
    const out = try b.allocator.alloc(u32, args.len);
    for (out) |*o| o.* = 0;
    const trailing_lambda = args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun;
    if (trailing_lambda and args.len <= params.len) {
        var i: usize = 0;
        while (i + 1 < args.len) : (i += 1) {
            out[i] = fnTypeBroadMask(params[i].ty, fnTypeArityAlias(b, params[i].ty) orelse -1);
        }
        out[args.len - 1] = fnTypeBroadMask(params[params.len - 1].ty, fnTypeArityAlias(b, params[params.len - 1].ty) orelse -1);
    } else if (args.len == params.len) {
        for (params, out) |p, *o| o.* = fnTypeBroadMask(p.ty, fnTypeArityAlias(b, p.ty) orelse -1);
    } else {
        b.allocator.free(out);
        return null;
    }
    return out;
}

/// Whether a callee parameter's declared function type takes only values
/// typed by the callee's own type parameters (`f2t: (T, T) -> T` inside
/// `fun <T : Comparable<T>> ...`). A callable reference in such a slot
/// denotes the GENERIC overload of the referenced name: kotlinc substitutes
/// the call-site type argument, so only the generic candidate applies.
fn fnTypeIsCalleeGeneric(b: *FuncBuilder, func: *const Func, ty: ir.TypeRef, arity: i16) bool {
    if (arity <= 0) return false;
    const tps = b.module.registry.func_type_params.get(func.id) orelse return false;
    if (tps.items.len == 0) return false;
    if (!std.mem.startsWith(u8, ty.name, "Function")) return false;
    const n: usize = @intCast(arity);
    // The lowered encoding is `[#suspend?] [receiver?] params… ret [#markers]`.
    var hi: usize = ty.args.len;
    while (hi > 0 and ty.args[hi - 1].name.len != 0 and ty.args[hi - 1].name[0] == '#') hi -= 1;
    var lo: usize = 0;
    if (lo < hi and std.mem.eql(u8, ty.args[lo].name, "#suspend")) lo += 1;
    const remaining = hi - lo;
    var pstart = lo;
    if (remaining == n + 2) {
        pstart = lo + 1;
    } else if (remaining != n + 1) {
        return false;
    }
    var i: usize = 0;
    while (i < n and pstart + i < hi) : (i += 1) {
        var hit = false;
        for (tps.items) |tp| {
            if (std.mem.eql(u8, ty.args[pstart + i].name, tp)) {
                hit = true;
                break;
            }
        }
        if (!hit) return false;
    }
    return true;
}

/// Per-argument callee-generic function-type flags for a call dispatched to
/// `func`, parallel to `args` and aligned exactly like `argFnArities`.
fn argFnGenericFlags(b: *FuncBuilder, func: *const Func, args: []const Expr, arg_names: []const ?[]const u8, recv_offset: usize) Allocator.Error!?[]bool {
    if (args.len == 0) return null;
    for (arg_names) |an| if (an != null) return null;
    for (args) |*a| if (a.* == .Spread) return null;
    if (func.params.len < recv_offset) return null;
    const params = func.params[recv_offset..];
    const out = try b.allocator.alloc(bool, args.len);
    for (out) |*o| o.* = false;
    const trailing_lambda = args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun;
    if (trailing_lambda and args.len <= params.len) {
        var i: usize = 0;
        while (i + 1 < args.len) : (i += 1) {
            out[i] = fnTypeIsCalleeGeneric(b, func, params[i].ty, fnTypeArityAlias(b, params[i].ty) orelse -1);
        }
        out[args.len - 1] = fnTypeIsCalleeGeneric(b, func, params[params.len - 1].ty, fnTypeArityAlias(b, params[params.len - 1].ty) orelse -1);
    } else if (args.len == params.len) {
        for (params, out) |p, *o| o.* = fnTypeIsCalleeGeneric(b, func, p.ty, fnTypeArityAlias(b, p.ty) orelse -1);
    } else {
        b.allocator.free(out);
        return null;
    }
    return out;
}

/// Pseudo-explicit type args solved from the call site's EXPECTED type: when
/// the declared return's head matches the expected head, its argument count
/// matches, and EVERY one of the callee's type parameters appears as a
/// direct return type argument, each binds to the expected's argument at
/// that position. `compareBy`'s `Comparator<T>` against an expected
/// `Comparator<String>` yields `[String]`; a partial or mismatched shape
/// yields nothing.
fn expectedReturnTypeArgsFor(b: *FuncBuilder, func: *const Func) Allocator.Error!?[]ir.TypeRef {
    const exp = b.peekExpected() orelse return null;
    if (exp.function != null or exp.type_args.len == 0) return null;
    const tps = b.module.registry.func_type_params.get(func.id) orelse return null;
    if (tps.items.len == 0) return null;
    const ret = func.return_ty;
    if (ret.name.len == 0 or ret.args.len == 0) return null;
    if (!std.mem.eql(u8, typeHead(std.mem.trimEnd(u8, ret.name, "?")), exp.name.name)) return null;
    if (exp.type_args.len != ret.args.len) return null;
    const out = try b.allocator.alloc(ir.TypeRef, tps.items.len);
    var filled: usize = 0;
    errdefer {
        for (out[0..filled]) |*t| t.deinit(b.allocator);
        b.allocator.free(out);
    }
    for (tps.items) |tp| {
        var found: ?usize = null;
        var declared_nullable = false;
        for (ret.args, 0..) |ra, ri| {
            var rn = std.mem.trimEnd(u8, ra.name, "?");
            if (std.mem.startsWith(u8, rn, "in#")) rn = rn[3..];
            if (std.mem.startsWith(u8, rn, "out#")) rn = rn[4..];
            if (std.mem.eql(u8, rn, tp)) {
                found = ri;
                declared_nullable = ra.nullable or rn.len != std.mem.trimEnd(u8, ra.name, "?").len or
                    std.mem.endsWith(u8, ra.name, "?");
                break;
            }
        }
        const ri = found orelse {
            for (out[0..filled]) |*t| t.deinit(b.allocator);
            b.allocator.free(out);
            return null;
        };
        const ta = exp.type_args[ri];
        if (ta.is_star) {
            for (out[0..filled]) |*t| t.deinit(b.allocator);
            b.allocator.free(out);
            return null;
        }
        out[filled] = try loweredOwnedLocalTypeRef(b, &ta.ty);
        // A declared `T?` return position already carries the `?`: the
        // binding is the expected argument WITHOUT it (`Comparator<T?>`
        // against `Comparator<String?>` binds T := String, satisfying
        // `T : Any` exactly as kotlinc solves nullsFirst).
        if (declared_nullable) out[filled].nullable = false;
        filled += 1;
    }
    return out;
}

/// PARTIAL bindings solved from the call site's EXPECTED type: each of the
/// callee's type parameters that appears as a direct return type argument
/// binds to the expected's argument at that position; the rest stay unbound
/// (unlike `expectedReturnTypeArgsFor`, which needs every one for the
/// positional explicit-args slot). The caller owns the bindings' types.
fn expectedReturnPartialBindings(b: *FuncBuilder, func: *const Func) Allocator.Error!?[]ir.Module.TypeBinding {
    const exp = b.peekExpected() orelse return null;
    if (exp.function != null or exp.type_args.len == 0) return null;
    const tps = b.module.registry.func_type_params.get(func.id) orelse return null;
    if (tps.items.len == 0) return null;
    const ret = func.return_ty;
    if (ret.name.len == 0 or ret.args.len == 0) return null;
    if (!std.mem.eql(u8, typeHead(std.mem.trimEnd(u8, ret.name, "?")), exp.name.name)) return null;
    if (exp.type_args.len != ret.args.len) return null;
    var out: std.ArrayList(ir.Module.TypeBinding) = .empty;
    errdefer {
        for (out.items) |*bd| {
            var t = bd.ty;
            t.deinit(b.allocator);
        }
        out.deinit(b.allocator);
    }
    for (tps.items) |tp| {
        var found: ?usize = null;
        var declared_nullable = false;
        for (ret.args, 0..) |ra, ri| {
            var rn = std.mem.trimEnd(u8, ra.name, "?");
            if (std.mem.startsWith(u8, rn, "in#")) rn = rn[3..];
            if (std.mem.startsWith(u8, rn, "out#")) rn = rn[4..];
            if (std.mem.eql(u8, rn, tp)) {
                found = ri;
                declared_nullable = ra.nullable or std.mem.endsWith(u8, ra.name, "?");
                break;
            }
        }
        const ri = found orelse continue;
        const ta = exp.type_args[ri];
        if (ta.is_star) continue;
        var ty = try loweredOwnedLocalTypeRef(b, &ta.ty);
        if (declared_nullable) ty.nullable = false;
        try out.append(b.allocator, .{ .name = tp, .ty = ty });
    }
    if (out.items.len == 0) {
        out.deinit(b.allocator);
        return null;
    }
    return try out.toOwnedSlice(b.allocator);
}

fn instantiatedLambdaValueParams(
    b: *FuncBuilder,
    func: *const Func,
    fn_ty: ir.TypeRef,
    type_args: []const ast.TypeRef,
    include_function_receiver: bool,
    recv: ?*const ir.TypeRef,
    shapes: ?[]const applicability.ArgShape,
) Allocator.Error!?[]ir.TypeRef {
    const arity = fnTypeArityAlias(b, fn_ty) orelse return null;
    if (arity < 0) return null;
    const n: usize = @intCast(arity);

    const explicit = try b.allocator.alloc(ir.TypeRef, type_args.len);
    defer {
        for (explicit) |*ty| ty.deinit(b.allocator);
        b.allocator.free(explicit);
    }
    for (type_args, explicit) |*src, *dst| {
        dst.* = try loweredOwnedLocalTypeRef(b, src);
    }
    // An expected type at the call site binds like explicit type args:
    // compareBy's declared `Comparator<T>` against an expected
    // `Comparator<String>` binds T := String, instantiating the selector's
    // `(T) -> ...` so the literal's parameter types.
    var expected_explicit: ?[]ir.TypeRef = null;
    defer if (expected_explicit) |ea| {
        for (ea) |*t| t.deinit(b.allocator);
        b.allocator.free(ea);
    };
    if (type_args.len == 0) {
        expected_explicit = try expectedReturnTypeArgsFor(b, func);
    }
    const explicit_eff: []const ir.TypeRef = if (explicit.len != 0)
        explicit
    else
        (expected_explicit orelse explicit);
    // A PARTIAL expected binding still instantiates the lambda slot's
    // inputs: two-arg `compareBy(comparator, selector)` declares [T, K]
    // and its `Comparator<T>` return binds only T from the expected type —
    // exactly the parameter the selector's `it` needs; K stays bare and
    // the per-slot guard below handles it.
    var fn_ty_sub: ?ir.TypeRef = null;
    defer if (fn_ty_sub) |*t| t.deinit(b.allocator);
    if (type_args.len == 0 and expected_explicit == null) {
        if (try expectedReturnPartialBindings(b, func)) |binds| {
            defer {
                for (binds) |*bd| {
                    var t = bd.ty;
                    t.deinit(b.allocator);
                }
                b.allocator.free(binds);
            }
            var scratch0 = std.heap.ArenaAllocator.init(b.allocator);
            defer scratch0.deinit();
            if (ir.Module.substituteBoundType(scratch0.allocator(), fn_ty, binds) catch null) |sub| {
                fn_ty_sub = try sub.clone(b.allocator);
            }
        }
    }
    const fn_ty_eff: ir.TypeRef = fn_ty_sub orelse fn_ty;
    var instantiated = blk: {
        // The ENGINE: solve every binding the call site offers — receiver,
        // typed value arguments, explicit type args — in one pass and
        // substitute the lambda's declared fn type through it. The bare-tp
        // guard below refuses whatever stays unsubstituted.
        engine: {
            if (std.mem.eql(u8, runtime.envOnce("KLIO_ENGINE_LAMBDA") orelse "1", "0")) break :engine;
            const sh = shapes orelse break :engine;
            var scratch = std.heap.ArenaAllocator.init(b.allocator);
            defer scratch.deinit();
            const a = scratch.allocator();
            const solved = (b.module.solveCallBindings(
                a,
                func.id,
                func,
                if (recv) |r| r.* else null,
                null,
                sh,
                explicit_eff,
                false,
            ) catch break :engine) orelse break :engine;
            if (solved.bindings.len == 0) break :engine;
            const substituted = ir.Module.substituteBoundType(a, fn_ty_eff, solved.bindings) catch break :engine;
            break :blk try substituted.clone(b.allocator);
        }
        // With no explicit type args, the ACTUAL receiver may bind the
        // callee's params (`Iterable<String>.count` binds T := String).
        if (type_args.len == 0) {
            if (recv) |r| {
                // Partial substitution: a return-only parameter (`R` in
                // `minOfWith`'s selector) must not block binding the ones
                // the receiver proves; the bare-tp guard below refuses any
                // entry that stayed unsubstituted.
                if (try b.module.instantiatedTypeFromReceiverPartial(
                    b.allocator,
                    func.id,
                    fn_ty_eff,
                    r.*,
                )) |t| break :blk t;
            }
        }
        break :blk (try b.module.instantiatedDeclarationType(
            b.allocator,
            func.id,
            fn_ty_eff,
            explicit_eff,
        )) orelse try fn_ty_eff.clone(b.allocator);
    };
    defer instantiated.deinit(b.allocator);

    var hi = instantiated.args.len;
    while (hi > 0 and instantiated.args[hi - 1].name.len != 0 and
        instantiated.args[hi - 1].name[0] == '#') hi -= 1;
    var lo: usize = 0;
    if (lo < hi and std.mem.eql(u8, instantiated.args[lo].name, "#suspend")) lo += 1;
    const remaining = hi - lo;
    const has_receiver = remaining == n + 2;
    if (!has_receiver and remaining != n + 1) return null;
    const include_receiver = has_receiver and include_function_receiver;
    const start = lo + @intFromBool(has_receiver and !include_receiver);
    const count = n + @intFromBool(include_receiver);
    if (count == 0 and !include_function_receiver) return null;

    const out = try b.allocator.alloc(ir.TypeRef, count);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |*ty| ty.deinit(b.allocator);
        b.allocator.free(out);
    }
    // A slice that still quotes one of the CALLEE's own type parameters is
    // not an answer: the head names nothing in the receiving scope, and
    // recording it feeds the no-class bucket and disproves candidates a
    // null leaves open (the splice-inheritance rule). Refuse the whole
    // slice when any entry's head stayed unsubstituted.
    const callee_tps = b.module.registry.func_type_params.get(func.id);
    for (out, instantiated.args[start .. start + count]) |*dst, src| {
        const h = typeHead(std.mem.trimEnd(u8, src.name, "?"));
        // A star-erased head names nothing either — the engine's erasure
        // marks an UNSOLVED parameter, which is a null answer here.
        if (std.mem.eql(u8, h, "*")) {
            for (out[0..initialized]) |*ty| ty.deinit(b.allocator);
            b.allocator.free(out);
            return null;
        }
        if (callee_tps) |tps| {
            for (tps.items) |tp| {
                if (std.mem.eql(u8, tp, h)) {
                    for (out[0..initialized]) |*ty| ty.deinit(b.allocator);
                    b.allocator.free(out);
                    return null;
                }
            }
        }
        dst.* = try src.clone(b.allocator);
        initialized += 1;
    }
    return out;
}

fn deinitArgLambdaParamTypes(
    allocator: Allocator,
    types: []?[]ir.TypeRef,
) void {
    for (types) |maybe_params| {
        if (maybe_params) |params| {
            for (params) |*ty| ty.deinit(allocator);
            allocator.free(params);
        }
    }
    allocator.free(types);
}

/// The receiver to substitute a generic callee's params from: a declared
/// receiver carrying ARGUMENTS is authoritative; a bare type-param head
/// resolves through its full bound ref when one was recorded
/// (`T : Iterable<String>` answers `Iterable<String>`); a head-only
/// receiver substitutes nothing.
fn substitutionRecv(b: *FuncBuilder, declared: ?*const ir.TypeRef) ?*const ir.TypeRef {
    const d = declared orelse return null;
    var head = std.mem.trimEnd(u8, d.name, "?");
    if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
    if (b.typeParamBoundRef(typeHead(head))) |ref| return ref;
    if (d.args.len != 0) return d;
    if (std.mem.eql(u8, runtime.envOnce("KLIO_SUBST_NONGEN") orelse "1", "0")) return null;
    // A head-only receiver naming a NON-GENERIC class is complete: the head
    // is the whole type, so `SlotWriter.let { writer -> }` binds
    // `T := SlotWriter` exactly. Only a generic class's bare head (a `List`
    // missing its element) says nothing.
    const cid = (if (std.mem.indexOfScalar(u8, head, '.') != null)
        b.module.classIdByFqn(head)
    else
        b.module.uniqueClassIdBySimpleName(typeHead(head))) orelse return null;
    if (cid.int() >= b.module.classes.items.len) return null;
    if (b.module.classes.items[cid.int()].type_params.len == 0) return d;
    return null;
}

/// Instantiated expected value-parameter types for each lambda argument,
/// aligned through the same positional/named/trailing-lambda map as arity.
fn argLambdaParamTypes(
    b: *FuncBuilder,
    func: *const Func,
    args: []const Expr,
    arg_names: []const ?[]const u8,
    type_args: []const ast.TypeRef,
    recv_offset: usize,
) Allocator.Error!?[]?[]ir.TypeRef {
    applyExpectedLiteralKindsToArgs(b, func, args, arg_names, recv_offset);
    return argLambdaParamTypesRecv(b, func, args, arg_names, type_args, recv_offset, null);
}

fn argLambdaParamTypesRecv(
    b: *FuncBuilder,
    func: *const Func,
    args: []const Expr,
    arg_names: []const ?[]const u8,
    type_args: []const ast.TypeRef,
    recv_offset: usize,
    recv: ?*const ir.TypeRef,
) Allocator.Error!?[]?[]ir.TypeRef {
    if (runtime.envOnce("KLIO_ALPT")) |want| {
        if (std.mem.eql(u8, want, func.name)) {
            std.debug.print("[alpt] {s}#{d} nargs={d} nparams={d} off={d} p_last={s} p_last_args={d}\n", .{
                func.fqn,
                func.id.int(),
                args.len,
                func.params.len,
                recv_offset,
                if (func.params.len != 0) func.params[func.params.len - 1].ty.name else "-",
                if (func.params.len != 0) func.params[func.params.len - 1].ty.args.len else 0,
            });
        }
    }
    if (args.len == 0 or func.params.len < recv_offset) return null;
    for (args) |*arg| if (arg.* == .Spread) return null;
    // One shape build per call: the engine consumes value-argument
    // evidence alongside the receiver and explicit type args.
    var lam_shape_set = try buildStaticReturnArgShapes(b, args, arg_names);
    defer lam_shape_set.deinit(b.allocator);
    const lam_shapes = lam_shape_set.shapes;
    const params = func.params[recv_offset..];
    const out = try b.allocator.alloc(?[]ir.TypeRef, args.len);
    for (out) |*slot| slot.* = null;
    errdefer deinitArgLambdaParamTypes(b.allocator, out);
    var any = false;
    // Lambda literals bound to a `-> Unit` parameter return Unit whatever
    // their tail expression yields; the mask rides the same per-argument
    // channel as the instantiated parameter types.
    const unit_mask = try b.allocator.alloc(bool, args.len);
    for (unit_mask) |*u| u.* = false;
    if (b.pending_arg_lambda_unit) |m| b.allocator.free(m);
    b.pending_arg_lambda_unit = unit_mask;

    if (anyNamedArg(arg_names)) {
        const mapping = (try mapArgsToParams(b, params, args, arg_names)) orelse {
            b.allocator.free(out);
            return null;
        };
        defer b.allocator.free(mapping);
        for (args, mapping, out, 0..) |*arg, mapped, *slot, ai| {
            const callable_ref = arg.* == .PropertyRef or arg.* == .MemberRef;
            if (arg.* != .Lambda and arg.* != .AnonFun and !callable_ref) continue;
            const pi = mapped orelse continue;
            if (arg.* == .Lambda and fnTypeReturnsUnit(b, params[pi].ty)) unit_mask[ai] = true;
            slot.* = try instantiatedLambdaValueParams(
                b,
                func,
                params[pi].ty,
                type_args,
                callable_ref,
                recv,
                lam_shapes,
            );
            any = any or slot.* != null;
        }
    } else {
        const trailing_lambda = args[args.len - 1] == .Lambda or
            args[args.len - 1] == .AnonFun;
        for (args, out, 0..) |*arg, *slot, i| {
            const callable_ref = arg.* == .PropertyRef or arg.* == .MemberRef;
            if (arg.* != .Lambda and arg.* != .AnonFun and !callable_ref) continue;
            const pi: ?usize = if (trailing_lambda and i + 1 == args.len and
                args.len <= params.len)
                params.len - 1
            else if (i < params.len)
                i
            else
                null;
            if (pi) |param_index| {
                if (arg.* == .Lambda and fnTypeReturnsUnit(b, params[param_index].ty)) unit_mask[i] = true;
                slot.* = try instantiatedLambdaValueParams(
                    b,
                    func,
                    params[param_index].ty,
                    type_args,
                    callable_ref,
                    recv,
                    lam_shapes,
                );
                any = any or slot.* != null;
            }
        }
    }
    if (runtime.envOnce("KLIO_ALPT")) |want| {
        if (std.mem.eql(u8, want, func.name)) {
            for (out, 0..) |slot, i| {
                if (slot) |tys| {
                    for (tys) |t| std.debug.print("[alpt-slot] {s}#{d} arg{d} ty={s}\n", .{ func.fqn, func.id.int(), i, t.name });
                }
            }
        }
    }
    if (!any) {
        b.allocator.free(out);
        return null;
    }
    return out;
}

/// The unique body-bearing generic overload of `name` with `arity` value
/// params (every one typed by the func's own type parameters), or null when
/// none or several exist. The target a callee-generic `::name` slot binds.
///
/// Reads the placed `Func` when phase 2 has lowered the body, else the
/// phase-1 header metadata (`decl_user_sig` + `decl_ast_body`) — the
/// in-memory two-phase build lowers user files while the stdlib funcs are
/// still header stubs, and the answer must not depend on that state.
fn genericRefTarget(
    b: *FuncBuilder,
    name: []const u8,
    caller_file: ir.FileId,
    arity: usize,
) Allocator.Error!?FuncId {
    const candidates = try b.module.bareCallCandidates(
        b.allocator,
        name,
        caller_file,
    );
    defer b.allocator.free(candidates);
    var found: ?FuncId = null;
    cands: for (candidates) |id| {
        const f = b.module.funcById(id) orelse continue;
        // An extension (a placed leading `this`, or a header stub's
        // synthesized receiver param) never binds a bare `::name`.
        if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) continue;
        const tps = b.module.registry.func_type_params.get(id) orelse continue;
        if (tps.items.len == 0) continue;
        if (f.hasBody()) {
            if (f.params.len != arity or arity == 0) continue;
            if (f.params[f.params.len - 1].is_vararg) continue;
            for (f.params) |*p| {
                if (!nameInList(p.ty.name, tps.items)) continue :cands;
            }
        } else {
            // Phase-1 header stub: judge by the declared metadata, so the
            // answer is the same whether the body is placed yet or not.
            if (!b.module.decl_ast_body.contains(id.int())) continue;
            const sig = b.module.decl_user_sig.get(id.int()) orelse continue;
            if (sig.len != arity or arity == 0) continue;
            if (b.module.decl_user_arity.get(id.int())) |da| {
                if (da.has_vararg) continue;
            }
            for (sig) |*ty| {
                if (!nameInList(ty.name, tps.items)) continue :cands;
            }
        }
        if (found != null) return null;
        found = id;
    }
    return found;
}

const CallableRefArgShapes = struct {
    shapes: []applicability.ArgShape,
    owned_types: []TypeRef = &.{},

    fn deinit(self: *@This(), allocator: Allocator) void {
        for (self.owned_types) |*ty| ty.deinit(allocator);
        if (self.owned_types.len != 0) allocator.free(self.owned_types);
        allocator.free(self.shapes);
    }
};

/// Expected argument types for a callable reference. A typed local initializer
/// contributes its source function type; an argument position contributes the
/// callee-instantiated lambda parameter types, falling back to arity alone.
fn callableRefArgShapes(
    b: *FuncBuilder,
    ref_arity: i16,
) Allocator.Error!?CallableRefArgShapes {
    if (b.pending_ref_lambda_param_types) |types| {
        const shapes = try b.allocator.alloc(applicability.ArgShape, types.len);
        for (types, shapes) |ty, *shape| {
            shape.* = .{ .ty = ty, .ty_authoritative = true };
        }
        return .{ .shapes = shapes };
    }
    if (b.peekExpected()) |expected| {
        if (expected.function) |ft| {
            const types = try b.allocator.alloc(TypeRef, ft.params.len);
            var initialized: usize = 0;
            errdefer {
                for (types[0..initialized]) |*ty| ty.deinit(b.allocator);
                b.allocator.free(types);
            }
            for (ft.params, types) |*param, *ty| {
                ty.* = try loweredOwnedLocalTypeRef(b, param);
                initialized += 1;
            }
            const shapes = try b.allocator.alloc(applicability.ArgShape, types.len);
            for (types, shapes) |ty, *shape| {
                shape.* = .{ .ty = ty, .ty_authoritative = true };
            }
            return .{ .shapes = shapes, .owned_types = types };
        }
    }
    if (ref_arity < 0) return null;
    const shapes = try b.allocator.alloc(applicability.ArgShape, @intCast(ref_arity));
    @memset(shapes, .{});
    return .{ .shapes = shapes };
}

fn resolveExtensionRefTarget(
    b: *FuncBuilder,
    receiver: *const Expr,
    name: ast.Ident,
    ref_shapes: *const CallableRefArgShapes,
) Allocator.Error!?FuncId {
    const receiver_ty = argDeclTypeRefLazy(b, receiver) orelse return null;
    const unbound = receiver.* == .Path and
        receiver.Path.segments.len == 1 and
        b.resolve(receiver.Path.segments[0].name) == null and
        !b.knowsOuter(receiver.Path.segments[0].name) and
        b.module.classIdIndexed(
            receiver.Path.segments[0].name,
            b.self_package,
            name.span.file,
        ) != null;
    const args = if (unbound) blk: {
        if (ref_shapes.shapes.len == 0) return null;
        break :blk ref_shapes.shapes[1..];
    } else ref_shapes.shapes;
    const trace_ref = if (runtime.envOnce("KLIO_BARE_TRACE")) |wanted|
        std.mem.eql(u8, wanted, name.name)
    else
        false;
    if (trace_ref) {
        std.debug.print("[refext] {s} unbound={} expected={d} args={d}", .{
            name.name,
            unbound,
            ref_shapes.shapes.len,
            args.len,
        });
        for (ref_shapes.shapes) |shape| {
            std.debug.print(" {s}", .{if (shape.ty) |ty| ty.name else "?"});
        }
        std.debug.print("\n", .{});
    }

    if (staticTypeClassId(b, receiver_ty)) |owner| {
        if (b.module.resolveMemberCall(owner, name.name, args, .{
            .caller_file = name.span.file,
            .lexical_owner = if (b.ownerClass()) |owner_name|
                b.module.classId(owner_name)
            else
                null,
            .receiver_type = receiver_ty,
        }).applicable) return null;
    }

    const implicit_owners = try b.collectImplicitReceiverTower(
        b.allocator,
        eagerLambdaRecvHead(b),
    );
    defer b.allocator.free(implicit_owners);
    const resolution = b.module.resolveExtensionCall(
        name.name,
        receiver_ty,
        args,
        .{
            .caller_file = name.span.file,
            .caller_package = b.module.packageOfFile(name.span.file) orelse
                b.self_package,
            .implicit_dispatch_owners = implicit_owners,
            .lexical_owner = b.ownerClass(),
            .call_name = name.name,
        },
    );
    const target = resolution.target orelse return null;
    if (trace_ref) std.debug.print("[refext] {s} -> #{d}\n", .{
        name.name,
        target.int(),
    });
    const func = b.module.funcById(target) orelse return null;
    const kind = if (b.module.decl_sigs.get(target.int())) |decl|
        decl.kind
    else
        func.kind;
    if (kind != .top_level_extension) return null;
    return target;
}

fn nameInList(name: []const u8, list: []const []const u8) bool {
    for (list) |n| {
        if (std.mem.eql(u8, name, n)) return true;
    }
    return false;
}

/// The constructor-call half of the P12 shape repair: for each lambda
/// argument bound to a primary-constructor parameter with a declared
/// composable arity, re-shape it against that arity (inserting the implicit
/// `it` a bare-pair-shaped sink lambda dropped). Alignment mirrors
/// `ctorArgFnArities`: an unnamed trailing lambda binds the last
/// function-typed parameter; leading positionals map 1:1 when unnamed.
fn transformCtorComposableArgs(b: *FuncBuilder, class_id: ir.ClassId, args: []const Expr, arg_names: []const ?[]const u8) Allocator.Error!void {
    if (args.len == 0) return;
    for (args) |*a| if (a.* == .Spread) return;
    if (!allNull(arg_names)) return;
    if (class_id.int() >= b.module.classes.items.len) return;
    const cls = &b.module.classes.items[class_id.int()];
    const params = cls.primary_params;
    const trailing_lambda = args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun;
    for (args, 0..) |*arg, i| {
        const pi: ?usize = blk: {
            if (trailing_lambda and i == args.len - 1) {
                var k = params.len;
                while (k > 0) : (k -= 1) {
                    if (fnTypeArityAlias(b, params[k - 1].ty) != null) break :blk k - 1;
                }
                break :blk null;
            }
            break :blk if (i < params.len) i else null;
        };
        const p = pi orelse continue;
        const expected = params[p].composable_arity orelse continue;
        const expected_slots: u8 = expected +| params[p].composable_recv_slots;
        _ = try compose_pass.transformResolvedComposableLambda(
            b.allocator,
            @constCast(arg),
            expected_slots,
            cls.name,
            false,
        );
    }
}

/// `argFnArities` for a constructor call: the per-argument expected lambda
/// arity from the class's primary-constructor parameters. A `T.() -> R`
/// receiver-lambda parameter reports arity 0 so the lambda drops its `it` and
/// resolves bare members through the receiver bound at invocation (the same as
/// a function-call argument).
fn ctorArgFnArities(b: *FuncBuilder, class_id: ir.ClassId, args: []const Expr, arg_names: []const ?[]const u8) Allocator.Error!?[]i16 {
    if (args.len == 0) return null;
    for (args) |*a| if (a.* == .Spread) return null;
    if (class_id.int() >= b.module.classes.items.len) return null;
    const params = b.module.classes.items[class_id.int()].primary_params;
    const out = try b.allocator.alloc(i16, args.len);
    for (out) |*o| o.* = -1;
    const trailing_lambda = args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun;
    if (trailing_lambda) {
        // An unnamed trailing lambda binds the LAST function-typed parameter
        // (intervening defaulted/named params are skipped) — find it and take
        // its arity, so `Op(desc, named = x) { member() }` still detects the
        // receiver lambda.
        var pi = params.len;
        while (pi > 0) : (pi -= 1) {
            if (fnTypeArityAlias(b, params[pi - 1].ty)) |ar| {
                out[args.len - 1] = ar;
                break;
            }
        }
    }
    // Leading positional args map 1:1 only when there are no named args.
    if (allNull(arg_names) and args.len <= params.len) {
        var i: usize = 0;
        const lead: usize = if (trailing_lambda) args.len - 1 else args.len;
        while (i < lead) : (i += 1) out[i] = fnTypeArityAlias(b, params[i].ty) orelse -1;
    }
    return out;
}

/// When an unnamed trailing lambda binds a constructor's function-typed
/// parameter that sits *after* one or more defaulted parameters (`Op("d") {…}`
/// for `Op(d: String, flag: Boolean = true, f: C.() -> Unit)`), positional
/// binding would put the lambda in the defaulted slot. Returns an arg-name
/// vector that names the trailing lambda with the function parameter so the
/// named-arg constructor path realigns it (the gap params take their defaults).
/// Null when no realignment is needed.
fn ctorRealignedArgNames(b: *FuncBuilder, class_id: ir.ClassId, args: []const Expr, arg_names: []const ?[]const u8) Allocator.Error!?[]?[]const u8 {
    if (args.len == 0 or !allNull(arg_names)) return null;
    if (!(args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun)) return null;
    if (class_id.int() >= b.module.classes.items.len) return null;
    const params = b.module.classes.items[class_id.int()].primary_params;
    if (args.len > params.len) return null;
    var fn_idx: ?usize = null;
    var pi = params.len;
    while (pi > 0) : (pi -= 1) {
        if (fnTypeArityAlias(b, params[pi - 1].ty) != null) {
            fn_idx = pi - 1;
            break;
        }
    }
    const fi = fn_idx orelse return null;
    const lead = args.len - 1; // positional args preceding the trailing lambda
    if (fi <= lead) return null; // the lambda already aligns with (or past) the fn param
    // Every skipped parameter must be defaultable.
    var k = lead;
    while (k < fi) : (k += 1) if (!params[k].has_default and params[k].default == null) return null;
    const out = try b.allocator.alloc(?[]const u8, args.len);
    for (out) |*o| o.* = null;
    out[args.len - 1] = params[fi].name;
    return out;
}

fn lowerPostfix(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const pf = expr.Postfix;
    const inner = pf.expr;
    switch (pf.op) {
        .NotNull => {
            const s = try lowerExpr(b, inner);
            const dst = b.allocReg();
            try b.push(.{ .NotNullAssert = .{ .dst = dst, .src = s } });
            return dst;
        },
        .Inc, .Dec => {
            const uo: UnOp = if (pf.op == .Inc) .Inc else .Dec;
            // Index target: evaluate receiver + keys once.
            if (inner.* == .Index) {
                const ix = inner.Index;
                const recv = try lowerReceiver(b, ix.receiver);
                const n_keys = ix.args.len;
                const key_start = b.allocReg();
                const key_slots = try b.allocator.alloc(Reg, if (n_keys == 0) 1 else n_keys);
                defer b.allocator.free(key_slots);
                key_slots[0] = key_start;
                var k: usize = 1;
                while (k < n_keys) : (k += 1) key_slots[k] = b.allocReg();
                const val_slot = b.allocReg();
                for (ix.args, 0..) |*arg, i| {
                    const r = try lowerExpr(b, arg);
                    try b.push(.{ .Move = .{ .dst = key_slots[i], .src = r } });
                }
                const old = b.allocReg();
                const get_nm = try b.module.internConst(b.allocator, .{ .String = "get" });
                try b.push(.{ .CallMember = .{
                    .dst = old,
                    .receiver = recv,
                    .name = get_nm,
                    .args = key_start,
                    .n_args = @intCast(n_keys),
                    .arg_names = &.{},
                } });
                const new = b.allocReg();
                try b.push(.{ .UnOp = .{ .dst = new, .op = uo, .operand = old } });
                try b.push(.{ .Move = .{ .dst = val_slot, .src = new } });
                const set_dst = b.allocReg();
                const set_nm = try b.module.internConst(b.allocator, .{ .String = "set" });
                try b.push(.{ .CallMember = .{
                    .dst = set_dst,
                    .receiver = recv,
                    .name = set_nm,
                    .args = key_start,
                    .n_args = @as(u32, @intCast(n_keys)) + 1,
                    .arg_names = &.{},
                } });
                return old;
            }
            // Safe-target postfix (`parent?.count++`): the receiver
            // evaluates ONCE and a null receiver skips the whole
            // get/inc/store (Kotlin's `?.` short-circuit) — running the
            // unguarded sequence incremented `null` at the chain's root.
            if (inner.* == .Member and inner.Member.safe) {
                const m = inner.Member;
                const recv = try lowerReceiver(b, m.receiver);
                const null_r = try b.emitConst(.Null);
                const is_null = b.allocReg();
                try b.push(.{ .BinOp = .{ .dst = is_null, .op = .Eq, .lhs = recv, .rhs = null_r } });
                const then_b = try b.allocBlock();
                const else_b = try b.allocBlock();
                const join = try b.allocBlock();
                const old = b.allocReg();
                b.terminate(.{ .Branch = .{ .cond = is_null, .t = then_b, .f = else_b } });
                b.switchTo(then_b);
                const n0 = try b.emitConst(.Null);
                try b.push(.{ .Move = .{ .dst = old, .src = n0 } });
                b.terminate(.{ .Goto = join });
                b.switchTo(else_b);
                const field = try b.module.internConst(b.allocator, .{ .String = m.name.name });
                const got = b.allocReg();
                try b.push(.{ .GetField = .{ .dst = got, .receiver = recv, .field = field } });
                const new = b.allocReg();
                try b.push(.{ .UnOp = .{ .dst = new, .op = uo, .operand = got } });
                try b.push(.{ .SetField = .{ .receiver = recv, .field = field, .value = new } });
                try b.push(.{ .Move = .{ .dst = old, .src = got } });
                b.terminate(.{ .Goto = join });
                b.switchTo(join);
                return old;
            }
            const s = try lowerExpr(b, inner);
            // Snapshot the old value before mutating the storage slot.
            const old = b.allocReg();
            try b.push(.{ .Move = .{ .dst = old, .src = s } });
            const new = b.allocReg();
            try b.push(.{ .UnOp = .{ .dst = new, .op = uo, .operand = old } });
            // Postfix `x++` evaluates to the OLD value but writes the NEW
            // value back through the shared write-back decision.
            try stmt_mod.storeCombinedToTarget(b, inner, new);
            return old;
        },
    }
}

fn lowerLabeled(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const lab = expr.Labeled;
    const inner = lab.expr;
    const label = lab.label;
    switch (inner.*) {
        .While => |w| {
            const header = try b.allocBlock();
            const body_blk = try b.allocBlock();
            const exit = try b.allocBlock();
            b.terminate(.{ .Goto = header });
            b.switchTo(header);
            const c = try lowerExpr(b, w.cond);
            b.terminate(.{ .Branch = .{ .cond = c, .t = body_blk, .f = exit } });
            b.switchTo(body_blk);
            try b.pushLoop(label.name, header, exit);
            var lw_not_null: std.ArrayList(build.FuncBuilder.NarrowedLocal) = .empty;
            defer lw_not_null.deinit(b.allocator);
            try narrowNullCheckAll(b, w.cond, true, &lw_not_null);
            _ = try lowerExpr(b, w.body);
            var lwn = lw_not_null.items.len;
            while (lwn > 0) : (lwn -= 1) b.restoreLocal(lw_not_null.items[lwn - 1]);
            b.popLoop();
            b.terminate(.{ .Goto = header });
            b.switchTo(exit);
            return b.emitConst(.Unit);
        },
        .For => |f| return lowerForLabeled(b, f.vars, f.iter, f.body, label.name),
        .DoWhile => |w| {
            const body_blk = try b.allocBlock();
            const exit = try b.allocBlock();
            b.terminate(.{ .Goto = body_blk });
            b.switchTo(body_blk);
            try b.pushLoop(label.name, body_blk, exit);
            // Kotlin scopes the do-body's declarations into the `while`
            // condition, so when the body is a block, lower its statements and
            // the condition in one shared scope; otherwise the block's own
            // scope closes first and a `do { val x = … } while (x …)` local
            // resolves as a stray global.
            if (w.body) |body| {
                if (body.* == .Block) {
                    const block = &body.Block;
                    try b.pushScope();
                    try hoistMutualLocalFns(b, block);
                    for (block.stmts) |*stmt| _ = try lowerStmt(b, stmt);
                    b.popLoop();
                    const c = try lowerExpr(b, w.cond);
                    try b.popScope();
                    b.terminate(.{ .Branch = .{ .cond = c, .t = body_blk, .f = exit } });
                    b.switchTo(exit);
                    return b.emitConst(.Unit);
                }
                _ = try lowerExpr(b, body);
            }
            b.popLoop();
            const c = try lowerExpr(b, w.cond);
            b.terminate(.{ .Branch = .{ .cond = c, .t = body_blk, .f = exit } });
            b.switchTo(exit);
            return b.emitConst(.Unit);
        },
        // An explicit label on a lambda / anonymous function literal
        // (`sc@ { … }`) names that body for `return@sc`. It overrides any
        // implicit callee-derived label `lowerExpr` would otherwise arm,
        // so the lambda's own `implicit_label` is the explicit one.
        .Lambda, .AnonFun => {
            b.pending_lambda_label = label.name;
            return lowerExpr(b, inner);
        },
        else => return lowerExpr(b, inner),
    }
}

// -------------------------------------------------------------------------
// Call lowering — the long overload-resolution ladder.
// -------------------------------------------------------------------------

pub fn lastArgIsLambda(args: []const Expr) bool {
    if (args.len == 0) return false;
    return args[args.len - 1] == .Lambda;
}

/// Last `.`-separated segment of a (possibly qualified) type name.
fn lastTypeSegment(name: []const u8) []const u8 {
    if (std.mem.lastIndexOfScalar(u8, name, '.')) |i| return name[i + 1 ..];
    return name;
}

/// Whether any same-simple-name function is an extension whose declared
/// receiver type is compatible with the spliced receiver's type chain
/// (`chain`, the receiver simple-name plus its supertypes). Distinguishes
/// a bare member/extension call on the spliced receiver
/// (`receiveNullable(...)` — applies to that receiver) from a bare call
/// whose extension namesakes target unrelated types (`maxOf(a, b)` inside
/// `Buffer.indexOf` — its only extension overloads are `Iterable.maxOf` /
/// array `maxOf`, none applies to `Buffer`, so the call binds the
/// package-level `maxOf(Int, Int)`). Only the former dispatches on the
/// splice's bound `this`; the latter falls through to the bare-name path.
/// A null `chain` (no receiver type narrowing available) admits any
/// extension namesake, preserving the prior receiver-agnostic behavior.
/// Whether any inline candidate for `name` declares a REIFIED type
/// parameter. Such a call can only run as a SPLICE (the runtime walk
/// cannot instantiate `T`), so no dispatch-deferring arm may claim it.
fn nameHasReifiedInlineCandidate(name: []const u8) bool {
    const cands = inline_state.candidatesForName(name) orelse return false;
    for (cands) |cf| {
        for (cf.type_params) |tp| {
            if (tp.is_reified) return true;
        }
    }
    return false;
}

fn nameHasReceiverCandidate(b: *FuncBuilder, name: []const u8, chain: ?[]const []const u8) bool {
    for (b.module.funcsBySimpleName(name)) |fid| {
        const idx = fid.int();
        const f = b.module.funcById(FuncId.from(idx)) orelse continue;
        if (f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this")) continue;
        const recv_ty = lastTypeSegment(f.params[0].ty.name);
        const ch = chain orelse return true;
        for (ch) |c| {
            if (std.mem.eql(u8, lastTypeSegment(c), recv_ty)) return true;
        }
    }
    return false;
}

fn lastArgIsLambdaOrAnon(args: []const Expr) bool {
    if (args.len == 0) return false;
    const last = args[args.len - 1];
    return last == .Lambda or last == .AnonFun;
}

/// Declared parameter arity of a trailing lambda/anon-fun argument, or
/// `null` when the last argument is neither. A zero-`->` `{ … }` (its `it`
/// injected by the parser) reports 0 — the literal declares no parameters,
/// so overload resolution treats it as a `() -> R` handler.
fn trailingLambdaArity(args: []const Expr) ?usize {
    if (args.len == 0) return null;
    return switch (args[args.len - 1]) {
        .Lambda => |l| if (l.implicit_it) 0 else l.params.len,
        .AnonFun => |af| af.params.len,
        else => null,
    };
}

/// The local `name` holds a value whose declared type is never invokable:
/// a primitive/String/Unit, or a class whose complete hierarchy record
/// declares no `invoke`. An unknown or function-typed local stays callable.
fn localValueNotInvokable(b: *FuncBuilder, name: []const u8) bool {
    const t = b.localDeclTypeRef(name) orelse return false;
    if (std.mem.startsWith(u8, t.name, "Function") or std.mem.startsWith(u8, t.name, "kotlin.Function")) return false;
    var head = std.mem.trimEnd(u8, t.name, "?");
    if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
    if (std.mem.startsWith(u8, head, "kotlin.")) head = head["kotlin.".len..];
    const plain = [_][]const u8{ "Int", "Long", "Short", "Byte", "Double", "Float", "Boolean", "Char", "String", "Unit", "UInt", "ULong", "UShort", "UByte" };
    for (plain) |p| {
        if (std.mem.eql(u8, head, p)) return true;
    }
    if (head.len <= 2 and head.len != 0 and std.ascii.isUpper(head[0])) return false;
    if (std.mem.eql(u8, head, "Any") or std.mem.eql(u8, head, "Nothing")) return false;
    const hs = b.module.registry.hierarchy_shadow_names.get(head) orelse return false;
    if (!hs.complete) return false;
    return !hs.names.contains("invoke");
}

/// The receiver's statically known class resolves a member named `name`
/// that binds these arguments (the registered member resolution proves a
/// unique target).
fn receiverConcreteMemberTakes(b: *FuncBuilder, receiver: *const Expr, name: []const u8, args: []const Expr, arg_names: []const ?[]const u8) Allocator.Error!bool {
    const head = (try inline_call.gateReceiverHead(b, receiver)) orelse {
        if (runtime.envOnce("KLIO_INLINE_PICK")) |w| {
            if (std.mem.eql(u8, w, name)) std.debug.print("[rcmt] {s} no receiver head (recv tag={s})\n", .{ name, @tagName(std.meta.activeTag(receiver.*)) });
        }
        return false;
    };
    var h = std.mem.trimEnd(u8, head, "?");
    if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
    const file = exprSpan(receiver).file;
    const cid = b.module.classIdIndexed(h, b.self_package, file) orelse b.module.classId(h) orelse return false;
    if (cid.int() >= b.module.classes.items.len) return false;
    const shapes = try buildStaticArgShapes(b, args, arg_names);
    defer b.allocator.free(shapes);
    const owned_bounds = try b.typeParamBoundsSlice();
    defer if (owned_bounds) |bounds| b.allocator.free(bounds);
    var recv_type = try ownedClassSelfType(b.allocator, &b.module.classes.items[cid.int()]);
    defer recv_type.deinit(b.allocator);
    const res = b.module.resolveMemberCall(cid, name, shapes, .{
        .caller_file = file,
        .lexical_owner = cid,
        .actual_type_param_bounds = owned_bounds orelse &.{},
        .receiver_type = recv_type,
    });
    if (runtime.envOnce("KLIO_INLINE_PICK")) |w| {
        if (std.mem.eql(u8, w, name)) {
            std.debug.print("[rcmt] {s} head={s} target={?d} shapes:", .{ name, h, if (res.target) |t| t.int() else null });
            for (shapes) |sh| std.debug.print(" {s}", .{if (sh.ty) |t| t.name else "?"});
            std.debug.print("\n", .{});
        }
    }
    // An applicable member shadows every same-named extension even when the
    // overload set stays ambiguous for the statically known argument shapes
    // (`matrix.map(Offset(1f, 1f))` among `map(Offset)`/`map(Rect)`/
    // `map(MutableRect)` with the factory call's type unproven).
    return res.target != null or res.applicable;
}

fn lowerCall(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    // Sibling-arg expected type: `assertEquals(EmptyEnum.entries,
    // enumEntries())` — a sibling argument bound to the same declared type
    // variable statically names an enum, which solves the nested reified
    // call's expected type. Recorded per-arg-node; the arg-lowering loops
    // surface it as THAT argument's expected type so the nested inline
    // splice's return-type unification (the existing reified oracle)
    // stamps the type argument.
    const sib_prev_site = b.sib_expected_site;
    const sib_prev_ty = b.sib_expected_ty;
    if (solveSiblingExpected(b, expr.Call.callee, expr.Call.args)) |solved| {
        b.sib_expected_site = @ptrCast(solved.site);
        b.sib_expected_ty = solved.ty;
        if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null)
            std.debug.print("[sibexp] solved ty={s} site={x}\n", .{ solved.ty.name.name, @intFromPtr(solved.site) & 0xffff });
    } else if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null and expr.Call.args.len >= 2) {
        const cn: []const u8 = switch (expr.Call.callee.*) {
            .Path => |p| p.segments[p.segments.len - 1].name,
            .Member => |m| m.name.name,
            else => "?",
        };
        std.debug.print("[sibexp] none for `{s}` with {d} args\n", .{ cn, expr.Call.args.len });
    }
    defer {
        b.sib_expected_site = sib_prev_site;
        b.sib_expected_ty = sib_prev_ty;
    }
    const call = expr.Call;
    const prev_trailing = b.setCallTrailingLambda(call.has_trailing_lambda);
    defer _ = b.setCallTrailingLambda(prev_trailing);
    // `dep!!()` calls the value a not-null-asserted BARE NAME holds: keep
    // the bare-name call machinery (member-vs-global walk, and with it the
    // receiver-function-typed property arm) by unwrapping the assertion at
    // the callee — a null value still fails at the invoke, matching the
    // assertion's intent.
    const callee = blk: {
        var c = call.callee;
        while (c.* == .Postfix and c.Postfix.op == .NotNull and
            (c.Postfix.expr.* == .Path or c.Postfix.expr.* == .Member))
        {
            c = c.Postfix.expr;
        }
        break :blk c;
    };
    const prev_call_label = b.current_call_label;
    b.current_call_label = helpers.calleeLabel(callee);
    defer b.current_call_label = prev_call_label;
    const args = call.args;
    const ast_arg_names = call.arg_names;
    const ast_type_args = call.type_args;
    const is_infix = call.is_infix;
    // Scalar bitwise infix: `a and b` / `shl` / `shr` / `ushr` / `or` /
    // `xor` over statically-typed Int/Long (Bool for the logical trio)
    // are Int members with intrinsic semantics; lowering them as member
    // calls sent every bit of hot trie arithmetic through the virtual
    // dispatch ladder with a full frame per op. Emit the BinOp the
    // evaluator already serves. Members always outrank extensions on
    // these final receivers, so the reduction can never shadow user code.
    if (is_infix and args.len == 2 and callee.* == .Path and
        callee.Path.segments.len == 1 and ast_type_args.len == 0)
    {
        if (scalarBitBinOp(callee.Path.segments[0].name)) |op| blk: {
            var lt = (try staticExprTypeRef(b, &args[0])) orelse break :blk;
            defer lt.deinit(b.allocator);
            var rt = (try staticExprTypeRef(b, &args[1])) orelse break :blk;
            defer rt.deinit(b.allocator);
            if (lt.nullable or rt.nullable) break :blk;
            const shift = op == .Shl or op == .Shr or op == .UShr;
            const ok_types = if (shift)
                ((std.mem.eql(u8, lt.name, "Int") or std.mem.eql(u8, lt.name, "Long")) and
                    std.mem.eql(u8, rt.name, "Int"))
            else
                ((std.mem.eql(u8, lt.name, "Int") and std.mem.eql(u8, rt.name, "Int")) or
                    (std.mem.eql(u8, lt.name, "Long") and std.mem.eql(u8, rt.name, "Long")) or
                    (op != .Xor and std.mem.eql(u8, lt.name, "Bool") and std.mem.eql(u8, rt.name, "Bool")) or
                    (op == .Xor and std.mem.eql(u8, lt.name, "Bool") and std.mem.eql(u8, rt.name, "Bool")));
            if (!ok_types) break :blk;
            const lr = try lowerExpr(b, &args[0]);
            const rr = try lowerExpr(b, &args[1]);
            const dst = b.allocReg();
            try b.push(.{ .BinOp = .{ .dst = dst, .op = op, .lhs = lr, .rhs = rr } });
            return dst;
        }
    }
    // Record each lambda argument's expected value-parameter arity by span,
    // taken from the resolved callee's parameter types, BEFORE the args are
    // lowered. `lowerLambda` reads it authoritatively, so a receiver lambda
    // (`T.() -> R`, arity 0) drops its `it` no matter which emit branch lowers
    // the argument — the per-arg `pending_lambda_arity` is set only on some
    // paths, which is why a non-trailing receiver-lambda argument otherwise
    // stays an `it`-lambda and its bare member calls fall through to globals.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        const cnm = callee.Path.segments[0].name;
        // A bare call to an OWN MEMBER resolves to the member, not any
        // same-named top-level fn — and the member is absent from
        // func_name_index, so without this branch no arity is ever
        // recorded and a `() -> Unit` trailing lambda keeps a phantom
        // `it` that shadows the enclosing lambda's (`mrun { println(it) }`
        // printed null). The registered member AST, keyed by (owner,
        // name, arity), is the signature source; positional args only.
        if (b.ownerClass() != null and b.hasOwnMember(cnm)) {
            var any_named = false;
            for (ast_arg_names) |n| {
                if (n != null) any_named = true;
            }
            if (!any_named) {
                if (inline_state.exprBodyMemberAst(b.ownerClass().?, cnm, args.len)) |mf| {
                    for (args, 0..) |*a, i| {
                        if (a.* != .Lambda and a.* != .AnonFun) continue;
                        if (i >= mf.params.len) continue;
                        const pt = &mf.params[i].ty;
                        if (pt.function) |ft| {
                            b.recordLambdaArgArity(a.span(), @intCast(ft.params.len));
                        }
                    }
                }
            }
        }
        // Only when the callee name is UNAMBIGUOUS (a single same-named
        // function): the arity then definitely matches the resolved overload.
        // With overloads, `funcId` is a heuristic that may name the wrong one,
        // whose arity would wrongly drop a needed `it`.
        const unambiguous = if (b.module.func_name_index.get(cnm)) |ids| ids.items.len == 1 else false;
        // An APPLICABLE own member shadows the same-named top-level function
        // in Kotlin's scope order (`private fun Json(arrays: Boolean, build:
        // PolymorphicModuleBuilder<Any>.() -> Unit)` beside the library's
        // `Json { … }` builder): its lambda shapes come from the member, not
        // from the global this pre-record would commit.
        const own_shadows = b.ownerClass() != null and b.resolve("this") != null and
            b.hasOwnMember(cnm) and b.ownFunctionApplicable(cnm, args.len) and
            !ownMemberRejectsLambdas(b, cnm, args);
        const chosen: ?FuncId = if (own_shadows)
            null
        else if (unambiguous)
            b.module.funcId(cnm)
        else
            // Ambiguous name (`withCurrent` has a `SnapshotStateList.() ->` and a
            // `StateRecord.() ->` overload): disambiguate by the enclosing
            // receiver type so a receiver-lambda argument's arity (0) is still
            // recorded and its `it` dropped — otherwise its bare member reads
            // fall through to globals.
            disambiguateByReceiver(b, cnm);
        if (chosen) |fid| {
            if (b.module.funcById(fid)) |f| {
                const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
                const arr = try argFnArities(b, f, args, ast_arg_names, recv_off);
                if (arr) |ar| {
                    defer b.allocator.free(ar);
                    for (args, 0..) |*a, i| {
                        if ((a.* == .Lambda or a.* == .AnonFun) and i < ar.len and ar[i] >= 0) {
                            b.recordLambdaArgArity(a.span(), ar[i]);
                        }
                    }
                }
                try recordLambdaArgReceivers(b, f, args, ast_arg_names, ast_type_args, recv_off);
            }
        } else if (args.len != 0 and (args[args.len - 1] == .Lambda or args[args.len - 1] == .AnonFun)) {
            // Ambiguous name, no receiver disambiguation: when EVERY overload
            // declares the SAME receiver head for its trailing function-typed
            // parameter (`runTest`'s block is `TestScope.() -> Unit` in every
            // overload), that head is safe to record — `this + dispatcher`
            // inside the lambda then dispatches against the static type.
            if (b.module.func_name_index.get(cnm)) |ids| {
                var common: ?ir.TypeRef = null;
                defer if (common) |receiver| {
                    var cleanup = receiver;
                    cleanup.deinit(b.allocator);
                };
                var ok = ids.items.len >= 2;
                for (ids.items) |fid2| {
                    const f2 = b.module.funcById(fid2) orelse {
                        ok = false;
                        break;
                    };
                    if (f2.params.len == 0) {
                        ok = false;
                        break;
                    }
                    const declared_receiver = fnTypeReceiver(b, f2.params[f2.params.len - 1].ty) orelse {
                        ok = false;
                        break;
                    };
                    const recv_off: usize = if (std.mem.eql(u8, f2.params[0].name, "this")) 1 else 0;
                    var bound_receiver = try callBoundLambdaReceiverType(
                        b,
                        f2,
                        declared_receiver,
                        f2.params[recv_off..],
                        args,
                        ast_arg_names,
                        ast_type_args,
                        null,
                    );
                    if (common) |c0| {
                        if (!c0.eql(bound_receiver)) {
                            bound_receiver.deinit(b.allocator);
                            ok = false;
                            break;
                        }
                        bound_receiver.deinit(b.allocator);
                    } else common = bound_receiver;
                }
                if (ok) {
                    if (common) |receiver| {
                        common = null;
                        if (std.c.getenv("KLIO_LAR_TRACE") != null)
                            std.debug.print("[lar-site] site=common name={s} recv={s} s={d}..{d}\n", .{ cnm, receiver.name, args[args.len - 1].span().start, args[args.len - 1].span().end });
                        try b.recordLambdaArgRecvOwned(args[args.len - 1].span(), receiver);
                    }
                }
            }
        }
    }

    // Context parameters: the stdlib `context(v..., block)` scope function
    // and `contextOf<T>()` accessor lower to dedicated context-stack ops so
    // implicit resolution is driven by the runtime stack, not overload
    // resolution. Only when the name is not shadowed by a local/outer.
    if (!is_infix and callee.* == .Path and callee.Path.segments.len == 1) {
        const cname = callee.Path.segments[0].name;
        if (b.resolve(cname) == null and !b.knowsOuter(cname)) {
            if (std.mem.eql(u8, cname, "contextOf") and args.len == 0 and ast_type_args.len == 1) {
                b.module.has_context_decls = true;
                const dst = b.allocReg();
                const ty_const = try b.module.internConst(b.allocator, .{ .String = ast_type_args[0].name.name });
                try b.push(.{ .CtxLoad = .{ .dst = dst, .ty = ty_const, .erased = false } });
                return dst;
            }
            if (std.mem.eql(u8, cname, "context") and args.len >= 2 and lastArgIsLambda(args)) {
                b.module.has_context_decls = true;
                const run = try lowerArgRun(b, args);
                const n_ctx: u32 = @intCast(args.len - 1);
                const block_reg = Reg.from(run[0].int() + n_ctx);
                const dst = b.allocReg();
                try b.push(.{ .CtxScope = .{
                    .dst = dst,
                    .ctx_args = run[0],
                    .n_ctx = n_ctx,
                    .block = block_reg,
                } });
                return dst;
            }
        }
    }

    // Fully-positional call of a contextual function-type value:
    // `f(c0, c1, a0)` where `f: context(C0, C1) (A0) -> R`. When the arg
    // count matches the flattened `n_ctx + n_regular`, split the leading
    // context args onto the context stack (`CtxCall`); the implicit form
    // `f(a0)` (contexts from scope) has only `n_regular` args and falls
    // through to the ordinary value-call path.
    if (!is_infix and callee.* == .Path and callee.Path.segments.len == 1 and ast_type_args.len == 0) {
        const cname = callee.Path.segments[0].name;
        if (b.contextFnParam(cname)) |shape| {
            if (b.resolve(cname)) |callee_reg| {
                if (args.len == shape.n_ctx + shape.n_regular and !lastArgIsLambda(args)) {
                    b.module.has_context_decls = true;
                    const run = try lowerArgRun(b, args);
                    const dst = b.allocReg();
                    try b.push(.{ .CtxCall = .{
                        .dst = dst,
                        .callee = callee_reg,
                        .args = run[0],
                        .n_args = run[1],
                        .n_ctx = @intCast(shape.n_ctx),
                    } });
                    return dst;
                }
            }
        }
    }

    // Scope-true callee rewrite: a bare ctor/factory head naming a mangled
    // nested class (`Node(...)` inside its declaring class's subtree) or a
    // renamed file-private class/typealias resolves to the mangled lift
    // name. Locals and own members keep shadowing it (Kotlin scope order).
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        const head = callee.Path.segments[0];
        if (scopeTypeRename(b, head.name, head.span.file.int())) |renamed| {
            if (b.resolve(head.name) == null and !b.knowsOuter(head.name)) {
                var new_segs = [_]ast.Ident{.{ .name = renamed, .span = head.span }};
                var new_callee = Expr{ .Path = .{ .segments = &new_segs, .span = callee.Path.span } };
                var rewritten = expr.*;
                rewritten.Call.callee = &new_callee;
                return lowerCall(b, &rewritten);
            }
        }
    }

    // A bare call to a file-private top-level function mangled per file (two
    // files in one package each declaring the same-signature `private fun`)
    // resolves to the calling file's mangled name. Locals / outer captures /
    // own members still shadow it (Kotlin scope order). An applicable
    // EXTENSION on an in-scope implicit receiver also shadows it: Kotlin
    // resolves the implicit-receiver candidate group before any no-receiver
    // candidate, so `Text(…)` inside `fun MockViewValidator.value()` binds
    // the validator extension, never the file's private plain fn.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        const head = callee.Path.segments[0];
        if (build.filePrivateFuncRename(head.name, head.span.file.int())) |renamed| {
            if (b.resolve(head.name) == null and !b.knowsOuter(head.name) and !b.hasOwnMember(head.name) and
                !extOnEnclosingReceiverApplies(b, head.name, call.args.len))
            {
                var new_segs = [_]ast.Ident{.{ .name = renamed, .span = head.span }};
                var new_callee = Expr{ .Path = .{ .segments = &new_segs, .span = callee.Path.span } };
                var rewritten = expr.*;
                rewritten.Call.callee = &new_callee;
                return lowerCall(b, &rewritten);
            }
        }
    }

    // A bare call to a companion member imported by name
    // (`import X.Companion.member` then `member(args)`) dispatches on X's
    // companion: rewrite the callee to the qualified `X.member` the same way a
    // bare companion-imported name expression is rewritten, so the call reaches
    // the companion method instead of an unresolved global. A local / captured /
    // own-member binding of the name shadows the import (Kotlin scope order).
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        const head = callee.Path.segments[0];
        if (b.resolve(head.name) == null and !b.knowsOuter(head.name) and !b.hasOwnMember(head.name)) {
            if (importCompanionRewrite(b, head.span.file, head.name)) |rw| {
                const sp = head.span;
                const recv_segs = try b.allocator.alloc(ast.Ident, rw.segs.len - 1);
                for (rw.segs[0 .. rw.segs.len - 1], 0..) |s, k| recv_segs[k] = .{ .name = s, .span = sp };
                var recv = Expr{ .Path = .{ .segments = recv_segs, .span = sp } };
                var new_callee = Expr{ .Member = .{
                    .receiver = &recv,
                    .name = .{ .name = rw.segs[rw.segs.len - 1], .span = sp },
                    .safe = false,
                    .span = callee.Path.span,
                } };
                var rewritten = expr.*;
                rewritten.Call.callee = &new_callee;
                return lowerCall(b, &rewritten);
            }
        }
    }

    // Empty stdlib container creator (`emptyList()`, `setOf()`, `mapOf()`)
    // typed only by its binding annotation. With no explicit creation-site
    // type argument the runtime value cannot carry its element head, so a
    // receiver proof (`List<String>.describe()`) cannot bind. When the
    // tail-position expected type names the container's element/entry heads
    // (`val xs: List<String> = emptyList()`), synthesize those heads as the
    // call's type args so the existing creation-site path stamps
    // `declared_elem` on the built value, exactly as an explicit
    // `emptyList<String>()` would.
    if (!is_infix and ast_type_args.len == 0 and args.len == 0 and
        callee.* == .Path and callee.Path.segments.len == 1)
    {
        const cname = callee.Path.segments[0].name;
        if (b.resolve(cname) == null and !b.knowsOuter(cname)) {
            const want_heads = emptyContainerCreatorArity(cname);
            if (want_heads != 0) {
                if (b.peekExpected()) |exp| {
                    if (try synthesizeContainerTypeArgs(b, exp, want_heads)) |synth| {
                        var rewritten = expr.*;
                        rewritten.Call.type_args = synth;
                        return lowerCallGeneral(b, &rewritten);
                    }
                }
            }
        }
    }

    // A member call onto an inline `reified` extension (`xs.filterIsInstance<T>()`).
    // Explicit type args or an expected type let the splice bind the
    // reified parameters. Without either — a lambda body has no expected
    // type, the `Json.encodeToString(user)` hook shape — a call through a
    // companioned class name still splices; the splice itself declines
    // when the body reads a reified parameter it cannot bind, falling
    // back to runtime dispatch.
    if (!is_infix and callee.* == .Member and !callee.Member.safe and gate: {
        if (ast_type_args.len != 0 or b.peekExpected() != null) break :gate true;
        // A trailing-lambda call whose name has a monomorphic member-inline
        // candidate enters regardless of receiver form — the strict pick
        // inside re-validates everything, and a decline falls through to
        // the ordinary member lowering.
        if (args.len != 0 and switch (args[args.len - 1]) {
            .Lambda, .AnonFun => true,
            else => false,
        }) {
            if (inline_state.candidatesForName(callee.Member.name.name)) |mcands| {
                for (mcands) |mcf| {
                    if (mcf.receiver_type == null and mcf.type_params.len == 0 and
                        inline_state.inlineMemberOwner(mcf) != null) break :gate true;
                }
            }
        }
        // Statement position with no type args: splice anyway when the value
        // arguments alone bind every reified parameter (a generic-class
        // argument like `Nodes.Draw : NodeKind<DrawModifierNode>`), so the
        // spliced `is T` checks the real class — runtime dispatch of the
        // inline body would read a stale/unbound `T`.
        // EXCEPT when the receiver's own static type serves the name at
        // this arity: kotlinc resolves members before extensions, so
        // `pipelineCall.respond(message, typeInfo)` binds the interface
        // member — splicing the reified two-parameter respond EXTENSION
        // here committed the message into its HttpStatusCode parameter.
        if (inline_call.argsBindAllReified(b.allocator, callee.Member.name.name, args, b)) {
            // The receiver's own applicable member wins over the inline
            // extensions, unless that member IS a reified inline function
            // (`Json.encodeToString(value)`): the image keeps it bodiless,
            // so only the splice honors it.
            if (try receiverMemberIsReifiedInline(b, callee.Member.receiver, callee.Member.name.name, args.len)) break :gate true;
            break :gate !(try receiverStaticMemberApplies(b, callee.Member.receiver, callee.Member.name.name, args, ast_arg_names, callee.Member.name.span.file));
        }
        const recv = callee.Member.receiver;
        if (recv.* != .Path or recv.Path.segments.len != 1) break :gate false;
        const n = recv.Path.segments[0].name;
        if (b.resolve(n) != null or b.knowsOuter(n)) break :gate false;
        break :gate b.module.registry.companion_singletons.contains(n);
    }) {
        const mname = callee.Member.name.name;
        if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s} cands={d}\n", .{ mname, if (inline_state.candidatesForName(mname)) |c| c.len else 0 });
        // A MONOMORPHIC member `inline fun` taking a lambda splices like its
        // reified siblings — kotlinc inlines every inline fun, and the framed
        // form pays an activation for the wrapper AND one for the lambda
        // (`Operations.push(op) { setInt(...) }` is two frames per
        // changelist push). The pick is strict: no type parameters, no
        // defaults or varargs, arity matched, the declared callback shape
        // matched against the site's lambda, owner on the receiver chain,
        // and exactly one survivor. `KLIO_MEMBER_INLINE=0` bisects.
        const plain_member_inline: ?*const ast.Function = blk: {
            // `KLIO_MEMBER_INLINE`: "0" disables; a comma list allows ONLY
            // those names; a list starting with '!' allows all BUT those.
            if (runtime.envOnce("KLIO_MEMBER_INLINE")) |sel| {
                if (std.mem.eql(u8, sel, "0")) break :blk null;
                if (!std.mem.eql(u8, sel, "1")) {
                    var wanted = std.mem.startsWith(u8, sel, "!");
                    var it = std.mem.splitScalar(u8, if (wanted) sel[1..] else sel, ',');
                    const inverted = wanted;
                    wanted = inverted;
                    while (it.next()) |tok| {
                        if (tok.len != 0 and std.mem.eql(u8, tok, mname)) {
                            wanted = !inverted;
                            break;
                        }
                    }
                    if (inverted) {
                        if (!wanted) break :blk null;
                    } else if (!wanted) break :blk null;
                }
            }
            if (ast_type_args.len != 0) break :blk null;
            if (args.len == 0) break :blk null;
            const site_lambda: ?struct { n: usize, implicit: bool } = switch (args[args.len - 1]) {
                .Lambda => |l| .{ .n = l.params.len, .implicit = l.implicit_it },
                .AnonFun => |af| .{ .n = af.params.len, .implicit = false },
                else => null,
            };
            const sl = site_lambda orelse break :blk null;
            const cands = inline_state.candidatesForName(mname) orelse break :blk null;
            var found: ?*const ast.Function = null;
            for (cands) |cf| {
                if (cf.receiver_type != null) continue;
                const owner = inline_state.inlineMemberOwner(cf) orelse continue;
                if (cf.type_params.len != 0) continue;
                // The OWNER must be monomorphic too: a generic class's
                // member body (`MutableVector<T>.forEach`) casts through the
                // class parameter, and a splice leaves `T` reading the
                // process-global slot — unbound or stale. An owner the
                // module cannot name declines conservatively.
                const owner_cid = b.module.uniqueClassIdBySimpleName(owner) orelse
                    b.module.classIdByFqn(owner) orelse continue;
                if (owner_cid.int() >= b.module.classes.items.len) continue;
                if (b.module.classes.items[owner_cid.int()].type_params.len != 0) continue;
                if (cf.params.len != args.len) continue;
                var irregular = false;
                for (cf.params) |*p| {
                    if (p.default != null or p.is_vararg) irregular = true;
                }
                if (irregular) continue;
                // Callback-shape discrimination: same-name same-arity
                // member-inline overloads can differ only here (Duration's
                // LongParser vs FractionalParser `parse`). A receiver
                // lambda matches a parameterless site block; an implicit-it
                // site block matches a declared arity of at most one.
                const decl_fn = cf.params[cf.params.len - 1].ty.function orelse continue;
                const shape_ok = if (decl_fn.receiver != null)
                    (sl.implicit or sl.n == decl_fn.params.len)
                else if (sl.implicit)
                    decl_fn.params.len <= 1
                else
                    sl.n == decl_fn.params.len;
                if (!shape_ok) continue;
                if (cf.body == null) continue;
                if (!try memberOwnerOnReceiverChainStrict(b, callee.Member.receiver, cf)) continue;
                if (found != null) break :blk null;
                found = cf;
            }
            break :blk found;
        };
        const reified_ext = blk: {
            if (inlineFnAst(mname)) |f| {
                if (f.receiver_type != null and anyReified(f.type_params)) break :blk true;
            }
            // A reified MEMBER-inline fn is invisible to the top-level
            // stub index: a qualified call (`CC(e, a).pfw<E> { … }`) must
            // still splice, or the reified parameter dies at runtime. The
            // same holds for a reified EXTENSION that the single-pick above
            // missed because a same-named top-level overload outranked it
            // (`SerializersModule.serializer<T>()` next to the top-level
            // `serializer<T>()`). Only an EXPLICITLY type-argumented call
            // qualifies on that route: without `<…>` the widened scan would
            // pull same-named non-reified overloads (`Int.serializer()`) into
            // a splice their call shape does not select.
            if (ast_type_args.len != 0) {
                if (inline_state.candidatesForName(mname)) |cands| {
                    for (cands) |cf| {
                        if (anyReified(cf.type_params) and cf.receiver_type != null) break :blk true;
                    }
                }
            }
            if (inline_state.candidatesForName(mname)) |cands| {
                for (cands) |cf| {
                    if (anyReified(cf.type_params) and cf.receiver_type == null and
                        inline_state.inlineMemberOwner(cf) != null)
                    {
                        break :blk true;
                    }
                }
            }
            break :blk false;
        };
        if (reified_ext or plain_member_inline != null) {
            const receiver = callee.Member.receiver;
            const expected = b.peekExpected();
            const exp_ptr: ?*const ast.TypeRef = if (expected) |*_e| _e else null;
            // A member-inline overload set is invisible to the stub index
            // the general resolution consults, and its receiver-blind
            // shape pick cannot tell `visitNodes(mask: Int, block)` from
            // the reified `visitNodes(type: NodeKind<T>, block)`. Pick
            // here: the reified candidate whose type parameters the call
            // can actually bind (explicit `<…>`, or inference from the
            // value arguments) wins; otherwise leave the resolution to
            // the general path.
            var member_target: ?*const ast.Function = null;
            if (ast_type_args.len != 0) {
                if (inline_state.candidatesForName(mname)) |cands| {
                    if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm-xn] {s}: cands={d} ptr={x} enc={?s}\n", .{ mname, cands.len, @intFromPtr(cands.ptr), b.ownerClass() orelse build.currentOwnerClass() });
                    for (cands) |cf| {
                        if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm-x] {s}: cand owner={?s} reified={} recv={?s} params={d} args={d} enc={?s}/{?s}\n", .{ mname, inline_state.inlineMemberOwner(cf), anyReified(cf.type_params), if (cf.receiver_type) |rt| rt.name.name else null, cf.params.len, args.len, b.ownerClass(), build.currentOwnerClass() });
                        if (inline_state.inlineMemberOwner(cf) == null) continue;
                        if (!anyReified(cf.type_params)) continue;
                        if (inlineEvidenceRejects(b, cf, args, ast_arg_names)) continue;
                        if (cf.receiver_type) |crt| {
                            // A reified member EXTENSION declared by an
                            // enclosing class (`json.decodeFromString<B>(text,
                            // mode)` against the test base's
                            // `Json.decodeFromString`): the receiver's static
                            // type must fit its extension receiver and the
                            // owner must be in the enclosing hierarchy.
                            const enclosing = b.ownerClass() orelse build.currentOwnerClass() orelse continue;
                            if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm-x] {s}: inHier={}\n", .{ mname, inlineOwnerInEnclosingHierarchy(b, enclosing, cf) });
                            if (!inlineOwnerInEnclosingHierarchy(b, enclosing, cf)) continue;
                            if (cf.params.len != args.len) continue;
                            // A receiver whose static head is unknown (a
                            // local bound from an expression-bodied helper)
                            // still reaches the splice: its own receiver
                            // gates decide, and the alternative is a
                            // dynamic call that cannot honor the explicit
                            // type arguments.
                            if (try inline_call.gateReceiverHead(b, receiver)) |head| {
                                var h = std.mem.trimEnd(u8, head, "?");
                                if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
                                const want = typeHead(std.mem.trimEnd(u8, crt.name.name, "?"));
                                if (!std.mem.eql(u8, typeHead(h), want) and !b.module.classIsOrExtends(typeHead(h), want)) continue;
                            }
                        } else {
                            if (!try memberOwnerOnReceiverChain(b, receiver, cf)) continue;
                            // A member overload that cannot take this many
                            // arguments must not preempt a sibling that can
                            // (`Json.decodeFromString<T>(string)` beside the
                            // test base's `Json.decodeFromString<T>(source,
                            // mode)`).
                            if (cf.params.len < args.len) continue;
                            var required: usize = 0;
                            for (cf.params) |*cp| {
                                if (cp.default == null and !cp.is_vararg) required += 1;
                            }
                            if (args.len < required) continue;
                        }
                        member_target = cf;
                        break;
                    }
                }
            }
            if (ast_type_args.len == 0) blk_mit: {
                const cands = inline_state.candidatesForName(mname) orelse break :blk_mit;
                if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm-n] {s}: cands={d} enc={?s}\n", .{ mname, cands.len, b.ownerClass() orelse build.currentOwnerClass() });
                // Inference-bound reified MEMBER-inline call: the splice's
                // runtime-enclosing parity is not established, so dispatch
                // it as a statically-bound TYPED member call instead — the
                // lowered instance method runs framed with its reified
                // parameters bound from the inferred type-argument names
                // (`c.visitNodes(Kinds.OnRe) { … }` binds `T = Lw`).
                for (cands) |cf| {
                    if (!anyReified(cf.type_params)) continue;
                    // Argument evidence that refutes the candidate (a `List`
                    // argument for a `JsonTestingMode` parameter) leaves the
                    // receiver's own applicable member to the general path.
                    if (inlineEvidenceRejects(b, cf, args, ast_arg_names)) continue;
                    // The receiver's own applicable MEMBER outranks a member
                    // extension declared elsewhere (`Json.encodeToString(
                    // serializer, value)` is Json's member, never the test
                    // base's `encodeToString(value, mode)` extension).
                    if (cf.receiver_type != null and try receiverConcreteMemberTakes(b, receiver, mname, args, ast_arg_names)) continue;
                    if (cf.receiver_type) |crt| {
                        // A reified member EXTENSION on the receiver's static
                        // type (`json.decodeFromString(text, mode)` against
                        // the test base's `Json.decodeFromString`): its
                        // owner must be in the enclosing hierarchy.
                        if (inline_state.inlineMemberOwner(cf) == null) continue;
                        const enclosing = b.ownerClass() orelse build.currentOwnerClass() orelse continue;
                        if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s}: ext-cand owner={s} enclosing={s} inHier={}\n", .{ mname, inline_state.inlineMemberOwner(cf).?, enclosing, inlineOwnerInEnclosingHierarchy(b, enclosing, cf) });
                        if (!inlineOwnerInEnclosingHierarchy(b, enclosing, cf)) continue;
                        const head = (try inline_call.gateReceiverHead(b, receiver)) orelse continue;
                        var h = std.mem.trimEnd(u8, head, "?");
                        if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
                        const want = typeHead(std.mem.trimEnd(u8, crt.name.name, "?"));
                        if (!std.mem.eql(u8, typeHead(h), want) and !b.module.classIsOrExtends(typeHead(h), want)) continue;
                        if (cf.params.len != args.len) continue;
                    } else {
                        if (inline_state.inlineMemberOwner(cf) == null) continue;
                        if (!try memberOwnerOnReceiverChain(b, receiver, cf)) continue;
                    }
                    const names = inline_call.inferReifiedNamesForCall(b, cf, args, ast_arg_names, callee.Member.name.span.file.int()) orelse
                        (try reifiedNamesFromExpected(b, cf, exp_ptr)) orelse
                    {
                        if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s}: names=null\n", .{mname});
                        continue;
                    };
                    const fid = blk: {
                        for (b.module.funcsBySimpleName(mname)) |cand_fid| {
                            const ds = b.module.decl_span.get(cand_fid.int()) orelse continue;
                            if (ds.file.int() == cf.name.span.file.int() and ds.start == cf.name.span.start) {
                                if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s}: fid by span -> {s}\n", .{ mname, if (b.module.funcById(cand_fid)) |cfn| cfn.fqn else "?" });
                                break :blk cand_fid;
                            }
                        }
                        // Instance methods are not in the simple-name index;
                        // match by declaration span over the full table.
                        // User-file instance methods carry no decl-span
                        // record; identify the overload by its declared
                        // parameter-name sequence (`type, block` vs
                        // `mask, block`) behind the implicit `this`.
                        for (b.module.funcs.items) |*mf| {
                            if (!std.mem.eql(u8, mf.name, mname)) continue;
                            if (mf.kind != .instance_method) continue;
                            if (mf.params.len != cf.params.len + 1) continue;
                            var all_match = mf.params.len > 0 and std.mem.eql(u8, mf.params[0].name, "this");
                            if (all_match) {
                                for (cf.params, 0..) |*cp, pi| {
                                    if (!std.mem.eql(u8, mf.params[pi + 1].name, cp.name.name)) {
                                        all_match = false;
                                        break;
                                    }
                                }
                            }
                            if (all_match) {
                                if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s}: fid by param names -> {s}\n", .{ mname, mf.fqn });
                                break :blk mf.id;
                            }
                        }
                        break :blk null;
                    } orelse {
                        // No registered function for the member (a pack's
                        // reified inline member is a header stub): splice
                        // its AST, the only form that honors it.
                        if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s}: fid=null -> splice\n", .{mname});
                        inline_call.splice_route_tag = "lowerCall:6578";
                        if (try tryInlineCallWithTypeArgs(b, mname, cf, args, ast_arg_names, receiver, ast_type_args, exp_ptr)) |r| return r;
                        continue;
                    };
                    // A registered function that carries no type-parameter
                    // record cannot bind the stamped names at runtime (the
                    // image's header stub for a reified inline member): the
                    // splice is the only form that honors `T` there.
                    {
                        const tp_rec = b.module.registry.func_type_params.get(fid);
                        const n_rec: usize = if (tp_rec) |l| l.items.len else 0;
                        if (n_rec < cf.type_params.len) {
                            if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s}: fid without type params -> splice\n", .{mname});
                            inline_call.splice_route_tag = "lowerCall:6590";
                            if (try tryInlineCallWithTypeArgs(b, mname, cf, args, ast_arg_names, receiver, ast_type_args, exp_ptr)) |r| return r;
                        }
                    }
                    // A REIFIED inline callee with no written type arguments
                    // (`Json.encodeToString(origin)`) binds `T` only through the
                    // splice: the typed member call below stamps the written
                    // names, and with none the frame would read whatever
                    // process-global `T` an earlier splice left behind.
                    reified_splice: {
                        var any_reified = false;
                        for (cf.type_params) |*tp| {
                            if (tp.is_reified) any_reified = true;
                        }
                        if (!any_reified) break :reified_splice;
                        // Only when the registered target IS this declaration:
                        // `cf` was found by simple name, and a same-named inline
                        // member of another class (`LaunchFlowBuilder.catch`
                        // beside `Flow.catch`) must not be spliced onto this
                        // receiver. The receiver heads decide.
                        const cf_recv: ?[]const u8 = if (cf.receiver_type) |*rt|
                            typeHead(std.mem.trimEnd(u8, rt.name.name, "?"))
                        else
                            inline_state.inlineMemberOwner(cf);
                        const mf_reg = b.module.funcById(fid) orelse break :reified_splice;
                        const mf_recv: ?[]const u8 = if (mf_reg.params.len != 0 and std.mem.eql(u8, mf_reg.params[0].name, "this"))
                            typeHead(std.mem.trimEnd(u8, mf_reg.params[0].ty.name, "?"))
                        else
                            null;
                        const same_target = blk_same: {
                            const cr = cf_recv orelse break :blk_same mf_recv == null;
                            const mr = mf_recv orelse break :blk_same false;
                            break :blk_same std.mem.eql(u8, typeHead(cr), mr);
                        };
                        if (!same_target) break :reified_splice;
                        // And the CALL-SITE receiver must be that type (or a
                        // subtype): `flow.catch { }` is not a `LaunchFlowBuilder`
                        // call even though that class declares a reified inline
                        // `catch`. An untyped receiver keeps the typed member
                        // call below.
                        const site_ty: ?ir.TypeRef = staticExprTypeRef(b, receiver) catch null;
                        const recv_ok = blk_recv: {
                            const mr = mf_recv orelse break :blk_recv site_ty == null;
                            const st = site_ty orelse break :blk_recv false;
                            const sh = typeHead(std.mem.trimEnd(u8, st.name, "?"));
                            break :blk_recv std.mem.eql(u8, sh, mr) or b.module.classIsOrExtends(sh, mr);
                        };
                        if (!recv_ok) break :reified_splice;
                        if (runtime.envOnce("KLIO_SAM_TRACE") != null) std.debug.print("[marm] {s}: reified -> splice first\n", .{mname});
                        inline_call.splice_route_tag = "lowerCall:reified";
                        if (try tryInlineCallWithTypeArgs(b, mname, cf, args, ast_arg_names, receiver, ast_type_args, exp_ptr)) |r| return r;
                    }
                    const recv = try lowerReceiver(b, receiver);
                    const run = try lowerArgRun(b, args);
                    const arg_names_c = try internArgNames(b.allocator, b.module, ast_arg_names);
                    var ta_ids = try b.allocator.alloc(ir.ConstId, names.len);
                    for (names, 0..) |n, i| ta_ids[i] = try b.module.internConst(b.allocator, .{ .String = n });
                    const nm = try b.module.internConst(b.allocator, .{ .String = mname });
                    const dst = b.allocReg();
                    orEmitAudit(b, "member_inline_typed", "CallMemberOrGlobal", mname);
                    try b.push(.{ .CallMemberOrGlobal = .{
                        .dst = dst,
                        .this_idx = 0,
                        .name = nm,
                        .trailing_lambda = b.callTrailingLambda(),
                        .args = run[0],
                        .n_args = run[1],
                        .arg_names = arg_names_c,
                        .recv = recv,
                        .func = fid,
                        .candidates = try cmgCandidates(b, mname, callee.Member.name.span.file, run[1]),
                        .type_args = ta_ids,
                    } });
                    return dst;
                }
            }
            if (member_target == null) member_target = plain_member_inline;
            if (runtime.envOnce("KLIO_PMI_TRACE") != null and plain_member_inline != null and
                member_target == plain_member_inline)
            {
                std.debug.print("[pmi] {s}\n", .{mname});
            }
            inline_call.splice_route_tag = "lowerCall:6623";
            // A receiver whose static class declares a MEMBER that binds this
            // call outranks any extension in Kotlin's resolution order:
            // `Json.decodeFromString(serial, source)` is Json's own
            // `(deserializer, string)` member, never the test base's reified
            // `Json.decodeFromString(source, mode)` extension the name-only
            // narrowing would splice.
            const member_binds = member_target == null and try receiverConcreteMemberTakes(b, receiver, mname, args, ast_arg_names);
            if (!member_binds) {
                if (try tryInlineCallWithTypeArgs(b, mname, member_target, args, ast_arg_names, receiver, ast_type_args, exp_ptr)) |r| {
                    if (runtime.envOnce("KLIO_SPLICE_TRACE")) |w| {
                        if (std.mem.eql(u8, w, mname)) std.debug.print("[splice-ok] {s} span={}:{}\n", .{ mname, exprSpan(callee).file, exprSpan(callee).start });
                    }
                    return r;
                }
            }
            if (runtime.envOnce("KLIO_SPLICE_TRACE")) |w| {
                if (std.mem.eql(u8, w, mname)) std.debug.print("[splice-bail] {s} span={}:{}\n", .{ mname, exprSpan(callee).file, exprSpan(callee).start });
            }
            // Splice bailed: fall back to a plain member dispatch. The
            // reified parameters then have no binding of their own, and the
            // body reads them from the process-wide slot the splice writes —
            // which still holds whatever an UNRELATED earlier splice left
            // there. The call knows its own type arguments, so write them
            // where the body looks before dispatching.
            try storeExplicitReifiedGlobals(b, mname, ast_type_args);
            const recv = try lowerReceiver(b, receiver);
            const bail_arity: ?[]const i16 = try memberCallArgArities(b, receiver, mname, args, ast_arg_names);
            const run = try lowerArgRunWithArity(b, args, bail_arity);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const nm = try b.module.internConst(b.allocator, .{ .String = mname });
            const dst = b.allocReg();
            // An unsafe-cast receiver fixes the static type for overload
            // resolution even on this dynamic bail: `(this as Flow<T>)
            // .catch(action)` in the deprecated SharedFlow.catch stub must
            // never re-bind the stub on the runtime SharedFlow receiver
            // (kotlinc binds the general Flow.catch through the cast; the
            // re-bind self-recursed to stack overflow).
            const bail_declared: ?ir.ConstId = blk: {
                if (receiver.* != .As or receiver.As.safe) break :blk null;
                const t = argDeclTypeRef(b, receiver) orelse break :blk null;
                const head = std.mem.trimEnd(u8, t.name, "?");
                if (head.len == 0) break :blk null;
                break :blk try b.module.internConst(b.allocator, .{ .String = head });
            };
            try b.push(.{ .CallMember = .{
                .dst = dst,
                .receiver = recv,
                .name = nm,
                .trailing_lambda = b.callTrailingLambda(),
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
                .declared_recv = bail_declared,
            } });
            return dst;
        }
    }

    // An explicit-receiver call to a NO-LAMBDA inline EXTENSION on a
    // SCALAR receiver (`value.countOneBits()`, `mask.rotateLeft(n)`)
    // splices exactly as kotlinc inlines it: the ladder otherwise
    // dispatches a frame per call (193k countOneBits activations in one
    // vpd window). Scoped to scalar heads with no member namesake
    // anywhere in the program — a member would outrank the extension.
    if (!is_infix and callee.* == .Member and !callee.Member.safe and
        ast_type_args.len == 0 and args.len <= 2 and
        inline_call.rfsEnabled() and
        !lastArgIsLambdaOrAnon(args))
    scalar_ext: {
        const mname = callee.Member.name.name;
        const receiver = callee.Member.receiver;
        const sxt = if (runtime.envOnce("KLIO_SEXT_TRACE")) |w| std.mem.eql(u8, w, mname) else false;
        const cands = inline_state.candidatesForName(mname) orelse {
            if (sxt) std.debug.print("[sext] {s}: no candidates\n", .{mname});
            break :scalar_ext;
        };
        const head = (try inline_call.gateReceiverHead(b, receiver)) orelse {
            if (sxt) std.debug.print("[sext] {s}: no receiver head (in {s})\n", .{ mname, build.currentRealFn() orelse "-" });
            break :scalar_ext;
        };
        const h = typeHead(std.mem.trimEnd(u8, head, "?"));
        if (sxt) std.debug.print("[sext] {s}: head={s} in {s}\n", .{ mname, h, build.currentRealFn() orelse "-" });
        // Member-namesake decline, hierarchy-scoped: the global
        // `class_member_names` set is owner-blind — ANY class declaring a
        // member of this name suppressed the splice program-wide (a pack
        // class's `countOneBits` member kept every scalar call framed).
        // On a scalar head only the scalar's own hierarchy can outrank
        // the extension; when its shadow set is complete, decide by it.
        if (b.module.registry.class_member_names.contains(mname)) {
            const shadowed = blk: {
                const hs = b.module.registry.hierarchy_shadow_names.get(h) orelse break :blk true;
                if (!hs.complete) break :blk true;
                break :blk hs.names.contains(mname);
            };
            if (shadowed) break :scalar_ext;
        }
        const scalar = for ([_][]const u8{
            "Int",   "Long",  "Short",  "Byte",  "Char", "Boolean",
            "Float", "Double", "UInt",  "ULong", "UShort", "UByte",
        }) |sc| {
            if (std.mem.eql(u8, h, sc)) break true;
        } else false;
        if (!scalar) break :scalar_ext;
        for (cands) |cf| {
            const rt = cf.receiver_type orelse continue;
            if (!std.mem.eql(u8, typeHead(std.mem.trimEnd(u8, rt.name.name, "?")), h)) continue;
            if (cf.params.len != args.len) continue;
            var has_fn_or_vararg = false;
            for (cf.params) |*p| {
                if (p.ty.function != null or p.is_vararg) has_fn_or_vararg = true;
            }
            if (has_fn_or_vararg) continue;
            if (anyReified(cf.type_params)) continue;
            // Scalar overload sets differ ONLY by parameter width
            // (`Long.mod(Int)` vs `Long.mod(Long)`), and picking the
            // first arity match computed `Instant.fromEpochMilliseconds`'
            // millisecond remainder with the wrong overload. Every
            // argument's derived head must equal the declared param head;
            // an underivable argument declines the splice (the framed
            // path resolves it).
            var args_match = true;
            for (cf.params, 0..) |*p, pi| {
                const want = typeHead(std.mem.trimEnd(u8, p.ty.name.name, "?"));
                var got_owned: ?ir.TypeRef = null;
                defer if (got_owned) |*t| t.deinit(b.allocator);
                const got: ?ir.TypeRef = argDeclTypeRefLazy(b, &args[pi]) orelse gblk: {
                    got_owned = try staticExprTypeRef(b, &args[pi]);
                    break :gblk got_owned;
                };
                const gv = got orelse {
                    args_match = false;
                    break;
                };
                if (!std.mem.eql(u8, typeHead(std.mem.trimEnd(u8, gv.name, "?")), want)) {
                    args_match = false;
                    break;
                }
            }
            if (!args_match) continue;
            const expected0 = b.peekExpected();
            const exp_ptr0: ?*const ast.TypeRef = if (expected0) |*_e| _e else null;
            inline_call.splice_route_tag = "lowerCall:6755";
            if (try inline_call.tryInlineCallWithTypeArgs(b, mname, cf, args, ast_arg_names, receiver, ast_type_args, exp_ptr0)) |r| {
                return r;
            }
            break;
        }
    }

    // A qualified member-inline call whose lambda (literal or forwarded)
    // carries a labeled return TARGETING AN OPEN INLINE SPLICE must splice:
    // kotlinc inlines these, and the label targets a frameless spliced
    // scope in the caller, so the dynamic member dispatch can never deliver
    // the return (`slots.table.traverseGroupAndParents(target) {
    // … return@apply … }` otherwise unwinds a LabeledReturn past every
    // frame). Everything else keeps the dynamic path.
    if (!is_infix and callee.* == .Member and !callee.Member.safe and
        inline_call.argLambdaTargetsSplicedLabel(b, args))
    {
        const mname = callee.Member.name.name;
        const receiver = callee.Member.receiver;
        const expected = b.peekExpected();
        const exp_ptr: ?*const ast.TypeRef = if (expected) |*_e| _e else null;
        if (inline_state.candidatesForName(mname)) |cands| {
            // STRICT owner evidence only: the receiver's static type must be
            // known and carry the candidate's owner in its hierarchy. The
            // lenient unknown-receiver keep would splice an unrelated
            // same-named member (`values.forEach` on a Set binding
            // LockFreeLinkedListNode.forEach).
            const head = try inline_call.gateReceiverHead(b, receiver);
            if (head != null) {
                for (cands) |cf| {
                    if (cf.receiver_type != null) continue;
                    const owner = inline_state.inlineMemberOwner(cf) orelse continue;
                    // A duplicated class name is uniquified per file at
                    // registration (`SlotTable$f356`); the inferred head
                    // carries the source-level name, so also accept a
                    // base-name match.
                    const owner_base = if (std.mem.indexOf(u8, owner, "$f")) |i| owner[0..i] else owner;
                    if (!classIsOrExtendsHosted(b, head.?, owner) and
                        !std.mem.eql(u8, head.?, owner_base)) continue;
                    inline_call.splice_route_tag = "lowerCall:6794";
                    if (try tryInlineCallWithTypeArgs(b, mname, cf, args, ast_arg_names, receiver, ast_type_args, exp_ptr)) |r| {
                        return r;
                    }
                    break;
                }
            }
        }
    }

    // An explicit-receiver call to a top-level inline EXTENSION whose last
    // param is fn-typed, fed a lambda literal or a forwarded inline-lambda
    // param (`record.withCurrent(block)`, `(firstStateRecord as
    // StateMapStateRecord).writable(this, block)`) splices as kotlinc
    // inlines it. The declared receiver may be a concrete head or a
    // BOUNDED fn type param (`T : StateRecord`) the derived head extends;
    // an unbounded `T` (the scope-function family) keeps its existing
    // routes. A member of the head's own hierarchy outranks the extension
    // and declines the splice; unknown heads decline.
    if (!is_infix and callee.* == .Member and !callee.Member.safe and
        ast_type_args.len == 0 and args.len >= 1 and
        !std.mem.eql(u8, runtime.envOnce("KLIO_XLE") orelse "1", "0") and
        !inline_call.argLambdaTargetsLabel(args, callee.Member.name.name))
    ext_lambda: {
        const mname = callee.Member.name.name;
        const receiver = callee.Member.receiver;
        const xlt = if (runtime.envOnce("KLIO_XLE_TRACE")) |w|
            (std.mem.eql(u8, w, "*") or std.mem.eql(u8, w, mname))
        else
            false;
        const last = &args[args.len - 1];
        const last_forwarded = last.* == .Path and last.Path.segments.len == 1 and
            b.inlineLambdaFor(last.Path.segments[0].name) != null;
        if (last.* != .Lambda and last.* != .AnonFun and !last_forwarded) break :ext_lambda;
        const cands = inline_state.candidatesForName(mname) orelse break :ext_lambda;
        // DECLARED evidence only: an unsafe cast's target, a declared
        // local/param type, a constructor call, or the enclosing
        // extension's declared receiver for `this`. The general derivation
        // chain resolves overloaded-call returns heuristically and once
        // handed this tier `Iterable` for a Sequence expression — which
        // spliced the EAGER `Iterable.filter` onto an infinite sequence.
        const head0: []const u8 = blk: {
            switch (receiver.*) {
                .As => |a| {
                    if (a.safe) break :ext_lambda;
                    break :blk a.ty.name.name;
                },
                .This => |t| {
                    if (t.qualifier != null) break :ext_lambda;
                    break :blk b.recvTy() orelse break :ext_lambda;
                },
                else => {
                    if (argDeclTypeRefLazy(b, receiver)) |ty| break :blk ty.name;
                    break :ext_lambda;
                },
            }
        };
        const h = typeHead(std.mem.trimEnd(u8, head0, "?"));
        if (b.module.registry.class_member_names.contains(mname)) {
            const cid = b.module.classIdIndexed(h, b.self_package, callee.Member.name.span.file) orelse {
                if (xlt) std.debug.print("[xle] {s}: head {s} unresolvable for shadow check\n", .{ mname, h });
                break :ext_lambda;
            };
            if (b.module.classHierarchyDeclaresMember(cid, mname)) {
                if (xlt) std.debug.print("[xle] {s}: member shadows on {s}\n", .{ mname, h });
                break :ext_lambda;
            }
        }
        var picked: ?*const ast.Function = null;
        var ambiguous = false;
        for (cands) |cf| {
            if (inline_state.inlineMemberOwner(cf) != null) continue;
            const rt = cf.receiver_type orelse continue;
            if (cf.params.len != args.len) continue;
            if (anyReified(cf.type_params)) continue;
            if (anyCrossOrNoinlineParam(cf)) continue;
            if (cf.params[cf.params.len - 1].ty.function == null) continue;
            const rhead = typeHead(std.mem.trimEnd(u8, rt.name.name, "?"));
            var head_ok = std.mem.eql(u8, rhead, h);
            if (!head_ok) {
                for (cf.type_params) |tp| {
                    if (!std.mem.eql(u8, tp.name.name, rhead)) continue;
                    const ub = tp.upper_bound orelse break;
                    const ub_head = typeHead(std.mem.trimEnd(u8, ub.name.name, "?"));
                    head_ok = b.module.classIsOrExtends(h, ub_head);
                    break;
                }
            }
            if (!head_ok) continue;
            if (picked != null) {
                ambiguous = true;
                break;
            }
            picked = cf;
        }
        if (ambiguous) {
            if (xlt) std.debug.print("[xle] {s}: ambiguous candidates\n", .{mname});
            break :ext_lambda;
        }
        const cf = picked orelse {
            if (xlt) std.debug.print("[xle] {s}: no applicable candidate (head {s})\n", .{ mname, h });
            break :ext_lambda;
        };
        if (xlt) std.debug.print("[xle] {s}: splicing head={s} in {s}\n", .{ mname, h, build.currentRealFn() orelse "-" });
        const expected0 = b.peekExpected();
        const exp_ptr0: ?*const ast.TypeRef = if (expected0) |*_e| _e else null;
        inline_call.splice_route_tag = "lowerCall:6899";
        if (try inline_call.tryInlineCallWithTypeArgs(b, mname, cf, args, ast_arg_names, receiver, ast_type_args, exp_ptr0)) |r| {
            return r;
        }
    }

    // `recv?.m(args)` — null-guard the whole call.
    if (callee.* == .Member and callee.Member.safe) {
        const receiver = callee.Member.receiver;
        const name = callee.Member.name;
        const recv = try lowerReceiver(b, receiver);
        const null_r = try b.emitConst(.Null);
        const is_null = b.allocReg();
        try b.push(.{ .BinOp = .{ .dst = is_null, .op = .Eq, .lhs = recv, .rhs = null_r } });
        const then_b = try b.allocBlock();
        const else_b = try b.allocBlock();
        const join = try b.allocBlock();
        const dst = b.allocReg();
        b.terminate(.{ .Branch = .{ .cond = is_null, .t = then_b, .f = else_b } });
        b.switchTo(then_b);
        const n = try b.emitConst(.Null);
        try b.push(.{ .Move = .{ .dst = dst, .src = n } });
        b.terminate(.{ .Goto = join });
        b.switchTo(else_b);
        // On this branch the receiver is proven non-null, so its declared
        // nullability no longer disqualifies a member. Bind statically when
        // the declaration is provable; the receiver is already in a register,
        // so hand it over rather than let it be evaluated a second time.
        const declared_from_expr = argDeclTypeRef(b, receiver);
        // The full static deriver, matching the plain member path.
        var inferred_ty: ?ir.TypeRef = if (declared_from_expr == null)
            try staticExprTypeRef(b, receiver)
        else
            null;
        defer if (inferred_ty) |*t| t.deinit(b.allocator);
        switch (try lowerResolvedMemberCall(
            b,
            receiver,
            name,
            args,
            ast_arg_names,
            ast_type_args,
            declared_from_expr orelse inferred_ty,
            .{ .reg = recv, .non_null = true },
        )) {
            .lowered => |reg| {
                try b.push(.{ .Move = .{ .dst = dst, .src = reg } });
                b.terminate(.{ .Goto = join });
                b.switchTo(join);
                return dst;
            },
            .deferred, .none => {},
        }
        // The member resolver could not commit, but the ORDINARY call path
        // has more to try — an inline splice above all. `x?.let { it.f() }`
        // gives `it` the non-null receiver type in Kotlin; dispatching the
        // whole thing as a runtime member call gives it none, and every
        // member call inside the lambda then resolves by name. Rewrite the
        // proven-non-null branch as a plain call on a temporary that HOLDS
        // the already-lowered receiver, so nothing is evaluated twice.
        if (declared_from_expr orelse inferred_ty) |rty| non_null_rewrite: {
            const nn_name = std.mem.trimEnd(u8, rty.name, "?");
            if (nn_name.len == 0) break :non_null_rewrite;
            const tmp_name = try std.fmt.allocPrint(b.allocator, "$nn{d}", .{recv});
            var tmp_ty = try rty.clone(b.allocator);
            tmp_ty.nullable = false;
            b.allocator.free(tmp_ty.name);
            tmp_ty.name = try b.allocator.dupe(u8, nn_name);
            try b.pushScope();
            try b.bind(tmp_name, recv);
            try b.setLocalDeclTypeOwned(tmp_name, tmp_ty);
            var segs = [_]ast.Ident{.{ .name = tmp_name, .span = receiver.span() }};
            var recv_expr = Expr{ .Path = .{ .segments = segs[0..], .span = receiver.span() } };
            var plain_callee = Expr{ .Member = .{
                .receiver = &recv_expr,
                .name = name,
                .safe = false,
                .span = callee.span(),
            } };
            var plain = expr.Call;
            plain.callee = &plain_callee;
            const rewritten = Expr{ .Call = plain };
            const rv = try lowerCall(b, &rewritten);
            try b.popScope();
            try b.push(.{ .Move = .{ .dst = dst, .src = rv } });
            b.terminate(.{ .Goto = join });
            b.switchTo(join);
            return dst;
        }
        const run = try lowerArgRun(b, args);
        const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
        const nm = try b.module.internConst(b.allocator, .{ .String = name.name });
        const v = b.allocReg();
        try b.push(.{ .CallMember = .{
            .dst = v,
            .receiver = recv,
            .name = nm,
            .trailing_lambda = b.callTrailingLambda(),
            .args = run[0],
            .n_args = run[1],
            .arg_names = arg_names,
        } });
        try b.push(.{ .Move = .{ .dst = dst, .src = v } });
        b.terminate(.{ .Goto = join });
        b.switchTo(join);
        return dst;
    }

    // `repeat(n) { … }` — inline-desugar to a counted loop.
    if (!is_infix and args.len == 2 and args[1] == .Lambda and
        callee.* == .Path and callee.Path.segments.len == 1 and
        std.mem.eql(u8, callee.Path.segments[0].name, "repeat") and
        b.resolve("repeat") == null and b.module.funcId("repeat") == null)
    {
        return lowerRepeat(b, &args[0], &args[1]);
    }

    // Calls containing a `*spread` argument.
    if (anySpread(args)) {
        if (callee.* == .Member and !callee.Member.safe) {
            const member = callee.Member;
            switch (try lowerResolvedMemberCall(
                b,
                member.receiver,
                member.name,
                args,
                ast_arg_names,
                ast_type_args,
                argDeclTypeRef(b, member.receiver),
                .{},
            )) {
                .lowered => |reg| return reg,
                .deferred, .none => {},
            }
        }
        return lowerCallSpread(b, callee, args, ast_arg_names);
    }

    return lowerCallGeneral(b, expr);
}

fn anyReified(type_params: []const ast.TypeParam) bool {
    for (type_params) |tp| {
        if (tp.is_reified) return true;
    }
    return false;
}

/// Number of element/entry heads a bare stdlib container creator carries
/// (`emptyList` -> 1, `emptyMap` -> 2), or 0 when the name is not one of
/// them. Mirrors `runtime.attachDeclaredElemTypes`'s creator sets so a
/// binding-typed empty creation stamps the same `declared_elem`/`declared_*`
/// fields an explicit creation-site type argument would.
fn emptyContainerCreatorArity(name: []const u8) u8 {
    const elem_creators = [_][]const u8{
        "listOf",      "mutableListOf", "emptyList", "arrayListOf",
        "setOf",       "mutableSetOf",  "emptySet",  "hashSetOf",
        "linkedSetOf", "sortedSetOf",   "arrayOf",   "emptyArray",
        "sequenceOf",  "emptySequence",
    };
    const pair_creators = [_][]const u8{
        "mapOf", "mutableMapOf", "emptyMap", "hashMapOf", "linkedMapOf", "sortedMapOf",
    };
    for (elem_creators) |c| {
        if (std.mem.eql(u8, c, name)) return 1;
    }
    for (pair_creators) |c| {
        if (std.mem.eql(u8, c, name)) return 2;
    }
    return 0;
}

/// True when `name` is a concrete type head (a stdlib value type or a
/// lowered user class) rather than an erased type-parameter name. Used to
/// gate the binding-typed empty-container element stamp so the
/// erased-generic-return shape (`List<T>`) is left to on-demand dispatch.
fn isConcreteTypeHead(b: *FuncBuilder, name: []const u8) bool {
    const value_type_heads = [_][]const u8{
        "Int",        "Long",     "Short",       "Byte",       "UInt",       "ULong",
        "UShort",     "UByte",    "Double",      "Float",      "Boolean",    "Char",
        "String",     "Any",      "Number",      "Unit",       "CharObject", "List",
        "Set",        "Map",      "MutableList", "MutableSet", "MutableMap", "Array",
        "Collection", "Iterable", "Sequence",    "Pair",       "Triple",
    };
    for (value_type_heads) |h| {
        if (std.mem.eql(u8, h, name)) return true;
    }
    return b.module.classId(name) != null;
}

/// Build `want` synthetic call-site type-arg `TypeRef`s from the expected
/// container type `exp` (`List<String>` -> `[String]`). Returns null when
/// `exp` does not name `want` concrete (non-star, non-type-parameter) heads,
/// so an unannotated or partially-erased binding keeps the on-demand path.
fn synthesizeContainerTypeArgs(
    b: *FuncBuilder,
    exp: ast.TypeRef,
    want: u8,
) Allocator.Error!?[]ast.TypeRef {
    if (exp.type_args.len < want) return null;
    const out = try b.allocator.alloc(ast.TypeRef, want);
    var i: usize = 0;
    while (i < want) : (i += 1) {
        const ta = exp.type_args[i];
        if (ta.is_star) return null;
        if (ta.ty.name.name.len == 0) return null;
        // Only a concrete head carries runtime element identity. A bare
        // type-parameter head (`List<T>` from a generic function's declared
        // return) is erased — stamping the parameter name would forge a
        // proof — so that erased-generic-return shape keeps the on-demand
        // path rather than a synthesized element type.
        if (!isConcreteTypeHead(b, ta.ty.name.name)) return null;
        out[i] = ta.ty;
    }
    return out;
}

fn anySpread(args: []const Expr) bool {
    for (args) |a| {
        if (a == .Spread) return true;
    }
    return false;
}

fn lowerRepeat(b: *FuncBuilder, n_arg: *const Expr, lam_arg: *const Expr) Allocator.Error!Reg {
    const lam = lam_arg.Lambda;
    const n_reg = try lowerExpr(b, n_arg);
    const i_reg = b.allocReg();
    const zero = try b.emitConst(.{ .Int = 0 });
    try b.push(.{ .Move = .{ .dst = i_reg, .src = zero } });
    const header = try b.allocBlock();
    const body_blk = try b.allocBlock();
    const exit = try b.allocBlock();
    b.terminate(.{ .Goto = header });
    b.switchTo(header);
    const cond = b.allocReg();
    try b.push(.{ .BinOp = .{ .dst = cond, .op = .Less, .lhs = i_reg, .rhs = n_reg } });
    b.terminate(.{ .Branch = .{ .cond = cond, .t = body_blk, .f = exit } });
    b.switchTo(body_blk);
    try b.pushScope();
    const pname: []const u8 = if (lam.params.len != 0) lam.params[0].name else "it";
    try b.bind(pname, i_reg);
    try b.pushLoop(null, header, exit);
    _ = try lowerBlock(b, &lam.body);
    b.popLoop();
    try b.popScope();
    const one = try b.emitConst(.{ .Int = 1 });
    const nexti = b.allocReg();
    try b.push(.{ .BinOp = .{ .dst = nexti, .op = .Add, .lhs = i_reg, .rhs = one } });
    try b.push(.{ .Move = .{ .dst = i_reg, .src = nexti } });
    b.terminate(.{ .Goto = header });
    b.switchTo(exit);
    return b.emitConst(.Unit);
}

/// Compact a list of registers into a contiguous run, returning the start
/// reg (or reg 0 when empty).
fn packContiguous(b: *FuncBuilder, regs: []const Reg) Allocator.Error!Reg {
    if (regs.len == 0) return Reg.from(0);
    const start = b.allocReg();
    try b.push(.{ .Move = .{ .dst = start, .src = regs[0] } });
    for (regs[1..]) |r| {
        const slot = b.allocReg();
        try b.push(.{ .Move = .{ .dst = slot, .src = r } });
    }
    return start;
}

fn lowerSpreadParts(b: *FuncBuilder, args: []const Expr) Allocator.Error![]SpreadPart {
    const parts = try b.allocator.alloc(SpreadPart, args.len);
    for (args, parts) |*arg, *part| {
        if (arg.* == .Spread) {
            part.* = .{ .reg = try lowerExpr(b, arg.Spread.expr), .is_spread = true };
        } else {
            part.* = .{ .reg = try lowerExpr(b, arg), .is_spread = false };
        }
    }
    return parts;
}

/// Resolve a `this` reg for a bare extension call: bound local, else a
/// capture inside a lambda body, else null. Binds the recovered capture
/// locally so later references reuse it.
fn resolveThisForBareCall(b: *FuncBuilder) Allocator.Error!?Reg {
    return resolveThisRegKind(b, true, true);
}

/// Like `resolveThisForBareCall` but does not bind `this` locally.
fn resolveThisForBareCallNoBind(b: *FuncBuilder) Allocator.Error!?Reg {
    return resolveThisRegKind(b, true, false);
}

fn lowerCallSpread(
    b: *FuncBuilder,
    callee: *const Expr,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!Reg {
    // `recv.method(*array)` dispatches the spread-flattened args through
    // member resolution on the receiver, not by invoking `recv.method` as a
    // first-class value (which a member like `split` is not). Lower the
    // receiver and carry the method name so the evaluator routes through
    // `callMemberNamed`.
    var member_id: ?ConstId = null;
    var spread_name: ?ConstId = null;
    var spread_candidates: ?[]const FuncId = null;
    var spread_anchor_pkg: ?ConstId = null;
    const callee_reg = blk: {
        if (callee.* == .Member) {
            const m = callee.Member;
            if (b.resolve(m.name.name) == null and !b.knowsOuter(m.name.name) and !b.isLocalFn(m.name.name)) {
                member_id = try b.module.internConst(b.allocator, .{ .String = m.name.name });
                break :blk try lowerReceiver(b, m.receiver);
            }
        }
        // A bare callee naming an enclosing-class member fn
        // (`checkContents(context, *es)` inside another member) dispatches
        // through `this`, not as a first-class value read (a member fn is
        // not a field, so the value path dies on `get_field`). A name that
        // is also a known top-level fn (`maxOf(a, *rest)`) keeps the
        // global path — the member set over-approximates.
        if (callee.* == .Path and callee.Path.segments.len == 1) {
            const name = callee.Path.segments[0].name;
            // Only a PLAIN top-level namesake keeps the global path. An
            // EXTENSION namesake cannot answer this bare call — it needs a
            // receiver of its own type — so it must not divert the call away
            // from the enclosing class's member and into the value-read path
            // below, which dies on `get_field` because a member fn is not a
            // field.
            if (b.resolve(name) == null and !b.isLocalFn(name) and b.hasEnclosingMember(name) and
                !b.module.hasNonExtensionBareCallCandidate(name, callee.Path.segments[0].span.file))
            {
                if (try resolveThisForBareCall(b)) |this_reg| {
                    member_id = try b.module.internConst(b.allocator, .{ .String = name });
                    break :blk this_reg;
                }
            }
            // A bare global with overloads: the spread can only bind a
            // `vararg` parameter, so pick among the vararg-bearing
            // candidates explicitly — the generic value read below is
            // arg-blind and can hand back a zero-arg overload, silently
            // dropping the spread's elements.
            if (b.resolve(name) == null and !b.knowsOuter(name) and !b.isLocalFn(name) and
                !b.hasOwnMember(name) and
                b.module.hasBareCallCandidate(name, callee.Path.segments[0].span.file))
            {
                const nm = try b.module.internConst(b.allocator, .{ .String = name });
                if (try b.module.boundedSpreadCandidates(
                    b.allocator,
                    name,
                    b.self_package,
                    callee.Path.segments[0].span.file,
                )) |ids| {
                    // Every candidate an EXTENSION: the bare call binds the
                    // implicit receiver, so it must route as a member-form
                    // dispatch on `this` — the global-value invoke below
                    // passes only the flattened args, and the extension's
                    // receiver slot then swallowed the first spread element
                    // (`constructSerializerForGivenTypeArgs(*arr)` inside a
                    // KClass extension bound `this = IntSerializer`).
                    const all_ext = ids.len != 0 and blk_ext: {
                        for (ids) |fid| {
                            const f = b.module.funcById(fid) orelse break :blk_ext false;
                            if (f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this")) break :blk_ext false;
                        }
                        break :blk_ext true;
                    };
                    if (all_ext) {
                        if (try resolveThisForBareCall(b)) |this_reg| {
                            member_id = nm;
                            break :blk this_reg;
                        }
                    }
                    spread_name = nm;
                    spread_candidates = ids;
                    if (ids.len != 0) {
                        if (b.module.funcById(ids[0])) |f| {
                            spread_anchor_pkg = try b.module.internConst(
                                b.allocator,
                                .{ .String = f.package },
                            );
                        }
                        const dst = b.allocReg();
                        try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm, .func = ids[0] } });
                        break :blk dst;
                    }
                }
                if (b.module.funcIdForSpreadCall(name, b.ownerClass())) |fid| {
                    // An EXTENSION picked for a bare spread call binds the
                    // implicit receiver; invoking it as a global value passes
                    // only the flattened args and the receiver slot swallows
                    // the first spread element. Route it as a member-form
                    // dispatch on `this`.
                    const is_ext = blk_ext2: {
                        const f = b.module.funcById(fid) orelse break :blk_ext2 false;
                        break :blk_ext2 f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this");
                    };
                    if (is_ext) {
                        if (try resolveThisForBareCall(b)) |this_reg| {
                            member_id = nm;
                            break :blk this_reg;
                        }
                    }
                    const dst = b.allocReg();
                    try b.push(.{ .LoadGlobal = .{ .dst = dst, .name = nm, .func = fid } });
                    break :blk dst;
                }
            }
            // No local, no global, and no recorded enclosing member: a bare
            // call can only be a member of the implicit receiver. The
            // smart-cast `this` inside `when (this) { is Abs -> va(*a) }` of
            // an extension on a TYPE PARAMETER is the live shape — no static
            // member set records `Abs.va` there, and the value read below
            // dies on `get_field`.
            if (b.resolve(name) == null and !b.knowsOuter(name) and !b.isLocalFn(name) and
                !b.module.hasBareCallCandidate(name, callee.Path.segments[0].span.file))
            {
                if (try resolveThisForBareCall(b)) |this_reg| {
                    member_id = try b.module.internConst(b.allocator, .{ .String = name });
                    break :blk this_reg;
                }
            }
        }
        break :blk try lowerExpr(b, callee);
    };
    const parts = try lowerSpreadParts(b, args);
    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
    const dst = b.allocReg();
    try b.push(.{ .CallSpread = .{
        .dst = dst,
        .callee = callee_reg,
        .parts = parts,
        .arg_names = arg_names,
        .member = member_id,
        .name = spread_name,
        .candidates = spread_candidates,
        .anchor_pkg = spread_anchor_pkg,
    } });
    return dst;
}

/// The general call path: inline expansion, infix, scope-fn markers, tailrec,
/// value invocation, class constructors, member dispatch, and the long
/// overload-selection ladder.
/// True when the enclosing class declares a primary-ctor *property* param
/// named `name` and also a same-named `vararg` method. In that case a bare
/// call `name(args)` inside the class body (notably a field initializer, where
/// the param is in scope as a local) must resolve by argument shape — the
/// vararg method for several args, the property's `invoke` for one matching
/// array — rather than blindly invoking the param's lambda. Routing such calls
/// through member dispatch lets `varargShadowedFieldInvoke` make that pick.
fn ctorParamShadowsVarargMethod(b: *FuncBuilder, name: []const u8) bool {
    const owner = b.ownerClass() orelse return false;
    const cid = b.module.classId(owner) orelse return false;
    const idx = cid.int();
    if (idx >= b.module.classes.items.len) return false;
    const cls = &b.module.classes.items[idx];
    var has_prop_param = false;
    for (cls.primary_params) |p| {
        if (p.is_property and std.mem.eql(u8, p.name, name)) {
            has_prop_param = true;
            break;
        }
    }
    if (!has_prop_param) return false;
    for (cls.methods) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (std.mem.eql(u8, f.name, name) and
            f.params.len != 0 and f.params[f.params.len - 1].is_vararg) return true;
    }
    return false;
}

/// A plain function parameter is inapplicable to a trailing-lambda call when
/// its own final value parameter is not function-typed. Inline splices retain
/// this declaration shape through `currentInlineDecl`; the substituted lambda
/// value alone does not carry it.
fn plainFnParamRejectsTrailingLambda(
    b: *const FuncBuilder,
    name: []const u8,
    args: []const Expr,
) bool {
    if (!lastArgIsLambda(args)) return false;
    if (b.isPlainFnParam(name)) return !b.fnParamTakesTrailingLambda(name);
    const decl = b.currentInlineDecl() orelse return false;
    for (decl.params) |*param| {
        if (!std.mem.eql(u8, param.name.name, name)) continue;
        const ft = param.ty.function orelse return false;
        if (ft.receiver != null) return false;
        return ft.params.len == 0 or
            ft.params[ft.params.len - 1].function == null;
    }
    return false;
}

/// Bare-path inline expansion: splice an inline-lambda parameter's body,
/// the reified overload an explicit `<T>` argument binds, or the resolved
/// inline target of a bare call. Returns null when the callee is not a
/// bare path or no splice applies, leaving the call to the normal
/// dispatch paths.
fn tryBareInlineExpansion(b: *FuncBuilder, expr: *const Expr) Allocator.Error!?Reg {
    const call = expr.Call;
    const callee = call.callee;
    const args = call.args;
    const ast_arg_names = call.arg_names;
    const ast_type_args = call.type_args;
    if (call.is_infix or callee.* != .Path) {
        if (!call.is_infix and callee.* == .Member) return tryQualifiedInlineExpansion(b, expr);
        return null;
    }
    if (callee.Path.segments.len != 1) return tryQualifiedInlineExpansion(b, expr);
    const nm = callee.Path.segments[0].name;
    if (b.inlineLambdaFor(nm)) |lam| {
        if (!plainFnParamRejectsTrailingLambda(b, nm, args)) {
            return try spliceInlineLambda(b, nm, lam, args);
        }
    }
    // A local binding of a function-typed value (a plain fn param like
    // `body: () -> T`, a local val) shadows every top-level namesake for a
    // bare call — the call invokes the value, never an inline splice of an
    // unrelated extension. A NON-function-typed local does not shadow a
    // call (the `flow`-param case), matching the bare-function path.
    if (b.resolve(nm) != null and !b.isNonFnParam(nm)) return null;
    // A constructible same-named class that shadows this call per the scope
    // rules (an own-scope constructor, or no applicable same-named factory)
    // is the Kotlin target: never splice an inline factory over it —
    // `MutableVector(arr, size)` inside the class body binds the internal
    // constructor, not the reified `MutableVector(size, init)` factory that
    // happens to fit the arity.
    if (try shadowedByClass(b, callee, args)) return null;
    const inline_call_shape = CallShape{
        .want = args.len,
        .last_is_lambda = lastArgIsLambdaOrAnon(args),
        .trailing_lambda_arity = trailingLambdaArity(args),
        .call_file = callee.Path.segments[0].span.file,
        .arg0_class_literal = args.len != 0 and args[0] == .MemberRef and
            std.mem.eql(u8, args[0].MemberRef.name.name, "class"),
    };
    // An explicit `<T>` argument binds a reified parameter, so a reified
    // inline overload of this shape outranks a non-reified `KClass<T>`
    // namesake (which would lower `<T>` as a constructor value instead of
    // binding `T::class`). Splice the reified overload directly.
    if (ast_type_args.len != 0) {
        if (inline_state.reifiedInlineFnAstFor(nm, inline_call_shape)) |rf| {
            if (bareInlineNeedsSplice(b, nm, rf, args)) {
                const expected = b.peekExpected();
                const exp_ptr: ?*const ast.TypeRef = if (expected) |*_e| _e else null;
                var selected = if (inline_state.inlineIdByAst(rf)) |id|
                    try selectedCallArgsForBuilder(
                        b,
                        FuncId.from(id),
                        args,
                        ast_arg_names,
                        exprSpan(callee),
                        call.has_trailing_lambda,
                    )
                else
                    SelectedCallArgs{ .args = args, .names = ast_arg_names };
                defer selected.deinit(b.allocator);
                inline_call.splice_route_tag = "tryBareInlineExpansion:7457";
                if (try tryInlineCallWithTypeArgs(b, nm, rf, selected.args, selected.names, null, ast_type_args, exp_ptr)) |r| {
                    return r;
                }
            }
        }
    }
    const nlr_dbg = if (runtime.envOnce("KLIO_EF_TRACE")) |efw| std.mem.eql(u8, efw, nm) else false;
    if (try inlineTargetForBareCall(b, &callee.Path.segments[0], args, ast_arg_names, inline_call_shape)) |f| {
        if (nlr_dbg) {
            const last_stmts: usize = if (args.len > 0 and args[args.len - 1] == .Lambda) args[args.len - 1].Lambda.body.stmts.len else 999;
            std.debug.print("[tbie] synchronized file={d} in_fn={s} target-found needs={} nlr={} nstmts={d}\n", .{ callee.Path.segments[0].span.file.int(), build.currentRealFn() orelse "-", bareInlineNeedsSplice(b, nm, f, args), inline_call.argLambdaHasNonlocalReturn(args), last_stmts });
        }
        // A reified inline overload whose type parameter lives only in
        // the trailing lambda's parameter list (`T.(R) -> Unit`) cannot
        // bind that parameter from a lambda that declares fewer
        // arguments — `post("/p") { … }` against
        // `post<reified R>(path, RoutingContext.(R) -> Unit)`. Kotlin
        // drops such an overload (R unconstrained) and resolves the call
        // to a non-reified namesake; decline the splice so the normal
        // call path picks the plain `post(path, RoutingHandler)`.
        const reified_underfilled = ast_type_args.len == 0 and
            anyReified(f.type_params) and
            inline_call_shape.trailing_lambda_arity != null and
            reifiedNeedsLambdaArity(b, f, inline_call_shape.trailing_lambda_arity.?) and
            !inline_call.reifiedBindableFromArgs(b, f, args, ast_arg_names);
        if (!reified_underfilled and bareInlineNeedsSpliceT(b, nm, f, args, ast_type_args.len != 0)) {
            const expected = b.peekExpected();
            const exp_ptr: ?*const ast.TypeRef = if (expected) |*_e| _e else null;
            var selected = if (inline_state.inlineIdByAst(f)) |id|
                try selectedCallArgsForBuilder(
                    b,
                    FuncId.from(id),
                    args,
                    ast_arg_names,
                    exprSpan(callee),
                    call.has_trailing_lambda,
                )
            else
                SelectedCallArgs{ .args = args, .names = ast_arg_names };
            defer selected.deinit(b.allocator);
            inline_call.splice_route_tag = "tryBareInlineExpansion:7497";
            if (try tryInlineCallWithTypeArgs(b, nm, f, selected.args, selected.names, null, ast_type_args, exp_ptr)) |r| {
                return r;
            }
            if (nlr_dbg) std.debug.print("[tbie] synchronized in_fn={s} SPLICE-DECLINED\n", .{build.currentRealFn() orelse "-"});
        }
    }
    if (nlr_dbg) std.debug.print("[tbie] synchronized file={d} NO-TARGET-OR-DECLINED\n", .{callee.Path.segments[0].span.file.int()});
    return null;
}

/// Package-qualified inline expansion: `kotlin.synchronized(lock) { ... }`,
/// `kotlinx.atomicfu.locks.synchronized(lock, block)`. Kotlin inlines an
/// inline fun at every call spelling; the bare-path tier alone left
/// package-qualified wrapper chains framed (the compose sync chain
/// materialized a closure per block through three forwarding wrappers).
/// Applies only when the WHOLE dotted prefix equals the candidate's
/// declaring package, so a value/class/companion prefix never matches and
/// those calls keep their existing routes.
fn tryQualifiedInlineExpansion(b: *FuncBuilder, expr: *const Expr) Allocator.Error!?Reg {
    const call = expr.Call;
    const callee = call.callee;
    const args = call.args;
    // Flatten the callee into a dotted name run: either a multi-segment
    // Path, or a Member chain (`kotlin.synchronized(...)` parses as
    // Member(receiver=Path(kotlin), name=synchronized)) whose links are
    // all plain non-safe accesses over a Path head.
    var names: std.ArrayList([]const u8) = .empty;
    defer names.deinit(b.allocator);
    {
        var member_names: std.ArrayList([]const u8) = .empty;
        defer member_names.deinit(b.allocator);
        var cur = callee;
        while (cur.* == .Member) {
            if (cur.Member.safe) return null;
            try member_names.append(b.allocator, cur.Member.name.name);
            cur = cur.Member.receiver;
        }
        if (cur.* != .Path) return null;
        for (cur.Path.segments) |seg| try names.append(b.allocator, seg.name);
        var i = member_names.items.len;
        while (i > 0) {
            i -= 1;
            try names.append(b.allocator, member_names.items[i]);
        }
    }
    if (names.items.len < 2) return null;
    const segs = names.items;
    const nm = segs[segs.len - 1];
    const qtrace = if (runtime.envOnce("KLIO_QIE_TRACE")) |w| std.mem.eql(u8, w, nm) else false;
    // A resolvable head names a value chain, not a package path; a class
    // head is a companion/static route.
    if (b.resolve(segs[0]) != null) {
        if (qtrace) std.debug.print("[qie] {s}: head resolves\n", .{nm});
        return null;
    }
    const cands = inline_state.candidatesForName(nm) orelse {
        if (qtrace) std.debug.print("[qie] {s}: no candidates\n", .{nm});
        return null;
    };
    var pkg_buf: std.ArrayList(u8) = .empty;
    defer pkg_buf.deinit(b.allocator);
    for (segs[0 .. segs.len - 1], 0..) |seg, i| {
        if (i != 0) try pkg_buf.append(b.allocator, '.');
        try pkg_buf.appendSlice(b.allocator, seg);
    }
    const pkg = pkg_buf.items;
    var picked: ?*const ast.Function = null;
    for (cands) |f| {
        if (f.receiver_type != null) continue;
        if (inline_state.inlineMemberOwner(f) != null) continue;
        const fpkg = b.module.packageOfFile(f.name.span.file) orelse {
            if (qtrace) std.debug.print("[qie] {s}: cand file={d} no package\n", .{ nm, f.name.span.file.int() });
            continue;
        };
        if (!std.mem.eql(u8, fpkg, pkg)) {
            if (qtrace) std.debug.print("[qie] {s}: cand pkg={s} want={s}\n", .{ nm, fpkg, pkg });
            continue;
        }
        if (!qualifiedInlineArityFits(f, args.len)) {
            if (qtrace) std.debug.print("[qie] {s}: arity misfit\n", .{nm});
            continue;
        }
        // Same-package overloads that both fit: the dynamic path ranks.
        if (picked != null) return null;
        picked = f;
    }
    const f = picked orelse {
        if (qtrace) std.debug.print("[qie] {s}: no pick\n", .{nm});
        return null;
    };
    if (!bareInlineNeedsSpliceT(b, nm, f, args, call.type_args.len != 0)) {
        if (qtrace) std.debug.print("[qie] {s}: needs-splice false\n", .{nm});
        return null;
    }
    if (qtrace) std.debug.print("[qie] {s}: splicing pkg={s}\n", .{ nm, pkg });
    const expected = b.peekExpected();
    const exp_ptr: ?*const ast.TypeRef = if (expected) |*_e| _e else null;
    var selected = if (inline_state.inlineIdByAst(f)) |id|
        try selectedCallArgsForBuilder(
            b,
            FuncId.from(id),
            args,
            call.arg_names,
            exprSpan(callee),
            call.has_trailing_lambda,
        )
    else
        SelectedCallArgs{ .args = args, .names = call.arg_names };
    defer selected.deinit(b.allocator);
    inline_call.splice_route_tag = "tryQualifiedInlineExpansion:7606";
    return try tryInlineCallWithTypeArgs(b, nm, f, selected.args, selected.names, null, call.type_args, exp_ptr);
}

fn qualifiedInlineArityFits(f: *const ast.Function, want: usize) bool {
    if (want > f.params.len) return false;
    for (f.params) |*p| {
        if (p.is_vararg) return false;
    }
    var i: usize = want;
    while (i < f.params.len) : (i += 1) {
        if (f.params[i].default == null) return false;
    }
    return true;
}

/// Whether any registered class's fqn ends in `.{name}` or `${name}` (a
/// nested/companion class reachable by simple name from some scope).
/// The nesting tree's conservative complement: splice windows whose owner
/// chain is unknown cannot walk the tree, so this module-wide probe keeps
/// a capitalized bare call from being mis-claimed as a member call.
fn anyClassNamed(b: *FuncBuilder, name: []const u8) bool {
    for (b.module.classes.items) |*c| {
        const fqn = c.fqn;
        if (fqn.len > name.len and std.mem.endsWith(u8, fqn, name)) {
            const sep = fqn[fqn.len - name.len - 1];
            if (sep == '.' or sep == '$') return true;
        }
        if (std.mem.eql(u8, c.name, name)) return true;
    }
    return false;
}

/// Whether the eager-vs-lazy audit is enabled (`KLIO_EAGER_AUDIT=1`).
fn eagerAuditOn() bool {
    const S = struct {
        var cached: ?bool = null;
    };
    if (S.cached) |v| return v;
    const on = runtime.envOnce("KLIO_EAGER_AUDIT") != null;
    S.cached = on;
    return on;
}

fn lowerCallGeneral(b: *FuncBuilder, expr: *const Expr) Allocator.Error!Reg {
    const call = expr.Call;
    const callee = call.callee;
    const args = call.args;
    const ast_arg_names = call.arg_names;
    const ast_type_args = call.type_args;
    const is_infix = call.is_infix;

    // A bare ctor callee naming a nested class must bind the one in THIS
    // enclosing-class chain, not a same-simple-name nested class in a sibling
    // outer class. Walk the owner's FQN, and for each prefix that is itself a
    // CLASS (never a package — so a same-package top-level is left alone),
    // check for a nested `<prefix>.<name>`. Only rewrite when it differs from
    // the bare resolution (a genuine collision), to the qualified path.
    if (!is_infix and ast_type_args.len == 0 and callee.* == .Path and
        callee.Path.segments.len == 1 and b.resolve(callee.Path.segments[0].name) == null)
    {
        const cname = callee.Path.segments[0].name;
        if (b.ownerClass()) |owner| resolve: {
            const ocid = b.module.classId(owner) orelse break :resolve;
            if (ocid.int() >= b.module.classes.items.len) break :resolve;
            const bare = b.module.classIdIndexed(cname, b.self_package, callee.Path.segments[0].span.file);
            var prefix: []const u8 = b.module.classes.items[ocid.int()].fqn;
            while (std.mem.lastIndexOfScalar(u8, prefix, '.')) |dot| {
                prefix = prefix[0..dot];
                if (b.module.classIdByFqn(prefix) == null) continue; // package, not a class
                const cand = try std.fmt.allocPrint(b.allocator, "{s}.{s}", .{ prefix, cname });
                const cand_cid = b.module.classIdByFqn(cand);
                if (cand_cid != null and (bare == null or cand_cid.?.int() != bare.?.int())) {
                    var segs: std.ArrayList(ast.Ident) = .empty;
                    var it = std.mem.splitScalar(u8, cand, '.');
                    while (it.next()) |seg| try segs.append(b.allocator, .{ .name = seg, .span = callee.Path.segments[0].span });
                    const new_callee = try b.allocator.create(Expr);
                    new_callee.* = Expr{ .Path = .{ .segments = try segs.toOwnedSlice(b.allocator), .span = callee.Path.span } };
                    var new_call = call;
                    new_call.callee = new_callee;
                    const rewritten = Expr{ .Call = new_call };
                    return lowerCallGeneral(b, &rewritten);
                }
                b.allocator.free(cand);
            }
        }
    }

    // `this.onError(index)` — an inline lambda PARAMETER with a receiver type
    // (`String.(Int) -> Nothing`) invoked through an explicit `this`. The
    // qualifier names the lambda's receiver, not a member of it, so this is
    // the same splice the bare form takes; without the arm the call emitted
    // a member dispatch that no class declares.
    if (!is_infix and callee.* == .Member and !callee.Member.safe and
        callee.Member.receiver.* == .This and callee.Member.receiver.This.qualifier == null)
    {
        const lam_name = callee.Member.name.name;
        if (b.inlineLambdaFor(lam_name)) |lam| {
            if (!b.hasEnclosingMember(lam_name)) {
                const recv_reg = try lowerExpr(b, callee.Member.receiver);
                return try inline_call.spliceInlineLambdaOn(b, lam_name, lam, args, recv_reg, callee.Member.receiver);
            }
        }
    }

    // `flow.emit(1)` — an inline lambda PARAMETER with a RECEIVER-typed
    // function type (`T.(Int) -> Unit`) invoked with an explicit receiver
    // expression. Kotlin's invoke convention resolves the local parameter
    // over the receiver's same-named MEMBER (the local scope is nearer), so
    // the call splices the lambda with the qualifier as its receiver —
    // SharedFlowTest's testSubscriptionByFirstSuspensionInCollect calls
    // `flow.emit(1)` where `emit: T.(Int) -> Unit` must shadow
    // MutableStateFlow's own `emit`. Receiver-typed params only: a plain
    // `(Int) -> Unit` param is inapplicable to a qualified call and the
    // member keeps it.
    if (!is_infix and callee.* == .Member and !callee.Member.safe and
        callee.Member.receiver.* != .This)
    {
        const lam_name = callee.Member.name.name;
        if (b.isReceiverLambdaParam(lam_name)) {
            if (b.inlineLambdaFor(lam_name)) |lam| {
                if (!b.hasEnclosingMember(lam_name)) {
                    const recv_reg = try lowerExpr(b, callee.Member.receiver);
                    return try inline_call.spliceInlineLambdaOn(b, lam_name, lam, args, recv_reg, callee.Member.receiver);
                }
            }
        }
    }

    // Inline expansion (suspend-inline only).
    if (try tryBareInlineExpansion(b, expr)) |r| {
        return r;
    }

    // `collector.block()` — an EXPLICIT receiver invoking the enclosing
    // class's RECEIVER-function-typed property (`SafeFlow.block: suspend
    // FlowCollector.() -> Unit`): Kotlin runs the stored callable with the
    // explicit value as its receiver. Without this arm the call dispatched
    // as a member of the receiver and missed (`invoke` on NopCollector).
    if (!is_infix and callee.* == .Member and !callee.Member.safe and
        callee.Member.receiver.* != .This)
    {
        const mname0 = callee.Member.name.name;
        const own_recv_fn = blk: {
            if (b.resolve("this") == null) break :blk false;
            var owner = b.ownerClass() orelse build.currentOwnerClass();
            var hops: usize = 0;
            while (owner) |o| : (hops += 1) {
                if (hops > 32) break;
                if (b.module.registry.recv_fn_props.get(.{ .a = o, .b = mname0 }) != null) break :blk true;
                owner = b.module.registry.enclosing_class.get(o);
            }
            break :blk false;
        };
        if (own_recv_fn) {
            const recv_r = try lowerExpr(b, callee.Member.receiver);
            const this_reg = b.resolve("this").?;
            const cal = b.allocReg();
            const fld = try b.module.internConst(b.allocator, .{ .String = mname0 });
            try b.push(.{ .GetField = .{ .dst = cal, .receiver = this_reg, .field = fld } });
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const dst = b.allocReg();
            try b.push(.{ .CallValueWithThis = .{
                .dst = dst,
                .callee = cal,
                .receiver = recv_r,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
    }

    // Inside an inline-extension splice, a bare call to a member of the
    // spliced extension's bound receiver (`receiveNullable(...)` inside a
    // spliced `ApplicationCall.receive`) is `this.member(...)` on that
    // receiver. Resolve it here, before the bare-name paths below treat the
    // member as a top-level function (which would lose the receiver). The
    // bound `this` is a local register (the splice's receiver binding), not a
    // captured frame slot, so dispatch it as an explicit `CallMember`.
    if (!is_infix and callee.* == .Path and callee.Path.segments.len == 1 and
        b.currentInlineFn() != null)
    {
        const nm = callee.Path.segments[0].name;
        // Only route to the spliced receiver when the bare name is a member
        // of it or names an extension whose declared receiver type is
        // compatible with the spliced receiver's type chain. A bare call
        // whose only extension namesakes target unrelated types (`maxOf(a,
        // b)` inside `Buffer.indexOf`, whose extension overloads are
        // `Iterable.maxOf` / array `maxOf`) is the package-level function,
        // not a receiver member — it must fall through to the bare-name path.
        var recv_chain = try narrowingRecvChain(b);
        // Inside an inline splice the ACTIVE receiver is the splice's — for
        // `Greeter().apply { greet() }` the substituted concrete head — and
        // the enclosing function's own receiver context says nothing about
        // it. Without this, the receiver's member could not shadow a
        // same-named top-level function.
        if (recv_chain == null) {
            if (b.spliceRecvTy()) |sr| recv_chain = try recvChainOf(b, sr);
        } else if (b.lambda_splice_resolve != null and inline_call.rfsEnabled()) {
            // A spliced receiver LAMBDA is the innermost implicit receiver,
            // AHEAD of the enclosing (framed) receiver the narrowing chain
            // starts from: `with(operation) { executeWithComposeStackTrace(...) }`
            // inside a framed `OpIterator.()` block resolves the bare call
            // against the with-subject first, exactly as kotlinc scopes it.
            if (b.spliceRecvTy()) |sr| {
                var sh = typeHead(std.mem.trimEnd(u8, sr, "?"));
                // The registry keys carry file-collision mangles
                // (`Operation$f429`); resolve the source-spelled head
                // through the class index scoped at this reference site.
                if (b.module.classIdIndexed(sh, b.self_package, callee.Path.segments[0].span.file)) |cid| {
                    if (cid.int() < b.module.classes.items.len) sh = b.module.classes.items[cid.int()].name;
                }
                if (recv_chain.?.len == 0 or !std.mem.eql(u8, typeHead(std.mem.trimEnd(u8, recv_chain.?[0], "?")), sh)) {
                    const inner = try recvChainOf(b, sh);
                    const outer = recv_chain.?;
                    const joined = try b.allocator.alloc([]const u8, inner.len + outer.len);
                    @memcpy(joined[0..inner.len], inner);
                    @memcpy(joined[inner.len..], outer);
                    recv_chain = joined;
                }
            }
        }
        // A captured crossinline param shadows a same-named member of the
        // anonymous object being lowered (`object : Iterable<T> { override fun
        // iterator() = iterator() }` — the bare `iterator()` is the captured
        // lambda, not the override, which would recurse). Let it fall through
        // to the anon-capture invocation below.
        if (b.resolve(nm) == null and !b.knowsOuter(nm) and !isLowerAnonCapture(nm) and
            !nameHasReifiedInlineCandidate(nm))
        {
            // Confident the call binds to the spliced `this`: the name is a
            // member of its class, or an extension whose declared receiver is
            // compatible with the *known* receiver-type chain. Dispatch it
            // straight onto the bound receiver register.
            // A NESTED CLASS's name sits in the own-member set but a
            // capitalized bare call to it is a CONSTRUCTOR, never a
            // method on `this` — leave it to the ctor resolution.
            const is_scoped_class = nm.len > 0 and std.ascii.isUpper(nm[0]) and
                (scopedClassIdForRead(b, nm, callee.Path.segments[0].span.file) != null or
                    b.module.classId(nm) != null or anyClassNamed(b, nm));
            // A DECLARED MEMBER of the spliced receiver's own hierarchy
            // (`fetchStreamingResponse()` inside a spliced member-inline
            // `HttpStatement.body`) binds the receiver the same way an
            // extension namesake does — the hierarchy shadow set answers
            // membership even when the member is internal.
            const member_of_recv = blk: {
                const chain = recv_chain orelse break :blk false;
                if (chain.len == 0) break :blk false;
                const hs = b.module.registry.hierarchy_shadow_names.get(chain[0]) orelse {
                    // An image-loaded class carries no per-build shadow
                    // entry; the function index still proves member-EXT
                    // membership (`executeWithComposeStackTrace` inside
                    // `with(operation) { ... }` is Operation's member
                    // extension in the pack).
                    if (!inline_call.rfsEnabled()) break :blk false;
                    break :blk mextCandidateOwnedBy(b, nm, chain[0], callee.Path.segments[0].span.file) catch false;
                };
                if (!hs.complete) break :blk false;
                break :blk hs.names.contains(nm);
            };
            // An extension NAMESAKE on the receiver chain does not pin the
            // walk: the static bare-extension resolution below ranks the
            // overload set with argument evidence (`plus(element)` inside a
            // spliced `plusElement` must pick the `element: T` overload; the
            // walk's member-first runtime pick took the Iterable one), and
            // its own deferral remains the fallback when the shapes cannot
            // prove a pick.
            var binds_this = !is_scoped_class and (b.hasOwnMember(nm) or member_of_recv);
            // Under the subject tower, when the name ALSO has an
            // extension candidate whose declared receiver matches the
            // chain, the member-vs-extension arbitration needs argument
            // applicability — static resolution's strength, not the
            // runtime walk's (`putAll(pairs)` must drop the member
            // `putAll(Map)` for the Iterable-pairs extension). Fall
            // through to the static tiers; the commit-point parity guard
            // still defers plain top-level picks.
            if (binds_this and inline_call.rfsEnabled() and b.encl_tower_depth > 0 and
                nameHasReceiverCandidate(b, nm, null))
            {
                binds_this = false;
            }
            if (runtime.envOnce("KLIO_BINDS_TRACE")) |w| {
                if (std.mem.eql(u8, w, nm)) {
                    const c0: []const u8 = if (recv_chain) |ch| (if (ch.len != 0) ch[0] else "<empty>") else "<null>";
                    const hs_state: []const u8 = if (recv_chain) |ch| blk: {
                        if (ch.len == 0) break :blk "-";
                        const hs = b.module.registry.hierarchy_shadow_names.get(ch[0]) orelse break :blk "no-entry";
                        if (!hs.complete) break :blk "incomplete";
                        break :blk if (hs.names.contains(nm)) "contains" else "missing";
                    } else "-";
                    std.debug.print("[binds] {s} chain0={s} hs={s} own={} scoped_class={} binds={}\n", .{
                        nm, c0, hs_state, b.hasOwnMember(nm), is_scoped_class, binds_this,
                    });
                }
            }
            if (binds_this) {
                // Pinning the dispatch to the innermost bound `this` is only
                // sound when the receiver evidence proves that value serves
                // the member (`member_of_recv`, an extension on the proven
                // chain). The `hasOwnMember` leg names a member of the
                // lexically enclosing CLASS — inside a receiver lambda whose
                // receiver does not own the member (a `(Long) -> R` frame
                // callback created in a `CoroutineScope.()` block, calling a
                // Recomposer private), the bound `this` is the scope receiver
                // and the owner sits further out; a lazily lowered pack body
                // has no receiver-type context to tell the cases apart. Emit
                // the receiver-walking form for that leg: the walk tries the
                // bound receiver's members first (identical to the pin when
                // `this` IS the owner), then each enclosing receiver.
                if (b.resolve("this")) |bound_this| {
                    // The PROVEN leg resolves statically: the chain's head
                    // class declares the member, so the call binds its
                    // virtual slot instead of walking per invocation
                    // (`propertyEquals { ... }` inside a spliced
                    // `(object {}).let` ran the walk 200 times per suite).
                    // Sound only when NO enclosing receiver could shadow:
                    // the chain must be exactly the bound receiver. With
                    // outer receivers in scope the walking form arbitrates
                    // (the atomicfu mutex splice livelocked when pinned).
                    if (member_of_recv and ast_type_args.len == 0 and
                        recv_chain.?.len == 1 and
                        // Under the subject tower the bound `this` is the
                        // spliced SUBJECT; a pin resolved against a lexical
                        // owner would dispatch that owner's member ON the
                        // subject (CallVirtual Holder.eachInline on the
                        // StringBuilder). The walking form ranks receivers
                        // correctly there.
                        b.encl_tower_depth == 0 and
                        runtime.envOnce("KLIO_SPLICE_PIN") == null and
                        allNull(ast_arg_names)) pin: {
                        const chain0 = recv_chain.?[0];
                        // The pin dispatches on the BOUND `this`, so the
                        // chain's head must be that same value. Inside a
                        // receiver lambda over another type the two diverge —
                        // the chain names the enclosing class that owns the
                        // member while `this` is the lambda's receiver — and
                        // pinning then dispatched the owner's member on the
                        // lambda receiver (`eachInline` on
                        // kotlin.text.StringBuilder inside `with(sb) { … }`),
                        // blocking the outward walk a non-inline sibling uses.
                        if (b.recvTy() orelse b.spliceRecvTy()) |inner| {
                            const ih = typeHead(std.mem.trimEnd(u8, inner, "?"));
                            const ch = typeHead(std.mem.trimEnd(u8, chain0, "?"));
                            if (!std.mem.eql(u8, ih, ch) and
                                !std.mem.eql(u8, simpleTail(ih), simpleTail(ch))) break :pin;
                        }
                        const pin_cid = (if (std.mem.indexOfScalar(u8, chain0, '.') != null)
                            b.module.classIdByFqn(chain0)
                        else
                            b.module.uniqueClassIdBySimpleName(chain0)) orelse break :pin;
                        var shape_set = try buildStaticReturnArgShapes(b, args, ast_arg_names);
                        defer shape_set.deinit(b.allocator);
                        const pin_recv_ref: ir.TypeRef = .{ .name = chain0, .nullable = false, .args = &.{} };
                        const resolved = b.module.resolveMemberCall(pin_cid, nm, shape_set.shapes, .{
                            .caller_file = callee.Path.segments[0].span.file,
                            .lexical_owner = null,
                            .actual_type_param_bounds = &.{},
                            .receiver_type = pin_recv_ref,
                        });
                        const target = resolved.target orelse break :pin;
                        const tf = b.module.funcById(target) orelse break :pin;
                        if (!tf.hasBody()) break :pin;
                        // A FUNCTION-SPELLED parameter fed a non-lambda
                        // argument is exactly the member-vs-extension shape
                        // the static shapes cannot always refute (the arg's
                        // static type may be unknowable through the splice
                        // substitution): `url(urlString)` must not pin the
                        // member `url(block)`. Fall to the walking form,
                        // whose runtime adjudication sees the value.
                        for (tf.params, 0..) |*tp, tpi| {
                            if (tpi == 0 and std.mem.eql(u8, tp.name, "this")) continue;
                            const ai = tpi - @intFromBool(tf.params.len != 0 and std.mem.eql(u8, tf.params[0].name, "this"));
                            if (ai >= args.len) break;
                            if (recvHeadIsFunctionType(tp.ty.name) and
                                args[ai] != .Lambda and args[ai] != .AnonFun) break :pin;
                        }
                        // A member in a stdlib/pack package may be shadowed
                        // by a HOST binding the lowering cannot see
                        // (atomicfu's ReentrantLock.unlock stub deadlocked
                        // when its interpreted body was pinned). Pin only
                        // program-owned declarations.
                        const shipped_pkg = std.mem.eql(u8, tf.package, "kotlin") or
                            std.mem.startsWith(u8, tf.package, "kotlin.") or
                            std.mem.startsWith(u8, tf.package, "kotlinx.") or
                            std.mem.startsWith(u8, tf.package, "androidx.") or
                            std.mem.startsWith(u8, tf.package, "io.ktor");
                        if (shipped_pkg) break :pin;
                        const run = try lowerArgRun(b, args);
                        const dst = b.allocReg();
                        orEmitAudit(b, "inline_splice_recv_pin", "CallVirtual", nm);
                        try b.push(.{ .CallVirtual = .{
                            .dst = dst,
                            .receiver = bound_this,
                            .slot = ir.MethodSlotId.fromFunc(target),
                            .args = run[0],
                            .n_args = run[1],
                        } });
                        return dst;
                    }
                    const run = try lowerArgRun(b, args);
                    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
                    const dst = b.allocReg();
                    const nmc = try b.module.internConst(b.allocator, .{ .String = nm });
                    orEmitAudit(b, "inline_splice_recv_walk", "CallMemberOrGlobal", nm);
                    try b.push(.{ .CallMemberOrGlobal = .{
                        .dst = dst,
                        .this_idx = 0,
                        .name = nmc,
                        .trailing_lambda = b.callTrailingLambda(),
                        .args = run[0],
                        .n_args = run[1],
                        .arg_names = arg_names,
                        // With the runtime subject tower live, the chain
                        // already holds every nested subject in scope order;
                        // pinning one bound register would put it AHEAD of an
                        // inner subject and invert Kotlin's innermost-first
                        // receiver ranking.
                        .recv = if (b.encl_tower_depth > 0) null else bound_this,
                        .candidates = try cmgCandidates(b, nm, callee.Path.segments[0].span.file, run[1]),
                        // Under the subject tower the runtime chain ranks the
                        // receivers; a static head would pin the strict-ext
                        // arm to the SUBJECT and raise where the walk should
                        // fall outward (`eachInline` in `with(sb) { ... }` is
                        // the enclosing Holder's member-inline).
                        .static_recv = if (b.encl_tower_depth > 0) null else try cmgStaticRecv(b),
                    } });
                    return dst;
                }
            } else if (recv_chain == null and nameHasReceiverCandidate(b, nm, null)) {
                // The name is an extension namesake but the spliced receiver's
                // type is unknown here, so we cannot prove it binds to the
                // innermost `this`. Emit the receiver-walking form rather than
                // pinning it to `this`: a bare `collect` inside a nested
                // `FlowCollector.()` lambda must reach the outer `Flow`
                // receiver (`this@unsafeTransform`), not dispatch on the
                // collector. `CallMemberOrGlobal` tries the bound receiver,
                // then each enclosing receiver innermost-first, before any
                // global. Pass the bound `this` register directly so the splice
                // receiver (`filterIsInstanceTo` on the bound `List`) is the
                // innermost candidate even though it is a local register, not a
                // capture. Still handled here so the bare-name paths below
                // cannot grab it as a top-level function and drop the receiver.
                if (b.resolve("this")) |bound_this| {
                    const run = try lowerArgRun(b, args);
                    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
                    const dst = b.allocReg();
                    const nmc = try b.module.internConst(b.allocator, .{ .String = nm });
                    orEmitAudit(b, "inline_splice_unknown_recv", "CallMemberOrGlobal", nm);
                    try b.push(.{ .CallMemberOrGlobal = .{
                        .dst = dst,
                        .this_idx = 0,
                        .name = nmc,
                        .trailing_lambda = b.callTrailingLambda(),
                        .args = run[0],
                        .n_args = run[1],
                        .arg_names = arg_names,
                        .recv = if (b.encl_tower_depth > 0) null else bound_this,
                        .candidates = try cmgCandidates(b, nm, callee.Path.segments[0].span.file, run[1]),
                        // Under the subject tower the runtime chain ranks the
                        // receivers; a static head would pin the strict-ext
                        // arm to the SUBJECT and raise where the walk should
                        // fall outward (`eachInline` in `with(sb) { ... }` is
                        // the enclosing Holder's member-inline).
                        .static_recv = if (b.encl_tower_depth > 0) null else try cmgStaticRecv(b),
                    } });
                    return dst;
                } else if (b.knowsOuter("this") or b.capturesThisSlot()) {
                    const run = try lowerArgRun(b, args);
                    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
                    const this_idx = try b.recordCapture("this");
                    const dst = b.allocReg();
                    const nmc = try b.module.internConst(b.allocator, .{ .String = nm });
                    orEmitAudit(b, "inline_splice_unknown_recv", "CallMemberOrGlobal", nm);
                    try b.push(.{ .CallMemberOrGlobal = .{
                        .dst = dst,
                        .this_idx = this_idx,
                        .name = nmc,
                        .trailing_lambda = b.callTrailingLambda(),
                        .args = run[0],
                        .n_args = run[1],
                        .arg_names = arg_names,
                        .candidates = try cmgCandidates(b, nm, callee.Path.segments[0].span.file, run[1]),
                        .static_recv = try cmgStaticRecv(b),
                    } });
                    return dst;
                }
            }
        }
    }

    // Bare call to a name the enclosing anon object closes over.
    if (!is_infix and callee.* == .Path and callee.Path.segments.len == 1 and
        b.resolve(callee.Path.segments[0].name) == null and
        isLowerAnonCapture(callee.Path.segments[0].name))
    {
        const nm0 = callee.Path.segments[0].name;
        const idx = try b.recordCapture(nm0);
        const callee_r = b.allocReg();
        try b.push(.{ .LoadCapture = .{ .dst = callee_r, .idx = idx } });
        const run = try lowerArgRun(b, args);
        const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
        const dst = b.allocReg();
        // Inside a receiver splice the captured name may shadow a MEMBER
        // of the spliced receiver (`lock()` in withLock's body vs the
        // caller's captured `val lock`): Kotlin resolves the body's bare
        // call to the receiver member, and the capture is usually not
        // even callable — emit the runtime-arbitrated form.
        if (b.spliceRecvTy() != null) {
            if (try resolveThisForBareCallNoBind(b)) |this_reg| {
                const nmc = try b.module.internConst(b.allocator, .{ .String = nm0 });
                orEmitAudit(b, "cvom_anon_capture_splice", "CallValueOrMember", nm0);
                try b.push(.{ .CallValueOrMember = .{
                    .dst = dst,
                    .callee = callee_r,
                    .this_recv = this_reg,
                    .name = nmc,
                    .args = run[0],
                    .n_args = run[1],
                    .arg_names = arg_names,
                } });
                return dst;
            }
        }
        try b.push(.{ .CallValue = .{
            .dst = dst,
            .callee = callee_r,
            .args = run[0],
            .n_args = run[1],
            .arg_names = arg_names,
        } });
        return dst;
    }

    // Infix call `a fn b` → `a.fn(b)`.
    if (is_infix and args.len == 2 and callee.* == .Path and callee.Path.segments.len == 1) {
        // An infix call IS `a.f(b)`: route it through the member lowering
        // so it binds statically like the written-out form. The plain
        // CallMember emitted here left every infix extension walking by
        // name (`0 until times` inside `repeat`'s body, once per run).
        var member_callee = Expr{ .Member = .{
            .receiver = &args[0],
            .name = callee.Path.segments[0],
            .safe = false,
            .span = call.span,
        } };
        const member_call = Expr{ .Call = .{
            .callee = &member_callee,
            .args = args[1..],
            .arg_names = call.arg_names[1..],
            .type_args = call.type_args,
            .is_infix = false,
            .has_trailing_lambda = call.has_trailing_lambda,
            .span = call.span,
        } };
        return try lowerMemberCallFallback(b, &member_call);
    }

    // `suspend { … }` builder: the value is the lambda itself, with its
    // body marked suspend so dispatch can distinguish it from a plain
    // function value.
    if (callee.* == .Path and callee.Path.segments.len == 1 and
        std.mem.eql(u8, callee.Path.segments[0].name, "suspend") and
        args.len == 1 and args[0] == .Lambda)
    {
        b.pending_suspend_lambda = true;
        return lowerExpr(b, &args[0]);
    }
    // `contract { … }` — compile-time marker with no runtime effect.
    if (callee.* == .Path and callee.Path.segments.len == 1 and
        std.mem.eql(u8, callee.Path.segments[0].name, "contract") and
        args.len == 1 and args[0] == .Lambda)
    {
        return b.emitConst(.Unit);
    }
    // Self-call inside a tailrec fn → TailJump terminator. The jump
    // re-binds the function's parameters in place; an instance/extension
    // tailrec function carries its receiver as the leading implicit
    // param, and a bare recursive call keeps the same receiver, so the
    // arg run must lead with `this` — dropping it would shift every
    // re-bound parameter by one.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        if (b.tailrecSelf()) |ts| {
            if (std.mem.eql(u8, ts, callee.Path.segments[0].name)) {
                const run = if (b.tailrecSelfHasThis()) blk: {
                    const sp = exprSpan(callee);
                    const all = try b.allocator.alloc(Expr, args.len + 1);
                    defer b.allocator.free(all);
                    const synth_segs = try b.allocator.alloc(ast.Ident, 1);
                    defer b.allocator.free(synth_segs);
                    synth_segs[0] = .{ .name = "this", .span = sp };
                    all[0] = .{ .Path = .{ .segments = synth_segs, .span = sp } };
                    for (args, 0..) |arg, i| all[i + 1] = arg;
                    break :blk try lowerArgRun(b, all);
                } else try lowerArgRun(b, args);
                b.terminate(.{ .TailJump = .{ .args = run[0], .n_args = run[1] } });
                const dead = try b.allocBlock();
                b.switchTo(dead);
                return b.emitConst(.Unit);
            }
        }
    }

    // A ctor-property param shadowing a same-named vararg method must dispatch
    // by argument shape: a field initializer `val data = createFrom("a", "b")`
    // has the param in scope as a local, but the call belongs to the vararg
    // method, not the property lambda invoked with two arguments. Route to
    // member dispatch so `varargShadowedFieldInvoke` makes the pick.
    if (callee.* == .Path and callee.Path.segments.len == 1 and
        b.resolve(callee.Path.segments[0].name) != null and
        ctorParamShadowsVarargMethod(b, callee.Path.segments[0].name))
    {
        if (b.resolve("this")) |this_reg| {
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const dst = b.allocReg();
            const nmc = try b.module.internConst(b.allocator, .{ .String = callee.Path.segments[0].name });
            try b.push(.{ .CallMember = .{
                .dst = dst,
                .receiver = this_reg,
                .name = nmc,
                .trailing_lambda = b.callTrailingLambda(),
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
    }

    // A `name<T>(…)` call whose name resolves to a value parameter/local that
    // is not a local function names the SHADOWED global function/builder: a
    // value takes no call-site type arguments. `iterator<List<T>> { … }` inside
    // `windowedIterator(iterator: Iterator<T>, …)` binds the `iterator {}`
    // builder, not the `iterator` parameter. Load the global so the runtime
    // resolves the intrinsic builder rather than invoking the parameter.
    // Likewise a `name(…)` call whose name resolves to a value whose
    // DECLARED type cannot be invoked (`var globalFun: Int = globalFun()`
    // in a primary constructor: the parameter is an `Int`, the call is the
    // top-level function): a value of a primitive/String type, or of a
    // class with no `invoke` member, is never a callee.
    if (callee.* == .Path and callee.Path.segments.len == 1 and ast_type_args.len == 0) {
        const nm0 = callee.Path.segments[0].name;
        // A member FUNCTION of the enclosing class chain still takes the
        // call when a plain value shadows the name (`AbstractCoroutine`'s
        // `if (initParentJob) initParentJob(parent)`: the Boolean property
        // and the inherited `JobSupport.initParentJob(Job?)`).
        var chain_buf: [8]FuncId = undefined;
        const chain_fns = try enclosingChainMethodsNamed(b, nm0, callee.Path.segments[0].span.file, &chain_buf);
        if (b.resolve(nm0) != null and !b.isLocalFn(nm0) and !b.isLocalExtFn(nm0) and
            b.module.classIdIndexed(nm0, b.self_package, callee.Path.segments[0].span.file) == null and
            chain_fns.len == 0 and
            // Only redirect to a global when a global function/builder of this
            // name actually exists to receive the call. Without this guard a
            // local whose DECLARED type reads as non-invokable — a receiver
            // lambda's value parameter mis-typed as its own receiver class
            // (`{ block -> block(7) }` bound to `Cls.((Int) -> Unit) -> Unit`,
            // where the receiver leaks into `block`'s type) — emitted a
            // `LoadGlobal` for a name no global carries and failed at runtime
            // with "unresolved global". The local IS the callee: fall through
            // to the value-invocation path.
            b.module.hasBareCallCandidate(nm0, callee.Path.segments[0].span.file) and
            localValueNotInvokable(b, nm0))
        {
            const gv = b.allocReg();
            const cn = try b.module.internConst(b.allocator, .{ .String = nm0 });
            orEmitAudit(b, "call_shadowed_by_plain_value", "LoadGlobal", nm0);
            try b.push(.{ .LoadGlobal = .{ .dst = gv, .name = cn } });
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const dst = b.allocReg();
            try b.push(.{ .CallValue = .{
                .dst = dst,
                .callee = gv,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
    }
    if (callee.* == .Path and callee.Path.segments.len == 1 and ast_type_args.len != 0) {
        const nm0 = callee.Path.segments[0].name;
        if (b.resolve(nm0) != null and !b.isLocalFn(nm0) and
            b.module.classIdIndexed(nm0, b.self_package, callee.Path.segments[0].span.file) == null)
        {
            const gv = b.allocReg();
            const cn = try b.module.internConst(b.allocator, .{ .String = nm0 });
            orEmitAudit(b, "typed_call_shadowed_global", "LoadGlobal", nm0);
            try b.push(.{ .LoadGlobal = .{ .dst = gv, .name = cn } });
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const type_args = try helpers.internTypeArgsScoped(b, ast_type_args);
            const dst = b.allocReg();
            try b.push(.{ .CallValue = .{
                .dst = dst,
                .callee = gv,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
                .type_args = type_args,
            } });
            return dst;
        }
    }

    // A single-name callee resolving to a local binding / parameter is a
    // value invocation.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        // Same-named local-fn siblings are OVERLOADS: when the call's
        // static facts (arity, argument names, literal/declared type
        // heads) select exactly one, call through its mangled cell —
        // reachable both in the declaring scope and as a capture. Calls
        // no fact separates keep the plain last-decl binding below.
        const bare = callee.Path.segments[0].name;
        var local_fn_inapplicable = false;
        if (b.localFnOverloads(bare)) |ovs| {
            if (runtime.envOnce("KLIO_LFN_TRACE") != null)
                std.debug.print("[lfn] {s} ovs={d}\n", .{ bare, ovs.len });
            if (try selectLocalFnOverload(b, ovs, args, ast_arg_names)) |m| {
                if (runtime.envOnce("KLIO_LFN_TRACE") != null)
                    std.debug.print("[lfn] {s} selected={s} cell={} outer={}\n", .{ bare, m, b.resolve(m) != null, b.knowsOuter(m) });
                if (try lowerSelectedLocalOverloadCall(b, bare, m, args, ast_arg_names)) |r| return r;
            } else if (runtime.envOnce("KLIO_LFN_TRACE") != null)
                std.debug.print("[lfn] {s} no-select\n", .{bare});
        } else if (b.resolve(bare) != null and runtime.envOnce("KLIO_LFN_TRACE") != null)
            std.debug.print("[lfn] {s} no-registry\n", .{bare});
        // SELF-reference: a bare call to the enclosing local fn's own name
        // from inside its body — including generated nested lambdas (the
        // compose restart re-invoke) — binds the fn ITSELF through its
        // mangled cell. The plain name cannot serve it: a later same-named
        // sibling declaration rebinds the shared plain-name slot (last bind
        // wins), and Kotlin scopes this call to the declarations visible at
        // this point in the body — the enclosing fn, never the sibling.
        if (b.selfLocalFn()) |slf| {
            if (std.mem.eql(u8, slf.name, bare) and
                try selfLocalFnApplicable(b, slf.mangled, bare, args, ast_arg_names))
            {
                if (try lowerSelectedLocalOverloadCall(b, bare, slf.mangled, args, ast_arg_names)) |r| return r;
            }
        }
        if (b.localFnDecls(bare)) |decls| {
            local_fn_inapplicable = !(try anyLocalFnOverloadApplicable(
                b,
                decls,
                args,
                ast_arg_names,
            ));
            if (runtime.envOnce("KLIO_LFN_TRACE") != null)
                std.debug.print("[lfn] {s} decls={d} inapplicable={} plain={} mangled_cell={} mangled_outer={} splice_win={}\n", .{
                    bare,
                    decls.len,
                    local_fn_inapplicable,
                    b.resolve(bare) != null,
                    if (decls.len > 0) b.resolve(decls[0].mangled) != null else false,
                    if (decls.len > 0) b.knowsOuter(decls[0].mangled) else false,
                    b.lambda_splice_resolve != null,
                });
            // A LONE local fn reached from a NESTED body (its own body, or
            // a local fn declared inside it): the mangled overload cell
            // binds BEFORE the body lowers exactly so nested calls can
            // capture it. Route the call through the cell (`fun traverse`
            // inside GapComposer's `movableContentReferenceFor` recursing
            // into its encloser). The PLAIN name cannot serve even when it
            // IS a visible outer binding: a later same-named sibling
            // declaration (a validator extension beside the composable)
            // rebinds the shared plain-name slot, so a by-name capture
            // runs the sibling. Multi-overload sets select above; an
            // inapplicable local keeps outward resolution.
            // The plain name may also be bound to a same-named local
            // PROPERTY (`var seen = ...; fun seen(x)`): the property owns
            // the bare binding, so a CALL routes through the fn's mangled
            // cell — Kotlin resolves `seen(x)` to the fun and `seen` to
            // the var.
            const plain_is_property = b.resolve(bare) != null and !b.isLocalFn(bare);
            if (decls.len == 1 and !local_fn_inapplicable and
                (b.resolve(bare) == null or plain_is_property) and
                (b.resolve(decls[0].mangled) != null or b.knowsOuter(decls[0].mangled)))
            {
                if (try lowerSelectedLocalOverloadCall(b, bare, decls[0].mangled, args, ast_arg_names)) |r| return r;
            }
        }
        // A local function shadows an outer one by NAME, but only among
        // candidates that can take the call. A local `fun validate()` does
        // not hide the top-level `validate(block: () -> Unit)` from
        // `validate { … }`; invoking the local as a value made it call
        // itself for ever. With no applicable local, resolution continues
        // outward to the top-level / member candidates below.
        if (!local_fn_inapplicable) {
            if (try lowerValueInvocation(b, callee, args, ast_arg_names)) |r| return r;
            // A LONE applicable local fn reached as a CAPTURE (declared in
            // an enclosing body, called from this closure): invoke the
            // captured closure value. Without this the call fell through to
            // the classifier arms, and a local `fun Test(a, b)` lost to an
            // imported `kotlin.test.Test` inside `r.go { Test(1, 2) }`.
            // Two or more siblings select through the mangled binding above.
            // Gated on an actual classifier collision: a captured local fn
            // with NO same-named class keeps its established route (its
            // value binding is not always capturable — a `fun emit` inside
            // a runtime-lowered lambda resolves through the scoped-global
            // layers, not a capture slot).
            if (b.localFnDecls(bare) != null and b.resolve(bare) == null and b.knowsOuter(bare) and
                b.module.classIdIndexed(bare, b.self_package, callee.Path.segments[0].span.file) != null)
            {
                const cap = try resolveCapture(b, bare);
                const callee_r = b.allocReg();
                try b.push(.{ .CellGet = .{ .dst = callee_r, .cell = cap } });
                const run = try lowerArgRun(b, args);
                const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
                const dst = b.allocReg();
                orEmitAudit(b, "captured_local_fn_call", "CallValue", bare);
                try b.push(.{ .CallValue = .{
                    .dst = dst,
                    .callee = callee_r,
                    .args = run[0],
                    .n_args = run[1],
                    .arg_names = arg_names,
                } });
                return dst;
            }
        }
    }

    const callee_class_id: ?ir.ClassId = if (callee.* == .Path and callee.Path.segments.len == 1)
        b.module.classIdIndexed(callee.Path.segments[0].name, b.self_package, callee.Path.segments[0].span.file) orelse
            b.module.classIdExactImport(callee.Path.segments[0].name, callee.Path.segments[0].span.file)
    else
        null;
    const callee_is_object = if (callee_class_id) |cid|
        cid.int() < b.module.classes.items.len and b.module.classes.items[cid.int()].is_object
    else
        false;

    // Whether a single-segment class-name call resolves to the constructor.
    const shadowed_by_class = if (callee_is_object) false else try shadowedByClass(b, callee, args);
    var force_static_class = false;
    // A constructible same-named class competes with the function candidates.
    // Until constructors participate in the shared applicability set, the
    // deferred class-carrying form below compares both declarations on the
    // actual argument types (`Box(s.length)` constructs `Box(Int)`, not the
    // `fun Box(s: String)` factory).
    const class_competes = callee.* == .Path and callee.Path.segments.len == 1 and
        !shadowed_by_class and !callee_is_object and blk: {
        const cid = callee_class_id orelse break :blk false;
        if (cid.int() >= b.module.classes.items.len) break :blk false;
        const cls = &b.module.classes.items[cid.int()];
        // An abstract/interface/sealed class never constructs, so it
        // does not compete with the function candidates.
        if (cls.is_abstract) break :blk false;
        // The class competes when its primary constructor can take this
        // argument count, OR when the count exceeds the primary arity — a
        // secondary constructor (not visible in the IR class, which carries
        // only the primary) may accept it (`ByteString(bytes, 0, n)` binds
        // the `(ByteArray, Int, Int)` secondary, not `fun ByteString(vararg
        // Byte)`). Deferring an over-primary count to runtime is safe: when
        // no constructor actually matches, the runtime falls to the factory.
        var required: usize = 0;
        var has_vararg = false;
        for (cls.primary_params) |*p| {
            if (p.is_vararg) {
                has_vararg = true;
                continue;
            }
            if (!p.has_default) required += 1;
        }
        break :blk (args.len >= required and (has_vararg or args.len <= cls.primary_params.len)) or
            args.len > cls.primary_params.len;
    };

    // Path-callee with a registered top-level fn → Call{func}.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        if (try lowerPathCall(
            b,
            expr,
            shadowed_by_class,
            class_competes,
            &force_static_class,
        )) |r| return r;
    }

    // A named object is a singleton value, not a constructible class.
    // Once same-named function overloads have had their ordinary call tier,
    // invoke the exact object identity through its operator surface.
    if (callee_is_object) {
        return try emitObjectValueCall(b, args, ast_arg_names, ast_type_args, callee.Path.segments[0].name, callee_class_id.?);
    }

    // A LOCAL class declared in this function (or an enclosing one) shadows
    // any same-simple-name module class for a bare constructor call. Its
    // runtime `.Class` value is bound at the declaration; inside a nested
    // lambda it arrives through the capture set. Route the call through
    // that binding — the module-index class path below would construct an
    // unrelated class (a nested class of another owner) instead.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        const nm0 = callee.Path.segments[0].name;
        if (build.isLocalClassInScope(nm0) and b.resolve(nm0) == null and b.knowsOuter(nm0)) {
            const callee_r = try resolveCapture(b, nm0);
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const dst = b.allocReg();
            orEmitAudit(b, "local_class_capture_ctor", "CallValue", nm0);
            try b.push(.{ .CallValue = .{
                .dst = dst,
                .callee = callee_r,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
    }

    // Path-callee with a registered class name. The indexed lookup binds
    // the class visible from the caller's package and imports, so a
    // cross-package simple-name collision constructs the right class.
    // A typealias constructs its expansion (`typealias Node = ListNode;
    // Node("a")` is a ListNode constructor call), so an unindexed name
    // retries through the alias registry scoped at this reference site.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        const ctor_seg = callee.Path.segments[0];
        const ctor_cid: ?ir.ClassId = b.module.classIdIndexed(ctor_seg.name, b.self_package, ctor_seg.span.file) orelse
            b.module.classIdExactImport(ctor_seg.name, ctor_seg.span.file) orelse blk_alias: {
                const aref = ir.TypeRef{ .name = ctor_seg.name, .nullable = false, .args = &.{} };
                const resolved = try b.module.resolveTypeAliasAt(b.allocator, aref, ctor_seg.span.file, b.self_package);
                const rh = typeHead(std.mem.trimEnd(u8, resolved.name, "?"));
                if (std.mem.eql(u8, rh, ctor_seg.name)) break :blk_alias null;
                break :blk_alias b.module.classIdIndexed(rh, b.self_package, ctor_seg.span.file) orelse
                    b.module.classId(rh);
            };
        // An APPLICABLE own member named like a class in scope (`private fun
        // Json(arrays: Boolean, build: PolymorphicModuleBuilder<Any>.() -> Unit)`
        // beside the library's `Json` class) wins the bare call in Kotlin's
        // scope order: the implicit-this path binds the member's lambda
        // shapes and receivers, where the constructor path below would not.
        if (ctor_cid != null and b.ownerClass() != null and b.resolve("this") != null and
            b.hasOwnMember(ctor_seg.name) and b.ownFunctionApplicable(ctor_seg.name, args.len) and
            !ownMemberRejectsLambdas(b, ctor_seg.name, args))
        {
            if (try lowerImplicitThisCall(b, callee, args, ast_arg_names, call.type_args)) |r| return r;
        }
        if (ctor_cid) |class_id| {
            applyExpectedLiteralKindsToCtorArgs(b, class_id, args, ast_arg_names);
            const ctor_arity = try ctorArgFnArities(b, class_id, args, ast_arg_names);
            defer if (ctor_arity) |ca| b.allocator.free(ca);
            // P12's shape-repair contract for constructor calls: the compose
            // pass shapes a sink lambda with the bare composer pair and the
            // LOWERING repairs it against the resolved parameter's declared
            // arity. Function calls repair in transformSelectedComposableArgs;
            // a class whose primary constructor takes a composable lambda
            // (`MovableContent({ content() })`, arity 1) needs the same
            // repair here, or the content invokes with every slot shifted.
            try transformCtorComposableArgs(b, class_id, args, ast_arg_names);
            const cls = &b.module.classes.items[class_id.int()];
            // A fun-interface conversion types its lambda's params from the
            // interface's single abstract method, instantiated by the
            // explicit type args or the EXPECTED type (`val C:
            // Comparator<String> get() = Comparator { a, b -> ... }` binds
            // T := String, so `a` dispatches statically).
            var sam_lpt: ?[]?[]ir.TypeRef = null;
            defer if (sam_lpt) |types| deinitArgLambdaParamTypes(b.allocator, types);
            if (cls.is_fun_interface and args.len == 1 and args[0] == .Lambda and
                cls.type_params.len != 0)
            {
                sam_lpt = try samLambdaParamTypes(b, class_id, call.type_args);
            }
            if (runtime.envOnce("KLIO_SAM_TRACE") != null and cls.is_fun_interface) {
                std.debug.print("[sam] {s} tps={d} lam={} lpt={} exp={}\n", .{ cls.name, cls.type_params.len, args.len == 1 and args[0] == .Lambda, sam_lpt != null, b.peekExpected() != null });
            }
            // A ctor's CONCRETE fn-typed params type their lambda arguments
            // (`IntArray(256) { it shr 4 }` types `it` Int).
            if (sam_lpt == null) sam_lpt = try ctorLambdaParamTypes(b, class_id, args);
            b.pending_arg_lambda_param_types = sam_lpt;
            const run = try lowerArgRunFull(b, args, ctor_arity, null);
            b.pending_arg_lambda_param_types = null;
            const realigned = try ctorRealignedArgNames(b, class_id, args, ast_arg_names);
            defer if (realigned) |r| b.allocator.free(r);
            const arg_names = try internArgNames(b.allocator, b.module, realigned orelse ast_arg_names);
            const dst = b.allocReg();
            const static_sam = cls.is_fun_interface and args.len == 1 and !anyNamedArg(ast_arg_names);
            if (shadowed_by_class or force_static_class or static_sam) {
                // A bare `Inner()` uses the enclosing `this` as the new
                // instance's outer. Inside a lambda body that `this` is
                // only reachable through the closure's capture set, so
                // record the capture (kotlinc does the same: the inner
                // ctor's outer argument forces a `this$0` capture).
                if (class_id.int() < b.module.classes.items.len and
                    b.module.classes.items[class_id.int()].is_inner and
                    b.resolve("this") == null and b.capturesThisSlot())
                {
                    _ = try b.recordCapture("this");
                }
                orEmitAudit(b, if (static_sam) "fun_interface_sam" else "bare_ctor_shadowed_by_class", "NewInstance", callee.Path.segments[0].name);
                try b.push(.{ .NewInstance = .{
                    .dst = dst,
                    .class = class_id,
                    .args = run[0],
                    .n_args = run[1],
                    .arg_names = arg_names,
                    .arg_static_heads = try ctorArgStaticHeads(b, args),
                } });
            } else {
                const this_idx = try b.recordCapture("this");
                const nmc = try b.module.internConst(b.allocator, .{ .String = callee.Path.segments[0].name });
                orEmitAudit(b, "class_or_factory_call", "CallMemberOrGlobal", callee.Path.segments[0].name);
                try b.push(.{ .CallMemberOrGlobal = .{
                    .dst = dst,
                    .this_idx = this_idx,
                    .name = nmc,
                    .args = run[0],
                    .n_args = run[1],
                    .arg_names = arg_names,
                    .class = class_id,
                    .candidates = try cmgCandidates(b, callee.Path.segments[0].name, callee.Path.segments[0].span.file, run[1]),
                    .static_recv = try cmgStaticRecv(b),
                } });
            }
            return dst;
        }
    }

    // Inside a method/extension body: unqualified `name(...)` that didn't
    // match a local / top-level fn / class is a method call on `this`.
    if (callee.* == .Path) {
        if (try lowerImplicitThisCall(
            b,
            callee,
            args,
            ast_arg_names,
            ast_type_args,
        )) |r| return r;
    }

    // Unresolved bare-name call. Reaching here means the resolver above
    // declined to commit a target, so in a receiver context the call must
    // still dispatch member-first even when a same-named top-level function
    // exists in the index (a bare `close(permission)` inside a NodeList
    // member-extension reaches the receiver's inherited member, not a
    // same-named extension elsewhere); a bare-name value load would miss
    // receiver METHODS entirely. Outside a receiver context an indexed name
    // keeps the value-call fallback, which binds the resolved global.
    if (callee.* == .Path and callee.Path.segments.len == 1 and
        b.resolve(callee.Path.segments[0].name) == null and
        !b.knowsOuter(callee.Path.segments[0].name) and
        b.module.classId(callee.Path.segments[0].name) == null and
        // A collision-mangled class reached only through an explicit import
        // (`import a.Widget` with a same-named `b.Widget`) is registered under
        // its mangled name, so `classId` misses — but it is a real class ctor,
        // not an unresolved bare call.
        b.module.classIdExactImport(callee.Path.segments[0].name, callee.Path.segments[0].span.file) == null and
        (b.module.funcId(callee.Path.segments[0].name) == null or inReceiverContext(b)))
    {
        if (try lowerUnresolvedBareCall(b, callee, args, ast_arg_names, ast_type_args, null)) |r| return r;
    }

    // Built-in stdlib companion shortcuts: `Result.success(x)` etc.
    if (try lowerCompanionShortcut(b, callee, args, ast_arg_names)) |r| return r;

    // Package-qualified constructor call (`app.sub.Widget()`): the dotted
    // callee names a class, so construct it — before the function-FQN and
    // member-fallback paths, which would otherwise read the package head as a
    // field of the implicit receiver (`get_field app on this`).
    // A multi-segment Path callee is the same dotted-FQN shape (the compose
    // pass synthesizes `androidx.compose.runtime.remember(...)` that way);
    // routing it here gives the qualified call the same overload-precise
    // binding the parsed Member form gets, instead of a first-registered
    // global value call.
    const dotted_callee = callee.* == .Member or
        (callee.* == .Path and callee.Path.segments.len >= 2);
    if (callee.* == .Member) {
        if (try lowerFqnCtorCall(b, expr)) |r| return r;
    }
    // Package-qualified call to a user / pack top-level function.
    if (dotted_callee) {
        if (try lowerFqnFlattenCall(b, callee, args, ast_arg_names, ast_type_args)) |r| return r;
    }
    // Fully-qualified callee resolved as a global, CallValue.
    if (dotted_callee) {
        if (try lowerFqnGlobalCall(b, callee, args, ast_arg_names)) |r| return r;
    }

    // The catch-all member / value call.
    if (callee.* == .Member) {
        return lowerMemberCallFallback(b, expr);
    }
    // A bare single-name call that no earlier path resolved, but whose name
    // could be a member of an implicit receiver (a lambda's captured outer
    // `this`), must dispatch member-first — not fall to a bare-name value load
    // that binds a same-named top-level global. Otherwise `error(msg)` inside a
    // `runCatching { }` binds `kotlin.error` instead of the enclosing class's
    // own `error`.
    if (callee.* == .Path and callee.Path.segments.len == 1) {
        const nm0 = callee.Path.segments[0].name;
        // Only reroute a name that is ACTUALLY an own/enclosing member — not
        // merely "an unknown receiver could have it" — so a top-level helper
        // (`testEquals`) called in a lambda is left on the global path.
        if (b.resolve(nm0) == null and inReceiverContext(b) and b.hasEnclosingMember(nm0)) {
            // A captured local fn is a candidate the runtime member walk
            // cannot see: emit the runtime-arbitrated form. Its value arm
            // falls to the enclosing member when the closure's declared
            // params refute the args (`testEncode(codec, bytes, symbols)`
            // binds the local on String args, the private member on
            // ByteArray).
            if (b.knowsOuter(nm0) and call.type_args.len == 0) {
                if (try resolveThisForBareCallNoBind(b)) |this_reg| {
                    const cv = try resolveCapture(b, nm0);
                    const run0 = try lowerArgRun(b, args);
                    const an0 = try internArgNames(b.allocator, b.module, ast_arg_names);
                    const nmc = try b.module.internConst(b.allocator, .{ .String = nm0 });
                    const d0 = b.allocReg();
                    orEmitAudit(b, "cvom_bare_capture", "CallValueOrMember", nm0);
                    try b.push(.{ .CallValueOrMember = .{
                        .dst = d0,
                        .callee = cv,
                        .this_recv = this_reg,
                        .name = nmc,
                        .args = run0[0],
                        .n_args = run0[1],
                        .arg_names = an0,
                    } });
                    return d0;
                }
            }
            if (try lowerUnresolvedBareCall(b, callee, args, ast_arg_names, ast_type_args, null)) |r| return r;
        }
    }
    // A bare call whose name is a bound local / captured outer does not
    // shadow an implicit receiver's member unless the local is actually
    // invokable: `subList = subList(0, 4)` inside `buildList { }` calls
    // the receiver's subList; the captured non-callable `val subList` is
    // not a candidate. Emit the runtime-arbitrated form (value when
    // callable, else the member on `this`) — the same arbitration
    // `redirect_to_member` applies inside a method body.
    if (callee.* == .Path and callee.Path.segments.len == 1 and call.type_args.len == 0) {
        const nm0 = callee.Path.segments[0].name;
        // A RECEIVER-lambda param is Kotlin-unambiguous (the param wins and
        // its receiver binds by declared type): let the ladder reach the
        // RLP arms, which carry the declared head — this arbitration arm
        // seated the syntactic `this` (flowScope's coroutine) and
        // combineInternal's `transform(...)` lost its FlowCollector.
        if (!b.isLocalFn(nm0) and !b.isLocalExtFn(nm0) and
            !b.isReceiverLambdaParam(nm0) and
            (b.knowsOuter(nm0) or b.resolve(nm0) != null))
        {
            if (try resolveThisForBareCallNoBind(b)) |this_reg| {
                const cv = try lowerExpr(b, callee);
                const run0 = try lowerArgRun(b, args);
                const an0 = try internArgNames(b.allocator, b.module, ast_arg_names);
                const nmc = try b.module.internConst(b.allocator, .{ .String = nm0 });
                const d0 = b.allocReg();
                orEmitAudit(b, "cvom_bare_local", "CallValueOrMember", nm0);
                try b.push(.{ .CallValueOrMember = .{
                    .dst = d0,
                    .callee = cv,
                    .this_recv = this_reg,
                    .name = nmc,
                    .args = run0[0],
                    .n_args = run0[1],
                    .arg_names = an0,
                } });
                return d0;
            }
        }
    }
    // A RECEIVER-function-typed property invoked bare (`block!!()` where
    // `block: Scope.() -> R` and an implicit receiver is in scope — the
    // cached-draw block invoked directly inside `scope.apply { … }`): the
    // innermost implicit receiver rides the call, exactly as Kotlin binds
    // it. Without this the closure body ran receiverless and its bare
    // member calls fell to globals.
    recv_fn: {
        var core = callee;
        var hops: usize = 0;
        while (hops < 8) : (hops += 1) {
            switch (core.*) {
                .Unary => |u| core = u.expr,
                .Postfix => |pf| core = pf.expr,
                else => break,
            }
        }
        if (core.* != .Path or core.Path.segments.len != 1) break :recv_fn;
        const pname = core.Path.segments[0].name;
        if (b.resolve(pname) != null or b.knowsOuter(pname)) break :recv_fn;
        const this_reg = b.resolve("this") orelse break :recv_fn;
        var owner: ?[]const u8 = b.ownerClass();
        var ohops: usize = 0;
        const is_recv_fn = blk: {
            while (owner) |o| : (ohops += 1) {
                if (ohops > 32) break;
                if (b.module.registry.recv_fn_props.get(.{ .a = o, .b = pname }) != null) break :blk true;
                owner = b.module.registry.enclosing_class.get(o);
            }
            break :blk false;
        };
        if (!is_recv_fn) break :recv_fn;
        const callee_r = try lowerExpr(b, callee);
        const run = try lowerArgRun(b, args);
        const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
        const dst = b.allocReg();
        try b.push(.{ .CallValueWithThis = .{
            .dst = dst,
            .callee = callee_r,
            .receiver = this_reg,
            .args = run[0],
            .n_args = run[1],
            .arg_names = arg_names,
        } });
        return dst;
    }
    const callee_r = try lowerExpr(b, callee);
    const run = try lowerArgRun(b, args);
    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
    // Carry explicit call-site type arguments so an intrinsic container
    // creator (`listOf<Byte>(…)`) stamps and coerces its element type.
    const type_args = try helpers.internTypeArgsScoped(b, call.type_args);
    const dst = b.allocReg();
    try b.push(.{ .CallValue = .{
        .dst = dst,
        .callee = callee_r,
        .args = run[0],
        .n_args = run[1],
        .arg_names = arg_names,
        .type_args = type_args,
    } });
    return dst;
}

/// True when a bodied same-name function already accepts this call's arity.
fn aFuncFits(b: *FuncBuilder, nm: []const u8, want: usize) bool {
    for (b.module.funcsBySimpleName(nm)) |fid| {
        const mf = b.module.funcById(fid) orelse continue;
        if (!mf.hasBody()) continue;
        const has_this = mf.params.len != 0 and std.mem.eql(u8, mf.params[0].name, "this");
        const base: usize = if (has_this) 1 else 0;
        const user = mf.params.len - base;
        if (user == want) return true;
        if (want < user) {
            var all_optional = true;
            for (mf.params[base + want ..]) |p| {
                if (p.default == null and !p.is_vararg) {
                    all_optional = false;
                    break;
                }
            }
            if (all_optional) return true;
        }
        if (want > user and mf.params.len != 0 and mf.params[mf.params.len - 1].is_vararg) return true;
    }
    return false;
}

/// The receiver type a bare extension call inside this builder's body
/// narrows against — the enclosing extension's declared receiver, or
/// inside a class method (no extension receiver) the enclosing class
/// itself, since `this` is the implicit receiver Kotlin resolves the
/// call's extension on — followed by its transitive supertype names,
/// most-derived first. Null when no receiver is in scope.
/// Whether any bare-call candidate for `nm` visible from `file` is a
/// member EXTENSION declared in (a supertype of) `chain_head`'s class.
fn mextCandidateOwnedBy(b: *FuncBuilder, nm: []const u8, chain_head: []const u8, file: ir.FileId) Allocator.Error!bool {
    const head = stripLowerFileMangle(typeHead(std.mem.trimEnd(u8, chain_head, "?")));
    if (head.len == 0) return false;
    const cands = try b.module.bareCallCandidates(b.allocator, nm, file);
    defer b.allocator.free(cands);
    for (cands) |fid| {
        const owner_fqn = b.module.registry.member_ext_owner_class.get(fid) orelse continue;
        const owner_simple = stripLowerFileMangle(simpleTail(owner_fqn));
        if (std.mem.eql(u8, owner_simple, head)) return true;
        if (b.module.classIsOrExtends(head, owner_simple)) return true;
    }
    return false;
}

fn narrowingRecvChain(b: *FuncBuilder) Allocator.Error!?[]const []const u8 {
    const cur = b.recvTy() orelse b.ownerClass() orelse return null;
    return try recvChainOf(b, cur);
}

/// Receiver evidence for a bare call inside an inline body. The inline
/// extension's receiver is the active lexical receiver while its own body is
/// lowered. A spliced lambda argument restores the caller's receiver tower.
fn inlineBodyRecvHead(b: *const FuncBuilder) ?[]const u8 {
    if (b.lambda_splice_resolve == null) {
        if (b.spliceRecvTy()) |receiver| return receiver;
    } else if (inline_call.rfsEnabled() and b.splice_recv_from_window) {
        // A spliced receiver LAMBDA's window carries its subject's head
        // (`polymorphic { subclass(ints) }` lowers under
        // PolymorphicModuleBuilder, not the outer serializers-module
        // builder): without it the reified `subclass` splice declined on
        // recv_mismatch and fell to a dynamic call that cannot carry `T`.
        // Only the WINDOW-set head qualifies — a stale enclosing-EXT
        // receiver keeps the hygiene contract (the test pinning
        // MeasurePolicy over List).
        if (b.spliceRecvTy()) |receiver| return receiver;
    }
    return b.recvTy() orelse b.ownerClass();
}

fn inlineBodyRecvChain(b: *FuncBuilder) Allocator.Error!?[]const []const u8 {
    const receiver = inlineBodyRecvHead(b) orelse return null;
    return try recvChainOf(b, receiver);
}

/// `cur` followed by its transitive supertype simple names (nearest
/// first), from the hierarchy recorded at build time. A type with no
/// recorded hierarchy (a built-in, a generic parameter) yields just
/// itself.
pub fn recvChainOf(b: *FuncBuilder, cur: []const u8) Allocator.Error![]const []const u8 {
    const supers: []const []const u8 =
        b.module.registry.class_super_names.get(cur) orelse &.{};
    const chain = try b.allocator.alloc([]const u8, supers.len + 1);
    chain[0] = cur;
    @memcpy(chain[1..], supers);
    return chain;
}

/// The inline-fn declaration a bare call may splice, resolved through
/// the symbol index FIRST: a unique top-level winner decides — an
/// inline winner splices its registered AST, a non-inline winner
/// suppresses the splice so the normal call path binds it. The
/// shape/receiver narrowing over the simple-name candidate table
/// survives only as the tie-break for the shapes the index defers on
/// (extension forms, overload sets, default/vararg/trailing-lambda
/// shapes, and bodies lowered before the phase-1 headers exist — class
/// method bodies). Default-import-owned names never splice. The
/// KLIO_RESOLVE_AUDIT `inline` records compare this pick against the
/// simple-name narrowing's per call, a permanent regression detector
/// for the fold (zero unexplained divergences over the corpus).
/// Whether inline member fn `f` is declared on the enclosing class or one of
/// its transitive supertypes — i.e. reachable as `this.<f>` from a member body.
fn inlineOwnerInEnclosingHierarchy(b: *FuncBuilder, enclosing: []const u8, f: *const ast.Function) bool {
    const owner = inline_state.inlineMemberOwner(f) orelse return false;
    return classIsOrExtendsHosted(b, enclosing, owner);
}

/// Whether a member-inline candidate's owner class is on the qualified
/// call receiver's static type chain. An unknown receiver type keeps the
/// candidate (the shape-based pick's historical behavior); a KNOWN
/// receiver whose hierarchy does not include the owner rejects it —
/// `resp.body<User>()` on an `HttpResponse` must not splice the
/// unrelated `HttpStatement.body`.
/// Strict form for the monomorphic member-inline splice: an UNPROVABLE
/// receiver type rejects instead of passing — `xs.fold(init) { }` on a
/// List must never splice SnapshotIdSet's same-named member body.
fn memberOwnerOnReceiverChainStrict(b: *FuncBuilder, receiver: *const Expr, cf: *const ast.Function) Allocator.Error!bool {
    const owner = inline_state.inlineMemberOwner(cf) orelse return false;
    const head = (try inline_call.inferReceiverType(b, receiver)) orelse return false;
    return classIsOrExtendsHosted(b, head, owner);
}

fn memberOwnerOnReceiverChain(b: *FuncBuilder, receiver: *const Expr, cf: *const ast.Function) Allocator.Error!bool {
    const owner = inline_state.inlineMemberOwner(cf) orelse return true;
    const head = (try inline_call.inferReceiverType(b, receiver)) orelse return true;
    return classIsOrExtendsHosted(b, head, owner);
}

/// `classIsOrExtends` that also accepts `$Companion`-mangled names on
/// either side by reducing them to their host class: a bare call inside
/// `ContentType.Companion` is in scope of `HeaderValueWithParameters`'s
/// companion members exactly when `ContentType` extends it.
pub fn classIsOrExtendsHosted(b: *FuncBuilder, sub: []const u8, super: []const u8) bool {
    if (b.module.classIsOrExtends(sub, super)) return true;
    const sub_host = hostClassOfCompanion(sub) orelse sub;
    const super_host = hostClassOfCompanion(super) orelse super;
    if (sub_host.len == sub.len and super_host.len == super.len) return false;
    return b.module.classIsOrExtends(sub_host, super_host);
}

/// The symbol-index scope tier of an inline candidate at a reference
/// site (0 named-import … 5 invisible); unknown metadata ranks as the
/// default-import tier so it neither wins nor loses against real
/// records.
fn inlineCandTier(b: *const FuncBuilder, f: *const ast.Function, caller_file: span.FileId) u8 {
    const m = b.module;
    const decl_file = f.name.span.file;
    const decl_pkg = m.packageOfFile(decl_file) orelse return 3;
    const caller_pkg = m.packageOfFile(caller_file) orelse b.self_package;
    var buf: [256]u8 = undefined;
    const fqn = std.fmt.bufPrint(&buf, "{s}.{s}", .{ decl_pkg, f.name.name }) catch return 3;
    return m.scopeTier(fqn, decl_pkg, f.name.name, caller_pkg, caller_file);
}

/// Whether a plain top-level inline fn is visible at `caller_file` under
/// Kotlin scoping: same package, exact or wildcard import, or a
/// default-import package. Only the invisible tier (an unimported
/// foreign package) is rejected.
fn bareInlineVisibleFrom(b: *const FuncBuilder, f: *const ast.Function, caller_file: span.FileId) bool {
    return inlineCandTier(b, f, caller_file) <= 3;
}

/// Re-rank a shape-based plain-inline pick by call-site visibility: with
/// several same-name NON-extension inline candidates across packs (seven
/// `synchronized` actuals in the compose set), the registration-order
/// pick is bake-order-sensitive and can splice another pack's body.
/// Kotlin resolves by scope — prefer the lowest tier among candidates
/// that fit the call shape; ties keep the incumbent.
fn retierPlainInlinePick(
    b: *const FuncBuilder,
    pick: *const ast.Function,
    nm: []const u8,
    shape: CallShape,
    caller_file: span.FileId,
) *const ast.Function {
    if (pick.receiver_type != null or inline_state.inlineMemberOwner(pick) != null) return pick;
    const cands = inline_state.candidatesForName(nm) orelse return pick;
    if (cands.len < 2) return pick;
    var best = pick;
    var best_tier = inlineCandTier(b, pick, caller_file);
    for (cands) |cf| {
        if (cf == pick) continue;
        if (cf.receiver_type != null or inline_state.inlineMemberOwner(cf) != null) continue;
        if (shape.last_is_lambda) {
            if (cf.params.len == 0) continue;
            const lp = &cf.params[cf.params.len - 1];
            if (lp.ty.function == null) continue;
            if (cf.params.len != shape.want) continue;
        } else if (cf.params.len != shape.want) {
            continue;
        }
        const t = inlineCandTier(b, cf, caller_file);
        if (t < best_tier) {
            best_tier = t;
            best = cf;
        }
    }
    return best;
}

/// Whether an implicit receiver in the caller's context declares a MEMBER
/// named `nm` that can take `argc` args — bodyless
/// (`registry.abstract_member_arity`) or concrete (`member_method_fids`
/// at the exact arity), walked over the recorded supertype name chains.
/// Kotlin ranks such a member above any extension, so an inline-extension
/// splice must yield to it (`respond(message, typeInfo<T>())` inside an
/// `ApplicationCall` extension binds the interface's member, never the
/// reified 2-arg `respond(status, message)` extension).
fn receiverMemberTakesCall(b: *FuncBuilder, evid_chain: ?[]const []const u8, nm: []const u8, argc: usize) bool {
    var heads_buf: [12][]const u8 = undefined;
    var n: usize = 0;
    if (b.recvTy()) |h| {
        heads_buf[n] = h;
        n += 1;
    }
    if (b.ownerClass()) |h| {
        if (n < heads_buf.len) {
            heads_buf[n] = h;
            n += 1;
        }
    }
    if (evid_chain) |chain| for (chain) |h| {
        if (n < heads_buf.len) {
            heads_buf[n] = h;
            n += 1;
        }
    };
    const bit: u64 = @as(u64, 1) << @intCast(@min(argc, 63));
    var stack_buf: [48][]const u8 = undefined;
    var stack_len: usize = 0;
    for (heads_buf[0..n]) |h| {
        if (stack_len < stack_buf.len) {
            stack_buf[stack_len] = h;
            stack_len += 1;
        }
    }
    var seen_buf: [48][]const u8 = undefined;
    var seen_len: usize = 0;
    while (stack_len > 0) {
        stack_len -= 1;
        const cur = stack_buf[stack_len];
        var dup = false;
        for (seen_buf[0..seen_len]) |sn| {
            if (std.mem.eql(u8, sn, cur)) {
                dup = true;
                break;
            }
        }
        if (dup) continue;
        if (seen_len < seen_buf.len) {
            seen_buf[seen_len] = cur;
            seen_len += 1;
        }
        // Bodyless slots only: a CONCRETE member is already ranked by the
        // existing ladders, and vetoing every concrete-member namesake here
        // was measured too blunt (it broke `execute(context, Unit)` inside
        // the pipeline extension). The abstract record is the information
        // the ladders lack.
        if (b.module.registry.abstract_member_arity.get(.{ .a = cur, .b = nm })) |mask| {
            if (runtime.envOnce("KLIO_INLINE_PICK")) |w| {
                if (std.mem.eql(u8, w, nm)) std.debug.print("[rmtc] {s} on {s} mask={x} argc={d}\n", .{ nm, cur, mask, argc });
            }
            if (mask & bit != 0) return true;
        }
        const supers: []const []const u8 = b.module.registry.class_super_names.get(cur) orelse &.{};
        for (supers) |sup| {
            if (stack_len < stack_buf.len) {
                stack_buf[stack_len] = sup;
                stack_len += 1;
            }
        }
    }
    return false;
}

/// Whether the module declares a same-named NON-inline extension whose
/// receiver head appears in `chain`. Used to decline an inline splice that
/// picked a receiverless candidate while a receiver is in scope: the inline
/// candidate set cannot contain the extension (it is not inline), so the
/// decline has to come from outside that set.
fn nonInlineExtensionFits(b: *FuncBuilder, name: []const u8, chain: []const []const u8, file: ir.FileId) bool {
    // `import kotlinx.coroutines.flow.combine as combineOriginal` means the
    // call site's name is not the declared one; look the extension up under
    // what it is actually called. CombineTest imports exactly this way, so
    // without the unaliasing the check found nothing.
    var lookup = name;
    if (b.module.importAliasIn(file, name)) |segs| {
        if (segs.len != 0) lookup = segs[segs.len - 1];
    }
    for (b.module.funcsBySimpleName(lookup)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this")) continue;
        var rh = std.mem.trimEnd(u8, f.params[0].ty.name, "?");
        if (std.mem.indexOfScalar(u8, rh, '<')) |lt| rh = rh[0..lt];
        const rhead = typeHead(rh);
        for (chain) |c| {
            var ch = std.mem.trimEnd(u8, c, "?");
            if (std.mem.indexOfScalar(u8, ch, '<')) |lt| ch = ch[0..lt];
            if (std.mem.eql(u8, rhead, typeHead(ch))) return true;
        }
    }
    return false;
}

/// Publish a call's EXPLICIT type arguments under the callee's reified
/// type-parameter names, for a call that could not be spliced. The spliced
/// form binds these names itself; without the splice the body would read a
/// stale binding. Only reified parameters of a candidate with this name are
/// written, and each name once.
fn storeExplicitReifiedGlobals(b: *FuncBuilder, name: []const u8, type_args: []const ast.TypeRef) Allocator.Error!void {
    if (type_args.len == 0) return;
    const cands = inline_state.candidatesForName(name) orelse return;
    var written: std.ArrayList([]const u8) = .empty;
    defer written.deinit(b.allocator);
    for (cands) |cf| {
        for (cf.type_params, 0..) |tp, i| {
            if (!tp.is_reified or i >= type_args.len) continue;
            var dup = false;
            for (written.items) |w| {
                if (std.mem.eql(u8, w, tp.name.name)) dup = true;
            }
            if (dup) continue;
            const arg = &type_args[i];
            if (arg.function != null) continue;
            const resolved = scopeTypeRename(b, arg.name.name, arg.name.span.file.int()) orelse arg.name.name;
            const cls_reg = b.allocReg();
            const arg_name = try b.module.internConst(b.allocator, .{ .String = resolved });
            const cls_pick: ?ir.ClassId = b.module.classIdIndexed(resolved, b.self_package, arg.name.span.file) orelse
                b.module.classId(resolved);
            try b.push(.{ .LoadGlobal = .{ .dst = cls_reg, .name = arg_name, .class = cls_pick, .ctor_ref = true } });
            const tp_global = try b.module.internConst(b.allocator, .{ .String = tp.name.name });
            try b.push(.{ .StoreGlobal = .{ .name = tp_global, .value = cls_reg } });
            try written.append(b.allocator, tp.name.name);
        }
    }
}

/// Heads whose values a `vararg` sibling's single argument can never be.
fn containerParamHead(name: []const u8) bool {
    const heads = [_][]const u8{
        "Iterable", "Collection", "List", "MutableList", "Set", "MutableSet",
        "Sequence", "Array",
    };
    for (heads) |h| if (std.mem.eql(u8, name, h)) return true;
    return false;
}

/// The same-named inline sibling that declares the first parameter
/// `vararg`, when `picked` declares it as a CONTAINER the first argument's
/// static type is not. Null when the pick already fits.
fn varargSiblingForContainerMismatch(
    b: *FuncBuilder,
    nm: []const u8,
    picked: *const ast.Function,
    args: []const Expr,
) Allocator.Error!?*const ast.Function {
    if (args.len == 0) return null;
    if (picked.params.len == 0) return null;
    const p0 = &picked.params[0];
    if (p0.is_vararg) return null;
    if (!containerParamHead(typeHead(p0.ty.name.name))) return null;

    var arg_ty = (staticExprTypeRef(b, &args[0]) catch null) orelse return null;
    defer arg_ty.deinit(b.allocator);
    const arg_head = typeHead(std.mem.trimEnd(u8, arg_ty.name, "?"));
    if (arg_head.len == 0) return null;
    if (containerParamHead(arg_head)) return null;
    // A class that really does implement the container is no mismatch.
    if (b.module.uniqueClassIdBySimpleName(arg_head)) |acid| {
        if (b.module.uniqueClassIdBySimpleName(typeHead(p0.ty.name.name))) |pcid| {
            if (b.module.classIdIsOrExtends(acid, pcid)) return null;
        }
    }

    const cands = inline_state.candidatesForName(nm) orelse return null;
    for (cands) |c| {
        if (c == picked) continue;
        if (c.params.len != picked.params.len) continue;
        if (c.params.len == 0 or !c.params[0].is_vararg) continue;
        if (c.receiver_type != null) continue;
        return c;
    }
    return null;
}

fn inlineTargetForBareCall(
    b: *FuncBuilder,
    seg: *const ast.Ident,
    args: []const Expr,
    arg_names: []const ?[]const u8,
    shape: CallShape,
) Allocator.Error!?*const ast.Function {
    const nm = seg.name;
    // A renamed import (`import a.b.f as g`) fixes the declaration family
    // by exact FQN, but the inline candidate table is keyed by DECLARED
    // name — the aliased call must look the target up under its own name,
    // or a same-named declaration in scope preempts the aliased one.
    // kotlinx-coroutines aliases `unsafeTransform as transform` inside the
    // flow operators; the name-keyed pick spliced the public safe
    // `transform` and made every unsafe-chain flow cancellable.
    const inline_nm: []const u8 = blk: {
        if (b.module.importAliasIn(seg.span.file, nm)) |asegs| {
            if (asegs.len != 0 and !std.mem.eql(u8, asegs[asegs.len - 1], nm) and
                inline_state.candidatesForName(asegs[asegs.len - 1]) != null)
            {
                break :blk asegs[asegs.len - 1];
            }
        }
        break :blk nm;
    };
    // The active splice's declared receiver serves as evidence when the
    // caller context has none of its own (a bare reified call inside a
    // spliced extension body); it feeds only this pick, not binding.
    const evid_chain = try inlineBodyRecvChain(b);

    // Host-backed default imports suppress the simple-name candidate table,
    // but not an exact FuncId resolved by the scope-aware index below. The
    // source declaration remains the semantic target of an inline call and
    // must be available when reification, non-local return, or suspension
    // requires a splice; ordinary calls still fall through to the host binding
    // because `bareInlineNeedsSplice` rejects them.
    const narrowed = inlineFnAstForRecv(inline_nm, shape, evid_chain);
    // A receiver is in scope and the splice picked a RECEIVERLESS candidate,
    // while a same-named non-inline EXTENSION fits that receiver: the correct
    // target is not in the inline candidate set at all, so no comparison among
    // inline candidates can find it. kotlinx-coroutines declares
    // `Flow<T1>.combine(flow, transform)` as a plain `public fun` and
    // `combine(vararg flows, transform)` as `inline` + `reified`, so a bare
    // `combine(other, transform)` inside a Flow extension spliced a vararg and
    // its body iterated `flows`:
    //   Vm::call_member `iterator` on `kotlinx.coroutines.flow.SafeFlow`
    // Declining hands the call to normal dispatch, which binds the extension.
    // Gated on the extension existing, so a reified splice with no such
    // sibling still splices and keeps its type argument.
    if (runtime.envOnce("KLIO_SPLICEDECL")) |w| if (std.mem.eql(u8, w, nm)) {
        std.debug.print("[splicedecl] {s} narrowed={} recvty={?s} chain={?d} fits={}\n", .{
            nm, narrowed != null,
            if (narrowed) |p| (if (p.receiver_type) |rt| rt.name.name else null) else null,
            if (evid_chain) |c| c.len else null,
            if (evid_chain) |c| nonInlineExtensionFits(b, nm, c, seg.span.file) else false,
        });
    };
    // Whether the splice that would happen is RECEIVERLESS: either the
    // receiver-narrowed pick is one, or narrowing found nothing at all and the
    // indexed resolution below will choose among the receiverless namesakes.
    const splice_would_be_receiverless = if (narrowed) |p|
        (p.receiver_type == null and inline_state.inlineMemberOwner(p) == null)
    else blk: {
        // Narrowing found nothing, so the indexed resolution below will pick
        // among the inline candidates. Only decline when NONE of them takes a
        // receiver — otherwise the inline EXTENSION is the right target and
        // declining would strand the call (`Flow<T>.collect { … }` is an
        // inline extension, and declining it left `collect` unresolved).
        // The candidate table is keyed by the DECLARED name, so an aliased
        // call (`import … .combine as combineOriginal`) must unalias first.
        var cname = nm;
        if (b.module.importAliasIn(seg.span.file, nm)) |segs| {
            if (segs.len != 0) cname = segs[segs.len - 1];
        }
        const cands = inline_state.candidatesForName(cname) orelse break :blk false;
        for (cands) |c| {
            if (c.receiver_type != null or inline_state.inlineMemberOwner(c) != null) break :blk false;
        }
        break :blk cands.len != 0;
    };
    if (splice_would_be_receiverless) {
        if (evid_chain) |chain| {
            // Abandon the splice outright: clearing `narrowed` is not enough,
            // because the indexed resolution below re-picks the same
            // receiverless namesake and splices it anyway.
            if (nonInlineExtensionFits(b, nm, chain, seg.span.file)) return null;
        }
    }
    const ires = b.module.resolveBareCallIndexed(
        nm,
        b.self_package,
        seg.span.file,
        args.len,
        shape.last_is_lambda,
    );
    if (runtime.envOnce("KLIO_EF_TRACE")) |efw| {
        if (std.mem.eql(u8, efw, nm)) {
            const rid: i64 = switch (ires.outcome) {
                .resolved => |fid| @intCast(fid.int()),
                else => -1,
            };
            std.debug.print("[tbie] {s} outcome={s} fid={d} narrowed={} ast_by_id={}\n", .{
                nm,
                @tagName(ires.outcome),
                rid,
                narrowed != null,
                rid >= 0 and inline_state.inlineAstById(@intCast(rid)) != null,
            });
        }
    }
    var pick: ?*const ast.Function = switch (ires.outcome) {
        .resolved => |fid| blk: {
            // Receiver preference: an extension the receiver narrowing matched
            // (and that the
            // splice gate accepts) outranks the index's receiverless
            // namesake — Kotlin resolves the in-scope receiver's
            // extension over the top-level function, and the index
            // never models receivers.
            if (narrowed) |nf| {
                if (nf.receiver_type != null and bareInlineNeedsSplice(b, nm, nf, args)) {
                    break :blk nf;
                }
                // Same reasoning for a companion member reached through
                // the enclosing class's hierarchy (`ContentType.Companion
                // .parse` calling the inherited `HeaderValueWithParameters
                // .Companion.parse`): companion scope is invisible to the
                // index, and Kotlin ranks it above a top-level namesake.
                if (nf.receiver_type == null and bareInlineNeedsSplice(b, nm, nf, args)) {
                    if (inline_state.inlineMemberOwner(nf)) |nowner| {
                        if (companionOwnerInEnclosingHierarchy(b, nowner)) break :blk nf;
                    }
                }
            }
            const idx_pick = inline_state.inlineAstById(fid.int());
            // A trailing-lambda call cannot bind a candidate whose last
            // parameter is not function-typed: the lambda would land on a
            // scalar parameter (`group(metadata: LongArray, offset: Int)`
            // absorbing `group(200) { … }`). When the index resolves such a
            // namesake for a trailing-lambda call, decline the inline splice so
            // the ordinary path resolves the lambda-hosting overload (the
            // receiver extension) instead.
            if (shape.last_is_lambda) {
                if (idx_pick) |ip| {
                    if (!astLastParamHostsLambda(ip)) break :blk null;
                }
            }
            break :blk idx_pick;
        },
        // The index declined; the shape-narrowed pick stands in — but a
        // plain (receiverless) inline fn is only a legal target when its
        // declaring package is in scope at the call site. Without the
        // filter, `max(permits, 0)` under `import kotlin.math.*` splices
        // an unrelated pack's `max(a: Dp, b: Dp)`. Extension picks stay:
        // receiver narrowing, not package scope, is their discriminator.
        .deferred => blk: {
            var nf = narrowed orelse break :blk null;
            // A plain pick re-ranks by call-site scope tier: with several
            // same-name plain inline candidates across packs (`synchronized`
            // actuals), the registration-order pick is bake-order-sensitive.
            nf = retierPlainInlinePick(b, nf, nm, shape, seg.span.file);
            // Member-inline fns are exempt: their discriminator is the
            // enclosing class hierarchy (checked below), not package
            // scope — `propertyFailsWith` on an implicit CompareContext
            // receiver must splice from any file.
            if (nf.receiver_type == null and
                inline_state.inlineMemberOwner(nf) == null and
                !bareInlineVisibleFrom(b, nf, seg.span.file))
            {
                break :blk null;
            }
            break :blk nf;
        },
    };
    // Vararg-vs-container siblings: the index resolves by NAME and ARITY,
    // and `combine(vararg flows: Flow<T>, transform)` and
    // `combine(flows: Iterable<Flow<T>>, transform)` are both arity 2. A
    // single `Flow` argument only fits the vararg one — a `Flow` is not an
    // `Iterable` — but the index cannot see that, and splicing the
    // container overload made its body iterate the flow itself
    // (`Vm::call_member iterator`). Swap in the vararg sibling when the
    // argument disproves the container parameter.
    if (pick) |pf| {
        if (try varargSiblingForContainerMismatch(b, nm, pf, args)) |alt| pick = alt;
    }

    // Same-simple-name inline MEMBER overloads declared in unrelated classes:
    // a bare call inside a member binds `this.<name>`, so the overload must be
    // one declared in the enclosing class's own hierarchy — never a namesake
    // member of an unrelated class. The index resolves the bare name without a
    // receiver, so it can pick either; correct it here. (`performingMeasure` is
    // a member of both `NodeCoordinator` and the unrelated `LookaheadDelegate`;
    // inside `InnerNodeCoordinator.measure` only the `NodeCoordinator` one is in
    // scope, and the two bodies differ.)
    if (pick) |pf| {
        if (b.ownerClass()) |enclosing| {
            // The pick is an inline member of a class the enclosing class does
            // NOT belong to. A bare call inside a member binds `this.<name>`, so
            // an unrelated class's namesake is never the target.
            if (pf.receiver_type == null) {
                if (inline_state.inlineMemberOwner(pf)) |powner| {
                    if (!classIsOrExtendsHosted(b, enclosing, powner)) {
                        // Prefer a same-name inline overload declared in the
                        // enclosing class's own hierarchy, if one exists.
                        var replaced = false;
                        if (inline_state.candidatesForName(nm)) |cands| {
                            if (cands.len >= 2) {
                                for (cands) |cf| {
                                    if (cf == pf or cf.receiver_type != null) continue;
                                    if (inlineOwnerInEnclosingHierarchy(b, enclosing, cf)) {
                                        pick = cf;
                                        replaced = true;
                                        break;
                                    }
                                }
                            }
                        }
                        // Otherwise, if the enclosing class declares its own
                        // member of this name, decline the splice so the normal
                        // member-call path binds it — a class's own `head`
                        // (even non-inline) wins over an unrelated class's
                        // inline `head`, whose body would run on the wrong `this`.
                        // Only an APPLICABLE own member outranks the pick:
                        // JsonTestBase's `encodeToString(value, mode)` must
                        // not send a one-argument `encodeToString(tree)` to
                        // the dynamic path (where the reified `T` of Json's
                        // member reads a stale binding).
                        if (!replaced and b.hasEnclosingMember(nm) and
                            enclosingMemberTakes(b, nm, args.len) and !ownMemberRejectsLambdas(b, nm, args))
                        {
                            if (runtime.envOnce("KLIO_INLINE_PICK")) |w| { if (std.mem.eql(u8, w, nm)) std.debug.print("[ipick-why] {s} decline at L229\n", .{nm}); }
                            return null;
                        }
                    }
                }
            }
        } else if (pf.receiver_type == null) {
            // No enclosing class at all (a top-level extension body): a
            // member-inline pick can only be in scope through an implicit
            // receiver, and the receiver chain is known here. When the
            // pick's owner is not on the chain, prefer the same-name
            // EXTENSION overload whose declared receiver IS — inside
            // `List<T>.fastFirstOrNull`, bare `fastForEach { }` must
            // splice `List.fastForEach`, never `SlotIdsSet`'s member
            // (whose body reads the wrong class's `set` field).
            if (inline_state.inlineMemberOwner(pf)) |powner| {
                const chain: ?[]const []const u8 = try narrowingRecvChain(b);
                if (chain) |ch| {
                    var owner_on_chain = false;
                    for (ch) |cn| {
                        if (std.mem.eql(u8, cn, powner)) {
                            owner_on_chain = true;
                            break;
                        }
                    }
                    if (!owner_on_chain) {
                        if (inline_state.candidatesForName(nm)) |cands| {
                            for (cands) |cf| {
                                if (cf == pf) continue;
                                const rt = cf.receiver_type orelse continue;
                                for (ch) |cn| {
                                    if (std.mem.eql(u8, cn, rt.name.name)) {
                                        pick = cf;
                                        break;
                                    }
                                }
                                if (pick != pf) break;
                            }
                        }
                    }
                }
            }
        }
    }
    // An inline overload whose last parameter is a function type does not
    // apply when its matching argument is an object instance — e.g. a
    // `FlowCollector` passed to `Flow.collect`, where the real target is the
    // member `collect(collector)`, not the inline `collect(action: (T) -> Unit)`
    // extension. Splicing it would bind the object to the function parameter and
    // invoke it as `obj.invoke(...)`. Decline the splice so the member wins.
    if (pick) |pf| {
        const inline_takes_fn = pf.params.len != 0 and pf.params[pf.params.len - 1].ty.function != null;
        if (inline_takes_fn and lastArgIsObjectNotFunction(b, args) and
            b.resolve(nm) == null and b.hasOwnMember(nm))
        {
            if (runtime.envOnce("KLIO_INLINE_PICK")) |w| { if (std.mem.eql(u8, w, nm)) std.debug.print("[ipick-why] {s} decline at L282\n", .{nm}); }
            return null;
        }
    }
    // Argument type evidence corrects a shape-picked sibling: the splice
    // selectors above rank by NAME + arity + receiver only, so two inline
    // overloads that differ in a parameter's TYPE tie and the first
    // registered one wins — `visitAncestors(mask: Int, ...)` binding a
    // `NodeKind` argument whose real target is the `(type: NodeKind<T>, ...)`
    // sibling. When the declared/derived head of an argument DISPROVES the
    // pick's parameter (a user-class head against a primitive parameter, or
    // two distinct known classes), re-pick the sibling the evidence fits.
    if (pick) |pf| {
        if (inlineEvidenceRejects(b, pf, args, arg_names)) {
            var better: ?*const ast.Function = null;
            if (inline_state.candidatesForName(nm)) |cands| {
                for (cands) |cf| {
                    if (cf == pf) continue;
                    if ((cf.receiver_type == null) != (pf.receiver_type == null)) continue;
                    if (!inlineShapeFits(cf, args, shape)) continue;
                    if (inlineEvidenceRejects(b, cf, args, arg_names)) continue;
                    better = cf;
                    break;
                }
            }
            // No sibling fits either: decline the splice entirely so the
            // dynamic call path resolves on runtime values.
            if (runtime.envOnce("KLIO_INLINE_PICK")) |w| {
                if (std.mem.eql(u8, w, nm)) std.debug.print("[ipick-why] {s} evidence re-pick better={}\n", .{ nm, better != null });
            }
            pick = better;
        }
    }
    // The enclosing class's OWN applicable member outranks an inline
    // EXTENSION whose declared receiver is not evidenced by the receiver
    // chain: a bare `withCurrent { }` inside SnapshotStateMap (which
    // declares a private inline member `withCurrent`) must bind the
    // member, never splice the unrelated `T : StateRecord`.withCurrent
    // extension onto the map. An extension whose receiver IS on the
    // chain keeps the splice — the innermost receiver's extension is
    // Kotlin's pick there.
    if (pick) |pf| {
        if (runtime.envOnce("KLIO_INLINE_PICK")) |w| {
            if (std.mem.eql(u8, w, nm)) std.debug.print("[ipick-tail] {s} recv={s} hasOwn={} applicable={}\n", .{ nm, if (pf.receiver_type) |rt| rt.name.name else "-", b.hasOwnMember(nm), b.ownMemberApplicable(nm, args.len) });
        }
        if (pf.receiver_type != null and b.hasOwnMember(nm) and
            enclosingMemberTakes(b, nm, args.len) and !ownMemberRejectsLambdas(b, nm, args))
        {
            const rt_name = pf.receiver_type.?.name.name;
            var evidenced = false;
            if (try inlineBodyRecvChain(b)) |ch| {
                for (ch) |cn| {
                    if (std.mem.eql(u8, cn, rt_name)) {
                        evidenced = true;
                        break;
                    }
                }
            }
            if (!evidenced) return null;
        }
    }
    // An ABSTRACT member on the implicit-receiver tower that can take this
    // call outranks an EXTENSION / top-level inline candidate in Kotlin's
    // resolution order (`respond(message, typeInfo<T>())` inside an
    // `ApplicationCall` extension binds the interface's bodyless member,
    // never the reified 2-arg `respond(status, message)` extension).
    // Member-inline picks are exempt: they are themselves tower members
    // (DebugPipelineContext's own `proceed` must keep splicing over the
    // base class's abstract slot).
    if (pick) |pf| {
        if (inline_state.inlineMemberOwner(pf) == null and
            receiverMemberTakesCall(b, evid_chain, nm, args.len))
        {
            if (runtime.envOnce("KLIO_ABSVETO_TRACE") != null)
                std.debug.print("[absveto] {s} argc={d} in={s}\n", .{ nm, args.len, build.currentRealFn() orelse "-" });
            if (runtime.envOnce("KLIO_INLINE_PICK")) |w| { if (std.mem.eql(u8, w, nm)) std.debug.print("[ipick-why] {s} decline at L353\n", .{nm}); }
            return null;
        }
    }
    inlineResolveAudit(b, nm, seg.span.file, narrowed, pick, args, shape.last_is_lambda, ires);
    return pick;
}

/// Whether argument type evidence definitely excludes inline candidate `f`
/// for this call: a positional argument whose evidence head is a known user
/// class bound to a builtin-kind parameter (`NodeKind` -> `Int`), or two
/// distinct known class heads with no shared name. Conservative — unknown
/// evidence or parameter kinds never reject.
fn inlineEvidenceRejects(b: *FuncBuilder, f: *const ast.Function, args: []const Expr, arg_names: []const ?[]const u8) bool {
    const positional_n = if (args.len > 0 and switch (args[args.len - 1]) {
        .Lambda, .AnonFun => true,
        else => false,
    }) args.len - 1 else args.len;
    for (args[0..positional_n], 0..) |*a, i| {
        // A NAMED argument fills its declared parameter, not the slot at its
        // call-site position: comparing it against `params[i]` disproves the
        // candidate on a parameter it never binds (`element<T>(name,
        // isOptional = true)` judged the Boolean against the skipped
        // `annotations: List<Annotation>`), which declined the splice and
        // left the reified parameter unbound.
        const pi: usize = blk: {
            const nm = if (i < arg_names.len) arg_names[i] else null;
            const n = nm orelse break :blk i;
            for (f.params, 0..) |p, pj| {
                if (std.mem.eql(u8, p.name.name, n)) break :blk pj;
            }
            continue;
        };
        if (pi >= f.params.len) break;
        const ev = argDeclTypeRef(b, a) orelse continue;
        const ehead = std.mem.trimEnd(u8, ev.name, "?");
        const pname = f.params[pi].ty.name.name;
        const phead = std.mem.trimEnd(u8, pname, "?");
        if (std.mem.eql(u8, ehead, phead)) continue;
        // A top-type parameter accepts every argument; evidence can never
        // disprove it (`classify(x: Any, block: (T) -> String)` called
        // with an Int must keep the reified splice).
        if (std.mem.eql(u8, phead, "Any")) continue;
        const e_builtin = paramLitKind(ehead);
        const p_builtin = paramLitKind(phead);
        // A known user class where a builtin kind is required (or vice
        // versa) is a definite mismatch.
        if (p_builtin != null and e_builtin == null and b.module.classId(ehead) != null) return true;
        if (p_builtin == null and e_builtin != null and b.module.classId(phead) != null and
            !classHasBoundedTypeParam(b, phead) and
            !typeNameIsParam(f, phead)) return true;
    }
    // A trailing lambda binds the LAST parameter; a builtin-typed one
    // (`cast(value, serialName, tag: String)`) can never take it, so the
    // same-named overload whose last parameter is a function type is the
    // target (`cast(value, serialName, path: () -> String)`).
    if (positional_n + 1 == args.len and f.params.len > positional_n) {
        const lp = &f.params[f.params.len - 1].ty;
        if (lp.function == null and paramLitKind(std.mem.trimEnd(u8, lp.name.name, "?")) != null) return true;
    }
    return false;
}

/// Whether the class named `phead` declares a type parameter with a real
/// (non-`Any`) upper bound. The registry records every class type param
/// (unbounded ones under an `Any` bound), so presence alone is not the
/// signal this evidence check keys on.
fn classHasBoundedTypeParam(b: *FuncBuilder, phead: []const u8) bool {
    const key = if (std.mem.indexOfScalar(u8, phead, '.') != null)
        phead
    else if (b.module.uniqueClassIdBySimpleName(phead)) |id|
        b.module.classes.items[id.int()].fqn
    else
        return false;
    const bounds = b.module.registry.class_type_param_bounds.get(key) orelse return false;
    for (bounds) |bd| {
        if (!std.mem.eql(u8, applicability.simpleName(bd.bound), "Any")) return true;
    }
    return false;
}

/// Whether `name` is one of `f`'s declared type parameters.
fn typeNameIsParam(f: *const ast.Function, name: []const u8) bool {
    for (f.type_params) |*tp| {
        if (std.mem.eql(u8, tp.name.name, name)) return true;
    }
    return false;
}

/// Shape fit for an evidence re-pick: every positional argument has a
/// parameter slot, a trailing lambda has a last parameter to bind, and every
/// unfilled parameter carries a default.
fn inlineShapeFits(f: *const ast.Function, args: []const Expr, shape: CallShape) bool {
    const has_trailing = shape.last_is_lambda;
    const positional_n = if (has_trailing and args.len > 0) args.len - 1 else args.len;
    if (f.params.len < args.len) return false;
    if (has_trailing and f.params.len == 0) return false;
    var i: usize = positional_n;
    const last = if (has_trailing) f.params.len - 1 else f.params.len;
    while (i < last) : (i += 1) {
        if (f.params[i].default == null) return false;
    }
    return true;
}

/// Whether a bare call to inline fn `f` must be spliced at the call
/// site rather than dispatched: a `suspend inline` builder (its
/// `suspendCoroutineUninterceptedOrReturn` must capture the caller's
/// continuation), a lambda argument performing a non-local return, a
/// reified type parameter, or a member shadowing the trailing-lambda
/// shape. A receiver mismatch vetoes the splice (the call belongs to a
/// different receiver's overload). The receiver judged is the
/// innermost one in scope — the enclosing extension's declared
/// receiver, or inside a class method the enclosing class itself — and
/// matching is subtype-aware: an extension declared on a base class
/// accepts a subclass receiver.
/// Whether the last argument is definitely an object instance, not a
/// function value: an `object : Foo {}` expression, or a local bound to
/// one. Such an argument cannot satisfy a function-typed parameter, so an
/// inline overload that wants a lambda there is the wrong target.
fn lastArgIsObjectNotFunction(b: *FuncBuilder, args: []const Expr) bool {
    if (args.len == 0) return false;
    switch (args[args.len - 1]) {
        .ObjectExpr => return true,
        .Path => |p| {
            if (p.segments.len != 1) return false;
            return b.isObjectInitLocal(p.segments[0].name);
        },
        else => return false,
    }
}

/// Whether any of `f`'s value parameters is a RECEIVER-formed function type
/// (`block: R.() -> T`).
/// A body cheap enough to splice into every caller: an expression body
/// or a short block, containing no try machinery (whose splice drags the
/// finally/catch lowering into each call site).
fn smallInlineBody(f: *const ast.Function) bool {
    const body = &(f.body orelse return false);
    switch (body.*) {
        .Expr => |*e| return !exprContainsTry(e),
        .Block => |*blk| {
            if (blk.stmts.len > 4) return false;
            for (blk.stmts) |*st| {
                const has_try = switch (st.*) {
                    .Expr => |*e| exprContainsTry(e),
                    .Assign => |asg| exprContainsTry(&asg.value),
                    .DestructuringDecl => |d| exprContainsTry(&d.init),
                    .Decl => |decl| switch (decl) {
                        .Property => |pr| if (pr.init) |*init| exprContainsTry(init) else false,
                        else => false,
                    },
                };
                if (has_try) return false;
            }
            return true;
        },
    }
}

fn exprContainsTry(e: *const Expr) bool {
    return switch (e.*) {
        .Try => true,
        .Lambda => |l| blk: {
            for (l.body.stmts) |*st| {
                if (st.* == .Expr and exprContainsTry(&st.Expr)) break :blk true;
            }
            break :blk false;
        },
        .Call => |c| blk: {
            if (exprContainsTry(c.callee)) break :blk true;
            for (c.args) |*a| {
                if (exprContainsTry(a)) break :blk true;
            }
            break :blk false;
        },
        .Member => |m| exprContainsTry(m.receiver),
        .Binary => |bi| exprContainsTry(bi.lhs) or exprContainsTry(bi.rhs),
        .Unary => |u| exprContainsTry(u.expr),
        .If => |iff| exprContainsTry(iff.cond) or exprContainsTry(iff.then_branch) or
            (if (iff.else_branch) |eb| exprContainsTry(eb) else false),
        else => false,
    };
}

fn anyReceiverFormedFnParam(f: *const ast.Function) bool {
    for (f.params) |*p| {
        if (p.ty.function) |ft| {
            if (ft.receiver != null) return true;
        }
    }
    return false;
}

fn anyCrossOrNoinlineParam(f: *const ast.Function) bool {
    for (f.params) |*p| {
        if (p.is_crossinline or p.is_noinline) return true;
    }
    return false;
}

/// Whether `f`'s body contains a `this` reference INSIDE a nested lambda /
/// anon-fun. Such a `this` may belong to a receiver-formed block invoked
/// dynamically (`withCurrent { this }`), which a member-body splice would
/// statically capture to the wrong receiver.
fn bodyLambdaBindsThis(f: *const ast.Function) bool {
    const body = &(f.body orelse return false);
    return switch (body.*) {
        .Block => |*blk| thisScanStmts(blk.stmts, false),
        .Expr => |*e| thisScan(e, false),
    };
}

fn thisScanStmts(stmts: []const ast.Stmt, in_lambda: bool) bool {
    for (stmts) |*st| {
        const hit = switch (st.*) {
            .Expr => |*e| thisScan(e, in_lambda),
            .Assign => |asg| thisScan(&asg.target, in_lambda) or thisScan(&asg.value, in_lambda),
            .DestructuringDecl => |d| thisScan(&d.init, in_lambda),
            .Decl => |decl| switch (decl) {
                .Property => |pr| if (pr.init) |*init| thisScan(init, in_lambda) else false,
                else => false,
            },
        };
        if (hit) return true;
    }
    return false;
}

fn thisScanArgs(args: []const Expr, in_lambda: bool) bool {
    for (args) |*a| {
        if (thisScan(a, in_lambda)) return true;
    }
    return false;
}

fn thisScan(e: *const Expr, in_lambda: bool) bool {
    return switch (e.*) {
        .This => in_lambda,
        .Lambda => |l| thisScanStmts(l.body.stmts, true),
        .AnonFun => true,
        .ObjectExpr => true,
        .Member => |m| thisScan(m.receiver, in_lambda),
        .Unary => |u| thisScan(u.expr, in_lambda),
        .Postfix => |po| thisScan(po.expr, in_lambda),
        .Spread => |sp| thisScan(sp.expr, in_lambda),
        .Throw => |t| thisScan(t.value, in_lambda),
        .Labeled => |l| thisScan(l.expr, in_lambda),
        .As => |a| thisScan(a.expr, in_lambda),
        .IsCheck => |c| thisScan(c.expr, in_lambda),
        .MemberRef => |r| thisScan(r.receiver, in_lambda),
        .Return => |r| if (r.value) |v| thisScan(v, in_lambda) else false,
        .Call => |c| thisScan(c.callee, in_lambda) or thisScanArgs(c.args, in_lambda),
        .Index => |i| thisScan(i.receiver, in_lambda) or thisScanArgs(i.args, in_lambda),
        .Binary => |bin| thisScan(bin.lhs, in_lambda) or thisScan(bin.rhs, in_lambda),
        .If => |i| thisScan(i.cond, in_lambda) or thisScan(i.then_branch, in_lambda) or
            (if (i.else_branch) |eb| thisScan(eb, in_lambda) else false),
        .While => |w| thisScan(w.cond, in_lambda) or thisScan(w.body, in_lambda),
        .DoWhile => |dw| (if (dw.body) |db| thisScan(db, in_lambda) else false) or thisScan(dw.cond, in_lambda),
        .For => |fl| thisScan(fl.iter, in_lambda) or thisScan(fl.body, in_lambda),
        .Block => |blk| thisScanStmts(blk.stmts, in_lambda),
        .When => |w| (if (w.subject) |sub| thisScan(sub, in_lambda) else false) or blk: {
            for (w.branches) |*br| {
                if (thisScan(&br.body, in_lambda)) break :blk true;
            }
            break :blk false;
        },
        .StringTemplate => |t| blk: {
            for (t.parts) |*p| {
                if (p.* == .Interp) {
                    if (thisScan(p.Interp, in_lambda)) break :blk true;
                }
            }
            break :blk false;
        },
        .Try => |t| blk: {
            if (thisScanStmts(t.body.stmts, in_lambda)) break :blk true;
            for (t.catches) |*c| {
                if (thisScanStmts(c.body.stmts, in_lambda)) break :blk true;
            }
            if (t.finally) |fin| {
                if (thisScanStmts(fin.stmts, in_lambda)) break :blk true;
            }
            break :blk false;
        },
        else => false,
    };
}

fn bareInlineNeedsSplice(b: *FuncBuilder, nm: []const u8, f: *const ast.Function, args: []const Expr) bool {
    return bareInlineNeedsSpliceT(b, nm, f, args, false);
}

fn bareInlineNeedsSpliceT(b: *FuncBuilder, nm: []const u8, f: *const ast.Function, args: []const Expr, has_explicit_type_args: bool) bool {
    const has_reified = anyReified(f.type_params);
    const want = args.len;
    const trailing_lambda = lastArgIsLambdaOrAnon(args);
    const inline_takes_fn = f.params.len != 0 and f.params[f.params.len - 1].ty.function != null;
    const drops_trailing_lambda = trailing_lambda and want >= 2;
    const a_func_fits = aFuncFits(b, nm, want);
    const shadowed_by_member = drops_trailing_lambda and inline_takes_fn and
        !a_func_fits and b.resolve(nm) == null and b.hasOwnMember(nm);
    const recv_mismatch = blk: {
        if (f.receiver_type) |rt| {
            const rn = rt.name.name;
            const in_extension_splice =
                b.lambda_splice_resolve == null and b.spliceRecvTy() != null;
            const owner_accepts = !in_extension_splice and
                (if (b.ownerClass()) |oc| b.module.classIsOrExtends(oc, rn) else false);
            const positive = if (inlineBodyRecvHead(b)) |cur|
                (!b.module.classIsOrExtends(cur, rn) and !owner_accepts)
            else
                false;
            const member_wins = !in_extension_splice and b.hasEnclosingMember(nm) and
                (if (b.ownerClass()) |oc| !std.mem.eql(u8, oc, rn) else false);
            break :blk positive or member_wins;
        }
        break :blk false;
    };
    // An inline member of a COMPANION object reached through the enclosing
    // class's hierarchy (`ContentType.Companion.parse` calling the inherited
    // `HeaderValueWithParameters.Companion.parse`): the splice is the only
    // route — member dispatch has no enclosing-supertype-companion walk on
    // the call side, and the bare-global fallback binds an unrelated
    // namesake (or nothing). Kotlin resolves this statically, so splice it.
    const companion_super_member = f.receiver_type == null and blk: {
        const owner = inline_state.inlineMemberOwner(f) orelse break :blk false;
        break :blk companionOwnerInEnclosingHierarchy(b, owner);
    };
    // A bare inline-EXT call inside a class MEMBER body: `this` there is
    // always an interpreted Instance, so the no-splice route's host binding
    // can only serve it by draining the whole receiver into a host value
    // per call (`indexOfFirst` inside `AbstractList.indexOf` drained the
    // list on every `contains`). The splice keeps the operation in place,
    // exactly as kotlinc inlines it. Ext-body contexts (recvTy set) keep
    // the host fast path — their values are host-repr. RECEIVER-formed
    // lambda params (`block: R.() -> T`) are excluded: a nested splice of
    // `withCurrent { this }` bound the block's `this` to the OUTER member
    // receiver (`current.modification` read off the list instead of the
    // record) — those keep the dynamic route until the nested receiver
    // rebinding is fixed.
    const rfs_on = inline_call.rfsEnabled();
    const member_body_ext = f.receiver_type != null and
        b.lambda_splice_resolve == null and b.spliceRecvTy() == null and
        b.recvTy() == null and b.ownerClass() != null and
        (rfs_on or !anyReceiverFormedFnParam(f)) and !bodyLambdaBindsThis(f) and
        !std.mem.eql(u8, runtime.envOnce("KLIO_MEMBER_EXT_SPLICE") orelse "1", "0");
    // Literal-lambda inline calls splice by default (kotlinc semantics);
    // KLIO_LLP=0 restores the framed route for bisecting. A CLASS MEMBER
    // callee is excluded: its bare member reads need the decl class's
    // `this`, which the splice does not thread.
    // Receiver-formed lambda params (`block: R.() -> T`) are excluded for
    // the same reason as member_body_ext: the nested receiver rebinding
    // is not implemented, so `with(x) { field }` would bind the block's
    // bare reads to the wrong receiver. A lambda that `return@<callee>`s
    // its own label is also excluded — a nested member-inline call inside
    // it stays framed, so the label must live on a real frame to be
    // found at unwind.
    // `crossinline`/`noinline` params embed the lambda in a result
    // closure rather than calling it in place; that capture wiring is
    // not spliced correctly yet (compareBy { it.name } handed the
    // selector the comparator's other operand), so those stay framed.
    // Exact positional fit only: `f` is the name's inline candidate, not
    // a resolved overload, so a call whose arity differs (the 4-arg
    // compareValuesBy against the 1-selector inline) must stay on the
    // dynamic path where real overload resolution runs.
    // Positional fit under Kotlin's trailing-lambda rule: the trailing
    // lambda binds the LAST param, leading args bind positionally, and
    // the gap in between must be default-filled. `f` is the name's
    // inline pick, not a type-resolved overload, so a call that does not
    // fit (the 4-arg compareValuesBy against the 1-selector inline) must
    // stay on the dynamic path where real overload resolution runs.
    const llp_arity_fits = want >= 1 and want <= f.params.len and blk: {
        for (f.params) |*p| {
            if (p.is_vararg) break :blk false;
        }
        var pi: usize = 0;
        while (pi + 1 < want) : (pi += 1) {
            // A lambda literal must land on a function-typed param —
            // compareValuesBy(a, b, sel, sel) arity-matches the
            // (a, b, Comparator, selector) inline overload, but its
            // third lambda lands on the Comparator slot.
            const arg_is_lambda = args[pi] == .Lambda or args[pi] == .AnonFun;
            if (arg_is_lambda and f.params[pi].ty.function == null) break :blk false;
        }
        var gi: usize = want - 1;
        while (gi + 1 < f.params.len) : (gi += 1) {
            if (f.params[gi].default == null) break :blk false;
        }
        // Several same-shape inline candidates (sumOf's per-numeric
        // selectors, Grouping.fold's two-fn-param variant) tie on shape
        // alone — stay dynamic. Receiver-ness separates plain `run`
        // from `T.run`.
        if (inline_state.candidatesForName(nm)) |cands| {
            var fitting: usize = 0;
            for (cands) |cf| {
                if (cf.params.len != f.params.len) continue;
                if ((cf.receiver_type == null) != (f.receiver_type == null)) continue;
                // Only same-package candidates form a genuine overload
                // set (kotlin.synchronized vs the compose platform
                // namesake are separated by scope, not types).
                if (cf != f and cf.name.span.file.int() != f.name.span.file.int()) {
                    const cf_pkg = b.module.packageOfFile(cf.name.span.file) orelse "";
                    const f_pkg = b.module.packageOfFile(f.name.span.file) orelse "";
                    if (!std.mem.eql(u8, cf_pkg, f_pkg)) continue;
                }
                fitting += 1;
            }
            if (fitting > 1) break :blk false;
        }
        break :blk true;
    };
    // A same-named member or in-scope binding can win by Kotlin's scope
    // ranking (a class property `run: CallableHolder.((Int) -> Unit) ->
    // Unit` invoked as `run { total += it }` outranks kotlin.run) — the
    // dynamic path resolves those; the splice must not preempt them.
    const llp_unshadowed = !b.hasOwnMember(nm) and !b.hasEnclosingMember(nm) and
        b.resolve(nm) == null and !b.knowsOuter(nm);
    // A MEMBER-inline callee taking a lambda (`drain { ... }` inside
    // Operations' own methods) splices when the call sits in the OWNER's
    // hierarchy — the member-splice window threads `this` and the owner
    // scope, exactly as the no-lambda tier relies on. Outside the owner
    // the dynamic path keeps its member ranking. The shadowing test
    // differs from the top-level tier: the callee IS an own member.
    const member_inline_lambda = inline_takes_fn and trailing_lambda and
        llp_arity_fits and rfs_on and
        b.resolve(nm) == null and
        !anyCrossOrNoinlineParam(f) and
        !inline_call.argLambdaTargetsLabel(args, nm) and
        // COST gate, not a semantics gate: a plain member-inline is
        // semantically identical framed or spliced (reified/non-local
        // returns have their own mandatory tiers), and splicing a LARGE
        // body into every hot caller inflates frames past the no-fill
        // mask — the map path lost a third of its throughput to
        // per-activation fill/alloc when `edit`'s try machinery spliced
        // everywhere. Small try-free bodies (`drain`, `forEach`,
        // `peekOperation`) splice; the rest stay framed.
        smallInlineBody(f) and blk: {
        const owner = inline_state.inlineMemberOwner(f) orelse break :blk false;
        const enc = b.ownerClass() orelse break :blk false;
        const enc_host = hostClassOfCompanion(enc) orelse enc;
        const own_host = hostClassOfCompanion(owner) orelse owner;
        break :blk b.module.classIsOrExtends(enc_host, own_host);
    };
    const lambda_literal_plain = inline_takes_fn and trailing_lambda and
        llp_arity_fits and llp_unshadowed and
        inline_state.inlineMemberOwner(f) == null and
        (rfs_on or !anyReceiverFormedFnParam(f)) and
        !anyCrossOrNoinlineParam(f) and
        !inline_call.argLambdaTargetsLabel(args, nm) and
        !std.mem.eql(u8, runtime.envOnce("KLIO_LLP") orelse "1", "0");
    // Kotlin inlines EVERY `inline fun`, lambda parameters or not — a
    // no-lambda member inline (`private inline fun peekOperation() =
    // opCodes[opCodesSize - 1]`) otherwise dispatches a full frame per
    // call (311k activations in one vpd window). Splice when the call is
    // bare inside the OWNER's own hierarchy (the member-splice window
    // threads `this`/owner scope), positional args fit with a defaulted
    // tail, and no local binding shadows the name. Top-level no-lambda
    // inlines already lower flat; receiver-typed ones ride the ext tiers.
    const plain_inline_nolambda = !inline_takes_fn and !trailing_lambda and
        f.receiver_type == null and !f.is_suspend and
        b.resolve(nm) == null and blk: {
        // An explicit call-site type argument on a NON-reified inline
        // (`listOf<String>()`) carries element knowledge the receiver
        // proofs read off the CALL; the splice would replace the call
        // with its body (`emptyList()`) and drop it. Keep those framed.
        if (has_explicit_type_args and !anyReified(f.type_params)) break :blk false;
        // The splice stands in for OVERLOAD RESOLUTION, so it may only
        // engage when resolution is trivial — a lone candidate under the
        // name. Committing by name+inline picked the sole INLINE overload
        // over its non-inline siblings: `plusAssign(element: E)` swallowed
        // `plusAssign(elements: List<E>)` inside MutableObjectList.addAll
        // (an unbounded E accepts the List, and the runtime rank that
        // prefers the List form never ran).
        if (b.module.funcsBySimpleName(nm).len != 1) break :blk false;
        for (f.params) |*p| {
            if (p.is_vararg) break :blk false;
        }
        if (want > f.params.len) break :blk false;
        var gi: usize = want;
        while (gi < f.params.len) : (gi += 1) {
            if (f.params[gi].default == null) break :blk false;
        }
        const owner = inline_state.inlineMemberOwner(f) orelse {
            // Top-level: only when unshadowed, mirroring the lambda tier.
            break :blk llp_unshadowed;
        };
        const enc = b.ownerClass() orelse break :blk false;
        const enc_host = hostClassOfCompanion(enc) orelse enc;
        const own_host = hostClassOfCompanion(owner) orelse owner;
        break :blk b.module.classIsOrExtends(enc_host, own_host);
    };
    if (runtime.envOnce("KLIO_EF_TRACE")) |efw| {
        if (std.mem.eql(u8, efw, nm)) {
            std.debug.print("[needs] {s} mismatch={} llp={} llp_unshadowed={} own={} encl={} resolve={} outer={} fits={} mil={} pin={}\n", .{
                nm,                         recv_mismatch,
                lambda_literal_plain,       llp_unshadowed,
                b.hasOwnMember(nm),         b.hasEnclosingMember(nm),
                b.resolve(nm) != null,      b.knowsOuter(nm),
                llp_arity_fits,             member_inline_lambda,
                plain_inline_nolambda,
            });
        }
    }
    return !recv_mismatch and
        (f.is_suspend or argLambdaHasNonlocalReturn(args) or
            inline_call.argsForwardInlineLambda(b, args) or has_reified or shadowed_by_member or
            companion_super_member or member_body_ext or lambda_literal_plain or
            member_inline_lambda or plain_inline_nolambda or
            inline_call.argLambdaMaySuspend(b, f, args));
}

/// True when `owner` names a companion object (a `$Companion`-mangled
/// lifted class) whose HOST class is the enclosing class — or an
/// ancestor of it. Both sides reduce to their host class: a bare call
/// written inside `Sub.Companion` or inside `Sub`'s own body sees the
/// companion members of `Sub`'s superclasses (Kotlin's static scope).
fn companionOwnerInEnclosingHierarchy(b: *FuncBuilder, owner: []const u8) bool {
    const o_host = hostClassOfCompanion(owner) orelse return false;
    const e = b.ownerClass() orelse return false;
    const e_host = hostClassOfCompanion(e) orelse e;
    return b.module.classIsOrExtends(e_host, o_host);
}

/// The class a `$Companion` mangle belongs to (`Base$Companion` →
/// `Base`), or null when `name` is not a companion mangle.
fn hostClassOfCompanion(name: []const u8) ?[]const u8 {
    const idx = std.mem.indexOf(u8, name, "$Companion") orelse return null;
    if (idx == 0) return null;
    return name[0..idx];
}

/// Audit one inline-target resolution (the `inline` records of
/// KLIO_RESOLVE_AUDIT): the simple-name narrowing's pick against the
/// index-first pick, compared on the splice that would actually occur —
/// a candidate failing the needs-splice gate never splices, so a
/// difference confined to non-splicing picks is not a divergence.
/// Divergences are graded like the bare-call audit's: the index
/// resolving an exact-arity overload where the simple-name table —
/// which only ever holds the inline overloads — fell back to a
/// vararg/default/arity-mismatched candidate is a `shape_correction`
/// (the pick takes the index's exact target), and the index resolving
/// in a strictly better scope tier than the simple-name pick ranks in
/// is a `tier_correction` (Kotlin's scope order — a named import
/// outranks even a same-package inline declaration — is a program
/// property the simple-name table cannot see). Anything else is
/// unexplained: an interpreter bug. KLIO_RESOLVE_STRICT turns an
/// unexplained divergence into a hard failure.
fn inlineResolveAudit(
    b: *FuncBuilder,
    nm: []const u8,
    file: ir.FileId,
    narrowed: ?*const ast.Function,
    pick: ?*const ast.Function,
    args: []const Expr,
    last_is_lambda: bool,
    ires: ir.Module.BareCallResolution,
) void {
    const audit_on = resolveAuditOn();
    const strict_on = resolveStrictOn();
    if (!audit_on and !strict_on) return;
    const old_eff: ?*const ast.Function = if (narrowed) |f|
        (if (bareInlineNeedsSplice(b, nm, f, args)) f else null)
    else
        null;
    const new_eff: ?*const ast.Function = if (pick) |f|
        (if (bareInlineNeedsSplice(b, nm, f, args)) f else null)
    else
        null;
    const divergent = old_eff != new_eff;
    const tier_corrected = divergent and ires.pick() != null and old_eff != null and blk: {
        const old_id = inline_state.inlineIdByAst(old_eff.?) orelse break :blk false;
        const old_tier = b.module.bareCallTierOf(FuncId.from(old_id), nm, b.self_package, file) orelse break :blk false;
        break :blk ires.tier < old_tier;
    };
    const explained = divergent and ires.pick() != null and
        (old_eff == null or tier_corrected or astPickInexact(old_eff.?, args.len, last_is_lambda));
    if (audit_on) {
        const outcome: []const u8 = switch (ires.outcome) {
            .resolved => "resolved",
            .deferred => "deferred",
        };
        const reason: []const u8 = switch (ires.outcome) {
            .resolved => "-",
            .deferred => |r| @tagName(r),
        };
        const old_np: usize = if (narrowed) |f| f.params.len else 0;
        const new_np: usize = if (pick) |f| f.params.len else 0;
        std.debug.print(
            "[KLIO_RESOLVE_AUDIT] inline name={s} pkg={s} arity={d} outcome={s} reason={s} old={s}/{d} new={s}/{d} splice_old={d} splice_new={d} divergent={d} correction={d}\n",
            .{
                nm,                            b.self_package,                args.len,
                outcome,                       reason,                        inlineCandLabel(narrowed),
                old_np,                        inlineCandLabel(pick),         new_np,
                @intFromBool(old_eff != null), @intFromBool(new_eff != null), @intFromBool(divergent),
                @intFromBool(explained),
            },
        );
    }
    if (strict_on and divergent and !explained) {
        std.debug.panic(
            "KLIO_RESOLVE_STRICT: unexplained inline-target divergence on '{s}' (pkg='{s}' arity={d}): simple-name pick {s} vs index pick {s}",
            .{ nm, b.self_package, args.len, inlineCandLabel(old_eff), inlineCandLabel(new_eff) },
        );
    }
}

/// Whether an inline candidate matches the call less exactly than any
/// index pick can: a vararg at any position, a default parameter, or a
/// declared arity differing from the call's (a trailing-lambda gap the
/// candidate's fn-typed last parameter absorbs is exact enough).
/// Whether `f`'s last parameter is function-typed, so it can host a trailing
/// lambda argument. A candidate that fails this cannot be the target of a
/// `name(args) { … }` call — the block would bind a scalar parameter.
fn astLastParamHostsLambda(f: *const ast.Function) bool {
    if (f.params.len == 0) return false;
    const last = f.params[f.params.len - 1];
    if (last.is_vararg) return false;
    return last.ty.function != null;
}

fn astPickInexact(f: *const ast.Function, want: usize, last_is_lambda: bool) bool {
    for (f.params) |p| {
        if (p.is_vararg) return true;
    }
    if (f.params.len != want) {
        const tl_fits = last_is_lambda and f.params.len != 0 and
            f.params[f.params.len - 1].ty.function != null and want >= 1 and
            f.params.len > want;
        if (!tl_fits) return true;
    }
    for (f.params) |p| {
        if (p.default != null) return true;
    }
    return false;
}

/// Audit label classifying an inline candidate's declaration shape
/// (overloads share the simple name; receiver-ness, suspend-ness, and
/// the printed parameter count identify the declaration).
fn inlineCandLabel(f: ?*const ast.Function) []const u8 {
    const fp = f orelse return "-";
    if (fp.receiver_type != null) {
        return if (fp.is_suspend) "ext+suspend" else "ext";
    }
    return if (fp.is_suspend) "plain+suspend" else "plain";
}

/// The definitely-known static type head of an argument expression, for
/// local-fn overload selection: literals, lambdas, and locals with a
/// declared type annotation. Null = unknown (never disproves).
fn staticArgHead(b: *const FuncBuilder, e: *const Expr) ?[]const u8 {
    return switch (e.*) {
        .BoolLit => "Boolean",
        .StringTemplate => "String",
        .CharLit => "Char",
        .IntLit => "Int",
        .FloatLit => "Double",
        .Lambda => "->",
        .Path => |p| blk: {
            if (p.segments.len != 1) break :blk null;
            break :blk b.localDeclType(p.segments[0].name);
        },
        // A zero-argument stdlib CONVERSION has a statically known result
        // type, and it is often the only evidence a bare call has. Without it
        // `writeULEB128(data.size.toUInt())` inside kotlinx-io's local
        // `Buffer.writeULEB128(data: UIntArray)` had no argument head, the
        // type disproof below was skipped, the local was judged applicable on
        // arity alone, and the call recursed into itself.
        .Call => |c| blk: {
            if (c.args.len != 0 or c.callee.* != .Member) break :blk null;
            break :blk conversionResultHead(c.callee.Member.name.name);
        },
        else => null,
    };
}

/// The result head of a stdlib collection factory (`listOf`, `mapOf`, ...), or
/// null for any other name. Deliberately a fixed list, like
/// `conversionResultHead`: these names fix their own result head.
fn factoryResultHead(name: []const u8) ?[]const u8 {
    const pairs = [_]struct { m: []const u8, t: []const u8 }{
        .{ .m = "listOf", .t = "List" },
        .{ .m = "listOfNotNull", .t = "List" },
        .{ .m = "emptyList", .t = "List" },
        .{ .m = "mutableListOf", .t = "MutableList" },
        .{ .m = "arrayListOf", .t = "ArrayList" },
        .{ .m = "setOf", .t = "Set" },
        .{ .m = "setOfNotNull", .t = "Set" },
        .{ .m = "emptySet", .t = "Set" },
        .{ .m = "mutableSetOf", .t = "MutableSet" },
        .{ .m = "hashSetOf", .t = "HashSet" },
        .{ .m = "linkedSetOf", .t = "LinkedHashSet" },
        .{ .m = "mapOf", .t = "Map" },
        .{ .m = "emptyMap", .t = "Map" },
        .{ .m = "mutableMapOf", .t = "MutableMap" },
        .{ .m = "hashMapOf", .t = "HashMap" },
        .{ .m = "linkedMapOf", .t = "LinkedHashMap" },
        .{ .m = "sequenceOf", .t = "Sequence" },
        .{ .m = "emptySequence", .t = "Sequence" },
    };
    for (pairs) |p| {
        if (std.mem.eql(u8, name, p.m)) return p.t;
    }
    return null;
}

/// The result type of a zero-argument stdlib conversion (`toUInt`, `toLong`,
/// ...), or null for any other name. Deliberately a fixed list: these are
/// canonical stdlib conversions whose result type is fixed by their name.
fn conversionResultHead(name: []const u8) ?[]const u8 {
    const pairs = [_]struct { m: []const u8, t: []const u8 }{
        .{ .m = "toInt", .t = "Int" },       .{ .m = "toLong", .t = "Long" },
        .{ .m = "toShort", .t = "Short" },   .{ .m = "toByte", .t = "Byte" },
        .{ .m = "toFloat", .t = "Float" },   .{ .m = "toDouble", .t = "Double" },
        .{ .m = "toUInt", .t = "UInt" },     .{ .m = "toULong", .t = "ULong" },
        .{ .m = "toUShort", .t = "UShort" }, .{ .m = "toUByte", .t = "UByte" },
        .{ .m = "toChar", .t = "Char" },     .{ .m = "toBoolean", .t = "Boolean" },
    };
    for (pairs) |p| {
        if (std.mem.eql(u8, name, p.m)) return p.t;
    }
    return null;
}

fn allUppercase(s: []const u8) bool {
    for (s) |c| {
        if (!std.ascii.isUpper(c)) return false;
    }
    return s.len != 0;
}

const numeric_heads = [_][]const u8{
    "Int",  "Long",  "Short",  "Byte",  "Double", "Float",
    "UInt", "ULong", "UShort", "UByte", "Number",
};

fn headIsNumeric(h: []const u8) bool {
    for (numeric_heads) |n| {
        if (std.mem.eql(u8, h, n)) return true;
    }
    return false;
}

/// A builtin scalar head — the only heads that definitely disprove one
/// another (and that a lambda literal can never satisfy).
fn headIsScalar(h: []const u8) bool {
    if (headIsNumeric(h)) return true;
    const scalars = [_][]const u8{ "Boolean", "String", "Char" };
    for (scalars) |s| {
        if (std.mem.eql(u8, h, s)) return true;
    }
    return false;
}

/// Whether declared head `d` denotes a function type. A parsed function
/// type carries the synthetic tag `"<function>"` (see `ast.TypeRef`); a
/// spelled-out `(P) -> R` or an erased `FunctionN` name also count.
fn headIsFunctionType(d: []const u8) bool {
    return std.mem.eql(u8, d, "<function>") or
        std.mem.indexOf(u8, d, "->") != null or
        std.mem.startsWith(u8, d, "Function");
}

/// Can an argument with static head `h` bind a parameter declared `d`?
/// Disproof-only: `true` unless both sides are known and definitely
/// incompatible (numeric literals coerce across the numeric family).
///
/// `strict` tightens the lambda case for OVERLOAD SELECTION: a `{ … }`
/// argument matches only a function-typed parameter, so a `(…) -> R`
/// sibling wins over a same-arity non-function one. When `false` (the
/// applicability / shadow-or-fall-through decision) the lambda case is
/// disproof-only: reject only a definite non-function scalar, since an
/// unknown class name may be a function typealias.
/// Builtin container heads: final array/collection types that no scalar can
/// ever be an instance of.
fn headIsContainer(h: []const u8) bool {
    const heads = [_][]const u8{
        "Array",       "IntArray",   "LongArray",  "ShortArray",  "ByteArray",
        "FloatArray",  "DoubleArray", "CharArray", "BooleanArray",
        "UIntArray",   "ULongArray", "UShortArray", "UByteArray",
        "List",        "MutableList", "Set",       "MutableSet",
        "Map",         "MutableMap", "Collection", "MutableCollection",
        "Iterable",    "Sequence",
    };
    for (heads) |x| {
        if (std.mem.eql(u8, h, x)) return true;
    }
    return false;
}

fn headCompatible(h: []const u8, d_raw: []const u8, strict: bool) bool {
    const d = std.mem.trimEnd(u8, d_raw, "?");
    if (std.mem.eql(u8, d, "Any") or std.mem.eql(u8, d, "Unit")) return true;
    if (d.len > 0 and d.len <= 2 and allUppercase(d)) return true;
    const d_fn = headIsFunctionType(d);
    if (std.mem.eql(u8, h, "->")) {
        if (d_fn) return true;
        return if (strict) false else !headIsScalar(d);
    }
    if (d_fn) return false;
    if (std.mem.eql(u8, h, d)) return true;
    if (headIsNumeric(h) and headIsNumeric(d)) return true;
    // A scalar argument can never satisfy an ARRAY or COLLECTION parameter.
    // These are final builtin containers with no scalar subtype, so unlike a
    // plain class name (which could be a supertype of the argument) they
    // disprove outright. kotlinx-io's local
    // `Buffer.writeULEB128(data: UIntArray)` was judged able to take
    // `writeULEB128(data.size.toUInt())` without this, and the call recursed
    // into itself.
    if (headIsScalar(h) and headIsContainer(d)) return false;
    // The head is a definite literal kind; a differently-named declared
    // class stays unknown (could be a supertype) — only the builtin
    // scalar heads disprove each other.
    return !(headIsScalar(h) and headIsScalar(d));
}

/// Statically select among same-named local-fn declarations: arity and
/// named-argument fit, then literal/declared-type disproof per bound
/// parameter. Returns the unique survivor's mangled binding, or null
/// when no signature fact separates the candidates (the caller keeps
/// the plain last-decl binding).
/// Can any same-named local-function declaration take this call at all
/// (arity, varargs, defaults, argument names)? When none can, the local
/// name does not shadow the outer candidates.
fn anyLocalFnOverloadApplicable(
    b: *const FuncBuilder,
    ovs: []const build.LocalFnOverload,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!bool {
    outer: for (ovs) |*ov| {
        if (ov.is_ext) {
            // A statically known receiver type adjudicates; a scope with a
            // REACHABLE `this` but no threaded type (a nested lambda inside
            // the local ext's own body) keeps the candidate UNPROVEN — only
            // a genuinely receiver-less scope drops it.
            if (b.recvTypeRef()) |receiver| {
                if (!try localOverloadReceiverCouldApply(b, ov, receiver)) continue;
            } else if (b.resolve("this") == null and !b.knowsOuter("this") and !b.capturesThisSlot()) {
                return false;
            }
        }
        if (args.len < ov.n_required and !ov.has_vararg) continue;
        if (args.len > ov.param_tys.len and !ov.has_vararg) continue;
        var bound = [_]bool{false} ** 64;
        if (ov.param_tys.len > bound.len) continue;
        var positional: usize = 0;
        for (args, 0..) |*a, i| {
            const supplied: ?[]const u8 = if (i < ast_arg_names.len) ast_arg_names[i] else null;
            var pi: ?usize = null;
            if (supplied) |nm| {
                var found = false;
                for (ov.param_names, 0..) |pn, k| {
                    if (std.mem.eql(u8, pn, nm)) {
                        if (bound[k]) continue :outer;
                        pi = k;
                        bound[k] = true;
                        found = true;
                        break;
                    }
                }
                if (!found) continue :outer;
            } else {
                // A generated positional arg after named ones (the compose
                // pass appends the ($composer, $changed) pair positionally
                // behind named user args): skip slots the names already
                // bound, or the pair refutes against the first user param.
                while (positional < ov.param_tys.len and bound[positional]) positional += 1;
                if (positional < ov.param_tys.len) {
                    pi = positional;
                    bound[positional] = true;
                } else if (!ov.has_vararg) {
                    continue :outer;
                }
                positional += 1;
            }
            // Type-head disproof per bound parameter, mirroring
            // `selectLocalFnOverload`: a `validate { … }` (lambda arg) does not
            // fit `fun validate(state: Int)`. Without this the local name was
            // deemed applicable on arity alone and the call recursed into
            // itself instead of falling through to the outer extension.
            if (pi) |k| {
                const d = ov.param_tys[k] orelse continue;
                const h = staticArgHead(b, a) orelse continue;
                if (!headCompatible(h, d, false)) continue :outer;
            }
        }
        return true;
    }
    return false;
}

/// Whether the enclosing local fn's own overload record can take this call
/// (arity + argument names). Missing record (the table did not reach this
/// deferred body) keeps the route available — the runtime binder still
/// resolves the mangled cell's closure.
fn selfLocalFnApplicable(
    b: *const FuncBuilder,
    mangled: []const u8,
    bare: []const u8,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!bool {
    const decls = b.localFnDecls(bare) orelse return true;
    for (decls) |*ov| {
        if (!std.mem.eql(u8, ov.mangled, mangled)) continue;
        return anyLocalFnOverloadApplicable(b, @as([*]const build.LocalFnOverload, @ptrCast(ov))[0..1], args, ast_arg_names);
    }
    return true;
}

/// Ext-only variant of `selectLocalFnOverload` for a RECEIVER-FULL call
/// (`this.f(args)` / `recv.f(args)`): only extension siblings can take a
/// receiver, and their applicability is judged against the receiver's
/// DECLARED type (in scope at the call), not the enclosing lambda's
/// receiver context.
fn selectLocalExtOverload(
    b: *const FuncBuilder,
    ovs: []const build.LocalFnOverload,
    declared_ty: ?TypeRef,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!?[]const u8 {
    var survivor: ?*const build.LocalFnOverload = null;
    var n_survivors: usize = 0;
    outer: for (ovs) |*ov| {
        if (!ov.is_ext) continue;
        if (declared_ty) |actual| {
            if (!try localOverloadReceiverCouldApply(b, ov, actual)) continue;
        }
        if (args.len < ov.n_required and !ov.has_vararg) continue;
        if (args.len > ov.param_tys.len and !ov.has_vararg) continue;
        var bound = [_]bool{false} ** 64;
        if (ov.param_tys.len > bound.len) continue;
        var positional: usize = 0;
        for (args, 0..) |*a, i| {
            const supplied: ?[]const u8 = if (i < ast_arg_names.len) ast_arg_names[i] else null;
            var pi: ?usize = null;
            if (supplied) |nm| {
                for (ov.param_names, 0..) |pn, k| {
                    if (std.mem.eql(u8, pn, nm)) {
                        if (bound[k]) continue :outer;
                        pi = k;
                        bound[k] = true;
                        break;
                    }
                }
                if (pi == null) continue :outer;
            } else {
                // A generated positional arg after named ones (the compose
                // pass appends the ($composer, $changed) pair positionally
                // behind named user args): skip slots the names already
                // bound, or the pair refutes against the first user param.
                while (positional < ov.param_tys.len and bound[positional]) positional += 1;
                if (positional < ov.param_tys.len) {
                    pi = positional;
                    bound[positional] = true;
                } else if (!ov.has_vararg) {
                    continue :outer;
                }
                positional += 1;
            }
            if (pi) |k| {
                const d = ov.param_tys[k] orelse continue;
                const h = staticArgHead(b, a) orelse continue;
                if (!headCompatible(h, d, true)) continue :outer;
            }
        }
        survivor = ov;
        n_survivors += 1;
    }
    if (n_survivors == 1) return survivor.?.mangled;
    return null;
}

/// Call a selected local EXTENSION overload through its mangled cell with
/// an EXPLICIT receiver expression prepended as the leading `this` arg.
/// Null when the cell is unreachable from this scope (forward reference);
/// the caller keeps its plain-name route.
fn lowerSelectedLocalExtCallWithReceiver(
    b: *FuncBuilder,
    mangled: []const u8,
    receiver: *const Expr,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!?Reg {
    const cell: Reg = if (b.resolve(mangled)) |r|
        r
    else if (b.knowsOuter(mangled))
        try resolveCapture(b, mangled)
    else
        return null;
    const callee_reg = b.allocReg();
    try b.push(.{ .CellGet = .{ .dst = callee_reg, .cell = cell } });
    const recv = try lowerReceiver(b, receiver);
    const vals = try b.allocator.alloc(Reg, args.len + 1);
    defer b.allocator.free(vals);
    vals[0] = recv;
    for (args, 0..) |*a, i| vals[i + 1] = try lowerExpr(b, a);
    const args_start = try packContiguous(b, vals);
    // The receiver rides as slot 0: shift the arg-name list one slot right,
    // or a named call (`this.Composition(a = true, ...)`) labels the RECEIVER
    // "a" and every binding misaligns.
    const shifted: []const ?[]const u8 = blk: {
        if (ast_arg_names.len == 0) break :blk ast_arg_names;
        const sh = try b.allocator.alloc(?[]const u8, ast_arg_names.len + 1);
        sh[0] = null;
        @memcpy(sh[1..], ast_arg_names);
        break :blk sh;
    };
    const arg_names = try internArgNames(b.allocator, b.module, shifted);
    const dst = b.allocReg();
    try b.push(.{ .CallValue = .{
        .dst = dst,
        .callee = callee_reg,
        .args = args_start,
        .n_args = @intCast(vals.len),
        .arg_names = arg_names,
    } });
    return dst;
}

fn selectLocalFnOverload(
    b: *const FuncBuilder,
    ovs: []const build.LocalFnOverload,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!?[]const u8 {
    var survivor: ?*const build.LocalFnOverload = null;
    var n_survivors: usize = 0;
    var exact: ?*const build.LocalFnOverload = null;
    var n_exact: usize = 0;
    outer: for (ovs) |*ov| {
        // An EXTENSION sibling is only a candidate where a KNOWN
        // receiver type is in scope (the enclosing receiver-lambda's
        // declared receiver, carried across lambda boundaries):
        // `fun Checker.Composition()` beside a plain local
        // `fun Composition(...)` binds inside the validator's receiver
        // lambda and never from a receiver-less scope. A merely-captured
        // `this` is not enough — every lambda captures one.
        if (ov.is_ext) {
            const receiver = b.recvTypeRef() orelse continue;
            if (!try localOverloadReceiverCouldApply(b, ov, receiver)) continue;
        }
        if (args.len < ov.n_required and !ov.has_vararg) continue;
        if (args.len > ov.param_tys.len and !ov.has_vararg) continue;
        var bound = [_]bool{false} ** 64;
        if (ov.param_tys.len > bound.len) continue;
        var positional: usize = 0;
        for (args, 0..) |*a, i| {
            const supplied: ?[]const u8 = if (i < ast_arg_names.len) ast_arg_names[i] else null;
            var pi: ?usize = null;
            if (supplied) |nm| {
                for (ov.param_names, 0..) |pn, k| {
                    if (std.mem.eql(u8, pn, nm)) {
                        if (bound[k]) continue :outer;
                        pi = k;
                        bound[k] = true;
                        break;
                    }
                }
                if (pi == null) continue :outer;
            } else {
                // A generated positional arg after named ones (the compose
                // pass appends the ($composer, $changed) pair positionally
                // behind named user args): skip slots the names already
                // bound, or the pair refutes against the first user param.
                while (positional < ov.param_tys.len and bound[positional]) positional += 1;
                if (positional < ov.param_tys.len) {
                    pi = positional;
                    bound[positional] = true;
                } else if (!ov.has_vararg) {
                    continue :outer;
                }
                positional += 1;
            }
            if (pi) |k| {
                const d = ov.param_tys[k] orelse continue;
                const h = staticArgHead(b, a) orelse continue;
                if (!headCompatible(h, d, true)) continue :outer;
            }
        }
        survivor = ov;
        n_survivors += 1;
        if (args.len == ov.param_tys.len) {
            exact = ov;
            n_exact += 1;
        }
    }
    if (n_survivors == 1) return survivor.?.mangled;
    if (n_exact == 1) return exact.?.mangled;
    return null;
}

/// Emit the call to a statically selected local-fn overload through its
/// mangled cell binding — resolvable in the declaring scope or as a
/// capture. Null when this scope cannot reach the cell (a forward sibling
/// reference from a lambda captured before the sibling declared); the
/// caller falls back to the plain-name binding.
fn lowerSelectedLocalOverloadCall(
    b: *FuncBuilder,
    bare: []const u8,
    mangled: []const u8,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!?Reg {
    const cell: Reg = if (b.resolve(mangled)) |r|
        r
    else if (b.knowsOuter(mangled))
        try resolveCapture(b, mangled)
    else
        return null;
    const callee_reg = b.allocReg();
    try b.push(.{ .CellGet = .{ .dst = callee_reg, .cell = cell } });
    // A selected local *extension* overload takes the enclosing receiver
    // as its leading `this` param, like the plain-name ext arm.
    if (b.isLocalExtFn(mangled)) {
        // No reachable receiver: fall back to the plain-name route rather
        // than invoking the extension with its `this` slot missing.
        const this_reg = try resolveThisForBareCallNoBind(b);
        if (this_reg == null) return null;
        if (this_reg) |tr| {
            const recv = b.allocReg();
            try b.push(.{ .Move = .{ .dst = recv, .src = tr } });
            const vals = try b.allocator.alloc(Reg, args.len + 1);
            defer b.allocator.free(vals);
            vals[0] = recv;
            for (args, 0..) |*a, i| vals[i + 1] = try lowerExpr(b, a);
            const args_start = try packContiguous(b, vals);
            // The receiver rides as slot 0: shift the arg-name list one
            // slot right, or a named call (`Composition(a = ..., ...)`)
            // labels the RECEIVER "a" and every binding misaligns.
            const shifted: []const ?[]const u8 = blk: {
                if (ast_arg_names.len == 0) break :blk ast_arg_names;
                const sh = try b.allocator.alloc(?[]const u8, ast_arg_names.len + 1);
                sh[0] = null;
                @memcpy(sh[1..], ast_arg_names);
                break :blk sh;
            };
            const arg_names = try internArgNames(b.allocator, b.module, shifted);
            const dst = b.allocReg();
            try b.push(.{ .CallValue = .{
                .dst = dst,
                .callee = callee_reg,
                .args = args_start,
                .n_args = @intCast(vals.len),
                .arg_names = arg_names,
            } });
            return dst;
        }
    }
    const lfp: ?[]const ?[]const u8 = if (allNull(ast_arg_names)) b.localFnParamTys(mangled) else null;
    const run = try lowerArgRunFull(b, args, null, lfp);
    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
    const dst = b.allocReg();
    var member_declared = b.hasEnclosingMember(bare);
    if (!member_declared) {
        if (b.ownerClass()) |oc| {
            if (b.module.registry.hierarchy_methods.get(oc)) |s| {
                member_declared = s.contains(bare);
            }
        }
    }
    if (member_declared) {
        if (try resolveThisForBareCallNoBind(b)) |this_reg| {
            const name = try b.module.internConst(b.allocator, .{ .String = bare });
            orEmitAudit(b, "cvom_unresolved_bare", "CallValueOrMember", bare);
            try b.push(.{ .CallValueOrMember = .{
                .dst = dst,
                .callee = callee_reg,
                .this_recv = this_reg,
                .name = name,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
    }
    try b.push(.{ .CallValue = .{
        .dst = dst,
        .callee = callee_reg,
        .args = run[0],
        .n_args = run[1],
        .arg_names = arg_names,
    } });
    return dst;
}

/// A single-name callee bound as a local / parameter / receiver-lambda-param.
fn lowerValueInvocation(
    b: *FuncBuilder,
    callee: *const Expr,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error!?Reg {
    const name0 = callee.Path.segments[0].name;

    // A bare call to a receiver-lambda param reached as a capture. The
    // declared receiver HEAD rides the instruction: the captured `this`
    // register can be a coroutine that rebound the enclosing block's slot,
    // and the VM re-selects the innermost implicit receiver of the
    // declared type (combineInternal's `transform(...)` binds
    // this@combineInternal, the FlowCollector, not the flowScope
    // coroutine).
    if (runtime.envOnce("KLIO_RLP_TRACE")) |w| {
        if (std.mem.eql(u8, w, name0))
            std.debug.print("[rlp-arm] {s} isRLP={} resolved={} outer={} head={s} in={s}\n", .{ name0, b.isReceiverLambdaParam(name0), b.resolve(name0) != null, b.knowsOuter(name0), b.receiverLambdaRecvHead(name0) orelse "-", build.currentRealFn() orelse "-" });
    }
    if (b.isReceiverLambdaParam(name0) and b.resolve(name0) == null and b.knowsOuter(name0)) {
        // The innermost implicit receiver OF THE DECLARED HEAD, resolved
        // lexically: an enclosing extension fn's receiver reaches nested
        // lambdas through its `this@<fn>` entry slot, which no coroutine
        // receiver rebinding ever displaces (the flowScope block's `this`
        // is the FlowCoroutine; `transform(...)` still binds
        // this@combineInternal, the FlowCollector).
        var head_receiver: ?Reg = null;
        if (b.receiverLambdaRecvHead(name0)) |h| {
            const tower = try b.collectReceiverTowerLabeled(b.allocator, null, null);
            defer b.allocator.free(tower);
            for (tower) |entry| {
                if (!std.mem.eql(u8, entry.head, h)) continue;
                if (entry.label) |lbl| {
                    const label = try std.fmt.allocPrint(b.allocator, "this@{s}", .{lbl});
                    if (b.resolve(label)) |r| {
                        head_receiver = r;
                    } else if (b.knowsOuter(label)) {
                        const dst2 = try b.loadCaptureHoisted(label);
                        try b.bind(label, dst2);
                        head_receiver = dst2;
                    }
                    if (runtime.envOnce("KLIO_RLP_TRACE") != null)
                        std.debug.print("[rlp-head] {s} label={s} hit={} in={s}\n", .{ name0, label, head_receiver != null, build.currentRealFn() orelse "-" });
                }
                break;
            }
        }
        const this_reg: ?Reg = head_receiver orelse if (b.knowsOuter("this") or b.capturesThisSlot())
            try resolveCapture(b, "this")
        else
            b.resolve("this");
        if (this_reg) |tr| {
            const callee_r = try resolveCapture(b, name0);
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const head_c: ?ir.ConstId = if (b.receiverLambdaRecvHead(name0)) |h|
                try b.module.internConst(b.allocator, .{ .String = h })
            else
                null;
            const dst = b.allocReg();
            try b.push(.{ .CallValueWithThis = .{
                .dst = dst,
                .callee = callee_r,
                .receiver = tr,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
                .recv_head = head_c,
            } });
            return dst;
        }
    }

    // A bare call to a local *extension* function reached as a capture:
    // prepend the enclosing receiver as the closure's leading `this`
    // param, mirroring the declaring-scope arm below (`handleCall(...)`
    // inside an `on(Send) { ... }` lambda binds the Sender receiver).
    if (b.isLocalExtFn(name0) and b.resolve(name0) == null and b.knowsOuter(name0)) {
        const this_reg: ?Reg = if (b.knowsOuter("this") or b.capturesThisSlot())
            try resolveCapture(b, "this")
        else
            b.resolve("this");
        if (this_reg) |tr| {
            const callee_r = try resolveCapture(b, name0);
            const recv = b.allocReg();
            try b.push(.{ .Move = .{ .dst = recv, .src = tr } });
            const vals = try b.allocator.alloc(Reg, args.len + 1);
            defer b.allocator.free(vals);
            vals[0] = recv;
            for (args, 0..) |*a, i| vals[i + 1] = try lowerExpr(b, a);
            const args_start = try packContiguous(b, vals);
            // The receiver rides as slot 0: shift the arg-name list one slot
            // right, or a named call (`Composition(a = true, ...)`) labels
            // the RECEIVER "a" and every binding misaligns.
            const shifted: []const ?[]const u8 = blk: {
                if (ast_arg_names.len == 0) break :blk ast_arg_names;
                const sh = try b.allocator.alloc(?[]const u8, ast_arg_names.len + 1);
                sh[0] = null;
                @memcpy(sh[1..], ast_arg_names);
                break :blk sh;
            };
            const arg_names = try internArgNames(b.allocator, b.module, shifted);
            const dst = b.allocReg();
            try b.push(.{ .CallValue = .{
                .dst = dst,
                .callee = callee_r,
                .args = args_start,
                .n_args = @intCast(vals.len),
                .arg_names = arg_names,
            } });
            return dst;
        }
    }

    // Member-function precedence over a same-named value/param. A local
    // fn with a same-named enclosing member also routes through the
    // arbitrated form: the value arm wins unless the closure's declared
    // params refute the args (Kotlin picks the member overload then), so
    // `testEncode(codec, byteArray, s)` reaches the private member past
    // the String-typed local.
    const redirect_to_member = blk: {
        var member_declared = b.hasEnclosingMember(name0);
        if (!member_declared) {
            if (b.ownerClass()) |oc| {
                if (b.module.registry.hierarchy_methods.get(oc)) |s| {
                    member_declared = s.contains(name0);
                }
            }
        }
        break :blk member_declared and b.resolve(name0) != null and !b.isLocalExtFn(name0);
    };
    if (redirect_to_member) {
        if (try resolveThisForBareCallNoBind(b)) |this_reg| {
            var callee_reg = b.resolve(name0).?;
            if (b.isBoxed(name0)) {
                const c = b.allocReg();
                try b.push(.{ .CellGet = .{ .dst = c, .cell = callee_reg } });
                callee_reg = c;
            }
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const dst = b.allocReg();
            const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
            orEmitAudit(b, "cvom_redirect_member", "CallValueOrMember", name0);
            try b.push(.{ .CallValueOrMember = .{
                .dst = dst,
                .callee = callee_reg,
                .this_recv = this_reg,
                .name = nm,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
    }

    if (b.resolve(name0)) |reg| {
        // A non-function-typed param does not shadow a same-named top-level
        // function for a *call*: `flow { … }` inside
        // `fun Flow<T>.combine(flow: Flow<T2>, …)` resolves to the `flow {}`
        // builder, not the `flow: Flow<T2>` parameter (a `Flow` is not
        // invokable). Defer to the bare-function path so the builder binds.
        if (b.isNonFnParam(name0) and
            b.module.hasBareCallCandidate(name0, callee.Path.segments[0].span.file))
        {
            return null;
        }
        // Nor does a LOCAL whose initializer is a definite non-callable
        // literal: `var nodeIndex = 0` beside `fun nodeIndex(slots, group)`
        // resolves the call `nodeIndex(slots, startingGroup)` to the
        // function (an Int is not invokable) — the composer's
        // movable-content insert is the shape.
        // A constructor initializer of a class with no `invoke` operator
        // (member or extension) is equally non-invokable, and the member
        // alternative counts alongside the bare-function one: inside a
        // spliced `ReentrantLock.withLock` body the bare `lock()` is the
        // receiver's member, never the caller's `val lock =
        // ReentrantLock()` local.
        if ((b.module.hasBareCallCandidate(name0, callee.Path.segments[0].span.file) or
            (inReceiverContext(b) and anyReceiverClassDeclares(b, name0))) and
            !b.isLocalFn(name0))
        {
            if (b.localInitExpr(name0)) |init_e| {
                if (argLitKind(init_e) != null) return null;
                if (ctorInitNonInvocable(b, init_e, args.len)) return null;
                if (callInitNonInvocable(b, init_e, args.len)) return null;
                if (try initTypeNonInvocable(b, init_e, args.len)) return null;
            } else if (b.knowsOuter(name0) and b.spliceRecvTy() != null and
                anyReceiverClassDeclares(b, name0))
            {
                // A CAPTURE-reached local has no recorded initializer to
                // disprove invocability, but the spliced receiver's class
                // declares the name: the same `lock()`-in-withLock rule
                // applies (the body's bare call is the receiver's member),
                // so defer to the arbitrated/member path.
                return null;
            }
        }
        // Nor does a function-typed param shadow one for a TRAILING-LAMBDA
        // call it cannot accept. The lambda binds the callee's last parameter,
        // so a param whose own last parameter is not a function type is not
        // this call's target: inside
        // `Flow<T>.map(crossinline transform: suspend (T) -> R)` the body's
        // `transform { value -> … }` is the `Flow.transform` OPERATOR, and only
        // the inner `transform(value)` is the parameter. Binding the parameter
        // there passed the operator's own lambda in as the emitted value, so
        // `map`'s caller saw a closure where its element belonged.
        if (plainFnParamRejectsTrailingLambda(b, name0, args)) {
            return null;
        }
        var callee_reg = reg;
        if (b.isBoxed(name0)) {
            const c = b.allocReg();
            try b.push(.{ .CellGet = .{ .dst = c, .cell = reg } });
            callee_reg = c;
        }
        // A bare call to a receiver-typed function param. With explicit
        // positional args the FIRST one is the receiver (`f: T.() -> R`
        // called `f(x)` means `x.f()`); with none, the enclosing `this`.
        if (b.isReceiverLambdaParam(name0) and args.len >= 1 and
            ast_arg_names.len >= 1 and ast_arg_names[0] == null and blk: {
            const ar = b.receiverLambdaArity(name0) orelse break :blk false;
            break :blk args.len == ar + 1;
        }) {
            const recv_r = try lowerExpr(b, &args[0]);
            const run = try lowerArgRun(b, args[1..]);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names[1..]);
            const dst = b.allocReg();
            try b.push(.{ .CallValueWithThis = .{
                .dst = dst,
                .callee = callee_reg,
                .receiver = recv_r,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
        if (b.isReceiverLambdaParam(name0)) {
            const this_reg = try resolveThisForBareCallNoBind(b);
            if (this_reg) |tr| {
                const run = try lowerArgRun(b, args);
                const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
                // The declared receiver HEAD rides the instruction: inside a
                // spliced/nested receiver block the syntactic `this` can be
                // the block's own receiver (flowScope's coroutine), while
                // Kotlin binds the innermost implicit receiver of the
                // DECLARED type (`transform(...)` for a
                // `FlowCollector.(Array) -> Unit` param binds
                // this@combineInternal).
                const head_c: ?ir.ConstId = if (b.receiverLambdaRecvHead(name0)) |h|
                    try b.module.internConst(b.allocator, .{ .String = h })
                else
                    null;
                const dst = b.allocReg();
                try b.push(.{ .CallValueWithThis = .{
                    .dst = dst,
                    .callee = callee_reg,
                    .receiver = tr,
                    .args = run[0],
                    .n_args = run[1],
                    .arg_names = arg_names,
                    .recv_head = head_c,
                } });
                return dst;
            }
        }
        // A bare call to a *local extension* function.
        if (b.isLocalExtFn(name0)) {
            const this_reg = try resolveThisForBareCallNoBind(b);
            if (this_reg) |tr| {
                const recv = b.allocReg();
                try b.push(.{ .Move = .{ .dst = recv, .src = tr } });
                const vals = try b.allocator.alloc(Reg, args.len + 1);
                defer b.allocator.free(vals);
                vals[0] = recv;
                for (args, 0..) |*a, i| vals[i + 1] = try lowerExpr(b, a);
                const args_start = try packContiguous(b, vals);
                // The receiver rides as slot 0: shift the arg-name list one
                // slot right, or a named call (`Composition(a = true, ...)`)
                // labels the RECEIVER "a" and every binding misaligns.
                const shifted: []const ?[]const u8 = blk: {
                    if (ast_arg_names.len == 0) break :blk ast_arg_names;
                    const sh = try b.allocator.alloc(?[]const u8, ast_arg_names.len + 1);
                    sh[0] = null;
                    @memcpy(sh[1..], ast_arg_names);
                    break :blk sh;
                };
                const arg_names = try internArgNames(b.allocator, b.module, shifted);
                const dst = b.allocReg();
                try b.push(.{ .CallValue = .{
                    .dst = dst,
                    .callee = callee_reg,
                    .args = args_start,
                    .n_args = @intCast(vals.len),
                    .arg_names = arg_names,
                } });
                return dst;
            }
        }
        const lfp: ?[]const ?[]const u8 = if (allNull(ast_arg_names)) b.localFnParamTys(name0) else null;
        const run = try lowerArgRunFull(b, args, null, lfp);
        const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
        const dst = b.allocReg();
        try b.push(.{ .CallValue = .{
            .dst = dst,
            .callee = callee_reg,
            .args = run[0],
            .n_args = run[1],
            .arg_names = arg_names,
        } });
        return dst;
    }
    return null;
}

/// Whether a single-segment class-name call resolves to the constructor
/// rather than a same-named factory function.
const LitKind = enum { numeric, string, boolean, char };

/// Whether an expression's STATIC type head is definitely a list-family
/// value: a call to a list factory, or a `listOf(...) + x` chain. Used to
/// route `list + (rhs as Any)` through `plusElement`.
fn staticListHead(e: *const Expr) bool {
    return switch (e.*) {
        .Call => |c| blk: {
            if (c.callee.* != .Path or c.callee.Path.segments.len != 1) break :blk false;
            const n = c.callee.Path.segments[0].name;
            break :blk std.mem.eql(u8, n, "listOf") or std.mem.eql(u8, n, "mutableListOf") or
                std.mem.eql(u8, n, "emptyList") or std.mem.eql(u8, n, "arrayListOf");
        },
        .Binary => |bi| bi.op == .Add and staticListHead(bi.lhs),
        else => false,
    };
}

/// Definite builtin value kind of a literal argument expression, or null when
/// the argument's type is not a known literal (so it can never *disprove* a
/// candidate parameter type).
fn argLitKind(e: *const Expr) ?LitKind {
    return switch (e.*) {
        .IntLit, .FloatLit => .numeric,
        .BoolLit => .boolean,
        .CharLit => .char,
        .StringTemplate => .string,
        // A signed literal is a literal: `nextInt(-1)` carries numeric
        // evidence exactly as `nextInt(1)` does.
        .Unary => |u| if ((u.op == .Neg or u.op == .Pos) and
            (u.expr.* == .IntLit or u.expr.* == .FloatLit)) .numeric else null,
        else => null,
    };
}

/// Whether a local's initializer is a constructor call of a concrete class
/// that provably has no `invoke` operator — member (own or inherited) or
/// applicable extension — making the local's value non-invokable, so a bare
/// call of its name must bind a same-named function or member instead.
/// Answers false whenever anything is unknown (qualified callee, abstract
/// classifier, absent hierarchy entry): unknown keeps the local binding.
/// Whether a local initialized by an ordinary FUNCTION call is non-invocable,
/// judged from that function's declared return type. `ctorInitNonInvocable`
/// answers only `val x = X(...)`; this answers `val box = mk()` and, the shape
/// that matters across kotlinx's flow tests, `val flow = flowOf(1, 2)` — a
/// `Flow` declares no `invoke`, so the call `flow { … }` written beside it
/// names the `flow { … }` builder, exactly as Kotlin resolves it.
/// The same non-invokable test over the initializer's STATIC TYPE, so a
/// local initialised by anything the deriver can type — a member call
/// (`val flow = listOf(1).asFlow()`), a property read, a chain — shadows a
/// same-named function only when its own type could actually take the call.
/// `Flow` declares no `invoke`, so `flow { emit(42) }` beside such a local
/// is the BUILDER.
fn initTypeNonInvocable(b: *FuncBuilder, init_e: *const Expr, argc: usize) Allocator.Error!bool {
    var ty = (staticExprTypeRef(b, init_e) catch null) orelse return false;
    defer ty.deinit(b.allocator);
    const head = typeHead(std.mem.trimEnd(u8, ty.name, "?"));
    if (head.len == 0) return false;
    if (std.mem.startsWith(u8, head, "Function")) return false;
    if (std.mem.eql(u8, head, "<function>")) return false;
    const cid = b.module.uniqueClassIdBySimpleName(head) orelse b.module.classId(head) orelse return false;
    if (cid.int() >= b.module.classes.items.len) return false;
    const cls = &b.module.classes.items[cid.int()];
    const methods = b.module.registry.hierarchy_methods.get(cls.fqn) orelse
        b.module.registry.hierarchy_methods.get(cls.name) orelse return false;
    if (methods.contains("invoke")) return false;
    return b.module.extCouldApplyWhy(b.allocator, cls.name, "invoke", argc) == .none;
}

fn callInitNonInvocable(b: *FuncBuilder, init_e: *const Expr, argc: usize) bool {
    const call = switch (init_e.*) {
        .Call => |*c| c,
        else => return false,
    };
    const path = switch (call.callee.*) {
        .Path => |*p| p,
        else => return false,
    };
    if (path.segments.len != 1) return false;
    const fid = b.module.funcId(path.segments[0].name) orelse return false;
    const f = b.module.funcById(fid) orelse return false;
    if (!f.return_ty_declared) return false;
    const head = typeHead(std.mem.trimEnd(u8, f.return_ty.name, "?"));
    if (std.mem.indexOf(u8, f.return_ty.name, "->") != null) return false;
    if (std.mem.startsWith(u8, head, "Function")) return false;
    const cid = b.module.classId(head) orelse return false;
    if (cid.int() >= b.module.classes.items.len) return false;
    const cls = &b.module.classes.items[cid.int()];
    const methods = b.module.registry.hierarchy_methods.get(cls.fqn) orelse
        b.module.registry.hierarchy_methods.get(cls.name) orelse return false;
    if (methods.contains("invoke")) return false;
    return b.module.extCouldApplyWhy(b.allocator, cls.name, "invoke", argc) == .none;
}

/// The last dotted segment of a type head (`kotlin.text.StringBuilder` ->
/// `StringBuilder`), so a qualified and an unqualified spelling of the same
/// class compare equal.
fn simpleTail(h: []const u8) []const u8 {
    if (std.mem.lastIndexOfScalar(u8, h, '.')) |i| return h[i + 1 ..];
    return h;
}

fn ctorInitNonInvocable(b: *FuncBuilder, init_e: *const Expr, argc: usize) bool {
    const call = switch (init_e.*) {
        .Call => |*c| c,
        else => return false,
    };
    const path = switch (call.callee.*) {
        .Path => |*p| p,
        else => return false,
    };
    if (path.segments.len != 1) return false;
    const cls_name = path.segments[0].name;
    const cid = b.module.classId(cls_name) orelse return false;
    if (cid.int() >= b.module.classes.items.len) return false;
    const cls = &b.module.classes.items[cid.int()];
    if (cls.is_abstract) return false;
    const methods = b.module.registry.hierarchy_methods.get(cls.fqn) orelse
        b.module.registry.hierarchy_methods.get(cls.name) orelse return false;
    if (methods.contains("invoke")) return false;
    return b.module.extCouldApplyWhy(b.allocator, cls.name, "invoke", argc) == .none;
}

/// Declared parameter arity of a single lambda / anon-fun argument
/// expression, or null when it is neither. A zero-`->` `{ … }` (its `it`
/// injected by the parser) reports 0 — the literal declares no parameters,
/// so overload resolution treats it as a `() -> R` handler.
fn astArgLambdaArity(arg: *const Expr) ?u8 {
    return switch (arg.*) {
        .Lambda => |l| blk: {
            if (l.implicit_it) break :blk @as(u8, 0);
            // The compose plugin threads every composable lambda BEFORE
            // lowering, appending `($composer, $changed)`. Those are not
            // source params: overload selection must rank the literal by
            // its DECLARED header, or the +2 shift binds `{ d -> }` to a
            // 3-param overload (`movableContentOf`'s P3 form).
            var n = l.params.len;
            if (n >= 2 and std.mem.eql(u8, l.params[n - 1].name, "$changed") and
                std.mem.eql(u8, l.params[n - 2].name, "$composer"))
            {
                n -= 2;
            }
            break :blk @intCast(n);
        },
        .AnonFun => |af| @intCast(af.params.len),
        else => blk: {
            // A memo-wrapped sink lambda ranks by the inner literal's
            // declared header, exactly like the bare literal above.
            const lam = compose_pass.memoWrappedLambda(@constCast(arg)) orelse break :blk null;
            if (lam.implicit_it) break :blk @as(u8, 0);
            var n = lam.params.len;
            if (n >= 2 and std.mem.eql(u8, lam.params[n - 1].name, "$changed") and
                std.mem.eql(u8, lam.params[n - 2].name, "$composer"))
            {
                n -= 2;
            }
            break :blk @intCast(n);
        },
    };
}

/// One argument's applicability `ArgShape` at LOWERING time. Only the
/// fields lowering can prove cheaply and soundly are populated — named /
/// spread / lambda binding shape, a literal kind, and the declared-type
/// head of a plain local/param argument; `runtime_class` /
/// `lambda_param_types` / `value` stay null, so the shared scorer treats
/// the arg as UNKNOWN (base points, never disproven) wherever the type is
/// not statically decidable. Declared-type evidence is additive-only in
/// the scorer: it can promote a head-matching candidate but never
/// disqualify one.
/// Head-only `TypeRef`s for a lambda literal's ANNOTATED parameters, or null
/// when it annotates none. Only the head matters: the consumer refutes on a
/// definite mismatch and stays silent otherwise.
fn lambdaDeclaredParamTypes(b: *FuncBuilder, arg: *const Expr) ?[]const ir.TypeRef {
    if (arg.* != .Lambda) return null;
    const tys = arg.Lambda.param_tys;
    if (tys.len == 0) return null;
    var any = false;
    for (tys) |t| {
        if (t != null) any = true;
    }
    if (!any) return null;
    const out = b.allocator.alloc(ir.TypeRef, tys.len) catch return null;
    for (tys, out) |t, *o| {
        o.* = if (t) |ast_ty|
            .{ .name = ast_ty.name.name, .nullable = ast_ty.nullable, .args = &.{} }
        else
            .{ .name = "", .nullable = false, .args = &.{} };
    }
    return out;
}

fn shapeOfAstArg(b: *FuncBuilder, arg: *const Expr, name: ?[]const u8) applicability.ArgShape {
    const lazy_ty = argDeclTypeRefLazy(b, arg);
    const ty = argDeclTypeRef(b, arg);
    const declared_fn_arity = if (ty) |t| fnTypeArityAlias(b, t) else null;
    // A memo-wrapped sink lambda is the trailing functional argument for
    // overload selection — the wrap is transparent to the shape.
    const literal_callable = arg.* == .Lambda or arg.* == .AnonFun or
        compose_pass.memoWrappedLambda(@constCast(arg)) != null;
    const sh: applicability.ArgShape = .{
        .named = name,
        .is_spread = arg.* == .Spread,
        .is_null = arg.* == .NullLit,
        .is_lambda = literal_callable or declared_fn_arity != null,
        .lambda_arity = astArgLambdaArity(arg) orelse if (declared_fn_arity) |n| @intCast(n) else null,
        .func_typed = declared_fn_arity != null,
        .lambda_is_literal = literal_callable,
        .literal_kind = if (argEvidenceLitKind(b, arg)) |k| switch (k) {
            .numeric => .numeric,
            .string => .string,
            .boolean => .boolean,
            .char => .char,
        } else null,
        .ty = ty,
        .ty_authoritative = lazy_ty != null,
        // Explicitly annotated lambda parameters are programmer-stated types,
        // and kotlinc drops a candidate whose function parameter cannot accept
        // them.
        .lambda_param_types = lambdaDeclaredParamTypes(b, arg),
    };
    if (runtime.envSetOnce("KLIO_ARGSHAPE_UNK") and
        sh.ty == null and sh.literal_kind == null and !sh.is_lambda)
    {
        noteUnknownArgShape("argshape-unk", arg);
    }
    return sh;
}

/// Diagnostic: which argument SHAPES stay unknown to the applicability
/// scorer (no type, no literal kind, not callable). Those are the shapes
/// that make `memberPromotionProven` answer `arg-unauthoritative`, so the
/// tag histogram names the expression forms worth typing next.
fn noteUnknownArgShape(tag: []const u8, arg: *const Expr) void {
    const detail: []const u8 = switch (arg.*) {
        .Path => |p| if (p.segments.len != 0) p.segments[p.segments.len - 1].name else "-",
        .Member => |m| m.name.name,
        .Call => |c| if (c.callee.* == .Member) c.callee.Member.name.name else if (c.callee.* == .Path and c.callee.Path.segments.len != 0) c.callee.Path.segments[c.callee.Path.segments.len - 1].name else "-",
        .Binary => |bin| @tagName(bin.op),
        else => "-",
    };
    std.debug.print("[{s}] {s} {s}\n", .{ tag, @tagName(arg.*), detail });
}

/// Literal-kind evidence for an argument: the argument itself is a literal,
/// or it names a local whose recorded initializer is one (`val x = 1.0;
/// f(x)`). Evidence only, never disproving.
fn argEvidenceLitKind(b: *FuncBuilder, arg: *const Expr) ?LitKind {
    if (argLitKind(arg)) |k| return k;
    if (arg.* == .Path and arg.Path.segments.len == 1) {
        if (b.localInitExpr(arg.Path.segments[0].name)) |init_e| {
            return argLitKind(init_e);
        }
    }
    return null;
}

/// Declared-type head of a single-segment Path argument naming a local /
/// parameter whose declared type is known (`b.localDeclType`), as a `TypeRef`
/// for the shared scorer's declared-type evidence. Null for anything else.
/// An `if (x is T)` condition over a bare name smart-casts `x` to `T` for the
/// then-arm. Kotlin resolves extensions against the STATIC type, and lowering
/// hands the receiver's declared head to the extension filter, so without the
/// narrowing the declared head (`Any?`) refutes every `CharSequence` extension
/// and `x.isEmpty()` misses. A negated check narrows nothing here (its
/// information is on the else path).
/// Every smart cast a condition proves for its TRUE branch. Kotlin narrows on
/// each `is` check in an `&&` chain, not only on a condition that is itself an
/// `is` check: `if (!ignoreCase && this is String && prefix is String)` narrows
/// both. Without walking the chain, `CharSequence.startsWith` resolved its own
/// `this.startsWith(prefix)` — written under exactly that guard — back to the
/// CharSequence extension instead of `String.startsWith`, and recursed until
/// the stack ran out.
///
/// Applied in source order; the caller restores in reverse, because each
/// narrowing saves the binding the previous one left.
pub fn narrowIsCheckAll(
    b: *FuncBuilder,
    cond: *const Expr,
    out: *std.ArrayList(build.FuncBuilder.NarrowedLocal),
) Allocator.Error!void {
    if (cond.* == .Binary and cond.Binary.op == .And) {
        try narrowIsCheckAll(b, cond.Binary.lhs, out);
        try narrowIsCheckAll(b, cond.Binary.rhs, out);
        return;
    }
    if (try narrowIsCheck(b, cond)) |n| try out.append(b.allocator, n);
}

pub fn narrowIsCheck(b: *FuncBuilder, cond: *const Expr) Allocator.Error!?build.FuncBuilder.NarrowedLocal {
    if (cond.* != .IsCheck) return null;
    const ck = cond.IsCheck;
    if (ck.negated) return null;
    const head = loweredCheckTypeName(b, &ck.ty);
    if (head.len == 0) return null;
    if (ck.expr.* == .Path and ck.expr.Path.segments.len == 1) {
        return try b.narrowLocal(ck.expr.Path.segments[0].name, head);
    }
    if (ck.expr.* == .This and ck.expr.This.qualifier == null) {
        return try b.narrowLocal("this", head);
    }
    return null;
}

/// Every non-null narrowing a condition proves for the branch it guards.
/// Kotlin narrows on each `!= null` in an `&&` chain, exactly as it does for
/// each `is` check — `if (a != null && b != null)` narrows both — and on each
/// `== null` in an `||` chain for the ELSE branch. Only a condition that was
/// itself the whole check narrowed anything, so the common guarded shape got
/// no narrowing at all and its member calls stayed off the static path.
///
/// Applied in source order; the caller restores in reverse, because each
/// narrowing saves the binding the previous one left.
pub fn narrowNullCheckAll(
    b: *FuncBuilder,
    cond: *const Expr,
    truthy: bool,
    out: *std.ArrayList(build.FuncBuilder.NarrowedLocal),
) Allocator.Error!void {
    if (cond.* == .Binary and
        !std.mem.eql(u8, runtime.envOnce("KLIO_NULL_CHAIN") orelse "1", "0"))
    {
        const op = cond.Binary.op;
        if ((truthy and op == .And) or (!truthy and op == .Or)) {
            try narrowNullCheckAll(b, cond.Binary.lhs, truthy, out);
            try narrowNullCheckAll(b, cond.Binary.rhs, truthy, out);
            return;
        }
    }
    if (try narrowNullCheck(b, cond, truthy)) |n| try out.append(b.allocator, n);
}

fn narrowNullCheck(
    b: *FuncBuilder,
    cond: *const Expr,
    truthy: bool,
) Allocator.Error!?build.FuncBuilder.NarrowedLocal {
    if (cond.* != .Binary) return null;
    const binary = cond.Binary;
    const unequal = binary.op == .Neq or binary.op == .IdentNeq;
    const equal = binary.op == .Eq or binary.op == .IdentEq;
    if (!(if (truthy) unequal else equal)) return null;
    const value = if (binary.lhs.* == .NullLit)
        binary.rhs
    else if (binary.rhs.* == .NullLit)
        binary.lhs
    else
        return null;
    if (value.* != .Path or value.Path.segments.len != 1) return null;
    return b.narrowLocalNotNull(value.Path.segments[0].name);
}

fn argDeclTypeRef(b: *FuncBuilder, arg: *const Expr) ?ir.TypeRef {
    if (runtime.envOnce("KLIO_VALTY_TRACE")) |w| {
        if (arg.* == .Path and arg.Path.segments.len == 1 and std.mem.eql(u8, arg.Path.segments[0].name, w)) {
            std.debug.print("[valty] READ {s} decl={s} b={x} fn={s} ndecl={d}\n", .{ w, if (b.localDeclTypeRef(w)) |t| t.name else "<unset>", @intFromPtr(b) & 0xffff, build.currentRealFn() orelse "-", b.localDeclTypeCount() });
        }
    }
    // The E2.1 type-head channel exists (Module.eagerTypeOf) but does
    // NOT feed evidence yet: typeck's permissive inference can hand back
    // a wrong container head (a ByteArray value typed Iterable), and a
    // wrong head DISPROVES valid candidates downstream. The seam flips
    // only after the type-head audit below reaches zero disagreement,
    // mirroring the call channel's per-class trust discipline.
    var lazy_ans = argDeclTypeRefLazy(b, arg);
    // E2.1, ADDITIVE-ONLY: typeck's head fills in where the AST probes
    // have no answer; the declared (AST) answer always wins when both
    // exist — kotlinc resolves overloads against the STATIC DECLARED
    // type, and the audit shows the only both-exist deltas are the
    // legitimate declared-wider-vs-inferred-narrower class.
    if (lazy_ans == null) {
        if (b.module.eagerTypeOf(arg.span())) |th| {
            // `EagerTypeHead` carries a head and nullability, no type
            // ARGUMENTS. For a generic type that makes the answer worse than
            // none: extension selection needs the element type to choose
            // between `Iterable<T>.minOrNull` (total order) and
            // `Iterable<Double>.minOrNull` (IEEE), and a head-only `List`
            // disproves the generic candidate that a null receiver type would
            // have found by the broader walk. Measured: with the head,
            // `minOrNull` on Array/List/Sequence resolves to target=null and
            // falls to runtime dispatch, which picks the IEEE overload and
            // returns NaN where 0.0 is correct.
            const th_head = typeHead(std.mem.trimEnd(u8, th.name, "?"));
            const bare_tp_head = (th_head.len > 0 and th_head.len <= 2 and std.ascii.isUpper(th_head[0])) or
                b.isTypeParam(th_head) or ir.parseClassTypeParamIdentity(th_head) != null;
            if (headDeclaresTypeParams(b, th.name) or bare_tp_head) {
                // A bare TYPE-PARAMETER answer (`expected: T` read on a
                // typed receiver) blocks the substituting deriver behind
                // it, which would answer the instantiated type.
                if (typeheadAuditOn()) {
                    const sp = arg.span();
                    std.debug.print("[TYPEHEAD-SKIP] f{d}:{d} generic head {s} has no args\n", .{ sp.file.int(), sp.start, th.name });
                }
            } else {
                if (typeheadAuditOn()) {
                    const sp = arg.span();
                    std.debug.print("[TYPEHEAD-FILL] f{d}:{d} typeck={s}{s}\n", .{ sp.file.int(), sp.start, th.name, if (th.nullable) @as([]const u8, "?") else "" });
                }
                lazy_ans = .{ .name = th.name, .nullable = th.nullable, .args = &.{} };
            }
        }
    }
    // `KLIO_ARGTY_TRACE=<name>` — the static type this resolution actually
    // used for a named expression, and whether it came from an inline
    // splice's declared parameter type. This is what separates "lowering has
    // no type" from "lowering has the wrong type", which look identical from
    // a failing test.
    if (runtime.envOnce("KLIO_ARGTY_TRACE")) |w| {
        if (arg.* == .Path and arg.Path.segments.len == 1 and std.mem.eql(u8, arg.Path.segments[0].name, w)) {
            if (lazy_ans) |la| {
                std.debug.print("[argty] {s} -> {s} args={d} splice_ty={}\n", .{ w, la.name, la.args.len, b.spliceParamTy(w) != null });
            } else std.debug.print("[argty] {s} -> <none>\n", .{w});
        }
    }
    if (typeheadAuditOn()) {
        if (b.module.eagerTypeOf(arg.span())) |th| {
            if (lazy_ans) |la| {
                if (!std.mem.eql(u8, la.name, th.name) or la.nullable != th.nullable) {
                    const sp = arg.span();
                    std.debug.print("[TYPEHEAD-AUDIT] f{d}:{d} ast={s}{s} typeck={s}{s}\n", .{
                        sp.file.int(), sp.start,
                        la.name,       if (la.nullable) @as([]const u8, "?") else "",
                        th.name,       if (th.nullable) @as([]const u8, "?") else "",
                    });
                }
            }
        }
    }
    return lazy_ans;
}

fn typeheadAuditOn() bool {
    const S = struct {
        var cached: ?bool = null;
    };
    if (S.cached) |v| return v;
    const on = runtime.envOnce("KLIO_TYPEHEAD_AUDIT") != null;
    S.cached = on;
    return on;
}

/// Whether the class named by an eager type HEAD declares type parameters,
/// in which case a head without arguments is incomplete evidence. Builtin
/// container heads are listed explicitly: they are not user classes, so the
/// class table cannot answer for them.
fn headDeclaresTypeParams(b: *FuncBuilder, head: []const u8) bool {
    const generic_builtins = [_][]const u8{
        "Array",           "List",                    "MutableList", "Set",               "MutableSet",
        "Map",             "MutableMap",              "Collection",  "MutableCollection", "Iterable",
        "MutableIterable", "Sequence",                "Iterator",    "MutableIterator",   "Comparable",
        "Comparator",      "Pair",                    "Triple",      "Lazy",              "Result",
        "Map.Entry",       "MutableMap.MutableEntry",
    };
    for (generic_builtins) |g| {
        if (std.mem.eql(u8, g, head)) return true;
    }
    const cid = if (std.mem.indexOfScalar(u8, head, '.') != null)
        b.module.classIdByFqn(head)
    else
        b.module.uniqueClassIdBySimpleName(head);
    if (cid) |id| {
        if (id.int() < b.module.classes.items.len) {
            return b.module.classes.items[id.int()].type_params.len != 0;
        }
    }
    return false;
}

pub fn argDeclTypeRefLazy(b: *FuncBuilder, arg: *const Expr) ?ir.TypeRef {
    if (lazyMemoGet(b, arg)) |hit| return hit.ty;
    const owns = tyMemoEnter(b);
    const r = argDeclTypeRefLazyUncached(b, arg);
    lazyMemoLeave(b, owns, arg, r);
    return r;
}

/// A bare name that denotes an `object` declaration visible from this
/// scope (the enclosing class's nested object first, then the indexed
/// top-level one) types as that object's class.
pub fn objectRefTypeRef(b: *FuncBuilder, arg: *const Expr) ?ir.TypeRef {
    if (arg.* != .Path or arg.Path.segments.len != 1) return null;
    const seg = arg.Path.segments[0];
    const nm = seg.name;
    if (nm.len == 0 or !std.ascii.isUpper(nm[0])) return null;
    const tr = runtime.envOnce("KLIO_SIBEXP_TRACE") != null;
    if (tr) std.debug.print("[objref] {s} resolve={} outer={} param={} decl={} owner={?s} cur={?s}\n", .{ nm, b.resolve(nm) != null, b.knowsOuter(nm), b.isParam(nm), b.localDeclTypeRef(nm) != null, b.ownerClass(), build.currentOwnerClass() });
    if (b.resolve(nm) != null or b.knowsOuter(nm) or b.isParam(nm)) return null;
    if (b.localDeclTypeRef(nm) != null) return null;
    var cid: ?ir.ClassId = null;
    var owner = b.ownerClass() orelse build.currentOwnerClass();
    var hops: usize = 0;
    while (owner) |o| : (hops += 1) {
        if (hops > 16) break;
        var qb: [192]u8 = undefined;
        if (std.fmt.bufPrint(&qb, "{s}.{s}", .{ o, nm }) catch null) |qualified| {
            if (b.module.classIdByQualifiedSuffix(qualified)) |n| {
                cid = n;
                break;
            }
        }
        if (b.module.classIdIndexed(o, b.self_package, seg.span.file) orelse b.module.classId(o)) |oid| {
            if (b.module.classIdNestedIn(oid, nm)) |n| {
                cid = n;
                break;
            }
        }
        owner = b.module.registry.enclosing_class.get(o);
    }
    if (cid == null) cid = b.module.classIdIndexed(nm, b.self_package, seg.span.file);
    const id = cid orelse {
        if (tr) std.debug.print("[objref] {s} no class\n", .{nm});
        return null;
    };
    if (id.int() >= b.module.classes.items.len) return null;
    const cls = &b.module.classes.items[id.int()];
    if (tr) std.debug.print("[objref] {s} -> {s} object={}\n", .{ nm, cls.name, cls.is_object });
    if (!cls.is_object) return null;
    return .{ .name = cls.name, .nullable = false, .args = &.{} };
}

fn argDeclTypeRefLazyUncached(b: *FuncBuilder, arg: *const Expr) ?ir.TypeRef {
    if (runtime.envOnce("KLIO_VALTY_TRACE")) |w| {
        if (arg.* == .Path and arg.Path.segments.len == 1 and std.mem.eql(u8, arg.Path.segments[0].name, w)) {
            std.debug.print("[valty] LAZY {s} decl={s} splice={} lsr={}\n", .{ w, if (b.localDeclTypeRef(w)) |t| t.name else "<unset>", b.spliceParamTy(w) != null, b.lambda_splice_resolve != null });
        }
    }
    if (arg.* == .This and arg.This.qualifier == null) {
        // An extension body spliced into a member function binds a new `this`
        // register while the builder's flat declaration metadata still names
        // the enclosing member receiver. The splice receiver is the lexical
        // `this` for this body and must win. A spliced lambda argument skips
        // it because that lambda's receiver/free-name window is independent.
        if (b.lambda_splice_resolve == null) {
            // The window's full receiver record wins over the head-only
            // channel: iterating `this` needs the type arguments.
            if (b.spliceRecvTyRef()) |ref| return ref.*;
            if (b.spliceRecvTy()) |head| {
                return .{ .name = head, .nullable = false, .args = &.{} };
            }
        }
        if (b.localDeclTypeRef("this")) |narrowed| return narrowed;
        if (b.recvTypeRef()) |receiver| return receiver;
        if (b.enclosingRecvTy()) |head| {
            return .{ .name = head, .nullable = false, .args = &.{} };
        }
        return null;
    }
    // `this@label`: the receiver bound under that label — the builder's own
    // receiver when its label matches (an ext body's label is its fn name),
    // else the tower entry carrying it. `this@runningReduce.iterator()`
    // inside the `sequence { }` body types as the OUTER Sequence receiver.
    if (arg.* == .This) {
        if (arg.This.qualifier) |q| {
            if (b.own_this_label) |own| {
                if (std.mem.eql(u8, own, q.name)) {
                    if (b.recvTypeRef()) |receiver| return receiver;
                    if (b.recvTy()) |head| return .{ .name = head, .nullable = false, .args = &.{} };
                }
            }
            for (b.implicit_receiver_tower.items) |entry| {
                const label = entry.label orelse continue;
                if (std.mem.eql(u8, label, q.name)) {
                    return .{ .name = entry.head, .nullable = false, .args = &.{} };
                }
            }
        }
        return null;
    }
    switch (arg.*) {
        .IntLit => |lit| return .{
            .name = switch (lit.kind) {
                .Int => if (lit.value >= std.math.minInt(i32) and
                    lit.value <= std.math.maxInt(i32)) "Int" else "Long",
                .Long => "Long",
                .UInt => "UInt",
                .ULong => "ULong",
            },
            .nullable = false,
            .args = &.{},
        },
        .FloatLit => |lit| return .{
            .name = if (lit.kind == .Float) "Float" else "Double",
            .nullable = false,
            .args = &.{},
        },
        .BoolLit => return .{ .name = "Boolean", .nullable = false, .args = &.{} },
        .CharLit => return .{ .name = "Char", .nullable = false, .args = &.{} },
        .StringTemplate => return .{ .name = "String", .nullable = false, .args = &.{} },
        .NullLit => return .{ .name = "Nothing", .nullable = true, .args = &.{} },
        else => {},
    }
    // An unsafe cast fixes the argument's static type for overload
    // resolution — kotlinc sees exactly the cast target. That is the
    // documented way to force a sibling overload (ktor's deprecated
    // `P.install` delegates with `install(plugin as Plugin<P, B, F>,
    // configure)`; without the cast evidence the call binds itself and
    // recurses forever).
    if (arg.* == .As and !arg.As.safe) {
        return .{ .name = loweredTypeName(b, &arg.As.ty), .nullable = arg.As.ty.nullable, .args = &.{} };
    }
    // A member PROPERTY READ as a receiver (`this.indices.reversed()`):
    // the receiver's head plus the property's declared head answers —
    // class properties through their recorded heads, extension
    // properties through the getter contract and its supertype walk.
    if (arg.* == .Member and !arg.Member.safe) {
        const m = arg.Member;
        // A CLASS-named receiver reads the companion's property
        // (`Byte.MAX_VALUE.toLong()`): consult the companion's lifted key
        // and the class's own record.
        if (m.receiver.* == .Path and m.receiver.Path.segments.len == 1) {
            const on = m.receiver.Path.segments[0].name;
            if (on.len != 0 and std.ascii.isUpper(on[0]) and
                b.resolve(on) == null and b.module.classId(on) != null)
            {
                var cb2: [96]u8 = undefined;
                if (std.fmt.bufPrint(&cb2, "{s}$Companion", .{on}) catch null) |ck2| {
                    if (b.module.registry.class_prop_type_heads.get(.{ .a = ck2, .b = m.name.name })) |head| {
                        return .{ .name = head, .nullable = false, .args = &.{} };
                    }
                }
                if (b.module.registry.class_prop_type_heads.get(.{ .a = on, .b = m.name.name })) |head| {
                    return .{ .name = head, .nullable = false, .args = &.{} };
                }
            }
        }
        // An enum ENTRY (`AlternateEnumNames.VALUE_A`, `Cases.hasSerialName`)
        // is a value of its enum class, nested enums included: a reified
        // sibling beside it (`assertEquals(E.A, json.decodeFromString(...))`)
        // solves `T` as the enum.
        if (m.receiver.* == .Path and !std.mem.eql(u8, m.name.name, "entries")) {
            if (enumClassOfPath(b, m.receiver)) |enum_name| {
                return .{ .name = enum_name, .nullable = false, .args = &.{} };
            }
        }
        if (argDeclTypeRefLazy(b, m.receiver)) |rt| {
            var h = std.mem.trimEnd(u8, rt.name, "?");
            if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
            const head = typeHead(h);
            // The property's FULL declared type, with the owner's type
            // parameters substituted from the receiver's own arguments:
            // `Map<K, V>.values` read off a `Map<String, Named>` is a
            // `Collection<Named>`, and iterating it needs the element.
            if (propTypeRefOn(b, head, m.name.name)) |declared| {
                if (substitutedPropType(b, head, rt, declared)) |full| return full;
            }
            if (propTypeHeadOn(b, head, m.name.name) orelse
                extPropReturnHead(b, head, m.name.name)) |ph|
            {
                return .{ .name = ph, .nullable = false, .args = &.{} };
            }
            // Builtin properties with no Kotlin declaration to read.
            // `source[index].code` in Base64's decoder is the live case: the
            // receiver types as Char and the read stopped there.
            if (std.mem.eql(u8, head, "Char") and std.mem.eql(u8, m.name.name, "code")) {
                return .{ .name = "Int", .nullable = false, .args = &.{} };
            }
        }
    }
    // `x++` / `x--` evaluates to the operand's PRIOR value, so it carries the
    // operand's type. The inline splice types a lambda parameter from the
    // argument expression, and half the indexed stdlib family invokes its
    // lambda that way — `action(index++, item)` inside
    // `CharSequence.forEachIndexed` — so the parameter arrived untyped and
    // every call on it resolved by name.
    if (arg.* == .Postfix) return argDeclTypeRefLazy(b, arg.Postfix.expr);
    // `!x` is Boolean; `-x` / `+x` keep their operand's type. Same reason as
    // the postfix arm: these are argument shapes the splice must type.
    if (arg.* == .Unary) {
        switch (arg.Unary.op) {
            .Not => return .{ .name = "Boolean", .nullable = false, .args = &.{} },
            .Neg, .Pos => return argDeclTypeRefLazy(b, arg.Unary.expr),
            else => {},
        }
    }
    // Arithmetic on PRIMITIVES promotes to the wider operand, and comparison
    // and logic are Boolean. Both rules already exist for the eager walk;
    // the splice consults this function instead and had neither.
    if (arg.* == .Binary) {
        switch (arg.Binary.op) {
            .Eq, .Neq, .IdentEq, .IdentNeq, .Lt, .Le, .Gt, .Ge, .In, .NotIn, .And, .Or => {
                return .{ .name = "Boolean", .nullable = false, .args = &.{} };
            },
            .Add, .Sub, .Mul, .Div, .Rem => arith: {
                // Falls THROUGH on anything it cannot answer: the class
                // operator-member arm below handles a non-primitive left
                // operand, and returning null here would skip it.
                const lt = argDeclTypeRefLazy(b, arg.Binary.lhs) orelse
                    break :arith;
                const rt = argDeclTypeRefLazy(b, arg.Binary.rhs) orelse
                    break :arith;
                if (lt.nullable or rt.nullable) break :arith;
                const lh = typeHead(std.mem.trimEnd(u8, lt.name, "?"));
                const rh = typeHead(std.mem.trimEnd(u8, rt.name, "?"));
                if (!isPrimitiveTypeName(lh) or !isPrimitiveTypeName(rh)) break :arith;
                // Kotlin's numeric promotion order. A String on either side
                // is concatenation, and `Char + Int` is a Char; neither is
                // in this table, so both decline.
                // Kotlin's UNSIGNED arithmetic is a closed family: it never
                // mixes with the signed types, `UByte`/`UShort` widen to
                // `UInt`, and a `ULong` operand makes the result `ULong`.
                // Absent from the signed table below, `(to - 1u).toUInt()`
                // inside `UInt.until` had no receiver at all.
                const unsigned = [_][]const u8{ "UByte", "UShort", "UInt", "ULong" };
                var l_unsigned = false;
                var r_unsigned = false;
                for (unsigned) |un| {
                    if (std.mem.eql(u8, lh, un)) l_unsigned = true;
                    if (std.mem.eql(u8, rh, un)) r_unsigned = true;
                }
                if (l_unsigned != r_unsigned) break :arith;
                if (l_unsigned) {
                    const w: []const u8 = if (std.mem.eql(u8, lh, "ULong") or
                        std.mem.eql(u8, rh, "ULong")) "ULong" else "UInt";
                    return .{ .name = w, .nullable = false, .args = &.{} };
                }
                const order = [_][]const u8{ "Double", "Float", "Long", "Int" };
                for (order) |w| {
                    if (std.mem.eql(u8, lh, w) or std.mem.eql(u8, rh, w)) {
                        // Byte/Short arithmetic is Int in Kotlin, which the
                        // Int entry already produces.
                        return .{ .name = w, .nullable = false, .args = &.{} };
                    }
                }
                const small = [_][]const u8{ "Byte", "Short" };
                for (small) |sm| {
                    if (std.mem.eql(u8, lh, sm) and std.mem.eql(u8, rh, sm)) {
                        return .{ .name = "Int", .nullable = false, .args = &.{} };
                    }
                }
            },
            else => {},
        }
    }
    // `a..b` is a range whose class follows from its endpoints. Named here
    // because the range CLASSES exist (`IntRange`, `CharRange`, …) while the
    // operator producing them is builtin with no declaration to read.
    if (arg.* == .Binary and arg.Binary.op == .Range) {
        if (argDeclTypeRefLazy(b, arg.Binary.lhs)) |lt| {
            if (!lt.nullable) {
                const lh = typeHead(std.mem.trimEnd(u8, lt.name, "?"));
                const ranges = [_]struct { e: []const u8, r: []const u8 }{
                    .{ .e = "Int", .r = "IntRange" },     .{ .e = "Long", .r = "LongRange" },
                    .{ .e = "Char", .r = "CharRange" },   .{ .e = "UInt", .r = "UIntRange" },
                    .{ .e = "ULong", .r = "ULongRange" },
                };
                for (ranges) |rr| {
                    if (std.mem.eql(u8, lh, rr.e)) {
                        return .{ .name = rr.r, .nullable = false, .args = &.{} };
                    }
                }
            }
        }
    }
    // `a / b` on a CLASS is an operator member, and its declared return is
    // the answer: `val half = duration / 2` in the saturating-math helpers
    // types `half` as Duration. The arithmetic arm beside this one promotes
    // NUMERIC operands and declines everything else, so a class receiver
    // reached no channel at all.
    if (arg.* == .Binary) {
        const opname: ?[]const u8 = switch (arg.Binary.op) {
            .Add => "plus",
            .Sub => "minus",
            .Mul => "times",
            .Div => "div",
            .Rem => "rem",
            else => null,
        };
        if (opname) |on| {
            if (argDeclTypeRefLazy(b, arg.Binary.lhs)) |lt| {
                if (!lt.nullable) {
                    var identity = std.mem.trimEnd(u8, lt.name, "?");
                    if (std.mem.indexOfScalar(u8, identity, '<')) |ltp| identity = identity[0..ltp];
                    const lh = typeHead(identity);
                    if (lh.len != 0 and !isPrimitiveTypeName(lh)) {
                        // The operator member is chosen by the SAME engine that
                        // dispatches it, with the rhs's own static type as the
                        // argument evidence. A name+arity shortcut is wrong the
                        // moment overloads diverge on return type
                        // (`ValueTimeMark.minus(Duration): ValueTimeMark` vs
                        // `minus(ValueTimeMark): Duration`); an unresolvable
                        // overload set stays untyped rather than guessing.
                        const owner_id = if (std.mem.indexOfScalar(u8, identity, '.') != null)
                            b.module.classIdByFqn(identity)
                        else
                            b.module.uniqueClassIdBySimpleName(lh);
                        if (owner_id) |owner| {
                            const rhs_ty = argDeclTypeRefLazy(b, arg.Binary.rhs);
                            const shape = applicability.ArgShape{
                                .ty = rhs_ty,
                                .ty_authoritative = rhs_ty != null,
                            };
                            const resolved = b.module.resolveMemberCall(owner, on, &.{shape}, .{
                                .caller_file = arg.Binary.span.file,
                                .lexical_owner = null,
                                .receiver_type = lt,
                            });
                            if (resolved.target) |fid| {
                                if (b.module.funcById(fid)) |f| {
                                    if (f.return_ty_declared and f.return_ty.name.len != 0) {
                                        return .{
                                            .name = f.return_ty.name,
                                            .nullable = f.return_ty.nullable,
                                            .args = &.{},
                                        };
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    // `xs[i]` — the element of what `xs` indexes. Stated for the shapes that
    // have no declaration to read (a CharSequence's Char, a primitive
    // array's scalar) and taken from the sole type argument otherwise.
    if (arg.* == .Index and arg.Index.args.len == 1) {
        if (argDeclTypeRefLazy(b, arg.Index.receiver)) |rt| {
            if (!rt.nullable) {
                const h = typeHead(std.mem.trimEnd(u8, rt.name, "?"));
                if (std.mem.eql(u8, h, "CharSequence") or std.mem.eql(u8, h, "String") or
                    std.mem.eql(u8, h, "StringBuilder"))
                {
                    return .{ .name = "Char", .nullable = false, .args = &.{} };
                }
                const prim = [_]struct { a: []const u8, e: []const u8 }{
                    .{ .a = "BooleanArray", .e = "Boolean" }, .{ .a = "ByteArray", .e = "Byte" },
                    .{ .a = "ShortArray", .e = "Short" },     .{ .a = "IntArray", .e = "Int" },
                    .{ .a = "LongArray", .e = "Long" },       .{ .a = "CharArray", .e = "Char" },
                    .{ .a = "FloatArray", .e = "Float" },     .{ .a = "DoubleArray", .e = "Double" },
                    .{ .a = "UByteArray", .e = "UByte" },     .{ .a = "UShortArray", .e = "UShort" },
                    .{ .a = "UIntArray", .e = "UInt" },       .{ .a = "ULongArray", .e = "ULong" },
                };
                for (prim) |pa| {
                    if (std.mem.eql(u8, h, pa.a)) {
                        return .{ .name = pa.e, .nullable = false, .args = &.{} };
                    }
                }
            }
        }
    }
    if (arg.* == .Call and arg.Call.callee.* == .Path and arg.Call.callee.Path.segments.len == 1) {
        const seg = arg.Call.callee.Path.segments[0];
        if (b.localCallReturn(seg.name)) |ret| {
            return .{ .name = ret.name, .nullable = ret.nullable, .args = &.{} };
        }
        // A unique concrete classifier with no same-named plain function is
        // a constructor call, so its result head is statically authoritative.
        // The conservative function gate leaves factory/class collisions for
        // the ordinary call resolver instead of inventing a receiver type.
        if (b.resolve(seg.name) == null and !b.isLocalFn(seg.name) and
            !enclosingHasMemberNamed(b, seg.name))
        {
            var same_named_function = false;
            for (b.module.funcsBySimpleName(seg.name)) |fid| {
                const f = b.module.funcById(fid) orelse continue;
                if (f.kind == .plain and
                    (f.hasBody() or b.module.decl_ast_body.contains(fid.int())))
                {
                    same_named_function = true;
                    break;
                }
            }
            if (!same_named_function) {
                const pkg = b.module.packageOfFile(seg.span.file) orelse b.self_package;
                if (b.module.classIdIndexed(seg.name, pkg, seg.span.file)) |cid| {
                    if (cid.int() < b.module.classes.items.len) {
                        const class = &b.module.classes.items[cid.int()];
                        if (!class.is_object and !class.is_interface and !class.is_abstract) {
                            const type_args = b.allocator.alloc(
                                ir.TypeRef,
                                arg.Call.type_args.len,
                            ) catch return null;
                            for (arg.Call.type_args, type_args) |*ast_ty, *out| {
                                out.* = decl_mod.loweredTypeRef(
                                    b.allocator,
                                    ast_ty,
                                    true,
                                ) catch return null;
                            }
                            return .{
                                .name = class.fqn,
                                .nullable = false,
                                .args = type_args,
                            };
                        }
                    }
                }
            }
        }
    }
    // A qualified object/class property read (`Nodes.Traversable`, parsed
    // as a Member access on a bare class-name receiver): the registered
    // per-class property type head is the argument's static type —
    // `visitAncestors(Nodes.Traversable) { }` must resolve against
    // `NodeKind`, not bind the sibling `(mask: Int, ...)` overload.
    if (arg.* == .Member) {
        const recv = arg.Member.receiver;
        // A SAFE read reaches its property through a nullable receiver and
        // yields a nullable result: look the property up on the non-null
        // owner and hand the `?` back. A plain read of a nullable receiver
        // does not type-check at all, so it keeps declining.
        const safe_read = arg.Member.safe;
        if (recv.* == .Path and recv.Path.segments.len == 1) {
            const owner = recv.Path.segments[0].name;
            if (owner.len != 0 and std.ascii.isUpper(owner[0]) and
                b.resolve(owner) == null and b.module.classId(owner) != null)
            {
                if (b.module.registry.class_prop_type_heads.get(.{ .a = owner, .b = arg.Member.name.name })) |head| {
                    return .{ .name = head, .nullable = safe_read, .args = &.{} };
                }
            }
        }
        // Resolve each property segment from its receiver's declared type so
        // the final member call can use the shared declaration resolver. A
        // receiver that is itself a CALL has no declared type to read; its
        // resolved return is the same fact one step further along the chain.
        var owned_recv: ?ir.TypeRef = null;
        defer if (owned_recv) |*t| t.deinit(b.allocator);
        const recv_ty_opt: ?ir.TypeRef = argDeclTypeRefLazy(b, recv) orelse blk: {
            if (recv.* != .Call) break :blk null;
            owned_recv = (staticCallReturnTypeRef(b, recv) catch null) orelse break :blk null;
            break :blk owned_recv;
        };
        if (recv_ty_opt) |receiver_ty| {
            if (receiver_ty.nullable and !safe_read) return null;
            const owner = typeHead(std.mem.trimEnd(u8, receiver_ty.name, "?"));
            const heads = b.module.registry.class_prop_type_heads;
            if (heads.get(.{ .a = owner, .b = arg.Member.name.name })) |head| {
                return .{ .name = head, .nullable = safe_read, .args = &.{} };
            }
            const chain: []const []const u8 =
                b.module.registry.class_super_names.get(owner) orelse &.{};
            for (chain) |super_name| {
                if (heads.get(.{ .a = super_name, .b = arg.Member.name.name })) |head| {
                    return .{ .name = head, .nullable = safe_read, .args = &.{} };
                }
            }
        }
        return null;
    }
    if (arg.* != .Path) return null;
    const p = arg.Path;
    // Same qualified property-read evidence for the two-segment Path form.
    if (p.segments.len == 2) {
        const owner = p.segments[0].name;
        if (owner.len != 0 and std.ascii.isUpper(owner[0]) and
            b.resolve(owner) == null and b.module.classId(owner) != null)
        {
            if (b.module.registry.class_prop_type_heads.get(.{ .a = owner, .b = p.segments[1].name })) |head| {
                return .{ .name = head, .nullable = false, .args = &.{} };
            }
            // A class-named access reads the COMPANION's property
            // (`Byte.MAX_VALUE.toLong()`): the head is recorded under the
            // companion's lifted name.
            var cb: [96]u8 = undefined;
            if (std.fmt.bufPrint(&cb, "{s}$Companion", .{owner}) catch null) |ck| {
                if (b.module.registry.class_prop_type_heads.get(.{ .a = ck, .b = p.segments[1].name })) |head| {
                    return .{ .name = head, .nullable = false, .args = &.{} };
                }
            }
        }
        return null;
    }
    if (p.segments.len != 1) return null;
    // An inlined function's parameters live in the caller builder, but their
    // declared types belong to the spliced declaration rather than the
    // caller's local-declaration table. Keep that source type as static
    // applicability evidence while lowering the inline body. A spliced
    // lambda argument deliberately skips this channel: its free names resolve
    // in the caller scopes and may shadow a same-named inline parameter.
    if (b.lambda_splice_resolve == null or
        (b.resolve(p.segments[0].name) == null and
            !b.knowsOuter(p.segments[0].name)))
    {
        // The spliced-caller-lambda skip exists for CALLER names that
        // shadow an inline parameter. A name the caller WINDOW cannot see
        // at all (`destination.append` inside filterIndexedTo's predicate
        // splice — the window deliberately skips the inline fn's own
        // scopes) can only mean the spliced parameter, so its declared
        // source type stays as evidence.
        if (b.spliceParamTy(p.segments[0].name)) |declared| {
            if (declared.function == null) {
                // A declared head that is itself a TYPE PARAMETER of the
                // spliced declaration (`destination: M`) names nothing the
                // receiving scope can bind; the entry records the
                // ARGUMENT's derived type under the local-decl channel
                // below, and that concrete head must win.
                const dh = declared.name.name;
                const tp_head = ((dh.len > 0 and dh.len <= 2 and
                    std.ascii.isUpper(dh[0])) or b.isTypeParam(dh));
                if (!tp_head) {
                    return .{
                        .name = declared.name.name,
                        .nullable = declared.nullable,
                        .args = &.{},
                    };
                }
            }
        }
    }
    if (b.localDeclTypeRef(p.segments[0].name)) |declared| {
        var result = declared;
        result.nullable = result.nullable or b.localDeclNullable(p.segments[0].name);
        return result;
    }
    // A bare implicit-`this` property read: the name is the enclosing class's
    // own `val`, not a local (`assertEquals(expected, decode(…))` where
    // `expected` is a class-level property whose static type a sibling-driven
    // reified inference needs). Resolve it against the receiver's own property
    // table and QUALIFY a nested-class head through the enclosing scope so a
    // reified `serializer<T>()` binds `Outer$Nested`, not a bare unresolvable
    // name. A local would have won above.
    {
        const rhead: ?[]const u8 = if (b.recvTypeRef()) |rt|
            typeHead(std.mem.trimEnd(u8, rt.name, "?"))
        else
            b.ownerClass() orelse b.enclosingRecvTy();
        if (rhead) |rh| {
            if (b.module.registry.class_prop_type_heads.get(.{ .a = rh, .b = p.segments[0].name })) |head| {
                if (head.len != 0 and !b.isTypeParam(head)) {
                    const qualified = scopeTypeRenameFrom(b, rh, head, p.segments[0].span.file.int()) orelse head;
                    return .{ .name = qualified, .nullable = false, .args = &.{} };
                }
            }
        }
    }
    if (b.localInitExpr(p.segments[0].name)) |init| {
        // Following a local's initializer can re-enter this local. Kotlin has
        // no such cycle — a local cannot be initialized from one declared
        // after it — but lowering re-asks from a later point in the block,
        // where every local is already bound, so `val a = b.x` beside
        // `val b = a.y` reaches itself and recurses until the stack ends.
        // Refuse to re-enter a local already on the chain.
        if (init != arg and pushInitChain(p.segments[0].name)) {
            defer popInitChain();
            // The initializer is read in its DECLARATION scope: the local's
            // own name was free there (recorded at the decl), so the init's
            // bare calls must not see the binding that now exists at the
            // READ point — `iterator.hasNext()` follows `val iterator =
            // iterator()`, whose init resolves the RECEIVER member, never
            // the local itself.
            const prev_self = init_self_name;
            if (b.localInitNameFree(p.segments[0].name) and
                !std.mem.eql(u8, runtime.envOnce("KLIO_INIT_SELF") orelse "1", "0"))
                init_self_name = p.segments[0].name;
            defer init_self_name = prev_self;
            if (argDeclTypeRefLazy(b, init)) |inferred| return inferred;
            // A MEMBER-call or elvis initializer needs the full derivation
            // the lazy reader lacks (`val clause = findClause(x) ?:
            // continue; val onCancellation = clause.create...(a, b)`), so a
            // pass whose statement arm recorded nothing still types the
            // shape. Depth-guarded with the on-demand counter.
            if (od_depth < 3) {
                od_depth += 1;
                defer od_depth -= 1;
                if (staticExprTypeRef(b, init) catch null) |derived| return derived;
            }
        }
    }
    // The full declared type wins over its head: `items[0].tag()` and
    // `for (i in items)` need the ARGUMENTS the head throws away.
    if (staticBareReceiverTypeRef(b, p.segments[0].name)) |full| return full;
    if (staticBareReceiverType(b, p.segments[0].name)) |head| {
        return .{ .name = head, .nullable = false, .args = &.{} };
    }
    // A bare class name used as a value is its companion object: carry the
    // owner class's head as type evidence so `install(RoutingRoot, ...)`
    // cannot bind an overload whose parameter is an unrelated object type.
    const nm = p.segments[0].name;
    if (b.resolve(nm) == null and !b.knowsOuter(nm) and b.module.classId(nm) != null) {
        return .{ .name = nm, .nullable = false, .args = &.{} };
    }
    // A bare read of a TOP-LEVEL property carries its declared type head
    // (`asserter.assertEquals(...)` resolves against `Asserter`): the same
    // scoping walk a bare call ranks by picks the declaration.
    if (b.resolve(nm) == null and !b.knowsOuter(nm) and !enclosingHasMemberNamed(b, nm)) {
        const file = p.segments[0].span.file;
        const pkg = b.module.packageOfFile(file) orelse b.self_package;
        if (b.module.topLevelPropTypeRef(nm, pkg, file)) |full| return full;
        if (b.module.topLevelPropTypeHead(nm, pkg, file)) |head| {
            return .{ .name = head, .nullable = false, .args = &.{} };
        }
    }
    return null;
}

/// Locals whose initializer the declared-type walk is currently inside, so it
/// can refuse to re-enter one. Bounded: past the cap the walk simply stops
/// deriving, which is the same answer a null type already stands for.
var init_chain: [16][]const u8 = @splat(&.{});
var init_chain_len: usize = 0;

fn pushInitChain(name: []const u8) bool {
    if (init_chain_len == init_chain.len) return false;
    for (init_chain[0..init_chain_len]) |seen| {
        if (std.mem.eql(u8, seen, name)) return false;
    }
    init_chain[init_chain_len] = name;
    init_chain_len += 1;
    return true;
}

fn popInitChain() void {
    init_chain_len -= 1;
}

pub fn staticTypeClassId(b: *const FuncBuilder, ty: ir.TypeRef) ?ir.ClassId {
    var identity = std.mem.trimEnd(u8, ty.name, "?");
    if (std.mem.indexOfScalar(u8, identity, '<')) |lt| identity = identity[0..lt];
    return if (std.mem.indexOfScalar(u8, identity, '.') != null)
        b.module.classIdByFqn(identity)
    else
        b.module.uniqueClassIdBySimpleName(typeHead(identity));
}

fn ownedClassSelfType(
    allocator: Allocator,
    class: *const ir.Class,
) Allocator.Error!ir.TypeRef {
    const args = try allocator.alloc(ir.TypeRef, class.type_params.len);
    errdefer allocator.free(args);
    var initialized: usize = 0;
    errdefer {
        for (args[0..initialized]) |*arg| arg.deinit(allocator);
    }
    for (class.type_params, args) |param, *arg| {
        arg.* = .{
            .name = try ir.classTypeParamIdentity(allocator, class.id, param),
            .nullable = false,
            .args = try allocator.alloc(ir.TypeRef, 0),
        };
        initialized += 1;
    }
    return .{
        .name = try allocator.dupe(u8, class.fqn),
        .nullable = false,
        .args = args,
    };
}

pub fn staticDispatchReceiverTypeRef(
    b: *FuncBuilder,
    target: FuncId,
    call_receiver: ?ir.TypeRef,
    caller_file: ir.FileId,
) Allocator.Error!?ir.TypeRef {
    const sig = b.module.decl_sigs.get(target.int()) orelse return null;
    const owner = sig.enclosing_class orelse return null;
    if (owner.int() >= b.module.classes.items.len) return null;
    if (sig.kind == .instance_method) {
        const receiver = call_receiver orelse return null;
        return try receiver.clone(b.allocator);
    }
    if (sig.kind != .member_extension) return null;

    const owner_class = &b.module.classes.items[owner.int()];
    if (b.recvTypeRef()) |receiver| {
        if (staticTypeClassId(b, receiver)) |receiver_id| {
            if (receiver_id.int() >= b.module.classes.items.len) return null;
            const receiver_class = &b.module.classes.items[receiver_id.int()];
            if (b.module.classIsOrExtends(receiver_class.fqn, owner_class.fqn)) {
                return try receiver.clone(b.allocator);
            }
        }
    }
    const lexical = b.ownerClass() orelse return null;
    const lexical_id = if (std.mem.indexOfScalar(u8, lexical, '.') != null)
        b.module.classIdByFqn(lexical)
    else
        b.module.classIdIndexed(lexical, b.self_package, caller_file);
    const id = lexical_id orelse return null;
    if (id.int() >= b.module.classes.items.len) return null;
    const lexical_class = &b.module.classes.items[id.int()];
    if (!b.module.classIsOrExtends(lexical_class.fqn, owner_class.fqn)) return null;
    return try ownedClassSelfType(b.allocator, lexical_class);
}

/// `val x = Foo()` — a constructor call names its own type, so no return-type
/// derivation is needed at all. These reach the census as `no_func`: the callee
/// resolves to a CLASS rather than to a function.
pub fn ctorInitTypeRef(b: *FuncBuilder, init_expr: *const Expr) Allocator.Error!?ir.TypeRef {
    if (init_expr.* != .Call) return null;
    const call = init_expr.Call;
    // `Inner.Deep(2)` — a nested class constructed through its OWN enclosing
    // class name. The bare form (`Inner(1)`) resolves through the lexical
    // nested-class walk; the qualified one reached no class at all, so the
    // value it constructs had no type and every call on it resolved by name.
    // `HexFormat.Builder` builds `BytesHexFormat.Builder` exactly this way.
    if (call.callee.* == .Member and call.callee.Member.receiver.* == .Path and
        call.callee.Member.receiver.Path.segments.len == 1)
    {
        const outer_name = call.callee.Member.receiver.Path.segments[0].name;
        const inner_name = call.callee.Member.name.name;
        if (outer_name.len != 0 and std.ascii.isUpper(outer_name[0]) and
            inner_name.len != 0 and std.ascii.isUpper(inner_name[0]) and
            b.resolve(outer_name) == null and !b.knowsOuter(outer_name))
        {
            var qb: [128]u8 = undefined;
            if (std.fmt.bufPrint(&qb, "{s}.{s}", .{ outer_name, inner_name }) catch null) |qualified| {
                if (runtime.envOnce("KLIO_CITR_TRACE")) |w| {
                    if (std.mem.eql(u8, w, inner_name)) {
                        const c_opt = b.module.classIdByQualifiedSuffix(qualified);
                        if (c_opt) |c| {
                            const cc = &b.module.classes.items[c.int()];
                            std.debug.print("[citr] dotted {s} -> cid={d} name={s} object={} stub={} value={} abstract={}\n", .{ qualified, c.int(), cc.name, cc.is_object, cc.is_stub, cc.is_value, cc.is_abstract });
                        } else std.debug.print("[citr] dotted {s} -> none\n", .{qualified});
                    }
                }
                if (b.module.classIdByQualifiedSuffix(qualified)) |ncid| {
                    if (ncid.int() < b.module.classes.items.len) {
                        const ncls = &b.module.classes.items[ncid.int()];
                        // A class declared in a file whose bodies have not
                        // lowered yet is still a header row (`is_stub`); the
                        // constructed type is its name all the same.
                        if (!ncls.is_object and !ncls.is_value and !ncls.is_abstract) {
                            return ir.TypeRef{
                                .name = try b.allocator.dupe(u8, ncls.name),
                                .nullable = false,
                                .args = &.{},
                            };
                        }
                    }
                }
            }
        }
    }
    if (call.callee.* != .Path or call.callee.Path.segments.len != 1) return null;
    const ident = call.callee.Path.segments[0];
    const citr_trace = if (runtime.envOnce("KLIO_CITR_TRACE")) |w| std.mem.eql(u8, w, ident.name) else false;
    if (citr_trace) std.debug.print("[citr] {s} enter\n", .{ident.name});
    // A LOCAL class registers only at runtime (`RegisterClass` with its
    // captures): no lowering-time row exists, and the module index would
    // answer an unrelated same-named class — the resolve() bail below
    // already catches it (the declaration binds the name), noted here so
    // the local-class tail is not re-probed as a missed lookup.
    // A LOCAL CLASS constructor call: the lowering-time typing record's
    // mangled head (its registered supertype chain proves extension
    // applicability; the runtime RegisterClass binding stays the ctor).
    if (build.isLocalClassInScope(ident.name)) {
        var lc_buf: [160]u8 = undefined;
        if (std.fmt.bufPrint(&lc_buf, "{s}$lc{s}", .{ ident.name, build.currentRealFn() orelse "" }) catch null) |key| {
            if (b.module.registry.class_super_names.get(key) != null) {
                if (citr_trace) std.debug.print("[citr] {s} local-class head {s}\n", .{ ident.name, key });
                return .{ .name = try b.allocator.dupe(u8, key), .nullable = false, .args = &.{} };
            }
        }
    }
    // A local or a function of the same name is not a constructor call.
    if (b.resolve(ident.name) != null or b.knowsOuter(ident.name)) {
        if (citr_trace) std.debug.print("[citr] {s} bail=local_or_outer\n", .{ident.name});
        return null;
    }
    if (b.module.funcId(ident.name) != null) {
        if (citr_trace) std.debug.print("[citr] {s} bail=func_namesake\n", .{ident.name});
        return null;
    }
    // A collision-mangled internal class (`SlotTable$fN`) is absent from the
    // simple-name index. A same-file/package reference reaches it through
    // the scope rename ladder; a cross-package one through its exact import,
    // which still resolves by FQN.
    // Inside a splice's argument binding the callee frame is already
    // pushed: a nested class written in the CALLER (`listOf(B(1))` as a
    // reified argument) renames through the caller's lexical owner.
    const ref_name = scopeTypeRenameFrom(b, inline_call.spliceLexicalOwner() orelse b.ownerClass(), ident.name, ident.span.file.int()) orelse ident.name;
    const cid = b.module.classIdIndexed(ref_name, b.self_package, ident.span.file) orelse
        b.module.classIdExactImport(ident.name, ident.span.file) orelse {
        if (citr_trace) std.debug.print("[citr] {s} bail=no_class ref_name={s}\n", .{ ident.name, ref_name });
        return null;
    };
    // A MEMBER of the enclosing receiver shadows the constructor, exactly as
    // the emission router decides it (`fun Foo(): Bar` inside Host makes a
    // bare `Foo()` the member call). Typing the local as the class here bound
    // later calls against the wrong receiver class.
    if (enclosingHasMemberNamed(b, ident.name) and !classNestedInEnclosing(b, cid)) {
        if (citr_trace) std.debug.print("[citr] {s} bail=enclosing_member_shadow owner={s}\n", .{ ident.name, b.ownerClass() orelse "-" });
        return null;
    }
    if (cid.int() >= b.module.classes.items.len) return null;
    const class = &b.module.classes.items[cid.int()];
    // A STUB generic class constructed positionally (`Triple("1", 2, x)`,
    // `Pair(a, b)`): its header lists no primary parameters, so each type
    // argument binds from the argument at its position when the counts
    // line up — the reified consumer of the local needs `Triple<String,
    // Int, Box<Int>>`, not the bare head.
    if (citr_trace) std.debug.print("[citr] {s} class={s} stub={} tps={d} pps={d} nargs={d}\n", .{ ident.name, class.fqn, class.is_stub, class.type_params.len, class.primary_params.len, call.args.len });
    // `Array(size) { init }`: the element type is the initializer
    // lambda's tail expression (kotlinc infers `Array<Box<String>>` from
    // `Array(1) { Box("foo") }`).
    if (std.mem.eql(u8, class.fqn, "kotlin.Array") and call.type_args.len == 0 and call.args.len == 2 and
        call.args[1] == .Lambda and call.args[1].Lambda.body.stmts.len != 0)
    {
        const stmts = call.args[1].Lambda.body.stmts;
        const tail = &stmts[stmts.len - 1];
        if (citr_trace) std.debug.print("[citr] Array tail={s}\n", .{@tagName(std.meta.activeTag(tail.*))});
        if (tail.* == .Expr) {
            if (citr_trace) std.debug.print("[citr] Array elem={?s}\n", .{if (try staticExprTypeRef(b, &tail.Expr)) |e| e.name else null});
            if (try staticExprTypeRef(b, &tail.Expr)) |elem| {
                var eh = std.mem.trimEnd(u8, elem.name, "?");
                if (std.mem.indexOfScalar(u8, eh, '<')) |lt| eh = eh[0..lt];
                const bare_tp = (eh.len > 0 and eh.len <= 2 and std.ascii.isUpper(eh[0])) or
                    b.isTypeParam(eh) or ir.parseClassTypeParamIdentity(eh) != null;
                if (eh.len != 0 and !bare_tp) {
                    const args1 = try b.allocator.alloc(ir.TypeRef, 1);
                    args1[0] = elem;
                    return ir.TypeRef{ .name = try b.allocator.dupe(u8, class.fqn), .nullable = false, .args = args1 };
                }
                var e2 = elem;
                e2.deinit(b.allocator);
            }
        }
    }
    if (class.is_stub and !class.is_object and !class.is_value and call.type_args.len == 0 and
        class.type_params.len != 0 and class.primary_params.len == 0 and call.args.len == class.type_params.len)
    {
        const inferred = try b.allocator.alloc(ir.TypeRef, class.type_params.len);
        var got: usize = 0;
        var ok = true;
        defer if (!ok) {
            for (inferred[0..got]) |*t| t.deinit(b.allocator);
            b.allocator.free(inferred);
        };
        for (call.args, 0..) |*a, ai| {
            var bt = (try staticExprTypeRef(b, a)) orelse {
                ok = false;
                break;
            };
            var bh = std.mem.trimEnd(u8, bt.name, "?");
            if (std.mem.indexOfScalar(u8, bh, '<')) |lt| bh = bh[0..lt];
            const bare_tp = (bh.len > 0 and bh.len <= 2 and std.ascii.isUpper(bh[0])) or
                b.isTypeParam(bh) or ir.parseClassTypeParamIdentity(bh) != null;
            if (bh.len == 0 or bare_tp) {
                bt.deinit(b.allocator);
                ok = false;
                break;
            }
            inferred[ai] = bt;
            got += 1;
        }
        if (ok) {
            var derived = ir.TypeRef{
                .name = try b.allocator.dupe(u8, class.fqn),
                .nullable = false,
                .args = inferred,
            };
            if (!staticClassifierArgsComplete(b, derived)) {
                derived.deinit(b.allocator);
                return null;
            }
            return derived;
        }
        return null;
    }
    // An object is not constructed; a stub or value class has no instance
    // identity for a member call to bind against.
    if (class.is_object or class.is_stub or class.is_value) return null;
    var args = try b.allocator.alloc(ir.TypeRef, call.type_args.len);
    errdefer b.allocator.free(args);
    for (call.type_args, args) |*ty, *out| {
        out.* = try decl_mod.loweredTypeRef(b.allocator, ty, true);
    }
    // With no explicit `<...>`, a generic class's arguments infer from the
    // CONSTRUCTOR arguments (kotlinc's inference): a primary param declared
    // bare `E` takes its argument's own type; one declared `X<..., E, ...>`
    // takes the argument's type argument at that position when the arities
    // line up. Every class parameter must bind or the head-only refusal
    // below stands.
    if (args.len == 0 and class.type_params.len != 0 and call.args.len != 0) infer: {
        const inferred = try b.allocator.alloc(ir.TypeRef, class.type_params.len);
        var got: usize = 0;
        var ok = true;
        defer if (!ok) {
            for (inferred[0..got]) |*t| t.deinit(b.allocator);
            b.allocator.free(inferred);
        };
        for (class.type_params) |tp| {
            var bound: ?ir.TypeRef = null;
            params: for (class.primary_params, 0..) |*p, pi| {
                if (pi >= call.args.len) break;
                const pt = p.ty;
                if (std.mem.eql(u8, std.mem.trimEnd(u8, pt.name, "?"), tp)) {
                    bound = try staticExprTypeRef(b, &call.args[pi]);
                    break :params;
                }
                for (pt.args, 0..) |pa, ai| {
                    var an = std.mem.trimEnd(u8, pa.name, "?");
                    if (std.mem.startsWith(u8, an, "in#")) an = an[3..];
                    if (std.mem.startsWith(u8, an, "out#")) an = an[4..];
                    if (!std.mem.eql(u8, an, tp)) continue;
                    var at = (try staticExprTypeRef(b, &call.args[pi])) orelse continue :params;
                    defer at.deinit(b.allocator);
                    if (at.args.len == pt.args.len and ai < at.args.len) {
                        bound = try at.args[ai].clone(b.allocator);
                    }
                    break :params;
                }
            }
            var bt = bound orelse {
                ok = false;
                break :infer;
            };
            var bh = std.mem.trimEnd(u8, bt.name, "?");
            if (std.mem.indexOfScalar(u8, bh, '<')) |lt| bh = bh[0..lt];
            const bare_tp = (bh.len > 0 and bh.len <= 2 and std.ascii.isUpper(bh[0])) or
                b.isTypeParam(bh) or ir.parseClassTypeParamIdentity(bh) != null;
            if (bh.len == 0 or bare_tp) {
                bt.deinit(b.allocator);
                ok = false;
                break :infer;
            }
            inferred[got] = bt;
            got += 1;
        }
        b.allocator.free(args);
        args = inferred;
    }
    var derived = ir.TypeRef{
        .name = try b.allocator.dupe(u8, class.fqn),
        .nullable = false,
        .args = args,
    };
    if (!staticClassifierArgsComplete(b, derived)) {
        if (citr_trace) std.debug.print("[citr] {s} bail=args_incomplete\n", .{ident.name});
        derived.deinit(b.allocator);
        return null;
    }
    return derived;
}

/// The element type a `for (x in xs)` binds `x` to: the sole type ARGUMENT of
/// the iterable's declared type. A loop variable has no initializer to derive
/// from and is one of the three shapes making up the `no_initializer` census
/// bucket, alongside a lambda parameter and a destructured component.
///
/// Conservative on purpose. A head with any argument count other than one is
/// not an element sequence this can read, and an argument that is still a type
/// PARAMETER names nothing — committing to it would disprove candidates a null
/// type leaves open.
pub fn iterableElementTypeRef(b: *FuncBuilder, iter: *const Expr) Allocator.Error!?ir.TypeRef {
    var owned: ?ir.TypeRef = null;
    defer if (owned) |*t| t.deinit(b.allocator);
    var ty: ir.TypeRef = blk: {
        if (argDeclTypeRef(b, iter)) |known| break :blk known;
        // The LAZY channel serves `this` (the splice window's full
        // receiver) — `for (element in this)` inside the associateWithTo
        // splice iterates List<String>, and the ladder below never
        // reached it. Borrowed, like argDeclTypeRef's answer.
        if (argDeclTypeRefLazy(b, iter)) |lazy_known| break :blk lazy_known;
        owned = (try staticCallReturnTypeRef(b, iter)) orelse
            (try staticExprTypeRef(b, iter)) orelse return null;
        break :blk owned.?;
    };
    // A type-parameter head resolves through its full bound ref: iterating
    // a `T : Iterable<String>` receiver binds String elements.
    {
        var h0 = std.mem.trimEnd(u8, ty.name, "?");
        if (std.mem.indexOfScalar(u8, h0, '<')) |lt| h0 = h0[0..lt];
        if (ty.args.len == 0) {
            if (b.typeParamBoundRef(typeHead(h0))) |bref| ty = bref.*;
        }
    }
    // Char sequences iterate Chars by their iterator, not by a type
    // argument — `for (element in this)` inside `CharSequence.all`'s
    // spliced body is the live case.
    {
        var h = std.mem.trimEnd(u8, ty.name, "?");
        if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
        h = typeHead(h);
        if (std.mem.eql(u8, h, "CharSequence") or std.mem.eql(u8, h, "String") or
            std.mem.eql(u8, h, "StringBuilder"))
        {
            return try (ir.TypeRef{
                .name = "Char",
                .nullable = false,
                .args = &.{},
            }).clone(b.allocator);
        }
        // Primitive arrays iterate their scalar kind the same way.
        const prim_arrays = [_]struct { a: []const u8, e: []const u8 }{
            .{ .a = "BooleanArray", .e = "Boolean" }, .{ .a = "ByteArray", .e = "Byte" },
            .{ .a = "ShortArray", .e = "Short" },     .{ .a = "IntArray", .e = "Int" },
            .{ .a = "LongArray", .e = "Long" },       .{ .a = "CharArray", .e = "Char" },
            .{ .a = "FloatArray", .e = "Float" },     .{ .a = "DoubleArray", .e = "Double" },
            .{ .a = "UByteArray", .e = "UByte" },     .{ .a = "UShortArray", .e = "UShort" },
            .{ .a = "UIntArray", .e = "UInt" },       .{ .a = "ULongArray", .e = "ULong" },
        };
        for (prim_arrays) |pa| {
            if (std.mem.eql(u8, h, pa.a)) {
                return try (ir.TypeRef{
                    .name = pa.e,
                    .nullable = false,
                    .args = &.{},
                }).clone(b.allocator);
            }
        }
        // Ranges and progressions carry their element in the CLASS NAME, not
        // in a type argument, so the `args.len == 1` path below cannot reach
        // them: `for (i in lastIndex downTo 1)` left `i` untyped and every
        // call taking `i` unproven.
        const progressions = [_]struct { p: []const u8, e: []const u8 }{
            .{ .p = "IntRange", .e = "Int" },               .{ .p = "LongRange", .e = "Long" },
            .{ .p = "CharRange", .e = "Char" },             .{ .p = "UIntRange", .e = "UInt" },
            .{ .p = "ULongRange", .e = "ULong" },           .{ .p = "IntProgression", .e = "Int" },
            .{ .p = "LongProgression", .e = "Long" },       .{ .p = "CharProgression", .e = "Char" },
            .{ .p = "UIntProgression", .e = "UInt" },       .{ .p = "ULongProgression", .e = "ULong" },
        };
        for (progressions) |pr| {
            if (std.mem.eql(u8, h, pr.p)) {
                return try (ir.TypeRef{
                    .name = pr.e,
                    .nullable = false,
                    .args = &.{},
                }).clone(b.allocator);
            }
        }
    }
    if (ty.args.len != 1) return null;
    var elem = ty.args[0].name;
    // Declaration-site variance is spelling, not structure: the element of
    // `Array<out Array<out T>>` is the inner Array, not a name the head
    // tables could ever hold.
    if (std.mem.startsWith(u8, elem, "in#")) elem = elem[3..];
    if (std.mem.startsWith(u8, elem, "out#")) elem = elem[4..];
    if (elem.len == 0) return null;
    // A STAR projection's element is `Any?` — the projection's own upper
    // bound, which is what Kotlin resolves a call on it against.
    // `Collection<*>` is how the stdlib's own `orderedHashCode` and
    // `unorderedHashCode` take their argument, and their loop variables had
    // no type at all.
    if (std.mem.eql(u8, elem, "*")) {
        return try (ir.TypeRef{ .name = "Any", .nullable = true, .args = &.{} }).clone(b.allocator);
    }
    if (ty.args[0].nullable) return null;
    // A bare type-PARAMETER element is carried, not discarded, when the
    // scope records a bound for it: a generic body is lowered once with no
    // call site to read an instantiation from, and its parameter's declared
    // upper bound is what Kotlin resolves such a call against. Without a
    // bound record the head still names nothing and the old answer stands.
    if (elem.len <= 2 and std.ascii.isUpper(elem[0])) {
        if (b.typeParamBound(elem) == null) return null;
        return try cloneElemStripped(b, &ty.args[0], elem);
    }
    var head = elem;
    if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
    if (b.module.classIdByFqn(head) == null and
        b.module.uniqueClassIdBySimpleName(typeHead(head)) == null) return null;
    return try cloneElemStripped(b, &ty.args[0], elem);
}

/// Clone the element type with the variance mangle stripped from its NAME —
/// the checks above judged the stripped spelling, and every consumer keys
/// heads by it.
fn cloneElemStripped(b: *FuncBuilder, arg: *const ir.TypeRef, stripped: []const u8) Allocator.Error!ir.TypeRef {
    var out = try arg.clone(b.allocator);
    if (!std.mem.eql(u8, out.name, stripped)) {
        const owned = try b.allocator.dupe(u8, stripped);
        b.allocator.free(out.name);
        out.name = owned;
    }
    return out;
}

pub fn iterableElementTypeName(b: *FuncBuilder, iter: *const Expr) Allocator.Error!?[]const u8 {
    var elem = (try iterableElementTypeRef(b, iter)) orelse return null;
    defer elem.deinit(b.allocator);
    return try b.allocator.dupe(u8, elem.name);
}

/// A statically known type for an arbitrary expression: its own declared type
/// where it has one, otherwise a constructed class, a resolved call's return
/// type, or the type a local's initializer lends it. Owned by the caller.
/// On-demand return-derivation nesting: a body deriving a body must
/// terminate on mutual recursion.
pub threadlocal var od_depth: u8 = 0;

/// Every resolution arm that needs an operand's type asks for it again, so a
/// chain of infix calls (`a and 1 + b and 1 + ...`) re-typed its whole left
/// operand once per arm: 24 terms cost 20M type queries and 17s of lowering.
/// One outermost query now types each subexpression once. The memo lives only
/// for that query — builder state (splice windows, narrowed locals) cannot
/// change while it runs, and the stamp below drops the memo if it does.
const TyMemo = struct {
    map: std.AutoHashMapUnmanaged(u64, ?ir.TypeRef) = .{},
    /// Lazy answers are BORROWED (the deriver returns registry/AST slices
    /// without cloning), so this map never frees what it holds.
    lazy: std.AutoHashMapUnmanaged(u64, ?ir.TypeRef) = .{},
    owner: ?*FuncBuilder = null,
    stamp: u64 = 0,
    depth: u32 = 0,
};
threadlocal var ty_memo: TyMemo = .{};

/// The memo outlives any one function build, so its own storage comes from a
/// process-lifetime allocator instead of the builder's arena.
fn memoAlloc() std.mem.Allocator {
    return std.heap.smp_allocator;
}

fn tyMemoOn() bool {
    // `KLIO_TY_MEMO=0` disables the static-type memo (bisect aid).
    return !std.mem.eql(u8, runtime.envOnce("KLIO_TY_MEMO") orelse "1", "0");
}

pub const TyMemoHit = struct { ty: ?ir.TypeRef };

fn tyMemoStamp(b: *const FuncBuilder) u64 {
    var h: u64 = if (b.caller_member_scope) |ms| @intFromPtr(ms) else 8;
    h = h *% 31 +% b.inline_stack_visible_base;
    h = h *% 31 +% b.inline_lambda_subst.items.len;
    h = h *% 31 +% b.splice_hidden_bands.items.len;
    h = h *% 31 +% b.local_decl_types.count();
    if (b.lambda_splice_resolve) |ls| h = h *% 31 +% ls.caller_depth *% 7 +% ls.own_base;
    return h;
}

fn tyMemoKey(e: *const Expr, tag: u1) u64 {
    return (@as(u64, @intFromPtr(e)) << 1) | tag;
}

fn tyMemoGet(b: *FuncBuilder, e: *const Expr, tag: u1) ?TyMemoHit {
    if (ty_memo.depth == 0 or ty_memo.owner != b) return null;
    const hit = ty_memo.map.get(tyMemoKey(e, tag)) orelse return null;
    const cloned: ?ir.TypeRef = if (hit) |t| (t.clone(b.allocator) catch return null) else null;
    return .{ .ty = cloned };
}

fn tyMemoEnter(b: *FuncBuilder) bool {
    if (!tyMemoOn()) return false;
    if (ty_memo.depth == 0) {
        ty_memo.owner = b;
        ty_memo.stamp = tyMemoStamp(b);
        ty_memo.depth = 1;
        return true;
    }
    ty_memo.depth += 1;
    return false;
}

fn tyMemoLeave(b: *FuncBuilder, owns: bool, e: *const Expr, tag: u1, r: ?ir.TypeRef) void {
    if (!tyMemoOn()) return;
    ty_memo.depth -= 1;
    if (owns) {
        tyMemoClear();
        return;
    }
    if (ty_memo.owner != b or ty_memo.stamp != tyMemoStamp(b)) return;
    const stored: ?ir.TypeRef = if (r) |t| (t.clone(memoAlloc()) catch return) else null;
    ty_memo.map.put(memoAlloc(), tyMemoKey(e, tag), stored) catch {
        if (stored) |t| @constCast(&t).deinit(memoAlloc());
    };
}

fn tyMemoClear() void {
    var it = ty_memo.map.iterator();
    while (it.next()) |ent| if (ent.value_ptr.*) |*t| t.deinit(memoAlloc());
    ty_memo.map.clearRetainingCapacity();
    ty_memo.lazy.clearRetainingCapacity();
    ty_memo.owner = null;
}

fn lazyMemoGet(b: *FuncBuilder, e: *const Expr) ?TyMemoHit {
    if (ty_memo.depth == 0 or ty_memo.owner != b) return null;
    const hit = ty_memo.lazy.get(@intFromPtr(e)) orelse return null;
    return .{ .ty = hit };
}

fn lazyMemoLeave(b: *FuncBuilder, owns: bool, e: *const Expr, r: ?ir.TypeRef) void {
    if (!tyMemoOn()) return;
    if (!owns and ty_memo.owner == b and ty_memo.stamp == tyMemoStamp(b)) {
        ty_memo.lazy.put(memoAlloc(), @intFromPtr(e), r) catch {};
    }
    ty_memo.depth -= 1;
    if (owns) tyMemoClear();
}

pub fn staticExprTypeRef(b: *FuncBuilder, e: *const Expr) Allocator.Error!?ir.TypeRef {
    if (tyMemoGet(b, e, 0)) |hit| return hit.ty;
    const owns = tyMemoEnter(b);
    const r = try staticExprTypeRefUncached(b, e);
    tyMemoLeave(b, owns, e, 0, r);
    return r;
}

/// Memo entry point for the call-return deriver, which several arms re-enter
/// on the same subexpression.
pub fn tyMemoCall(b: *FuncBuilder, e: *const Expr) ?TyMemoHit {
    return tyMemoGet(b, e, 1);
}
pub fn tyMemoCallEnter(b: *FuncBuilder) bool {
    return tyMemoEnter(b);
}
pub fn tyMemoCallLeave(b: *FuncBuilder, owns: bool, e: *const Expr, r: ?ir.TypeRef) void {
    tyMemoLeave(b, owns, e, 1, r);
}

fn staticExprTypeRefUncached(b: *FuncBuilder, e: *const Expr) Allocator.Error!?ir.TypeRef {
    // Literals name their own type (`var result = 0` is an Int wherever
    // the var is read, including across a capture boundary).
    switch (e.*) {
        .IntLit => |lit| return .{ .name = try b.allocator.dupe(u8, switch (lit.kind) {
            .Long => "Long",
            .UInt => "UInt",
            .ULong => "ULong",
            .Int => if (lit.value >= std.math.minInt(i32) and lit.value <= std.math.maxInt(i32)) "Int" else "Long",
        }), .nullable = false, .args = &.{} },
        .FloatLit => |lit| return .{ .name = try b.allocator.dupe(u8, if (lit.kind == .Float) "Float" else "Double"), .nullable = false, .args = &.{} },
        .BoolLit => return .{ .name = try b.allocator.dupe(u8, "Boolean"), .nullable = false, .args = &.{} },
        .CharLit => return .{ .name = try b.allocator.dupe(u8, "Char"), .nullable = false, .args = &.{} },
        .StringTemplate => return .{ .name = try b.allocator.dupe(u8, "String"), .nullable = false, .args = &.{} },
        else => {},
    }
    if (argDeclTypeRef(b, e)) |known| {
        // A bare TYPE-PARAMETER answer for an implicit property read
        // (`expected: T` on a `Ctx<Map<K, V>>` receiver) substitutes the
        // receiver's instantiation instead of stopping at `T`.
        const kh = typeHead(std.mem.trimEnd(u8, known.name, "?"));
        const bare_k = (kh.len > 0 and kh.len <= 2 and std.ascii.isUpper(kh[0])) or
            b.isTypeParam(kh) or ir.parseClassTypeParamIdentity(kh) != null;
        if (bare_k and e.* == .Path and e.Path.segments.len == 1) {
            const nm2 = e.Path.segments[0].name;
            if (runtime.envOnce("KLIO_IMPLPROP_TRACE")) |w| {
                if (std.mem.eql(u8, w, nm2))
                    std.debug.print("[implprop-bare] {s} known={s} rtref={} rt_args={d}\n", .{ nm2, known.name, b.recvTypeRef() != null, if (b.recvTypeRef()) |r| r.args.len else 0 });
            }
            if (b.recvTypeRef()) |rt| sub_head: {
                const rh = typeHead(std.mem.trimEnd(u8, rt.name, "?"));
                const declared: ir.TypeRef = propTypeRefOn(b, rh, nm2) orelse blk2: {
                    const head = b.module.registry.class_prop_type_heads.get(.{ .a = rh, .b = nm2 }) orelse break :sub_head;
                    break :blk2 .{ .name = head, .nullable = false, .args = &.{} };
                };
                const dh = typeHead(std.mem.trimEnd(u8, declared.name, "?"));
                // The declared type IS the owner's parameter: map it by
                // position under the receiver's instantiation.
                if (bareTypeParamHead(dh) and declared.args.len == 0) {
                    const cid = (b.module.uniqueClassIdBySimpleName(rh) orelse
                        b.module.classIdByFqn(rh)) orelse break :sub_head;
                    if (cid.int() >= b.module.classes.items.len) break :sub_head;
                    const tps = b.module.classes.items[cid.int()].type_params;
                    if (tps.len != rt.args.len) break :sub_head;
                    for (tps, 0..) |tp, j| {
                        if (!std.mem.eql(u8, tp, dh)) continue;
                        const sub = rt.args[j];
                        const sh = typeHead(std.mem.trimEnd(u8, sub.name, "?"));
                        if (sh.len == 0 or std.mem.eql(u8, sh, "*") or
                            bareTypeParamHead(sh)) break :sub_head;
                        var out = try sub.clone(b.allocator);
                        out.nullable = out.nullable or declared.nullable;
                        return out;
                    }
                    break :sub_head;
                }
                if (substitutedPropType(b, rh, rt, declared)) |sub| {
                    return try sub.clone(b.allocator);
                }
            }
        }
        // A generic CONSTRUCTOR call the eager typer answers head-only
        // (`Triple("1", 2, x)` as `kotlin.Triple`): the constructor
        // derivation instantiates the arguments the reified consumer of
        // the local needs.
        if (e.* == .Call and known.args.len == 0) {
            if (try ctorInitTypeRef(b, e)) |t| {
                if (t.args.len != 0) return t;
                var tt = t;
                tt.deinit(b.allocator);
            }
        }
        return try known.clone(b.allocator);
    }
    if (try ctorInitTypeRef(b, e)) |t| return t;
    if (try staticCallReturnTypeRef(b, e)) |t| return t;
    // `lhs ?: <jump>` carries the lhs type made NON-null: `val clause =
    // findClause(x) ?: continue` types `clause` as the call's declared
    // return without its `?` — the jump arm never produces a value.
    if (e.* == .Binary and e.Binary.op == .Elvis) {
        const bin = e.Binary;
        if (try staticExprTypeRef(b, bin.lhs)) |lhs_ty| {
            var out = lhs_ty;
            switch (bin.rhs.*) {
                .Continue, .Break, .Return, .Throw => {
                    out.nullable = false;
                    return out;
                },
                else => {},
            }
            // A value rhs makes the result the JOIN of both branches, not
            // the lhs type: `pendingPausedComposition?.pausableApplier ?:
            // applier` is an `Applier<*>`, and typing it as the final lhs
            // class devirtualizes member calls to bodies the runtime
            // receiver overrides. When one branch's type subsumes the
            // other, the supertype side is the result; unrelated heads
            // yield no static type (dynamic dispatch is always sound).
            out.nullable = false;
            const lhs_head = typeHead(std.mem.trimEnd(u8, out.name, "?"));
            if (try staticExprTypeRef(b, bin.rhs)) |rhs_ty| {
                const rhs_head = typeHead(std.mem.trimEnd(u8, rhs_ty.name, "?"));
                if (std.mem.eql(u8, lhs_head, rhs_head)) {
                    out.nullable = rhs_ty.nullable;
                    return out;
                }
                var lhs_nn = out;
                lhs_nn.name = lhs_head;
                var rhs_nn = rhs_ty;
                rhs_nn.name = rhs_head;
                rhs_nn.nullable = false;
                if (b.module.staticTypeCompatibility(lhs_nn, rhs_nn) == .compatible) {
                    return try rhs_ty.clone(b.allocator);
                }
                if (b.module.staticTypeCompatibility(rhs_nn, lhs_nn) == .compatible) {
                    out.nullable = rhs_ty.nullable;
                    return out;
                }
                return null;
            }
            return out;
        }
    }
    // Shapes that name their own type outright. Each one is exact — the cast
    // states the type, `this` is the enclosing class, a predicate operator
    // yields Boolean — and each was reaching the call sites below with no
    // receiver type at all, which is what forces a runtime name walk.
    self_named: {
        switch (e.*) {
            // `x as T` / `x as? T` — the cast IS the answer; `as?` carries the
            // null the safe form can produce.
        .As => |cast| {
            var out = try decl_mod.loweredTypeRef(b.allocator, &cast.ty, true);
            if (cast.safe) out.nullable = true;
            return out;
        },
        // An object EXPRESSION with a single supertype has that supertype
        // as its denotable static type (kotlinc: `object : List<String> by
        // coll {}` is a List<String> everywhere outside the literal). More
        // than one supertype is the anonymous intersection — refused.
        .ObjectExpr => |obj| {
            // A bare `object {}` with no supertype: its denotable type
            // outside the literal is `Any` (the marker-object idiom —
            // `(object {}).let { ... }` must splice like any receiver).
            if (obj.supertypes.len == 0) {
                return .{ .name = try b.allocator.dupe(u8, "Any"), .nullable = false, .args = &.{} };
            }
            if (obj.supertypes.len != 1) break :self_named;
            var out = try decl_mod.loweredTypeRef(b.allocator, &obj.supertypes[0], true);
            var h = std.mem.trimEnd(u8, out.name, "?");
            if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
            const bare = (h.len > 0 and h.len <= 2 and std.ascii.isUpper(h[0])) or
                ir.parseClassTypeParamIdentity(h) != null;
            if (h.len == 0 or bare) {
                out.deinit(b.allocator);
                break :self_named;
            }
            return out;
        },
        // `this` (or `this@Outer`) inside a class body, an extension body,
        // or an inline splice window.
        .This => |this_e| {
            if (this_e.qualifier) |q| {
                if (b.module.uniqueClassIdBySimpleName(q.name) != null) {
                    return .{ .name = try b.allocator.dupe(u8, q.name), .nullable = false, .args = &.{} };
                }
                // A FUNCTION-labeled `this@thenBy` names an enclosing
                // receiver the tower records with its label — including
                // the inline-splice window's receiver, which the tower
                // collection now carries into closure bodies.
                for (b.implicit_receiver_tower.items) |entry| {
                    if (entry.label) |lbl| {
                        if (std.mem.eql(u8, lbl, q.name)) {
                            return .{ .name = try b.allocator.dupe(u8, entry.head), .nullable = false, .args = &.{} };
                        }
                    }
                }
                // `this@<ownFn>` inside the function's own body (through
                // any spliced receiver-lambda window) is the declared
                // extension receiver — WITH its type arguments, so an
                // overload rank on the labeled value keeps its element
                // knowledge (`putAll(this@toMap)` must pick the
                // Iterable-of-pairs extension, not a sibling).
                if (build.currentRealFn()) |rf| {
                    if (std.mem.eql(u8, rf, q.name)) {
                        if (b.recvTypeRef()) |declared| return try declared.clone(b.allocator);
                        if (b.recvTy()) |head| {
                            return .{ .name = try b.allocator.dupe(u8, head), .nullable = false, .args = &.{} };
                        }
                    }
                }
                return null;
            }
            // The declared extension receiver, then the splice window's
            // ACTUAL receiver (`this.fill(...)` inside an IntArray splice),
            // then the enclosing class.
            if (b.recvTypeRef()) |declared| return try declared.clone(b.allocator);
            if (b.spliceRecvTyRef()) |art| return try art.clone(b.allocator);
            if (b.spliceRecvTy()) |head| {
                return .{ .name = try b.allocator.dupe(u8, head), .nullable = false, .args = &.{} };
            }
            if (b.ownerClass()) |owner| {
                return .{ .name = try b.allocator.dupe(u8, owner), .nullable = false, .args = &.{} };
            }
            return null;
        },
        // A conditional's type is the type its branches AGREE on. Kotlin's
        // answer is their least upper bound, which needs the full hierarchy;
        // this takes the exact case — every branch derives the same head —
        // which is what a member call on the local needs and is never a
        // widening. A branch whose type is unknown declines the whole shape.
        .If => |iff| {
            const else_e = iff.else_branch orelse return null;
            const t_then = (try staticExprTypeRef(b, iff.then_branch)) orelse return null;
            const t_else = (try staticExprTypeRef(b, else_e)) orelse return null;
            if (!std.mem.eql(u8, t_then.name, t_else.name)) return null;
            var out = t_then;
            out.nullable = t_then.nullable or t_else.nullable;
            return out;
        },
        .When => |whn| {
            if (whn.branches.len == 0) return null;
            var agreed: ?ir.TypeRef = null;
            var nullable = false;
            for (whn.branches) |*br| {
                const t = (try staticExprTypeRef(b, &br.body)) orelse return null;
                nullable = nullable or t.nullable;
                if (agreed) |a| {
                    if (!std.mem.eql(u8, a.name, t.name)) return null;
                } else {
                    agreed = t;
                }
            }
            var out = agreed orelse return null;
            out.nullable = nullable;
            return out;
        },
        .Binary => |bin| switch (bin.op) {
            .Eq, .Neq, .IdentEq, .IdentNeq, .Lt, .Le, .Gt, .Ge, .In, .NotIn, .And, .Or => {
                return .{ .name = try b.allocator.dupe(u8, "Boolean"), .nullable = false, .args = &.{} };
            },
            // Arithmetic over the BUILT-IN numeric types has a type Kotlin
            // fixes by promotion, so `(hi - lo).toLong()` reaches its member
            // call with a known receiver instead of none. Only both-sides-
            // known, non-nullable primitives qualify; anything else falls
            // through to the operator-method derivation below.
            .Add, .Sub, .Mul, .Div, .Rem => {
                var lhs_owned = try staticExprTypeRef(b, bin.lhs);
                defer if (lhs_owned) |*t| t.deinit(b.allocator);
                var rhs_owned = try staticExprTypeRef(b, bin.rhs);
                defer if (rhs_owned) |*t| t.deinit(b.allocator);
                const lt = lhs_owned orelse break :self_named;
                const rt = rhs_owned orelse break :self_named;
                if (lt.nullable or rt.nullable) break :self_named;
                const promoted = numericPromotion(lt.name, rt.name) orelse break :self_named;
                return .{ .name = try b.allocator.dupe(u8, promoted), .nullable = false, .args = &.{} };
            },
            else => {},
        },
        .Unary => |un| switch (un.op) {
            .Not => return .{ .name = try b.allocator.dupe(u8, "Boolean"), .nullable = false, .args = &.{} },
            // `-x` / `+x` keep the operand's type.
            .Neg, .Pos => return try staticExprTypeRef(b, un.expr),
            else => {},
        },
        // `x!!` is the operand's type made NON-null (`val step =
        // nextStep!!` on a `Continuation<Unit>?` property).
        .Postfix => |pf| if (pf.op == .NotNull) {
            var t = (try staticExprTypeRef(b, pf.expr)) orelse break :self_named;
            t.nullable = false;
            if (std.mem.endsWith(u8, t.name, "?")) {
                const trimmed = try b.allocator.dupe(u8, std.mem.trimEnd(u8, t.name, "?"));
                b.allocator.free(t.name);
                t.name = trimmed;
            }
            return t;
        },
        // A bare name that reads an ENCLOSING class or companion property
        // lends its declared type: `payload shl bitsPerSymbol` inside a
        // Base64 member needs the companion const to answer Int before the
        // Binary promotion above can type the operation. Locals were
        // consulted first (argDeclTypeRef), and a same-named local WITHOUT
        // a type must keep shadowing — Kotlin resolves the local.
        .Path => |p| {
            if (p.segments.len != 1) break :self_named;
            const nm = p.segments[0].name;
            if (runtime.envOnce("KLIO_IMPLPROP_TRACE")) |w| {
                if (std.mem.eql(u8, w, nm))
                    std.debug.print("[implprop-guard] {s} resolve={} localfn={} outer={}\n", .{ nm, b.resolve(nm) != null, b.isLocalFn(nm), b.knowsOuter(nm) });
            }
            if (b.resolve(nm) != null or b.isLocalFn(nm) or b.knowsOuter(nm)) break :self_named;
            if (b.ownerClass()) |owner| {
                // The full-ref table records only arg-carrying declared
                // types; a scalar property (`const val bitsPerSymbol: Int`)
                // lives in the HEAD table.
                if (propTypeRefOn(b, owner, nm)) |t| return try t.clone(b.allocator);
                if (b.module.registry.class_prop_type_heads.get(.{ .a = owner, .b = nm })) |head| {
                    return .{ .name = try b.allocator.dupe(u8, head), .nullable = false, .args = &.{} };
                }
                // The companion's properties are in scope in the class body;
                // they record under the lifted `{Owner}$Companion` key.
                var ckey_buf: [160]u8 = undefined;
                if (std.fmt.bufPrint(&ckey_buf, "{s}$Companion", .{owner})) |ckey| {
                    if (propTypeRefOn(b, ckey, nm)) |t| return try t.clone(b.allocator);
                    if (b.module.registry.class_prop_type_heads.get(.{ .a = ckey, .b = nm })) |head| {
                        return .{ .name = try b.allocator.dupe(u8, head), .nullable = false, .args = &.{} };
                    }
                } else |_| {}
            }
            // A property of the IMPLICIT receiver — the declared receiver
            // or the splice window — with a type-parameter head chased to
            // its declared bound: `entries` inside the apply-spliced
            // onEachIndexed body reads `Map<out K, V>.entries`.
            impl: {
                const h0 = b.recvTy() orelse b.spliceRecvTy() orelse break :impl;
                var hh = typeHead(std.mem.trimEnd(u8, h0, "?"));
                const impl_trace = if (runtime.envOnce("KLIO_IMPLPROP_TRACE")) |w| std.mem.eql(u8, w, nm) else false;
                if (impl_trace) {
                    std.debug.print("[implprop] {s} h0={s} tp={} bref={} tpb={}\n", .{
                        nm, h0, b.isTypeParam(hh), b.typeParamBoundRef(hh) != null, b.typeParamBound(hh) != null,
                    });
                }
                var bound_full: ?*const ir.TypeRef = null;
                if (b.isTypeParam(hh) or (hh.len > 0 and hh.len <= 2 and std.ascii.isUpper(hh[0]))) {
                    if (b.typeParamBoundRef(hh)) |bref| {
                        bound_full = bref;
                        hh = typeHead(std.mem.trimEnd(u8, bref.name, "?"));
                    } else if (b.typeParamBound(hh)) |tpb| {
                        // Head-only bound record: the head still names the
                        // property's owner for the head-table answer.
                        hh = typeHead(std.mem.trimEnd(u8, tpb.bound, "?"));
                    } else if (b.enclosingRecvTy()) |eh2| {
                        // The lambda's own receiver head may be the spliced
                        // callee's literal param (apply's `T` inside
                        // `M.onEachIndexed`); the ENCLOSING receiver's head
                        // carries the real parameter and its bound.
                        const hh2 = typeHead(std.mem.trimEnd(u8, eh2, "?"));
                        if (b.typeParamBoundRef(hh2)) |bref2| {
                            bound_full = bref2;
                            hh = typeHead(std.mem.trimEnd(u8, bref2.name, "?"));
                        } else if (b.typeParamBound(hh2)) |tpb2| {
                            hh = typeHead(std.mem.trimEnd(u8, tpb2.bound, "?"));
                        } else if (!(b.isTypeParam(hh2) or (hh2.len > 0 and hh2.len <= 2 and std.ascii.isUpper(hh2[0])))) {
                            hh = hh2;
                        } else {
                            hh = implBoundScan(b, nm) orelse break :impl;
                        }
                    } else {
                        // The window's head names a param with no recorded
                        // bound at all: the UNIQUE in-scope bound whose
                        // class declares the property is the receiver
                        // (`entries` under `M : Map<out K, V>`).
                        hh = implBoundScan(b, nm) orelse break :impl;
                    }
                }
                if (propTypeRefOn(b, hh, nm)) |declared| {
                    if (bound_full) |br| {
                        if (substitutedPropType(b, hh, br.*, declared)) |sub| {
                            return try sub.clone(b.allocator);
                        }
                    } else if (b.recvTypeRef()) |rt| {
                        if (substitutedPropType(b, hh, rt, declared)) |sub| {
                            return try sub.clone(b.allocator);
                        }
                    }
                }
                if (b.module.registry.class_prop_type_heads.get(.{ .a = hh, .b = nm })) |ph| {
                    const phh = typeHead(std.mem.trimEnd(u8, ph, "?"));
                    if (phh.len > 2 and ir.parseClassTypeParamIdentity(phh) == null and !b.isTypeParam(phh)) {
                        return .{ .name = try b.allocator.dupe(u8, ph), .nullable = false, .args = &.{} };
                    }
                }
            }
            // A TOP-LEVEL property read lends its recorded declared type
            // under the caller's own scope tiers (`DAYS_PER_CYCLE` inside
            // the ofEpochDay run block).
            if (b.module.topLevelPropTypeRef(nm, b.self_package, p.segments[0].span.file)) |t| {
                return try t.clone(b.allocator);
            }
            if (b.module.topLevelPropTypeHeadTiered(nm, b.self_package, p.segments[0].span.file)) |head| {
                const hh = typeHead(std.mem.trimEnd(u8, head, "?"));
                if (hh.len > 2 and ir.parseClassTypeParamIdentity(hh) == null) {
                    return .{ .name = try b.allocator.dupe(u8, head), .nullable = false, .args = &.{} };
                }
            }
            break :self_named;
        },
        // A CLASS-NAMED member read: `TimeSource.Monotonic` (a nested
        // OBJECT, whose type is its own qualified class) or a companion
        // property (`Formats.iso`), which the class-prop head tables
        // record under the lifted companion key.
        .Member => |m| {
            if (m.safe) break :self_named;
            const recv_p = m.receiver;
            if (recv_p.* != .Path or recv_p.Path.segments.len != 1 or
                b.resolve(recv_p.Path.segments[0].name) != null or
                b.knowsOuter(recv_p.Path.segments[0].name) or
                b.module.uniqueClassIdBySimpleName(recv_p.Path.segments[0].name) == null)
            {
                // Not a class-named read: a PROPERTY READ on any receiver
                // the deriver can type answers the property's recorded
                // declared type (`this@Duration.absoluteValue`), with the
                // owner's parameters substituted from the receiver's own
                // arguments where both sides carry them.
                if (od_depth >= 3) break :self_named;
                od_depth += 1;
                const recv_owned = staticExprTypeRef(b, m.receiver) catch null;
                od_depth -= 1;
                var rt = recv_owned orelse break :self_named;
                defer rt.deinit(b.allocator);
                var rh = std.mem.trimEnd(u8, rt.name, "?");
                if (std.mem.indexOfScalar(u8, rh, '<')) |lt| rh = rh[0..lt];
                const head = typeHead(rh);
                if (head.len == 0) break :self_named;
                if (runtime.envOnce("KLIO_IMPLPROP_TRACE")) |w| {
                    if (std.mem.eql(u8, w, m.name.name)) {
                        std.debug.print("[implprop-mem] {s} head={s} refs={} heads={}\n", .{
                            m.name.name, head,
                            propTypeRefOn(b, head, m.name.name) != null,
                            b.module.registry.class_prop_type_heads.get(.{ .a = head, .b = m.name.name }) != null,
                        });
                    }
                }
                if (propTypeRefOn(b, head, m.name.name)) |declared| {
                    if (substitutedPropType(b, head, rt, declared)) |sub| {
                        return try sub.clone(b.allocator);
                    }
                }
                if (b.module.registry.class_prop_type_heads.get(.{ .a = head, .b = m.name.name })) |ph| {
                    const phh = typeHead(std.mem.trimEnd(u8, ph, "?"));
                    if (phh.len > 2 and ir.parseClassTypeParamIdentity(phh) == null and !b.isTypeParam(phh)) {
                        return .{ .name = try b.allocator.dupe(u8, ph), .nullable = false, .args = &.{} };
                    }
                }
                break :self_named;
            }
            const cls = recv_p.Path.segments[0].name;
            var qbuf: [192]u8 = undefined;
            if (std.fmt.bufPrint(&qbuf, "{s}.{s}", .{ cls, m.name.name })) |qual| {
                if (b.module.classIdByQualifiedSuffix(qual) != null) {
                    return .{ .name = try b.allocator.dupe(u8, qual), .nullable = false, .args = &.{} };
                }
            } else |_| {}
            var ckbuf: [192]u8 = undefined;
            if (std.fmt.bufPrint(&ckbuf, "{s}$Companion", .{cls})) |ckey| {
                if (propTypeRefOn(b, ckey, m.name.name)) |t| return try t.clone(b.allocator);
                if (b.module.registry.class_prop_type_heads.get(.{ .a = ckey, .b = m.name.name })) |head| {
                    return .{ .name = try b.allocator.dupe(u8, head), .nullable = false, .args = &.{} };
                }
            } else |_| {}
            break :self_named;
        },
            else => {},
        }
    }
    return try localInitTypeRef(b, e);
}

/// Kotlin's promotion for arithmetic over the built-in numeric types: the
/// wider operand wins, with the unsigned family kept separate (mixing signed
/// and unsigned is not an operator Kotlin defines).
fn numericPromotion(a: []const u8, c: []const u8) ?[]const u8 {
    const order = [_][]const u8{ "Double", "Float", "Long", "Int", "Short", "Byte" };
    const uorder = [_][]const u8{ "ULong", "UInt", "UShort", "UByte" };
    const rank = struct {
        fn f(set: []const []const u8, n: []const u8) ?usize {
            for (set, 0..) |s2, i| {
                if (std.mem.eql(u8, s2, n)) return i;
            }
            return null;
        }
    }.f;
    if (rank(&order, a)) |ra| {
        const rc = rank(&order, c) orelse return null;
        // Byte/Short arithmetic yields Int in Kotlin — there is no
        // `Byte.plus(Byte): Byte`.
        const winner = order[@min(ra, rc)];
        if (std.mem.eql(u8, winner, "Short") or std.mem.eql(u8, winner, "Byte")) return "Int";
        return winner;
    }
    if (rank(&uorder, a)) |ra| {
        const rc = rank(&uorder, c) orelse return null;
        const winner = uorder[@min(ra, rc)];
        if (std.mem.eql(u8, winner, "UShort") or std.mem.eql(u8, winner, "UByte")) return "UInt";
        return winner;
    }
    return null;
}

/// The declared return type of a nullary member on a known receiver type, with
/// the receiver's own type arguments substituted in. This is what a
/// DESTRUCTURED component needs: `for ((a, b) in xs)` binds each name to the
/// element's `componentN()`, so each one's type is that accessor's return type.
pub fn nullaryMemberReturnTypeRef(
    b: *FuncBuilder,
    recv: ir.TypeRef,
    name: []const u8,
    file: span.FileId,
) Allocator.Error!?ir.TypeRef {
    const trace = runtime.envOnce("KLIO_COMP_TRACE") != null;
    var identity = std.mem.trimEnd(u8, recv.name, "?");
    if (std.mem.indexOfScalar(u8, identity, '<')) |lt| identity = identity[0..lt];
    if (identity.len == 0) return null;
    const owner = (if (std.mem.indexOfScalar(u8, identity, '.') != null)
        b.module.classIdByFqn(identity)
    else
        b.module.uniqueClassIdBySimpleName(typeHead(identity))) orelse {
        if (trace) std.debug.print("[comp] {s}.{s} no owner\n", .{ identity, name });
        return null;
    };
    var shape_set = try buildStaticReturnArgShapes(b, &.{}, &.{});
    defer shape_set.deinit(b.allocator);
    const owned_bounds = try b.typeParamBoundsSlice();
    defer if (owned_bounds) |bounds| b.allocator.free(bounds);
    const resolved = b.module.resolveMemberCall(owner, name, shape_set.shapes, .{
        .caller_file = file,
        .lexical_owner = null,
        .actual_type_param_bounds = owned_bounds orelse &.{},
        .receiver_type = recv,
    });
    // A deferred resolution that still names one declaration is enough here:
    // this reads a RETURN TYPE, not a dispatch commitment, and an override
    // may only narrow it.
    const target = resolved.target orelse {
        if (trace) std.debug.print("[comp] {s}.{s} no target applicable={} methods={d}\n", .{
            identity,
            name,
            resolved.applicable,
            b.module.classes.items[owner.int()].methods.len,
        });
        return null;
    };
    var dispatch_receiver = try staticDispatchReceiverTypeRef(b, target, recv, file);
    defer if (dispatch_receiver) |*ty| ty.deinit(b.allocator);
    var out = (try b.module.instantiatedCallReturnType(
        b.allocator,
        target,
        recv,
        dispatch_receiver,
        shape_set.shapes,
        &.{},
    )) orelse {
        if (trace) std.debug.print("[comp] {s}.{s} no return type\n", .{ identity, name });
        return null;
    };
    // A return type left as the owner's own type PARAMETER names no class —
    // the receiver was written without its arguments. Committing to it would
    // disprove candidates a null type leaves open.
    var head = std.mem.trimEnd(u8, out.name, "?");
    if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
    if (b.module.classIdByFqn(head) == null and
        b.module.uniqueClassIdBySimpleName(typeHead(head)) == null)
    {
        if (trace) std.debug.print("[comp] {s}.{s} unknown head {s}\n", .{ identity, name, out.name });
        out.deinit(b.allocator);
        return null;
    }
    if (trace) std.debug.print("[comp] {s}.{s} -> {s}\n", .{ identity, name, out.name });
    return out;
}

/// The local whose own initializer is currently being typed. Its name is not
/// in scope there, so a bare call of that name inside the initializer resolves
/// past it. Saved and restored by `localInitTypeRef`, which nests.
pub var init_self_name: ?[]const u8 = null;

fn localInitTypeRef(b: *FuncBuilder, receiver: *const Expr) Allocator.Error!?ir.TypeRef {
    if (receiver.* != .Path or receiver.Path.segments.len != 1) return null;
    return localInitTypeRefNamed(b, receiver.Path.segments[0].name);
}

/// The by-name entry: a local's type derived from its RECORDED initializer.
/// A call initializer is never written into the local's declared type — it is
/// resolved here, on demand, at each use site. Anything asking "is this local
/// typed?" must come through here, not through the declared-type table alone.
pub fn localInitTypeRefNamed(b: *FuncBuilder, name: []const u8) Allocator.Error!?ir.TypeRef {
    if (b.resolve(name) == null) return null;
    const init_expr = b.localInitExpr(name) orelse {
        if (norecvCensusOn()) lm_localinit[0] += 1;
        return null;
    };
    // Same cycle as the declared-type walk: deriving one local's type can
    // reach back into it once every local in the block is bound.
    if (!pushInitChain(name)) return null;
    defer popInitChain();
    if (try ctorInitTypeRef(b, init_expr)) |ctor_ty| {
        if (norecvCensusOn()) lm_localinit[1] += 1;
        return ctor_ty;
    }
    // An ALIAS takes the source local's type, whatever gave the source its
    // own: `val alias = made` where `made` came from a call's return type.
    if (init_expr.* == .Path and init_expr.Path.segments.len == 1) {
        if (try localInitTypeRef(b, init_expr)) |aliased| {
            if (norecvCensusOn()) lm_localinit[1] += 1;
            return aliased;
        }
        // A bare own-member snapshot: `val slots = slots` (the local's own
        // name is not in scope inside its initializer, so the reference is
        // the enclosing class's property) or `val w = writer` under another
        // name. The property's declared head types the local exactly as the
        // qualified `this.slots` read would.
        const src_name = init_expr.Path.segments[0].name;
        if (b.resolve(src_name) == null or std.mem.eql(u8, src_name, name)) {
            if (b.ownerClass()) |owner| {
                if (propTypeHeadOn(b, owner, src_name)) |head| {
                    // Two same-simple-name classes (the gapbuffer and
                    // linkbuffer SlotWriters) make a bare head ambiguous;
                    // resolve it through the reading file's import graph to
                    // the declaring class's FQN when possible.
                    const resolved_name: []const u8 = blk: {
                        const file = init_expr.Path.segments[0].span.file;
                        const cid = b.module.classIdIndexed(typeHead(head), b.self_package, file) orelse
                            b.module.classId(typeHead(head)) orelse break :blk head;
                        if (cid.int() >= b.module.classes.items.len) break :blk head;
                        break :blk b.module.classes.items[cid.int()].fqn;
                    };
                    if (norecvCensusOn()) lm_localinit[1] += 1;
                    return ir.TypeRef{
                        .name = try b.allocator.dupe(u8, resolved_name),
                        .nullable = false,
                        .args = &.{},
                    };
                }
            }
        }
    }
    // A property read carries its own declared type; nothing needs resolving.
    if (init_expr.* == .Member) {
        if (argDeclTypeRef(b, init_expr)) |declared| {
            if (norecvCensusOn()) lm_localinit[1] += 1;
            return try declared.clone(b.allocator);
        }
    }
    // The local's own name is not in scope inside its own initializer, so the
    // initializer's bare calls must not see it. `val iterator = iterator()` is
    // the shape, and the local shadowing the call is what stopped 10,088 of
    // these from lending a type.
    const prev_self = init_self_name;
    if (b.localInitNameFree(name) and !std.mem.eql(u8, runtime.envOnce("KLIO_INIT_SELF") orelse "1", "0")) init_self_name = name;
    defer init_self_name = prev_self;
    var derived = (try staticCallReturnTypeRef(b, init_expr)) orelse {
        if (norecvCensusOn()) {
            lm_localinit[2] += 1;
            if (runtime.envOnce("KLIO_LI_NAMES") != null and init_expr.* == .Call) {
                const c = init_expr.Call.callee;
                if (c.* == .Path and c.Path.segments.len == 1) {
                    std.debug.print("[li-null] {s}\n", .{c.Path.segments[0].name});
                } else if (c.* == .Member) {
                    std.debug.print("[li-null] .{s}\n", .{c.Member.name.name});
                } else std.debug.print("[li-null] <{s}>\n", .{@tagName(std.meta.activeTag(c.*))});
            }
        }
        return null;
    };
    if (!staticClassifierArgsComplete(b, derived)) {
        if (norecvCensusOn()) lm_localinit[3] += 1;
        derived.deinit(b.allocator);
        return null;
    }
    if (norecvCensusOn()) lm_localinit[4] += 1;
    return derived;
}

/// The declared return of the UNIQUE nullary top-level extension of `mname`
/// applicable to the receiver head — the for-loop protocol's answer for a
/// receiver whose `iterator()` is an extension, not a member
/// (`CharSequence.iterator(): CharIterator`). Disagreeing or generic
/// returns refuse.
pub fn extensionNullaryReturnTypeRef(
    b: *FuncBuilder,
    recv_ty: ir.TypeRef,
    mname: []const u8,
    out_fid: ?*?ir.FuncId,
) Allocator.Error!?ir.TypeRef {
    const recv_head = typeHead(std.mem.trimEnd(u8, recv_ty.name, "?"));
    if (recv_head.len == 0) return null;
    var agreed: ?ir.TypeRef = null;
    var agreed_fid: ?ir.FuncId = null;
    for (b.module.funcsBySimpleName(mname)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.kind == .instance_method or f.kind == .member_extension) continue;
        if (f.params.len != 1 or !std.mem.eql(u8, f.params[0].name, "this")) continue;
        if (!b.module.classIsOrExtends(recv_head, typeHead(f.params[0].ty.name))) continue;
        if (!f.return_ty_declared or f.return_ty.name.len == 0 or
            bareTypeParamHead(f.return_ty.name))
        {
            if (agreed) |*prev| prev.deinit(b.allocator);
            return null;
        }
        if (agreed) |prev| {
            if (!std.mem.eql(u8, prev.name, f.return_ty.name)) {
                var p = prev;
                p.deinit(b.allocator);
                return null;
            }
            // Same return on a MORE SPECIFIC receiver keeps the more
            // specific declaration (String over CharSequence).
            if (b.module.funcById(agreed_fid.?)) |pf| {
                if (b.module.classIsOrExtends(typeHead(f.params[0].ty.name), typeHead(pf.params[0].ty.name)))
                    agreed_fid = fid;
            }
        } else {
            agreed = try f.return_ty.clone(b.allocator);
            agreed_fid = fid;
        }
    }
    if (out_fid) |slot| slot.* = agreed_fid;
    return agreed;
}

/// The trailing lambda's derived RETURN under concrete input param types —
/// a census-quiet probe. Serves the RECORDER-level star patch only: it
/// never feeds overload shapes (the shape-level variant measured
/// net-negative and is recorded as such in the plan).
fn lambdaReturnUnderParams(
    b: *FuncBuilder,
    lam_expr: *const Expr,
    in_tys: []const ir.TypeRef,
) Allocator.Error!?ir.TypeRef {
    if (lam_expr.* != .Lambda) return null;
    const lam = lam_expr.Lambda;
    const stmts = lam.body.stmts;
    if (stmts.len == 0 or stmts[stmts.len - 1] != .Expr) return null;
    if (od_depth >= 4) return null;
    var nb = try FuncBuilder.init(b.allocator, b.module);
    nb.census_quiet = true;
    defer nb.deinit();
    {
        var dit = b.local_decl_types.iterator();
        while (dit.next()) |e2| {
            nb.setLocalDeclTypeOwned(e2.key_ptr.*, e2.value_ptr.clone(b.allocator) catch continue) catch {};
        }
    }
    var i: usize = 0;
    while (i < in_tys.len) : (i += 1) {
        const pname = if (lam.params.len == 0 and in_tys.len == 1)
            "it"
        else if (i < lam.params.len)
            lam.params[i].name
        else
            return null;
        const dh = typeHead(std.mem.trimEnd(u8, in_tys[i].name, "?"));
        if (dh.len == 0 or bareTypeParamHead(dh) or
            ir.parseClassTypeParamIdentity(dh) != null) return null;
        nb.setLocalDeclTypeOwned(pname, in_tys[i].clone(b.allocator) catch return null) catch return null;
    }
    od_depth += 1;
    defer od_depth -= 1;
    const t = staticExprTypeRef(&nb, &stmts[stmts.len - 1].Expr) catch null;
    if (t) |ty| {
        const th = typeHead(std.mem.trimEnd(u8, ty.name, "?"));
        if (th.len == 0 or bareTypeParamHead(th) or
            ir.parseClassTypeParamIdentity(th) != null)
        {
            var tt = ty;
            tt.deinit(b.allocator);
            return null;
        }
    }
    return t;
}

/// RECORDER-level star patch: a recorded call-return whose args contain
/// `*` (an unbound RETURN-position type parameter, star-erased by the
/// solve) re-derives the star from the call's trailing lambda when the
/// committed candidate's fn-typed last param returns exactly that
/// parameter (`groupBy(keySelector: (T) -> K): Map<K, List<T>>`). The
/// patch runs AFTER resolution — it improves the recorded local type and
/// feeds no overload shape.
pub fn patchStarredCallRecord(
    b: *FuncBuilder,
    recorded: *ir.TypeRef,
    call_expr: *const Expr,
) Allocator.Error!void {
    if (call_expr.* != .Call) return;
    const call = call_expr.Call;
    if (call.args.len == 0 or call.args[call.args.len - 1] != .Lambda) return;
    if (!allNull(call.arg_names)) return;
    var has_star = false;
    for (recorded.args) |ra| {
        if (std.mem.eql(u8, ra.name, "*")) has_star = true;
    }
    if (!has_star) return;
    if (call.callee.* != .Member) return;
    const mname = call.callee.Member.name.name;
    // The committed candidate: the receiver's unique lambda-hosting
    // extension of the name and shape.
    var recv_owned = (try staticExprTypeRef(b, call.callee.Member.receiver)) orelse return;
    defer recv_owned.deinit(b.allocator);
    const recv_head = typeHead(std.mem.trimEnd(u8, recv_owned.name, "?"));
    var target: ?FuncId = null;
    for (b.module.funcsBySimpleName(mname)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.kind == .instance_method or f.kind == .member_extension) continue;
        if (f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this")) continue;
        if (f.params.len - 1 != call.args.len) continue;
        if (!b.module.classIsOrExtends(recv_head, typeHead(f.params[0].ty.name))) continue;
        const lpt = f.params[f.params.len - 1].ty;
        const lph = typeHead(std.mem.trimEnd(u8, lpt.name, "?"));
        if (!std.mem.startsWith(u8, lph, "Function") and
            !std.mem.eql(u8, lph, "<function>")) continue;
        if (target != null) return;
        target = fid;
    }
    const tfid = target orelse return;
    const tf = b.module.funcById(tfid) orelse return;
    const lpt = tf.params[tf.params.len - 1].ty;
    if (lpt.args.len < 1) return;
    var rname = std.mem.trimEnd(u8, lpt.args[lpt.args.len - 1].name, "?");
    if (std.mem.startsWith(u8, rname, "in#")) rname = rname[3..];
    if (std.mem.startsWith(u8, rname, "out#")) rname = rname[4..];
    if (!bareTypeParamHead(rname)) return;
    // The starred position in the record must be exactly where the
    // declared return spells that parameter.
    if (!tf.return_ty_declared or tf.return_ty.args.len != recorded.args.len) return;
    var scratch = std.heap.ArenaAllocator.init(b.allocator);
    defer scratch.deinit();
    const a2 = scratch.allocator();
    const solved = (b.module.solveCallBindings(a2, tfid, tf, recv_owned, null, &.{}, &.{}, false) catch null) orelse return;
    const n_in = lpt.args.len - 1;
    const in_tys = a2.alloc(ir.TypeRef, n_in) catch return;
    for (lpt.args[0..n_in], in_tys) |raw, *slot| {
        slot.* = ir.Module.substituteBoundType(a2, raw, solved.bindings) catch return;
    }
    var lr = (try lambdaReturnUnderParams(b, &call.args[call.args.len - 1], in_tys)) orelse return;
    defer lr.deinit(b.allocator);
    for (tf.return_ty.args, recorded.args) |decl_arg, *rec_arg| {
        if (!std.mem.eql(u8, rec_arg.name, "*")) continue;
        var dn = std.mem.trimEnd(u8, decl_arg.name, "?");
        if (std.mem.startsWith(u8, dn, "in#")) dn = dn[3..];
        if (std.mem.startsWith(u8, dn, "out#")) dn = dn[4..];
        if (!std.mem.eql(u8, dn, rname)) continue;
        const patched = lr.clone(b.allocator) catch return;
        rec_arg.deinit(b.allocator);
        rec_arg.* = patched;
    }
}

/// The UNIQUE in-scope type-param bound whose class declares property `nm`
/// — the implicit-receiver chase's answer when the splice window's head is
/// a bare param with no bound record of its own.
fn implBoundScan(b: *FuncBuilder, nm: []const u8) ?[]const u8 {
    const bounds = (b.typeParamBoundsSlice() catch null) orelse return null;
    defer b.allocator.free(bounds);
    var hit: ?[]const u8 = null;
    for (bounds) |tb| {
        const bh = typeHead(std.mem.trimEnd(u8, tb.bound, "?"));
        if (bh.len == 0 or bh.len <= 2) continue;
        if (propTypeRefOn(b, bh, nm) != null or
            b.module.registry.class_prop_type_heads.get(.{ .a = bh, .b = nm }) != null)
        {
            if (hit != null) return null;
            hit = bh;
        }
    }
    return hit;
}

/// Lambda-param types for a CONSTRUCTOR call's lambda arguments, read from
/// the class's primary params whose declared types are CONCRETE function
/// types. Positional args only; a param mentioning a type parameter or the
/// suspend marker contributes nothing.
fn ctorLambdaParamTypes(
    b: *FuncBuilder,
    class_id: ir.ClassId,
    args: []const Expr,
) Allocator.Error!?[]?[]ir.TypeRef {
    if (class_id.int() >= b.module.classes.items.len) return null;
    const cls = &b.module.classes.items[class_id.int()];
    if (args.len == 0) return null;
    if (runtime.envOnce("KLIO_CTORLPT_TRACE") != null) {
        std.debug.print("[ctorlpt] {s} nparams={d} p_last_ty={s}<{d}>\n", .{ cls.name, cls.primary_params.len, if (cls.primary_params.len != 0) cls.primary_params[cls.primary_params.len - 1].ty.name else "-", if (cls.primary_params.len != 0) cls.primary_params[cls.primary_params.len - 1].ty.args.len else 0 });
    }
    // The array ctors' trailing init lambda takes the element INDEX
    // whatever the class row records (the (size, init) form is an
    // intrinsic, not the row's primary constructor).
    {
        const n = cls.name;
        const is_array_ctor = std.mem.eql(u8, n, "Array") or
            (std.mem.endsWith(u8, n, "Array") and isPrimitiveTypeName(n[0 .. n.len - "Array".len]));
        if (is_array_ctor and args.len == 2 and args[args.len - 1] == .Lambda) {
            const out0 = try b.allocator.alloc(?[]ir.TypeRef, args.len);
            @memset(out0, null);
            errdefer deinitArgLambdaParamTypes(b.allocator, out0);
            const tys0 = try b.allocator.alloc(ir.TypeRef, 1);
            tys0[0] = .{ .name = try b.allocator.dupe(u8, "Int"), .nullable = false, .args = &.{} };
            out0[args.len - 1] = tys0;
            return out0;
        }
    }
    if (cls.primary_params.len == 0) return null;
    var any = false;
    const out = try b.allocator.alloc(?[]ir.TypeRef, args.len);
    @memset(out, null);
    errdefer deinitArgLambdaParamTypes(b.allocator, out);
    for (args, 0..) |*arg, i| {
        if (arg.* != .Lambda) continue;
        if (i >= cls.primary_params.len) break;
        const pt = cls.primary_params[i].ty;
        const head = typeHead(std.mem.trimEnd(u8, pt.name, "?"));
        if (!std.mem.startsWith(u8, head, "Function") and
            !std.mem.eql(u8, head, "<function>")) continue;
        if (pt.args.len < 2) continue;
        const value_ins = pt.args[0 .. pt.args.len - 1];
        var ok = true;
        for (value_ins) |vi| {
            const h2 = typeHead(std.mem.trimEnd(u8, vi.name, "?"));
            if (h2.len == 0 or h2[0] == '#' or bareTypeParamHead(h2) or
                ir.parseClassTypeParamIdentity(h2) != null)
            {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        const tys = try b.allocator.alloc(ir.TypeRef, value_ins.len);
        var filled: usize = 0;
        errdefer {
            for (tys[0..filled]) |*t| t.deinit(b.allocator);
            b.allocator.free(tys);
        }
        for (value_ins) |vi| {
            tys[filled] = try vi.clone(b.allocator);
            filled += 1;
        }
        out[i] = tys;
        any = true;
    }
    if (!any) {
        b.allocator.free(out);
        return null;
    }
    return out;
}

/// The lambda-param types a fun-interface SAM conversion hands its sole
/// lambda argument: the interface's single abstract method's value-param
/// types, substituted under the class's type params as bound by the call's
/// explicit type arguments or the site's EXPECTED type. Null when neither
/// binds, when the interface has no sole abstract method, or when the
/// method takes no value params.
fn samLambdaParamTypes(
    b: *FuncBuilder,
    class_id: ir.ClassId,
    ast_type_args: []const ast.TypeRef,
) Allocator.Error!?[]?[]ir.TypeRef {
    if (class_id.int() >= b.module.classes.items.len) return null;
    const cls = &b.module.classes.items[class_id.int()];
    const st = runtime.envOnce("KLIO_SAM_TRACE") != null;
    var sam_fid: ?FuncId = null;
    for (cls.methods) |mfid| {
        const mf0 = b.module.funcById(mfid) orelse continue;
        if (mf0.hasBody()) continue;
        if (sam_fid != null) {
            if (st) std.debug.print("[sam-in] multi-abstract {s} + {s}\n", .{ b.module.funcById(sam_fid.?).?.name, mf0.name });
            return null;
        }
        sam_fid = mfid;
    }
    // An image class row can carry no method list (lazy header); the
    // member registry still records the interface's declared methods.
    if (sam_fid == null) {
        var prefix_buf: [160]u8 = undefined;
        const prefix = std.fmt.bufPrint(&prefix_buf, "{s}\x00", .{cls.name}) catch return null;
        var it = b.module.registry.member_method_fids.iterator();
        while (it.next()) |e| {
            if (!std.mem.startsWith(u8, e.key_ptr.*, prefix)) continue;
            const mf0 = b.module.funcById(e.value_ptr.*) orelse continue;
            if (mf0.hasBody()) continue;
            if (sam_fid != null and sam_fid.?.int() != e.value_ptr.int()) {
                if (st) std.debug.print("[sam-in] registry multi-abstract\n", .{});
                return null;
            }
            sam_fid = e.value_ptr.*;
        }
    }
    if (st) std.debug.print("[sam-in] methods={d} sam={}\n", .{ cls.methods.len, sam_fid != null });
    const mf = b.module.funcById(sam_fid orelse return null) orelse return null;
    const base: usize = if (mf.params.len != 0 and std.mem.eql(u8, mf.params[0].name, "this")) 1 else 0;
    if (mf.params.len == base) return null;
    var scratch = std.heap.ArenaAllocator.init(b.allocator);
    defer scratch.deinit();
    const a = scratch.allocator();
    var binds: std.ArrayList(ir.Module.TypeBinding) = .empty;
    if (ast_type_args.len == cls.type_params.len and ast_type_args.len != 0) {
        for (cls.type_params, ast_type_args) |tp, *ta| {
            const ty = try decl_mod.loweredTypeRef(a, ta, true);
            try binds.append(a, .{ .name = tp, .ty = ty });
            // The registry may spell the method's params with the class
            // identity mangle; bind that spelling too.
            try binds.append(a, .{ .name = try ir.classTypeParamIdentity(a, class_id, tp), .ty = ty });
        }
    } else if (b.peekExpected()) |exp| {
        if (exp.function == null and exp.type_args.len == cls.type_params.len and
            exp.type_args.len != 0 and std.mem.eql(u8, exp.name.name, cls.name))
        {
            for (cls.type_params, exp.type_args) |tp, ta| {
                if (ta.is_star) return null;
                const ty = try decl_mod.loweredTypeRef(a, &ta.ty, true);
                try binds.append(a, .{ .name = tp, .ty = ty });
                try binds.append(a, .{ .name = try ir.classTypeParamIdentity(a, class_id, tp), .ty = ty });
            }
        }
    }
    if (st and binds.items.len == 0) {
        if (b.peekExpected()) |exp| std.debug.print("[sam-in] nobind exp_name={s} exp_targs={d} exp_fn={}\n", .{ exp.name.name, exp.type_args.len, exp.function != null })
        else std.debug.print("[sam-in] nobind noexp\n", .{});
    }
    if (binds.items.len == 0) return null;
    const out = try b.allocator.alloc(?[]ir.TypeRef, 1);
    out[0] = null;
    errdefer b.allocator.free(out);
    const tys = try b.allocator.alloc(ir.TypeRef, mf.params.len - base);
    var filled: usize = 0;
    errdefer {
        for (tys[0..filled]) |*t| t.deinit(b.allocator);
        b.allocator.free(tys);
    }
    for (mf.params[base..]) |*p2| {
        const sub = try ir.Module.substituteBoundType(a, p2.ty, binds.items);
        tys[filled] = try sub.clone(b.allocator);
        filled += 1;
    }
    out[0] = tys;
    return out;
}

/// The companion object's own class type for a bare class-name reference in
/// value position, or null when the name is shadowed by a value binding or
/// names no class with a companion.
fn companionObjectTypeRef(b: *FuncBuilder, seg: ast.Ident) Allocator.Error!?ir.TypeRef {
    const nm = seg.name;
    if (nm.len == 0 or !std.ascii.isUpper(nm[0])) return null;
    if (b.resolve(nm) != null or b.knowsOuter(nm) or b.isLocalFn(nm) or b.isParam(nm)) return null;
    const cid = b.module.classIdIndexed(nm, b.self_package, seg.span.file) orelse
        b.module.uniqueClassIdBySimpleName(nm) orelse return null;
    if (cid.int() >= b.module.classes.items.len) return null;
    const cls = &b.module.classes.items[cid.int()];
    const comp = b.module.registry.companion_singletons.get(cls.fqn) orelse
        b.module.registry.companion_singletons.get(cls.name) orelse return null;
    const ccid = b.module.classIdByFqn(comp) orelse
        b.module.uniqueClassIdBySimpleName(comp) orelse return null;
    if (ccid.int() >= b.module.classes.items.len) return null;
    return .{
        .name = try b.allocator.dupe(u8, b.module.classes.items[ccid.int()].fqn),
        .nullable = false,
        .args = &.{},
    };
}

pub fn buildStaticReturnArgShapes(
    b: *FuncBuilder,
    args: []const Expr,
    arg_names: []const ?[]const u8,
) Allocator.Error!StaticReturnArgShapes {
    const shapes = try buildStaticArgShapes(b, args, arg_names);
    errdefer b.allocator.free(shapes);
    const inferred = try b.allocator.alloc(?ir.TypeRef, args.len);
    @memset(inferred, null);
    errdefer {
        for (inferred) |*ty| {
            if (ty.*) |*owned| owned.deinit(b.allocator);
        }
        b.allocator.free(inferred);
    }
    for (args, shapes, inferred) |*arg, *shape, *owned| {
        if (shape.ty != null) {
            // A bare class-name Path pre-typed as the class ITSELF is really
            // the companion value (Kotlin: a class name in value position IS
            // its companion). The companion's class record — which carries
            // its supertypes — is what a key-parameter solve projects from
            // (`context[ContinuationInterceptor]` binds E through the
            // companion's `CoroutineContext.Key<ContinuationInterceptor>`).
            if (arg.* == .Path and arg.Path.segments.len == 1 and
                std.mem.eql(u8, typeHead(std.mem.trimEnd(u8, shape.ty.?.name, "?")), arg.Path.segments[0].name))
            {
                if (try companionObjectTypeRef(b, arg.Path.segments[0])) |ct| {
                    owned.* = ct;
                    shape.ty = ct;
                    shape.ty_authoritative = true;
                }
            }
            continue;
        }
        // A callable reference's function type is declaration-read and can
        // disambiguate the outer overload set, so it is shaped BEFORE any
        // resolution commits (the expected-arity refinement in
        // enrichCallableRefArgShapes serves the cases the probe declines).
        if (arg.* == .MemberRef and !std.mem.eql(u8, runtime.envOnce("KLIO_REFSHAPE") orelse "1", "0")) {
            owned.* = try callableRefDeclTypeRef(b, &arg.MemberRef, null);
        } else if (arg.* == .Path and arg.Path.segments.len == 1) {
            // A bare class name in VALUE position is its companion object
            // (`context[ContinuationInterceptor]` passes the companion,
            // whose class extends `CoroutineContext.Key<ContinuationInterceptor>`
            // — the record the key-parameter solve projects E from).
            owned.* = try companionObjectTypeRef(b, arg.Path.segments[0]);
        } else {
            owned.* = try staticCallReturnTypeRef(b, arg);
        }
        if (owned.*) |ty| {
            shape.ty = ty;
            // A CALL-RETURN derivation whose head is a bare type parameter
            // names the CALLEE's parameter, not the caller's: judging it
            // against the caller's same-named bound conflates scopes (a
            // method-level `T : CharSequence` shadowing the class's
            // `T : Number` disproved the Number overload kotlinc picks).
            // Keep it advisory — it types, but never disproves.
            const th = typeHead(std.mem.trimEnd(u8, ty.name, "?"));
            shape.ty_authoritative = !(bareTypeParamHead(th) or ir.parseClassTypeParamIdentity(th) != null);
        }
    }
    return .{ .shapes = shapes, .inferred = inferred };
}

/// Build the `[]ArgShape` for a call's argument list once, before the
/// `resolveCall` query, replacing the per-rung `findCand` / `arityMatch`
/// walks. Borrows from `b.allocator` (a lowering scratch arena).
fn buildArgShapes(b: *FuncBuilder, args: []const Expr, arg_names: []const ?[]const u8) Allocator.Error![]applicability.ArgShape {
    const shapes = try b.allocator.alloc(applicability.ArgShape, args.len);
    for (args, 0..) |*a, i| {
        const nm: ?[]const u8 = if (i < arg_names.len) arg_names[i] else null;
        shapes[i] = shapeOfAstArg(b, a, nm);
    }
    return shapes;
}

/// Argument shapes admitted by an exact/static dispatch proof. The permissive
/// eager type-head fill remains useful for additive runtime ranking, but only
/// declared, cast, literal, and constructor evidence may reject a candidate.
fn buildStaticArgShapes(
    b: *FuncBuilder,
    args: []const Expr,
    arg_names: []const ?[]const u8,
) Allocator.Error![]applicability.ArgShape {
    const shapes = try buildArgShapes(b, args, arg_names);
    for (args, shapes) |*arg, *shape| {
        shape.ty = argDeclTypeRefLazy(b, arg);
        if (runtime.envOnce("KLIO_VALTY_TRACE")) |w| {
            if (arg.* == .Path and arg.Path.segments.len == 1 and std.mem.eql(u8, arg.Path.segments[0].name, w)) {
                std.debug.print("[valty] SHAPE {s} ty={s} in={s}\n", .{ w, if (shape.ty) |t| t.name else "<null>", build.currentRealFn() orelse "-" });
            }
        }
        shape.ty_authoritative = shape.ty != null;
    }
    return shapes;
}

/// Builtin value kind a declared parameter type accepts, or null when unknown
/// (a user class, a type parameter, `Any`, …) — those never disprove.
fn paramLitKind(type_name: []const u8) ?LitKind {
    const n = std.mem.trimEnd(u8, type_name, "?");
    const eq = std.mem.eql;
    if (eq(u8, n, "Int") or eq(u8, n, "Long") or eq(u8, n, "Short") or eq(u8, n, "Byte") or
        eq(u8, n, "UInt") or eq(u8, n, "ULong") or eq(u8, n, "UShort") or eq(u8, n, "UByte") or
        eq(u8, n, "Double") or eq(u8, n, "Float") or eq(u8, n, "Number")) return .numeric;
    if (eq(u8, n, "String") or eq(u8, n, "CharSequence")) return .string;
    if (eq(u8, n, "Boolean")) return .boolean;
    if (eq(u8, n, "Char")) return .char;
    return null;
}

/// True when a same-name factory's declared parameter types DEFINITELY cannot
/// accept the argument kinds — so the bare `Name(args)` constructs the class
/// rather than calling the factory. The argument kind comes from the same
/// evidence the shared scorer sees: a literal (direct or through a recorded
/// local initializer), a declared local/param type head, or the typeck
/// type-head channel (`Box(s.length)` inside `fun Box(s: String)` proves Int
/// against the factory's String and constructs the class). Conservative: an
/// unknown argument or parameter kind never disproves, so only a
/// known-kind-vs-builtin mismatch flips the decision.
fn factorySigRejectsArgs(b: *FuncBuilder, sig: []const ir.TypeRef, args: []const Expr) bool {
    for (args, 0..) |*a, i| {
        if (i >= sig.len) break;
        var ak_opt = argEvidenceLitKind(b, a);
        if (ak_opt == null) {
            if (argDeclTypeRef(b, a)) |ty| ak_opt = paramLitKind(ty.name);
        }
        const ak = ak_opt orelse continue;
        const pk = paramLitKind(sig[i].name) orelse continue;
        if (ak != pk) return true;
    }
    return false;
}

fn shadowedByClass(b: *FuncBuilder, callee: *const Expr, args: []const Expr) Allocator.Error!bool {
    if (callee.* != .Path or callee.Path.segments.len != 1) return false;
    const name = callee.Path.segments[0].name;
    // A LOCAL fn of the name (declared in an enclosing body — a test's
    // `@Composable fun Composition(a, b, c)`) is the nearest scope: it
    // shadows any same-named classifier (the pack's `interface
    // Composition`) for a bare call.
    if (b.local_fn_overloads.getPtr(name) != null) return false;
    // Resolve the class the SAME way the construct path below does — through
    // the scope-aware index (file imports, then self package, then global) —
    // not the simple-name-global `classId`, which picks an arbitrary winner on
    // a cross-package simple-name collision. Otherwise a bare `Name(args)` here
    // can be judged against the wrong same-named class (e.g. an abstract
    // `kotlinx.coroutines.internal.Segment` shadowing the concrete
    // `kotlinx.io.Segment` at its own construction site), inverting the
    // ctor-vs-factory decision.
    const cid = b.module.classIdIndexed(name, b.self_package, callee.Path.segments[0].span.file) orelse {
        if (runtime.envOnce("KLIO_SBC_TRACE")) |w| if (std.mem.eql(u8, w, name)) {
            std.debug.print("[sbc] {s} no-cid file={d}\n", .{ name, callee.Path.segments[0].span.file.int() });
        };
        return false;
    };
    if (runtime.envOnce("KLIO_SBC_TRACE")) |w| if (std.mem.eql(u8, w, name)) {
        const abs = cid.int() < b.module.classes.items.len and b.module.classes.items[cid.int()].is_abstract;
        std.debug.print("[sbc] {s} cid={d} abstract={} nargs={d} file={d}\n", .{ name, cid.int(), abs, args.len, callee.Path.segments[0].span.file.int() });
    };
    if (runtime.envOnce("KLIO_NU_TRACE") != null and std.mem.eql(u8, name, "Density")) {
        const abs = cid.int() < b.module.classes.items.len and b.module.classes.items[cid.int()].is_abstract;
        std.debug.print("[sbc] Density cid={d} abstract={} owner={s}\n", .{ cid.int(), abs, b.ownerClass() orelse "-" });
    }
    // An abstract/interface/sealed class cannot be constructed, so a bare
    // `Name(args)` is never a constructor call — it is a same-named factory
    // function (`fun Random(seed): Random`). Resolve it as a function (the
    // runtime global lookup finds the factory) rather than emitting a
    // `NewInstance` that aborts on the abstract class at run time.
    if (cid.int() < b.module.classes.items.len and b.module.classes.items[cid.int()].is_abstract) return false;
    const nargs = args.len;
    // Scope rule (spec: overload resolution walks scopes inside-out): inside
    // the class's own body — including its companion — the class's
    // constructor is a nearer-scope candidate than any same-named
    // package-level factory, so an applicable constructor decides the call.
    // `Path(normalized)` inside `Path.of` binds the private constructor; the
    // `fun Path(String)` factory calling back into `of` would recurse.
    if (b.ownerClass()) |oc| {
        // A companion body's owner is the lifted companion class; its name is
        // the class name with one or more `$Companion` suffixes. Stripping
        // them recovers the class whose scope the call sits in.
        var oc_base: []const u8 = oc;
        while (std.mem.endsWith(u8, oc_base, "$Companion")) {
            oc_base = oc_base[0 .. oc_base.len - "$Companion".len];
        }
        const in_own_scope = std.mem.eql(u8, oc_base, name) or blk: {
            if (cid.int() < b.module.classes.items.len) {
                if (b.module.classes.items[cid.int()].companion) |comp| {
                    if (comp.int() < b.module.classes.items.len) {
                        break :blk std.mem.eql(u8, b.module.classes.items[comp.int()].name, oc);
                    }
                }
            }
            break :blk false;
        };
        if (in_own_scope and cid.int() < b.module.classes.items.len) {
            const ps = b.module.classes.items[cid.int()].primary_params;
            var required: usize = 0;
            var has_vararg = false;
            for (ps) |*p| {
                if (p.is_vararg) {
                    has_vararg = true;
                    continue;
                }
                if (!p.has_default) required += 1;
            }
            if (nargs >= required and (has_vararg or nargs <= ps.len)) return true;
        }
    }
    // Scope rule: a MEMBER of the enclosing class hierarchy is a nearer-scope
    // candidate than a same-named foreign classifier — a bare `Test(...)`
    // inside a class declaring `fun Test(...)` calls the member, never
    // constructs an imported `kotlin.test.Test`. A class NESTED in the
    // enclosing chain keeps constructor semantics: its bare name also sits in
    // the member set, but a capitalized call to it is a constructor. Deciding
    // `false` here routes the call through `CallMemberOrGlobal`, whose runtime
    // scoring still reaches the constructor when no member actually binds.
    if (runtime.envOnce("KLIO_SBC_TRACE") != null) {
        std.debug.print("[sbc] {s} owner={s} own={} encl={} nested={}\n", .{ name, b.ownerClass() orelse "-", b.hasOwnMember(name), b.hasEnclosingMember(name), classNestedInEnclosing(b, cid) });
    }
    if (enclosingHasMemberNamed(b, name) and !classNestedInEnclosing(b, cid)) return false;
    // Scope rule: a captured outer binding of the name (a local `fun Test`
    // declared in an enclosing body, reaching this closure as a capture) is
    // a nearer-scope candidate than an imported classifier — `Test(1, 2)`
    // inside `r.go { … }` calls the local function, never constructs
    // `kotlin.test.Test`. Deciding false routes through the deferred
    // class-carrying form, whose runtime shadow gate lets the captured
    // callable win and still reaches the constructor when nothing binds.
    if (b.resolve(name) == null and (b.knowsOuter(name) or isLowerAnonCapture(name))) return false;
    // Only IN-SCOPE factories compete with the constructor: kotlinc never
    // considers an unimported cross-package `fun String(bytes, …)` (io.ktor's)
    // against `String(chars)` written in kotlin.text — without the tier
    // filter, pack load ORDER decided whether the builtin ctor won.
    const call_file = callee.Path.segments[0].span.file;
    if (lastArgIsLambda(args)) {
        // A trailing lambda routes to a same-named factory with a
        // function-typed param to receive it; only when none fits is it a ctor.
        var factory_takes_lambda = false;
        for (b.module.func_index.items) |entry| {
            if (!std.mem.eql(u8, entry.name, name)) continue;
            const f = b.module.funcById(entry.id) orelse continue;
            if (b.module.scopeTier(f.fqn, f.package, name, b.self_package, call_file) > 3) continue;
            const last_vararg = f.params.len != 0 and f.params[f.params.len - 1].is_vararg;
            const arity_ok = last_vararg or nargs <= f.params.len;
            if (arity_ok and anyFunctionParam(f.params)) {
                factory_takes_lambda = true;
                break;
            }
        }
        return !factory_takes_lambda;
    }
    // No lambda — ctor when the canonical factory can't take that many args,
    // or no same-named factory is applicable to the positional count.
    var canonical_cant_take = false;
    if (b.module.funcId(name)) |fid| {
        if (b.module.funcById(fid)) |f| {
            const last_vararg = f.params.len != 0 and f.params[f.params.len - 1].is_vararg;
            canonical_cant_take = !last_vararg and nargs > f.params.len;
        }
    }
    var any_factory_applicable = false;
    for (b.module.func_index.items) |entry| {
        if (!std.mem.eql(u8, entry.name, name)) continue;
        if (b.module.funcById(entry.id)) |ff| {
            if (b.module.scopeTier(ff.fqn, ff.package, name, b.self_package, call_file) > 3) continue;
        }
        if (b.module.decl_user_arity.get(entry.id.int())) |arity| {
            const n: u32 = @intCast(nargs);
            if (n >= arity.required and (arity.has_vararg or n <= arity.total)) {
                // A same-arity factory whose declared parameter types
                // definitely cannot accept the literal argument types is not
                // applicable — the call constructs the class instead. This is
                // what tells `Box(5)` (ctor `Box(Int)`) from the same-arity
                // factory `fun Box(s: String)`.
                if (b.module.decl_user_sig.get(entry.id.int())) |sig| {
                    if (factorySigRejectsArgs(b, sig, args)) continue;
                }
                any_factory_applicable = true;
                break;
            }
        }
    }
    return canonical_cant_take or !any_factory_applicable;
}

/// Whether the enclosing class scope (own members, outer-class members, or
/// the supertype hierarchy) declares a member named `name`.
/// Whether the enclosing class declares primary-ctor property `rn` with a
/// declared type that is a BARE class type parameter (`val expected: T` on
/// `CompareContext<out T>`). Such a receiver's member surface is the
/// parameter's bound; an in-scope receiver-taking callable of the called
/// name is what kotlinc commits.
fn classPropertyIsBareTp(b: *FuncBuilder, class_name: []const u8, rn: []const u8) ?bool {
    const cid = (if (std.mem.indexOfScalar(u8, class_name, '.') != null)
        b.module.classIdByFqn(class_name)
    else
        b.module.classId(class_name)) orelse return null;
    if (cid.int() >= b.module.classes.items.len) return null;
    const class = &b.module.classes.items[cid.int()];
    for (class.primary_params) |*p| {
        if (!std.mem.eql(u8, p.name, rn)) continue;
        var h = std.mem.trimEnd(u8, p.ty.name, "?");
        if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
        if (ir.parseClassTypeParamIdentity(h) != null) return true;
        for (class.type_params) |tp| {
            if (std.mem.eql(u8, h, tp)) return true;
        }
        return false;
    }
    return null;
}

/// The enclosing class — or any implicit receiver on the TOWER (a closure
/// body inside a member-inline splice reaches the owner only through it) —
/// declares primary-ctor property `rn` with a declared type that is a BARE
/// class type parameter (`val expected: T` on `CompareContext<out T>`).
fn enclosingPropertyBareTp(b: *FuncBuilder, rn: []const u8) bool {
    if (b.ownerClass()) |owner| {
        if (classPropertyIsBareTp(b, owner, rn)) |ans| return ans;
    }
    for (b.implicit_receiver_tower.items) |entry| {
        if (classPropertyIsBareTp(b, entry.head, rn)) |ans| return ans;
    }
    return false;
}

pub fn enclosingHasMemberNamed(b: *FuncBuilder, name: []const u8) bool {
    if (b.hasOwnMember(name) or b.hasEnclosingMember(name)) return true;
    const oc = b.ownerClass() orelse return false;
    const hs = b.module.registry.hierarchy_shadow_names.get(oc) orelse return false;
    return hs.names.contains(name);
}

/// Whether class `cid` is declared inside the enclosing class chain (a
/// nested/inner class of the class being lowered or of one of its outers).
fn classNestedInEnclosing(b: *FuncBuilder, cid: ir.ClassId) bool {
    if (cid.int() >= b.module.classes.items.len) return false;
    const cls_name = b.module.classes.items[cid.int()].name;
    const enc = b.module.registry.enclosing_class.get(cls_name) orelse return false;
    var owner = b.ownerClass();
    var hops: usize = 0;
    while (owner) |o| : (hops += 1) {
        if (hops > 32) break;
        if (std.mem.eql(u8, o, enc)) return true;
        owner = b.module.registry.enclosing_class.get(o);
    }
    return false;
}

fn anyFunctionParam(params: []const ir.Param) bool {
    for (params) |p| {
        if (std.mem.startsWith(u8, p.ty.name, "Function")) return true;
    }
    return false;
}

/// Path-callee bare-name → Call ladder. Returns null when no top-level fn /
/// the class path should handle it instead.
/// The read side of a `var x by D` local: dispatch `D.getValue(null, ::x)` when
/// the hidden delegate binding is reachable here — bound in this scope, or
/// captured from an enclosing one. Null when `x` is not a mutable delegated
/// local (a plain local, or a `val x by lazy`, whose eager-once value stands).
fn lowerDelegateRead(b: *FuncBuilder, name: []const u8) Allocator.Error!?Reg {
    var namebuf: [512]u8 = undefined;
    const dname_stack = std.fmt.bufPrint(&namebuf, "{s}$klio_delegate", .{name}) catch return null;
    const in_scope = b.resolve(dname_stack) != null;
    const outer = b.knowsOuter(dname_stack);
    if (!in_scope and !outer) return null;
    // An inner plain binding (a lambda/splice parameter, a shadowing
    // local) named like the delegated var outranks the delegate read.
    if (b.plainShadowsDelegate(name, dname_stack)) return null;
    const dname = try b.allocator.dupe(u8, dname_stack);
    const delegate = if (in_scope) b.resolve(dname).? else try resolveCapture(b, dname);
    const null_arg = try b.emitConst(.Null);
    const prop_ref = b.allocReg();
    const pname = try b.module.internConst(b.allocator, .{ .String = name });
    try b.push(.{ .PropertyRef = .{ .dst = prop_ref, .name = pname } });
    const args_start = b.allocReg();
    try b.push(.{ .Move = .{ .dst = args_start, .src = null_arg } });
    _ = b.allocReg();
    try b.push(.{ .Move = .{ .dst = Reg.from(args_start.int() + 1), .src = prop_ref } });
    const dst = b.allocReg();
    const getter = try b.module.internConst(b.allocator, .{ .String = "getValue" });
    try b.push(.{ .CallMember = .{
        .dst = dst,
        .receiver = delegate,
        .name = getter,
        .args = args_start,
        .n_args = 2,
        .arg_names = &.{},
    } });
    return dst;
}

/// Among the same-named EXTENSION overloads of `name`, the one whose leading
/// `this` receiver type matches the enclosing extension's receiver type. Lets an
/// ambiguous bare call inside an extension body resolve its arity/receiver-lambda
/// shape. Null when no enclosing receiver type is known or no single overload
/// matches.
/// Whether any same-named EXTENSION whose declared receiver head matches the
/// enclosing receiver type accepts `n_args` value arguments. Kotlin checks
/// implicit-receiver candidates before no-receiver ones, so such an extension
/// shadows a same-named file-private top-level function.
fn extOnEnclosingReceiverApplies(b: *FuncBuilder, name: []const u8, n_args: usize) bool {
    const recv = b.enclosingRecvTy() orelse return false;
    const recv_simple = simpleTypeHead(recv);
    const ids = b.module.func_name_index.get(name) orelse return false;
    for (ids.items) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this")) continue;
        if (!std.mem.eql(u8, simpleTypeHead(f.params[0].ty.name), recv_simple)) continue;
        const user_params = f.params.len - 1;
        var required: usize = 0;
        for (f.params[1..]) |*pp| {
            if (!pp.has_default and !pp.is_vararg) required += 1;
        }
        if (n_args >= required and n_args <= user_params) return true;
    }
    return false;
}

fn disambiguateByReceiver(b: *FuncBuilder, name: []const u8) ?FuncId {
    const recv = b.enclosingRecvTy() orelse return null;
    const recv_simple = simpleTypeHead(recv);
    const ids = b.module.func_name_index.get(name) orelse return null;
    var match: ?FuncId = null;
    for (ids.items) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this")) continue;
        if (!std.mem.eql(u8, simpleTypeHead(f.params[0].ty.name), recv_simple)) continue;
        if (match != null) return null;
        match = fid;
    }
    return match;
}

fn simpleTypeHead(name: []const u8) []const u8 {
    var n = name;
    if (std.mem.indexOfScalar(u8, n, '<')) |lt| n = n[0..lt];
    if (std.mem.lastIndexOfScalar(u8, n, '.')) |dot| n = n[dot + 1 ..];
    return n;
}

fn lowerPathCall(
    b: *FuncBuilder,
    expr: *const Expr,
    shadowed_by_class: bool,
    class_competes: bool,
    force_static_class: *bool,
) Allocator.Error!?Reg {
    const call = expr.Call;
    const callee = call.callee;
    const args = call.args;
    const ast_arg_names = call.arg_names;
    const ast_type_args = call.type_args;
    const segments = callee.Path.segments;
    const name0 = segments[0].name;

    // Secondary-ctor delegation / default-value thunk: a bare own-member call
    // with no `this` in scope is a companion access — the enclosing instance
    // does not exist yet, so `generateOetf(x)` inside `: this(generateOetf(x))`
    // binds the companion's `generateOetf`, never an instance method. Dispatch
    // it as a member call on the owner class value; the VM forwards a class
    // receiver to its companion singleton, walking the superclass chain so an
    // inherited companion member (declared on a superclass's companion) resolves
    // too — `Sub.mk()` lowers to exactly this `LoadGlobal + CallMember` pair.
    // Mirrors the value-read handling of the same case (a bare own-member read
    // in a param thunk); `own_members` already includes own + inherited
    // companion members, so a plain member name is filtered by `hasOwnMember`.
    if (b.isParamThunk() and b.resolve("this") == null and
        b.hasOwnMember(name0) and b.ownMemberApplicable(name0, args.len) and
        !ownMemberRejectsLambdas(b, name0, args) and !classWithCompanion(b, name0))
    {
        if (b.ownerClass()) |owner| {
            const cls = b.allocReg();
            const on = try b.module.internConst(b.allocator, .{ .String = owner });
            try b.push(.{ .LoadGlobal = .{ .dst = cls, .name = on } });
            const run = try lowerArgRun(b, args);
            const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
            const dst = b.allocReg();
            const nmc = try b.module.internConst(b.allocator, .{ .String = name0 });
            try b.push(.{ .CallMember = .{
                .dst = dst,
                .receiver = cls,
                .name = nmc,
                .trailing_lambda = b.callTrailingLambda(),
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
            return dst;
        }
    }

    // A captured outer that also names a top-level fn: route through value.
    // Unless the outer is a local FUNCTION that cannot take this call — a
    // local `fun validate()` does not shadow the top-level `validate(block)`
    // for `validate { … }`, and routing through the captured self-cell made
    // the local call itself.
    const local_fn_takes_call = if (b.localFnDecls(name0)) |decls|
        try anyLocalFnOverloadApplicable(b, decls, args, ast_arg_names)
    else
        true;
    const shadowed_by_local = b.knowsOuter(name0) and b.resolve(name0) == null and
        b.module.hasBareCallCandidate(name0, segments[0].span.file) and
        local_fn_takes_call and
        // A captured local with definite NON-callable evidence (`var key = 0`
        // beside the `key(...) {}` composable) never serves a CALL — the
        // function wins, as in Kotlin.
        !b.isNonFnLocal(name0);
    if (shadowed_by_local) {
        const callee_r = try resolveCapture(b, name0);
        // Only a captured local *extension* function or a receiver-lambda param
        // takes the enclosing receiver as a leading `this`; a plain captured
        // local function (`fun check(a, b)` called from inside a `repeat { }`
        // lambda) must dispatch as a bare value, or `callValueWithThis`'s
        // receiver-fills-param heuristic shifts the enclosing `this` into the
        // first value parameter.
        const wants_this = b.isLocalExtFn(name0) or b.isReceiverLambdaParam(name0);
        const this_reg: ?Reg = if (wants_this)
            (if (b.knowsOuter("this") or b.capturesThisSlot())
                try resolveCapture(b, "this")
            else
                b.resolve("this"))
        else
            null;
        const run = try lowerArgRun(b, args);
        const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
        const dst = b.allocReg();
        if (this_reg) |recv| {
            try b.push(.{ .CallValueWithThis = .{
                .dst = dst,
                .callee = callee_r,
                .receiver = recv,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
        } else {
            try b.push(.{ .CallValue = .{
                .dst = dst,
                .callee = callee_r,
                .args = run[0],
                .n_args = run[1],
                .arg_names = arg_names,
            } });
        }
        return dst;
    }

    // Bare-call resolution through the unified resolver. `resolveCall` folds
    // applicability, scope, and the member-vs-global emission decision into
    // one query; the switch below routes its verdict to a single emitter.
    const want = args.len;
    const cands = try b.module.bareCallCandidates(
        b.allocator,
        name0,
        segments[0].span.file,
    );
    defer b.allocator.free(cands);
    if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
        if (std.mem.eql(u8, w, name0)) {
            std.debug.print("[bare-candidates] {s} file={d} count={d}\n", .{
                name0,
                segments[0].span.file.int(),
                cands.len,
            });
            for (cands) |fid| {
                const f = b.module.funcById(fid) orelse continue;
                std.debug.print(
                    "[bare-candidate] {s}#{d} pkg={s} file={?d} params={d} body={} kind={s} sig={} vis={s} mext_owner={s}\n",
                    .{
                        f.fqn,
                        fid.int(),
                        f.package,
                        if (b.module.registry.private_fn_files.get(fid)) |file| file.int() else null,
                        f.params.len,
                        f.hasBody(),
                        @tagName(f.kind),
                        b.module.decl_sigs.get(fid.int()) != null,
                        if (b.module.decl_sigs.get(fid.int())) |ds| @tagName(ds.visibility) else "-",
                        b.module.registry.member_ext_owner_class.get(fid) orelse "-",
                    },
                );
            }
        }
    }
    const last_arg_lambda = lastArgIsLambda(args);

    // An own member applicable to this call outranks a same-named top-level
    // function: defer to the member-dispatch path (`lowerImplicitThisCall`). A
    // cast at the call site commits to a specific overload and overrides.
    const prefer_member = b.resolve("this") != null and b.hasOwnMember(name0) and
        b.ownMemberApplicable(name0, args.len) and !ownMemberRejectsLambdas(b, name0, args) and
        b.resolve(name0) == null and !b.isLocalFn(name0) and !b.isLocalExtFn(name0);

    // Call-site evidence pre-picks a same-tier overload: an `as` cast names
    // the parameter type outright, and a trailing lambda's derived return
    // discriminates a return-variant family (the sumOf shape).
    const cast_pick: ?FuncId = (try overloadPickByCast(b, cands, args, want)) orelse
        try overloadPickByLambdaReturn(b, cands, args, want);

    // The index classification, for the ambiguity / out-of-scope diagnostics.
    // A cast at the call site pre-picks a same-tier overload, so an ambiguity
    // or type-overload deferral is not reported.
    var index_res = b.module.resolveBareCallIndexed(
        name0,
        b.self_package,
        segments[0].span.file,
        want,
        last_arg_lambda,
    );
    if (cast_pick != null) {
        const r = indexDeferReason(index_res);
        if (r == .ambiguous_tier or r == .type_overload) {
            index_res.outcome = .{ .deferred = .cast_disambiguated };
        }
    }

    if (prefer_member and cast_pick == null) return null;

    const shapes = try buildArgShapes(b, args, ast_arg_names);
    defer b.allocator.free(shapes);
    // An argument written with an EXPLICIT type-argument list carries
    // programmer-stated types the raw shape pass cannot see
    // (`pick(emptyList<Int>())` — the call-return record instantiates
    // `List<Int>`). Derive exactly those args so the emission pick judges
    // the same evidence the derivation passes did; anything else keeps the
    // raw shape (cost and behavior unchanged).
    var explicit_shape_owned: [8]?ir.TypeRef = @splat(null);
    defer for (&explicit_shape_owned) |*t| {
        if (t.*) |*owned| owned.deinit(b.allocator);
    };
    for (args, shapes, 0..) |*a, *sh, i| {
        if (i >= explicit_shape_owned.len) break;
        if (sh.ty != null) continue;
        if (a.* != .Call) continue;
        // A stdlib collection FACTORY names its own result head, and for a
        // bare call that head is often the only evidence there is. Without
        // it `combine(listOf(this, other)) { … }` inside a `Flow<T>`
        // extension gave its first argument no type at all, the binary
        // extension `Flow<T1>.combine(flow, transform)` was not disproved,
        // and the enclosing receiver bound it — passing the list itself as
        // `flow`, which then failed collecting a `List`.
        if (a.Call.type_args.len == 0) {
            if (a.Call.callee.* != .Path or a.Call.callee.Path.segments.len != 1) continue;
            const head = factoryResultHead(a.Call.callee.Path.segments[0].name) orelse continue;
            if (b.resolve(a.Call.callee.Path.segments[0].name) != null) continue;
            sh.ty = .{ .name = head, .nullable = false, .args = &.{} };
            continue;
        }
        if (try staticCallReturnTypeRef(b, a)) |t| {
            // Only a FULLY CONCRETE record is disproof-grade: a derivation
            // still carrying a bare type parameter anywhere (`Core<E>(...)`
            // inside the declaring class) names the wrong scope's parameter
            // and refuted every applicable overload of `atomic(...)`.
            var concrete = blk: {
                const th = typeHead(std.mem.trimEnd(u8, t.name, "?"));
                if (bareTypeParamHead(th) or ir.parseClassTypeParamIdentity(th) != null) break :blk false;
                for (t.args) |a2| {
                    const ah = typeHead(std.mem.trimEnd(u8, a2.name, "?"));
                    if (bareTypeParamHead(ah) or ir.parseClassTypeParamIdentity(ah) != null) break :blk false;
                }
                break :blk true;
            };
            if (b.isTypeParam(typeHead(std.mem.trimEnd(u8, t.name, "?")))) concrete = false;
            if (concrete) {
                explicit_shape_owned[i] = t;
                sh.ty = t;
                sh.ty_authoritative = true;
            } else {
                var owned = t;
                owned.deinit(b.allocator);
            }
        }
    }
    const owned_type_param_bounds = try b.typeParamBoundsSlice();
    defer if (owned_type_param_bounds) |bounds| b.allocator.free(bounds);
    var ctx = resolveCtxFor(
        b,
        name0,
        ast_type_args,
        cast_pick,
        owned_type_param_bounds orelse &.{},
    );
    ctx.nonlocal_return_lambda = inline_call.argLambdaHasNonlocalReturn(args) or blk: {
        // A spliced forwarder passes the original lambda along as a
        // parameter Path (`synchronized(lock, block)` inside another
        // inline wrapper): follow the splice's lambda-argument map so a
        // non-local `return` in the ORIGINAL literal still pins the
        // static inline resolution.
        for (args) |*a| {
            if (a.* != .Path or a.Path.segments.len != 1) continue;
            const lam = b.inlineLambdaFor(a.Path.segments[0].name) orelse continue;
            if (lam.* != .Lambda) continue;
            var one = [_]Expr{lam.*};
            if (inline_call.argLambdaHasNonlocalReturn(&one)) break :blk true;
        }
        break :blk false;
    };
    if (runtime.envOnce("KLIO_EF_TRACE")) |efw| {
        if (std.mem.eql(u8, efw, name0)) std.debug.print("[efset] nlr={} nargs={d} last_lambda={} file={d}\n", .{ ctx.nonlocal_return_lambda, args.len, lastArgIsLambda(args), segments[0].span.file.int() });
    }
    const res = try resolveCallWithComposerAbi(
        b,
        name0,
        segments[0].span.file,
        cands,
        shapes,
        last_arg_lambda,
        ctx,
    );
    // Eager audit: where typeck recorded a pick for this call site,
    // compare it against the engine's answer. Audit-only — behavior
    // flips seam by seam once disagreement is at zero.
    if (eagerAuditOn() and runtime.envOnce("KLIO_EAGER_HITS") != null) {
        std.debug.print("[EAGER-PROBE] '{s}' f{d}:{d}-{d} map={}\n", .{ name0, segments[0].span.file.int(), segments[0].span.start, segments[0].span.end, b.module.eager_calls != null });
    }
    var res_final = res;
    if (b.module.eagerCallTarget(segments[0].span)) |eager_fid| eager: {
        // A pick that resolves the call back to the ENCLOSING declaration
        // while the lazy engine chose otherwise is distrusted: stdlib
        // overload families delegate to same-name siblings, and a
        // mis-picked self-target recurses forever.
        if (b.self_decl_span) |sds| {
            const ec = &(b.module.eager_calls.?);
            if (ec.get(segments[0].span)) |decl| {
                if (decl.file.int() == sds.file.int() and decl.start == sds.start and decl.end == sds.end and
                    (res.target == null or res.target.?.int() != eager_fid.int()))
                {
                    break :eager;
                }
            }
        }
        // Consumption: the typeck-decided target is type-derived and
        // overload-precise where the lazy engine is shape-based; prefer
        // it. `target_final` pins the pick against runtime value-typed
        // re-picks, matching a cast-disambiguated call.
        if (res.target == null or res.target.?.int() != eager_fid.int()) {
            res_final.target = eager_fid;
            res_final.target_final = true;
            if (res_final.emit_form != .Call) res_final.emit_form = .Call;
        }
        if (eagerAuditOn()) {
            const lazy: ?FuncId = res.target;
            if (runtime.envOnce("KLIO_EAGER_HITS") != null) {
                std.debug.print("[EAGER-HIT] '{s}'\n", .{name0});
            }
            if (lazy == null or lazy.?.int() != eager_fid.int()) {
                const lazy_str: i64 = if (lazy) |l| @intCast(l.int()) else -1;
                const efqn: []const u8 = if (b.module.funcById(eager_fid)) |f| f.fqn else "?";
                const lfqn: []const u8 = if (lazy) |l| (if (b.module.funcById(l)) |f| f.fqn else "?") else "-";
                std.debug.print("[EAGER-AUDIT] call '{s}': eager={d}({s}) lazy={d}({s})\n", .{ name0, eager_fid.int(), efqn, lazy_str, lfqn });
            }
        }
    }

    defer b.allocator.free(res_final.candidate_set);
    const was_cast = cast_pick != null and res_final.target != null and cast_pick.?.int() == res_final.target.?.int();

    // Kotlin ranks an implicit receiver's FUNCTION-TYPED property — the
    // invoke convention — above an outer-scope top-level function:
    // `with(Host()) { handler() }` calls the Host property's lambda even
    // when a top-level `handler()` exists. The static engine ranks
    // functions only, so a top-level pick with such a peer re-routes to
    // the member-or-global walk, whose runtime tail prefers the member.
    if (res_final.target != null and !was_cast) peer: {
        const tgt = res_final.target.?;
        const tf = b.module.funcById(tgt) orelse break :peer;
        if (tf.kind != .plain) break :peer;
        if (tf.params.len != 0 and std.mem.eql(u8, tf.params[0].name, "this")) break :peer;
        if (b.resolve(name0) != null) break :peer;
        const recv_heads = [_]?[]const u8{ bareStaticRecvHead(b), b.recvTy(), b.enclosingRecvTy() };
        for (recv_heads) |mh| {
            const h = mh orelse continue;
            const ph = propTypeHeadOn(b, typeHead(std.mem.trimEnd(u8, h, "?")), name0) orelse continue;
            // Function-typed property heads register as `FunctionN` from a
            // lowered ref or the `<function>` placeholder from an AST
            // function-type annotation; only the former proves an arity.
            if (std.mem.startsWith(u8, ph, "Function")) {
                const n = std.fmt.parseInt(usize, ph["Function".len..], 10) catch continue;
                if (n != args.len) continue;
            } else if (!std.mem.eql(u8, ph, "<function>")) continue;
            orEmitAudit(b, "prop_invoke_peer", "CallMemberOrGlobal", name0);
            return try emitMemberOrGlobal(b, expr, tgt, false);
        }
    }

    // A known stdlib host-intrinsic global (alias) whose user overloads do not
    // apply to this call still resolves to the intrinsic global. In a receiver
    // context, bind it directly — no class declares the name as a member, so a
    // `this.<name>` redispatch would invoke the receiver itself.
    if (res_final.target == null and !shadowed_by_class and inReceiverContext(b) and
        ir.isAliasName(name0) and !anyReceiverClassDeclares(b, name0) and
        !extensionCandidateFitsArity(b, name0, args.len) and
        b.resolve(name0) == null and !b.knowsOuter(name0))
    {
        return try emitValueCall(b, args, ast_arg_names, ast_type_args, name0);
    }

    // KLIO_BARE_TRACE=<name>: print the static resolution for a bare call —
    // which overload bound (or that none did), the emit form, and the
    // receiver context the decision saw. The static complement of
    // KLIO_MISS_TRACE.
    if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
        if (std.mem.eql(u8, w, name0) and res_final.target == null) {
            std.debug.print("[bare] {s} -> NONE recv_ty={s} encl_recv={s} pkg={s} shadowed={} known_none={} at=f{d}:{d}\n", .{
                name0,
                b.recvTy() orelse "-",
                b.enclosingRecvTy() orelse "-",
                b.self_package,
                shadowed_by_class,
                b.own_recv_known_none,
                segments[0].span.file.int(),
                segments[0].span.start,
            });
        }
    }
    // A TYPE-DISPATCHED overload set the index deferred to runtime must
    // reach an emit form whose runtime tail re-ranks by value types.
    // Falling through to the bare-name value read handed the call to the
    // global lookup's first-wins pick — the deprecated 9-param
    // ActualParagraph sibling ran with a TextOverflow in its Boolean
    // `ellipsis` slot.
    if (res_final.target == null and !shadowed_by_class and
        indexDeferReason(index_res) == .type_overload)
    {
        if (index_res.first) |first_cand| {
            orEmitAudit(b, "type_overload_deferred", "CallMemberOrGlobal", name0);
            return try emitMemberOrGlobal(b, expr, first_cand, false);
        }
    }
    // RESOLUTION PARITY for spliced receiver-lambda regions: a PLAIN
    // top-level pick may be shadowed by the subject's members/extensions
    // (the framed route's runtime walk would rank them first — static
    // `sort()` inside `toTypedArray().apply { }` bound a wrong top-level
    // where Array.sort must win). Defer those to the member-first walk.
    // An EXTENSION pick stands: it is receiver-compatible evidence the
    // walk can only weaken (`putAll(this@toMap)` must keep the
    // Iterable-pairs extension, not fall to the member `putAll(Map)`).
    if (inline_call.rfsEnabled() and b.encl_tower_depth > 0 and
        res_final.target != null and !nameHasReifiedInlineCandidate(name0))
    plain_defer: {
        const tf0 = b.module.funcById(res_final.target.?) orelse break :plain_defer;
        const is_ext0 = tf0.params.len != 0 and std.mem.eql(u8, tf0.params[0].name, "this");
        if (is_ext0) break :plain_defer;
        if (!nameHasReceiverCandidate(b, name0, null) and
            !b.module.registry.class_member_names.contains(name0)) break :plain_defer;
        orEmitAudit(b, "tower_parity_defer", "fallthrough", name0);
        return null;
    }
    if (res_final.target) |target| {
        if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
            if (std.mem.eql(u8, w, name0)) {
                const tfn = b.module.funcById(target);
                const tf = if (tfn) |f| f.fqn else "?";
                const np: usize = if (tfn) |f| f.params.len else 0;
                const is_ext_t = if (tfn) |f| f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this") else false;
                const sel_ret: []const u8 = if (tfn) |f| blk_sr: {
                    if (f.params.len == 0) break :blk_sr "-";
                    const lp = f.params[f.params.len - 1].ty;
                    if (lp.args.len == 0) break :blk_sr "-";
                    break :blk_sr lp.args[lp.args.len - 1].name;
                } else "-";
                std.debug.print("[bare] pick_was={?d} sel_ret={s}\n", .{ if (cast_pick) |cp| cp.int() else null, sel_ret });
                std.debug.print("[bare] {s} -> {s}#{d} params={d} ext={} form={s} recv_ty={s} encl_recv={s} pkg={s} shadowed={} at=f{d}:{d}\n", .{
                    name0,
                    tf,
                    target.int(),
                    np,
                    is_ext_t,
                    @tagName(res_final.emit_form),
                    b.recvTy() orelse "-",
                    b.enclosingRecvTy() orelse "-",
                    b.self_package,
                    shadowed_by_class,
                    @intFromEnum(segments[0].span.file),
                    segments[0].span.start,
                });
                std.debug.print("[bare-res] {s} tier={d} reason={?s} final={} tier_count={d} index={s} lazy={?d}\n", .{ name0, res_final.tier, if (res_final.reason) |r| @tagName(r) else null, res_final.target_final, res_final.tier_count, @tagName(index_res.outcome), if (res.target) |t| t.int() else null });
            }
        }
        if (!shadowed_by_class) {
            // Constructors do not yet occupy a `resolveCall` candidate slot,
            // but their classifier scope tier is shared with callables. A
            // nearer class constructs immediately; a nearer function commits;
            // only an equal-tier constructor/factory family needs the
            // class-carrying runtime comparison. An explicit argument cast
            // already disambiguated the factory overload.
            if (class_competes and !was_cast) {
                const caller_pkg = b.module.packageOfFile(
                    segments[0].span.file,
                ) orelse b.self_package;
                const class_tier = b.module.classRefTier(
                    name0,
                    caller_pkg,
                    segments[0].span.file,
                ) orelse ir.Module.other_package_tier;
                if (class_tier < res_final.tier) {
                    force_static_class.* = true;
                    return null;
                }
                if (class_tier == res_final.tier) return null;
            }
            if (indexDeferReason(index_res) == .ambiguous_tier) {
                try recordAmbiguousCall(b, name0, segments[0].span, index_res);
            }
            // A target in a package the caller cannot see is an unresolved
            // reference (kotlinc rejects the call); the diagnostic fails the
            // program before it runs.
            _ = try recordOutOfScopeCall(b, name0, segments[0].span, target, index_res);
            // A per-file import alias (`import ... unsafeFlow as flow`)
            // resolves through the symbol index to a target the NAME-keyed
            // inline table cannot see — it holds declared names only. When
            // that committed target is an inline header stub, emitting the
            // call would enter a bodyless frame at runtime; splice its
            // registered AST by id instead.
            if (b.module.funcById(target)) |tfi| {
                // Alias calls only (`import ... unsafeFlow as flow` spells
                // `flow`): when the call-site name matches the declared name,
                // the NAME-keyed inline path already made its splice-or-defer
                // decision and forcing a second splice here re-lowers bodies
                // in foreign file scopes (a compose body's package-private
                // reference failed at its splice site).
                if (tfi.is_inline and !tfi.hasBody() and !std.mem.eql(u8, name0, tfi.name)) {
                    if (inline_state.inlineAstById(target.int())) |inline_ast| {
                        inline_state.ensureInlineBody(inline_ast);
                        const iexp = b.peekExpected();
                        const iexp_ptr: ?*const ast.TypeRef = if (iexp) |*_e| _e else null;
                        var iselected = try selectedCallArgsForBuilder(
                            b,
                            target,
                            args,
                            ast_arg_names,
                            exprSpan(callee),
                            call.has_trailing_lambda,
                        );
                        defer iselected.deinit(b.allocator);
                        inline_call.splice_route_tag = "lowerPathCall:14624";
                        if (try tryInlineCallWithTypeArgs(b, name0, inline_ast, iselected.args, iselected.names, null, ast_type_args, iexp_ptr)) |r| {
                            return r;
                        }
                    }
                }
            }
            return switch (res_final.emit_form) {
                // A finalized pick is as definitive as a cast pick: the
                // runtime's value-typed overload re-pick must not override it.
                .Call => try emitCall(b, expr, target, was_cast or res_final.target_final),
                .CallMember => try emitCallMember(b, expr, target, was_cast),
                .CallMemberOrGlobal => try emitMemberOrGlobal(b, expr, target, was_cast),
                // The resolver never emits a value call with a committed target.
                .CallValue => unreachable,
            };
        }
    }
    return null;
}

/// The receiver-context bits `resolveCall` folds into its emit-form decision,
/// read once from the builder. Shared by the live path and the audit shadow so
/// both query `resolveCall` identically.
/// The active inline splice's receiver head, for a name the spliced body
/// does NOT bind itself. A spliced inline function's own parameter shadows
/// its receiver's extensions exactly as it does before splicing — `mp`'s
/// `crossinline transform` against `Flw.transform` — so a name the splice
/// substituted keeps resolving as that parameter.
fn spliceRecvForName(b: *const FuncBuilder, name0: []const u8) ?[]const u8 {
    if (b.resolve(name0) != null or b.knowsOuter(name0)) return null;
    if (b.inlineLambdaFor(name0) != null) return null;
    return b.spliceRecvTy();
}

pub fn resolveCtxFor(
    b: *FuncBuilder,
    name0: []const u8,
    ast_type_args: []const ast.TypeRef,
    cast_pick: ?FuncId,
    actual_type_param_bounds: []const ir.ModuleRegistry.TypeParamBound,
) ir.Module.ResolveCtx {
    return .{
        .in_receiver_context = inReceiverContext(b),
        .unknown_receiver = b.capturesThisSlot() or b.isParamThunk() or
            (b.recvTy() != null and !fnTypedRecvCannotShadow(b, name0)),
        .recv_cannot_shadow = fnTypedRecvCannotShadow(b, name0) and
            !b.capturesThisSlot() and !b.isParamThunk() and
            b.ownerClass() == null,
        .enclosing_has_member = b.hasEnclosingMember(name0) or blk: {
            const oc = b.ownerClass() orelse break :blk false;
            break :blk (ownerChainShadowContains(b, oc, name0) orelse false);
        },
        .receiver_known = receiverTypeKnown(b, name0),
        .has_type_args = ast_type_args.len != 0,
        .has_composer = b.resolve("$composer") != null,
        .cast_pick = cast_pick,
        // Inside an inline SPLICE the frame's own `recv_ty` is the CALLER's,
        // so a spliced extension body would resolve its bare calls with no
        // receiver at all and lose its own receiver's extensions
        // (`serializer(type)` inside `SerializersModule.serializer()` bound
        // the module-less overload). The splice channel carries the spliced
        // declaration's receiver; consult it only when the frame has none.
        // During an ACTIVE splice the spliced body's bare calls resolve
        // against the spliced declaration's OWN receiver, ahead of the
        // frame's `recv_ty` — which is the CALLER's. A receiver-bearing
        // caller (an inline fn spliced into an EXTENSION function) would
        // otherwise shadow the splice receiver and a bare extension call in
        // the spliced body (`transform { }` = `Flow.unsafeTransform` inside
        // `Flow.map`, spliced into `List<T>.ext`) would resolve against the
        // caller's receiver and miss. Mirrors `bareStaticRecvHead`: this
        // narrow, then the splice receiver, then the frame's own.
        // During an ACTIVE splice the frame's own `recv_ty` is the CALLER's
        // (the inline body is hygienic). When the caller is itself a
        // receiver-bearing function (an inline fn spliced into an EXTENSION
        // function), that caller receiver would shadow the spliced
        // declaration's own receiver and a bare extension call in the body
        // (`transform { }` = `Flow.unsafeTransform` inside `Flow.map`,
        // spliced into `List<T>.ext`) would resolve against the wrong
        // receiver and miss. Prefer the splice receiver over the caller's,
        // mirroring `bareStaticRecvHead`; `spliceRecvForName`'s local gate
        // cannot serve here because the collided name (`transform`) is also
        // a bound param, so consult the splice receiver directly.
        .recv_ty = b.thisNarrow() orelse
            (if (b.spliceHintActive() and b.recvTy() != null) b.spliceRecvTy() else b.recvTy()) orelse
            spliceRecvForName(b, name0),
        .recv_type = if (b.thisNarrow()) |t|
            ir.TypeRef{ .name = t, .nullable = false, .args = &.{} }
        else if (b.spliceHintActive() and b.recvTy() != null)
            (if (b.spliceRecvTyRef()) |srt| srt.* else null)
        else if (b.recvTypeRef()) |rt|
            rt
        else if (spliceRecvForName(b, name0) != null)
            (if (b.spliceRecvTyRef()) |srt| srt.* else null)
        else
            null,
        .actual_type_param_bounds = actual_type_param_bounds,
        .is_value_capture = b.knowsOuter(name0) and b.resolve(name0) == null,
        .in_tailrec_body = b.tailrecSelf() != null,
        .owner_class = b.ownerClass(),
        .receiver_scope_complete = receiverScopeKind(b) != .no,
        .tower_scope = receiverScopeKind(b) == .tower,
        .tower = b.implicit_receiver_tower.items,
    };
}

/// A lambda/thunk body's receiver scope is complete when its
/// implicit-receiver TOWER enumerates every level and each entry's class is
/// free of the outer-receiver escapes (enclosing-class instances, companion
/// pairing) with a complete hierarchy shadow set — the same tests the
/// plain-method owner path applies, per tower entry.
fn towerScopeComplete(b: *FuncBuilder) bool {
    const items = b.implicit_receiver_tower.items;
    if (items.len == 0) return false;
    for (items) |entry| {
        var head = std.mem.trimEnd(u8, entry.head, "?");
        if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
        const cid = (if (std.mem.indexOfScalar(u8, head, '.') != null)
            b.module.classIdByFqn(head)
        else
            b.module.uniqueClassIdBySimpleName(typeHead(head))) orelse return false;
        if (cid.int() >= b.module.classes.items.len) return false;
        const lifted = b.module.classes.items[cid.int()].name;
        const fqn = b.module.classes.items[cid.int()].fqn;
        if (b.module.registry.enclosing_class.get(lifted) != null or
            b.module.registry.enclosing_class.get(fqn) != null)
        {
            return false;
        }
        if (b.module.registry.companion_singletons.contains(lifted) or
            b.module.registry.companion_singletons.contains(fqn))
        {
            return false;
        }
        if (ownerChainShadowContains(b, lifted, "") == null) return false;
    }
    return true;
}

const ScopeCompleteness = enum { no, plain, tower };

fn receiverScopeKind(b: *FuncBuilder) ScopeCompleteness {
    if (b.capturesThisSlot() or b.isParamThunk()) {
        if (std.mem.eql(u8, runtime.envOnce("KLIO_TOWER_SCOPE") orelse "1", "0")) return .no;
        return if (towerScopeComplete(b)) .tower else .no;
    }
    return if (receiverScopeCompletePlain(b)) .plain else .no;
}

fn receiverScopeCompletePlain(b: *FuncBuilder) bool {
    const recv = b.recvTypeRef();
    const owner = b.ownerClass();
    if (recv) |receiver| {
        const head = typeHead(receiver.name);
        const hierarchy = b.module.registry.hierarchy_shadow_names.get(head) orelse
            b.module.registry.hierarchy_shadow_names.get(receiver.name) orelse
            return false;
        if (!hierarchy.complete) return false;
    }
    const owner_name = owner orelse return recv != null;
    const owner_id = b.module.classId(owner_name);
    const owner_fqn = if (owner_id) |id|
        (if (id.int() < b.module.classes.items.len)
            b.module.classes.items[id.int()].fqn
        else
            owner_name)
    else
        owner_name;
    if (b.module.registry.enclosing_class.get(owner_name) != null or
        b.module.registry.enclosing_class.get(owner_fqn) != null)
    {
        return false;
    }
    if (b.module.registry.companion_singletons.contains(owner_name) or
        b.module.registry.companion_singletons.contains(owner_fqn))
    {
        return false;
    }
    return ownerChainShadowContains(b, owner_name, "") != null;
}

/// Resolve a source-shaped call first, then retry with the hidden Compose ABI
/// only when the current function has a real threaded composer and ordinary
/// Kotlin resolution found no target. The retry must itself select a
/// declaration whose lowered signature proves the synthetic pair; this keeps
/// same-name non-composable overloads on the ordinary path.
fn resolveCallWithComposerAbi(
    b: *FuncBuilder,
    name: []const u8,
    caller_file: ir.FileId,
    candidates: []const FuncId,
    shapes: []const applicability.ArgShape,
    last_arg_lambda: bool,
    ctx: ir.Module.ResolveCtx,
) Allocator.Error!ir.Module.Resolution {
    const direct = try b.module.resolveCallCandidates(
        b.allocator,
        name,
        b.self_package,
        caller_file,
        candidates,
        shapes,
        last_arg_lambda,
        ctx,
    );
    if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
        if (std.mem.eql(u8, w, name)) std.debug.print("[abi-direct] {s} target={?d} reason={?s} composer_in_scope={} shapes_have_pair={} nshapes={d}\n", .{ name, if (direct.target) |t| t.int() else null, if (direct.reason) |r| @tagName(r) else null, b.resolve("$composer") != null, argShapesHaveComposerPair(shapes), shapes.len });
    }
    if (direct.target != null or b.resolve("$composer") == null or
        argShapesHaveComposerPair(shapes))
    {
        return direct;
    }

    const augmented = try b.allocator.alloc(applicability.ArgShape, shapes.len + 2);
    defer b.allocator.free(augmented);
    @memcpy(augmented[0..shapes.len], shapes);
    augmented[shapes.len] = .{ .named = "$composer" };
    augmented[shapes.len + 1] = .{
        .ty = build.typeInt(),
        .named = "$changed",
        .literal_kind = .numeric,
    };

    const threaded = try b.module.resolveCallCandidates(
        b.allocator,
        name,
        b.self_package,
        caller_file,
        candidates,
        augmented,
        false,
        ctx,
    );
    if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
        if (std.mem.eql(u8, w, name)) std.debug.print("[abi-retry] {s} threaded_target={?d} reason={?s} tier={d} tier_count={d}\n", .{ name, if (threaded.target) |t| t.int() else null, if (threaded.reason) |r| @tagName(r) else null, threaded.tier, threaded.tier_count });
    }
    if (threaded.target) |target| {
        if (b.module.funcById(target)) |f| {
            if (selectedCallHasComposerAbi(b.module, target, f)) {
                b.allocator.free(direct.candidate_set);
                return threaded;
            }
        }
    }
    b.allocator.free(threaded.candidate_set);
    return direct;
}

fn argShapesHaveComposerPair(shapes: []const applicability.ArgShape) bool {
    if (shapes.len < 2) return false;
    const composer_name = shapes[shapes.len - 2].named orelse return false;
    const changed_name = shapes[shapes.len - 1].named orelse return false;
    return std.mem.eql(u8, composer_name, "$composer") and
        std.mem.eql(u8, changed_name, "$changed");
}

fn indexDeferReason(res: ir.Module.BareCallResolution) ?ir.Module.ResolveDeferReason {
    return switch (res.outcome) {
        .resolved => null,
        .deferred => |r| r,
    };
}

/// Kotlin does not resolve a value-position reference — `::name`, a
/// `::Ctor`, or a bare read — whose only declaration lives in a package
/// the caller neither declares, imports, nor sees by default. Record the
/// unresolved diagnostic (the same one the bare-call path emits) when the
/// reference would otherwise bind such an out-of-scope declaration. A
/// reference denotes the declaration itself, so there is no arity or
/// member-redispatch shape to defer on: a tier-5 verdict is final, exactly
/// as for the call form. Returns true when the diagnostic was recorded so
/// the caller can suppress the lenient bind.
fn recordOutOfScopeRef(
    b: *FuncBuilder,
    name: []const u8,
    ref_span: ir.Span,
    fqn: []const u8,
    tier: ?u8,
) Allocator.Error!bool {
    if (tier != ir.Module.other_package_tier) return false;
    // The verdict is trustworthy only when the declaration carries a real
    // package: a bare FQN (no package prefix) is a lift artifact whose
    // scoping metadata is unreliable — an upstream class such as
    // `io.ktor.utils.io.ClosedByteChannelException` can lose its package
    // during the lift and read as the empty package even when the
    // reference is same-package and genuinely in scope. The resolver still
    // binds it (`classIdIndexed`/`resolveBareRefIndexed` return the best
    // pick); rejecting it would be a false positive, so a bare-FQN
    // declaration is never reported out of scope.
    if (std.mem.indexOfScalar(u8, fqn, '.') == null) return false;
    if (runtime.envOnce("KLIO_UNRES_TRACE") != null) {
        std.debug.print("[unres] name={s} fqn={s} inline_fn={s} owner={s} window={} depth={d}\n", .{
            name, fqn, b.currentInlineFn() orelse "-", b.owner_class orelse "-",
            b.lambda_splice_resolve != null, b.scopes.items.len,
        });
    }
    try b.module.resolve_diags.append(b.allocator, .{
        .name = name,
        .fqn_a = fqn,
        .fqn_b = "",
        .span = ref_span,
        .kind = .unresolved,
    });
    return true;
}

/// The FQN of a class by id, for an out-of-scope value-reference
/// diagnostic.
fn classFqnOf(b: *FuncBuilder, id: ir.ClassId) []const u8 {
    if (idGet(ir.Class, b.module.classes.items, id.int())) |c| return c.fqn;
    return "<invalid>";
}

/// Record an ambiguous bare call into the module's lowering diagnostics.
/// The build driver reports these before the program runs. Each
/// candidate carries its declaration span (from the phase-1 header
/// record) so a true duplicate's report can point at both declarations.
fn recordAmbiguousCall(b: *FuncBuilder, name: []const u8, call_span: ir.Span, res: ir.Module.BareCallResolution) Allocator.Error!void {
    const fqn_a = if (res.first) |f| fqnOf(b, f) else "?";
    const fqn_b = if (res.second) |s| fqnOf(b, s) else "?";
    const span_a: ?ir.Span = if (res.first) |f| b.module.decl_span.get(f.int()) else null;
    const span_b: ?ir.Span = if (res.second) |s| b.module.decl_span.get(s.int()) else null;
    try b.module.resolve_diags.append(b.allocator, .{
        .name = name,
        .fqn_a = fqn_a,
        .fqn_b = fqn_b,
        .span = call_span,
        .span_a = span_a,
        .span_b = span_b,
    });
}

/// Kotlin does not resolve an unqualified call whose every candidate
/// lives in a package the caller neither declares, imports, nor sees by
/// default (kotlinc: "unresolved reference"). When the bound target is a
/// plain top-level function in such a package, record the unresolved
/// diagnostic — naming the candidates and how to import them — and tell
/// the caller to suppress the bind. Receiver-bound extensions are the
/// heuristic's domain and never classify as out of scope here. The
/// corpus sweep (examples + coroutine fixtures + the lowered stdlib and
/// pack sources, KLIO_RESOLVE_AUDIT) resolves zero calls at this tier,
/// so the error only fires on programs kotlinc already rejects.
fn recordOutOfScopeCall(
    b: *FuncBuilder,
    name: []const u8,
    call_span: ir.Span,
    final_id: FuncId,
    index_res: ir.Module.BareCallResolution,
) Allocator.Error!bool {
    const file = call_span.file;
    // A bare call whose name is a known class member and that sits in a
    // receiver context is routed to runtime member-or-global dispatch by
    // `emitBareFuncCall` (`CallMemberOrGlobal`): the implicit receiver may
    // supply the member, so the reference is not out of scope even when
    // the only package-scope candidate is unimported. kotlinc resolves
    // `fun Source.discard() { request(count) }` to the receiver's
    // `request` member, not the package-scope `request` function.
    if (inReceiverContext(b) and anyReceiverClassDeclares(b, name)) return false;
    // Only the index's own out-of-scope verdicts count: a unique
    // exact-arity match, or a tier-5 candidate set (identical or
    // type-distinct). Loose-shape deferrals (arity/default/vararg/
    // bodyless) stay with the heuristic — those binds are provisional
    // and the runtime may still dispatch a member or re-pick an
    // overload (`list.apply { add(x) }` must not error because a
    // user file declares a top-level `add`).
    const precise = switch (index_res.outcome) {
        .resolved => true,
        .deferred => |r| r == .unimported_set or r == .type_overload,
    };
    // A loose-shape deferral (default/vararg/trailing-lambda arity, an
    // unmatched arity, a low-priority-only or bodyless-only set) is
    // unresolved too WHEN every rankable candidate is out of scope — the
    // winning tier is `other_package_tier`, i.e. there is no in-scope
    // candidate of any shape the runtime could re-pick. The member-
    // redispatch guard is `inReceiverContext`: inside a receiver context a
    // runtime member of the same name may still bind (kotlinc resolves
    // `g.apply { greet() }` to `g`'s member even when a top-level `greet`
    // is out of scope), so the loose-shape rejection only fires outside
    // any receiver context, where no implicit receiver can supply the
    // call. The bare-call member-shadowable routing already sends those
    // receiver-context calls to `CallMemberOrGlobal` rather than here.
    const loose_out_of_scope = switch (index_res.outcome) {
        .resolved => false,
        .deferred => |r| switch (r) {
            .default_param_shape,
            .vararg_only,
            .trailing_lambda_shape,
            .arity_mismatch,
            .low_priority_only,
            .bodyless_only,
            => index_res.tier == ir.Module.other_package_tier and !inReceiverContext(b),
            // The index defers a vararg/default call to `extension_form`
            // when an in-scope extension namesake exists, since it cannot
            // tell whether the receiver applies. Outside any receiver
            // context no receiver can supply such an extension, so a
            // heuristic that landed on a tier-5 NON-extension top-level
            // function is the same unresolved reference kotlinc rejects.
            // The `isNonExt(final_id)` + tier-5 checks below confirm the
            // bound target is out of scope before this fires.
            .extension_form => !inReceiverContext(b),
            else => false,
        },
    };
    if (!precise and !loose_out_of_scope) return false;
    // The index ranked at least one candidate in a visible tier (a named
    // import, own package, wildcard, or default import): the call resolves
    // among those in-scope candidates at runtime — a type-dispatched overload
    // set the runtime picks by argument types. A heuristic fallback that
    // happened to land on an invisible same-name namesake (e.g. Brush.kt's
    // `lerp(Offset, Offset, Float)` when many packs contribute out-of-scope
    // `lerp` overloads) does NOT make it an out-of-scope reference. Only a set
    // whose every rankable candidate is out of scope is genuinely unresolved.
    if (index_res.tier < ir.Module.other_package_tier) return false;
    if (!isNonExt(b, final_id)) return false;
    const tier = b.module.bareCallTierOf(final_id, name, b.self_package, file) orelse return false;
    if (tier != ir.Module.other_package_tier) return false;
    // A bare-FQN target (no package prefix) is a lift artifact with
    // unreliable scoping metadata; never report it out of scope (see
    // `recordOutOfScopeRef`).
    if (std.mem.indexOfScalar(u8, fqnOf(b, final_id), '.') == null) return false;
    const fqn_a = if (index_res.first) |f| fqnOf(b, f) else fqnOf(b, final_id);
    const fqn_b = if (index_res.second) |s2| fqnOf(b, s2) else "";
    try b.module.resolve_diags.append(b.allocator, .{
        .name = name,
        .fqn_a = fqn_a,
        .fqn_b = fqn_b,
        .span = call_span,
        .kind = .unresolved,
    });
    return true;
}

/// True when a bare name in this builder's context can be shadowed by a
/// runtime implicit receiver: lambda bodies (the bound receiver is only
/// known at invoke time), method / extension / ctor-thunk bodies (`this`
/// in scope). In every other context — a plain top-level function body —
/// no implicit receiver exists, so member-vs-global is statically
/// decidable: kotlinc rejects resolving a bare name against a *caller's*
/// receiver (dynamic scope), so those sites emit the static global form.
/// Whether the CURRENT `this` is a spliced receiver-lambda SUBJECT of a
/// known type that is not the enclosing owner and does not declare `name`:
/// an own-member read must then take the walking load, not a GetField on
/// the subject (a companion `tag` inside `with(Other()) { tag }` is the
/// enclosing class's, never a field of Other). Mirrors the write side's
/// `spliceReceiverHidesMember`.
fn spliceSubjectHidesOwnMember(b: *FuncBuilder, name: []const u8) bool {
    if (!inline_call.rfsEnabled() or b.encl_tower_depth == 0) return false;
    const recv = b.spliceRecvTy() orelse b.spliceHintRecv() orelse return false;
    var head = std.mem.trimEnd(u8, recv, "?");
    if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
    if (std.mem.lastIndexOfScalar(u8, head, '.')) |d| head = head[d + 1 ..];
    const owner = b.ownerClass() orelse return false;
    if (std.mem.eql(u8, head, owner)) return false;
    if (inline_state.memberPropAst(head, name) != null) return false;
    if (b.module.classId(head)) |cid| {
        if (cid.int() < b.module.classes.items.len) {
            const c = &b.module.classes.items[cid.int()];
            for (c.primary_params) |*pp| {
                if (std.mem.eql(u8, pp.name, name)) return false;
            }
        }
    }
    return true;
}

/// Unwind the spliced-subject tower down to `base` before a jump that
/// leaves the regions (`break`/`continue` past a spliced `sync {}`):
/// every skipped region's `EnclosingPop` is emitted here, or the CAS
/// retry loop leaks one chain entry per iteration.
fn emitTowerPopsForJump(b: *FuncBuilder, base: u32) Allocator.Error!void {
    var d = b.encl_tower_depth;
    while (d > base) : (d -= 1) {
        try b.push(.{ .EnclosingPop = .{} });
    }
}

fn inReceiverContext(b: *const FuncBuilder) bool {
    // A binding named `this` that is an ordinary user parameter (backtick-
    // quoted on a receiver-less function) is not a dispatch receiver.
    const this_binding = !b.this_is_plain_param and b.resolve("this") != null;
    return b.capturesThisSlot() or this_binding or b.ownerClass() != null or
        b.isParamThunk() or b.recvTy() != null;
}

/// An extension declared on a *function type* (`(suspend () -> T).start…`)
/// has a receiver with no members a bare call could bind: a function value's
/// only member surface is `invoke`/`call`. Deferring a resolved top-level call
/// to the runtime member-first walk from such a body is not just unnecessary,
/// it is wrong — the runtime's SAM arm invokes a callable receiver for any
/// member name no extension claims, so `runSafely(completion) { … }` inside
/// `startCoroutineCancellable` would call the suspend block itself instead of
/// the same-file top-level `runSafely`, silently discarding the completion.
fn fnTypedRecvCannotShadow(b: *const FuncBuilder, name: []const u8) bool {
    const rt = b.recvTy() orelse return false;
    if (!recvHeadIsFunctionType(rt)) return false;
    return !std.mem.eql(u8, name, "invoke") and !std.mem.eql(u8, name, "call");
}

/// Whether a recorded receiver-type head denotes a function type in any of
/// its spellings: the parser's `"<function>"` tag, a spelled-out
/// `(P) -> R`, or the erased builtin names (`Function1`,
/// `SuspendFunction0`, ...). Deliberately tighter than `headIsFunctionType`
/// — the erased names must end in digits so a user class named
/// `FunctionTable` never claims the closed no-member surface.
fn recvHeadIsFunctionType(rt: []const u8) bool {
    if (std.mem.eql(u8, rt, "<function>")) return true;
    if (std.mem.indexOf(u8, rt, "->") != null) return true;
    var head = rt;
    if (std.mem.indexOfScalar(u8, head, '<')) |lt| head = head[0..lt];
    for ([_][]const u8{ "Function", "SuspendFunction", "KFunction", "KSuspendFunction" }) |p| {
        if (std.mem.startsWith(u8, head, p) and head.len > p.len) {
            var all_digits = true;
            for (head[p.len..]) |c| {
                if (c < '0' or c > '9') {
                    all_digits = false;
                    break;
                }
            }
            if (all_digits) return true;
        }
    }
    return false;
}

/// Whether a bare name in an implicit-receiver context could bind to a member
/// of that receiver, so a static bind to a same-named top-level function would
/// wrongly shadow it. Used to decide whether to defer a resolved bare call to
/// the runtime member-first walk (`CallMemberOrGlobal`).
///
/// A lambda / scope-function / parameter-thunk / extension body has an implicit
/// receiver whose concrete type is unknown at lowering time — it may be a
/// builtin (e.g. `StringBuilder`) whose members are not in `class_member_names`
/// — so such a body always defers. A plain method body's receiver type IS
/// known: its own hierarchy (cross-file supertypes included, through the
/// transitive per-class member set) decides precisely — a member of some
/// unrelated class elsewhere in the program cannot shadow this call. Only a
/// receiver whose type is genuinely unknown falls back to the program-wide
/// member-name set.
/// The E2.3 precise answer for a lambda/thunk context: does the
/// typeck-recorded receiver head's hierarchy declare `name`? Null when
/// no head is recorded or its shadow set is missing/incomplete — the
/// caller stays conservative.
fn lambdaRecvHeadDeclares(b: *const FuncBuilder, name: []const u8) ?bool {
    const h = eagerLambdaRecvHead(b) orelse return null;
    const hs = b.module.registry.hierarchy_shadow_names.get(h) orelse return null;
    if (!hs.complete) return null;
    return hs.names.contains(name);
}

fn memberShadowPossible(b: *const FuncBuilder, name: []const u8) bool {
    if (b.capturesThisSlot() or b.isParamThunk() or
        (b.recvTy() != null and !fnTypedRecvCannotShadow(b, name)))
    {
        // E2.3: the recorded receiver head answers precisely; when it
        // does NOT declare the name, the remaining implicit receivers
        // (enclosing class, outer chain) are checked below instead of
        // answering a blanket true.
        if (lambdaRecvHeadDeclares(b, name)) |ans| {
            if (ans) return true;
        } else {
            return true;
        }
    }
    if (b.hasEnclosingMember(name)) return true;
    if (b.ownerClass()) |oc| {
        if (ownerChainShadowContains(b, oc, name)) |shadowed| return shadowed;
    }
    return b.module.registry.class_member_names.contains(name);
}

/// Whether `name` is a member anywhere along the owner class's hierarchy
/// OR any of its lifted outer classes' hierarchies (`A$B$C` also checks
/// `A$B` and `A` — a nested class's method body sees the outer classes as
/// implicit receivers). Null when any set along the chain is missing or
/// incomplete: the caller must then stay conservative.
fn ownerChainShadowContains(b: *const FuncBuilder, owner: []const u8, name: []const u8) ?bool {
    var found = false;
    var end = owner.len;
    while (true) {
        const hs = b.module.registry.hierarchy_shadow_names.get(owner[0..end]) orelse return null;
        if (!hs.complete) return null;
        if (name.len != 0 and hs.names.contains(name)) found = true;
        const dollar = std.mem.lastIndexOfScalar(u8, owner[0..end], '$') orelse break;
        end = dollar;
    }
    return found;
}

/// The receiver type at this body is statically known (a plain method
/// body with no unknown-receiver context layered on top), so the
/// member-shadow question is answered by its own hierarchy rather than
/// the program-wide name universe. Mirrored into `ResolveCtx` so
/// `resolveCall`'s Phase C asks the identical question.
/// The direct-bind guards' question — "does any class this context's
/// receiver could be declare `name` as a member". Unlike
/// `memberShadowPossible`, an unknown-receiver context (lambda, thunk,
/// extension body) does NOT answer true: the alias / container-creator /
/// prop-read guards bind DIRECT precisely when no class declares the name,
/// and only a plain method body (receiver types statically known) may
/// narrow the program-wide universe to its own+outer hierarchies.
fn anyReceiverClassDeclares(b: *const FuncBuilder, name: []const u8) bool {
    if (receiverTypeKnown(b, name)) {
        if (b.ownerClass()) |oc| {
            if (ownerChainShadowContains(b, oc, name)) |ans| return ans;
        }
    }
    // E2.3: a lambda context whose receiver head is recorded answers from
    // that head plus the enclosing chain — the program-wide name universe
    // is the fallback only when neither is known.
    if (lambdaRecvHeadDeclares(b, name)) |ans| {
        if (ans) return true;
        if (b.ownerClass()) |oc| {
            if (ownerChainShadowContains(b, oc, name)) |a2| return a2;
        }
        return false;
    }
    return b.module.registry.class_member_names.contains(name);
}

fn receiverTypeKnown(b: *const FuncBuilder, name0: []const u8) bool {
    if (b.capturesThisSlot() or b.isParamThunk() or
        (b.recvTy() != null and !fnTypedRecvCannotShadow(b, name0)))
    {
        // E2.3: a receiver-LAMBDA body whose receiver head typeck
        // recorded is a known-receiver context — the membership walk can
        // answer from that head instead of the conservative fallback.
        // Audit-only until the sweep is adjudicated.
        if (recvheadAuditOn()) {
            if (eagerLambdaRecvHead(b)) |h| {
                const precise = b.module.registry.hierarchy_shadow_names.get(h) != null;
                std.debug.print("[RECVHEAD-AUDIT] '{s}' head={s} hier={}\n", .{ name0, h, precise });
            }
        }
        return false;
    }
    const oc = b.ownerClass() orelse return false;
    return ownerChainShadowContains(b, oc, "") != null;
}

/// The typeck-recorded receiver head for this builder's lambda body.
pub fn eagerLambdaRecvHead(b: *const FuncBuilder) ?[]const u8 {
    const sp = b.body_span orelse return null;
    return b.module.eagerRecvHeadOf(sp);
}

fn recvheadAuditOn() bool {
    const S = struct {
        var cached: ?bool = null;
    };
    if (S.cached) |v| return v;
    const on = runtime.envOnce("KLIO_RECVHEAD_AUDIT") != null;
    S.cached = on;
    return on;
}

var or_audit_checked: bool = false;
var or_audit_enabled: bool = false;

/// Compile-side half of the `KLIO_OR_AUDIT` detector (the runtime half
/// lives in `ir/eval.zig`): logs every member-vs-global emission decision
/// so a corpus sweep can join emit context against the runtime arm that
/// actually won.
fn orAuditOn() bool {
    if (!or_audit_checked) {
        or_audit_checked = true;
        const a = std.heap.page_allocator;
        if (runtime.procEnvGetVar(a, "KLIO_OR_AUDIT") catch null) |v| {
            defer a.free(v);
            or_audit_enabled = v.len != 0 and !std.mem.eql(u8, v, "0");
        }
    }
    return or_audit_enabled;
}

pub fn orEmitAudit(b: *const FuncBuilder, site: []const u8, inst: []const u8, name: []const u8) void {
    if (!orAuditOn()) return;
    std.debug.print(
        "[KLIO_OR_AUDIT] emit site={s} inst={s} name={s} recvctx={d} pkg={s} fn={s} recv={s}\n",
        .{ site, inst, name, @intFromBool(inReceiverContext(b)), b.self_package, build.currentRealFn() orelse "-", b.recvTy() orelse b.spliceRecvTy() orelse b.ownerClass() orelse "-" },
    );
}

var resolve_audit_checked: bool = false;
var resolve_audit_enabled: bool = false;

fn resolveAuditOn() bool {
    if (!resolve_audit_checked) {
        resolve_audit_checked = true;
        const a = std.heap.page_allocator;
        if (runtime.procEnvGetVar(a, "KLIO_RESOLVE_AUDIT") catch null) |v| {
            a.free(v);
            resolve_audit_enabled = true;
        }
    }
    return resolve_audit_enabled;
}

var resolve_strict_checked: bool = false;
var resolve_strict_enabled: bool = false;

/// Test hook: force KLIO_RESOLVE_STRICT on for the current process,
/// bypassing the once-per-process environment read, so an in-process
/// integration test can pin strict mode's verdict on a specific
/// program.
pub fn setResolveStrictForTest(on: bool) void {
    resolve_strict_checked = true;
    resolve_strict_enabled = on;
}

/// Test hook: undo `setResolveStrictForTest` — the next strict-mode
/// read consults the environment again, so a forced setting never
/// leaks past the test that installed it (including under a
/// KLIO_RESOLVE_STRICT=1 suite run).
pub fn resetResolveStrictForTest() void {
    resolve_strict_checked = false;
    resolve_strict_enabled = false;
}

fn resolveStrictOn() bool {
    if (!resolve_strict_checked) {
        resolve_strict_checked = true;
        const a = std.heap.page_allocator;
        if (runtime.procEnvGetVar(a, "KLIO_RESOLVE_STRICT") catch null) |v| {
            defer a.free(v);
            resolve_strict_enabled = v.len != 0 and !std.mem.eql(u8, v, "0");
        }
    }
    return resolve_strict_enabled;
}

/// Audit one value-position bare reference: the index's pick against
/// the order-based `funcId` pick the runtime's bare-name closure path
/// binds. A divergence where both resolve is the index correcting (or,
/// unexplained, mis-binding) the reference target; the corpus sweep
/// proves zero unexplained before the FQN emission is trusted.
fn refAudit(b: *FuncBuilder, name: []const u8, index_pick: ?FuncId) void {
    if (!resolveAuditOn()) return;
    const heur = b.module.funcId(name);
    const divergent = index_pick != null and heur != null and index_pick.?.int() != heur.?.int();
    const idx_fqn: []const u8 = if (index_pick) |i| fqnOf(b, i) else "-";
    const heur_fqn: []const u8 = if (heur) |h| fqnOf(b, h) else "-";
    std.debug.print(
        "[KLIO_RESOLVE_AUDIT] ref name={s} pkg={s} index_fqn={s} heur_fqn={s} divergent={d}\n",
        .{ name, b.self_package, idx_fqn, heur_fqn, @intFromBool(divergent) },
    );
}

fn fqnOf(b: *FuncBuilder, id: FuncId) []const u8 {
    if (b.module.funcById(id)) |f| return f.fqn;
    return "<invalid>";
}

fn isNonExt(b: *FuncBuilder, fid: FuncId) bool {
    const f = b.module.funcById(fid) orelse return true;
    return f.params.len == 0 or !std.mem.eql(u8, f.params[0].name, "this");
}

/// Whether the enclosing class (or any of its supertypes) declares a member
/// named `name`. Scoped to the current `owner_class` — a bare `::name` /
/// `this.name` can only resolve to the enclosing class's members or a global,
/// never an unrelated class's member, so a program-wide member-name set would
/// over-suppress the global-alias path.
fn enclosingDeclaresMember(b: *const FuncBuilder, name: []const u8) bool {
    const oc = b.ownerClass() orelse return false;
    const methods = b.module.registry.hierarchy_methods.get(oc) orelse return false;
    return methods.contains(name);
}

/// True when `f` shares its simple name and arity with another overload whose
/// parameter at `pidx` has a different declared type. A bare call is lowered to
/// one (arbitrarily-picked) overload before the runtime types its arguments, so
/// when the overloads disagree on a parameter's type that pick is not an
/// authoritative coercion target — re-typing a numeric literal to it (e.g.
/// turning the `Int` literal `50` into `UInt` because the lowering happened to
/// pick `minOf(UInt, UInt)`) is wrong. Leaving the literal at its natural type
/// lets the runtime overload resolver select the right form.
fn overloadParamTypeConflicts(module: *const Module, f: *const Func, pidx: usize) bool {
    if (pidx >= f.params.len) return false;
    const want_ty = f.params[pidx].ty.name;
    const cands = module.funcsBySimpleName(f.name);
    if (cands.len < 2) return false;
    for (cands) |cid| {
        const g = module.funcById(cid) orelse continue;
        if (g.params.len != f.params.len) continue;
        if (pidx >= g.params.len) continue;
        if (!std.mem.eql(u8, g.params[pidx].ty.name, want_ty)) return true;
    }
    return false;
}

const SelectedCallArgs = struct {
    args: []const Expr,
    names: []const ?[]const u8,
    owned_args: ?[]Expr = null,
    owned_names: ?[]?[]const u8 = null,
    owned_composer_path: ?[]ast.Ident = null,

    fn deinit(self: *SelectedCallArgs, allocator: Allocator) void {
        if (self.owned_args) |items| allocator.free(items);
        if (self.owned_names) |items| allocator.free(items);
        if (self.owned_composer_path) |items| allocator.free(items);
        self.* = .{ .args = &.{}, .names = &.{} };
    }
};

fn hasThreadedComposerParams(f: *const Func) bool {
    if (f.params.len < 2) return false;
    return std.mem.eql(u8, f.params[f.params.len - 2].name, "$composer") and
        std.mem.eql(u8, f.params[f.params.len - 1].name, "$changed");
}

fn sameDeclSig(a: ir.Module.DeclSig, b: ir.Module.DeclSig) bool {
    if (a.kind != b.kind or
        a.arity.required != b.arity.required or
        a.arity.total != b.arity.total or
        a.arity.has_vararg != b.arity.has_vararg or
        a.sig.len != b.sig.len)
    {
        return false;
    }
    if ((a.enclosing_class == null) != (b.enclosing_class == null)) return false;
    if (a.enclosing_class) |ac| {
        if (ac.int() != b.enclosing_class.?.int()) return false;
    }
    if ((a.receiver_ty == null) != (b.receiver_ty == null)) return false;
    if (a.receiver_ty) |ar| {
        if (!ar.eql(b.receiver_ty.?)) return false;
    }
    for (a.sig, b.sig) |ap, bp| {
        if (!ap.eql(bp)) return false;
    }
    return true;
}

/// Whether the declaration selected during lowering has the transformed
/// Compose call ABI. A reserved declaration header retains the source
/// parameter list while its body-carrying sibling owns the synthetic tail, so
/// match that sibling by the canonical declaration signature rather than by
/// simple name.
fn selectedCallHasComposerAbi(module: *const Module, func_id: FuncId, f: *const Func) bool {
    if (hasThreadedComposerParams(f)) return true;
    for (f.annotation_names) |ann| {
        if (std.mem.eql(u8, ann, "Composable") or std.mem.endsWith(u8, ann, ".Composable")) return true;
    }
    const selected_sig = module.decl_sigs.get(func_id.int()) orelse return false;
    for (module.funcsBySimpleName(f.name)) |candidate_id| {
        if (candidate_id.int() == func_id.int()) continue;
        const candidate = module.funcById(candidate_id) orelse continue;
        if (!hasThreadedComposerParams(candidate)) continue;
        if (!std.mem.eql(u8, candidate.fqn, f.fqn)) continue;
        const candidate_sig = module.decl_sigs.get(candidate_id.int()) orelse continue;
        if (sameDeclSig(selected_sig, candidate_sig)) return true;
    }
    return false;
}

fn selectedCallArgs(module: *const Module, func_id: FuncId, args: []const Expr, names: []const ?[]const u8) SelectedCallArgs {
    if (args.len < 2 or names.len != args.len) return .{ .args = args, .names = names };
    const composer_name = names[names.len - 2] orelse return .{ .args = args, .names = names };
    const changed_name = names[names.len - 1] orelse return .{ .args = args, .names = names };
    if (!std.mem.eql(u8, composer_name, "$composer") or
        !std.mem.eql(u8, changed_name, "$changed"))
    {
        return .{ .args = args, .names = names };
    }
    const f = module.funcById(func_id) orelse return .{ .args = args, .names = names };
    if (selectedCallHasComposerAbi(module, func_id, f)) {
        compose_pass.compose_audit.threaded_agree += 1;
        return .{ .args = args, .names = names };
    }
    compose_pass.compose_audit.pair_stripped += 1;
    if (compose_pass.composeAuditOn()) {
        std.debug.print(
            "[KLIO_RESOLVE_AUDIT] compose pair-stripped target={s}#{d}\n",
            .{ f.fqn, func_id.int() },
        );
    }
    return .{
        .args = args[0 .. args.len - 2],
        .names = names[0 .. names.len - 2],
    };
}

fn hasComposerArgPair(names: []const ?[]const u8) bool {
    if (names.len < 2) return false;
    const composer_name = names[names.len - 2] orelse return false;
    const changed_name = names[names.len - 1] orelse return false;
    return std.mem.eql(u8, composer_name, "$composer") and
        std.mem.eql(u8, changed_name, "$changed");
}

/// Complete the exact selected Compose ABI from the current lowered scope.
/// The AST pass normally supplies this pair, but a cross-pack caller may have
/// been transformed before the callee joined its simple-name oracle. The
/// selected declaration and the synthesized `$composer` binding are direct
/// evidence, so emission can still produce the same static call.
fn selectedCallArgsForBuilder(
    b: *FuncBuilder,
    func_id: FuncId,
    args: []const Expr,
    names: []const ?[]const u8,
    call_span: ast.Span,
    trailing_lambda: bool,
) Allocator.Error!SelectedCallArgs {
    var selected = selectedCallArgs(b.module, func_id, args, names);
    const f = b.module.funcById(func_id) orelse return selected;
    if (!hasComposerArgPair(selected.names)) {
        const has_abi = selectedCallHasComposerAbi(b.module, func_id, f);
        const composer = b.resolve("$composer");
        if (runtime.envOnce("KLIO_BARE_TRACE")) |w| {
            if (std.mem.eql(u8, w, f.name)) {
                std.debug.print(
                    "[compose-abi] {s}#{d} caller={s} has_abi={} composer={} args={d}\n",
                    .{
                        f.fqn,
                        func_id.int(),
                        build.currentRealFn() orelse "-",
                        has_abi,
                        composer != null,
                        args.len,
                    },
                );
            }
        }
        if (has_abi and composer != null) {
            compose_pass.compose_audit.pair_completed += 1;
            if (compose_pass.composeAuditOn()) {
                std.debug.print(
                    "[KLIO_RESOLVE_AUDIT] compose pair-completed target={s}#{d} caller={s}\n",
                    .{ f.fqn, func_id.int(), build.currentRealFn() orelse "-" },
                );
            }
            const completed_args = try b.allocator.alloc(Expr, selected.args.len + 2);
            errdefer b.allocator.free(completed_args);
            @memcpy(completed_args[0..selected.args.len], selected.args);
            const composer_path = try b.allocator.alloc(ast.Ident, 1);
            errdefer b.allocator.free(composer_path);
            composer_path[0] = .{ .name = "$composer", .span = call_span };
            completed_args[selected.args.len] = .{ .Path = .{ .segments = composer_path, .span = call_span } };
            completed_args[selected.args.len + 1] = try composeChangedBits(b, f, selected.args, selected.names, trailing_lambda, call_span);

            const completed_names = try b.allocator.alloc(?[]const u8, selected.names.len + 2);
            errdefer b.allocator.free(completed_names);
            @memcpy(completed_names[0..selected.names.len], selected.names);
            completed_names[selected.names.len] = "$composer";
            completed_names[selected.names.len + 1] = "$changed";

            selected.owned_args = completed_args;
            selected.owned_names = completed_names;
            selected.owned_composer_path = composer_path;
            selected.args = completed_args;
            selected.names = completed_names;
        }
    }
    try transformSelectedComposableArgs(b, f, selected.args, selected.names, trailing_lambda);
    return selected;
}

/// The `$changed` value for a lowering-completed composable call: per-arg
/// certainty bits at the RESOLVED callee's triple positions (3 bits per
/// value param above the forced bit, kotlinc's layout). A literal argument
/// is STATIC (`0b110 << 3i`, a compile-time constant of the site); a bare
/// forward of one of the caller's own value params recombines the caller's
/// live `$dirty` triple into the callee position, so the callee's guarded
/// probe (`if ($changed and (0b110 << 3i) == 0)`) skips and its slot is
/// never taken — the drop from klio's 22 slots to kotlinc's 18 on the
/// checkboxLike anchor. Everything else claims nothing.
fn composeChangedBits(
    b: *FuncBuilder,
    f: *const Func,
    args: []const Expr,
    names: []const ?[]const u8,
    trailing_lambda: bool,
    call_span: ast.Span,
) Allocator.Error!Expr {
    var const_bits: i64 = 0;
    var dyn: ?Expr = null;
    const caller_dirty = b.resolve("$dirty") != null;
    const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
    var user_param_end = f.params.len;
    if (f.params.len >= 2 and std.mem.eql(u8, f.params[f.params.len - 2].name, "$composer")) user_param_end -= 2;
    var next_param: usize = recv_off;
    for (args, 0..) |*arg, arg_index| {
        var param_index: ?usize = null;
        if (trailing_lambda and arg_index + 1 == args.len and user_param_end != 0) {
            param_index = user_param_end - 1;
        } else if (arg_index < names.len and names[arg_index] != null) {
            for (f.params, 0..) |param, i| {
                if (applicability.paramNameMatchesArg(param.name, names[arg_index].?)) {
                    param_index = i;
                    break;
                }
            }
        } else {
            param_index = next_param;
        }
        const pi = param_index orelse continue;
        next_param = @max(next_param, pi + 1);
        if (pi < recv_off or pi >= user_param_end) continue;
        const triple = pi - recv_off;
        if (triple >= 9) continue;
        const callee_param = &f.params[pi];
        if (callee_param.is_vararg) continue;
        switch (arg.*) {
            .IntLit, .BoolLit, .CharLit, .FloatLit, .NullLit => {
                const_bits |= @as(i64, 6) << @intCast(3 * triple);
            },
            // `$composer.cache(false, { … })` — the plugin's memo of a
            // ZERO-capture lambda: the cached instance never invalidates,
            // so the argument is static exactly like kotlinc's lifted
            // singleton lambda; the callee's changedInstance probe (and
            // its slot) is unnecessary.
            .Call => |cc| {
                if (cc.callee.* == .Member and std.mem.eql(u8, cc.callee.Member.name.name, "cache") and
                    cc.args.len >= 1 and cc.args[0] == .BoolLit and !cc.args[0].BoolLit.value)
                {
                    const_bits |= @as(i64, 6) << @intCast(3 * triple);
                }
            },
            .Path => |p| fwd: {
                if (p.segments.len != 1) break :fwd;
                // A lifted memo singleton is a permanent instance — static.
                if (std.mem.startsWith(u8, p.segments[0].name, "$klio$memo$")) {
                    const_bits |= @as(i64, 6) << @intCast(3 * triple);
                    break :fwd;
                }
                if (!caller_dirty) break :fwd;
                const nm = p.segments[0].name;
                // A DEFAULTED caller param was renamed `p$arg` by the plugin
                // and the body reads the prologue local `p` — its triple is
                // still live (the probe reads the resolved value; a taken
                // default sets the same-bit), so it forwards like any other.
                var renamed_default = false;
                const j = for (b.compose_value_params, 0..) |*cp2, k| {
                    if (std.mem.eql(u8, cp2.name.name, nm)) break k;
                    if (cp2.name.name.len == nm.len + 4 and
                        std.mem.startsWith(u8, cp2.name.name, nm) and
                        std.mem.endsWith(u8, cp2.name.name, "$arg"))
                    {
                        renamed_default = true;
                        break k;
                    }
                } else break :fwd;
                if (j >= 9) break :fwd;
                const cp = &b.compose_value_params[j];
                if (cp.is_vararg) break :fwd;
                // A body local shadowing the param name would misattribute
                // the triple; only a binding that is still the parameter's
                // own (or its defaults-prologue local) may recombine.
                if (!renamed_default and !b.isParam(nm)) break :fwd;
                const sp = call_span;
                const dirty_ref = try composeBitsPath(b.allocator, "$dirty", sp);
                var term: Expr = undefined;
                if (j == triple) {
                    term = try composeBitsCall1(b.allocator, dirty_ref, "and", composeBitsInt(@as(i64, 6) << @intCast(3 * triple), sp), sp);
                } else {
                    const shifted = try composeBitsCall1(b.allocator, dirty_ref, "shr", composeBitsInt(3 * @as(i64, @intCast(j)), sp), sp);
                    const masked = try composeBitsCall1(b.allocator, shifted, "and", composeBitsInt(6, sp), sp);
                    term = try composeBitsCall1(b.allocator, masked, "shl", composeBitsInt(3 * @as(i64, @intCast(triple)), sp), sp);
                }
                dyn = if (dyn) |acc| try composeBitsCall1(b.allocator, acc, "or", term, sp) else term;
            },
            else => {},
        }
    }
    if (dyn) |d| {
        if (const_bits == 0) return d;
        return try composeBitsCall1(b.allocator, d, "or", composeBitsInt(const_bits, call_span), call_span);
    }
    return composeBitsInt(const_bits, call_span);
}

fn composeBitsInt(v: i64, sp: ast.Span) Expr {
    return .{ .IntLit = .{ .value = v, .kind = .Int, .span = sp } };
}

fn composeBitsPath(alloc: Allocator, nm: []const u8, sp: ast.Span) Allocator.Error!Expr {
    const segs = try alloc.alloc(ast.Ident, 1);
    segs[0] = .{ .name = nm, .span = sp };
    return .{ .Path = .{ .segments = segs, .span = sp } };
}

fn composeBitsCall1(alloc: Allocator, recv: Expr, nm: []const u8, a0: Expr, sp: ast.Span) Allocator.Error!Expr {
    const recv_p = try alloc.create(Expr);
    recv_p.* = recv;
    const cargs = try alloc.alloc(Expr, 1);
    cargs[0] = a0;
    const cnames = try alloc.alloc(?[]const u8, 1);
    cnames[0] = null;
    const callee = try alloc.create(Expr);
    callee.* = .{ .Member = .{
        .receiver = recv_p,
        .name = .{ .name = nm, .span = sp },
        .safe = false,
        .span = sp,
    } };
    return .{ .Call = .{
        .callee = callee,
        .args = cargs,
        .arg_names = cnames,
        .type_args = &.{},
        .is_infix = false,
        .has_trailing_lambda = false,
        .span = sp,
    } };
}

fn transformSelectedComposableArgs(
    b: *FuncBuilder,
    f: *const Func,
    args: []const Expr,
    names: []const ?[]const u8,
    trailing_lambda: bool,
) Allocator.Error!void {
    if (b.resolve("$composer") == null or args.len == 0) return;
    const occupied = try b.allocator.alloc(bool, f.params.len);
    defer b.allocator.free(occupied);
    @memset(occupied, false);
    var next_param: usize = 0;
    if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) {
        occupied[0] = true;
        next_param = 1;
    }
    const user_arg_end = if (hasComposerArgPair(names)) args.len - 2 else args.len;
    var user_param_end = f.params.len;
    if (hasThreadedComposerParams(f)) user_param_end -= 2;
    for (args, 0..) |_, arg_index| {
        var param_index: ?usize = null;
        if (trailing_lambda and arg_index + 1 == user_arg_end and user_param_end != 0) {
            param_index = user_param_end - 1;
        } else if (arg_index < names.len) {
            if (names[arg_index]) |arg_name| {
                for (f.params, 0..) |param, i| {
                    if (applicability.paramNameMatchesArg(param.name, arg_name)) {
                        param_index = i;
                        break;
                    }
                }
            }
        }
        if (param_index == null) {
            while (next_param < f.params.len and occupied[next_param]) next_param += 1;
            if (next_param < f.params.len) {
                param_index = next_param;
                next_param += 1;
            }
        }
        const pi = param_index orelse continue;
        occupied[pi] = true;
        const expected = f.params[pi].composable_arity orelse {
            if (runtime.envOnce("KLIO_BARE_TRACE")) |want| {
                if (std.mem.eql(u8, want, f.name)) {
                    std.debug.print(
                        "[compose-param] {s}#{d} arg={d} param={s} composable=false\n",
                        .{ f.fqn, f.id.int(), arg_index, f.params[pi].name },
                    );
                }
            }
            continue;
        };
        if (runtime.envOnce("KLIO_BARE_TRACE")) |want| {
            if (std.mem.eql(u8, want, f.name)) {
                std.debug.print(
                    "[compose-param] {s}#{d} arg={d} param={s} composable=true arity={d}\n",
                    .{ f.fqn, f.id.int(), arg_index, f.params[pi].name, expected },
                );
            }
        }
        // The synthetic slot count comes from the RESOLVED parameter: its
        // declared arity plus, for a non-inline sink, the receiver/context
        // slots the value protocol flattens in front (an inline sink
        // splices with the receiver bound as `this`, no slot).
        const expected_slots: u8 = if (f.is_inline)
            expected
        else
            expected +| f.params[pi].composable_recv_slots;
        _ = try compose_pass.transformResolvedComposableLambda(
            b.allocator,
            @constCast(&args[arg_index]),
            expected_slots,
            f.name,
            f.is_inline,
        );
    }
}

/// The `Call` emit form: a resolved bare-name static call. A committed
/// non-extension target lowers to a direct `Call` (or a `TailCallFunc` in a
/// tailrec body); an extension target routes through `emitExtBareCall`, which
/// prepends `this`. `resolveCall` has already decided this is a static call, so
/// the member-vs-global walk lives in `emitMemberOrGlobal`, not here.
fn emitCall(b: *FuncBuilder, expr: *const Expr, func_id: FuncId, was_cast: bool) Allocator.Error!Reg {
    const call = expr.Call;
    if (runtime.envOnce("KLIO_EMIT_TRACE") != null) {
        const c0 = call.callee;
        if (c0.* == .Path and c0.Path.segments.len == 1 and std.mem.eql(u8, c0.Path.segments[0].name, "remember") and @intFromEnum(c0.Path.segments[0].span.file) == 0) {
            std.debug.print("[emitCall] remember -> #{d} nargs={d}\n", .{ func_id.int(), call.args.len });
            runtime.trace.dumpCurrent(.{});
        }
    }
    var selected_args = try selectedCallArgsForBuilder(b, func_id, call.args, call.arg_names, exprSpan(call.callee), call.has_trailing_lambda);
    defer selected_args.deinit(b.allocator);
    const args = selected_args.args;
    const ast_arg_names = selected_args.names;
    const ast_type_args = call.type_args;
    const prev_trailing = b.setCallTrailingLambda(
        call.has_trailing_lambda and !hasComposerArgPair(ast_arg_names),
    );
    defer _ = b.setCallTrailingLambda(prev_trailing);

    // The committed target is overload-precise, so its receiver-function
    // parameter types are authoritative even when the source callee is an
    // alias with no same-named entry in the function index.
    if (b.module.funcById(func_id)) |f| {
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        try recordLambdaArgReceivers(b, f, args, ast_arg_names, ast_type_args, recv_off);
        applyExpectedLiteralKindsToArgs(b, f, args, ast_arg_names, recv_off);
    }

    const needs_this = blk: {
        if (b.module.funcById(func_id)) |f| {
            break :blk f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this");
        }
        break :blk false;
    };
    if (needs_this) {
        const this_reg_opt = try resolveThisForBareCall(b);
        if (this_reg_opt) |this_reg0| {
            const this_reg = blk: {
                const c0 = call.callee;
                if (c0.* == .Path and c0.Path.segments.len == 1) {
                    break :blk subjectCorrectedBareThis(b, c0.Path.segments[0].name, this_reg0);
                }
                break :blk this_reg0;
            };
            return emitExtBareCall(b, expr, func_id, this_reg, was_cast);
        }
        // No `this` in scope — fall through to the unmodified Call below.
    }

    const callee_is_tailrec = blk: {
        if (b.module.funcById(func_id)) |f| {
            if (f.is_tailrec) break :blk true;
        }
        break :blk false;
    };
    if (b.tailrecSelf() != null and callee_is_tailrec and allNull(ast_arg_names)) {
        const run = try lowerArgRun(b, args);
        b.terminate(.{ .TailCallFunc = .{ .func = func_id, .args = run[0], .n_args = run[1] } });
        const dead = try b.allocBlock();
        b.switchTo(dead);
        return b.emitConst(.Unit);
    }
    // A bare call a runtime implicit receiver could shadow is routed by
    // `resolveCall` to the `CallMemberOrGlobal` emit form (`emitMemberOrGlobal`),
    // never here: reaching `emitCall` means the resolver already committed to the
    // static call, so this emitter only ever emits the direct `Call`.
    const arg_arity: ?[]const i16 = blk: {
        if (b.module.funcById(func_id)) |f| {
            const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
            break :blk try argFnArities(b, f, args, ast_arg_names, recv_off);
        }
        break :blk null;
    };
    const param_ty_names: ?[]const ?[]const u8 = blk: {
        const f = b.module.funcById(func_id) orelse break :blk null;
        if (!allNull(ast_arg_names)) break :blk null;
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        const names = try b.allocator.alloc(?[]const u8, args.len);
        for (names, 0..) |*t, j| {
            const pidx = recv_off + j;
            if (pidx < f.params.len and !f.params[pidx].is_vararg and
                !overloadParamTypeConflicts(b.module, f, pidx))
            {
                t.* = f.params[pidx].ty.name;
            } else {
                t.* = null;
            }
        }
        break :blk names;
    };
    defer if (param_ty_names) |pt| b.allocator.free(pt);
    const broad_masks: ?[]u32 = blk: {
        const f = b.module.funcById(func_id) orelse break :blk null;
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        break :blk try argLambdaBroadMasks(b, f, args, ast_arg_names, recv_off);
    };
    defer if (broad_masks) |m| b.allocator.free(m);
    b.pending_arg_broad_masks = broad_masks;
    const fn_generic: ?[]bool = blk: {
        const f = b.module.funcById(func_id) orelse break :blk null;
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        break :blk try argFnGenericFlags(b, f, args, ast_arg_names, recv_off);
    };
    defer if (fn_generic) |m| b.allocator.free(m);
    b.pending_arg_fn_generic = fn_generic;
    var lpt_recv_owned: ?ir.TypeRef = null;
    defer if (lpt_recv_owned) |*t| t.deinit(b.allocator);
    const lambda_param_types: ?[]?[]ir.TypeRef = blk: {
        const f = b.module.funcById(func_id) orelse break :blk null;
        const recv_off: usize = if (f.params.len != 0 and
            std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        // A MEMBER-form call to an extension carries its receiver in the
        // callee: derive it so the lambda's params instantiate
        // (`dropped.associateWith { name -> ... }` on a DERIVED local left
        // the slot at bare `T`; the annotated form already bound String).
        const recv_ptr: ?*const ir.TypeRef = rp: {
            if (recv_off != 1) break :rp null;
            const ce = expr.Call.callee;
            if (ce.* != .Member) break :rp null;
            lpt_recv_owned = staticExprTypeRef(b, ce.Member.receiver) catch null;
            break :rp if (lpt_recv_owned) |*t| t else null;
        };
        if (runtime.envOnce("KLIO_ALPT") != null) std.debug.print("[alpt-site] emitCall fn={s} recv={s} callee={s} roff={d}\n", .{ f.name, if (recv_ptr) |r| r.name else "<null>", @tagName(std.meta.activeTag(expr.Call.callee.*)), recv_off });
        break :blk try argLambdaParamTypesRecv(
            b,
            f,
            args,
            ast_arg_names,
            ast_type_args,
            recv_off,
            recv_ptr,
        );
    };
    defer if (lambda_param_types) |types|
        deinitArgLambdaParamTypes(b.allocator, types);
    b.pending_arg_lambda_param_types = lambda_param_types;
    const run = try lowerArgRunFull(b, args, arg_arity, param_ty_names);
    // A trailing lambda always binds the target's last (function-typed)
    // parameter. When a vararg parameter precedes it, positional binding
    // would otherwise pack the lambda into the vararg and leave the last
    // parameter unfilled (Kotlin forbids a positional argument after a
    // vararg, so the trailing lambda is the only filler). Name the lambda
    // to the last parameter so the runtime binds it correctly.
    const arg_names = try trailingLambdaArgNames(b, func_id, args, ast_arg_names);
    var type_args = try helpers.internTypeArgsScoped(b, ast_type_args);
    if (type_args.len == 0) {
        if (try spliceReifiedTypeArgs(b, func_id, args.len)) |stamped| type_args = stamped;
    }
    const dst = b.allocReg();
    try b.push(.{ .Call = .{
        .dst = dst,
        .func = func_id,
        .trailing_lambda = b.callTrailingLambda(),
        .args = run[0],
        .n_args = run[1],
        .arg_names = arg_names,
        .type_args = type_args,
        .exact = was_cast,
    } });
    return dst;
}

/// Sibling-arg reified inference: when an argument of a resolved call is
/// itself a bare 0-arg call to a single-type-param fn with no type args
/// (`enumEntries()`), and a SIBLING argument bound to the same declared
/// type variable statically names an enum (`EmptyEnum.entries`,
/// `EmptyEnum.values().toList()`), the enum solves the nested call's
/// reified argument. Records the solution keyed by the nested call's AST
/// node; `emitCall` consumes it when that node lowers with no type args
/// of its own.
/// `::name` in a slot whose DECLARED function type solves the referenced
/// fn's single reified type parameter (`val empty: () -> EnumEntries<E> =
/// ::enumEntries`): the reference lowers as a zero-arg closure over the
/// call with the solved type argument stamped — a plain function value
/// carries no type args, so invoking it later would lose the reification.
/// AST synthesized from the MODULE allocator (lambda bodies are
/// runtime-read).
/// Eta-expand a bare `::localExt` reference into
/// `{ p0..pN -> localExt(p0..pN) }`: the synthesized bare call resolves
/// the local extension through the ordinary local-ext machinery (its
/// receiver supplied by the enclosing `this`), and the closure carries
/// the value-parameter arity the reference's use site applies.
fn localExtRefClosure(b: *FuncBuilder, name: []const u8, sp: ast.Span) Allocator.Error!?Reg {
    // Value-parameter count: the declaring builder recorded the local fn's
    // positional params; inside a nested lambda builder that record is not
    // inherited, so the use site's expected callable arity (the
    // function-typed parameter slot the reference fills) supplies it.
    const n: usize = blk: {
        if (b.localExtFnArity(name)) |a| break :blk @intCast(a);
        if (b.localFnParamTys(name)) |tys| break :blk tys.len;
        if (b.pending_lambda_arity >= 0) break :blk @intCast(b.pending_lambda_arity);
        if (b.peekExpected()) |exp| {
            if (exp.function) |ft| break :blk ft.params.len;
        }
        return null;
    };
    const ma = b.module.func_name_index.allocator;
    const params = try ma.alloc(ast.Ident, n);
    const args = try ma.alloc(ast.Expr, n);
    for (0..n) |i| {
        const pn = try std.fmt.allocPrint(ma, "$ref$p{d}", .{i});
        params[i] = .{ .name = pn, .span = sp };
        const segs_i = try ma.alloc(ast.Ident, 1);
        segs_i[0] = .{ .name = pn, .span = sp };
        args[i] = .{ .Path = .{ .segments = segs_i, .span = sp } };
    }
    const anames = try ma.alloc(?[]const u8, n);
    for (anames) |*a| a.* = null;
    const segs = try ma.alloc(ast.Ident, 1);
    segs[0] = .{ .name = try ma.dupe(u8, name), .span = sp };
    const callee = try ma.create(ast.Expr);
    callee.* = .{ .Path = .{ .segments = segs, .span = sp } };
    const stmts = try ma.alloc(ast.Stmt, 1);
    stmts[0] = .{ .Expr = .{ .Call = .{
        .callee = callee,
        .args = args,
        .arg_names = anames,
        .type_args = &.{},
        .is_infix = false,
        .span = sp,
    } } };
    const boxed = try ma.create(ast.Expr);
    boxed.* = .{ .Lambda = .{
        .params = params,
        .body = .{ .stmts = stmts, .span = sp },
        .span = sp,
        .implicit_it = false,
    } };
    return try lowerExpr(b, boxed);
}

fn reifiedRefClosure(b: *FuncBuilder, name: []const u8, sp: ast.Span) Allocator.Error!?Reg {
    const expected = b.peekExpected() orelse return null;
    const fnty = expected.function orelse return null;
    if (fnty.params.len != 0) return null;
    if (fnty.ret.type_args.len != 1) return null;
    const fid = b.module.funcId(name) orelse return null;
    const tps = b.module.registry.func_type_params.get(fid) orelse return null;
    if (tps.items.len != 1) return null;
    const ma = b.module.func_name_index.allocator;
    const segs = try ma.alloc(ast.Ident, 1);
    segs[0] = .{ .name = try ma.dupe(u8, name), .span = sp };
    const callee = try ma.create(ast.Expr);
    callee.* = .{ .Path = .{ .segments = segs, .span = sp } };
    const ta = try ma.alloc(ast.TypeRef, 1);
    ta[0] = fnty.ret.type_args[0].ty;
    const stmts = try ma.alloc(ast.Stmt, 1);
    stmts[0] = .{ .Expr = .{ .Call = .{
        .callee = callee,
        .args = &.{},
        .arg_names = &.{},
        .type_args = ta,
        .is_infix = false,
        .span = sp,
    } } };
    const lam: ast.Expr = .{ .Lambda = .{
        .params = &.{},
        .body = .{ .stmts = stmts, .span = sp },
        .span = sp,
        .implicit_it = false,
    } };
    const boxed = try ma.create(ast.Expr);
    boxed.* = lam;
    return try lowerExpr(b, boxed);
}

const SibSolved = struct { site: *const Expr, ty: ast.TypeRef };

/// Candidate walk for the comparator-sibling solve: same-simple-name
/// functions filtered by ARITY fit and by whether the declared receiver can
/// SERVE the call's actual receiver head — first-fit by arity alone handed
/// `List<String>.minOfWith` to the CharSequence variant, whose `(Char) -> R`
/// selector poisons the element binding.
fn solveComparatorSiblingByName(
    b: *FuncBuilder,
    callee: *const Expr,
    name: []const u8,
    args: []const Expr,
) ?SibSolved {
    var actual_owned: ?ir.TypeRef = switch (callee.*) {
        .Member => |m| (staticExprTypeRef(b, m.receiver) catch null),
        else => null,
    };
    defer if (actual_owned) |*t| t.deinit(b.allocator);
    const actual_head: ?[]const u8 = blk: {
        if (actual_owned) |t| break :blk typeHead(std.mem.trimEnd(u8, t.name, "?"));
        const h = b.recvTy() orelse b.spliceRecvTy() orelse b.enclosingRecvTy() orelse break :blk null;
        break :blk typeHead(std.mem.trimEnd(u8, h, "?"));
    };
    for (b.module.funcsBySimpleName(name)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (!outerArityFits(f, args.len)) continue;
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        if (recv_off == 1) {
            const ah = actual_head orelse continue;
            var dr = std.mem.trimEnd(u8, f.params[0].ty.name, "?");
            if (std.mem.indexOfScalar(u8, dr, '<')) |lt| dr = dr[0..lt];
            const dh = typeHead(dr);
            if (!(std.mem.eql(u8, ah, dh) or dh.len <= 2 or
                ir.parseClassTypeParamIdentity(f.params[0].ty.name) != null or
                receiverHeadServes(b, ah, dh))) continue;
        }
        if (solveComparatorSibling(b, callee, f, recv_off, args)) |solved| return solved;
    }
    return null;
}

/// `minOfWith(compareBy { it.reversed() }) { it.take(3) }`: the outer call's
/// `R` lives only in the trailing selector's RETURN, so it solves by
/// deriving that literal's tail under the receiver-element binding — any
/// tail kind, because the result feeds one sibling argument's EXPECTED type
/// and never instantiates a type variable of the outer callee (the recorded
/// member-tail hazard). The sibling declared `Comparator<in R>` then lowers
/// with `Comparator<derived>` expected, which binds compareBy's own type
/// parameter and types its lambda.
fn solveComparatorSibling(
    b: *FuncBuilder,
    callee: *const Expr,
    f: *const ir.Func,
    recv_off: usize,
    args: []const Expr,
) ?SibSolved {
    const sib_trace = runtime.envOnce("KLIO_SIBEXP_TRACE") != null;
    if (args[args.len - 1] != .Lambda) return null;
    const lam = args[args.len - 1].Lambda;
    const stmts = lam.body.stmts;
    if (stmts.len == 0 or stmts[stmts.len - 1] != .Expr) return null;
    const pk = recv_off + args.len - 1;
    if (pk >= f.params.len) return null;
    const sel_ty = f.params[pk].ty;
    if (!std.mem.startsWith(u8, typeHead(sel_ty.name), "Function") or sel_ty.args.len < 2) {
        if (sib_trace) std.debug.print("[sibexp-bail] outer={s} sel_head={s} sel_args={d}\n", .{ f.fqn, sel_ty.name, sel_ty.args.len });
        return null;
    }
    const r_name = std.mem.trimEnd(u8, sel_ty.args[sel_ty.args.len - 1].name, "?");
    if (r_name.len == 0 or r_name.len > 2 or !std.ascii.isUpper(r_name[0])) {
        if (sib_trace) std.debug.print("[sibexp-bail] outer={s} r_name={s}\n", .{ f.fqn, r_name });
        return null;
    }
    var site: ?*const Expr = null;
    var head: []const u8 = "";
    for (args[0 .. args.len - 1], 0..) |*arg, j| {
        const pj = recv_off + j;
        if (pj >= f.params.len) continue;
        const pt = f.params[pj].ty;
        if (pt.args.len != 1) continue;
        var a0 = std.mem.trimEnd(u8, pt.args[0].name, "?");
        if (std.mem.startsWith(u8, a0, "in#")) a0 = a0[3..];
        if (std.mem.startsWith(u8, a0, "out#")) a0 = a0[4..];
        if (!std.mem.eql(u8, a0, r_name)) continue;
        if (arg.* != .Call) continue;
        site = arg;
        head = typeHead(std.mem.trimEnd(u8, pt.name, "?"));
        break;
    }
    const s = site orelse {
        if (sib_trace) {
            std.debug.print("[sibexp-bail] outer={s} no_sibling_site r={s}\n", .{ f.fqn, r_name });
            for (args[0 .. args.len - 1], 0..) |*arg, j| {
                const pj = recv_off + j;
                if (pj >= f.params.len) continue;
                const pt = f.params[pj].ty;
                std.debug.print("[sibexp-bail]   arg{d} tag={s} p_name={s} p_args={d} p_arg0={s}\n", .{
                    j,
                    @tagName(arg.*),
                    pt.name,
                    pt.args.len,
                    if (pt.args.len != 0) pt.args[0].name else "-",
                });
            }
        }
        return null;
    };
    if (head.len == 0 or head.len <= 2) return null;
    const inputs = sel_ty.args[0 .. sel_ty.args.len - 1];
    var nb = FuncBuilder.init(b.allocator, b.module) catch return null;
    nb.census_quiet = true;
    defer nb.deinit();
    var elem_owned: ?ir.TypeRef = null;
    defer if (elem_owned) |*t| t.deinit(b.allocator);
    var i: usize = 0;
    while (i < inputs.len) : (i += 1) {
        const pname = if (lam.params.len == 0 and inputs.len == 1)
            "it"
        else if (i < lam.params.len)
            lam.params[i].name
        else
            return null;
        const declared = inputs[i];
        const dh = typeHead(std.mem.trimEnd(u8, declared.name, "?"));
        if (staticTypeClassId(b, declared) != null or isPrimitiveTypeName(dh)) {
            nb.setLocalDeclTypeOwned(pname, declared.clone(b.allocator) catch return null) catch return null;
        } else if (dh.len <= 2 or ir.parseClassTypeParamIdentity(declared.name) != null) {
            if (inputs.len != 1) return null;
            if (elem_owned == null) {
                elem_owned = switch (callee.*) {
                    .Member => |m| iterableElementTypeRef(b, m.receiver) catch null,
                    else => blk: {
                        const this_expr: Expr = .{ .This = .{ .qualifier = null, .span = exprSpan(s) } };
                        break :blk iterableElementTypeRef(b, &this_expr) catch null;
                    },
                };
            }
            const elem = elem_owned orelse return null;
            nb.setLocalDeclTypeOwned(pname, elem.clone(b.allocator) catch return null) catch return null;
        } else return null;
    }
    od_depth += 1;
    const derived = staticExprTypeRef(&nb, &stmts[stmts.len - 1].Expr) catch null;
    od_depth -= 1;
    var derived_ty = derived orelse {
        if (sib_trace) std.debug.print("[sibexp-bail] outer={s} derive=null\n", .{f.fqn});
        return null;
    };
    defer derived_ty.deinit(b.allocator);
    const derived_head = typeHead(std.mem.trimEnd(u8, derived_ty.name, "?"));
    if (derived_head.len <= 2) return null;
    if (staticTypeClassId(b, derived_ty) == null and !isPrimitiveTypeName(derived_head)) {
        if (sib_trace) std.debug.print("[sibexp-bail] outer={s} derived_no_class={s}\n", .{ f.fqn, derived_head });
        return null;
    }
    const sp = exprSpan(s);
    const head_owned = b.allocator.dupe(u8, head) catch return null;
    const derived_owned = b.allocator.dupe(u8, derived_head) catch return null;
    const ta = b.allocator.alloc(ast.TypeArg, 1) catch return null;
    ta[0] = .{
        .variance = .Invariant,
        .is_star = false,
        .ty = .{ .name = .{ .name = derived_owned, .span = sp }, .nullable = false, .span = sp, .type_args = &.{}, .function = null, .definitely_non_null = false, .annotations = &.{}, .qualified_path = null },
        .span = sp,
    };
    if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) {
        std.debug.print("[sibexp] outer={s} head={s} derived={s}\n", .{ f.fqn, head_owned, derived_owned });
    }
    return .{ .site = s, .ty = .{ .name = .{ .name = head_owned, .span = sp }, .nullable = false, .span = sp, .type_args = ta, .function = null, .definitely_non_null = false, .annotations = &.{}, .qualified_path = null } };
}

/// Whether every head in `ty` (through its arguments) names something the
/// receiving scope can resolve — no bare type parameters, no class-param
/// identity mangles. Variance prefixes are spelling, not structure.
fn irTypeFullyConcrete(b: *const FuncBuilder, ty: ir.TypeRef) bool {
    var h = std.mem.trimEnd(u8, ty.name, "?");
    if (std.mem.startsWith(u8, h, "in#")) h = h[3..];
    if (std.mem.startsWith(u8, h, "out#")) h = h[4..];
    if (std.mem.indexOfScalar(u8, h, '<')) |lt| h = h[0..lt];
    const head = typeHead(h);
    if (head.len == 0) return false;
    if ((head.len <= 2 and std.ascii.isUpper(head[0])) or b.isTypeParam(head) or
        ir.parseClassTypeParamIdentity(head) != null) return false;
    for (ty.args) |a| {
        if (!irTypeFullyConcrete(b, a)) return false;
    }
    return true;
}

/// A lowered type as source-shaped AST, for the expected-type stack.
/// Variance mangles strip; a trailing-`?` spelling folds into `nullable`.
pub fn astTypeRefFromIr(b: *FuncBuilder, ty: ir.TypeRef, sp: ast.Span) ?ast.TypeRef {
    var nm = std.mem.trimEnd(u8, ty.name, "?");
    const spelled_nullable = nm.len != ty.name.len;
    if (std.mem.startsWith(u8, nm, "in#")) nm = nm[3..];
    if (std.mem.startsWith(u8, nm, "out#")) nm = nm[4..];
    if (std.mem.indexOfScalar(u8, nm, '<')) |lt| nm = nm[0..lt];
    if (nm.len == 0) return null;
    const owned = b.allocator.dupe(u8, nm) catch return null;
    const tas = b.allocator.alloc(ast.TypeArg, ty.args.len) catch return null;
    for (ty.args, tas) |a, *out| {
        // A star projection is a projection, not a type named `*`: it
        // binds nothing (`DeserializationStrategy<*>` as an expected type
        // must not solve a reified `T := *`).
        if (std.mem.eql(u8, std.mem.trimEnd(u8, a.name, "?"), "*")) {
            out.* = .{ .variance = .Invariant, .is_star = true, .ty = .{
                .name = .{ .name = "*", .span = sp },
                .nullable = false,
                .span = sp,
                .type_args = &.{},
                .function = null,
                .definitely_non_null = false,
                .annotations = &.{},
                .qualified_path = null,
            }, .span = sp };
            continue;
        }
        const inner = astTypeRefFromIr(b, a, sp) orelse return null;
        out.* = .{ .variance = .Invariant, .is_star = false, .ty = inner, .span = sp };
    }
    return .{
        .name = .{ .name = owned, .span = sp },
        .nullable = ty.nullable or spelled_nullable,
        .span = sp,
        .type_args = tas,
        .function = null,
        .definitely_non_null = false,
        .annotations = &.{},
        .qualified_path = null,
    };
}

/// The general arm: a committed-shape callee's RECEIVER (plus the call
/// site's own expected type) instantiates a call-shaped argument's declared
/// parameter type, which becomes that argument's expected type —
/// `it.sortedWith(nullsFirst(...))` on a `List<String?>` hands `nullsFirst`
/// `Comparator<in String?>`; `nullsFirst`'s own lowering then repeats the
/// same solve one level down for `compareByDescending`. Only a fully
/// concrete instantiation is pushed: a partial one disproves more than it
/// types.
/// Whether `ty` (its head or any type argument, recursively) names one of
/// `names`, or carries a star projection — the shape an unbound type
/// variable is substituted to.
fn irTypeMentionsAny(ty: ir.TypeRef, names: []const []const u8) bool {
    const head = std.mem.trimEnd(u8, ty.name, "?");
    if (std.mem.eql(u8, head, "*")) return true;
    for (names) |n| if (std.mem.eql(u8, head, n)) return true;
    for (ty.args) |a| if (irTypeMentionsAny(a, names)) return true;
    return false;
}

fn solveInstantiatedArgExpected(
    b: *FuncBuilder,
    callee: *const Expr,
    name: []const u8,
    args: []const Expr,
) ?SibSolved {
    var site: ?*const Expr = null;
    var arg_idx: usize = 0;
    for (args, 0..) |*a, i| {
        if (a.* == .Call) {
            site = a;
            arg_idx = i;
            break;
        }
    }
    const s = site orelse return null;
    const sib_why = if (runtime.envOnce("KLIO_SIBEXP_WHY")) |w| std.mem.eql(u8, w, name) else false;
    var actual_owned: ?ir.TypeRef = switch (callee.*) {
        .Member => |m| (staticExprTypeRef(b, m.receiver) catch null),
        else => null,
    };
    defer if (actual_owned) |*t| t.deinit(b.allocator);
    if (callee.* == .Member and actual_owned == null) {
        if (sib_why) std.debug.print("[sibexp-why] {s} bail=recv_untyped\n", .{name});
        return null;
    }
    const actual_head: ?[]const u8 = blk: {
        if (actual_owned) |t| break :blk typeHead(std.mem.trimEnd(u8, t.name, "?"));
        break :blk null;
    };
    var scratch = std.heap.ArenaAllocator.init(b.allocator);
    defer scratch.deinit();
    for (b.module.funcsBySimpleName(name)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (!outerArityFits(f, args.len)) continue;
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        if (recv_off == 1) {
            const ah = actual_head orelse continue;
            var dr = std.mem.trimEnd(u8, f.params[0].ty.name, "?");
            if (std.mem.indexOfScalar(u8, dr, '<')) |lt| dr = dr[0..lt];
            const dh = typeHead(dr);
            if (!(std.mem.eql(u8, ah, dh) or dh.len <= 2 or
                ir.parseClassTypeParamIdentity(f.params[0].ty.name) != null or
                receiverHeadServes(b, ah, dh))) continue;
        } else if (callee.* == .Member) continue;
        const pi = recv_off + arg_idx;
        if (pi >= f.params.len) continue;
        const pt = f.params[pi].ty;
        // Only a GENERIC class type is worth pushing, and only when it is
        // not already concrete (a concrete param adds no information).
        if (pt.args.len == 0 or irTypeFullyConcrete(b, pt)) {
            if (sib_why) std.debug.print("[sibexp-why] {s}#{d} skip=param_shape pt={s} args={d}\n", .{ f.fqn, fid.int(), pt.name, pt.args.len });
            continue;
        }
        const expected_explicit: ?[]ir.TypeRef = expectedReturnTypeArgsFor(b, f) catch null;
        defer if (expected_explicit) |ea| {
            for (ea) |*t| t.deinit(b.allocator);
            b.allocator.free(ea);
        };
        // Project the actual receiver onto the DECLARED head first, so a
        // List<String?> binds an Iterable<T> receiver pattern (the same
        // head-consistency rule the splice window applies).
        var solve_recv: ?ir.TypeRef = if (actual_owned) |t| t else null;
        if (recv_off == 1 and actual_owned != null) {
            if (staticTypeClassId(b, f.params[0].ty)) |dcid| {
                if (b.module.projectTypeToClass(scratch.allocator(), actual_owned.?, dcid) catch null) |p| {
                    solve_recv = p;
                    if (sib_why) std.debug.print("[sibexp-why] {s}#{d} projected={s} args={d}\n", .{ f.fqn, fid.int(), p.name, p.args.len });
                } else if (sib_why) {
                    std.debug.print("[sibexp-why] {s}#{d} project_failed actual={s} dh={s}\n", .{ f.fqn, fid.int(), actual_owned.?.name, f.params[0].ty.name });
                }
            } else if (sib_why) {
                std.debug.print("[sibexp-why] {s}#{d} no_decl_cid dh={s}\n", .{ f.fqn, fid.int(), f.params[0].ty.name });
            }
        }
        // Receiver + expected-type evidence only: the value arguments are
        // exactly the still-untyped nested calls this push exists to type,
        // and their head-only shapes would refuse the bind.
        const solved = (b.module.solveCallBindings(
            scratch.allocator(),
            fid,
            f,
            solve_recv,
            null,
            &.{},
            expected_explicit orelse &.{},
            false,
        ) catch continue) orelse {
            if (sib_why) std.debug.print("[sibexp-why] {s}#{d} skip=no_solve\n", .{ f.fqn, fid.int() });
            continue;
        };
        if (solved.bindings.len == 0) {
            if (sib_why) std.debug.print("[sibexp-why] {s}#{d} skip=no_bindings\n", .{ f.fqn, fid.int() });
            continue;
        }
        const substituted = ir.Module.substituteBoundType(scratch.allocator(), pt, solved.bindings) catch continue;
        if (!irTypeFullyConcrete(b, substituted)) {
            if (sib_why) std.debug.print("[sibexp-why] {s}#{d} skip=not_concrete sub={s}\n", .{ f.fqn, fid.int(), substituted.name });
            continue;
        }
        // The outer's OWN type parameters are not type parameters of the
        // caller's scope, so the concreteness check reads a still-unbound
        // `T` as a concrete class named `T`. Pushing `KSerializer<T>` would
        // bind the nested reified call to the literal `T`; yield to the
        // sibling solvers, which take `T` from the argument that shares it.
        if (b.module.registry.func_type_params.get(fid)) |own_tps| {
            if (irTypeMentionsAny(substituted, own_tps.items)) {
                if (sib_why) std.debug.print("[sibexp-why] {s}#{d} skip=own_type_param sub={s}\n", .{ f.fqn, fid.int(), substituted.name });
                continue;
            }
        }
        const converted = astTypeRefFromIr(b, substituted, exprSpan(s)) orelse continue;
        if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) {
            std.debug.print("[sibexp-inst] outer={s} arg={d} pushed={s} args={d}\n", .{ f.fqn, arg_idx, converted.name.name, converted.type_args.len });
        }
        return .{ .site = s, .ty = converted };
    }
    return null;
}

/// The INSTANTIATED static type of a sibling generic call (`mapOf(1 to 2)`
/// is a `Map<Int, Int>`): the call's own type parameters solve from its
/// arguments' static shapes and substitute into its declared return type.
/// The head-only static type (`Map`) would hand a reified consumer beside
/// it (`serializer<T>()`) a raw classifier.
fn instantiatedSiblingCallTypeRef(b: *FuncBuilder, e: *const Expr) ?*const ast.TypeRef {
    const inst = instantiatedCallIrType(b, e, 0) orelse return null;
    const converted = astTypeRefFromIr(b, inst, exprSpan(e)) orelse return null;
    const out = b.allocator.create(ast.TypeRef) catch return null;
    out.* = converted;
    if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) std.debug.print("[sibexp-zero-inst] -> {s} args={d}\n", .{ converted.name.name, converted.type_args.len });
    return out;
}

/// The instantiated return type of a generic call, solved from its receiver
/// and argument shapes: a bare call (`mapOf(1 to 2)`) or a receiver call,
/// infix included (`1 to 2` is `Pair<Int, Int>`). Arguments that are
/// themselves calls instantiate the same way, two levels deep.
fn instantiatedCallIrType(b: *FuncBuilder, e: *const Expr, depth: usize) ?ir.TypeRef {
    if (depth > 2 or e.* != .Call) return null;
    const call = e.Call;
    if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) std.debug.print("[sibexp-zero-enter] depth={d} callee={s} nargs={d} type_args={d}\n", .{ depth, @tagName(std.meta.activeTag(call.callee.*)), call.args.len, call.type_args.len });
    if (call.type_args.len != 0) return null;
    const name: []const u8 = switch (call.callee.*) {
        .Path => |p| if (p.segments.len == 1) p.segments[0].name else return null,
        .Member => |m| m.name.name,
        else => return null,
    };
    const receiver: ?*const Expr = if (call.callee.* == .Member) call.callee.Member.receiver else null;
    var scratch = std.heap.ArenaAllocator.init(b.allocator);
    defer scratch.deinit();
    const shapes = buildStaticArgShapes(b, call.args, call.arg_names) catch return null;
    defer b.allocator.free(shapes);
    // An argument that is itself a call (`1 to 2`) carries no declared
    // type; its instantiated (else derived) static type is the evidence.
    for (call.args, shapes) |*a, *shape| {
        if (a.* == .Call) {
            // A nested generic call's instantiation (`Pair("a", "b")` is a
            // `Pair<String, String>`) beats the head-only declared type.
            if (instantiatedCallIrType(b, a, depth + 1)) |inst| {
                shape.ty = inst;
                shape.ty_authoritative = true;
                continue;
            }
        }
        if (shape.ty != null) continue;
        shape.ty = (staticExprTypeRef(b, a) catch null) orelse valueClassCtorTypeRef(b, a);
        shape.ty_authoritative = shape.ty != null;
    }
    const recv_ty: ?ir.TypeRef = if (receiver) |r|
        (instantiatedCallIrType(b, r, depth + 1) orelse (staticExprTypeRef(b, r) catch null))
    else
        null;
    if (receiver != null and recv_ty == null) return null;
    if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) {
        for (shapes, 0..) |sh, i| std.debug.print("[sibexp-zero-shape] call={s} arg{d} ty={s} recv={s}\n", .{ name, i, if (sh.ty) |t| t.name else "<null>", if (recv_ty) |t| t.name else "-" });
    }
    // A bare name that constructs a generic class (`Pair(42, Pair("a", "b"))`)
    // instantiates the class's own parameters from its primary parameters.
    if (receiver == null) ctor: {
        const file = call.callee.Path.segments[0].span.file;
        const scoped: ?ir.ClassId = if (scopeTypeRename(b, name, file.int())) |rn| b.module.classId(rn) else null;
        const cid = scoped orelse b.module.classIdIndexed(name, b.self_package, file) orelse
            b.module.classId(name) orelse break :ctor;
        if (cid.int() >= b.module.classes.items.len) break :ctor;
        const cls = &b.module.classes.items[cid.int()];
        if (cls.type_params.len == 0 or cls.primary_params.len != call.args.len) break :ctor;
        if (b.module.funcsBySimpleName(name).len != 0) break :ctor;
        var bindings: std.ArrayList(ir.Module.TypeBinding) = .empty;
        for (cls.primary_params, shapes) |pp, sh| {
            const at = sh.ty orelse continue;
            positionalBind(scratch.allocator(), pp.ty, at, cls.type_params, &bindings) catch break :ctor;
        }
        if (bindings.items.len != cls.type_params.len) break :ctor;
        const out_args = scratch.allocator().alloc(ir.TypeRef, cls.type_params.len) catch break :ctor;
        for (cls.type_params, 0..) |tp, i| {
            out_args[i] = for (bindings.items) |bd| {
                if (std.mem.eql(u8, bd.name, tp)) break bd.ty;
            } else break :ctor;
        }
        const inst = ir.TypeRef{ .name = cls.fqn, .nullable = false, .args = out_args };
        if (!irTypeFullyConcrete(b, inst)) break :ctor;
        return inst.clone(b.allocator) catch null;
    }
    for (b.module.funcsBySimpleName(name)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        const ext = f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this");
        if (ext != (receiver != null)) continue;
        const value_params = if (ext) f.params.len - 1 else f.params.len;
        const has_va = f.params.len != 0 and f.params[f.params.len - 1].is_vararg;
        if (!(value_params == call.args.len or (has_va and call.args.len + 1 >= value_params))) continue;
        if (f.return_ty.args.len == 0) continue;
        const tps = b.module.registry.func_type_params.get(fid) orelse continue;
        if (tps.items.len == 0) continue;
        // A vararg run of DIFFERENT classes (`listOf(ResponseInt(10), NoResponse,
        // ResponseString("foo"))`) binds the element parameter to their least
        // upper bound (the sealed `I`), as kotlinc infers it.
        if (has_va and value_params == 1 and tps.items.len == 1 and shapes.len > 1) {
            if (leastUpperBoundHead(b, shapes)) |lub| {
                for (shapes) |*sh| sh.ty = .{ .name = lub, .nullable = false, .args = &.{} };
            }
        }
        const solved = (b.module.solveCallBindings(scratch.allocator(), fid, f, recv_ty, null, shapes, &.{}, false) catch continue) orelse continue;
        if (solved.bindings.len == 0) continue;
        const substituted = ir.Module.substituteBoundType(scratch.allocator(), f.return_ty, solved.bindings) catch continue;
        if (!irTypeFullyConcrete(b, substituted)) continue;
        if (irTypeMentionsAny(substituted, tps.items)) continue;
        return substituted.clone(b.allocator) catch null;
    }
    return null;
}

/// Bind the class type parameters a declared parameter type mentions from
/// the argument's static type, positionally (`second: B` against
/// `Pair<String, String>` binds `B`; `items: List<T>` against `List<Int>`
/// binds `T`). A parameter already bound to a different type is a conflict.
fn positionalBind(a: Allocator, param: ir.TypeRef, arg: ir.TypeRef, tps: []const []const u8, out: *std.ArrayList(ir.Module.TypeBinding)) !void {
    const pn = std.mem.trimEnd(u8, param.name, "?");
    for (tps) |tp| {
        if (!std.mem.eql(u8, pn, tp)) continue;
        for (out.items) |bd| {
            if (std.mem.eql(u8, bd.name, tp)) {
                if (!std.mem.eql(u8, bd.ty.name, arg.name)) return error.Conflict;
                return;
            }
        }
        var owned = try arg.clone(a);
        owned.nullable = false;
        try out.append(a, .{ .name = tp, .ty = owned });
        return;
    }
    if (param.args.len != 0 and param.args.len == arg.args.len) {
        for (param.args, arg.args) |pa, aa| try positionalBind(a, pa, aa, tps, out);
    }
}

/// The nearest class every argument shape's static head is or extends,
/// walking the first head's supertype chain outward; null when the heads
/// agree (nothing to widen) or when no common class short of `Any` exists.
fn leastUpperBoundHead(b: *FuncBuilder, shapes: []const applicability.ArgShape) ?[]const u8 {
    var heads_buf: [16][]const u8 = undefined;
    if (shapes.len > heads_buf.len) return null;
    var all_same = true;
    for (shapes, 0..) |sh, i| {
        const t = sh.ty orelse return null;
        heads_buf[i] = typeHead(std.mem.trimEnd(u8, t.name, "?"));
        if (i != 0 and !std.mem.eql(u8, heads_buf[i], heads_buf[0])) all_same = false;
    }
    if (all_same) return null;
    const heads = heads_buf[0..shapes.len];
    var queue_buf: [64]ir.ClassId = undefined;
    var qlen: usize = 0;
    var qhead: usize = 0;
    const first = b.module.classIdByFqn(heads[0]) orelse b.module.classId(heads[0]) orelse return null;
    queue_buf[qlen] = first;
    qlen += 1;
    while (qhead < qlen) : (qhead += 1) {
        const cid = queue_buf[qhead];
        if (cid.int() >= b.module.classes.items.len) continue;
        const cls = &b.module.classes.items[cid.int()];
        var all = true;
        for (heads[1..]) |h| {
            if (!(std.mem.eql(u8, h, cls.name) or std.mem.eql(u8, h, cls.fqn) or b.module.classIsOrExtends(h, cls.fqn) or b.module.classIsOrExtends(h, cls.name))) {
                all = false;
                break;
            }
        }
        if (all) return cls.fqn;
        for (cls.supertypes) |sup| {
            if (qlen < queue_buf.len) {
                queue_buf[qlen] = sup;
                qlen += 1;
            }
        }
    }
    return null;
}

/// Whether an outer candidate can take `nargs` written arguments: its
/// receiver slot does not count (`JsonTestBase.assertJsonFormAndRestored`
/// called bare inside a subclass), and missing trailing parameters must
/// carry defaults (`json: Json = default`).
fn outerArityFits(f: *const ir.Func, nargs: usize) bool {
    const ro: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
    const vp = f.params.len - ro;
    if (vp == nargs) return true;
    if (vp < nargs) return false;
    if (vp - nargs <= 1) return true;
    var i: usize = ro + nargs;
    while (i < f.params.len) : (i += 1) {
        if (!f.params[i].has_default) return false;
    }
    return true;
}

/// The class a VALUE-class constructor call names (`Child1(Child1Value(1, "one"))`),
/// resolved in scope: `ctorInitTypeRef` declines value classes, yet an
/// element or argument typed by one still has that class as its static type
/// (a sealed-interface `List<Parent>` of inline children).
pub fn valueClassCtorTypeRef(b: *FuncBuilder, e: *const Expr) ?ir.TypeRef {
    if (e.* != .Call) return null;
    const call = e.Call;
    if (call.callee.* != .Path or call.callee.Path.segments.len != 1) return null;
    const seg = call.callee.Path.segments[0];
    if (seg.name.len == 0 or !std.ascii.isUpper(seg.name[0])) return null;
    const scoped: ?ir.ClassId = if (scopeTypeRename(b, seg.name, seg.span.file.int())) |rn| b.module.classId(rn) else null;
    const cid = scoped orelse b.module.classIdIndexed(seg.name, b.self_package, seg.span.file) orelse b.module.classId(seg.name) orelse return null;
    if (cid.int() >= b.module.classes.items.len) return null;
    const cls = &b.module.classes.items[cid.int()];
    if (!cls.is_value or cls.type_params.len != 0) return null;
    return .{ .name = b.allocator.dupe(u8, cls.fqn) catch return null, .nullable = false, .args = &.{} };
}

/// Kotlin types an integer literal by its EXPECTED type: `1` under a `Long`
/// parameter is a `Long`, and the expectation flows through a generic
/// factory (`mapOf("a" to 1)` under `Map<String, Long>` makes the `1` a
/// `Long` via `mapOf`'s `V` and `to`'s `B`). The literal node's kind is
/// rewritten in place before lowering; nothing else changes.
pub fn applyExpectedLiteralKinds(b: *FuncBuilder, e: *ast.Expr, expected: ir.TypeRef) void {
    const head = typeHead(std.mem.trimEnd(u8, expected.name, "?"));
    switch (e.*) {
        .IntLit => |*lit| {
            if (lit.kind == .Int and std.mem.eql(u8, head, "Long")) lit.kind = .Long;
        },
        .Unary => |*u| applyExpectedLiteralKinds(b, u.expr, expected),
        .Call => |*c| applyExpectedToGenericCall(b, c, expected),
        else => {},
    }
}

fn applyExpectedToGenericCall(b: *FuncBuilder, c: anytype, expected: ir.TypeRef) void {
    if (c.type_args.len != 0) return;
    if (expected.args.len == 0) return;
    const name: []const u8 = switch (c.callee.*) {
        .Path => |p| if (p.segments.len == 1) p.segments[0].name else return,
        .Member => |m| m.name.name,
        else => return,
    };
    // An infix call (`"a" to 1`) parses as `to(lhs, rhs)`: the first
    // argument is the extension receiver.
    const infix = c.is_infix and c.callee.* == .Path and c.args.len == 2;
    const receiver: ?*ast.Expr = if (c.callee.* == .Member) c.callee.Member.receiver else if (infix) &c.args[0] else null;
    const value_args: []ast.Expr = if (infix) c.args[1..] else c.args;
    var scratch = std.heap.ArenaAllocator.init(b.allocator);
    defer scratch.deinit();
    const a = scratch.allocator();
    // A generic class constructor (`Pair(1, 2)` under `Pair<Long, Long>`).
    if (receiver == null) ctor: {
        const cid = b.module.classIdIndexed(name, b.self_package, c.callee.Path.segments[0].span.file) orelse
            b.module.classId(name) orelse break :ctor;
        if (cid.int() >= b.module.classes.items.len) break :ctor;
        const cls = &b.module.classes.items[cid.int()];
        if (cls.type_params.len == 0 or cls.type_params.len != expected.args.len) break :ctor;
        if (b.module.funcsBySimpleName(name).len != 0) break :ctor;
        var bindings: std.ArrayList(ir.Module.TypeBinding) = .empty;
        for (cls.type_params, expected.args) |tp, ea| {
            bindings.append(a, .{ .name = tp, .ty = ea }) catch return;
        }
        for (cls.primary_params, 0..) |pp, i| {
            if (i >= c.args.len) break;
            const sub = ir.Module.substituteBoundType(a, pp.ty, bindings.items) catch continue;
            applyExpectedLiteralKinds(b, &c.args[i], sub);
        }
        return;
    }
    for (b.module.funcsBySimpleName(name)) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        const ext = f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this");
        if (ext != (receiver != null)) continue;
        const ro: usize = if (ext) 1 else 0;
        const value_params = f.params.len - ro;
        const has_va = f.params.len != 0 and f.params[f.params.len - 1].is_vararg;
        if (!(value_params == value_args.len or (has_va and value_args.len + 1 >= value_params))) continue;
        const tps = b.module.registry.func_type_params.get(fid) orelse continue;
        if (tps.items.len == 0) continue;
        var bindings: std.ArrayList(ir.Module.TypeBinding) = .empty;
        positionalBind(a, f.return_ty, expected, tps.items, &bindings) catch continue;
        if (bindings.items.len == 0) continue;
        if (receiver) |r| {
            const sub = ir.Module.substituteBoundType(a, f.params[0].ty, bindings.items) catch continue;
            applyExpectedLiteralKinds(b, r, sub);
        }
        for (value_args, 0..) |*arg, i| {
            const pi = ro + i;
            const pt: ir.TypeRef = if (pi < f.params.len)
                (if (f.params[pi].is_vararg) applicability.varargElementRef(&f.params[pi].ty) else f.params[pi].ty)
            else if (has_va)
                applicability.varargElementRef(&f.params[f.params.len - 1].ty)
            else
                continue;
            const sub = ir.Module.substituteBoundType(a, pt, bindings.items) catch continue;
            applyExpectedLiteralKinds(b, arg, sub);
        }
        return;
    }
}

/// Rewrite integer literals in a call's arguments by the callee's declared
/// parameter types (the expectation Kotlin applies), skipping parameters
/// that still mention the callee's own type parameters.
pub fn applyExpectedLiteralKindsToArgs(b: *FuncBuilder, f: *const ir.Func, args: []const Expr, ast_arg_names: []const ?[]const u8, recv_off: usize) void {
    for (ast_arg_names) |n| {
        if (n != null) return;
    }
    const own_tps: []const []const u8 = if (b.module.registry.func_type_params.get(f.id)) |l| l.items else &.{};
    for (args, 0..) |*arg, i| {
        const pi = recv_off + i;
        if (pi >= f.params.len) return;
        const p = f.params[pi];
        if (p.is_vararg) return;
        if (irTypeMentionsAny(p.ty, own_tps) or bareTypeParamHead(p.ty.name)) continue;
        applyExpectedLiteralKinds(b, @constCast(arg), p.ty);
    }
}

/// The constructor counterpart of `applyExpectedLiteralKindsToArgs`: the
/// class's primary parameter types are the expectation
/// (`WithValueKeyMap(mapOf(k to 1))` under `map: Map<K, Long>`).
fn applyExpectedLiteralKindsToCtorArgs(b: *FuncBuilder, class_id: ir.ClassId, args: []const Expr, ast_arg_names: []const ?[]const u8) void {
    for (ast_arg_names) |n| {
        if (n != null) return;
    }
    if (class_id.int() >= b.module.classes.items.len) return;
    const cls = &b.module.classes.items[class_id.int()];
    for (args, 0..) |*arg, i| {
        if (i >= cls.primary_params.len) return;
        const p = cls.primary_params[i];
        if (p.is_vararg) return;
        if (irTypeMentionsAny(p.ty, cls.type_params) or bareTypeParamHead(p.ty.name)) continue;
        applyExpectedLiteralKinds(b, @constCast(arg), p.ty);
    }
}

fn solveSiblingExpected(b: *FuncBuilder, callee: *const Expr, args: []const Expr) ?SibSolved {
    if (args.len == 0) return null;
    const outer_name: []const u8 = switch (callee.*) {
        .Path => |p| blk: {
            if (p.segments.len != 1) return null;
            break :blk p.segments[0].name;
        },
        .Member => |m| m.name.name,
        else => return null,
    };
    // A bare call naming a member of the lexically enclosing class (an
    // inherited `assertJsonFormAndRestored(serializer(), value, …)`) is not
    // in the simple-name index (only member extensions are): read the
    // enclosing chain's method slots, as the reified solver does.
    const own_member_outer = callee.* != .Member and b.hasEnclosingMember(outer_name);
    var chain_buf: [32]FuncId = undefined;
    const cand_fids: []const FuncId = if (own_member_outer)
        enclosingChainMethodsNamed(b, outer_name, callee.Path.segments[0].span.file, &chain_buf) catch &.{}
    else
        b.module.funcsBySimpleName(outer_name);
    var outer: ?*const ir.Func = null;
    for (cand_fids) |fid| {
        const f = b.module.funcById(fid) orelse continue;
        if (outerArityFits(f, args.len)) {
            outer = f;
            break;
        }
    }
    if (args.len >= 2) {
        if (solveComparatorSiblingByName(b, callee, outer_name, args)) |solved| return solved;
    }
    if (solveInstantiatedArgExpected(b, callee, outer_name, args)) |solved| return solved;
    if (solveReifiedArgExpected(b, callee, outer_name, args)) |solved| return solved;
    if (callee.* == .Member) return null;
    if (args.len < 2) return null;
    const f = outer orelse return null;
    const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
    for (args, 0..) |*arg, j| {
        if (arg.* != .Call) continue;
        const c = arg.Call;
        if (c.type_args.len != 0) continue;
        const nested_name: []const u8 = switch (c.callee.*) {
            .Path => |p| if (p.segments.len == 1) p.segments[0].name else continue,
            .Member => |m| m.name.name,
            else => continue,
        };
        // The outer overload judged here is the one whose parameter at this
        // slot is a bare type variable: `assertEquals` also declares the
        // `(Double, Double, tolerance)` forms, and the first arity match
        // may be one of those.
        var f_sel: *const ir.Func = f;
        var pj = recv_off + j;
        var tv_sel: []const u8 = "";
        {
            var found = false;
            for (cand_fids) |fid2| {
                const f2 = b.module.funcById(fid2) orelse continue;
                if (!outerArityFits(f2, args.len)) continue;
                const ro2: usize = if (f2.params.len != 0 and std.mem.eql(u8, f2.params[0].name, "this")) 1 else 0;
                const pj2 = ro2 + j;
                if (pj2 >= f2.params.len) continue;
                const slot2 = f2.params[pj2].ty;
                var tv2 = slot2.name;
                // A slot `C<T>` (`KSerializer<T>`) whose single argument is a
                // bare type variable shares that variable with the sibling's
                // plain `T` slot: the variable is the argument.
                if (!(tv2.len <= 2 and allUppercase(tv2)) and slot2.args.len == 1) {
                    const a0 = std.mem.trimEnd(u8, slot2.args[0].name, "?");
                    if (a0.len != 0 and a0.len <= 2 and allUppercase(a0)) tv2 = a0;
                }
                if (tv2.len > 2 or !allUppercase(tv2)) continue;
                f_sel = f2;
                pj = pj2;
                tv_sel = tv2;
                found = true;
                break;
            }
            if (!found) continue;
        }
        const tv = tv_sel;
        const ro_sel: usize = if (f_sel.params.len != 0 and std.mem.eql(u8, f_sel.params[0].name, "this")) 1 else 0;
        // A nested reified-inline call with arguments (`assertEquals(
        // Holder(1), decodeFromString(text))`) takes the sibling's static
        // type (a constructor call, a typed local, a literal) as its
        // expected type: the reified parameter binds from it where the
        // call's own arguments say nothing.
        if (c.args.len != 0) {
            var reified = false;
            if (inline_state.candidatesForName(nested_name)) |cands| {
                for (cands) |cf| {
                    for (cf.type_params) |*tp| {
                        if (tp.is_reified) reified = true;
                    }
                }
            }
            if (!reified) {
                if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) std.debug.print("[sibexp-why] nested `{s}` not reified-inline\n", .{nested_name});
                continue;
            }
            for (args, 0..) |*sib, k| {
                if (k == j) continue;
                const pk = ro_sel + k;
                if (pk >= f_sel.params.len) continue;
                if (!std.mem.eql(u8, f_sel.params[pk].ty.name, tv)) continue;
                const st = inline_call.ctorArgTypeRef(b.allocator, sib, b) orelse
                    inline_call.staticArgTypeRef(b.allocator, sib, b) orelse {
                    if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) std.debug.print("[sibexp-why] sibling #{d} of `{s}` has no static type (tag={s})\n", .{ k, outer_name, @tagName(std.meta.activeTag(sib.*)) });
                    continue;
                };
                return .{ .site = arg, .ty = st.* };
            }
            continue;
        }
        if (c.callee.* != .Path) continue;
        // The nested ZERO-argument reified overload — `serializer<T>()`
        // beside `serializer(type: KType)` and `KClass<T>.serializer()` —
        // is the receiver-less one with no value parameters and a single
        // type parameter; the simple-name index alone may answer another.
        var nested_pick: ?FuncId = null;
        for (b.module.funcsBySimpleName(nested_name)) |nfid| {
            const nf = b.module.funcById(nfid) orelse continue;
            if (nf.params.len != 0) continue;
            const ntps = b.module.registry.func_type_params.get(nfid) orelse continue;
            if (ntps.items.len != 1) continue;
            nested_pick = nfid;
            break;
        }
        const nested_fid = nested_pick orelse continue;
        const nested_f = b.module.funcById(nested_fid) orelse continue;
        // The lowered ir return type keeps only the head (`EnumEntries`);
        // the splice unifies against the AST declaration's full
        // `Head<T>`, so the head is all the expected type needs here.
        if (nested_f.return_ty.name.len == 0) continue;
        for (args, 0..) |*sib, k| {
            if (k == j) continue;
            const pk = ro_sel + k;
            if (pk >= f_sel.params.len) continue;
            // The sibling slot names `T` directly (`data: T`) or carries it as a
            // type argument (`pair: Pair<K, V>` for a `vSer: KSerializer<V>`),
            // in which case the sibling's instantiated type projects to it.
            const proj: ?usize = blk_proj: {
                if (std.mem.eql(u8, f_sel.params[pk].ty.name, tv)) break :blk_proj null;
                for (f_sel.params[pk].ty.args, 0..) |pa, pi| {
                    if (std.mem.eql(u8, std.mem.trimEnd(u8, pa.name, "?"), tv)) break :blk_proj pi;
                }
                continue;
            };
            const sp = c.callee.Path.segments[0].span;
            // The sibling's static type: an enum-entries expression, else a
            // constructor call / typed value (`check(serializer(), Holder(x), …)`
            // solves `serializer<T>()` from `Holder(x)` at the `data: T` slot).
            const sib_ty_full: ast.TypeRef = blk: {
                if (staticEnumElem(b, sib)) |enum_name| {
                    break :blk .{ .name = .{ .name = enum_name, .span = sp }, .nullable = false, .span = sp, .type_args = &.{}, .function = null, .definitely_non_null = false, .annotations = &.{}, .qualified_path = null };
                }
                const st = instantiatedSiblingCallTypeRef(b, sib) orelse
                    inline_call.ctorArgTypeRef(b.allocator, sib, b) orelse
                    inline_call.staticArgTypeRef(b.allocator, sib, b) orelse {
                    if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) std.debug.print("[sibexp-why] zero-arg nested `{s}`: sibling #{d} of `{s}` has no static type (tag={s})\n", .{ nested_name, k, outer_name, @tagName(sib.*) });
                    continue;
                };
                if (runtime.envOnce("KLIO_SIBEXP_TRACE") != null) std.debug.print("[sibexp-zero] outer={s} nested={s} sibling#{d} -> {s}\n", .{ outer_name, nested_name, k, st.name.name });
                break :blk st.*;
            };
            const sib_ty: ast.TypeRef = if (proj) |pi| blk_p: {
                if (pi >= sib_ty_full.type_args.len or sib_ty_full.type_args[pi].is_star) continue;
                break :blk_p sib_ty_full.type_args[pi].ty;
            } else sib_ty_full;
            // Build `Head<Sibling>` as the nested call's expected type; the
            // inline splice's return-type unification (the existing
            // reified oracle) solves T from it.
            var head = nested_f.return_ty.name;
            if (std.mem.lastIndexOfScalar(u8, head, '.')) |i| head = head[i + 1 ..];
            const ta = b.allocator.alloc(ast.TypeArg, 1) catch return null;
            ta[0] = .{ .variance = .Invariant, .is_star = false, .ty = sib_ty, .span = sp };
            return .{ .site = arg, .ty = .{ .name = .{ .name = head, .span = sp }, .nullable = false, .span = sp, .type_args = ta, .function = null, .definitely_non_null = false, .annotations = &.{}, .qualified_path = null } };
        }
    }
    return null;
}

/// A nested reified-inline call argument (`JsonTreeDecoder(json,
/// cast(currentObject(), descriptor), ...)`) takes the callee's DECLARED
/// parameter type as its expected type: Kotlin infers the reified `T`
/// from the expected type there, and the splice's return-type unification
/// binds it the same way. Only a concrete head-only parameter type that
/// every arity-matching overload agrees on is pushed.
/// The method slots named `name` on the lexically enclosing class and its
/// supertypes (declaration order, nearest class first), for a bare call
/// that reaches them through the implicit `this` receiver.
fn enclosingChainMethodsNamed(b: *FuncBuilder, name: []const u8, file: ir.FileId, buf: []FuncId) Allocator.Error![]const FuncId {
    const owner = b.ownerClass() orelse build.currentOwnerClass() orelse return buf[0..0];
    const root = b.module.classIdIndexed(owner, b.self_package, file) orelse b.module.classId(owner) orelse return buf[0..0];
    var out_len: usize = 0;
    // The class row's method slots fill after its bodies lower; while a
    // body is lowering, the registered member resolution (the same
    // authority the private-member call route uses) names the member.
    {
        var owner_type = try ownedClassSelfType(b.allocator, &b.module.classes.items[root.int()]);
        defer owner_type.deinit(b.allocator);
        const owned_bounds = try b.typeParamBoundsSlice();
        defer if (owned_bounds) |bounds| b.allocator.free(bounds);
        var probe_n: usize = 0;
        while (probe_n <= 8) : (probe_n += 1) {
            const shapes = try b.allocator.alloc(applicability.ArgShape, probe_n);
            defer b.allocator.free(shapes);
            for (shapes) |*sh| sh.* = .{};
            const res = b.module.resolveMemberCall(root, name, shapes, .{
                .caller_file = file,
                .lexical_owner = root,
                .actual_type_param_bounds = owned_bounds orelse &.{},
                .receiver_type = owner_type,
            });
            const fid = res.target orelse continue;
            var dup = false;
            for (buf[0..out_len]) |x| {
                if (x == fid) dup = true;
            }
            if (dup) continue;
            if (out_len == buf.len) return buf[0..out_len];
            buf[out_len] = fid;
            out_len += 1;
        }
    }
    var stack: [64]ir.ClassId = undefined;
    var seen: [64]ir.ClassId = undefined;
    var seen_len: usize = 0;
    var sp: usize = 0;
    stack[sp] = root;
    sp += 1;
    while (sp != 0) {
        sp -= 1;
        const cid = stack[sp];
        var dup = false;
        for (seen[0..seen_len]) |s| {
            if (s == cid) dup = true;
        }
        if (dup) continue;
        if (seen_len == seen.len) break;
        seen[seen_len] = cid;
        seen_len += 1;
        if (cid.int() >= b.module.classes.items.len) continue;
        const cls = &b.module.classes.items[cid.int()];
        for (cls.methods) |m| {
            const f = b.module.funcById(m) orelse continue;
            if (!std.mem.eql(u8, f.name, name)) continue;
            if (out_len == buf.len) return buf[0..out_len];
            buf[out_len] = m;
            out_len += 1;
        }
        var i = cls.supertypes.len;
        while (i > 0) : (i -= 1) {
            if (sp == stack.len) break;
            stack[sp] = cls.supertypes[i - 1];
            sp += 1;
        }
    }
    return buf[0..out_len];
}

/// `fid` is declared by the lexically enclosing class or one of its
/// supertypes, so a bare call inside that class can reach it through the
/// implicit `this` receiver.
fn funcInEnclosingChain(b: *FuncBuilder, fid: FuncId, file: ir.FileId) bool {
    const owner = b.ownerClass() orelse build.currentOwnerClass() orelse return false;
    const root = b.module.classIdIndexed(owner, b.self_package, file) orelse b.module.classId(owner) orelse return false;
    var stack: [64]ir.ClassId = undefined;
    var seen: [64]ir.ClassId = undefined;
    var seen_len: usize = 0;
    var sp: usize = 0;
    stack[sp] = root;
    sp += 1;
    while (sp != 0) {
        sp -= 1;
        const cid = stack[sp];
        var dup = false;
        for (seen[0..seen_len]) |s| {
            if (s == cid) dup = true;
        }
        if (dup) continue;
        if (seen_len == seen.len) return false;
        seen[seen_len] = cid;
        seen_len += 1;
        if (cid.int() >= b.module.classes.items.len) continue;
        const cls = &b.module.classes.items[cid.int()];
        for (cls.methods) |m| {
            if (m == fid) return true;
        }
        for (cls.supertypes) |st| {
            if (sp == stack.len) return false;
            stack[sp] = st;
            sp += 1;
        }
    }
    return false;
}

fn solveReifiedArgExpected(b: *FuncBuilder, callee: *const Expr, name: []const u8, args: []const Expr) ?SibSolved {
    for (args, 0..) |*a, i| {
        if (a.* != .Call) continue;
        const c = a.Call;
        if (c.type_args.len != 0) continue;
        var sp: ast.Span = undefined;
        const nested_name: []const u8 = switch (c.callee.*) {
            .Path => |p| blk: {
                if (p.segments.len != 1) continue;
                sp = p.segments[0].span;
                break :blk p.segments[0].name;
            },
            .Member => |m| blk: {
                sp = m.name.span;
                break :blk m.name.name;
            },
            else => continue,
        };
        const cands = inline_state.candidatesForName(nested_name) orelse continue;
        var reified = false;
        for (cands) |cf| {
            for (cf.type_params) |*tp| {
                if (tp.is_reified) reified = true;
            }
        }
        if (!reified) continue;
        var agreed: ?ir.TypeRef = null;
        var conflict = false;
        // A bare call naming a member of the lexically enclosing class
        // resolves to that member (an implicit `this` receiver wins over a
        // top-level namesake), so only the enclosing chain's members
        // supply the parameter type.
        const own_member = callee.* != .Member and b.hasEnclosingMember(name);
        const sib_tr = runtime.envOnce("KLIO_SIBEXP_TRACE") != null;
        if (sib_tr) std.debug.print("[sibexp-reified] outer={s} nested={s} own_member={} owner={?s} cur={?s}\n", .{ name, nested_name, own_member, b.ownerClass(), build.currentOwnerClass() });
        // Plain member functions are not in the simple-name index (only
        // member extensions are); an own-member call reads the enclosing
        // chain's method slots instead.
        var chain_buf: [32]FuncId = undefined;
        const cand_fids: []const FuncId = if (own_member)
            enclosingChainMethodsNamed(b, name, sp.file, &chain_buf) catch &.{}
        else
            b.module.funcsBySimpleName(name);
        for (cand_fids) |fid| {
            const f = b.module.funcById(fid) orelse continue;
            const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
            if (sib_tr) std.debug.print("[sibexp-reified]   cand {s} recv_off={d} nparams={d}\n", .{ f.fqn, recv_off, f.params.len });
            if (own_member) {
                if (recv_off != 1) continue;
            } else if (callee.* != .Member and recv_off == 1) continue;
            if (f.params.len - recv_off < args.len) continue;
            const pi = recv_off + i;
            if (pi >= f.params.len) continue;
            const pt = f.params[pi].ty;
            const head = std.mem.trimEnd(u8, pt.name, "?");
            if (head.len == 0 or pt.args.len != 0) {
                conflict = true;
                break;
            }
            if (std.mem.eql(u8, head, "Any") or std.mem.startsWith(u8, head, "Function") or !irTypeFullyConcrete(b, pt)) {
                conflict = true;
                break;
            }
            if (agreed) |g| {
                if (!std.mem.eql(u8, std.mem.trimEnd(u8, g.name, "?"), head)) {
                    conflict = true;
                    break;
                }
            } else agreed = pt;
        }
        if (conflict) continue;
        // A constructor call: the class's primary parameters.
        if (agreed == null and callee.* != .Member) {
            if (b.module.classId(name)) |cid| {
                const cls = &b.module.classes.items[cid.int()];
                if (i < cls.primary_params.len and cls.primary_params.len >= args.len) {
                    const pt = cls.primary_params[i].ty;
                    const head = std.mem.trimEnd(u8, pt.name, "?");
                    if (head.len != 0 and pt.args.len == 0 and !std.mem.eql(u8, head, "Any") and
                        !std.mem.startsWith(u8, head, "Function") and irTypeFullyConcrete(b, pt)) agreed = pt;
                }
            }
        }
        const pt = agreed orelse continue;
        const ty = astTypeRefFromIr(b, pt, sp) orelse continue;
        return .{ .site = a, .ty = ty };
    }
    return null;
}

/// The enum class statically named by an expression's element type:
/// `E.entries` and `E.values().toList()` both yield `E` when `E` resolves
/// to a registered enum class.
fn staticEnumElem(b: *FuncBuilder, e: *const Expr) ?[]const u8 {
    switch (e.*) {
        .Member => |m| {
            if (std.mem.eql(u8, m.name.name, "entries")) return enumClassOfPath(b, m.receiver);
            return null;
        },
        .Call => |c| {
            if (c.callee.* != .Member) return null;
            const outer_m = c.callee.Member;
            if (!std.mem.eql(u8, outer_m.name.name, "toList")) return null;
            if (outer_m.receiver.* != .Call) return null;
            const inner = outer_m.receiver.Call;
            if (inner.callee.* != .Member) return null;
            const vm = inner.callee.Member;
            if (!std.mem.eql(u8, vm.name.name, "values")) return null;
            return enumClassOfPath(b, vm.receiver);
        },
        else => return null,
    }
}

fn enumClassOfPath(b: *FuncBuilder, e: *const Expr) ?[]const u8 {
    var name: []const u8 = undefined;
    var qual_cid: ?ir.ClassId = null;
    var owner_hint: ?[]const u8 = null;
    switch (e.*) {
        .Path => |p| {
            name = p.segments[p.segments.len - 1].name;
            // A qualified nested reference (`EnumEntriesListTest.EmptyEnum`)
            // must bind THAT nested class — the simple name may collide
            // with an unrelated top-level or sibling-nested enum.
            if (p.segments.len >= 2) {
                const owner_name = p.segments[p.segments.len - 2].name;
                owner_hint = owner_name;
                if (b.module.classId(owner_name)) |oid| {
                    qual_cid = b.module.classIdNestedIn(oid, name);
                }
            }
        },
        .Member => |m| {
            name = m.name.name;
            if (m.receiver.* == .Path and m.receiver.Path.segments.len >= 1) {
                const owner_name = m.receiver.Path.segments[m.receiver.Path.segments.len - 1].name;
                owner_hint = owner_name;
                if (b.module.classId(owner_name)) |oid| {
                    qual_cid = b.module.classIdNestedIn(oid, name);
                }
            } else if (m.receiver.* == .Member) {
                owner_hint = m.receiver.Member.name.name;
            }
        },
        else => return null,
    }
    if (qual_cid) |cid| {
        if (cid.int() < b.module.classes.items.len) {
            // The registered (lifted) name is what the runtime type-arg
            // lookup resolves — already unique, so no owner qualification
            // on top (a mangled `EnumEntriesListTest$EmptyEnum` must not
            // stamp as `EnumEntriesListTest.EnumEntriesListTest$EmptyEnum`).
            name = b.module.classes.items[cid.int()].name;
            if (std.mem.indexOfScalar(u8, name, '$') != null) owner_hint = null;
        }
    }
    // A nested-enum reference whose class lifted under a mangled name
    // resolves through the rename: a QUALIFIED reference through its
    // owner's alias table (`EnumEntriesListTest.EmptyEnum` ->
    // `EnumEntriesListTest$EmptyEnum`), a bare one through the lexical
    // scope-rename ladder (`EmptyEnum` -> `EnumEntriesFactoryTest$EmptyEnum`).
    if (b.module.classId(name) == null) {
        if (owner_hint) |o| {
            if (b.module.registry.nested_object_aliases.get(o)) |m| {
                if (m.get(name)) |rn| {
                    name = rn;
                    owner_hint = null;
                }
            }
        } else if (scopeTypeRename(b, name, e.span().file.int())) |rn| {
            name = rn;
        }
    }
    if (b.module.classId(name) == null) return null;
    // Enum-ness at lowering: the recorded supertype chain carries
    // `Enum` for every enum class (the implicit supertype is recorded at
    // class lowering).
    const chain = b.module.registry.class_super_names.get(name) orelse return null;
    for (chain) |sup| {
        var sn = sup;
        if (std.mem.lastIndexOfScalar(u8, sn, '.')) |i| sn = sn[i + 1 ..];
        if (std.mem.indexOfScalar(u8, sn, '<')) |lt| sn = sn[0..lt];
        if (!std.mem.eql(u8, sn, "Enum")) continue;
        // A qualified reference stamps the owner-qualified name: the
        // simple name may collide with an unrelated same-named enum, and
        // the runtime resolves the dotted form through the lifted
        // nested-class key.
        if (owner_hint) |o| {
            return std.fmt.allocPrint(b.module.func_name_index.allocator, "{s}.{s}", .{ o, name }) catch name;
        }
        return name;
    }
    return null;
}

/// Static type args synthesized from the enclosing splice's reified
/// substitution: when the call site wrote none and every declared
/// type-parameter name of `func_id` is bound in the active reified name
/// map, the substituted names stamp the call (`enumEntriesIntrinsic()`
/// inside a spliced `enumEntries<E>()` body gets `<E>` — the runtime
/// typed dispatch is blind otherwise). Null when not fully bound.
fn spliceReifiedTypeArgs(b: *FuncBuilder, func_id: FuncId, argc: usize) Allocator.Error!?[]ConstId {
    if (b.reified_type_names.count() == 0) return null;
    const tps = b.module.registry.func_type_params.get(func_id) orelse return null;
    if (tps.items.len == 0) return null;
    const out = try b.allocator.alloc(ConstId, tps.items.len);
    for (tps.items, out) |tp, *slot| {
        const actual = b.resolveReifiedTypeName(tp) orelse blk: {
            // The callee names its type parameter differently from the
            // enclosing splice's. Kotlin solves it from the expected type;
            // with NO arguments to solve from and exactly one reified type
            // in scope, that binding is the only candidate there is —
            // `EnumSerializer(serialName, enumValues())` inside
            // `inline fun <reified E : Enum<E>> EnumSerializer(...)`.
            if (argc != 0 or tps.items.len != 1 or b.reified_type_names.count() != 1) {
                b.allocator.free(out);
                return null;
            }
            var it = b.reified_type_names.valueIterator();
            break :blk (it.next() orelse {
                b.allocator.free(out);
                return null;
            }).*;
        };
        slot.* = try b.module.internConst(b.allocator, .{ .String = actual });
    }
    return out;
}

/// The `CallMember` emit form: a resolved extension bound on the implicit
/// `this` with member precedence — a member of the receiver outranks the
/// same-named top-level extension. Routes through `emitExtBareCall`, which
/// selects the static-receiver `CallMember` (or, for a vararg trailing-lambda
/// gap / cast, the prepended static `Call`). With no `this` in scope the bind
/// degrades to the static `Call` of `emitCall`.
fn emitCallMember(b: *FuncBuilder, expr: *const Expr, func_id: FuncId, was_cast: bool) Allocator.Error!Reg {
    if (try resolveThisForBareCall(b)) |this_reg0| {
        const this_reg = blk: {
            const c0 = expr.Call.callee;
            if (c0.* == .Path and c0.Path.segments.len == 1) {
                break :blk subjectCorrectedBareThis(b, c0.Path.segments[0].name, this_reg0);
            }
            break :blk this_reg0;
        };
        return emitExtBareCall(b, expr, func_id, this_reg, was_cast);
    }
    return emitCall(b, expr, func_id, was_cast);
}

/// The receiver a BARE call to member `name` actually dispatches on when
/// spliced-subject binds shadow `this` (`with(rec) { writable { … } }`
/// where `writable` is the enclosing class's member): the innermost
/// subject whose class declares the member, else the receiver beneath
/// the whole subject run. Anything unprovable keeps the supplied reg.
/// Whether an extension property (or extension function) named `name` is
/// declared for `head` or one of its registered supertypes: the getter is
/// a registered function with a leading `this` whose declared receiver
/// the head is or extends.
fn extensionPropOnHead(b: *FuncBuilder, head_in: []const u8, name: []const u8) bool {
    const head = typeHead(std.mem.trimEnd(u8, head_in, "?"));
    if (head.len == 0) return false;
    const simple = applicability.simpleName(head);
    if (extPropExistsOn(b, simple, name)) return true;
    for (applicability.builtinSupersOf(simple)) |sup| {
        if (extPropExistsOn(b, sup, name)) return true;
    }
    if (b.module.registry.class_super_names.get(simple)) |chain| {
        for (chain) |sup| {
            if (extPropExistsOn(b, applicability.simpleName(sup), name)) return true;
        }
    }
    return false;
}

/// An extension property `val <head>.<name>` is known either by its
/// declared-type record or by its lowered getter `__ext_get_<head>_<name>`.
fn extPropExistsOn(b: *const FuncBuilder, head: []const u8, name: []const u8) bool {
    if (b.module.registry.ext_prop_type_heads.get(.{ .a = head, .b = name }) != null) return true;
    var buf: [160]u8 = undefined;
    const gname = std.fmt.bufPrint(&buf, "__ext_get_{s}_{s}", .{ head, name }) catch return false;
    return b.module.funcsBySimpleName(gname).len != 0;
}

fn subjectCorrectedBareThis(b: *FuncBuilder, name: []const u8, this_reg: Reg) Reg {
    const sct = if (runtime.envOnce("KLIO_SCT_TRACE")) |w| std.mem.eql(u8, w, name) else false;
    const sbs = b.subject_binds.items;
    if (sbs.len == 0) return this_reg;
    // Only correct when the ambient `this` IS the innermost subject —
    // otherwise scope already resolved beneath the subjects.
    if (sbs[sbs.len - 1].reg != this_reg) {
        if (sct) std.debug.print("[sct] {s}: this r{d} != innermost subject r{d}\n", .{ name, this_reg.int(), sbs[sbs.len - 1].reg.int() });
        return this_reg;
    }
    var i = sbs.len;
    while (i > 0) {
        i -= 1;
        const h = sbs[i].head orelse {
            if (sct) std.debug.print("[sct] {s}: subject {d} head unknown\n", .{ name, i });
            return this_reg;
        };
        const cid = b.module.classIdIndexed(h, b.self_package, ir.FileId.from(0)) orelse
            b.module.classId(h) orelse
            {
                if (sct) std.debug.print("[sct] {s}: head {s} unresolvable\n", .{ name, h });
                return this_reg;
            };
        if (b.module.classHierarchyDeclaresMember(cid, name)) {
            if (sct) std.debug.print("[sct] {s}: subject {d} ({s}) declares it\n", .{ name, i, h });
            return sbs[i].reg;
        }
        // An EXTENSION property declared on the subject's type (or a
        // supertype) binds the bare name to that subject the same way a
        // member does: `isSpecified` inside a spliced `Dp.takeOrElse`,
        // `indices` inside `List.fastForEach`.
        if (extensionPropOnHead(b, h, name)) {
            if (sct) std.debug.print("[sct] {s}: subject {d} ({s}) has an extension property\n", .{ name, i, h });
            return sbs[i].reg;
        }
    }
    if (sct) {
        std.debug.print("[sct] {s}: -> beneath-subjects this {?} (subjects={d}):", .{ name, sbs[0].prior_this, sbs.len });
        for (sbs) |sb| std.debug.print(" [reg=r{d} head={s} prior={?}]", .{ sb.reg.int(), sb.head orelse "-", sb.prior_this });
        std.debug.print("\n", .{});
    }
    return sbs[0].prior_this orelse this_reg;
}

/// The `CallMemberOrGlobal` emit form: the bare name dispatches member-first on
/// the runtime implicit receiver, falling back to the resolved global. A
/// non-extension target carries its resolved `func` as the global arm; a
/// resolved extension a member could shadow defers to the pure member-first
/// walk (`lowerUnresolvedBareCall`), which carries no static arm.
fn emitMemberOrGlobal(b: *FuncBuilder, expr: *const Expr, func_id: FuncId, was_cast: bool) Allocator.Error!Reg {
    const call = expr.Call;
    const callee = call.callee;
    var selected_args = try selectedCallArgsForBuilder(b, func_id, call.args, call.arg_names, exprSpan(callee), call.has_trailing_lambda);
    defer selected_args.deinit(b.allocator);
    const args = selected_args.args;
    const ast_arg_names = selected_args.names;
    const ast_type_args = call.type_args;
    const name0 = callee.Path.segments[0].name;
    const prev_trailing = b.setCallTrailingLambda(
        call.has_trailing_lambda and !hasComposerArgPair(ast_arg_names),
    );
    defer _ = b.setCallTrailingLambda(prev_trailing);

    // An APPLICABLE own member shadows the same-named top-level function in
    // Kotlin's scope order (`private fun Json(arrays: Boolean, build:
    // PolymorphicModuleBuilder<Any>.() -> Unit)` beside the library's
    // `Json { … }` builder): the implicit-this path binds the MEMBER's
    // lambda shapes and receivers, where the deferred form below would read
    // them off the global candidate.
    if (callee.Path.segments.len == 1 and b.resolve("this") != null and
        b.hasOwnMember(name0) and b.ownFunctionApplicable(name0, call.args.len) and
        !ownMemberRejectsLambdas(b, name0, call.args))
    {
        if (try lowerImplicitThisCall(b, callee, call.args, call.arg_names, ast_type_args)) |r| return r;
    }

    if (!isNonExt(b, func_id)) {
        if (try lowerUnresolvedBareCall(b, callee, args, ast_arg_names, ast_type_args, func_id)) |r| return r;
        return emitCall(b, expr, func_id, was_cast);
    }
    // The whole reason for the member-first form is that a member of the
    // implicit receiver could shadow the resolved global. With NO receiver
    // in scope there is no member to find, and the runtime walk resolves the
    // name only to arrive at the declaration already in hand.
    // A TRAILING LAMBDA keeps the member-or-global path: it does more than
    // dispatch there — the committed candidate shapes the lambda's arity,
    // its receiver and the composable broad masks, and the static emit does
    // not carry that.
    if (!call.has_trailing_lambda and
        b.resolve("this") == null and b.ownerClass() == null and
        b.recvTy() == null and b.spliceRecvTy() == null)
    {
        orEmitAudit(b, "bare_call_no_receiver_to_shadow", "Call", name0);
        return emitCall(b, expr, func_id, was_cast);
    }

    const this_idx = try b.recordCapture("this");
    const broad_masks: ?[]u32 = blk: {
        const f = b.module.funcById(func_id) orelse break :blk null;
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        break :blk try argLambdaBroadMasks(b, f, args, ast_arg_names, recv_off);
    };
    defer if (broad_masks) |m| b.allocator.free(m);
    b.pending_arg_broad_masks = broad_masks;
    // The dispatch is deferred, but the trailing lambda's static shape comes
    // from the committed global candidate: read the per-arg lambda arities
    // from it so a `T.() -> R` receiver lambda drops its synthetic `it` here
    // exactly as on the static-call path (`it` then resolves to the
    // enclosing lambda's, matching kotlinc).
    const arg_arity: ?[]const i16 = blk: {
        if (b.module.funcById(func_id)) |f| {
            const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
            // The receiver-type head of a receiver-lambda argument comes from
            // the same committed candidate: a deferred `validate { … }` must
            // lower its block with `MockViewValidator` as the body's receiver,
            // or bare ext-overload selection inside (`Composition(a, b, c)`
            // beside a local `MockViewValidator.Composition`) has no receiver
            // evidence and picks the wrong sibling.
            try recordLambdaArgReceivers(b, f, args, ast_arg_names, ast_type_args, recv_off);
            break :blk try argFnArities(b, f, args, ast_arg_names, recv_off);
        }
        break :blk null;
    };
    // The deferred form types lambda params from the committed global
    // candidate exactly as the static Call emitter does — a bare
    // `all { it.isWhitespace() }` whose inline callee is still a header
    // stub defers, and without this the closure's `it` lowers untyped.
    const lambda_param_types: ?[]?[]ir.TypeRef = blk: {
        const f = b.module.funcById(func_id) orelse break :blk null;
        const recv_off: usize = if (f.params.len != 0 and
            std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        if (runtime.envOnce("KLIO_ALPT") != null) std.debug.print("[alpt-site] stubDeferred fn={s}\n", .{f.name});
        break :blk try argLambdaParamTypes(
            b,
            f,
            args,
            ast_arg_names,
            ast_type_args,
            recv_off,
        );
    };
    defer if (lambda_param_types) |types|
        deinitArgLambdaParamTypes(b.allocator, types);
    b.pending_arg_lambda_param_types = lambda_param_types;
    if (runtime.envOnce("KLIO_ADM_TRACE") != null) {
        const f0 = b.module.funcById(func_id);
        std.debug.print("[cmg-lpt] {s} fid={d} lpt={} p_last={s} p_last_args={d}\n", .{
            name0,
            func_id.int(),
            lambda_param_types != null,
            if (f0) |f| (if (f.params.len != 0) f.params[f.params.len - 1].ty.name else "-") else "?",
            if (f0) |f| (if (f.params.len != 0) f.params[f.params.len - 1].ty.args.len else 0) else 0,
        });
    }
    const run = try lowerArgRunWithArity(b, args, arg_arity);
    const arg_names = try trailingLambdaArgNames(b, func_id, args, ast_arg_names);
    const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
    const dst = b.allocReg();
    orEmitAudit(b, "bare_call_member_shadowable", "CallMemberOrGlobal", name0);
    const cmg_static_recv: ?ConstId = try cmgStaticRecv(b);
    var type_args = try helpers.internTypeArgsScoped(b, ast_type_args);
    // The deferred form keeps the reified splice substitution too: a
    // spliced `enumEntriesIntrinsic()` lowered in a receiver context
    // (a lambda body) is otherwise blind at the runtime intrinsic.
    if (type_args.len == 0) {
        if (try spliceReifiedTypeArgs(b, func_id, args.len)) |stamped| type_args = stamped;
    }
    try b.push(.{ .CallMemberOrGlobal = .{
        .dst = dst,
        .this_idx = this_idx,
        .name = nm,
        .trailing_lambda = b.callTrailingLambda(),
        .args = run[0],
        .n_args = run[1],
        .arg_names = arg_names,
        .func = func_id,
        .func_final = was_cast,
        .candidates = try cmgCandidates(b, name0, callee.Path.segments[0].span.file, run[1]),
        .static_recv = cmg_static_recv,
        .type_args = type_args,
    } });
    return dst;
}

/// The receiver-type tag for a deferred member-or-global bare call: the
/// enclosing extension's declared receiver head, when this body has one.
/// The class id a bare classifier read binds, innermost first: a NESTED
/// class/object of the enclosing class chain (registered under its lifted
/// `Outer$Name` key, invisible to the flat index) beats the package-scope
/// pick — `object E : Base(Key)` inside a class declaring `object Key`
/// reads ITS OWN Key, not `CoroutineContext.Key` from a wildcard import.
fn scopedClassIdForRead(b: *FuncBuilder, name0: []const u8, file: anytype) ?ir.ClassId {
    if (nestedClassIdAtLexicalSite(b, name0)) |cid| return cid;
    if (b.module.classIdExactImport(name0, file)) |cid| return cid;
    // A receiver context whose owner chain is unknown here (a super-arg /
    // default-value thunk, a lambda) may still see a NESTED classifier the
    // flat index cannot rank; committing the package-scope pick would
    // override the runtime's scope walk with the wrong declaration
    // (CoroutineContext.Key shadowing a nested `object Key`). Decline —
    // the name-keyed runtime path owns the scoped resolution.
    if (inReceiverContext(b)) return null;
    return b.module.classIdIndexed(name0, b.self_package, file);
}

/// The class visible at a lexical source site without the receiver-context
/// decline used by an immediately-lowered read. Anonymous-object bodies use
/// this before moving into their registry-free side modules.
fn classIdAtLexicalSite(b: *FuncBuilder, name0: []const u8, file: anytype) ?ir.ClassId {
    if (nestedClassIdAtLexicalSite(b, name0)) |cid| return cid;
    if (b.module.classIdExactImport(name0, file)) |cid| return cid;
    return b.module.classIdIndexed(name0, b.self_package, file);
}

fn nestedClassIdAtLexicalSite(b: *FuncBuilder, name0: []const u8) ?ir.ClassId {
    if (b.ownerClass()) |oc| {
        // Resolve the OWNER to an id once (its lifted simple name is in the
        // class index), then answer through the nesting tree — the one
        // scoped classifier lookup, no string-mangled probing.
        if (b.module.classId(oc)) |owner_id| {
            if (b.module.classIdNestedIn(owner_id, name0)) |cid| return cid;
            // The nesting tree (`class_children`) is built at VM setup, AFTER
            // this lowering runs for a baked pack's bodies, so it can be empty
            // here. Derive the nesting directly from FQNs (which `classIdByFqn`
            // resolves without the tree): a bare `Nested` inside `a.b.Outer`
            // resolves to `a.b.Outer.Nested`, walking up the enclosing-class
            // FQNs so a reference to an outer-scope nested class still binds.
            if (b.module.classFqnById(owner_id)) |ofqn| {
                var pfqn: []const u8 = ofqn;
                var hops: usize = 0;
                while (hops < 16) : (hops += 1) {
                    const cand = std.fmt.allocPrint(b.allocator, "{s}.{s}", .{ pfqn, name0 }) catch break;
                    defer b.allocator.free(cand);
                    if (b.module.classIdByFqn(cand)) |cid| return cid;
                    const dot = std.mem.lastIndexOfScalar(u8, pfqn, '.') orelse break;
                    pfqn = pfqn[0..dot];
                    if (b.module.classIdByFqn(pfqn) == null) break; // left the class nest
                }
            }
        }
    }
    return null;
}

/// Whether the currently bound `this` is the tower's INNERMOST pushed
/// subject (already on the runtime chain, so emissions defer to the
/// chain) rather than a nested inline-EXT splice receiver (not on the
/// chain — must stay pinned; `resumeWith` inside a spliced
/// `Continuation.resume` dispatches on the CAST receiver, which no walk
/// can find).
fn boundThisIsTowerTop(b: *FuncBuilder) bool {
    if (b.encl_tower_depth == 0) return false;
    const top = b.encl_tower_top orelse return false;
    const cur = b.resolve("this") orelse return false;
    return cur.int() == top.int();
}

fn cmgStaticRecv(b: *FuncBuilder) Allocator.Error!?ConstId {
    // Under an active subject tower the runtime chain ranks the
    // receivers; a static head would pin the strict-ext arm to the
    // innermost SUBJECT and raise where the walk must fall outward
    // (`eachInline` inside `with(sb) { ... }` is the enclosing class's
    // member-inline, StringBuilder declares nothing by that name).
    if (boundThisIsTowerTop(b)) return null;
    const rt = bareStaticRecvHead(b) orelse return null;
    return try b.module.internConst(b.allocator, .{ .String = rt });
}

/// The static-receiver head a BARE call's dispatch hint should carry.
/// Inside an active inline splice this is the spliced fn's own receiver
/// (null for a receiver-less inline fn) — Kotlin inline bodies are
/// hygienic, so a bare call written in the stdlib body must never resolve
/// against the inline SITE's class. Outside a splice: the enclosing
/// function's receiver, as before.
pub fn bareStaticRecvHead(b: *const FuncBuilder) ?[]const u8 {
    if (b.thisNarrow()) |t| return t;
    if (b.spliceHintActive()) return b.spliceHintRecv();
    // An `is`-narrow of `this` is the innermost receiver truth: inside
    // `if (this is Collection)`, a bare call resolves against Collection
    // exactly as kotlinc smart-casts — `Iterable.contains`'s own
    // `contains(element)` binds the Collection MEMBER, never itself. The
    // narrow lives in the local-decl map under "this" (`narrowLocal`);
    // consulted AFTER the splice hint so a spliced stdlib body never
    // resolves against the inline site's caller context. Default ON with
    // the genuine-narrow gate below — the earlier 4.3x DeepRecursive
    // slowdown and the ArrayDeque mis-bind were both the UNGATED consult
    // trusting an enclosing method's `this` decl through receiver-less
    // lambdas. `KLIO_THIS_NARROW=0` disables for single-binary A/B.
    if (!std.mem.eql(u8, runtime.envOnce("KLIO_THIS_NARROW") orelse "1", "0")) {
        // Only a genuine NARROW counts: the entry must differ from this
        // frame's own declared receiver. A lambda with no receiver of its
        // own sees the ENCLOSING method's `this` decl through the shared
        // local map, and trusting that bound a bare `clear()` inside
        // `apply { }` to the enclosing test method (the ArrayDeque armed
        // recursion) instead of the runtime receiver walk.
        if (b.recvTy()) |declared| {
            if (b.localDeclType("this")) |narrowed| {
                if (!std.mem.eql(u8, typeHead(narrowed), typeHead(declared)))
                    return typeHead(narrowed);
            }
        }
    }
    if (b.recvTy()) |own| return own;
    // A lambda DECLARED receiverless (shape known) chains to the enclosing
    // receiver, exactly Kotlin's implicit-receiver resolution; an untyped
    // receiver-lambda must not (the ArrayDeque hazard above).
    if (b.own_recv_known_none) return b.enclosingRecvTy();
    return null;
}

/// Package/import-scoped declarations carried by a deferred bare call. The
/// optional distinction is intentional: null means the remaining host-only or
/// incomplete-header boundary has no rankable declaration metadata; a non-null
/// (possibly empty) slice is authoritative and prevents the runtime from
/// widening back to the program-wide simple-name index.
fn cmgCandidates(b: *FuncBuilder, name: []const u8, file: ir.FileId, user_arg_count: usize) Allocator.Error!?[]const FuncId {
    return b.module.boundedCallCandidates(b.allocator, name, b.self_package, file, user_arg_count);
}

/// The `CallValue` emit form for a bare name with no committed target: load the
/// global by name and invoke it. Used for a host-intrinsic alias whose user
/// overloads do not apply (no class declares the name as a member).
fn emitValueCall(
    b: *FuncBuilder,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
    ast_type_args: []const ast.TypeRef,
    name0: []const u8,
) Allocator.Error!Reg {
    orEmitAudit(b, "alias_global_no_overload", "LoadGlobal", name0);
    const callee_r = b.allocReg();
    const nm = try b.module.internConst(b.allocator, .{ .String = name0 });
    try b.push(.{ .LoadGlobal = .{ .dst = callee_r, .name = nm } });
    const run = try lowerArgRun(b, args);
    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
    const type_args = try helpers.internTypeArgsScoped(b, ast_type_args);
    const dst = b.allocReg();
    try b.push(.{ .CallValue = .{
        .dst = dst,
        .callee = callee_r,
        .args = run[0],
        .n_args = run[1],
        .arg_names = arg_names,
        .type_args = type_args,
    } });
    return dst;
}

fn emitObjectValueCall(
    b: *FuncBuilder,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
    ast_type_args: []const ast.TypeRef,
    name0: []const u8,
    class_id: ir.ClassId,
) Allocator.Error!Reg {
    orEmitAudit(b, "object_operator_call", "LoadGlobal", name0);
    const callee_r = b.allocReg();
    const identity = b.module.classFqnById(class_id) orelse name0;
    const nm = try b.module.internConst(b.allocator, .{ .String = identity });
    try b.push(.{ .LoadGlobal = .{ .dst = callee_r, .name = nm, .class = class_id } });
    const run = try lowerArgRun(b, args);
    const arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
    const type_args = try helpers.internTypeArgsScoped(b, ast_type_args);
    const dst = b.allocReg();
    try b.push(.{ .CallValue = .{
        .dst = dst,
        .callee = callee_r,
        .args = run[0],
        .n_args = run[1],
        .arg_names = arg_names,
        .type_args = type_args,
    } });
    return dst;
}

/// Arg names for a bare `Call`, synthesizing a name for a trailing lambda
/// that follows a vararg parameter so it binds the target's last
/// (function-typed) parameter rather than being packed into the vararg.
/// Returns the plain interned names otherwise.
fn trailingLambdaArgNames(
    b: *FuncBuilder,
    func_id: FuncId,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
) Allocator.Error![]?ConstId {
    if (b.module.funcById(func_id)) |f| {
        if (threadedTrailingLambdaParam(f, args, ast_arg_names)) |hit| {
            const tagged = try internArgNames(b.allocator, b.module, ast_arg_names);
            tagged[hit.arg_index] = try b.module.internConst(b.allocator, .{ .String = hit.param_name });
            return tagged;
        }
    }
    if (args.len != 0 and allNull(ast_arg_names) and lastArgIsLambda(args)) {
        if (b.module.funcById(func_id)) |f| {
            const last_is_fixed_fn = f.params.len != 0 and
                !f.params[f.params.len - 1].is_vararg and
                std.mem.startsWith(u8, f.params[f.params.len - 1].ty.name, "Function");
            var has_earlier_vararg = false;
            if (f.params.len > 1) {
                for (f.params[0 .. f.params.len - 1]) |p| {
                    if (p.is_vararg) has_earlier_vararg = true;
                }
            }
            // Only the vararg-before-trailing-lambda shape needs the
            // synthesized name; a plain positional trailing lambda already
            // lands on the last parameter. A final vararg of function values
            // absorbs every lambda positionally and must remain unnamed.
            if (last_is_fixed_fn and has_earlier_vararg) {
                const tagged = try b.allocator.alloc(?ConstId, args.len);
                for (tagged) |*t| t.* = null;
                const cid = try b.module.internConst(b.allocator, .{ .String = f.params[f.params.len - 1].name });
                tagged[tagged.len - 1] = cid;
                return tagged;
            }
        }
    }
    return internArgNames(b.allocator, b.module, ast_arg_names);
}

const ThreadedTrailingLambda = struct {
    arg_index: usize,
    param_name: []const u8,
};

/// The source trailing lambda immediately before the Compose synthetic pair
/// binds the selected declaration's last user parameter. The AST pass appends
/// the pair and clears `has_trailing_lambda`, so carrying this exact parameter
/// name into IR preserves Kotlin's across-default binding.
fn threadedTrailingLambdaParam(
    f: *const Func,
    args: []const Expr,
    names: []const ?[]const u8,
) ?ThreadedTrailingLambda {
    if (!hasThreadedComposerParams(f) or args.len < 3 or names.len != args.len) return null;
    const composer_name = names[names.len - 2] orelse return null;
    const changed_name = names[names.len - 1] orelse return null;
    if (!std.mem.eql(u8, composer_name, "$composer") or
        !std.mem.eql(u8, changed_name, "$changed"))
    {
        return null;
    }
    const arg_index = args.len - 3;
    if (args[arg_index] != .Lambda or names[arg_index] != null) return null;
    const user_param_end = f.params.len - 2;
    if (user_param_end == 0) return null;
    const param = &f.params[user_param_end - 1];
    if (param.is_vararg or !std.mem.startsWith(u8, param.ty.name, "Function")) return null;
    return .{ .arg_index = arg_index, .param_name = param.name };
}

/// The extension-fn bare-call path: prepend `this`, with trailing-lambda
/// arg-name synthesis and the member-precedence routing.
fn emitExtBareCall(b: *FuncBuilder, expr: *const Expr, func_id_in: FuncId, this_reg: Reg, was_cast_in: bool) Allocator.Error!Reg {
    const call = expr.Call;
    const callee = call.callee;
    // The THIRD emission channel for a return-variant family: a bare
    // extension call on the implicit receiver reached here with the
    // heuristic sibling committed, and the member-precedence CallMember
    // below would hand the runtime walk a first-declared re-pick (the
    // Double sumOf, 3.0 where kotlinc prints 3). The trailing lambda's
    // derived return discriminates here exactly as on the other two paths.
    var func_id = func_id_in;
    var was_cast = was_cast_in;
    if (!was_cast and lastArgIsLambda(call.args) and allNull(call.arg_names) and
        callee.* == .Path and callee.Path.segments.len == 1)
    {
        const pcands = try b.module.bareCallCandidates(b.allocator, callee.Path.segments[0].name, callee.Path.segments[0].span.file);
        defer b.allocator.free(pcands);
        if (try overloadPickByLambdaReturn(b, pcands, call.args, call.args.len)) |picked| {
            func_id = picked;
            was_cast = true;
        }
    }
    var selected_args = try selectedCallArgsForBuilder(b, func_id, call.args, call.arg_names, exprSpan(callee), call.has_trailing_lambda);
    defer selected_args.deinit(b.allocator);
    const args = selected_args.args;
    const ast_arg_names = selected_args.names;
    const ast_type_args = call.type_args;
    const prev_trailing = b.setCallTrailingLambda(
        call.has_trailing_lambda and !hasComposerArgPair(ast_arg_names),
    );
    defer _ = b.setCallTrailingLambda(prev_trailing);

    // Synthesise a Path("this") arg expr then lower the run.
    const sp = exprSpan(callee);
    const all = try b.allocator.alloc(Expr, args.len + 1);
    defer b.allocator.free(all);
    const synth_segs = try b.allocator.alloc(ast.Ident, 1);
    defer b.allocator.free(synth_segs);
    synth_segs[0] = .{ .name = "this", .span = sp };
    all[0] = .{ .Path = .{ .segments = synth_segs, .span = sp } };
    for (args, 0..) |a, i| all[i + 1] = a;
    const arg_arity: ?[]const i16 = blk: {
        if (allNull(ast_arg_names)) {
            // The trailing lambda lands on whichever same-name overload
            // declares a function-typed last parameter of the call's user
            // arity — the bare-call heuristic may have resolved a sibling
            // (`List.get(index)`) that cannot host the lambda, leaving the
            // receiver lambda's `it` unsuppressed. Prefer the overload that
            // actually hosts the trailing lambda for the arity readout.
            const arity_fid: ?FuncId = if (lastArgIsLambda(args))
                (overloadHostingTrailingLambda(b, callee.Path.segments[0].name, args.len) orelse func_id)
            else
                func_id;
            if (arity_fid) |fid| {
                if (b.module.funcById(fid)) |f| {
                    // `all` leads with the synthesized `this`, aligned with
                    // the function's own leading `this` parameter, so no
                    // offset.
                    break :blk try argFnArities(b, f, all, &.{}, 0);
                }
            }
        }
        break :blk null;
    };

    // Target params for trailing-lambda arg-name synthesis.
    var target_params: [][]const u8 = &.{};
    if (b.module.funcById(func_id)) |f| {
        target_params = try b.allocator.alloc([]const u8, f.params.len);
        for (f.params, target_params) |p, *tp| tp.* = p.name;
    }
    defer if (target_params.len != 0) b.allocator.free(target_params);
    const user_arg_count = all.len - 1;
    const trailing_lambda_call = lastArgIsLambda(args);
    const synth_names_needed = target_params.len != 0 and user_arg_count >= 1 and
        (1 + user_arg_count) < target_params.len and allNull(ast_arg_names) and trailing_lambda_call;

    var arg_names: []?ConstId = undefined;
    if (synth_names_needed) {
        const tagged = try b.allocator.alloc(?ConstId, all.len);
        for (tagged) |*t| t.* = null;
        const p_name = target_params[target_params.len - 1];
        const cid = try b.module.internConst(b.allocator, .{ .String = p_name });
        tagged[tagged.len - 1] = cid;
        arg_names = tagged;
    } else {
        arg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
    }
    const type_args = try helpers.internTypeArgsScoped(b, ast_type_args);

    if (!synth_names_needed and !was_cast) {
        // Member-of-receiver precedence: route through call_member on `this`.
        // Carry the trailing lambda's expected arity (from the overload that
        // hosts it) so a `T.() -> R` receiver handler drops its synthetic
        // `it` and resolves bare members through the receiver bound at
        // invocation, even on this member-dispatch arm.
        const uarg_arity: ?[]const i16 = ablk: {
            if (allNull(ast_arg_names) and lastArgIsLambda(args)) {
                if (overloadHostingTrailingLambda(b, callee.Path.segments[0].name, args.len)) |fid| {
                    if (b.module.funcById(fid)) |f| {
                        break :ablk try argFnArities(b, f, args, &.{}, 1);
                    }
                }
            }
            break :ablk null;
        };
        const uargs = try lowerArgRunWithArity(b, args, uarg_arity);
        const uarg_names = try internArgNames(b.allocator, b.module, ast_arg_names);
        const nmc = try b.module.internConst(b.allocator, .{ .String = callee.Path.segments[0].name });
        const dst = b.allocReg();
        // A captured-`this` receiver context routes through `emitMemberOrGlobal`
        // (the `CallMemberOrGlobal` emit form), never here — `resolveCall` never
        // reaches the static-receiver `CallMember` bind for such a call.
        //
        // Inside an extension body the implicit `this` has the
        // extension's declared receiver type; record it so dispatch
        // resolves extensions against the STATIC type, as kotlinc does.
        const static_recv: ?ConstId = if (bareStaticRecvHead(b)) |rt|
            try b.module.internConst(b.allocator, .{ .String = rt })
        else
            null;
        try b.push(.{ .CallMember = .{
            .dst = dst,
            .receiver = this_reg,
            .name = nmc,
            .trailing_lambda = b.callTrailingLambda(),
            .args = uargs[0],
            .n_args = uargs[1],
            .arg_names = uarg_names,
            .static_recv = static_recv,
        } });
        return dst;
    }
    // The member-precedence branch above lowers its own argument run and
    // returns; only the static-call path reaches here, so the `this`-prepended
    // run is lowered now — lowering it earlier would emit (and execute) every
    // argument's side effects a second time on the member path.
    const run = try lowerArgRunWithArity(b, all, arg_arity);
    const dst = b.allocReg();
    try b.push(.{ .Call = .{
        .dst = dst,
        .func = func_id,
        .trailing_lambda = b.callTrailingLambda(),
        .args = run[0],
        .n_args = run[1],
        .arg_names = arg_names,
        .type_args = type_args,
        .exact = was_cast,
    } });
    return dst;
}

pub fn allNull(names: []const ?[]const u8) bool {
    for (names) |n| {
        if (n != null) return false;
    }
    return true;
}

/// Resolve an own private method against the complete predeclared overload
/// set. Private members cannot be overridden, so a unique applicability winner
/// is a direct target even when its declaration appears after the caller.
fn resolvePrivateMemberCall(
    b: *FuncBuilder,
    name: []const u8,
    file: ir.FileId,
    args: []const Expr,
    arg_names: []const ?[]const u8,
) Allocator.Error!Module.MemberResolution {
    const owner_name = b.ownerClass() orelse return .{};
    const owner_id = b.module.classIdIndexed(owner_name, b.self_package, file) orelse
        b.module.classId(owner_name) orelse return .{};
    if (owner_id.int() >= b.module.classes.items.len) return .{};
    const shapes = try buildStaticArgShapes(b, args, arg_names);
    defer b.allocator.free(shapes);
    const owned_type_param_bounds = try b.typeParamBoundsSlice();
    defer if (owned_type_param_bounds) |bounds| b.allocator.free(bounds);
    var owner_type = try ownedClassSelfType(
        b.allocator,
        &b.module.classes.items[owner_id.int()],
    );
    defer owner_type.deinit(b.allocator);
    return b.module.resolveMemberCall(owner_id, name, shapes, .{
        .caller_file = file,
        .lexical_owner = owner_id,
        .private_only = true,
        .actual_type_param_bounds = owned_type_param_bounds orelse &.{},
        .receiver_type = owner_type,
    });
}

/// Inside a method body: unqualified `name(...)` is a method call on `this`.
fn lowerImplicitThisCall(
    b: *FuncBuilder,
    callee: *const Expr,
    args: []const Expr,
    ast_arg_names: []const ?[]const u8,
    ast_type_args: []const ast.TypeRef,
) Allocator.Error!?Reg {
    const segments = callee.Path.segments;
    if (segments.len != 1) return null;
    const name0 = segments[0].name;
    if (b.resolve(name0) != null or b.knowsOuter(name0) or !b.hasOwnMember(name0)) return null;
    // A call written with EXPLICIT type arguments cannot be answered by an own
    // member that declares no type parameters, so that member does not shadow
    // the same-named top-level function. androidx.collection's own test
    // declares `@Test fun emptyObjectIntMap()` and calls the imported
    // `fun <K> emptyObjectIntMap()` inside it; routing through implicit-this
    // dispatch bound the enclosing method and recursed until the eval depth
    // blew. Declining here returns the call to the normal resolution path,
    // which is what the same call in initializer position always took.
    if (ast_type_args.len != 0 and !b.ownMemberAcceptsTypeArgs(name0)) return null;
    // E4: when the eager channel committed this call to a PLAIN top-level
    // function, the same-named own member does not shadow it — kotlin
    // scoping resolved the other way, and the record gate now checks the
    // full declared+inherited member surface, so a surviving record means
    // no member (own or inherited) shadows. The redirect stands where the
    // channel is silent or names a method.
    if (b.module.eagerCallTarget(segments[0].span)) |efid| {
        if (b.module.funcById(efid)) |ef| {
            if (ef.kind == .plain) return null;
        }
    }
    // A same-named member that cannot bind this call's arity (a 0-arg
    // `requireNotNull()` for a 1-arg `requireNotNull(x)`) does not shadow the
    // top-level function: defer to the global-resolution path instead of
    // emitting a `this.<member>` call that can't dispatch.
    if (!b.ownMemberApplicable(name0, args.len)) return null;
    if (ownMemberRejectsLambdas(b, name0, args)) return null;
    const this_reg0 = b.resolve("this") orelse return null;
    const this_reg = subjectCorrectedBareThis(b, name0, this_reg0);

    const member_lambda_shape: ?ir.ModuleRegistry.MemberTrailingLambdaShape = if (allNull(ast_arg_names) and lastArgIsLambda(args))
        predeclaredMemberTrailingLambdaShape(b, name0, args.len)
    else
        null;
    const member_lambda_fid: ?FuncId = if (allNull(ast_arg_names) and lastArgIsLambda(args))
        memberHostingTrailingLambda(b, name0, args.len)
    else
        null;

    // Broad-collection mask: a trailing lambda bound to this member's
    // function-typed parameter whose declared type is `Iterable`/`Collection`
    // marks the lambda's matching params broad, so `it + x` over a runtime
    // `Set` yields a `List` (the declared, not runtime, receiver type).
    const itc_broad: ?[]u32 = blk: {
        const fid = member_lambda_fid orelse break :blk null;
        const f = b.module.funcById(fid) orelse break :blk null;
        const recv_off: usize = if (f.params.len != 0 and std.mem.eql(u8, f.params[0].name, "this")) 1 else 0;
        break :blk try argLambdaBroadMasks(b, f, args, ast_arg_names, recv_off);
    };
    defer if (itc_broad) |m| b.allocator.free(m);

    // Private own-class methods bind to their stable declaration identity.
    const private_resolution = try resolvePrivateMemberCall(
        b,
        name0,
        segments[0].span.file,
        args,
        ast_arg_names,
    );
    if (private_resolution.dispatch == .direct and ast_type_args.len == 0) {
        const fid = private_resolution.target.?;
        // Reserve the receiver slot first, then lower the arguments into a
        // contiguous run immediately after it. `lowerArgRun` reserves every
        // argument slot before lowering any argument, so an argument's own
        // scratch registers can never clobber an already-lowered slot (a bug
        // the previous hand-rolled loop had, dropping local-variable args).
        const args_start = b.allocReg();
        b.pending_arg_broad_masks = itc_broad;
        if (b.module.funcById(fid)) |pf| {
            const recv_off: usize = if (pf.params.len != 0 and std.mem.eql(u8, pf.params[0].name, "this")) 1 else 0;
            try recordLambdaArgReceivers(b, pf, args, ast_arg_names, ast_type_args, recv_off);
        }
        const priv_arity: ?[]const i16 = if (b.module.funcById(fid)) |pf|
            (try argFnArities(b, pf, args, ast_arg_names, if (pf.params.len != 0 and std.mem.eql(u8, pf.params[0].name, "this")) 1 else 0))
        else
            null;
        defer if (priv_arity) |arities| b.allocator.free(arities);
        const priv_fn_generic: ?[]bool = if (b.module.funcById(fid)) |pf|
            (try argFnGenericFlags(b, pf, args, ast_arg_names, if (pf.params.len != 0 and std.mem.eql(u8, pf.params[0].name, "this")) 1 else 0))
        else
            null;
        defer if (priv_fn_generic) |m| b.allocator.free(m);
        b.pending_arg_fn_generic = priv_fn_generic;
        const priv_lambda_param_types: ?[]?[]ir.TypeRef = if (b.module.funcById(fid)) |pf|
            blk_priv: {
                if (runtime.envOnce("KLIO_ALPT") != null) std.debug.print("[alpt-site] privBare fn={s}\n", .{pf.name});
                break :blk_priv try argLambdaParamTypes(
                b,
                pf,
                args,
                ast_arg_names,
                ast_type_args,
                if (pf.params.len != 0 and
                    std.mem.eql(u8, pf.params[0].name, "this")) 1 else 0,
            );
            }
        else
            null;
        defer if (priv_lambda_param_types) |types|
            deinitArgLambdaParamTypes(b.allocator, types);
        b.pending_arg_lambda_param_types = priv_lambda_param_types;
        const run = try lowerArgRunWithArity(b, args, priv_arity);
        try b.push(.{ .Move = .{ .dst = args_start, .src = this_reg } });
        var user_arg_names = try b.allocator.alloc(?[]const u8, ast_arg_names.len + 1);
        defer b.allocator.free(user_arg_names);
        user_arg_names[0] = null;
        for (ast_arg_names, 0..) |n, i| user_arg_names[i + 1] = n;
        const arg_names = try internArgNames(b.allocator, b.module, user_arg_names);
        const dst = b.allocReg();
        try b.push(.{ .Call = .{
            .dst = dst,
            .func = fid,
            .trailing_lambda = b.callTrailingLambda(),
            .args = args_start,
            .n_args = run[1] + 1,
            .arg_names = arg_names,
            .type_args = &.{},
            .exact = true,
        } });
        return dst;
    }
    // A member the receiver type PROVABLY declares wins over any same-named
    // top-level in Kotlin's scope order, so a resolved target commits
    // statically here — direct for final/private, a virtual slot otherwise.
    // Only an UNPROVEN member keeps the OrGlobal fallback below (a
    // non-callable property, an arity miss the runtime resolves to the
    // global). `KLIO_ITC_MEMBER=0` disables for single-binary A/B.
    const itc_gate = runtime.envOnce("KLIO_ITC_MEMBER") orelse "1";
    const itc_on = blk: {
        if (std.mem.eql(u8, itc_gate, "0")) break :blk false;
        if (std.mem.eql(u8, itc_gate, "1")) break :blk true;
        var it = std.mem.splitScalar(u8, itc_gate, ',');
        while (it.next()) |n| {
            if (std.mem.eql(u8, n, name0)) break :blk true;
        }
        break :blk false;
    };
    if (itc_on) attempt: {
        const head_name = bareStaticRecvHead(b) orelse b.ownerClass() orelse break :attempt;
        // A same-named FUNCTION-TYPED property on the receiver is an
        // invoke-convention peer the member resolver cannot rank (it ranks
        // functions only): `class C(val f: (A) -> T) { fun f(vararg s: A) =
        // f(s) }` binds the PROPERTY's invoke in Kotlin when the member's
        // vararg refuses the array. Leave such calls to the runtime walk.
        if (b.module.registry.class_prop_type_heads.get(.{ .a = typeHead(head_name), .b = name0 })) |ph| {
            if (std.mem.startsWith(u8, ph, "Function")) break :attempt;
        }
        {
            const guard_cid = if (std.mem.indexOfScalar(u8, head_name, '.') != null)
                b.module.classIdByFqn(head_name)
            else
                b.module.classIdIndexed(typeHead(head_name), b.self_package, segments[0].span.file) orelse
                    b.module.classId(typeHead(head_name));
            if (guard_cid) |gc| {
                if (gc.int() < b.module.classes.items.len) {
                    for (b.module.classes.items[gc.int()].primary_params) |pp| {
                        if (std.mem.eql(u8, pp.name, name0) and
                            std.mem.startsWith(u8, typeHead(pp.ty.name), "Function"))
                        {
                            break :attempt;
                        }
                    }
                }
            }
        }
        var owned_head_ty: ?TypeRef = null;
        defer if (owned_head_ty) |*t| t.deinit(b.allocator);
        const recv_ty = blk: {
            if (b.recvTypeRef()) |declared| {
                if (std.mem.eql(u8, typeHead(declared.name), head_name)) break :blk declared;
            }
            const head_fqn = blk2: {
                if (std.mem.indexOfScalar(u8, head_name, '.') != null) break :blk2 head_name;
                const cid = b.module.classIdIndexed(head_name, b.self_package, segments[0].span.file) orelse
                    b.module.classId(head_name) orelse break :attempt;
                if (cid.int() >= b.module.classes.items.len) break :attempt;
                break :blk2 b.module.classes.items[cid.int()].fqn;
            };
            owned_head_ty = TypeRef{
                .name = try b.allocator.dupe(u8, head_fqn),
                .nullable = false,
                .args = &.{},
            };
            break :blk owned_head_ty.?;
        };
        var this_path = [_]ast.Ident{.{ .name = "this", .span = segments[0].span }};
        const this_expr = Expr{ .Path = .{ .segments = &this_path, .span = segments[0].span } };
        switch (try lowerResolvedMemberCall(
            b,
            &this_expr,
            .{ .name = name0, .span = segments[0].span },
            args,
            ast_arg_names,
            ast_type_args,
            recv_ty,
            .{ .reg = this_reg, .non_null = true },
        )) {
            .lowered => |reg| {
                orEmitAudit(b, "implicit_this_call_member_bound", "Call/implicit-member", name0);
                return reg;
