                b,
                f,
                args,
                ast_arg_names,
                ast_type_args,
                recv_off,
            );
        }
    }
    if (member_lambda_shape) |shape| {
        if (member_arity == null) {
            const out = try b.allocator.alloc(i16, args.len);
            for (out) |*arity| arity.* = -1;
