}

test "lowers int min value as int" {
    var m = Module.default(testing.allocator);
    defer m.deinit(testing.allocator);
    var b = try FuncBuilder.init(testing.allocator, &m);
    defer b.deinit();
    // -2147483648 parses as Neg(IntLit(2147483648)).
